,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Choose if you want the plugin to show the colors defined in the diagram using the bpmn color standard.<br />',
'If you additionally enable the following option <strong>Add Highlighting</strong>, this will take precedence over the bpmn colors.<br />',
'As this can lead to unexpected results, we strongly recommend to only use one option at once.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(36793491762013642)
,p_plugin_id=>wwv_flow_imp.id(52324636500430595707)
