,p_is_required=>false
,p_column_data_types=>'CLOB'
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Choose the column holding the data of iterating elements in the diagram.<br/>',
'If existing, according elements will show an option to open the list of instances and select the highlighted instance.<br/>',
'Leave empty if you don''t want to show iteration data in the viewer.<br/>',
'<br/>',
'See view <em>FLOW_INSTANCE_DETAILS_VW</em> on how to build up the JSON structure of the iteration data.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(5552287501374875)
,p_plugin_id=>wwv_flow_imp.id(52324636500430595707)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>18
,p_display_sequence=>180
,p_static_id=>'attribute_18'
,p_prompt=>'User Task URLs'
,p_attribute_type=>'REGION SOURCE COLUMN'
,p_is_required=>false
,p_column_data_types=>'CLOB'
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Choose the column holding the URLs generated for APEX Page or APEX Simple Form User Tasks.<br/>',
'If existing, users that are eligible to work on a task can directly click on the icon next to the User Tasks to open the referenced page.<br/>',
'Leave empty if you don''t want to link User Tasks directly in the viewer.<br/>',
'<br/>',
'The URLs for a single process instance need to be wrapped in a JSON object. See view <em>FLOW_INSTANCE_DETAILS_VW</em> on how to build up the required JSON structure of this attribute.'))
);
wwv_flow_imp_shared.create_plugin_std_attribute(
 p_id=>wwv_flow_imp.id(48859196113982242635)
,p_plugin_id=>wwv_flow_imp.id(52324636500430595707)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p></p>',
'<pre>',
'function( config ) {',
'    config.currentStyle = {',
'        ''fill'': ''green'',',
'        ''border'': ''black'',',
'        ''label'': ''black''',
'    }',
'    config.completedStyle = {',
'        ''fill'': ''grey'',',
'        ''border'': ''black'',',
'        ''label'': ''black''',
'    }',
'    config.errorStyle = {',
'        ''fill'': ''red'',',
'        ''border'': ''black'',',
'        ''label'': ''white''',
'    };',
'    config.allowDownload = false;',
'    return config;',
'}',
'</pre>',
'<p></p>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Enter a JavaScript function that takes a configuration object for the Flow Viewer, modifies the object, and returns it.<br/>',
'This allows advanced customization of the Flow Viewer including:<br/>',
'<ul>',
'<li>Change highlighting options for elements depending on the process status</li>',
'<li>Disable button for downloading model as svg in the viewer toolbar</li>',
'</ul>'))
);
