', lgrt_token                VARCHAR2(400 char) ',
', lgrt_timestamp        		TIMESTAMP WITH TIME ZONE NOT NULL',
', lgrt_http_method          VARCHAR2(20 char)',
', lgrt_endpoint           	VARCHAR2(4000 char)',
', lgrt_payload              CLOB ',
