'create or replace package flow_parameters',
'  authid definer',
'as ',
'/* ',
'-- Flows for APEX - flow_parameters.pks',
'-- ',
'-- (c) Copyright Flowquest Limited and / or its affiliates. 2026.',
'--',
'-- Created    07-Feb-2026  Richard Allen (Flowquest Limited)',
'--',
'-- Package for processing BPMN task input/output parameters',
'*/',
'',
'  -- Process input parameters by combining user input with process variables, static values, etc.',
'  function process_input_parameters',
'  (',
'    pi_parameter_definitions  in clob -- JSON array from objt_attributes.inputParameters',
'  , pi_user_input_data        in clob -- JSON object with user-provided values  ',
'  , pi_process_id             in flow_processes.prcs_id%type',
'  , pi_subflow_id             in flow_subflows.sbfl_id%type default null',
'  , pi_scope                  in flow_subflows.sbfl_scope%type default 0',
'  , pi_allow_user_input       in boolean default true',
'  ) return clob; -- Complete JSON object with all parameter values',
'',
'  -- Get JSON schema for user input fields only (for APEX UI generation)',
'  function get_user_input_schema',
'  (',
'    pi_parameter_definitions  in clob -- JSON array from objt_attributes.inputParameters',
'  ) return clob; -- JSON Schema for user input fields only',
'',
'  -- Validate parameter values against their definitions',
'  function validate_parameters',
'  (',
'    pi_parameter_definitions  in clob -- JSON array from objt_attributes',
'  , pi_parameter_values       in clob -- JSON object with parameter values',
'  ) return boolean;',
'',
'  -- Get parameter definition from object attributes',
'  function get_input_parameter_definitions',
'  (',
'    pi_objt_id                in flow_objects.objt_id%type',
'  ) return clob; -- JSON array of input parameter definitions',
'',
'  function get_output_parameter_definitions  ',
'  (',
'    pi_objt_id                in flow_objects.objt_id%type',
'  ) return clob; -- JSON array of output parameter definitions',
'',
'  -- Convert parameter definitions to JSON Schema',
'  function parameters_to_json_schema',
'  (',
'    pi_parameters      in clob',
'  , pi_user_data_only  in boolean default false',
'  ) return clob;',
'',
'  function parameters_to_json_schema',
'  (',
'    pi_parameters        in clob',
'  , pi_user_data_only_yn in varchar2 default ''N''',
'  ) return clob;',
'',
'end flow_parameters;',
'/',
'create or replace package flow_parser_util',
'  authid definer',
'as',
'-- Holds all types needed during parsing and utility methods',
'-- The types are fitted to use natural keys',
'-- and are converted using the utility methods',
'',
'-- Types',
' type t_objt_rec is',
'    record',
'    (',
'      objt_name           flow_types_pkg.t_vc200',
'    , objt_tag_name       flow_types_pkg.t_bpmn_id',
'    , objt_parent_bpmn_id flow_types_pkg.t_bpmn_id',
'    , objt_sub_tag_name   flow_types_pkg.t_bpmn_id',
'    , objt_attached_to    flow_types_pkg.t_bpmn_id',
'    , objt_interrupting   flow_types_pkg.t_boolean_num',
'    , objt_attributes     sys.json_object_t',
'    );',
'  type t_objt_tab is table of t_objt_rec index by flow_types_pkg.t_bpmn_id;',
'',
'  type t_expr_rec is',
'    record',
'    (',
'      expr_set         flow_object_expressions.expr_set%type',
'    , expr_order       flow_object_expressions.expr_order%type',
'    , expr_var_name    flow_object_expressions.expr_var_name%type',
'    , expr_var_type    flow_object_expressions.expr_var_type%type',
'    , expr_type        flow_object_expressions.expr_type%type',
'    , expr_expression  flow_object_expressions.expr_expression%type',
'    , expr_source_type flow_object_expressions.expr_source_type%type',
'    , expr_source      flow_object_expressions.expr_source%type',
'    );',
'  type t_expr_tab is table of t_expr_rec index by pls_integer;',
'  type t_objt_expr_tab is table of t_expr_tab index by flow_types_pkg.t_bpmn_id;',
'',
'  type t_conn_rec is',
'    record',
'    (',
'      conn_name        flow_types_pkg.t_vc200',
'    , conn_src_bpmn_id flow_types_pkg.t_bpmn_id',
'    , conn_tgt_bpmn_id flow_types_pkg.t_bpmn_id',
'    , conn_tag_name    flow_types_pkg.t_bpmn_id',
'    , conn_origin      flow_types_pkg.t_bpmn_id',
'    , conn_sequence    number',
'    , conn_attributes  sys.json_object_t',
'    );',
'  type t_conn_tab is table of t_conn_rec index by flow_types_pkg.t_bpmn_id;',
'',
'  type t_bpmn_ref_tab is table of flow_types_pkg.t_bpmn_id index by flow_types_pkg.t_bpmn_id;',
'  type t_bpmn_id_tab is table of number index by flow_types_pkg.t_bpmn_id;',
'',
'  type t_id_lookup_tab is table of number index by flow_types_pkg.t_bpmn_id;',
'',
'  -- Methods',
'  procedure split_property_name',
'  (',
'    pi_property_name  in        varchar2',
'  , po_namespace     out nocopy varchar2',
'  , po_key           out nocopy varchar2',
'  );',
'',
'  function get_property_key( pi_property_name in varchar2 )',
'    return varchar2;',
'',
'  procedure guarantee_apex_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  );',
'',
'  procedure guarantee_bpmn_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  );',
'',
'  procedure guarantee_named_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  , pi_key         in varchar2',
'  );',
'',
'  function get_lines_array',
'  (',
'    pi_str in clob',
'  ) return sys.json_array_t;',
'',
'  procedure property_to_json',
'  (',
'    pi_property_name  in varchar2',
'  , pi_value          in clob',
'  , po_namespace     out nocopy varchar2',
'  , po_key           out nocopy varchar2',
'  , po_json_element  out nocopy sys.json_element_t',
'  );',
'',
'  procedure log',
'  (',
'    pi_plog_dgrm_id    in flow_parser_log.plog_dgrm_id%type',
'  , pi_plog_bpmn_id    in flow_parser_log.plog_bpmn_id%type',
'  , pi_plog_parse_step in flow_parser_log.plog_parse_step%type',
'  , pi_plog_payload    in flow_parser_log.plog_payload%type',
'  );',
'',
'  procedure log',
'  (',
'    pi_plog_dgrm_id    in flow_parser_log.plog_dgrm_id%type',
'  , pi_plog_bpmn_id    in flow_parser_log.plog_bpmn_id%type',
'  , pi_plog_parse_step in flow_parser_log.plog_parse_step%type',
'  , pi_plog_payload    in sys.xmltype',
'  );',
'',
'  function is_log_enabled',
'    return boolean',
'  ;',
'',
'  procedure clear_log',
'  (',
'    pi_plog_dgrm_id in flow_parser_log.plog_dgrm_id%type',
'  );',
'  ',
'end flow_parser_util;',
'/',
'',
