'/* ',
'-- Flows for APEX - flow_instance_details_vw.sql',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'--',
'-- Created    Nov-2020 Moritz Klein,  MT AG',
'-- Edited  16-Mar-2022 Richard Allen, Oracle Corporation',
'-- Edited  21-Jun-2024 Dennis Amthor, Hyand Solutions GmbH',
'--',
'-- NOTE THAT THIS VIEW HAS AN ENTERPRISE EDITION VERSION WHICH INCLUDES COMPLEX',
'-- PROCESSING TO GENERATE THE ITERATION_DATA COLUMN.',
'-- ANY CHANGES TO THIS VIEW SHOULD ALSO UPDATE THE ENTERPRISE EDITION VERSION IN ADDITION.',
'*/',
'create or replace view flow_instance_details_vw',
'as',
'with completed_objects as (',
'        select distinct sflg.sflg_prcs_id as prcs_id',
'                      , sflg.sflg_dgrm_id  as dgrm_id',
'                      , sflg.sflg_diagram_level as diagram_level',
'                      , sflg.sflg_objt_id as objt_id',
'          from flow_subflow_log sflg',
'         where sflg.sflg_objt_id not in (   ',
'                                          select sbfl.sbfl_current',
'                                            from flow_subflows sbfl',
'                                           where sbfl.sbfl_prcs_id = sflg.sflg_prcs_id',
'                                             and sbfl.sbfl_diagram_level = sflg.sflg_diagram_level',
'                                             and sbfl.sbfl_current is not null',
'                                             and sbfl.sbfl_status != ''delete on resume''',
'                                        )',
'), all_completed as ( ',
'    select prcs_id, dgrm_id, diagram_level,',
'           listagg( objt_id, '':'') within group (order by objt_id) as bpmn_ids',
'    from completed_objects',
'    group by prcs_id, dgrm_id, diagram_level',
'), all_current as (',
'  select sbfl_prcs_id as prcs_id',
'       , sbfl_dgrm_id as dgrm_id',
'       , sbfl_diagram_level as diagram_level ',
'       , listagg(sbfl_current, '':'') within group ( order by sbfl_current ) as bpmn_ids',
'    from flow_subflows',
'   where sbfl_current is not null ',
'     and sbfl_status != ''delete on resume'' ',
'group by sbfl_prcs_id, sbfl_dgrm_id, sbfl_diagram_level',
'), all_errors as (',
'  select sbfl_prcs_id as prcs_id',
'       , sbfl_dgrm_id as dgrm_id',
'       , sbfl_diagram_level as diagram_level',
'       , listagg(sbfl_current, '':'') within group (order by sbfl_current) as bpmn_ids',
'    from flow_subflows',
'   where sbfl_current is not null',
'     and sbfl_status = ''error''',
'group by sbfl_prcs_id, sbfl_dgrm_id, sbfl_diagram_level',
'), user_tasks as (',
'    select process_id as prcs_id',
'         , json_objectagg',
'           (',
'               key current_obj',
'               value details_link_target',
'               absent on null',
'               returning clob',
'           ) as user_task_urls',
'      from flow_apex_my_combined_task_list_vw',
'     group by process_id',
')',
'  select prcs.prcs_id',
'       , prcs.prcs_name',
'       , prdg.prdg_id',
'       , prdg.prdg_prdg_id',
'       , prdg.prdg_diagram_level as diagram_level',
'       , prdg.prdg_calling_dgrm as calling_dgrm',
'       , prdg.prdg_calling_objt as calling_objt',
'       , dgrm.dgrm_name || case when prdg.prdg_diagram_level is not null then '' ( Level: '' || prdg.prdg_diagram_level || '' )'' else '''' end as breadcrumb',
'       , 1 as drilldown_allowed',
'       , dgrm.dgrm_id',
'       , dgrm.dgrm_name',
'       , dgrm.dgrm_version',
'       , dgrm.dgrm_status',
'       , dgrm.dgrm_category',
'       , dgrm.dgrm_content',
'       , ( select acomp.bpmn_ids',
'             from all_completed acomp',
'            where acomp.prcs_id = prcs.prcs_id',
'              and acomp.dgrm_id = dgrm.dgrm_id',
'              and acomp.diagram_level =  prdg.prdg_diagram_level',
'         ) as all_completed',
'       , null as last_completed     -- remove in v22.1',
'       , ( select acurr.bpmn_ids',
'             from all_current acurr',
'            where acurr.prcs_id = prcs.prcs_id',
'              and acurr.dgrm_id = dgrm.dgrm_id',
'              and acurr.diagram_level =  prdg.prdg_diagram_level',
'         ) as all_current',
'       , ( select aerr.bpmn_ids',
'             from all_errors aerr',
'            where aerr.prcs_id = prcs.prcs_id',
'              and aerr.dgrm_id = dgrm.dgrm_id',
'              and aerr.diagram_level =  prdg.prdg_diagram_level',
'         ) as all_errors',
'       , usta.user_task_urls',
'       , to_clob(null) as iteration_data',
'       , prov.prov_var_vc2 as prcs_business_ref',
'    from flow_processes prcs',
'    join flow_instance_diagrams prdg',
'      on prdg.prdg_prcs_id = prcs.prcs_id',
''))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434476002467425)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'    join flow_diagrams dgrm',
'      on prdg.prdg_dgrm_id = dgrm.dgrm_id',
'    left join flow_process_variables prov',
'      on prov.prov_prcs_id  = prcs.prcs_id',
'     and prov.prov_var_name = ''BUSINESS_REF''',
'     and prov.prov_var_type = ''VARCHAR2''',
'     and prov.prov_scope    = 0',
'    left join user_tasks usta',
'      on prcs.prcs_id = usta.prcs_id',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_details_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Per-diagram-level view for each instance showing current, completed, and error objects with user task URLs''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (prcs_id           annotations (add content ''Process instance identifier''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (prcs_name         annotations (add content ''Process instance name''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (prdg_id           annotations (add content ''Instance diagram record for this level''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (prdg_prdg_id      annotations (add content ''Parent instance diagram record (FK: flow_instance_diagrams)''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (diagram_level     annotations (add content ''Nesting depth of this diagram within the instance''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (calling_dgrm      annotations (add content ''Name of the diagram that called this sub-diagram''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (calling_objt      annotations (add content ''BPMN ID of the call activity that invoked this sub-diagram''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (breadcrumb        annotations (add content ''Slash-separated path of diagram names from root to this level''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (drilldown_allowed annotations (add content ''Y if the user may drill into this sub-diagram level''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (dgrm_content      annotations (add content ''BPMN XML content for this diagram level''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (all_completed     annotations (add content ''Comma-separated BPMN IDs of all completed objects at this level''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (last_completed    annotations (add content ''BPMN ID of the most recently completed object''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (all_current       annotations (add content ''Comma-separated BPMN IDs of all objects currently active''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (all_errors        annotations (add content ''Comma-separated BPMN IDs of objects currently in error''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (user_task_urls    annotations (add content ''JSON structure of user task step keys and their APEX page URLs''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (iteration_data    annotations (add content ''JSON structure describing loop and multi-instance iteration state''))]'';',
'    execute immediate q''[alter view flow_instance_details_vw modify (prcs_business_ref annotations (add content ''Business reference key value for this instance''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_instance_diagrams_lov',
'as',
'  select distinct',
'    case when callobj.objt_id is null then ''Main Diagram'' else callobj.objt_name end as calling_diagram,',
'    prdg.prdg_id,',
'    prdg.prdg_prcs_id',
'  from flow_instance_diagrams prdg',
'  join flow_objects obj',
'        on obj.objt_dgrm_id = prdg.prdg_dgrm_id',
'  left join flow_objects callobj ',
'    on callobj.objt_dgrm_id = prdg.prdg_calling_dgrm',
'        and callobj.objt_bpmn_id = prdg.prdg_calling_objt',
'  where obj.objt_tag_name in (''bpmn:exclusiveGateway'', ''bpmn:inclusiveGateway'')',
'  and ( select count(*) from flow_connections conn where conn.conn_src_objt_id = obj.objt_id ) > 1',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_diagrams_lov annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Diagrams active within a process instance for LOV selection''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_diagrams_lov modify (calling_diagram annotations (add content ''Name of the calling diagram, or Main Diagram for the root level''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'/* ',
'-- Flows for APEX - flow_instance_events_vw.sql',
'-- ',
'--',
'-- Created    09-Jul-2025  Louis Moreaux, Talan',
'--',
'-- This view shows logged events for a process',
'--',
'--',
'*/',
'create or replace view flow_instance_events_vw as',
'with events as (',
'     select lgpr_prcs_event as operation',
'     , lgpr_prcs_event description',
'     , coalesce (objt.objt_name, lgpr_objt_id) as objt',
'     , coalesce (objt.objt_tag_name, ''bpmn:process'') as object_type',
'     , objt.objt_sub_tag_name as object_sub_type',
'     , nvl( objt.objt_interrupting, 2) as object_interrupting',
'     , lgpr_sbfl_id as subflow',
'     , lgpr_step_key as step_key',
'     , lgpr_severity as severity',
'     , lgpr_process_level as process_level',
'     , null as proc_var',
'     , null as value',
'     , lgpr_comment as event_comment',
'     , lgpr_timestamp as performed_on',
'     , lgpr_user as performed_by',
'     , lgpr_prcs_id as prcs_id ',
'  from flow_instance_event_log   ',
'  left outer join flow_objects objt',
'    on lgpr_objt_id = objt.objt_bpmn_id',
'   and lgpr_dgrm_id = objt.objt_dgrm_id',
')',
'select events.operation',
'     , events.description',
'     , events.objt',
'     , events.object_type',
'     , events.object_sub_type',
'     , bpmn.bpmn_icon',
'     , bpmn.bpmn_super_type as bpmn_super_type',
'     , events.proc_var',
'     , events.value',
'     , events.subflow',
'     , events.step_key',
'     , events.severity',
'     , events.process_level',
'     , events.event_comment',
'     , events.performed_on',
'     , events.performed_by',
'     , events.prcs_id',
'  from events',
'  join flow_bpmn_types bpmn',
'    on bpmn.bpmn_tag_name               = events.object_type',
'   and nvl(bpmn.bpmn_sub_tag_name, ''X'') = nvl(events.object_sub_type, ''X'')',
'   and nvl(bpmn.bpmn_interrupting, 2)   = events.object_interrupting',
'order by events.performed_on',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_events_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''logging''',
'  , add content ''Process event log with object types, severity levels, and performer information''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (operation       annotations (add content ''Event operation type, e.g. complete, start, error, set-variable''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (description     annotations (add content ''Human-readable description of the event''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (objt            annotations (add content ''BPMN ID of the object involved in this event''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (object_type     annotations (add content ''BPMN element type of the object, e.g. bpmn:userTask''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (object_sub_type annotations (add content ''BPMN element sub-type, e.g. bpmn:messageEventDefinition''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (bpmn_icon       annotations (add content ''CSS icon class for the BPMN object type''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (bpmn_super_type annotations (add content ''High-level BPMN category: event, gateway, activity, etc.''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (proc_var        annotations (add content ''Process variable name involved in this event, if applicable''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (value           annotations (add content ''Variable value or event payload at the time of the event''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (subflow         annotations (add content ''Subflow ID on which the event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (step_key        annotations (add content ''Step key identifying the step within the process where the event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (severity        annotations (add content ''Event severity label: 1 to 8, with 1 being the most severe''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (process_level   annotations (add content ''Nesting level of the sub-diagram where the event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (event_comment   annotations (add content ''Optional descriptive comment attached to the event''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (performed_on    annotations (add content ''Timestamp when this event was recorded''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (performed_by    annotations (add content ''User or system that triggered this event''))]'';',
'    execute immediate q''[alter view flow_instance_events_vw modify (prcs_id         annotations (add content ''Process instance this event belongs to''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_instance_gateways_lov',
'as',
'  select obj.objt_id',
'       , obj.objt_bpmn_id',
'       , case when callobj.objt_id is null then ''Main Diagram'' else callobj.objt_name end calling_object',
'       , case when obj.objt_name is null then obj.objt_bpmn_id else obj.objt_name || '' ('' || obj.objt_bpmn_id ||'')'' end objt_name',
'       , case obj.objt_tag_name',
'           when ''bpmn:exclusiveGateway'' then ''single''',
'           when ''bpmn:inclusiveGateway'' then ''multi''',
'           else null',
'         end as select_option',
'       , ins.prcs_id',
'       , prdg.prdg_diagram_level',
'       , prdg.prdg_dgrm_id',
'       , prdg.prdg_prdg_id',
'       , prdg.prdg_id',
'    from flow_instances_vw ins',
'    join flow_instance_diagrams prdg',
'      on prdg.prdg_prcs_id = ins.prcs_id',
'     and prdg.prdg_diagram_level is not null',
'    join flow_objects obj',
'      on obj.objt_dgrm_id = prdg.prdg_dgrm_id',
'    left join flow_objects callobj',
'      on callobj.objt_dgrm_id = prdg.prdg_calling_dgrm',
'      and callobj.objt_bpmn_id = prdg.prdg_calling_objt',
'   where obj.objt_tag_name in (''bpmn:exclusiveGateway'', ''bpmn:inclusiveGateway'')',
'     and ( select count(*) ',
'           from flow_connections conn ',
'           where conn.conn_src_objt_id = obj.objt_id ',
'           and conn.conn_tag_name = ''bpmn:sequenceFlow'') > 1',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_gateways_lov annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Exclusive and inclusive gateways with multiple outgoing flows for manual conditional routing selection''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (objt_id            annotations (add content ''System ID of the gateway object''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (objt_bpmn_id       annotations (add content ''BPMN identifier of the gateway''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (calling_object     annotations (add content ''BPMN ID of the subflow object calling this gateway selection''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (objt_name          annotations (add content ''Display name of the gateway''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (select_option      annotations (add content ''Outgoing connection option available for manual routing selection''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (prcs_id            annotations (add content ''Process instance identifier''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (prdg_diagram_level annotations (add content ''Diagram level of the subflow executing this gateway''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (prdg_dgrm_id       annotations (add content ''Diagram ID of the sub-diagram''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (prdg_prdg_id       annotations (add content ''Parent instance diagram record''))]'';',
'    execute immediate q''[alter view flow_instance_gateways_lov modify (prdg_id            annotations (add content ''Instance diagram record for this gateway''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_instance_scopes_vw',
'as',
'  select prdg_prcs_id         iscp_prcs_id',
'       , prdg_diagram_level   iscp_valid_scope',
'    from flow_instance_diagrams',
'   where prdg_diagram_level is not null',
'  union',
'  select distinct iter_prcs_id iscp_prcs_id',
'       , iter_scope            iscp_valid_scope',
'    from flow_iterations',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_scopes_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Valid process variable scopes derived from sub-diagram levels and multi-instance iterations''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_scopes_vw modify (iscp_prcs_id     annotations (add content ''Process instance identifier''))]'';',
'    execute immediate q''[alter view flow_instance_scopes_vw modify (iscp_valid_scope annotations (add content ''Valid scope number for process variable lookup within this instance''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_instance_summary_json_vw as ',
' with s as',
'                    (select distinct sc.lgvr_scope scope, sc.lgvr_prcs_id',
'                    from   flow_variable_event_log sc',
'                    )',
'select prcs_id, prcs_status, systimestamp as json_created_date, ',
'        json_object (',
'    ''processID''        : p.prcs_id,',
'    ''mainDiagram''      : p.prcs_dgrm_id,',
'    ''processName''      : p.prcs_name,',
'    ''businessID''       : prov.prov.prov_var_vc2,',
'    ''priority''         : p.prcs_priority,',
'    ''prcs_status''      : p.prcs_status,',
'    ''prcs_was_altered'' : p.prcs_was_altered,',
'    ''json_created''     : systimestamp,',
'    ''prcs_init_ts''     : p.prcs_init_ts,',
'    ''prcs_init_by''     : p.prcs_init_by,',
'    ''prcs_due_on''      : p.prcs_due_on,',
'    ''diagramsUsed''     :',
'         (select json_arrayagg ',
'                    ( json_object ',
'                        (',
'                        ''diagramLevel''               value prdg_diagram_level,',
'                        ''diagramId''                  value prdg_dgrm_id,',
'                        ''diagramName''                value dgrm_name,',
'                        ''diagramVersion''             value dgrm_version,',
'                        ''diagramStatus''              value dgrm_status,',
'                        ''callingDiagram''             value prdg_calling_dgrm,',
'                        ''callingObject''              value prdg_calling_objt',
'                        ) ORDER BY prdg_diagram_level asc ',
'                    )',
'            from flow_instance_diagrams prdg',
'            join flow_diagrams dgrm',
'              on dgrm.dgrm_id = prdg.prdg_dgrm_id',
'           where prdg.prdg_prcs_id = p.prcs_id   ',
'        ),',
'    ''events'' : ',
'        (select json_arrayagg ',
'                    ( json_object ',
'                        (',
'                        ''event''                      value lgpr_prcs_event,',
'                        ''object''                     value lgpr_OBJT_ID,',
'                        ''diagram''                    value lgpr_DGRM_ID,',
'                        ''timestamp''                  value lgpr_timestamp,',
'                        ''user''                       value lgpr_USER,',
'                        ''error-info''                 value lgpr_ERROR_INFO,',
'                        ''comment''                    value lgpr_COMMENT absent on null',
'                        ) ORDER BY lgpr_timestamp ',
'                   returning clob )',
'           from flow_instance_event_log lgpr',
'          where lgpr.lgpr_prcs_id = p.prcs_id',
'        ),       ',
'    ''steps'' :',
'        (select json_arrayagg',
'                    (json_object ',
'                        (',
'                        ''object''                     VALUE LGSF_OBJT_ID,',
'                        ''subflowID''                  VALUE LGSF_SBFL_ID,',
'                        ''processLevel''               VALUE LGSF_SBFL_PROCESS_LEVEL,',
'                        ''priority''                   VALUE lgsf_priority,',
'                        ''lastCompleted''              VALUE LGSF_LAST_COMPLETED,',
'                        ''wasCurrent''                 VALUE LGSF_WAS_CURRENT,',
'                        ''wasStarted''                 VALUE LGSF_STARTED,',
'                        ''wasCompleted''               VALUE LGSF_COMPLETED,',
'                        ''statusWhenComplete''         VALUE LGSF_STATUS_WHEN_COMPLETE,',
'                        ''subflowDiagram''             VALUE LGSF_SBFL_DGRM_ID,',
'                        ''reservation''                VALUE LGSF_RESERVATION,',
'                        ''user''                       VALUE LGSF_USER,',
'                        ''comment''                    VALUE LGSF_COMMENT absent on null',
'                        ) ORDER BY lgsf_was_current',
'                    returning clob)',
'          from flow_step_event_log lgsf',
'         where lgsf.lgsf_prcs_id = p.prcs_id',
'        ),',
'    ''processVariablesSet'' :',
'            (  select json_arrayagg (',
'                    json_object (',
'                        ''scope''         : s.scope,',
'                        ''variables''     :',
'                            ( select json_arrayagg ',
'                                        (',
'                                        json_object ',
'                                            (',
'                                            ''var_name''        value lgvr.lgvr_var_name,',
'                                            ''subflowID''       value lgvr.lgvr_sbfl_id,',
'                                            ''objectId''        value lgvr.lgvr_objt_id,',
'                                            ''expr_set''        value lgvr.lgvr_expr_set,',
'                                            ''type''            value lgvr.lgvr_var_type,',
'                                            ''timestamp''       value lgvr.lgvr_timestamp,',
'                                            ''newValue''        value case lgvr.lgvr_var_type',
'                                                                    when ''VARCHAR2''                   then lgvr.lgvr_var_vc2',
'                                                                    when ''NUMBER''                     then to_char(lgvr.lgvr_var_num)',
'                                                                    when ''DATE''                       then to_char(lgvr.lgvr_var_date,''YYYY-MM-DD"T"HH24:MI:SS"Z"'')',
'                                                                    when ''TIMESTAMP WITH TIME ZONE''   then to_char(lgvr.lgvr_var_tstz,''YYYY-MM-DD"T"HH24:MI:SSTZR'')',
'                                                                    when ''CLOB''                       then ''CLOB Value''',
'                                                                    end ',
'                                            )',
'                                        order by lgvr.lgvr_timestamp ',
'                                        )',
'                                from flow_variable_event_log lgvr',
'                               where lgvr.lgvr_prcs_id = p.prcs_id',
'                                 and lgvr.lgvr_scope   = s.scope',
'                            )',
'                        )',
'                    returning clob )',
'                from s',
'               where s.lgvr_prcs_id = p.prcs_id',
'            )',
'        returning clob)  summary_json',
'  from flow_processes p',
'  left join flow_process_variables prov',
'    on prov.prov_prcs_id    = p.prcs_id',
' where prov.prov_var_name   = ''BUSINESS_REF''',
'   and prov.prov_scope      = 0',
';',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_summary_json_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Complete process instance state as nested JSON including diagrams, events, steps, and variable history. If process instance is not yet completed,  this JSON contains state as at creation date.''',
'  , add note    ''This view is intended for archiving the full state of a process instance as a single JSON document, which can then be parsed and used to display instance details, timelines, variable histories, etc.  Note that the summary_json column'
||' can be quite large and may require CLOB handling on the application side.  It can also be used for problem diagnosis and debugging to understand the full state of a process instance at a given point in time.''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_summary_json_vw modify (prcs_id           annotations (add content ''Process instance identifier''))]'';',
'    execute immediate q''[alter view flow_instance_summary_json_vw modify (prcs_status       annotations (add content ''Current execution status of the process instance''))]'';',
'    execute immediate q''[alter view flow_instance_summary_json_vw modify (json_created_date annotations (add content ''Timestamp when this JSON summary was generated''))]'';',
'    execute immediate q''[alter view flow_instance_summary_json_vw modify (summary_json      annotations (add content ''Full instance state as a nested JSON document (CLOB)''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'/* ',
'-- Flows for APEX - flow_instance_timeline_vw.sql',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'--',
'-- Created    01-Feb-2023  Richard Allen (Oracle)',
'-- Edited     05-Jun-2023  Louis Moreaux, Insum',
'--',
'-- This view shows timeline of all logged events for a process',
'--',
'--',
'*/',
'create or replace view flow_instance_timeline_vw as',
'select ''created'' operation',
'     , ''Instance Created'' description',
'     , null as objt',
'     , null as subflow',
'     , 0 as process_level',
'     , null as proc_var',
'     , prcs.prcs_name as value',
'     , null as event_comment',
'     , prcs_init_ts performed_on',
'     , prcs_init_by performed_by',
'     , prcs_id ',
'  from flow_processes prcs',
'union',
'select ''started'' operation',
'     , ''Instance Started'' description',
'     , null as objt',
'     , null as subflow',
'     , 0 as process_level',
'     , null as proc_var ',
'     , prcs.prcs_name as value',
'     , null as event_comment',
'     , prcs_start_ts performed_on',
'     , null',
'     , prcs_id ',
'  from flow_processes prcs',
'union',
'select ''completed'' operation',
'     , ''Instance completed'' description',
'     , null as objt',
'     , null as subflow',
'     , 0 as process_level',
'     , null as proc_var',
'     , null as value',
'     , null as event_comment',
'     , prcs_start_ts performed_on',
'     , null',
'     , prcs_id ',
'  from flow_processes prcs',
' where prcs.prcs_complete_ts is not null',
'union',
'select lgpr_prcs_event operation',
'     , lgpr_prcs_event ',
'     , lgpr_objt_id',
'     , null as subflow',
'     , null as process_level',
'     , null as proc_var',
'     , null as value',
'     , lgpr_comment as event_comment',
'     , lgpr_timestamp performed_on',
'     , lgpr_user',
'     , lgpr_prcs_id as prcs_id',
'  from    flow_instance_event_log lgpr',
'union ',
'select ''step current'' as operation',
'     , ''Became Current after'' as description',
'     , lgsf_objt_id as objt',
'     , lgsf_sbfl_id as subflow',
'     , lgsf_sbfl_process_level as process_level',
'     , null as proc_var',
'     , lgsf_last_completed as value',
'     , lgsf_comment as event_comment',
'     , lgsf_was_current as performed_on',
'     , null as performed_by',
'     , lgsf_prcs_id as prcs_id ',
'  from flow_step_event_log',
'union',
'select ''step started'' as operation',
'     , ''Work Started on Step'' description',
'     , lgsf_objt_id as objt',
'     , lgsf_sbfl_id as subflow',
'     , lgsf_sbfl_process_level as process_level',
'     , null as proc_var',
'     , null as value',
'     , lgsf_comment as event_comment',
'     , lgsf_started as performed_on',
'     , null as performed_by',
'     , lgsf_prcs_id as prcs_id ',
'  from flow_step_event_log',
' where lgsf_started is not null',
'union ',
'select ''step completed'' as operation',
'     , ''Step completed'' description',
'     , lgsf_objt_id as objt',
'     , lgsf_sbfl_id as subflow',
'     , lgsf_sbfl_process_level as process_level',
'     , null as proc_var',
'     , null as value',
'     , lgsf_comment as event_comment',
'     , lgsf_completed as performed_on',
'     , lgsf_user as performed_by',
'     , lgsf_prcs_id as prcs_id ',
'  from flow_step_event_log   ',
'union ',
'select ''variable set'' as operation',
'     , ''Variable set'' as description',
'     , lgvr_objt_id as objt',
'     , lgvr_sbfl_id as subflow',
'     , null as process_level',
'     , lgvr_var_name as proc_var',
'     , case lgvr_var_type ',
'          when ''VARCHAR2'' then lgvr_var_vc2',
'          when ''NUMBER'' then to_char(lgvr_var_num)',
'          when ''DATE'' then to_char (lgvr_var_date, ''DD-MON-YY HH24:MI:SS'')',
'          when ''TIMESTAMP WITH TIME ZONE'' then to_char (lgvr_var_tstz, ''DD-MON-YY HH24:MI:SS TZR'')',
'          when ''CLOB'' then ''CLOB Value''',
'          end as value',
'     , lgvr_expr_set as event_comment',
'     , lgvr_timestamp as performed_on',
'     , null as performed_by',
'     , lgvr_prcs_id as prcs_id ',
'  from    flow_variable_event_log',
'order by performed_on',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_instance_timeline_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''logging''',
'  , add content ''Unified timeline of all process events including creation, start, step transitions, and variable assignments''',
'  )]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (operation     annotations (add content ''Event operation type''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (description   annotations (add content ''Human-readable description of the event''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (objt          annotations (add content ''BPMN ID of the object involved''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (subflow       annotations (add content ''Subflow ID on which the event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (process_level annotations (add content ''Nesting level where the event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (proc_var      annotations (add content ''Process variable name, for variable assignment events''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (value         annotations (add content ''Variable value at the time of assignment''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (event_comment annotations (add content ''Optional descriptive comment''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (performed_on  annotations (add content ''Timestamp when this event occurred''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (performed_by  annotations (add content ''User or s'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434476002467425)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ystem that triggered this event''))]'';',
'    execute immediate q''[alter view flow_instance_timeline_vw modify (prcs_id       annotations (add content ''Process instance this timeline entry belongs to''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
