'        , decode( lower(pv.prov_var_type) ',
'              , ''varchar2'', pv.prov_var_vc2',
'              , ''number'',   pv.prov_var_num',
'              , ''date'',     pv.prov_var_date',
'              , ''clob'',     pv.prov_var_clob',
'              , ''timestamp with time zone'', pv.prov_var_tstz',
'              , ''json'', pv.prov_var_json',
'              , null ) as value',
'  from flow_process_variables pv;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_rest_process_vars_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Process variables with type-aware value conversion for REST API responses''',
'  )]'';',
'    execute immediate q''[alter view flow_rest_process_vars_vw modify (prcs_id annotations (add content ''Process instance this variable belongs to''))]'';',
'    execute immediate q''[alter view flow_rest_process_vars_vw modify (scope   annotations (add content ''Variable scope number''))]'';',
'    execute immediate q''[alter view flow_rest_process_vars_vw modify (name    annotations (add content ''Variable name''))]'';',
'    execute immediate q''[alter view flow_rest_process_vars_vw modify (type    annotations (add content ''Variable data type: VARCHAR2, NUMBER, DATE, TIMESTAMP, CLOB, JSON''))]'';',
'    execute immediate q''[alter view flow_rest_process_vars_vw modify (value   annotations (add content ''Variable value cast to VARCHAR2 for REST response''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_rest_processes_vw',
'      (',
'          dgrm_id',
'        , prcs_id',
'        , name',
'        , status',
'        , init_ts',
'        , init_by',
'        , process_vars',
'        , links',
'      )',
'  as',
'  SELECT  ',
'          d.dgrm_id',
'        , p.prcs_id',
'        , p.prcs_name     as name',
'        , p.prcs_status   as status',
'        , p.prcs_init_ts  as init_ts',
'        , p.prcs_init_by  as init_by',
'        , json_array( ',
'            listagg( ',
'                json_object (',
'                  ''scope'' value pv.prov_scope',
'                 , ''name'' value pv.prov_var_name',
'                 , ''type'' value pv.prov_var_type',
'                 , ''value'' value decode( lower(pv.prov_var_type) ',
'                                      , ''varchar2'', pv.prov_var_vc2',
'                                      , ''number'',   pv.prov_var_num',
'                                      , ''date'',     pv.prov_var_num',
'                                      , ''clob'',     pv.prov_var_num',
'                                      , null )',
'                )     ',
'            ,'','') format json',
'          ) process_vars',
'        , json_array(',
'            flow_rest_api_v1.get_links_string_http_GET(''process'',p.prcs_id) format json',
'          ) links',
'  from flow_diagrams d',
'  join flow_processes p on d.dgrm_id = p.prcs_dgrm_id',
'  left join flow_process_variables pv on p.prcs_id = pv.prov_prcs_id',
'  group by  d.dgrm_id',
'          , p.prcs_id',
'          , p.prcs_name',
'          , p.prcs_status',
'          , p.prcs_init_ts',
'          , p.prcs_init_by;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_rest_processes_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Process instances with aggregated variables and HATEOAS links formatted for REST API''',
'  )]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (dgrm_id      annotations (add content ''Diagram this instance was created from''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (prcs_id      annotations (add content ''Unique process instance identifier''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (name         annotations (add content ''Process instance name''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (status       annotations (add content ''Current execution status''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (init_ts      annotations (add content ''Timestamp when the instance was initialised''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (init_by      annotations (add content ''User who initialised the instance''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (process_vars annotations (add content ''JSON array of current process variables''))]'';',
'    execute immediate q''[alter view flow_rest_processes_vw modify (links        annotations (add content ''HATEOAS links JSON for this process instance resource''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_rest_step_event_log_vw',
'      (',
'          lgsf_prcs_id',
'        , lgsf_objt_id ',
'      )',
'  as',
'  select  lgsf_prcs_id',
'        , lgsf_objt_id ',
'    from flow_step_event_log d;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_rest_step_event_log_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''logging''',
'  , add content ''Step event log entries formatted for REST API responses''',
'  )]'';',
'    execute immediate q''[alter view flow_rest_step_event_log_vw modify (lgsf_prcs_id annotations (add content ''Process instance this log entry belongs to''))]'';',
'    execute immediate q''[alter view flow_rest_step_event_log_vw modify (lgsf_objt_id annotations (add content ''Object ID involved in this step event''))]'';',
'  end if;',
