'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_rest_subflows_vw',
'      (',
'         prcs_id',
'       , sbfl_id',
'       , sbfl_sbfl_id',
'       , process_level',
'       , diagram_level',
'       , calling_sbfl',
'       , scope',
'       , "current"',
'       , step_key',
'       , status',
'       , became_current',
'       , reservation',
'       , links',
'      )',
'  as',
'  select p.prcs_id',
'       , s.sbfl_id',
'       , s.sbfl_sbfl_id',
'       , s.sbfl_process_level   as process_level',
'       , s.sbfl_diagram_level   as diagram_level',
'       , s.sbfl_calling_sbfl    as calling_sbfl',
'       , s.sbfl_scope           as scope',
'       , s.sbfl_current         as "current"',
'       , s.sbfl_step_key        as step_key',
'       , s.sbfl_status          as status',
'       , s.sbfl_became_current  as became_current',
'       , s.sbfl_reservation     as reservation',
'       , json_array(',
'           flow_rest_api_v1.get_links_string_http_GET(''step'',s.sbfl_id) format json',
'         ) links',
'  from flow_processes p',
'  join flow_subflows s on p.prcs_id = s.sbfl_prcs_id;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_rest_subflows_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Subflow instances with execution status and reservation data formatted for REST API with HATEOAS links''',
'  )]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (prcs_id        annotations (add content ''Parent process instance identifier''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (sbfl_id        annotations (add content ''Subflow instance identifier''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (sbfl_sbfl_id   annotations (add content ''Parent subflow identifier (FK: flow_subflows)''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (process_level  annotations (add content ''Process nesting level''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (diagram_level  annotations (add content ''Diagram nesting level''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (calling_sbfl   annotations (add content ''Subflow that created this one via a call activity''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (scope          annotations (add content ''Variable scope number for this subflow''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify ("current"      annotations (add content ''BPMN ID of the current object on this subflow''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (step_key       annotations (add content ''Step key identifying the current execution position''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (status         annotations (add content ''Current execution status of this subflow''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (became_current annotations (add content ''Timestamp when the current object was reached''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (reservation    annotations (add content ''User who has reserved this user task''))]'';',
'    execute immediate q''[alter view flow_rest_subflows_vw modify (links          annotations (add content ''HATEOAS links JSON for this subflow resource''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'/* ',
'-- Flows for APEX - flow_startable_adhoc_activities_vw.sql',
'-- ',
'-- (c) Copyright Flowquest Limited and / or its affiliates, 2025-2026.',
'--',
'-- todo - should this be a materialized view?',
'--',
'-- Created    22-Nov-2025  Richard Allen,  Flowquest Limited',
'*/',
'create or replace view flow_startable_adhoc_activities_vw as',
'  select ahat.dgrm_id                   as  dgrm_id',
'       , sbfl.sbfl_id                   as  subproc_sbfl_id',
'       , sbfl.sbfl_prcs_id              as  prcs_id  ',
'       , sbfl.sbfl_step_key             as  subproc_step_key',
'       , ahat.subprocess_bpmn_id        as  subproc_bpmn_id',
'       , sbfl.sbfl_ahsp_id              as  ahsp_id',
'       , ahat.activity_bpmn_id          as  activity_bpmn_id',
'       , ahat.activity_name             as  activity_name ',
'       , ahat.activity_description      as  activity_description',
'       , ahat.activity_grouping         as  activity_grouping',
'       , ahat.activity_display_order    as  activity_display_order',
'       , ahat.activity_tag_name         as  activity_tag_name',
'       , ahat.activity_is_repeatable    as  activity_is_repeatable ',
'       , ahat.activity_input_parameters  as  activity_input_parameters',
'       , ahat.activity_output_parameters as  activity_output_parameters',
'    from flow_adhoc_activities_vw ahat',
'    join flow_subflows sbfl',
'      on sbfl.sbfl_dgrm_id  = ahat.dgrm_id',
'     and sbfl.sbfl_current  = ahat.subprocess_bpmn_id',
'   where ( ahat.activity_is_repeatable = ''Y''',
'            or not exists ( select 1',
'                              from flow_adhoc_subflows ahsf',
'                             where ahsf.ahsf_starting_object = ahat.activity_bpmn_id',
'                               and ahsf.ahsf_ahsp_id         = sbfl.sbfl_ahsp_id)',
'         )',
'     -- Add start condition filtering - if condition exists, it must be met  ',
'     and (ahat.activity_start_condition is null ',
'          or flow_adhoc_subprocesses.activity_start_condition_met_YN ',
'              ( p_process_id =>sbfl.sbfl_prcs_id',
'              , p_activity_start_condition => ahat.activity_start_condition ',
'              , p_scope => sbfl.sbfl_scope',
'              ) = ''Y'')',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_startable_adhoc_activities_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Ad-hoc activities eligible to start for the current subflow, filtered by repeatability and start conditions''',
'  )]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'/* ',
'-- Flows for APEX - flow_startable_diagrams_vw.sql',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'--',
'-- Created    05-Apr-2023  Richard Allen (Oracle)',
'-- Edited     05-Jun-2023  Louis Moreaux, Insum',
'-- Edited     07-Oct-2024  Dennis Amthor, Hyand Solutions GmbH',
'-- Edited     11-Jun-2025  Dennis Amthor, Hyand Solutions GmbH',
'--',
'-- This view shows any process diagrams that are marked as startable, along with users and groups that can start them',
'-- and excluded uses who cannot start them (takes precedence over positive grants in potentialStartingGroups).',
'--',
'--  -- Note this View can only be queried inside an APEX session',
'--',
'*/',
'create or replace view flow_startable_diagrams_vw',
'as ',
'select dgrm.dgrm_id',
'     , dgrm.dgrm_name',
'     , dgrm.dgrm_short_description',
'     , dgrm.dgrm_description',
'     , dgrm.dgrm_icon',
'     , dgrm.dgrm_category',
'     , dgrm.dgrm_version',
'     , dgrm.dgrm_status',
'     , objt.objt_name process_name',
'     , objt.objt_bpmn_id process_bpmn_id',
'     , nvl2(objt.objt_attributes."apex"."potentialStartingUsers", flow_settings.get_vc2_expression(pi_expr=> objt.objt_attributes."apex"."potentialStartingUsers"),null) potential_starting_users',
'     , nvl2(objt.objt_attributes."apex"."potentialStartingGroups", flow_settings.get_vc2_expression(pi_expr=> objt.objt_attributes."apex"."potentialStartingGroups"),null) potential_starting_groups',
'     , nvl2(objt.objt_attributes."apex"."excludedStartingUsers", flow_settings.get_vc2_expression(pi_expr=> objt.objt_attributes."apex"."excludedStartingUsers"),null) excluded_starting_users',
'  from flow_diagrams_vw dgrm',
'  join flow_objects objt',
'    on dgrm.dgrm_id = objt.objt_dgrm_id',
'   and objt.objt_attributes."apex"."isStartable" = ''true''',
'  with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_startable_diagrams_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''definition''',
'  , add content ''Diagrams marked as startable with user and group permissions for initiating process instances''',
'  )]'';',
'    execute immediate q''[alter view flow_startable_diagrams_vw modify (process_name annotations (add content ''Display name of the startable process start event''))]'';',
'    execute immediate q''[alter view flow_startable_diagrams_vw modify (process_bpmn_id annotations (add content ''BPMN ID of the startable process object''))]'';',
'    execute immediate q''[alter view flow_startable_diagrams_vw modify (potential_starting_users annotations (add content ''Evaluated list of users permitted to start this process''))]'';',
'    execute immediate q''[alter view flow_startable_diagrams_vw modify (potential_starting_groups annotations (add content ''Evaluated list of groups permitted to start this process''))]'';',
'    execute immediate q''[alter view flow_startable_diagrams_vw modify (excluded_starting_users annotations (add content ''Evaluated list of users excluded from starting this process''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_subflows_vw',
'as',
'   select sbfl.sbfl_id',
'        , sbfl.sbfl_sbfl_id',
'        , sbfl.sbfl_prcs_id',
'        , coalesce( prcs.prcs_name, to_char(sbfl.sbfl_prcs_id)) as sbfl_process_name  -- flow instance ref',
'        , prcs.prcs_dgrm_id as sbfl_dgrm_id',
'        , sbfl.sbfl_dgrm_id as sbfl_sbfl_dgrm_id -- sbfl level dgrm id',
'        , dgrm.dgrm_name as sbfl_dgrm_name  -- flow name',
'        , dgrm.dgrm_version as sbfl_dgrm_version',
'        , dgrm.dgrm_status as sbfl_dgrm_status',
'        , dgrm.dgrm_category as sbfl_dgrm_category',
'        , sbfl.sbfl_starting_object',
'        , coalesce( objt_start.objt_name, sbfl.sbfl_starting_object ) as sbfl_starting_object_name',
'        , sbfl.sbfl_route',
'        , coalesce( conn.conn_name, sbfl.sbfl_route ) as sbfl_route_name',
'        , sbfl.sbfl_last_completed',
'        , coalesce( objt_last.objt_name, sbfl.sbfl_last_completed ) as sbfl_last_completed_name',
'        , sbfl.sbfl_current',
'        , coalesce( objt_curr.objt_name ||case ',
'                                          when sbfl_loop_counter is null then ''''',
'                                          else ''[''||sbfl_loop_counter||'']''',
'                                          end',
'                  , sbfl.sbfl_current ',
'                  ) as sbfl_current_name',
'        , iter.iter_display_name as sbfl_iteration_path',
'        , sbfl.sbfl_iter_id    -- remove from prod',
'        , sbfl.sbfl_iobj_id    -- remove from prod',
'        , sbfl.sbfl_iterati'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434476002467425)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'on_type -- remove from prod',
'        , sbfl.sbfl_step_key',
'        , objt_curr.objt_tag_name as sbfl_current_tag_name',
'        , sbfl.sbfl_became_current',
'        , sbfl.sbfl_due_on',
'        , sbfl.sbfl_last_update',
'        , sbfl.sbfl_last_update_by',
'        , sbfl.sbfl_priority',
'        , sbfl.sbfl_status',
'        , sbfl.sbfl_lane as sbfl_current_lane',
'        , sbfl.sbfl_lane_name as sbfl_current_lane_name',
'        , sbfl.sbfl_lane_isrole',
'        , sbfl.sbfl_lane_role',
'        , sbfl.sbfl_apex_task_id',
'        , sbfl.sbfl_process_level',
'        , sbfl.sbfl_diagram_level',
'        , sbfl.sbfl_loop_counter',
'        , sbfl.sbfl_loop_total_instances',
'        , sbfl.sbfl_scope',
'        , sbfl.sbfl_calling_sbfl',
'        , sbfl.sbfl_reservation',
'        , sbfl.sbfl_potential_users',
'        , sbfl.sbfl_potential_groups',
'        , sbfl.sbfl_excluded_users',
'        , objt_curr.objt_id as sbfl_current_objt_id',
'        , prcs.prcs_init_ts as sbfl_prcs_init_ts',
'        , case sbfl.sbfl_status ',
'          when ''waiting for timer'' then timr.timr_start_on',
'          else null',
'          end as timr_start_on',
'     from flow_subflows sbfl',
'     join flow_processes prcs',
'       on prcs.prcs_id = sbfl.sbfl_prcs_id',
'left join flow_objects objt_start',
'       on objt_start.objt_bpmn_id = sbfl.sbfl_starting_object',
'      and objt_start.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'left join flow_objects objt_curr',
'       on objt_curr.objt_bpmn_id = sbfl.sbfl_current',
'      and objt_curr.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'left join flow_objects objt_last',
'       on objt_last.objt_bpmn_id = sbfl.sbfl_last_completed',
'      and objt_last.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'left join flow_connections conn',
'       on conn.conn_bpmn_id = sbfl.sbfl_route',
'      and conn.conn_dgrm_id = sbfl.sbfl_dgrm_id',
'     join flow_diagrams dgrm ',
'       on dgrm.dgrm_id = prcs.prcs_dgrm_id',
'left join flow_timers timr',
'       on timr.timr_prcs_id = sbfl.sbfl_prcs_id',
'      and timr.timr_sbfl_id = sbfl.sbfl_id',
'      and timr.timr_status in (''C'', ''A'', ''B'')',
'left join flow_iterations iter',
'       on iter.iter_id = sbfl.sbfl_iter_id',
'with read only',
';',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_subflows_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''All subflow execution instances with current and completed objects, assignments, lane data, and timer information''',
'  )]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_process_name annotations (add content ''Process instance name resolved from the process record''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_dgrm_id annotations (add content ''Diagram ID of the top-level process diagram''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_sbfl_dgrm_id annotations (add content ''Diagram ID at the subflow level for called diagrams''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_dgrm_name annotations (add content ''Name of the diagram this subflow is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_dgrm_version annotations (add content ''Version of the diagram this subflow is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_dgrm_status annotations (add content ''Status of the diagram this subflow is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_dgrm_category annotations (add content ''Category of the diagram this subflow is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_starting_object_name annotations (add content ''Display name of the subflow starting BPMN object''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_route_name annotations (add content ''Display name of the sequence flow route taken''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_last_completed_name annotations (add content ''Display name of the last completed BPMN object''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_current_name annotations (add content ''Display name of the current BPMN object, including loop counter''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_iteration_path annotations (add content ''Human-readable path of the current iteration for looping subflows''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_current_tag_name annotations (add content ''BPMN element type of the current object''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_current_lane annotations (add content ''Lane BPMN ID where the current step is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_current_lane_name annotations (add content ''Display name of the lane where the current step is executing''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_current_objt_id annotations (add content ''Internal object ID of the current BPMN object''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (sbfl_prcs_init_ts annotations (add content ''Timestamp when the parent process instance was created''))]'';',
'    execute immediate q''[alter view flow_subflows_vw modify (timr_start_on annotations (add content ''Scheduled start time for subflows waiting for a timer''))]'';',
'  end if;',
'end;',
