'create or replace view flow_task_inbox_vw',
'as ',
'   select sbfl_id',
'        , sbfl_sbfl_id',
'        , sbfl_prcs_id',
'        , sbfl_process_name',
'        , sbfl_prcs_init_ts',
'        , sbfl_dgrm_id',
'        , sbfl_dgrm_name',
'        , sbfl_dgrm_version',
'        , sbfl_dgrm_status',
'        , sbfl_dgrm_category',
'        , sbfl_starting_object',
'        , sbfl_starting_object_name',
'        , sbfl_route',
'        , sbfl_route_name',
'        , sbfl_last_completed',
'        , sbfl_last_completed_name',
'        , sbfl_current',
'        , sbfl_current_name',
'        , sbfl_step_key',
'        , sbfl_scope',
'        , case sbfl_current_tag_name',
'            when ''bpmn:userTask'' then',
'              flow_usertask_pkg.get_url',
'              (',
'                pi_prcs_id  => sbfl_prcs_id',
'              , pi_sbfl_id  => sbfl_id',
'              , pi_objt_id  => sbfl_current_objt_id',
'              , pi_step_key => sbfl_step_key',
'              , pi_scope    => sbfl_scope',
'              )',
'            else null',
'          end link_text',
'        , sbfl_current_tag_name',
'        , sbfl_became_current',
'        , sbfl_last_update',
'        , sbfl_last_update_by',
'        , sbfl_status',
'        , sbfl_current_lane',
'        , sbfl_current_lane_name',
'        , sbfl_potential_users',
'        , sbfl_potential_groups',
'        , sbfl_excluded_users        ',
'        , sbfl_reservation',
'        , sbfl.sbfl_priority',
'        , sbfl.sbfl_due_on',
'        , prov.prov_var_vc2 as sbfl_business_ref',
'     from flow_subflows_vw sbfl',
'     left join flow_process_variables prov',
'        on prov.prov_prcs_id = sbfl.sbfl_prcs_id',
'       and prov.prov_var_name = ''BUSINESS_REF''',
'       and prov.prov_var_type = ''VARCHAR2'' ',
'       and prov.prov_scope = 0',
'    where sbfl_status = ''running''',
'with read only',
';',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_task_inbox_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Subflows currently at user tasks with assignment, priority, business reference, and rendered task link''',
'  )]'';',
'    execute immediate q''[alter view flow_task_inbox_vw modify (link_text annotations (add content ''Rendered HTML anchor linking to the current task APEX page''))]'';',
'    execute immediate q''[alter view flow_task_inbox_vw modify (sbfl_business_ref annotations (add content ''Business reference value from the BUSINESS_REF process variable''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_variable_event_timeline_vw as',
'with instance_dgrms as (',
'  select distinct prdg_prcs_id prcs_id, prdg_dgrm_id dgrm_id',
'  from flow_instance_diagrams',
')',
'select lgvr_prcs_id',
'     , lgvr_var_name',
'     , upper(lgvr_var_name) as lgvr_var_name_uc',
'     , lgvr_scope',
'     , lgvr_var_type',
'     , case',
'           when lgvr_var_vc2  is not null then lgvr_var_vc2',
'           when lgvr_var_num  is not null then cast(lgvr_var_num as varchar2(4000))',
'           when lgvr_var_date is not null then to_char(lgvr_var_date, v(''APP_DATE_TIME_FORMAT''))',
'           when lgvr_var_clob is not null then cast(dbms_lob.substr(lgvr_var_clob, 1000) as varchar2(4000))',
'           when lgvr_var_tstz is not null then to_char(lgvr_var_tstz, v(''NLS_TIMESTAMP_TZ_FORMAT''))',
'           when lgvr_var_json is not null then cast(dbms_lob.substr(lgvr_var_json, 1000) as varchar2(4000))',
'         end as  lgvr_var_value ',
'     , lgvr_objt_id',
'     , (select coalesce(objt_name, objt_bpmn_id) ',
'          from flow_objects objt',
'         where objt.objt_bpmn_id = lgvr_objt_id',
'           and objt.objt_dgrm_id in (select dgrm_id ',
'                                      from instance_dgrms ',
'                                     where prcs_id = lgvr_prcs_id)',
'       ) as lgvr_objt_name',
'     , lgvr_sbfl_id',
'     , lgvr_expr_set',
'     , lgvr_timestamp',
'     , lgvr_user',
'  from flow_variable_event_log',
'  order by lgvr_timestamp',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_variable_event_timeline_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''logging''',
'  , add content ''Timeline of variable assignments with object and scope context for audit and debugging''',
'  )]'';',
'    execute immediate q''[alter view flow_variable_event_timeline_vw modify (lgvr_var_name_uc annotations (add content ''Upper-case variable name for case-insensitive filtering''))]'';',
'    execute immediate q''[alter view flow_variable_event_timeline_vw modify (lgvr_var_value annotations (add content ''Current value of the variable retrieved as VARCHAR2''))]'';',
'    execute immediate q''[alter view flow_variable_event_timeline_vw modify (lgvr_objt_name annotations (add content ''Display name of the BPMN object that set the variable''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'/* ',
'-- Flows for APEX - flow_viewer_vw.sql',
'-- ',
'-- (c) Copyright Hyand Solutions GmbH, 2025.',
'--',
'-- Created    Apr-2025 Dennis Amthor, Hyand Solutions GmbH',
'--',
'-- NOTE THAT THIS VIEW HAS AN ENTERPRISE EDITION VERSION WHICH INCLUDES COMPLEX',
'-- PROCESSING TO GENERATE THE ITERATION_DATA COLUMN.',
'-- ANY CHANGES TO THIS VIEW SHOULD ALSO UPDATE THE ENTERPRISE EDITION VERSION IN ADDITION.',
'*/',
'create or replace view flow_viewer_vw',
'as',
'with all_completed as ( ',
'    select sflg.sflg_prcs_id as prcs_id',
'         , sflg.sflg_dgrm_id as dgrm_id',
'         , sflg.sflg_diagram_level as diagram_level',
'         , json_arrayagg(sflg.sflg_objt_id) as bpmn_ids',
'      from flow_subflow_log sflg',
'     where sflg.sflg_objt_id not in (   ',
'             select sbfl.sbfl_current',
'               from flow_subflows sbfl',
'              where sbfl.sbfl_prcs_id = sflg.sflg_prcs_id',
'                and sbfl.sbfl_diagram_level = sflg.sflg_diagram_level',
'                and sbfl.sbfl_current is not null',
'           )',
'     group by sflg.sflg_prcs_id',
'            , sflg.sflg_dgrm_id',
'            , sflg.sflg_diagram_level',
'), all_current as (',
'  select sbfl_prcs_id as prcs_id',
'       , sbfl_dgrm_id as dgrm_id',
'       , sbfl_diagram_level as diagram_level ',
'       , json_arrayagg(sbfl_current) as bpmn_ids',
'    from flow_subflows',
'   where sbfl_current is not null',
'   group by sbfl_prcs_id',
'          , sbfl_dgrm_id',
'          , sbfl_diagram_level',
'), all_errors as (',
'  select sbfl_prcs_id as prcs_id',
'       , sbfl_dgrm_id as dgrm_id',
'       , sbfl_diagram_level as diagram_level',
'       , json_arrayagg(sbfl_current) as bpmn_ids',
'    from flow_subflows',
'   where sbfl_current is not null',
'     and sbfl_status = ''error''',
'   group by sbfl_prcs_id',
'          , sbfl_dgrm_id',
'          , sbfl_diagram_level',
'), user_tasks as (',
'    select process_id as prcs_id',
'         , json_objectagg',
'           (',
'               key current_obj',
'               value details_link_target',
'               absent on null',
'               returning clob',
'           ) as user_task_urls',
'      from flow_apex_my_combined_task_list_vw',
'     group by process_id',
')',
'  select prcs.prcs_id',
'       , prdg.prdg_id',
'       , dgrm.dgrm_content',
'       , json_object',
'         (',
'           key ''current''   value acurr.bpmn_ids',
'         , key ''completed'' value acomp.bpmn_ids',
'         , key ''error''     value aerr.bpmn_ids',
'         ) as highlighting_data',
'       , json_object',
'         (',
'           key ''callingDiagramIdentifier'' value prdg.prdg_prdg_id',
'         , key ''callingObjectId''          value prdg.prdg_calling_objt',
'         , key ''breadcrumb''               value dgrm.dgrm_name || case when prdg.prdg_diagram_level is not null then '' ('' || prdg.prdg_diagram_level || '')'' else '''' end',
'         , key ''insight''                  value 1',
'         ) as call_activity_data',
'       , to_clob(null)       as iteration_data',
'       , usta.user_task_urls as user_task_data',
'       , to_clob(null)       as badges_data',
'    from flow_processes prcs',
'    join flow_instance_diagrams prdg',
'      on prdg.prdg_prcs_id = prcs.prcs_id',
'    join flow_diagrams dgrm',
'      on prdg.prdg_dgrm_id = dgrm.dgrm_id',
'    left join all_completed acomp',
'      on acomp.prcs_id = prcs.prcs_id',
'     and acomp.dgrm_id = dgrm.dgrm_id',
'     and acomp.diagram_level =  prdg.prdg_diagram_level',
'    left join all_current acurr',
'      on acurr.prcs_id = prcs.prcs_id',
'     and acurr.dgrm_id = dgrm.dgrm_id',
'     and acurr.diagram_level =  prdg.prdg_diagram_level',
'    left join all_errors aerr',
'      on aerr.prcs_id = prcs.prcs_id',
'     and aerr.dgrm_id = dgrm.dgrm_id',
'     and aerr.diagram_level =  prdg.prdg_diagram_level',
'    left join user_tasks usta',
'      on prcs.prcs_id = usta.prcs_id',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_viewer_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''BPMN viewer data with highlighting states, call activity relationships, and user task URLs for diagram visualisation''',
'  , add note    ''This view is intended for querying the data needed to render a single process diagram in a viewer. It is not intended for general querying across multiple instances or for other purposes. For more general querying of instance states,'
||' use the flow_instance_variables_vw, flow_instance_events_vw, and flow_instance_gateways_lov views instead.''',
'  )]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (prcs_id            annotations (add content ''Process instance identifier''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (prdg_id            annotations (add content ''Instance diagram record being visualised''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (dgrm_content       annotations (add content ''BPMN XML content for rendering in the viewer''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (highlighting_data  annotations (add content ''JSON structure defining current, completed, and error element highlighting''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (call_activity_data annotations (add content ''JSON structure describing call activity sub-process relationships''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (iteration_data     annotations (add content ''JSON structure describing loop and multi-instance iteration state''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (user_task_data     annotations (add content ''JSON structure with user task step keys and APEX page display data''))]'';',
'    execute immediate q''[alter view flow_viewer_vw modify (badges_data        annotations (add content ''JSON structure for count badge overlays on diagram elements''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'',
'create or replace view flow_p0002_diagrams_vw',
'as',
'  with instance_numbers as',
'  (',
'    select prdg_dgrm_id as dgrm_id',
'         , created_cnt',
'         , running_cnt',
'         , suspended_cnt',
'         , completed_cnt',
'         , terminated_cnt',
'         , error_cnt',
'         , created_cnt + running_cnt + suspended_cnt + completed_cnt + terminated_cnt + error_cnt as total_cnt ',
'      from (',
'             select prdg.prdg_dgrm_id',
'                  , prcs.prcs_status',
'               from flow_processes prcs',
'               join flow_instance_diagrams prdg',
'                 on prdg.prdg_prcs_id = prcs.prcs_id',
'           group by prcs.prcs_id, prdg.prdg_dgrm_id, prcs.prcs_status',
'           )',
'     pivot (',
'             count(*) for',
'               prcs_status in ( ''created'' created_cnt, ''running'' running_cnt, ''completed'' completed_cnt',
'                              , ''terminated'' terminated_cnt, ''error'' as error_cnt, ''suspended'' as suspended_cnt',
'                              )',
'           )',
'  )',
'    select d.dgrm_id',
'         , d.dgrm_name',
'         , d.dgrm_version',
'         , d.dgrm_status',
'         , d.dgrm_category',
'         , d.dgrm_last_update at time zone sessiontimezone as dgrm_last_update',
'         , null as btn',
'         , apex_page.get_url(p_page => 7, p_items => ''P7_DGRM_ID'', p_values => d.dgrm_id) as edit_link',
'         , apex_page.get_url(p_page => 11, p_items => ''P11_DGRM_ID'', p_values => d.dgrm_id) as create_instance_link',
'         , decode(inst_nums.total_cnt, 0, null, inst_nums.total_cnt) as instances ',
'         , case when not exists( select null from flow_objects objt where objt.objt_dgrm_id = d.dgrm_id ) then ''No'' else ''Yes'' end as diagram_parsed',
'         , case when not exists( select null from flow_objects objt where objt.objt_dgrm_id = d.dgrm_id ) then ''fa-times-circle-o fa-lg u-danger-text'' else ''fa-check-circle-o fa-lg u-success-text'' end as diagram_parsed_icon',
'         , dgrm_status_icon',
'         , nullif(inst_nums.created_cnt, 0) as instance_created',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',created'', p_clear_cache => ''RP,RIR'') as instance_created_link',
'         , nullif(inst_nums.running_cnt, 0) as instance_running',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',running'', p_clear_cache => ''RP,RIR'') as instance_running_link',
'         , nullif(inst_nums.suspended_cnt, 0) as instance_suspended',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',suspended'', p_clear_cache => ''RP,RIR'') as instance_suspended_link',
'         , nullif(inst_nums.completed_cnt, 0) as instance_completed',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',completed'', p_clear_cache => ''RP,RIR'') as instance_completed_link',
'         , nullif(inst_nums.terminated_cnt, 0) as instance_terminated',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',terminated'', p_clear_cache => ''RP,RIR'') as instance_terminated_link',
'         , nullif(inst_nums.error_cnt, 0) as instance_error',
'         , apex_page.get_url(p_page => 10, p_items => ''P10_FILTER_DGRM_ID,IR_PRCS_STATUS'', p_values => d.dgrm_id||'',error'', p_clear_cache => ''RP,RIR'') as instance_error_link',
'         , apex_item.checkbox2(p_idx => 1, p_value => d.dgrm_id, p_attributes => ''data-name = "'' || dgrm_name || ''" data-version = "'' || dgrm_version || ''"'') as checkbox',
'      from flow_diagrams_vw d',
' left join instance_numbers inst_nums',
'        on inst_nums.dgrm_id = d.dgrm_id',
'with read only',
';',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_p0002_diagrams_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''definition''',
'  , add content ''Diagram management list with per-status instance counts, parsed status, and navigation links for engine app page 2''',
'  )]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (btn annotations (add content ''Null placeholder for an inline action button''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (edit_link annotations (add content ''APEX URL to open the diagram in the editor (page 7)''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (create_instance_link annotations (add content ''APEX URL to create a new process instance from this diagram''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instances annotations (add content ''Total instance count across all statuses; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (diagram_parsed annotations (add content ''Yes/No indicator whether diagram objects have been parsed''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (diagram_parsed_icon annotations (add content ''FA icon CSS class indicating whether the diagram is parsed''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (dgrm_status_icon annotations (add content ''FA icon CSS class for the diagram status''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_created annotations (add content ''Count of created instances; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_created_link annotations (add content ''APEX URL filtered to created instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_running annotations (add content ''Count of running instances; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_running_link annotations (add content ''APEX URL filtered to running instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_suspended annotations (add content ''Count of suspended instances; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_suspended_link annotations (add content ''APEX URL filtered to suspended instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_completed annotations (add content ''Count of completed instances; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_completed_link annotations (add content ''APEX URL filtered to completed instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_terminated annotations (add content ''Count of terminated instances; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_terminated_link annotations (add content ''APEX URL filtered to terminated instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_error annotations (add content ''Count of instances in error state; null when zero''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (instance_error_link annotations (add content ''APEX URL filtered to error instances''))]'';',
'    execute immediate q''[alter view flow_p0002_diagrams_vw modify (checkbox annotations (add content ''APEX checkbox widget with diagram name and version data attributes''))]'';',
'  end if;',
'end;',
'/',
'',
'whenever sqlerror exit failure',
'',
'create or replace view flow_p0007_called_diagrams_vw',
'as',
'  with diagrams as',
'      (',
'         select dgrm.dgrm_id,',
'                null    as calling_dgrm,',
'                null    as calling_objt,',
'                dgrm.dgrm_name,',
'                dgrm.dgrm_version',
'           from flow_diagrams dgrm',
'         union all',
'         select dgrm.dgrm_id,',
'                objt.objt_dgrm_id as calling_dgrm,',
'                objt.objt_bpmn_id as calling_objt,',
'                dgrm.dgrm_name,',
'                dgrm.dgrm_version',
'           from flow_objects  objt',
'           join flow_diagrams dgrm',
'             on objt.objt_tag_name = ''bpmn:callActivity''',
'            and dgrm_id = flow_engine_app_api.get_current_diagram(',
'                   pi_dgrm_name           => objt.objt_attributes."apex"."calledDiagram",',
'                   pi_dgrm_calling_method => objt.objt_attributes."apex"."calledDiagramVersionSelection",',
'                   pi_dgrm_version        => objt.objt_attributes."apex"."calledDiagramVersion"',
'                )',
'      )',
'   select dgrm.dgrm_id,',
'          dgrm.calling_dgrm,',
'          dgrm.calling_objt,',
'          dgrm.dgrm_name,',
'          dgrm_version,',
'          connect_by_root(dgrm.dgrm_id) as root_dgrm,',
'          connect_by_iscycle as has_recursion,',
'          case when connect_by_iscycle = 1 then',
'            ''fa fa-exclamation-triangle-o fa-lg u-warning-text''',
'          end has_recursion_icon',
'     from diagrams dgrm',
'    start with dgrm.calling_dgrm is null',
'  connect by nocycle dgrm.calling_dgrm = prior dgrm.dgrm_id',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_p0007_called_diagrams_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''definition''',
'  , add content ''Diagram call hierarchy tree with recursion detection for engine app page 7''',
'  )]'';',
