'        , activity_bpmn_id',
'        , activity_name',
'        , activity_description',
'        , activity_grouping',
'        , activity_display_order',
'        , activity_tag_name',
'        , activity_is_repeatable',
'        , task_list_visibility',
'        , null as actions',
