'--',
'--',
'-- Created    15-Nov-2025  Richard Allen,  Flowquest Limited',
'-- Modified   06-Jun-2026  Richard Allen,  Flowquest Limited',
'',
'create or replace view flow_p0022_started_adhoc_activities_vw as',
'  select ahsf.ahsf_sbfl_id                             as  sbfl_id',
'       , ahsp.ahsp_prcs_id                             as  prcs_id ',
'       , ahsp.ahsp_dgrm_id                             as  dgrm_id',
'       , ahsp.ahsp_bpmn_id                             as  subproc_bpmn_id  ',
'       , ahsp.ahsp_sbfl_id                             as  subproc_sbfl_id ',
'       , ahsp.ahsp_step_key                            as  subproc_step_key',
'       , ahsf.ahsf_starting_object                     as  starting_object',
'       , (select coalesce(objt.objt_name, ahsf.ahsf_starting_object)',
'               from flow_objects objt',
'              where objt.objt_dgrm_id  = ahsp.ahsp_dgrm_id',
'                and objt.objt_bpmn_id  = ahsf.ahsf_starting_object)',
'                                                       as  starting_object_name',
'       , ahsf.ahsf_starting_step_key                   as  starting_step_key',
'       , ahsf.ahsf_repeat_count                        as  repeat_count',
'       , ahsf.ahsf_status                              as  status',
'       , case ahsf.ahsf_status',
'             when ''running'' then ''fa-play-circle-o''',
'             when ''created'' then ''fa-plus-circle-o''',
'             when ''completed'' then ''fa-check-circle-o''',
'             when ''terminated'' then ''fa-stop-circle-o''',
'             when ''suspended'' then ''fa-pause-circle-o''',
'             when ''error'' then ''fa-exclamation-circle-o''',
'             when ''split'' then ''fa fa-share-alt''',
'             when ''in subprocess'' then ''fa fa-share-alt''',
'             when ''in call activity'' then ''fa fa-share-alt''',
'             when ''in adhoc subprocess'' then ''fa fa-user-play''',
'             when ''waiting at gateway'' then ''fa fa-hand-stop-o''',
'             when ''waiting for timer'' then ''fa fa-clock-o''',
'             when ''waiting for event'' then ''fa fa-hand-stop-o''',
'             when ''waiting for approval'' then ''fa fa-question-square-o''',
'             when ''waiting for message'' then ''fa fa-envelope-o''',
'             when ''waiting iterations'' then ''fa fa-align-justify fa-rotate-90''',
'             when ''iterating'' then ''fa fa-align-justify fa-rotate-90''',
'             when ''delete on resume'' then ''fa fa-trash fam-pause fam-is-danger''',
'             when ''restart on resume'' then ''fa fa-pause-circle-o''',
'             when ''canceling task'' then ''fa fa-trash fam-play fam-is-danger''',
'         end as status_icon',
'       , ahsf.ahsf_start_time                          as  start_time',
'       , ahsf.ahsf_complete_time                       as  complete_time',
'       , json_query(ahsf.ahsf_inputs, ''$'' returning clob pretty)  as  inputs',
'       , json_query(ahsf.ahsf_outputs,''$'' returning clob pretty)  as  outputs',
'    from flow_adhoc_subflows ahsf',
'    join flow_adhoc_subprocs ahsp',
'      on ahsf.ahsf_ahsp_id = ahsp.ahsp_id',
'    join flow_objects objt',
'      on objt.objt_dgrm_id  = ahsp.ahsp_dgrm_id',
'     and objt.objt_bpmn_id  = ahsf.ahsf_starting_object',
'with read only;',
'',
'-- ---------------------------------------------------------------------------',
'-- Schema annotations (Oracle 23+ only; skipped on 19c/21c; idempotent - safe to re-run)',
'-- ---------------------------------------------------------------------------',
'declare',
'  l_major pls_integer := dbms_db_version.version;',
'begin',
'  if l_major >= 23 then',
'    execute immediate q''[alter view flow_p0022_started_adhoc_activities_vw annotations',
'  ( add app     ''Flows for APEX''',
'  , add type    ''runtime''',
'  , add content ''Started ad-hoc activities with inputs and outputs for engine app page 22''',
'  )]'';',
'  end if;',
'end;',
'/',
'/* ',
'-- Flows for APEX - flow_p0024_message_start_listeners_vw.sql',
'-- ',
'-- (c) Copyright Flowquest Limited and / or its affiliates, 2026.',
'--',
'-- Admin view of active message start listeners.',
'-- These are permanent subscriptions registered when a diagram is released,',
'-- acting as persistent listeners that start a new process instance when',
'-- a matching message is received (msub_callback = ''bpmn:startEvent'').',
'--',
'-- Created    31-May-2026  Richard Allen',
'*/',
'create or replace view flow_p0024_message_start_listeners_vw',
'as',
'   select mes.msub_id,',
'          mes.msub_message_name,',
'          mes.msub_key_name,',
'          mes.msub_callback_par        as msub_start_event_bpmn_id,',
'          mes.msub_payload_var,',
'          mes.msub_created,',
'          dgrm.dgrm_id,',
'          dgrm.dgrm_name,',
'          dgrm.dgrm_version,',
'          dgrm.dgrm_category,',
'          dgrm.dgrm_icon',
'     from flow_message_subscriptions_vw mes',
'     join flow_diagrams                 dgrm on dgrm.dgrm_id = mes.msub_dgrm_id',
'    where mes.msub_callback = ''bpmn:startEvent''',
'with read only;',
''))
);
end;
/
prompt --application/deployment/install/install_packages_bodies
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_install_id=>wwv_flow_imp.id(30210531648852655)
,p_name=>'Packages Bodies'
,p_sequence=>40
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'create or replace package body flow_admin_api as',
' /* Flows for APEX - flow_admin_api.pkb',
'--',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'--',
'-- Created    11-Feb-2023   Richard Allen, Oracle',
'*/',
' /**',
'FLOWS FOR APEX ADMIN API',
'=========================',
'',
'The `flow_admin_api` package gives you access to the Flows for APEX engine admin procedures, and allows you to perform:',
'-  Maintenance, Archiving and Purging of the Flows for APEX log files',
'-  Maintenance, Archiving, and Purging of the Flows for APEX performance statistics all_summaries',
'- Maintenance of Flows for APEX instance configuration parameters',
'',
'*/',
'-- Log File Functions',
'  procedure purge_instance_logs',
'  ( p_retention_period_days  in number default null',
'  ) ',
'  is',
'  begin',
'    flow_log_admin.purge_instance_logs ',
'    ( p_retention_period_days => p_retention_period_days ',
'    );',
'  end purge_instance_logs;',
'',
'  function instance_summary',
'  ( p_process_id        in flow_processes.prcs_id%type',
'  ) return clob',
'  is',
'  begin',
'    return flow_log_admin.get_instance_json_summary ( p_process_id => p_process_id);',
'  end instance_summary;',
'',
'  procedure archive_completed_instances',
'  ( p_completed_before         in date default trunc(sysdate)',
'  )',
'  is',
'      l_session_id   number;',
'    begin  ',
'        if v(''APP_SESSION'') is null then',
'          l_session_id := flow_apex_session.create_api_session(p_process_id => null);',
'        end if;',
'',
'        flow_log_admin.archive_completed_instances',
'        ( p_completed_before         => p_completed_before',
'        );',
'',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'    exception',
'      when others then',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;      ',
'  end archive_completed_instances;',
'',
'-- Performance Summary Functions',
'',
'  procedure run_daily_stats',
'  is',
'  begin',
'    flow_statistics.run_daily_stats;',
'  end run_daily_stats;',
'',
'',
'  procedure purge_statistics',
'  is',
'  begin',
'    flow_statistics.purge_statistics;',
'  end purge_statistics;',
'',
'  -- Configuration Parameters',
'',
'  procedure set_config_value',
'  ( p_config_key        in flow_configuration.cfig_key%type,',
'    p_value             in flow_configuration.cfig_value%type,',
'    p_update_if_set     in boolean default true',
'  )',
'  is',
'  begin',
'    flow_engine_util.set_config_value',
'    ( p_config_key      => p_config_key',
'    , p_value           => p_value',
'    , p_update_if_set   => p_update_if_set',
'    );',
'  end set_config_value;',
'',
'  function get_config_value',
'  ( p_config_key        in flow_configuration.cfig_key%type',
'  , p_default_value     in flow_configuration.cfig_value%type',
'  ) return flow_configuration.cfig_value%type',
'  is',
'  begin',
'    return flow_engine_util.get_config_value ( p_config_key     => p_config_key ',
'                                             , p_default_value  => p_default_value',
'                                             );       ',
'  end get_config_value;',
'',
'  -- Diagram Release',
'',
'  procedure release_diagram',
'  ( pi_dgrm_name    in flow_diagrams.dgrm_name%type,',
'    pi_dgrm_version in flow_diagrams.dgrm_version%type default ''0'' ',
'  )',
'  is',
'  begin ',
'    flow_diagram.release_diagram',
'    ( pi_dgrm_name    => pi_dgrm_name',
'    , pi_dgrm_version => pi_dgrm_version',
'    );',
'  end release_diagram;',
'',
'  -- suspend process instance (requires EE)',
'',
'  procedure suspend_process',
'  ( p_process_id  in flow_processes.prcs_id%type',
'  , p_comment     in flow_instance_event_log.lgpr_comment%type default null',
'  )',
'  is',
'    l_session_id   number;',
'  begin  ',
'    if v(''APP_SESSION'') is null then',
'      l_session_id := flow_apex_session.create_api_session (p_process_id => p_process_id);',
'    end if;',
'',
'    flow_instances.suspend_process ( p_process_id => p_process_id',
'                                   , p_comment    => p_comment',
'                                   );',
'',
'    if l_session_id is not null then',
'      flow_apex_session.delete_session (p_session_id => l_session_id );',
'    end if;',
'  exception',
'      when others then',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;',
'  end suspend_process;',
'',
'  -- resume process instance (requires EE)',
'',
'  procedure resume_process',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_comment       in flow_instance_event_log.lgpr_comment%type default null',
'  )',
'  is',
'    l_session_id   number;',
'  begin  ',
'    if v(''APP_SESSION'') is null then',
'      l_session_id := flow_apex_session.create_api_session (p_process_id => p_process_id);',
'    end if;',
'',
'    flow_instances.resume_process  ( p_process_id => p_process_id',
'                                   , p_comment    => p_comment',
'                                   );',
'',
'    if l_session_id is not null then',
'      flow_apex_session.delete_session (p_session_id => l_session_id );',
'    end if;',
'  exception',
'      when others then',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;',
'  end resume_process;',
'',
'  procedure mark_subflow_for_deletion',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , p_comment       in flow_instance_event_log.lgpr_comment%type default null',
'  )',
'  is',
'    l_session_id   number;  ',
'  begin',
'',
