'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;',
'  end flow_force_next_step;',
'',
'  procedure set_process_logging_level',
'  ( p_process_id     in flow_processes.prcs_id%type',
'  , p_logging_level  in flow_processes.prcs_logging_level%type',
'  )',
'  is',
'    l_session_id   number;',
'  begin     ',
'    if v(''APP_SESSION'') is null then',
'      l_session_id := flow_apex_session.create_api_session (p_process_id => p_process_id);',
'    end if;   ',
'',
'    flow_instances.set_logging_level ( p_process_id     => p_process_id',
'                                    , p_logging_level  => p_logging_level',
'                                    );',
'    if l_session_id is not null then',
'      flow_apex_session.delete_session (p_session_id => l_session_id );',
'    end if;   ',
'  exception',
'      when others then',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;',
'  end set_process_logging_level;',
'',
'  function test_ai_connection',
'  ( p_ai_interface   in varchar2',
'  , p_ai_service     in varchar2 default null',
'  , p_ai_provider    in varchar2 default null',
'  , p_ai_model       in varchar2 default null',
'  , p_prompt         in clob default ''Hello AI World''',
'  ) return clob',
'  is',
'    e_feature_requires_ee exception;',
'    l_result          clob;',
'    l_error_response  sys.json_object_t;',
'  begin',
'  $IF flow_apex_env.ee $THEN',
'    l_result :=',
'      flow_admin_api_ee.test_ai_connection',
'      (',
'        p_ai_interface => p_ai_interface',
'      , p_ai_service   => p_ai_service',
'      , p_ai_provider  => p_ai_provider',
'      , p_ai_model     => p_ai_model',
'      , p_prompt       => p_prompt',
'      );',
'    return l_result;',
'  $ELSE',
'    raise e_feature_requires_ee;',
'  $END',
'  exception',
'    when e_feature_requires_ee then',
'      l_error_response := sys.json_object_t();',
'      l_error_response.put(''success'', false);',
'      l_error_response.put(''aiInterface'', p_ai_interface);',
'      l_error_response.put(''errorCode'', -20001);',
'      l_error_response.put(''errorMessage'', apex_lang.message(''feature-requires-ee''));',
'      return l_error_response.to_clob;',
'    when others then',
'      l_error_response := sys.json_object_t();',
'      l_error_response.put(''success'', false);',
'      l_error_response.put(''aiInterface'', p_ai_interface);',
'      l_error_response.put(''errorCode'', sqlcode);',
'      l_error_response.put(''errorMessage'', apex_lang.message(''ai-connection-error''));',
'      -- $F4AMESSAGE ''ai-connection-error'' || ''AI connection definition incorrect - check your configuration''',
'      return l_error_response.to_clob;',
'  end test_ai_connection;',
'',
'end flow_admin_api;',
'/',
'',
'create or replace package body flow_apex_session',
'as',
'',
'  type t_session_parameters    is record ',
'  ( app_id          flow_types_pkg.t_bpmn_attribute_vc2',
'  , page_id         flow_types_pkg.t_bpmn_attribute_vc2',
'  , username        flow_types_pkg.t_bpmn_attribute_vc2',
'  , business_admin  flow_types_pkg.t_bpmn_attribute_vc2',
'  );',
'  e_apex_session_missing_param        exception;',
'  e_apex_session_multiple_processes   exception;',
'',
'  function get_session_parameters ',
'  ( p_dgrm_id         flow_diagrams.dgrm_id%type default null',
'  , p_process_bpmn_id flow_objects.objt_bpmn_id%type default null',
'  )',
'  return t_session_parameters',
'  as',
'    l_var_value             flow_subflows.sbfl_current%type;',
'    l_session_parameters    t_session_parameters;',
'  begin',
'    -- null dgrm_id case is for running archives - no process or diagram is running',
'    if p_dgrm_id is not null then',
'      begin',
'        -- get the session parameters from the process diagram using process_bpmn_id',
'        -- if process_bpmn_id is null (processes started with 24.1 or earlier), then get the session ',
'        --    parameters from the first bpmn:process in the diagram',
'        -- first the new (25.1) way...',
'        select jt.app_id',
'             , jt.page_id',
'             , jt.username',
'             , jt.business_admin',
'          into l_session_parameters',
'          from flow_objects objt',
'             , json_table( objt.objt_attributes, ''$.apex''',
'                 columns',
'                   app_id         varchar2(4000) path ''$.applicationId''',
'                 , page_id        varchar2(4000) path ''$.pageId''',
'                 , username       varchar2(4000) path ''$.username''',
'                 , business_admin varchar2(4000) path ''$.businessAdmin''',
'               ) jt',
'         where objt.objt_dgrm_id  = p_dgrm_id',
'           and objt.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'           and objt.objt_bpmn_id  = p_process_bpmn_id',
'        ;',
'      exception',
'        when too_many_rows then',
'          apex_debug.info ( p_message => ''flow_apex_session - multiple bpmn:process events found in model.  Multiple not yet supported.  raising Error'');',
'          raise e_apex_session_multiple_processes;',
'          /* Note for future:  Session information is available from bpmn:process in diagram.  We currently support bpmn:process or bpmn:collaboration as the top ',
'          level in the XML but dont create a flow_object for the collaboration object.   So top level is the bpmn:participation.',
'          when we support collaboration properly (i.e., support message flow between participations), this code will need to be revisited.',
'          */',
'        when no_data_found then',
'          apex_debug.info ( p_message => ''flow_apex_session - no session parameters found from diagram.'');',
'          begin',
'            -- try the old way...',
'            select jt.app_id',
'                 , jt.page_id',
'                 , jt.username',
'                 , jt.business_admin',
'              into l_session_parameters',
'              from flow_objects objt',
'                 , json_table( objt.objt_attributes, ''$.apex''',
'                     columns',
'                       app_id         varchar2(4000) path ''$.applicationId''',
'                     , page_id        varchar2(4000) path ''$.pageId''',
'                     , username       varchar2(4000) path ''$.username''',
'                     , business_admin varchar2(4000) path ''$.businessAdmin''',
'                   ) jt',
'             where objt.objt_dgrm_id  = p_dgrm_id',
'               and objt.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'            fetch first 1 row only;',
'          exception',
'            when no_data_found then',
'              apex_debug.info ( p_message => ''flow_apex_session - no session parameters found from diagram.'');',
'          end;',
'      end;',
'    end if;',
'',
'',
'    if (  l_session_parameters.app_id is null',
'       or l_session_parameters.page_id is null ',
'       or l_session_parameters.username is null',
'       ) then',
'      -- attribute not set at process diagram level - try system config',
'      l_session_parameters.app_id   := flow_engine_util.get_config_value ',
'                        ( p_config_key    => flow_constants_pkg.gc_config_default_application',
'                        , p_default_value => null',
'                        );',
'      l_session_parameters.page_id  := flow_engine_util.get_config_value ',
'                        ( p_config_key    => flow_constants_pkg.gc_config_default_pageid ',
'                        , p_default_value => null',
'                        );',
'      l_session_parameters.username := flow_engine_util.get_config_value ',
'                        ( p_config_key    => flow_constants_pkg.gc_config_default_username',
'                        , p_default_value => null',
'                        );',
'    end if;',
'',
'    -- do this separately for apex_business_admin for upwards compatibility reasons...l_session_parameters',
'    if l_session_parameters.business_admin is null then',
'      l_session_parameters.business_admin := flow_engine_util.get_config_value ',
'                        ( p_config_key    => flow_constants_pkg.gc_config_default_apex_business_admin',
'                        , p_default_value => null',
'                        );',
'    end if;',
'  ',
'',
'    if (  l_session_parameters.app_id is null',
'       or l_session_parameters.page_id is null ',
'       or l_session_parameters.username is null',
'       ) then',
'      -- attribute not set at system config level - throw error   ',
'      raise e_apex_session_missing_param;',
'    end if;',
'    return l_session_parameters;',
'  end get_session_parameters;',
'',
'  procedure set_async_proc_vars',
'  ( p_process_id         in flow_processes.prcs_id%type',
'  , p_subflow_id         in flow_subflows.sbfl_id%type',
'  )',
'  is ',
'    l_current                flow_subflows.sbfl_current%type;',
'    l_sbfl_dgrm_id           flow_subflows.sbfl_dgrm_id%type;',
'    l_session_parameters     t_session_parameters;',
'    l_timer_scope            flow_subflows.sbfl_scope%type;   ',
'  begin',
'    -- get the current object (and scope) as timer object name',
'    select sbfl.sbfl_current',
'         , sbfl.sbfl_dgrm_id',
'         , sbfl.sbfl_scope',
'      into l_current',
'         , l_sbfl_dgrm_id',
'         , l_timer_scope',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id      = p_subflow_id',
'    ;',
'    -- check if required process variables exist in current scope ',
'    if flow_proc_vars_int.get_var_vc2 ( pi_prcs_id  => p_process_id',
'                                     , pi_var_name => l_current || '':'' || flow_constants_pkg.gc_async_parameter_applicationId',
'                                     , pi_scope    => l_timer_scope',
'                                     ) is null  ',
'    or flow_proc_vars_int.get_var_vc2 ( pi_prcs_id  => p_process_id',
'                                     , pi_var_name => l_current || '':'' || flow_constants_pkg.gc_async_parameter_pageId',
'                                     , pi_scope    => l_timer_scope',
'                                     ) is null',
'    or flow_proc_vars_int.get_var_vc2 ( pi_prcs_id  => p_process_id',
'                                     , pi_var_name => l_current || '':'' || flow_constants_pkg.gc_async_parameter_username',
'                                     , pi_scope    => l_timer_scope',
'                                     ) is null',
'    then',
'      l_session_parameters := get_session_parameters (p_dgrm_id => l_sbfl_dgrm_id);',
'',
'      flow_proc_vars_int.set_var',
'          ( pi_prcs_id      => p_process_id',
'          , pi_var_name     => l_current || '':'' || flow_constants_pkg.gc_async_parameter_applicationId',
'          , pi_scope        => l_timer_scope',
'          , pi_vc2_value    => l_session_parameters.app_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_objt_bpmn_id => l_current',
'          );',
'      flow_proc_vars_int.set_var',
'          ( pi_prcs_id      => p_process_id',
'          , pi_var_name     => l_current || '':'' || flow_constants_pkg.gc_async_parameter_pageId',
'          , pi_scope        => l_timer_scope',
'          , pi_vc2_value    => l_session_parameters.page_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_objt_bpmn_id => l_current',
'          );',
'      flow_proc_vars_int.set_var',
'          ( pi_prcs_id      => p_process_id',
'          , pi_var_name     => l_current || '':'' || flow_constants_pkg.gc_async_parameter_username',
'          , pi_scope        => l_timer_scope',
'          , pi_vc2_value    => l_session_parameters.username',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_objt_bpmn_id => l_current',
'          );',
'    end if;',
'  exception',
'      when e_apex_session_multiple_processes then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''apex-task-multiple-process''',
'          );',
'          -- F4A$MESSAGE ''apex-task-multiple-process'' || ''Error creating APEX session.  BPMN diagram contains multiple Process objects.''',
'      when e_apex_session_missing_param then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''apex-session-params-not-set''',
'          , p0              => l_current',
'          );',
'          -- $F4AMESSAGE ''apex-session-params-not-set'' || ''Asynchronous connection details for timer %0 need to be set in process variables, diagram async connection details, or system config details.'' ',
'  end set_async_proc_vars;',
'',
' function create_async_session',
'  ( p_process_id         in flow_processes.prcs_id%type',
'  , p_subflow_id         in flow_subflows.sbfl_id%type',
'  ) return number',
'  is ',
'    l_timer_name             flow_subflows.sbfl_current%type;',
'    l_timer_scope            flow_subflows.sbfl_scope%type;',
'    l_app_id                 flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_page_id                flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_username               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_session_id             number;',
'  begin',
'    flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'    -- get the current object (and scope) as timer object name',
'    select sbfl.sbfl_current',
'         , sbfl.sbfl_scope',
'      into l_timer_name',
'         , l_timer_scope',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id      = p_subflow_id',
'    ;',
'    -- get async process variable details ',
'    l_username  := flow_proc_vars_int.get_var_vc2',
'                      ( pi_prcs_id   => p_process_id',
'                      , pi_var_name  => l_timer_name || '':'' || flow_constants_pkg.gc_async_parameter_username',
'                      , pi_scope     => l_timer_scope',
'                      );',
'    l_app_id    := flow_proc_vars_int.get_var_vc2',
'                      ( pi_prcs_id   => p_process_id',
'                      , pi_var_name  => l_timer_name || '':'' || flow_constants_pkg.gc_async_parameter_applicationId',
'                      , pi_scope     => l_timer_scope',
'                      );',
'    l_page_id   := flow_proc_vars_int.get_var_vc2',
'                      ( pi_prcs_id   => p_process_id',
'                      , pi_var_name  => l_timer_name || '':'' || flow_constants_pkg.gc_async_parameter_pageId',
'                      , pi_scope     => l_timer_scope',
'                      );         ',
'    -- check all process variables are set in case they have been deleted since timer was set',
'    if l_username is null then',
'      flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''async-no-username''',
'          , p0              => l_timer_name',
'          );',
'          -- $F4AMESSAGE ''async-no-username'' || ''Unable to create asyncronous connection for object %0.  Username needs to be specified in process variable, the process diagram, or system configuration.''',
'    end if;',
'    if l_app_id is null then',
'      flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''async-no-appid''',
'          , p0              => l_timer_name',
'          );',
'          -- $F4AMESSAGE ''async-no-appid'' || ''Unable to create asyncronous connection for object %0.  Application ID needs to be specified in process variable, the process diagram, or system configuration.''',
'    end if;',
'    if l_page_id is null then',
'      flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''async-no-pageid''',
'          , p0              => l_timer_name',
'          );',
'          -- $F4AMESSAGE ''async-no-pageid'' || ''Unable to create asyncronous connection for object %0.  Page ID needs to be specified in process variable, the process diagram, or system configuration.''',
'    end if;',
'    -- create apex session',
'    begin',
'      apex_session.create_session ',
'        ( p_app_id   => l_app_id',
'        , p_page_id  => l_page_id',
'        , p_username => l_username ',
'        );',
'    exception',
'      when flow_constants_pkg.ge_invalid_session_params then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_process_id'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'          , pi_sbfl_id      => p_subflow_id',
'          , pi_message_key  => ''async-invalid_params''',
'          , p0              => l_timer_name',
'          );',
'          -- $F4AMESSAGE ''async-invalid_params'' || ''Unable to create asyncronous connection for object %0.  Username not valid in specified Application''',
'          raise flow_constants_pkg.ge_invalid_session_params;',
'    end;',
'    return v(''APP_SESSION'');',
'  end create_async_session;',
'',
' function create_api_session',
'  ( p_dgrm_id            in flow_diagrams.dgrm_id%type default null',
'  , p_prcs_id            in flow_processes.prcs_id%type default null',
'  , p_process_bpmn_id    in flow_objects.objt_bpmn_id%type default null',
'  ) return number',
'  is ',
'    l_session_id             number;',
'    l_session_parameters     t_session_parameters;',
'    l_username               flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    -- get session parameters from process diagram or system config',
'    l_session_parameters := get_session_parameters ( p_dgrm_id          => p_dgrm_id, ',
'                                                     p_process_bpmn_id  => p_process_bpmn_id);',
'  ',
'    -- create apex session',
'    begin',
'      apex_session.create_session ',
'        ( p_app_id   => l_session_parameters.app_id',
'        , p_page_id  => l_session_parameters.page_id',
'        , p_username => l_session_parameters.username ',
'        );',
'    exception',
'      when flow_constants_pkg.ge_invalid_session_params then',
'        if p_prcs_id is not null then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_prcs_id',
'          , pi_message_key  => ''async-invalid_params''',
'          , p0              => ''API Call''',
'          );',
'          -- $F4AMESSAGE ''async-invalid_params'' || ''Unable to create asyncronous connection for object %0.  Username not valid in specified Application''',
'          raise flow_constants_pkg.ge_invalid_session_params;',
'        else',
'          flow_errors.handle_general_error',
'          ( pi_message_key  => ''async-invalid_params''',
'          , p0 => ''Default Parameters in Configurations''',
'          );',
'          -- $F4AMESSAGE ''async-invalid_params'' || ''Unable to create asyncronous connection for object %0.  Username not valid in specified Application''',
'          raise flow_constants_pkg.ge_invalid_session_params;',
'        end if;',
'    end;',
'    return v(''APP_SESSION'');',
'  end create_api_session;',
'',
'  function create_api_session',
'  ( p_subflow_id         in flow_subflows.sbfl_id%type',
'  ) return number',
'  is ',
'    l_dgrm_id         flow_diagrams.dgrm_id%type;',
'    l_prcs_id         flow_processes.prcs_id%type;',
'    l_process_bpmn_id flow_objects.objt_bpmn_id%type;',
'  begin',
'    select sbfl.sbfl_dgrm_id',
'         , sbfl.sbfl_prcs_id',
'         , prcs.prcs_process_bpmn_id',
'      into l_dgrm_id',
'         , l_prcs_id',
'         , l_process_bpmn_id',
'      from flow_subflows sbfl',
'      join flow_processes prcs',
'        on sbfl.sbfl_prcs_id = prcs.prcs_id',
'     where sbfl.sbfl_id = p_subflow_id',
'    ;',
'    return create_api_session ( p_dgrm_id => l_dgrm_id',
'                              , p_prcs_id => l_prcs_id',
'                              , p_process_bpmn_id => l_process_bpmn_id',
'                              );',
'  end create_api_session;',
'',
'  function create_api_session',
'  ( p_process_id         in flow_processes.prcs_id%type',
'  ) return number',
'  is ',
'    l_dgrm_id         flow_diagrams.dgrm_id%type;',
'    l_process_bpmn_id flow_objects.objt_bpmn_id%type;',
'  begin',
'    select prcs.prcs_dgrm_id',
'         , prcs.prcs_process_bpmn_id',
'      into l_dgrm_id',
'         , l_process_bpmn_id',
'      from flow_processes prcs',
'     where prcs.prcs_id = p_process_id',
'    ;',
'    return create_api_session ( p_dgrm_id => l_dgrm_id',
'                              , p_prcs_id => p_process_id',
'                              , p_process_bpmn_id => l_process_bpmn_id',
'                              );',
'  end create_api_session;',
'',
'  function create_api_session',
'  ( p_function          in varchar2',
'  ) return number',
'  is ',
'    l_dgrm_id      flow_diagrams.dgrm_id%type;',
'  begin',
'    if p_function = ''archive'' then ',
'      return create_api_session (p_prcs_id => null, p_dgrm_id => null, p_process_bpmn_id => null);',
'    else',
'      return null;',
'    end if;',
'  end create_api_session;',
'',
'  procedure delete_session',
'  ( p_session_id         in number)',
'  is ',
'  begin',
'    apex_session.delete_session ( p_session_id => p_session_id);',
'  end;',
'',
'end flow_apex_session;',
'/',
'',
'create or replace package body flow_api_pkg as',
'/* ',
'-- Flows for APEX - flow_api_pkg.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG. 2020-22',
'-- (c) Flowquest Limited and / or its affiliates, 2025.',
'--',
'-- Created    20-Jun-2020   Moritz Klein, MT AG ',
'-- Modified   01-May-2022   Richard Allen, Oracle',
'-- Modified   02-Mar-2025   Richard Allen, Flowquest',
'-- ',
'*/',
'',
'  e_lock_timeout exception;',
'  pragma exception_init (e_lock_timeout, -3006);',
'',
'  function get_dgrm_name',
'  (',
'    p_prcs_id in flow_processes.prcs_id%type',
'  ) return varchar2',
'  is',
'    l_dgrm_name flow_diagrams.dgrm_name%type;',
'  begin',
'',
'    select dgrm.dgrm_name',
'      into l_dgrm_name',
'      from flow_processes prcs',
'      join flow_diagrams dgrm',
'        on dgrm.dgrm_id = prcs.prcs_dgrm_id',
'     where prcs.prcs_id = p_prcs_id',
'    ;',
'         ',
'    return l_dgrm_name;',
'  end get_dgrm_name;',
'',
'  function flow_create',
'  (',
'    pi_dgrm_name in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version in flow_diagrams.dgrm_version%type default null',
'  , pi_prcs_name in flow_processes.prcs_name%type default null',
'  , pi_logging_level in flow_processes.prcs_logging_level%type default null',
'  , pi_auto_commit in boolean default true',
'  ) return flow_processes.prcs_id%type',
'  as',
'    l_dgrm_id         flow_diagrams.dgrm_id%type;',
'    l_dgrm_version    flow_diagrams.dgrm_version%type;',
'    l_calling_method  flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'  ',
'    if pi_dgrm_version is null then',
'      -- this is the former way of calling the latest release',
'      l_calling_method := flow_constants_pkg.gc_dgrm_version_latest_version;',
'    else',
'      -- dgrm_version was specified - use ''namedVersion'' call...                                                      ',
'      l_calling_method := flow_constants_pkg.gc_dgrm_version_named_version;',
'    end if;',
'',
'    -- get the released diagram or ''draft'' version ''0'' diagram (or error...)',
'    l_dgrm_id := flow_diagram.get_current_diagram ( pi_dgrm_name            => pi_dgrm_name ',
'                                                  , pi_dgrm_calling_method  => l_calling_method',
'                                                  , pi_dgrm_version         => pi_dgrm_version',
'                                                  );',
'',
'    -- TODO - Get the Logging level from the diagram, then start the process with the greatest logging level',
'',
'    return  flow_instances.create_process',
'            ( p_dgrm_id       => l_dgrm_id',
'            , p_prcs_name     => pi_prcs_name',
'            , p_logging_level => pi_logging_level',
'            , p_auto_commit   => pi_auto_commit',
'            );',
'  end flow_create;',
'',
'  function flow_create',
'  (',
'    pi_dgrm_id       in flow_diagrams.dgrm_id%type',
'  , pi_prcs_name     in flow_processes.prcs_name%type default null',
'  , pi_logging_level in flow_processes.prcs_logging_level%type default null',
'  , pi_auto_commit   in boolean default true',
'  ) return flow_processes.prcs_id%type',
'  is',
'    l_ret flow_processes.prcs_id%type;',
'  begin',
'    return flow_instances.create_process',
'           ( p_dgrm_id => pi_dgrm_id',
'           , p_prcs_name => pi_prcs_name',
'           , p_logging_level => pi_logging_level',
'           , p_auto_commit => pi_auto_commit',
'           )',
'    ;',
'  end flow_create;',
'',
'  procedure flow_create',
'  (',
'    pi_dgrm_name     in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version  in flow_diagrams.dgrm_version%type default null',
'  , pi_prcs_name     in flow_processes.prcs_name%type default null',
'  , pi_logging_level in flow_processes.prcs_logging_level%type default null',
'  , pi_auto_commit   in boolean default true',
'  )',
'  as',
'    l_prcs_id flow_processes.prcs_id%type;',
'  begin',
'    l_prcs_id :=',
'      flow_create',
'      (',
'        pi_dgrm_name     => pi_dgrm_name',
'      , pi_dgrm_version  => pi_dgrm_version',
'      , pi_prcs_name     => pi_prcs_name',
'      , pi_logging_level => pi_logging_level',
'      , pi_auto_commit   => pi_auto_commit',
'      );',
'  end flow_create;',
'',
'  procedure flow_create',
'  (',
'    pi_dgrm_id       in flow_diagrams.dgrm_id%type',
'  , pi_prcs_name     in flow_processes.prcs_name%type default null',
'  , pi_logging_level in flow_processes.prcs_logging_level%type default null',
'  , pi_auto_commit   in boolean default true',
'  )',
'  as',
'    l_prcs_id flow_processes.prcs_id%type;',
'  begin',
'    l_prcs_id :=',
'      flow_instances.create_process',
'      (',
'        p_dgrm_id       => pi_dgrm_id',
'      , p_prcs_name     => pi_prcs_name',
'      , p_logging_level => pi_logging_level',
'      , p_auto_commit   => pi_auto_commit',
'      );',
'  end flow_create;',
'',
'  procedure flow_start',
'    ( p_process_id in flow_processes.prcs_id%type',
'    )',
'    is',
'      l_session_id   number;',
'    begin  ',
'        if v(''APP_SESSION'') is null then',
'          l_session_id := flow_apex_session.create_api_session (p_process_id => p_process_id);',
'        end if;',
'',
'        apex_debug.message(p_message => ''Begin flow_start'', p_level => 3) ;',
'',
'        flow_globals.set_context',
'        ( pi_prcs_id => p_process_id',
'        , pi_scope   => 0   -- initial scope is always 0',
'        );',
'  ',
'        flow_instances.start_process ',
'        ( p_process_id => p_process_id',
'        );',
'',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'    exception',
'      when others then',
'        if l_session_id is not null then',
'          flow_apex_session.delete_session (p_session_id => l_session_id );',
'        end if;',
'        raise;',
'  end flow_start;',
'',
'  procedure flow_set_priority ',
'  ( p_process_id in flow_processes.prcs_id%type',
'  , p_priority   in flow_processes.prcs_priority%type ',
'  )',
