'',
'  function get_current_usertask_url',
'  (',
'    p_process_id in flow_processes.prcs_id%type',
'  , p_subflow_id in flow_subflows.sbfl_id%type',
'  , p_step_key   in flow_subflows.sbfl_step_key%type default null',
'  , p_scope      in flow_subflows.sbfl_scope%type default 0',
'  ) return varchar2',
'  as',
'    l_objt_id flow_objects.objt_id%type;',
'  begin',
'    apex_debug.trace ( p_message => ''Entering GET_CURRENT_USERTASK_URL'' );',
'',
'    select objt.objt_id',
'      into l_objt_id',
'      from flow_subflows sbfl',
'      join flow_processes prcs',
'        on prcs.prcs_id = sbfl.sbfl_prcs_id',
'      join flow_objects objt',
'        on objt.objt_dgrm_id = prcs.prcs_dgrm_id',
'       and objt.objt_bpmn_id = sbfl.sbfl_current',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id = p_subflow_id',
'       and objt.objt_tag_name in ( flow_constants_pkg.gc_bpmn_usertask',
'                                 , flow_constants_pkg.gc_bpmn_adhoc_subprocess )',
'    ;',
'',
'    apex_debug.trace( p_message => ''Found OBJT_ID %s'', p0 => l_objt_id );',
'',
'    return ',
'      flow_usertask_pkg.get_url',
'      (',
'        pi_prcs_id  => p_process_id',
'      , pi_sbfl_id  => p_subflow_id',
'      , pi_step_key => p_step_key',
'      , pi_objt_id  => l_objt_id',
'      , pi_scope    => p_scope',
'      );',
'  end get_current_usertask_url;',
'',
'  function message',
'  ( p_message_key    in varchar2',
'  , p_lang            in varchar2 default ''en''',
'  , p0                in varchar2 default null',
'  , p1                in varchar2 default null',
'  , p2                in varchar2 default null',
'  , p3                in varchar2 default null',
'  , p4                in varchar2 default null',
'  , p5                in varchar2 default null',
'  , p6                in varchar2 default null',
'  , p7                in varchar2 default null',
'  , p8                in varchar2 default null',
'  , p9                in varchar2 default null',
'  ) return varchar2',
'  is',
'  begin',
'    return flow_errors.make_error_message',
'           ( pi_message_key => p_message_key',
'           , pi_lang        => p_lang',
'           , p0   => p0',
'           , p1   => p1',
'           , p2   => p2',
'           , p3   => p3',
'           , p4   => p4',
'           , p5   => p5',
'           , p6   => p6',
'           , p7   => p7',
'           , p8   => p8',
'           , p9   => p9',
'           );',
'',
'  end message;',
'',
'  function get_tasks ',
'  ( p_context      in varchar2',
'  , p_prcs_id      in flow_processes.prcs_id%type',
'  , p_user         in varchar2 default null ',
'  , p_groups       in varchar2 default null',
'  )',
'  return sys_refcursor',
'  is',
'    l_cur     sys_refcursor;',
'    l_user    varchar2(250);',
'  begin ',
'    l_user := upper(coalesce( p_user, SYS_CONTEXT(''APEX$SESSION'',''APP_USER'') )); ',
'',
'    case p_context',
'    when flow_constants_pkg.gc_task_list_context_my_tasks then',
'      ',
'        open l_cur for',
'        select curr_objt.objt_name',
'             , curr_objt.objt_tag_name',
'             , curr_objt.objt_id',
'             , sbfl.sbfl_current',
'             , prcs.prcs_name',
'             , bref.prov_var_vc2',
'             , dgrm.dgrm_name',
'             , sbfl.sbfl_due_on',
'             , round((cast(sbfl.sbfl_due_on as date) - sysdate) * 24, 1) ',
'             , sbfl.sbfl_priority',
'             , prcs.prcs_init_by',
'             , sbfl.sbfl_reservation',
'             , sbfl.sbfl_status',
'             , sbfl.sbfl_became_current',
'             , sbfl.sbfl_last_update_by',
'             , sbfl.sbfl_last_update',
'             , prcs.prcs_id',
'             , sbfl.sbfl_id',
'             , sbfl.sbfl_step_key',
'             , sbfl.sbfl_scope',
'             , sbfl.sbfl_potential_users',
'             , sbfl.sbfl_potential_groups',
'             , sbfl.sbfl_excluded_users',
'             , sbfl.sbfl_lane_name',
'             , sbfl.sbfl_lane_role',
'             , sbfl.sbfl_subject',
'          from flow_subflows sbfl',
'          join flow_processes prcs',
'            on prcs.prcs_id = sbfl.sbfl_prcs_id',
'     left join flow_objects curr_objt',
'            on curr_objt.objt_bpmn_id = sbfl.sbfl_current',
'           and curr_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'          join flow_diagrams dgrm ',
'            on dgrm.dgrm_id = prcs.prcs_dgrm_id',
'     left join flow_process_variables bref',
'            on bref.prov_prcs_id = sbfl.sbfl_prcs_id',
'           and bref.prov_var_name = ''BUSINESS_REF''',
'           and bref.prov_scope = 0',
'         where curr_objt.objt_tag_name in ( ''bpmn:userTask'' , ''bpmn:adHocSubProcess'' )',
'           and sbfl.sbfl_status in ( flow_constants_pkg.gc_sbfl_status_running',
'                                   , flow_constants_pkg.gc_sbfl_status_in_adhoc_subprocess',
'                                   )',
'           and nvl(sbfl.sbfl_hide_in_task_list, ''N'') != ''Y'';',
'',
'    when flow_constants_pkg.gc_task_list_context_single then',
'        open l_cur for',
'        select curr_objt.objt_name',
'             , curr_objt.objt_tag_name',
'             , curr_objt.objt_id',
'             , sbfl.sbfl_current',
'             , prcs.prcs_name',
'             , bref.prov_var_vc2',
'             , dgrm.dgrm_name',
'             , sbfl.sbfl_due_on',
'             , round((cast(sbfl.sbfl_due_on as date) - sysdate) * 24, 1) ',
'             , sbfl.sbfl_priority',
'             , prcs.prcs_init_by',
'             , sbfl.sbfl_reservation',
'             , sbfl.sbfl_status',
'             , sbfl.sbfl_became_current',
'             , sbfl.sbfl_last_update_by',
'             , sbfl.sbfl_last_update',
'             , prcs.prcs_id',
'             , sbfl.sbfl_id',
'             , sbfl.sbfl_step_key',
'             , sbfl.sbfl_scope',
'             , sbfl.sbfl_potential_users',
'             , sbfl.sbfl_potential_groups',
'             , sbfl.sbfl_excluded_users',
'             , sbfl.sbfl_lane_name',
'             , sbfl.sbfl_lane_role',
'             , sbfl.sbfl_subject',
'          from flow_subflows sbfl',
'          join flow_processes prcs',
'            on prcs.prcs_id = sbfl.sbfl_prcs_id',
'     left join flow_objects curr_objt',
'            on curr_objt.objt_bpmn_id = sbfl.sbfl_current',
'           and curr_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'          join flow_diagrams dgrm ',
'            on dgrm.dgrm_id = prcs.prcs_dgrm_id',
'     left join flow_process_variables bref',
'            on bref.prov_prcs_id = sbfl.sbfl_prcs_id',
'           and bref.prov_var_name = ''BUSINESS_REF''',
'           and bref.prov_scope = 0',
'         where curr_objt.obj'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
't_tag_name in ( ''bpmn:userTask'' , ''bpmn:adHocSubProcess'' )',
'           and sbfl.sbfl_status in ( flow_constants_pkg.gc_sbfl_status_running',
'                                   , flow_constants_pkg.gc_sbfl_status_waiting_approval',
'                                   , flow_constants_pkg.gc_sbfl_status_in_adhoc_subprocess',
'                                   )',
'           and prcs.prcs_id = p_prcs_id;',
'    end case;',
'',
'    return l_cur;',
'  end get_tasks;',
'',
'',
'  function get_current_tasks',
'  ( p_context    in varchar2 default flow_constants_pkg.gc_task_list_context_my_tasks',
'  , p_prcs_id    in flow_processes.prcs_id%type default null',
'  , p_user       in varchar2 default null',
'  , p_groups     in varchar2 default null',
'  ) return t_task_list_items pipelined ',
'  is',
'    type t_sbfl_row is record ',
'      ( curr_objt_name        varchar2( 200 char)',
'      , curr_objt_tag_name    varchar2(  50 char)',
'      , curr_objt_id          number',
'      , sbfl_current          varchar2(  50 char)',
'      , prcs_name             varchar2( 150 char)',
'      , prcs_business_ref     varchar2(4000 char)',
'      , prcs_dgrm_name        varchar2( 150 char)',
'      , sbfl_due_on           timestamp with time zone',
'      , sbfl_due_in_hours     number',
'      , sbfl_priority         number',
'      , prcs_init_by          varchar2( 255 char)',
'      , sbfl_reservation      varchar2( 255 char)',
'      , sbfl_status           varchar2(  20 char)',
'      , sbfl_became_current   timestamp with time zone',
'      , sbfl_last_update_by   varchar2( 255 char)',
'      , sbfl_last_update      timestamp with time zone',
'      , prcs_id               number',
'      , sbfl_id               number',
'      , sbfl_step_key              varchar2(  20 char)',
'      , sbfl_scope            number',
'      , sbfl_potential_users  varchar2(4000 char)',
'      , sbfl_potential_groups varchar2(4000 char)',
'      , sbfl_excluded_users   varchar2(4000 char)',
'      , sbfl_lane_name        varchar2( 200 char)',
'      , sbfl_lane_role        varchar2( 200 char)',
'      , sbfl_subject         varchar2(1000 char)',
'      );',
'',
'    --',
'',
'    --',
'    l_row               t_sbfl_row;',
'    l_cur               sys_refcursor;',
'    l_task              flow_api_pkg.t_task_list_item;  ',
'    l_current_groups    apex_t_varchar2;',
'    l_user              varchar2 (255 char);',
'    --',
'    procedure process_row is',
'    begin',
'        l_task.manager                 := ''FlowsForAPEX'';',
'        l_task.app_id                  := null;',
'        l_task.task_id                 := null;',
'        l_task.task_def_id             := null;',
'        l_task.task_def_name           := coalesce( l_row.curr_objt_name, l_row.sbfl_current );',
'        l_task.task_def_static_id      := null;',
'        l_task.subject                 := coalesce',
'                                           ( l_row.sbfl_subject',
'                                           , l_row.prcs_name||'' (''||l_row.prcs_business_ref||'') - ''||coalesce( l_row.curr_objt_name, l_row.sbfl_current)',
'                                           );',
'        l_task.task_type               := case l_row.sbfl_status',
'                                              when flow_constants_pkg.gc_sbfl_status_waiting_approval then',
'                                                  ''APPROVAL''',
'                                              else',
'                                                  ''F4A_USERTASK''',
'                                          end;',
'        l_task.details_app_id          := null;',
'        l_task.details_app_name        := l_row.prcs_dgrm_name;',
'        l_task.details_link_target     := case ',
'                                              when l_row.curr_objt_tag_name in (flow_constants_pkg.gc_bpmn_usertask',
'                                                                               , flow_constants_pkg.gc_bpmn_adhoc_subprocess) ',
'                                              then',
'                                                flow_usertask_pkg.get_url',
'                                                (',
'                                                  pi_prcs_id  => l_row.prcs_id',
'                                                , pi_sbfl_id  => l_row.sbfl_id',
'                                                , pi_objt_id  => l_row.curr_objt_id   ',
'                                                , pi_step_key => l_row.sbfl_step_key',
'                                                , pi_scope    => l_row.sbfl_scope',
'                                                )',
'                                              else null ',
'                                              end;',
'        l_task.due_on                  := l_row.sbfl_due_on;',
'        l_task.due_in_hours            := l_row.sbfl_due_in_hours;',
'        l_task.due_in                  := apex_util.get_since( l_row.sbfl_due_on );',
'        l_task.due_code                := case',
'                                              when l_row.sbfl_due_in_hours <   0 then ''OVERDUE''',
'                                              when l_row.sbfl_due_in_hours <   1 then ''NEXT_HOUR''',
'                                              when l_row.sbfl_due_in_hours <  24 then ''NEXT_24_HOURS''',
'                                              when l_row.sbfl_due_in_hours < 168 then ''NEXT_7_DAYS''',
'                                              when l_row.sbfl_due_in_hours < 720 then ''NEXT_30_DAYS''',
'                                              else                               ''MORE_THAN_30_DAYS''',
'                                          end;',
'        l_task.priority                := l_row.sbfl_priority;',
'        l_task.priority_level          := case l_row.sbfl_priority',
'                                              when 1 then ''urgent''',
'                                              when 2 then ''high''',
'                                              when 3 then ''medium''',
'                                              when 4 then ''low''',
'                                              when 5 then ''lowest''',
'                                          end;',
'        l_task.initiator               := l_row.prcs_init_by;',
'        l_task.initiator_lower         := lower(l_row.prcs_init_by);',
'        l_task.initiator_can_complete  := ''Y'';',
'        l_task.actual_owner            := l_row.sbfl_reservation;',
'        l_task.actual_owner_lower      := lower (l_row.sbfl_reservation);',
'        l_task.potential_owners        := l_row.sbfl_potential_users;',
'        l_task.potential_groups        := l_row.sbfl_potential_groups;',
'        l_task.excluded_owners         := l_row.sbfl_excluded_users;',
'        l_task.badge_css_classes       := --> no class, if unassigned or assigned (also see next case)',
'                                          case ',
'                                              when l_row.sbfl_status = flow_constants_pkg.gc_sbfl_status_error ',
'                                                  then ''u-danger''',
'                                          end;',
'        l_task.badge_text              := case ',
'                                            when p_context = flow_constants_pkg.gc_task_list_context_my_tasks then',
'                                                case ',
'                                                  when l_row.sbfl_status = flow_constants_pkg.gc_sbfl_status_error ',
'                                                      then flow_constants_pkg.gc_sbfl_status_error',
'                                                  when l_row.sbfl_reservation is null',
'                                                      then ''unassigned''',
'                                                end',
'                                            when p_context = flow_constants_pkg.gc_task_list_context_single then',
'                                                case',
'                                                  when l_row.sbfl_reservation is not null',
'                                                    then ''assigned : ''||l_row.sbfl_reservation',
'                                                  when l_row.sbfl_reservation is null ',
'                                                    then',
'                                                      case when l_row.sbfl_potential_users is not null then ''potential users : '' end ||',
'                                                      l_row.sbfl_potential_users ||',
'                                                      case when l_row.sbfl_potential_groups is not null then '' potential groups : '' end ||',
'                                                      l_row.sbfl_potential_groups ||',
'                                                      case when l_row.sbfl_excluded_users is not null then '' excluded users : '' end ||',
'                                                      l_row.sbfl_excluded_users',
'                                                end',
'                                          end;',
'        l_task.state_code              := null;',
'        l_task.state                   := l_row.sbfl_status;',
'        l_task.is_completed            := ''N'';',
'        l_task.outcome_code            := null;',
'        l_task.outcome                 := null;',
'',
'        l_task.created_ago_hours       := floor((sysdate - cast(l_row.sbfl_became_current as date) )*24);',
'        l_task.created_ago             := apex_util.get_since( l_row.sbfl_became_current );',
'        l_task.created_by              := l_row.prcs_init_by;',
'        l_task.created_on              := l_row.sbfl_became_current;',
'        l_task.last_updated_by         := l_row.sbfl_last_update_by;',
'        l_task.last_updated_on         := l_row.sbfl_last_update;',
'        l_task.process_id              := l_row.prcs_id;',
'        l_task.subflow_id              := l_row.sbfl_id;',
'        l_task.step_key                := l_row.sbfl_step_key;',
'        l_task.current_obj             := l_row.sbfl_current;',
'',
'    end process_row;',
'',
'    function user_is_eligible',
'    ( p_task            in flow_api_pkg.t_task_list_item',
'    , p_user            in varchar2',
'    , p_current_groups  in apex_t_varchar2',
'    ) return boolean',
'    is',
'      l_excluded_users    apex_t_varchar2;',
'      l_potential_users   apex_t_varchar2;',
'      l_potential_groups  apex_t_varchar2;',
'    begin ',
'      if p_task.excluded_owners is not null then',
'        l_excluded_users := apex_string.split ( p_str => p_task.excluded_owners',
'                                              , p_sep => '':''',
'                                              );',
'        for i in 1 .. l_excluded_users.count loop',
'          if upper(trim(l_excluded_users(i))) = upper(trim(p_user)) then',
'            return false;',
'          end if;',
'        end loop;',
'      end if;',
'',
'      if p_task.actual_owner is not null then',
'        return upper(trim(p_task.actual_owner)) = upper(trim(p_user));',
'      end if;',
'',
'      if p_task.potential_owners is null',
'         and p_task.potential_groups is null',
'      then',
'        return true;',
'      end if;',
'',
'      if p_task.potential_owners is not null then',
'        l_potential_users    := apex_string.split ( p_str => p_task.potential_owners',
'                                                  , p_sep => '':'' ',
'                                                  );',
'        for i in 1 .. l_potential_users.count loop',
'          if upper(trim(l_potential_users(i))) = upper(trim(p_user)) then',
'            return true;',
'          end if;',
'        end loop;',
'      end if;',
'',
'      if p_task.potential_groups is not null then',
'         l_potential_groups  := apex_string.split ( p_str => p_task.potential_groups',
'                                                  , p_sep => '':''',
'                                                  );',
'          for i in 1 .. l_potential_groups.count loop',
'            for j in 1 .. p_current_groups.count loop',
'              if upper(trim(l_potential_groups(i))) = upper(trim(p_current_groups(j))) then',
'                return true;',
'              end if;',
'            end loop;',
'          end loop;',
'          end if;',
'',
'      return false;',
'    end user_is_eligible;',
'',
'',
'  begin',
'        l_user    := upper(coalesce( p_user, v(''APP_USER'')));',
'',
'        if p_groups is not null then',
'          l_current_groups  := apex_string.split ( p_str => p_groups',
'                                                 , p_sep => '':''',
'                                                 );',
'        else',
'          select roles.role_static_id',
'          bulk   collect into l_current_groups',
'            from apex_appl_acl_user_roles roles',
'           where roles.user_name     = v(''APP_USER'')',
'             and roles.workspace_id  = v(''WORKSPACE_ID'')',
'          ;',
'        end if;',
'',
'        if l_current_groups is null then',
'          l_current_groups := apex_t_varchar2();',
'        end if;',
'',
'        l_task := flow_api_pkg.t_task_list_item ',
'                  ( null, null, null, null, null, null, null, null, null, null',
'                  , null, null, null, null, null, null, null, null, null, null',
'                  , null, null, null, null, null, null, null, null, null, null',
'                  , null, null, null, null, null, null, null, null, null, null ',
'                  );',
'        l_cur  := get_tasks',
'                  ( p_context  => p_context',
'                  , p_prcs_id  => p_prcs_id',
'                  , p_user     => l_user',
'                  , p_groups   => p_groups',
'                  );',
'',
'',
'        loop',
'            fetch l_cur into l_row;',
'            exit when l_cur%notfound;',
'            pragma inline(process_row, ''YES'');',
'            process_row;',
'            if    p_context = flow_constants_pkg.gc_task_list_context_single',
'               or user_is_eligible  ( p_task            => l_task',
'                                    , p_user            => l_user',
'                                    , p_current_groups  => l_current_groups',
'                                    ) ',
'            then ',
'               pipe row( l_task );',
'            end if;',
'        end loop;',
'',
'        if l_cur%isopen then',
'            close l_cur;',
'        end if;',
'',
'  exception',
'    when no_data_needed then',
'        close l_cur;',
'    when others then',
'        if l_cur%isopen then',
'            close l_cur;',
'        end if;',
'        raise;',
'  end get_current_tasks;',
'      ',
'',
'  procedure return_approval_result',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_apex_task_id  in number',
'    , p_result        in flow_process_variables.prov_var_vc2%type default null',
'    )',
'  is',
'  begin',
'    flow_usertask_pkg.return_approval_result  ( p_process_id    => p_process_id',
'                                              , p_apex_task_id  => p_apex_task_id',
'                                              , p_result        => p_result',
'                                              );',
'  end return_approval_result;',
'',
'  procedure return_task_state_outcome',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type',
'    , p_step_key      in flow_subflows.sbfl_step_key%type ',
'    , p_apex_task_id  in number',
'    , p_state_code    in apex_tasks.state_code%type ',
'    , p_outcome       in flow_process_variables.prov_var_vc2%type default null',
'    )',
'  is',
'    l_session_id   number;',
'  begin',
'      -- create an APEX session if this has come in from outside APEX',
'    if sys_context(''apex$session'',''app_user'')  is null then',
'      l_session_id := flow_apex_session.create_api_session (p_subflow_id => p_subflow_id);',
'    end if; ',
'    flow_usertask_pkg.return_task_state_outcome   ( p_process_id    => p_process_id',
'                                                  , p_subflow_id    => p_subflow_id',
'                                                  , p_step_key      => p_step_key',
'                                                  , p_apex_task_id  => p_apex_task_id',
'                                                  , p_state_code    => p_state_code',
'                                                  , p_outcome       => p_outcome',
'                                                  );',
'    if l_session_id is not null then',
'      flow_apex_session.delete_session (p_session_id => l_session_id ); ',
'    end if;',
'  end return_task_state_outcome;',
'',
'  function get_task_potential_owners ',
'   ( p_process_id in flow_processes.prcs_id%type ',
'   , p_subflow_id in flow_subflows.sbfl_id%type   ',
'   , p_step_key   in flow_subflows.sbfl_step_key%type ',
'   , p_separator  in varchar2 default '',''  ',
'   ) return flow_process_variables.prov_var_vc2%type',
'  is',
'  begin',
'    return flow_usertask_pkg.get_task_potential_owners',
'           ( p_process_id => p_process_id',
'           , p_subflow_id => p_subflow_id',
'           , p_step_key   => p_step_key',
'           , p_separator  => p_separator',
'           );',
'  end get_task_potential_owners;',
'  ',
'  function get_task_business_admins ',
'   ( p_process_id         in flow_processes.prcs_id%type ',
'   , p_subflow_id         in flow_subflows.sbfl_id%type ',
'   , p_step_key           in flow_subflows.sbfl_step_key%type ',
'   , p_separator          in varchar2 default '','' ',
'   , p_add_diagram_admin  in boolean default false',
'   , p_add_instance_admin in boolean default false',
'   ) return flow_process_variables.prov_var_vc2%type',
'  is',
'  begin',
'    return flow_usertask_pkg.get_task_business_admins',
'           ( p_process_id => p_process_id',
'           , p_subflow_id => p_subflow_id',
'           , p_step_key   => p_step_key',
'           , p_separator  => p_separator',
'           );',
'  end get_task_business_admins;',
'',
'  procedure receive_message',
'  ( p_message_name  flow_message_subscriptions.msub_message_name%type',
'  , p_key_name      flow_message_subscriptions.msub_key_name%type',
'  , p_key_value     flow_message_subscriptions.msub_key_value%type',
'  , p_payload       clob default null',
'  )',
'  is',
'  begin',
'    -- Note:  Unlike other API calls, we cannot create an  APEX session here if this has come in from outside APEX',
'    -- as we do not yet have Flows information.  Wait until correlation completed to ',
'    -- create a session (inside flow_message_flow.receive_message)',
'    flow_message_flow.receive_message ( p_message_name  =>p_message_name',
'                                          , p_key_name  =>  p_key_name',
'                                          , p_key_value  => p_key_value',
'                                          , p_payload  => p_payload ',
'                                          );',
'  end receive_message;',
'',
'  function intervalDStoSec (',
'    p_intervalDS  interval day to second',
'  ) return number',
'  is',
'    l_sec number;',
'  begin',
'    return ( extract( day   from p_intervalDS) * 86400',
'           + extract( hour  from p_intervalDS) *  3600',
'           + extract(minute from p_intervalDS) *    60',
'           + extract(second from p_intervalDS)        ',
'           );',
'  end intervalDStoSec;',
'',
'  function intervalDStoHours (',
'    p_intervalDS  interval day to second',
'  ) return number',
'  is',
'    l_sec number;',
'  begin',
'    return ( extract( day   from p_intervalDS) * 24',
'           + extract( hour  from p_intervalDS)      ',
'           );',
'  end intervalDStoHours;',
'',
'-- Manually Step Forward Timers',
'',
'  procedure step_timers',
'  is',
'  begin',
'    flow_timers_pkg.step_timers;',
'  end;',
'',
'end flow_api_pkg;',
'/',
'',
'create or replace package body flow_boundary_events',
'is ',
'',
'/* -- Flows for APEX - flow_boundary_events.pkb',
'--',
'-- (c) Copyright Flowquest Ltd and / or its affiliates, 2021-2025',
'--',
'-- Created  22-Feb-2021   Richard Allen - ',
'-- Modified 15-Jun-2022   Moritz Klein (MT AG)',
'-- Modified 02-Apr-2025   Richard Allen (Flowquest)',
'*/',
'',
'',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  procedure set_boundary_events',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , p_sbfl_info     in flow_subflows%rowtype',
'  )',
'  is ',
'    l_new_non_int_event_sbfl      flow_types_pkg.t_subflow_context;',
'    l_new_non_int_event_sbfl_info flow_subflows%rowtype;',
'    l_subscription_detail         flow_message_flow.t_subscription_details;',
'    l_status                      flow_subflows.sbfl_status%type;',
'    l_parent_tag                  varchar2(50);',
'    l_child_tag                   varchar2(50);',
'    l_msg_sub                     flow_message_subscriptions.msub_id%type;',
'  begin',
'    apex_debug.enter ',
'    ( ''set_boundary_events''',
'    , ''subflow'', p_subflow_id',
'    );',
'    begin',
'      for boundary_events in ',
'        (',
'        select objt.objt_bpmn_id as objt_bpmn_id ',
'             , objt.objt_sub_tag_name as objt_sub_tag_name',
'             , objt.objt_interrupting as objt_interrupting',
'             , sbfl.sbfl_process_level as sbfl_process_level',
'             , sbfl.sbfl_dgrm_id as sbfl_dgrm_id',
'             , sbfl.sbfl_current as parent_current_object',
'             , objt.objt_id as objt_id',
'             , sbfl.sbfl_scope as sbfl_scope',
'          from flow_objects objt',
'          join flow_subflows sbfl ',
'            on sbfl.sbfl_current = objt.objt_attached_to',
'           and sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'         where objt.objt_tag_name = flow_constants_pkg.gc_bpmn_boundary_event  ',
'           and objt.objt_sub_tag_name in ( flow_constants_pkg.gc_bpmn_timer_event_definition',
'                                         , flow_constants_pkg.gc_bpmn_message_event_definition )',
'           and sbfl.sbfl_id = p_subflow_id',
'           and sbfl.sbfl_prcs_id = p_process_id',
'        )',
'      loop',
'        apex_debug.message ',
'        ( p_message => ''Boundary Event found.  ID: %0 SubTag:  %1  Interupting: %2''',
'        , p0 => boundary_events.objt_bpmn_id',
'        , p1 => boundary_events.objt_sub_tag_name',
'        , p2 => boundary_events.objt_interrupting',
'        );',
'        case boundary_events.objt_interrupting',
'        when 1 then',
'          -- process any before-event variable expressions on the starting object',
'          flow_expressions.process_expressions',
'          ( pi_objt_id     => boundary_events.objt_id ',
'          , pi_set         => flow_constants_pkg.gc_expr_set_before_event',
'          , pi_prcs_id     => p_process_id',
'          , pi_sbfl_id     => p_subflow_id',
'          , pi_step_key    => null',
'          , pi_var_scope   => boundary_events.sbfl_scope',
'          , pi_expr_scope  => boundary_events.sbfl_scope',
'          );',
'          -- test for any step errors',
'          if not flow_globals.get_step_error then ',
'            case boundary_events.objt_sub_tag_name',
'            when flow_constants_pkg.gc_bpmn_timer_event_definition then',
'              -- interupting timer.  set timer on current object in current subflow',
'              flow_timers_pkg.start_timer',
'              ( pi_prcs_id      => p_process_id',
'              , pi_sbfl_id      => p_subflow_id',
'              , pi_callback     => flow_constants_pkg.gc_bpmn_boundary_event',
'              , pi_callback_par => ''interrupting''',
'              );',
'              l_parent_tag := '':SIT'';  -- (Self, Interrupting, Timer)',
'            when flow_constants_pkg.gc_bpmn_message_event_definition then',
'              -- interupting message.  set message subscription on current object in current subflow',
'              l_subscription_detail := flow_message_util.get_msg_subscription_details ( p_msg_object_bpmn_id  => boundary_events.objt_bpmn_id',
'                                                                                      , p_dgrm_id  => boundary_events.sbfl_dgrm_id',
'                                                                                      , p_sbfl_info  => p_sbfl_info',
'                                                                                      );',
'              l_subscription_detail.callback     := flow_constants_pkg.gc_bpmn_boundary_event;',
'              l_subscription_detail.callback_par := boundary_events.objt_bpmn_id;',
'              l_msg_sub := flow_message_flow.subscribe ( p_subscription_details  => l_subscription_detail);',
'  ',
'              l_parent_tag := '':SIM'';  -- (Self, Interrupting, Message)',
'            end case;',
'          end if;',
'        when 0 then',
'            case boundary_events.objt_sub_tag_name',
'            when flow_constants_pkg.gc_bpmn_timer_event_definition   then ',
'              l_status      := flow_constants_pkg.gc_sbfl_status_waiting_timer;',
'              l_child_tag   := '':SNT'';  -- (Self, Non-Interrupting, Timer)',
'              l_parent_tag  := '':CNT'';  -- (Child, Non-Interrupting, Timer)',
'            when flow_constants_pkg.gc_bpmn_message_event_definition then ',
'              l_status := flow_constants_pkg.gc_sbfl_status_waiting_message;',
'              l_child_tag   := '':SNM'';  -- (Self, Non-Interrupting, Message)  ',
'              l_parent_tag  := '':CNM'';  -- (Child, Non-U=Interrupting, Message)            ',
'            end case;',
'',
'          -- non-interupting event.  create child subflow starting at boundary event and start timer/subscribe message / etc',
'          l_new_non_int_event_sbfl := flow_engine_util.subflow_start',
'          ( p_process_id => p_process_id',
'          , p_parent_subflow => p_subflow_id',
'          , p_starting_object => boundary_events.objt_bpmn_id',
'          , p_current_object => boundary_events.objt_bpmn_id',
'          , p_route => ''from boundary event - run 1''',
'          , p_last_completed => boundary_events.parent_current_object ',
'          , p_status => l_status',
'          , p_parent_sbfl_proc_level => boundary_events.sbfl_process_level',
'          , p_new_proc_level => false',
'          , p_dgrm_id => boundary_events.sbfl_dgrm_id',
'          );',
' ',
'          -- process any before-event variable expressions on the starting object',
'          flow_expressions.process_expressions',
'          ( pi_objt_id     => boundary_events.objt_id',
'          , pi_set         => flow_constants_pkg.gc_expr_set_before_event',
'          , pi_prcs_id     => p_process_id',
'          , pi_sbfl_id     => l_new_non_int_event_sbfl.sbfl_id',
'          , pi_step_key    => l_new_non_int_event_sbfl.step_key',
'          , pi_var_scope   => boundary_events.sbfl_scope',
'          , pi_expr_scope  => boundary_events.sbfl_scope',
'          );',
'          -- test for any step errors',
'          if not flow_globals.get_step_error then ',
'            case boundary_events.objt_sub_tag_name',
'            when flow_constants_pkg.gc_bpmn_timer_event_definition then',
'              -- non-interrupting timer - start timer on event subflow',
'              flow_timers_pkg.start_timer',
'              ( pi_prcs_id      => p_process_id',
'              , pi_sbfl_id      => l_new_non_int_event_sbfl.sbfl_id',
'              , pi_step_key     => l_new_non_int_event_sbfl.step_key',
'              , pi_callback     => flow_constants_pkg.gc_bpmn_boundary_event',
'              , pi_callback_par => ''non-interrupting''                -----  RA NOTE  move to constants_pkg',
'              );',
'            when flow_constants_pkg.gc_bpmn_message_event_definition then',
'              -- non-interupting message.  set message subscription on event subflow',
'              select *',
'                into l_new_non_int_event_sbfl_info',
'                from flow_subflows',
'               where sbfl_id = l_new_non_int_event_sbfl.sbfl_id;',
'',
'              l_subscription_detail := flow_message_util.get_msg_subscription_details ( p_msg_object_bpmn_id  => boundary_events.objt_bpmn_id',
'                                                                                      , p_dgrm_id             => boundary_events.sbfl_dgrm_id',
'                                                                                      , p_sbfl_info           => l_new_non_int_event_sbfl_info',
'                                                                                      );  ',
'              l_subscription_detail.callback      := flow_constants_pkg.gc_bpmn_boundary_event;',
'              l_subscription_detail.callback_par  := boundary_events.objt_bpmn_id;',
'              l_msg_sub := flow_message_flow.subscribe(p_subscription_details  => l_subscription_detail);',
'            end case;',
'',
'            -- test again for any step errors',
'            if not flow_globals.get_step_error then ',
'              -- set timer flag on child (Self, Noninterrupting, Timer)',
'              update flow_subflows sbfl',
'                  set sbfl.sbfl_has_events      = sbfl.sbfl_has_events||l_child_tag',
'                    , sbfl.sbfl_last_update     = systimestamp',
'                    , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                           , sys_context(''userenv'',''os_user'')',
'                                                           , sys_context(''userenv'',''session_user'')',
'                                                           )  ',
'                where sbfl.sbfl_id = l_new_non_int_event_sbfl.sbfl_id',
'                  and sbfl.sbfl_prcs_id = p_process_id',
'              ;',
'            end if;',
'          end if;',
'        end case;',
'        --- set timer flag on parent (it can get more than 1)',
'        update flow_subflows sbfl',
'          set sbfl.sbfl_has_events      = sbfl.sbfl_has_events||l_parent_tag',
'            , sbfl.sbfl_last_update     = systimestamp',
'            , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'        where sbfl.sbfl_id      = p_subflow_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'        ;',
'      end loop;',
'    exception',
'      when no_data_found then',
'        return;',
'    end;',
'  end set_boundary_events;',
'',
'  procedure unset_boundary_events',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  )',
'  is ',
'    l_non_int_timer_sbfl  flow_subflows.sbfl_id%type;',
'    l_return_code         number;',
'  begin',
'    apex_debug.enter ',
'    ( ''unset_boundary_events''',
'    , ''subflow'', p_s'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ubflow_id',
'    );',
'    begin',
'      for boundary_events in ',
'        (',
'        select objt.objt_bpmn_id as objt_bpmn_id ',
'             , objt.objt_interrupting as objt_interrupting',
'          from flow_objects objt',
'          join flow_subflows sbfl ',
'            on sbfl.sbfl_current = objt.objt_attached_to',
'           and sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'         where objt.objt_tag_name = flow_constants_pkg.gc_bpmn_boundary_event  ',
'           and objt.objt_sub_tag_name in ( flow_constants_pkg.gc_bpmn_timer_event_definition',
'                                         , flow_constants_pkg.gc_bpmn_message_event_definition )',
'           and sbfl.sbfl_id = p_subflow_id',
'           and sbfl.sbfl_prcs_id = p_process_id',
'        )',
'      loop',
'        case boundary_events.objt_interrupting',
'        when 1 then',
'          -- interupting timer.  terminate timer on current object in current subflow',
'          flow_timers_pkg.terminate_timer',
'          ( pi_prcs_id => p_process_id',
'          , pi_sbfl_id => p_subflow_id',
'          , po_return_code => l_return_code',
'          );',
'        when 0 then',
'          -- non-interupting timer.  find child subflow starting at boundary event and delete if not yet fired',
'          -- timer will delete cascade',
'          delete from flow_subflows',
'          where sbfl_starting_object = boundary_events.objt_bpmn_id',
'          and sbfl_sbfl_id = p_subflow_id',
'          and sbfl_prcs_id = p_process_id',
'          and sbfl_status = flow_constants_pkg.gc_sbfl_status_waiting_timer',
'          ;',
'        end case;',
'      end loop;',
'      -- remove the event flags from the subflow',
'      update flow_subflows sbfl',
'         set sbfl_has_events      = ''''',
'           , sbfl_last_update     = systimestamp',
'           , sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                             , sys_context(''userenv'',''os_user'')',
'                                             , sys_context(''userenv'',''session_user'')',
'                                             )  ',
'       where sbfl.sbfl_id = p_subflow_id',
'         and sbfl.sbfl_prcs_id = p_process_id',
'      ;',
'    exception',
'      when no_data_found then',
'        return;',
'    end;',
'  end unset_boundary_events;',
'',
'  procedure lock_child_boundary_timers',
'  ( p_process_id          in flow_processes.prcs_id%type',
'  , p_subflow_id          in flow_subflows.sbfl_id%type',
'  , p_parent_objt_bpmn_id in flow_objects.objt_bpmn_id%type',
'  ) ',
'  is ',
'    cursor c is ',
'        select child_sbfl.sbfl_id, child_timr.timr_id',
'          from flow_subflows child_sbfl',
'          join flow_timers child_timr',
'            on child_timr.timr_prcs_id = child_sbfl.sbfl_prcs_id',
'           and child_timr.timr_sbfl_id = child_sbfl.sbfl_id',
'         where child_sbfl.sbfl_starting_object = p_parent_objt_bpmn_id ',
'           and child_sbfl.sbfl_current = p_parent_objt_bpmn_id ',
'           and child_sbfl.sbfl_prcs_id = p_process_id',
'           and child_sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_waiting_timer',
'         order by child_sbfl.sbfl_id',
'        for update of child_sbfl.sbfl_id, child_timr.timr_id wait 3;',
'  begin ',
'    open c;',
'    close c;',
'  exception ',
'    when lock_timeout then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => p_subflow_id',
'      , pi_message_key => ''boundary-event-child-lock-to''',
'      , p0             => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''boundary-event-child-lock-to'' || ''Child Boundary Subflows or Timers of %0 currently locked by another user.  Retry your transaction later.''  ',
'  end lock_child_boundary_timers; ',
'',
'  procedure handle_interrupting_boundary_event',
'    ( p_process_id      in flow_processes.prcs_id%type',
'    , p_subflow_id      in flow_subflows.sbfl_id%type',
'    , p_event_type      in flow_objects.objt_sub_tag_name%type',
'    , p_boundary_object in flow_objects.objt_bpmn_id%type default null',
'    ) ',
'      -- used for Interrupting Timer   Boundary events, called by flow_engine.timer_callback',
'      -- used for Interrupting Message Boundary events, called by flow_message_flow.receive_message',
'  is',
'    l_boundary_objt_bpmn_id  flow_objects.objt_bpmn_id%type;',
'    l_parent_objt_tag        flow_objects.objt_tag_name%type;',
'    l_parent_objt_bpmn_id    flow_objects.objt_bpmn_id%type;',
'    l_child_process_level    flow_subflows.sbfl_process_level%type; ',
'    l_step_key               flow_subflows.sbfl_step_key%type;',
'    l_timestamp              flow_subflows.sbfl_became_current%type;',
'    l_scope                  flow_subflows.sbfl_scope%type;',
'    l_sbfl_rec               flow_subflows%rowtype;',
'    l_apex_business_admin    flow_subflows.sbfl_apex_business_admin%type;',
'    l_apex_task_id           flow_subflows.sbfl_apex_task_id%type;',
'  begin',
'    apex_debug.enter ',
'    ( ''handle_interrupting_boundary_event''',
'    , ''subflow'', p_subflow_id',
'    , ''event type'', p_event_type',
'    , ''boundary object'',p_boundary_object',
'    );',
'    -- we are migrating boundary event callback structure over next few releases but will handle old and new way',
'    -- result will be to allow multiple boundary events of the same type on an object',
'    if p_boundary_object is null or p_boundary_object in (''interrupting'', ''non-interrupting'') then ',
'      -- old style - should be only one event of type on parent',
'      select boundary_objt.objt_bpmn_id',
'           , main_objt.objt_tag_name',
'           , main_objt.objt_bpmn_id',
'           , sbfl.sbfl_scope',
'           , sbfl.sbfl_apex_business_admin',
'           , sbfl.sbfl_apex_task_id',
'        into l_boundary_objt_bpmn_id',
'           , l_parent_objt_tag',
'           , l_parent_objt_bpmn_id',
'           , l_scope',
'           , l_apex_business_admin',
'           , l_apex_task_id',
'        from flow_subflows sbfl',
'        join flow_objects main_objt',
'          on main_objt.objt_bpmn_id = sbfl.sbfl_current',
'         and main_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'        join flow_objects boundary_objt',
'          on boundary_objt.objt_attached_to = main_objt.objt_bpmn_id',
'         and boundary_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'       where sbfl.sbfl_id = p_subflow_id',
'         and sbfl.sbfl_prcs_id = p_process_id',
'         and boundary_objt.objt_sub_tag_name = p_event_type',
'         and boundary_objt.objt_interrupting = 1',
'          ;',
'    else',
'      -- newstyle - event callback contained a bpmn id of the object to callback',
'      select boundary_objt.objt_bpmn_id',
'           , main_objt.objt_tag_name',
'           , main_objt.objt_bpmn_id',
'           , sbfl.sbfl_scope',
'           , sbfl.sbfl_apex_business_admin',
'           , sbfl.sbfl_apex_task_id',
'        into l_boundary_objt_bpmn_id',
'           , l_parent_objt_tag',
'           , l_parent_objt_bpmn_id',
'           , l_scope',
'           , l_apex_business_admin',
'           , l_apex_task_id',
'        from flow_subflows sbfl',
'        join flow_objects main_objt',
'          on main_objt.objt_bpmn_id = sbfl.sbfl_current',
'         and main_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'        join flow_objects boundary_objt',
'          on boundary_objt.objt_attached_to = main_objt.objt_bpmn_id',
'         and boundary_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'         and boundary_objt.objt_bpmn_id = p_boundary_object',
'       where sbfl.sbfl_id = p_subflow_id',
'         and sbfl.sbfl_prcs_id = p_process_id',
'         and boundary_objt.objt_sub_tag_name = p_event_type',
'         and boundary_objt.objt_interrupting = 1',
'          ;',
'    end if;',
'',
'    if l_parent_objt_tag in ( flow_constants_pkg.gc_bpmn_subprocess',
'                            , flow_constants_pkg.gc_bpmn_call_activity ',
'                            , flow_constants_pkg.gc_bpmn_adhoc_subprocess',
'                            )',
'    then',
'       -- if the boundary event is on a subprocess or call activity (rather than a task type), terminate the subprocess level',
'       -- find the process level inside the subprocess and then stop all processing at that level and below',
'       -- this wll also work for adhoc subprocesses',
'      select distinct sbfl.sbfl_process_level',
'        into l_child_process_level',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_sbfl_id = p_subflow_id',
'      ;',
'      if l_child_process_level is not null ',
'      then ',
'         flow_engine_util.terminate_level',
'         ( p_process_id    => p_process_id',
'         , p_process_level => l_child_process_level',
'         );',
'      end if;',
'    end if;',
'',
'    -- clean up any other boundary events on the object',
'    flow_boundary_events.unset_boundary_events ',
'    ( p_process_id => p_process_id',
'    , p_subflow_id => p_subflow_id',
'    );',
'    -- clean up any subscriptions for message events on the object',
'    flow_message_util.cancel_subscription',
'    ( p_process_id => p_process_id',
'    , p_subflow_id => p_subflow_id',
'    );',
'    -- log the step interruption on the interupted object',
'    flow_logging.log_step_event',
'    ( p_process_id       => p_process_id',
'    , p_subflow_id       => p_subflow_id',
'    , p_event            => flow_constants_pkg.gc_step_event_interrupted',
'    , p_event_level      => flow_constants_pkg.gc_logging_level_routine',
'    , p_comment          => ''Interrupted by Boundary Event ''||l_boundary_objt_bpmn_id',
'    );',
'    -- clean up any APEX Human Tasks started for the interrupted object',
'    if ( l_parent_objt_tag = flow_constants_pkg.gc_bpmn_usertask ',
'       and  l_apex_task_id is not null ) then',
'      flow_usertask_pkg.cancel_apex_task',
'      ( p_process_id            => p_process_id',
'      , p_subflow_id            => p_subflow_id',
'      , p_objt_bpmn_id          => l_parent_objt_bpmn_id',
'      , p_apex_task_id          => l_apex_task_id',
'      , p_apex_business_admin   => l_apex_business_admin',
'      );',
'    end if;',
'    -- generate a step key & insert in the update...use later',
'    l_timestamp := systimestamp;',
'    l_step_key := flow_engine_util.step_key ( pi_sbfl_id   => p_subflow_id',
'                                            , pi_current => l_boundary_objt_bpmn_id',
'                                            , pi_became_current => l_timestamp ',
'                                            );',
'    -- switch processing onto boundaryEvent path and do next step',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_current        = l_boundary_objt_bpmn_id',
'         , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'         , sbfl.sbfl_apex_task_id   = null',
'         , sbfl.sbfl_apex_business_admin = null',
'         , sbfl.sbfl_last_completed = l_parent_objt_bpmn_id',
'         , sbfl.sbfl_became_current = l_timestamp',
'         , sbfl.sbfl_step_key       = l_step_key',
'         , sbfl.sbfl_last_update    = l_timestamp ',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )  ',
'     where sbfl.sbfl_id = p_subflow_id ',
'       and sbfl.sbfl_prcs_id = p_process_id',
'    ;',
' ',
'    -- process on-event variable expressions for the boundary event',
'    flow_expressions.process_expressions',
'    ( pi_objt_bpmn_id => l_boundary_objt_bpmn_id  ',
'    , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'    , pi_prcs_id      => p_process_id',
'    , pi_sbfl_id      => p_subflow_id',
'    , pi_step_key     => l_step_key',
'    , pi_var_scope    => l_scope',
'    , pi_expr_scope   => l_scope',
'    );',
'    -- test for errors',
'    if flow_globals.get_step_error then ',
'      -- has step errors from expressions - set error status',
'      flow_errors.set_error_status',
'      ( pi_prcs_id => p_process_id',
'      , pi_sbfl_id => p_subflow_id',
'      );',
'    else',
'      -- If not, step off on new path...',
'      flow_engine.flow_complete_step ',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id ',
'      , p_step_key => l_step_key',
'      );',
'    end if;',
'',
'  end handle_interrupting_boundary_event;',
'',
'  procedure get_boundary_event',
'  ( pi_dgrm_id                  in  flow_diagrams.dgrm_id%type',
'  , pi_throw_objt_bpmn_id       in  flow_objects.objt_bpmn_id%type',
'  , pi_par_sbfl                 in  flow_subflows.sbfl_id%type',
'  , pi_sub_tag_name             in  flow_objects.objt_sub_tag_name%type ',
'  , po_boundary_objt            out flow_objects.objt_bpmn_id%type',
'  , po_is_interrupting          out boolean',
'  , po_par_sbfl_scope           out flow_subflows.sbfl_scope%type',
'  )',
'  is ',
'    l_process_id    flow_processes.prcs_id%type;',
'      l_interrupting  flow_objects.objt_interrupting%type;',
'  begin',
'    -- in later release if named errors and escalations are supported, change this to look for specific event',
'    select boundary_objt.objt_bpmn_id',
'         , boundary_objt.objt_interrupting',
'         , parent_sbfl.sbfl_prcs_id',
'         , parent_sbfl.sbfl_scope',
'      into po_boundary_objt',
'         , l_interrupting',
'         , l_process_id',
'         , po_par_sbfl_scope',
'      from flow_objects boundary_objt',
'      join flow_subflows parent_sbfl',
'        on parent_sbfl.sbfl_current = boundary_objt.objt_attached_to',
'       and parent_sbfl.sbfl_dgrm_id = boundary_objt.objt_dgrm_id',
'     where parent_sbfl.sbfl_id = pi_par_sbfl',
'       and boundary_objt.objt_sub_tag_name = pi_sub_tag_name',
'    ;',
'    if l_interrupting = 1 then',
'      po_is_interrupting := true;',
'    else',
'      po_is_interrupting := false;',
'    end if;',
'  exception',
'    when no_data_found then',
'        -- no boundary event found -- returned flow should continue from normal return',
'        if pi_sub_tag_name in (flow_constants_pkg.gc_bpmn_error_event_definition) then',
'           po_is_interrupting := true;',
'        else ',
'           po_is_interrupting := false;',
'        end if;',
'    when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => l_process_id',
'        , pi_sbfl_id     => pi_par_sbfl',
'        , pi_message_key => ''boundary-event-too-many''',
'        , p0 => pi_sub_tag_name',
'        );',
'        -- $F4AMESSAGE ''boundary-event-too-many'' || ''More than one %0 boundaryEvent found on sub process.''  ',
'  end get_boundary_event;',
'',
'  procedure process_escalation',
'    ( pi_sbfl_info        in  flow_subflows%rowtype',
'    , pi_step_info        in  flow_types_pkg.flow_step_info',
'    , pi_par_sbfl         in  flow_subflows.sbfl_id%type',
'    , pi_source_type      in  flow_types_pkg.t_bpmn_id',
'    , po_step_key         out flow_subflows.sbfl_step_key%type',
'    , po_is_interrupting  out boolean',
'    )',
'  is ',
'    l_boundary_event        flow_objects.objt_bpmn_id%type;',
'    l_interrupting          flow_objects.objt_interrupting%type;',
'    l_new_sbfl              flow_types_pkg.t_subflow_context;',
'    l_parent_processs_level flow_subflows.sbfl_process_level%type;',
'    l_parent_sbfl_scope     flow_subflows.sbfl_scope%type;',
'    l_parent_dgrm_id        flow_diagrams.dgrm_id%type;',
'    l_parent_step_key       flow_subflows.sbfl_step_key%type;',
'    l_timestamp             flow_subflows.sbfl_became_current%type;',
'    l_step_key              flow_subflows.sbfl_step_key%type;',
'  begin ',
'    apex_debug.enter ',
'    ( ''process_escalation''',
'    , ''subflow'', pi_sbfl_info.sbfl_id',
'    , ''parent subflow'', pi_par_sbfl',
'    , ''source type'', pi_source_type',
'    );',
'    -- called to process an escallation from an Escalation ITE or an Escalation End Event',
'    -- both can be Interrupting or Non interrupting',
'    --',
'    -- find matching boundary event of its type',
'    get_boundary_event',
'    ( pi_dgrm_id            => pi_step_info.dgrm_id',
'    , pi_throw_objt_bpmn_id => pi_step_info.target_objt_ref',
'    , pi_par_sbfl           => pi_par_sbfl',
'    , pi_sub_tag_name       => pi_step_info.target_objt_subtag',
'    , po_boundary_objt      => l_boundary_event',
'    , po_is_interrupting    => po_is_interrupting',
'    , po_par_sbfl_scope     => l_parent_sbfl_scope',
'    );',
'    if l_boundary_event is null then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => pi_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id     => pi_sbfl_info.sbfl_id',
'      , pi_message_key => ''boundary-event-no-catch-found''',
'      , p0 => pi_step_info.target_objt_subtag',
'      );',
'      -- $F4AMESSAGE ''boundary-event-no-catch-found'' || ''No boundaryEvent of type %0 found to catch event.''  ',
'    end if;',
'',
'    if po_is_interrupting then',
'      -- interrupting escalation event',
'      if pi_source_type = flow_constants_pkg.gc_bpmn_intermediate_throw_event then ',
'        -- set the throwing event to completed if an ITE',
'        flow_logging.log_step_completion   ',
'        ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => pi_sbfl_info.sbfl_id',
'        , p_completed_object => pi_step_info.target_objt_ref',
'        );  ',
'      end if;',
'      -- first remove any non-interrupting timers that are on the parent event',
'      unset_boundary_events (pi_sbfl_info.sbfl_prcs_id, pi_par_sbfl);',
'      -- stop processing in process level and all lower (child) levels',
'      flow_engine_util.terminate_level',
'      ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'      , p_process_level => pi_sbfl_info.sbfl_process_level',
'      );        ',
'      -- generate a step key & insert in the update...use later',
'      l_timestamp := systimestamp;',
'      l_step_key := flow_engine_util.step_key ( pi_sbfl_id   => pi_par_sbfl --p_sbfl_info.sbfl_id',
'                                              , pi_current => l_boundary_event',
'                                              , pi_became_current => l_timestamp ',
'                                              );                       ',
'      -- set parent subflow to boundary event and do flow_complete_step',
'      update flow_subflows sbfl',
'          set sbfl.sbfl_current         = l_boundary_event',
'            , sbfl.sbfl_last_completed  = pi_step_info.target_objt_ref ',
'            , sbfl.sbfl_status          = flow_constants_pkg.gc_sbfl_status_running',
'            , sbfl.sbfl_became_current  = l_timestamp',
'            , sbfl.sbfl_step_key        = l_step_key',
'            , sbfl.sbfl_last_update     = l_timestamp',
'            , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'        where sbfl.sbfl_id = pi_par_sbfl',
'          and sbfl.sbfl_prcs_id = pi_sbfl_info.sbfl_prcs_id',
'      ;',
'      -- process on-event expressions for boundary event',
'      flow_expressions.process_expressions',
'      ( pi_objt_bpmn_id => l_boundary_event  ',
'      , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'      , pi_prcs_id      => pi_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id      => pi_par_sbfl',
'      , pi_step_key     => l_step_key',
'      , pi_var_scope    => l_parent_sbfl_scope',
'      , pi_expr_scope   => l_parent_sbfl_scope',
'      );',
'',
'        flow_engine.flow_complete_step',
'        ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => pi_par_sbfl',
'        , p_step_key   => l_step_key',
'        ); ',
'',
'    else  --( = not po_is_interrupting)',
'      -- non interrupting.  ',
'      select par_sbfl.sbfl_process_level',
'           , par_sbfl.sbfl_dgrm_id',
'        into l_parent_processs_level ',
'           , l_parent_dgrm_id',
'        from flow_subflows par_sbfl',
'        where par_sbfl.sbfl_id = pi_par_sbfl',
'          and par_sbfl.sbfl_prcs_id = pi_sbfl_info.sbfl_prcs_id',
'          ;',
'',
'      -- fork first, then procced on main, then step off on child',
'',
'      -- start new subflow starting at the boundary event and step to next task',
'      l_new_sbfl := flow_engine_util.subflow_start',
'      ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'      , p_parent_subflow => pi_par_sbfl',
'      , p_starting_object => l_boundary_event',
'      , p_current_object => l_boundary_event',
'      , p_route => ''from ''||l_boundary_event',
'      , p_last_completed => pi_step_info.target_objt_ref -- even thou it hasnt yet completed ',
'      , p_status => flow_constants_pkg.gc_sbfl_status_running',
'      , p_parent_sbfl_proc_level => l_parent_processs_level',
'      , p_new_proc_level => false',
'      , p_dgrm_id => l_parent_dgrm_id',
'      );',
'      ',
'      apex_debug.message',
'      (',
'        p_message => ''process_boundary_event.  target_objt_tag :''||pi_step_info.target_objt_subtag',
'      , p_level => 3',
'      );',
'      -- process on-event expressions for boundary event',
'      flow_expressions.process_expressions',
'      ( pi_objt_bpmn_id => l_boundary_event  ',
'      , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'      , pi_prcs_id      => pi_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id      => l_new_sbfl.sbfl_id',
'      , pi_step_key     => l_new_sbfl.step_key',
'      , pi_var_scope    => l_parent_sbfl_scope',
'      , pi_expr_scope   => l_parent_sbfl_scope',
'      );     ',
'',
'      if not flow_globals.get_step_error then',
'',
'',
'        if pi_source_type = flow_constants_pkg.gc_bpmn_intermediate_throw_event  ',
'        then ',
'            -- do next_step on triggering subflow if an ITE ',
'            flow_engine.flow_complete_step ',
'            ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'            , p_subflow_id => pi_sbfl_info.sbfl_id ',
'            , p_step_key   => pi_sbfl_info.sbfl_step_key',
'            );',
'        elsif pi_source_type = flow_constants_pkg.gc_bpmn_end_event  ',
'        then',
'            -- normal end event',
'            flow_engine_util.subflow_complete',
'            ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'            , p_subflow_id => pi_sbfl_info.sbfl_id',
'            );',
'        end if;',
'',
'        -- step forward from boundary event',
'        flow_engine.flow_complete_step ',
'        ( p_process_id => pi_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => l_new_sbfl.sbfl_id',
'        , p_step_key   => l_new_sbfl.step_key',
'        );',
'      else',
'        -- set error status on instance and subflow',
'        flow_errors.set_error_status',
'        ( pi_prcs_id => pi_sbfl_info.sbfl_prcs_id',
'        , pi_sbfl_id => pi_sbfl_info.sbfl_id',
'        );',
'      end if;',
'    end if;',
'  end process_escalation;',
'',
'  procedure handle_task_error_boundary_event',
'  ( pi_sbfl_info        in  flow_subflows%rowtype',
'  )',
'  is',
'    l_boundary_event_bpmn_id         flow_objects.objt_bpmn_id%type;',
'    l_boundary_event_is_interrupting boolean;',
'    l_boundary_event_scope           flow_subflows.sbfl_scope%type;',
'  begin',
'    apex_debug.enter  ',
'    ( ''handle_task_error_boundary_event''',
'    , ''current object: '', pi_sbfl_info.sbfl_current',
'    );',
'',
'    get_boundary_event ',
'    ( pi_dgrm_id            => pi_sbfl_info.sbfl_dgrm_id',
'    , pi_throw_objt_bpmn_id => pi_sbfl_info.sbfl_current',
'    , pi_par_sbfl           => pi_sbfl_info.sbfl_id',
'    , pi_sub_tag_name       => flow_constants_pkg.gc_bpmn_error_event_definition',
'    , po_boundary_objt      => l_boundary_event_bpmn_id',
'    , po_is_interrupting    => l_boundary_event_is_interrupting',
'    , po_par_sbfl_scope     => l_boundary_event_scope',
'    );',
'    apex_debug.message',
'    ( p_message => ''Interrupting Error Boundary Event found: %0''  ',
'    , p0        => l_boundary_event_bpmn_id',
'    );',
'    -- handle the error event',
'    handle_interrupting_boundary_event',
'    ( p_process_id      => pi_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id      => pi_sbfl_info.sbfl_id',
'    , p_event_type      => flow_constants_pkg.gc_bpmn_error_event_definition',
'    , p_boundary_object => l_boundary_event_bpmn_id',
'    );',
'  end handle_task_error_boundary_event;',
'',
'end flow_boundary_events;',
'/',
'',
'create or replace package body flow_bpmn_parser_pkg',
'as',
'/* ',
'-- Flows for APEX - flow_bpmn_parser_pkg.pkb',
'-- ',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'--',
'-- Created    2020         Moritz Klein (MT AG)',
'-- Modified   2022-08-10   Moritz Klein (MT AG)',
'-- Modified   2023-03-10   Moritz Klein (MT GmbH)',
'-- Modified   2023-04-12   Moritz Klein (MT GmbH)',
'-- Modified   2023-05-16   Moritz Klein (MT GmbH)',
'-- Modified   2024-07-19   Moritz Klein (Hyand Solutions GmbH)',
'--',
'*/',
'',
'  -- Configuration Settings',
'  g_log_enabled    boolean := false;',
'',
'  -- Variables to hold data during parse run',
'  g_dgrm_id        flow_diagrams.dgrm_id%type;',
'  g_objects        flow_parser_util.t_objt_tab;',
'  g_objt_expr      flow_parser_util.t_objt_expr_tab;',
'  g_connections    flow_parser_util.t_conn_tab;',
'  g_lane_refs      flow_parser_util.t_bpmn_ref_tab;',
'  g_collab_refs    flow_parser_util.t_bpmn_ref_tab;',
'  g_default_cons   flow_parser_util.t_bpmn_id_tab;',
'  g_objt_lookup    flow_parser_util.t_id_lookup_tab;',
'',
'  procedure register_object',
'  (',
'    pi_objt_bpmn_id        in flow_objects.objt_bpmn_id%type',
'  , pi_objt_name           in flow_objects.objt_name%type default null',
'  , pi_objt_tag_name       in flow_objects.objt_tag_name%type default null',
'  , pi_objt_sub_tag_name   in flow_objects.objt_sub_tag_name%type default null',
'  , pi_objt_parent_bpmn_id in flow_objects.objt_bpmn_id%type default null',
'  , pi_objt_attached_to    in flow_objects.objt_attached_to%type default null ',
'  , pi_objt_interrupting   in flow_objects.objt_interrupting%type default null',
'  )',
'  as',
'    l_objt_rec flow_parser_util.t_objt_rec;',
'  begin',
'    if pi_objt_bpmn_id is not null then',
'      if g_objects.exists( pi_objt_bpmn_id ) then',
'        l_objt_rec := g_objects( pi_objt_bpmn_id );',
'      end if;',
'      l_objt_rec.objt_name           := coalesce( pi_objt_name, l_objt_rec.objt_name );',
'      l_objt_rec.objt_tag_name       := coalesce( pi_objt_tag_name, l_objt_rec.objt_tag_name );',
'      l_objt_rec.objt_sub_tag_name   := coalesce( pi_objt_sub_tag_name, l_objt_rec.objt_sub_tag_name );',
'      l_objt_rec.objt_parent_bpmn_id := coalesce( pi_objt_parent_bpmn_id, l_objt_rec.objt_parent_bpmn_id );',
'      l_objt_rec.objt_attached_to    := coalesce( pi_objt_attached_to, l_objt_rec.objt_attached_to );',
'      l_objt_rec.objt_interrupting   := coalesce( pi_objt_interrupting, l_objt_rec.objt_interrupting );',
'',
'      g_objects( pi_objt_bpmn_id ) := l_objt_rec;',
'    end if;',
'  end register_object;',
'',
'  procedure register_object_attribute',
'  (',
'    pi_objt_bpmn_id   in flow_types_pkg.t_bpmn_id',
'  , pi_attribute_name in flow_types_pkg.t_bpmn_attributes_key',
'  , pi_value          in clob',
'  )',
'  as',
'    l_namespace        flow_types_pkg.t_vc200;',
'    l_attribute        flow_types_pkg.t_vc200;',
'    l_namespace_object sys.json_object_t;',
'    l_json_element     sys.json_element_t;',
'  begin',
'',
'    if not g_objects.exists( pi_objt_bpmn_id ) then',
'      register_object( pi_objt_bpmn_id => pi_objt_bpmn_id );',
'    end if;',
'',
'    if g_objects(pi_objt_bpmn_id).objt_attributes is null then',
'            g_objects(pi_objt_bpmn_id).objt_attributes := sys.json_object_t();',
'    end if;',
'',
'    flow_parser_util.property_to_json',
'    (',
'      pi_property_name => pi_attribute_name',
'    , pi_value         => pi_value',
'    , po_namespace     => l_namespace',
'    , po_key           => l_attribute',
'    , po_json_element  => l_json_element',
'    );',
'',
'    if l_namespace is not null then',
'      flow_parser_util.guarantee_named_object',
'      (',
'        pio_attributes => g_objects(pi_objt_bpmn_id).objt_attributes',
'      , pi_key         => l_namespace',
'      );',
'      l_namespace_object := g_objects(pi_objt_bpmn_id).objt_attributes.get_object( l_namespace );',
'    else',
'      l_namespace_object := g_objects(pi_objt_bpmn_id).objt_attributes;',
'    end if;',
'',
'    if l_json_element is not null then',
'      l_namespace_object.put( l_attribute, l_json_element );',
'    elsif pi_value in ( flow_constants_pkg.gc_vcbool_true, flow_constants_pkg.gc_vcbool_false ) then',
'      l_namespace_object.put( l_attribute, (pi_value = flow_constants_pkg.gc_vcbool_true) );',
'    else',
'      l_namespace_object.put( l_attribute, pi_value );',
'    end if;',
'',
'  end register_object_attribute;',
'',
'  procedure register_object_expression',
'  (',
'    pi_objt_bpmn_id     in flow_objects.objt_bpmn_id%type',
'  , pi_expr_set         in flow_object_expressions.expr_set%type',
'  , pi_expr_order       in flow_object_expressions.expr_order%type',
'  , pi_expr_var_name    in flow_object_expressions.expr_var_name%type',
'  , pi_expr_var_type    in flow_object_expressions.expr_var_type%type',
'  , pi_expr_type        in flow_object_expressions.expr_type%type',
'  , pi_expr_expression  in flow_object_expressions.expr_expression%type',
'  , pi_expr_source_type in flow_object_expressions.expr_source_type%type default null',
'  , pi_expr_source      in flow_object_expressions.expr_source%type default null',
'  )',
'  as',
'    l_object_expression flow_parser_util.t_expr_rec;',
'    l_insert_index      pls_integer := 0;',
'  begin',
'    if pi_objt_bpmn_id is not null then',
'      l_object_expression.expr_set         := pi_expr_set;',
'      l_object_expression.expr_order       := pi_expr_order;',
'      l_object_expression.expr_var_name    := pi_expr_var_name;',
'      l_object_expression.expr_var_type    := pi_expr_var_type;',
'      l_object_expression.expr_type        := pi_expr_type;',
'      l_object_expression.expr_expression  := pi_expr_expression;    ',
'      l_object_expression.expr_source_type := pi_expr_source_type;',
'      l_object_expression.expr_source      := pi_expr_source;',
'',
'      -- Verify if we already have some variable expression for same object',
'      if g_objt_expr.exists(pi_objt_bpmn_id) then',
'        l_insert_index := g_objt_expr(pi_objt_bpmn_id).count + 1;',
'      else',
'        l_insert_index := 1;',
'      end if;',
'',
'      g_objt_expr(pi_objt_bpmn_id)(l_insert_index) := l_object_expression;',
'    end if;',
'  end register_object_expression;',
'',
'  procedure register_connection',
'  (',
'    pi_conn_bpmn_id     in flow_connections.conn_bpmn_id%type',
'  , pi_conn_name        in flow_connections.conn_name%type',
'  , pi_conn_src_bpmn_id in flow_objects.objt_bp'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'mn_id%type',
'  , pi_conn_tgt_bpmn_id in flow_objects.objt_bpmn_id%type',
'  , pi_conn_tag_name    in flow_connections.conn_tag_name%type',
'  , pi_conn_origin      in flow_connections.conn_origin%type',
'  , pi_conn_sequence    in flow_connections.conn_sequence%type',
'  , pi_conn_attributes  in sys.json_object_t default null',
'  )',
'  as',
'    l_conn_rec flow_parser_util.t_conn_rec;',
'  begin',
'    if pi_conn_bpmn_id is not null then',
'      l_conn_rec.conn_name        := pi_conn_name;',
'      l_conn_rec.conn_src_bpmn_id := pi_conn_src_bpmn_id;',
'      l_conn_rec.conn_tgt_bpmn_id := pi_conn_tgt_bpmn_id;',
'      l_conn_rec.conn_tag_name    := pi_conn_tag_name;',
'      l_conn_rec.conn_origin      := pi_conn_origin;',
'      l_conn_rec.conn_sequence    := pi_conn_sequence;',
'      l_conn_rec.conn_attributes  := pi_conn_attributes;',
'',
'      g_connections( pi_conn_bpmn_id ) := l_conn_rec;',
'    end if;',
'  end register_connection;',
'',
'  procedure register_connection_attribute',
'  (',
'    pi_conn_bpmn_id   in flow_types_pkg.t_bpmn_id',
'  , pi_attribute_name in flow_types_pkg.t_bpmn_attributes_key',
'  , pi_value          in clob',
'  )',
'  as',
'    l_namespace        flow_types_pkg.t_vc200;',
'    l_attribute        flow_types_pkg.t_vc200;',
'    l_namespace_object sys.json_object_t;',
'    l_json_element     sys.json_object_t;',
'  begin',
'',
'    if g_connections(pi_conn_bpmn_id).conn_attributes is null then',
'      g_connections(pi_conn_bpmn_id).conn_attributes := sys.json_object_t();',
'    end if;',
'',
'    flow_parser_util.property_to_json',
'    (',
'      pi_property_name => pi_attribute_name',
'    , pi_value         => pi_value',
'    , po_namespace     => l_namespace',
'    , po_key           => l_attribute',
'    , po_json_element  => l_json_element',
'    );',
'',
'    if l_namespace is not null then',
'      flow_parser_util.guarantee_named_object',
'      (',
'        pio_attributes => g_connections(pi_conn_bpmn_id).conn_attributes',
'      , pi_key         => l_namespace',
'      );',
'      l_namespace_object := g_connections(pi_conn_bpmn_id).conn_attributes.get_object( l_namespace );',
'    else',
'      l_namespace_object := g_connections(pi_conn_bpmn_id).conn_attributes;',
'    end if;',
'',
'    if l_json_element is not null then',
'      l_namespace_object.put( l_attribute, l_json_element );',
'    elsif pi_value in ( flow_constants_pkg.gc_vcbool_true, flow_constants_pkg.gc_vcbool_false ) then',
'      l_namespace_object.put( l_attribute, (pi_value = flow_constants_pkg.gc_vcbool_true) );',
'    else',
'      l_namespace_object.put( l_attribute, pi_value );',
'    end if;',
'',
'  end register_connection_attribute;',
'',
'  procedure insert_object',
'  (',
'    pi_objt_bpmn_id       in flow_objects.objt_bpmn_id%type',
'  , pi_objt_name          in flow_objects.objt_name%type default null',
'  , pi_objt_tag_name      in flow_objects.objt_tag_name%type default null',
'  , pi_objt_objt_id       in flow_objects.objt_objt_id%type default null',
'  , pi_objt_sub_tag_name  in flow_objects.objt_sub_tag_name%type default null',
'  , pi_objt_objt_lane_id  in flow_objects.objt_objt_lane_id%type default null',
'  , pi_objt_attached_to   in flow_objects.objt_attached_to%type default null',
'  , pi_objt_interrupting  in flow_objects.objt_interrupting%type default null',
'  , pi_objt_attributes    in flow_objects.objt_attributes%type default null',
'  , po_objt_id           out nocopy flow_objects.objt_id%type',
'  )',
'  as',
'  begin',
'    insert',
'      into flow_objects',
'           (',
'             objt_dgrm_id',
'           , objt_bpmn_id',
'           , objt_name',
'           , objt_tag_name',
'           , objt_sub_tag_name',
'           , objt_objt_id',
'           , objt_objt_lane_id',
'           , objt_attached_to',
'           , objt_interrupting',
'           , objt_attributes',
'           )',
'    values (',
'             g_dgrm_id',
'           , pi_objt_bpmn_id',
'           , pi_objt_name',
'           , pi_objt_tag_name',
'           , pi_objt_sub_tag_name',
'           , pi_objt_objt_id',
'           , pi_objt_objt_lane_id',
'           , pi_objt_attached_to',
'           , pi_objt_interrupting',
'           , pi_objt_attributes',
'           )',
'      returning objt_id into po_objt_id',
'    ;',
'  end insert_object;',
'',
'  procedure insert_object_expression',
'  (',
'    pi_expr_objt_id     in flow_object_expressions.expr_objt_id%type',
'  , pi_expr_set         in flow_object_expressions.expr_set%type',
'  , pi_expr_order       in flow_object_expressions.expr_order%type',
'  , pi_expr_var_name    in flow_object_expressions.expr_var_name%type',
'  , pi_expr_var_type    in flow_object_expressions.expr_var_type%type',
'  , pi_expr_type        in flow_object_expressions.expr_type%type',
'  , pi_expr_expression  in flow_object_expressions.expr_expression%type',
'  , pi_expr_source_type in flow_object_expressions.expr_source_type%type default null',
'  , pi_expr_source      in flow_object_expressions.expr_source%type default null',
'  )',
'  as',
'  begin',
'    insert',
'      into flow_object_expressions',
'           (',
'             expr_objt_id',
'           , expr_set',
'           , expr_order',
'           , expr_var_name',
'           , expr_var_type',
'           , expr_type',
'           , expr_expression',
'           , expr_source_type',
'           , expr_source',
'           )',
'    values (',
'             pi_expr_objt_id',
'           , pi_expr_set',
'           , pi_expr_order',
'           , pi_expr_var_name',
'           , upper(pi_expr_var_type)',
'           , pi_expr_type',
'           , pi_expr_expression',
'           , pi_expr_source_type',
'           , pi_expr_source',
'           )',
'    ;',
'  end insert_object_expression;',
'',
'  procedure insert_connection',
'  (',
'    pi_conn_bpmn_id      in flow_connections.conn_bpmn_id%type',
'  , pi_conn_name         in flow_connections.conn_name%type',
'  , pi_conn_src_objt_id  in flow_connections.conn_src_objt_id%type',
'  , pi_conn_tgt_objt_id  in flow_connections.conn_tgt_objt_id%type',
'  , pi_conn_tag_name     in flow_connections.conn_tag_name%type',
'  , pi_conn_origin       in flow_connections.conn_origin%type',
'  , pi_conn_sequence     in flow_connections.conn_sequence%type',
'  , pi_conn_attributes   in flow_connections.conn_attributes%type',
'  , po_conn_id          out flow_connections.conn_id%type',
'  )',
'  as',
'    l_conn_is_default flow_connections.conn_is_default%type := 0;',
'  begin',
'    l_conn_is_default := case when g_default_cons.exists(pi_conn_bpmn_id) then 1 else 0 end;',
'    insert',
'      into flow_connections',
'            (',
'              conn_dgrm_id',
'            , conn_bpmn_id',
'            , conn_name',
'            , conn_src_objt_id',
'            , conn_tgt_objt_id',
'            , conn_tag_name',
'            , conn_origin',
'            , conn_is_default',
'            , conn_sequence',
'            , conn_attributes',
'            )',
'    values (',
'              g_dgrm_id',
'            , pi_conn_bpmn_id',
'            , pi_conn_name',
'            , pi_conn_src_objt_id',
'            , pi_conn_tgt_objt_id',
'            , pi_conn_tag_name',
'            , pi_conn_origin',
'            , l_conn_is_default',
'            , pi_conn_sequence',
'            , pi_conn_attributes',
'            )',
'      returning conn_id into po_conn_id',
'    ;',
'  end insert_connection;',
'',
'  procedure process_object_expressions',
'  (',
'    pi_objt_id       in flow_object_expressions.expr_objt_id%type',
'  , pi_objt_bpmn_id  in flow_types_pkg.t_bpmn_id    ',
'  )',
'  as',
'    l_cur_expressions flow_parser_util.t_expr_tab;',
'    l_cur_index       pls_integer;',
'  begin',
'    if g_objt_expr.exists(pi_objt_bpmn_id) then',
'      l_cur_index       := g_objt_expr(pi_objt_bpmn_id).first;',
'      while l_cur_index is not null loop',
'        insert_object_expression',
'        (',
'          pi_expr_objt_id     => pi_objt_id',
'        , pi_expr_set         => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_set',
'        , pi_expr_order       => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_order',
'        , pi_expr_var_name    => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_var_name',
'        , pi_expr_var_type    => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_var_type',
'        , pi_expr_type        => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_type',
'        , pi_expr_expression  => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_expression',
'        , pi_expr_source_type => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_source_type',
'        , pi_expr_source      => g_objt_expr(pi_objt_bpmn_id)(l_cur_index).expr_source',
'        );',
'        l_cur_index := g_objt_expr(pi_objt_bpmn_id).next(l_cur_index);',
'      end loop;',
'    end if;',
'  end process_object_expressions;',
'',
'  procedure process_objects',
'  as',
'    l_cur_objt_bpmn_id  flow_types_pkg.t_bpmn_id;',
'    l_next_objt_bpmn_id flow_types_pkg.t_bpmn_id;',
'    l_cur_object        flow_parser_util.t_objt_rec;',
'    l_objt_id           flow_objects.objt_id%type;',
'    l_parent_check      boolean;',
'    l_lane_check        boolean;',
'  begin',
'',
'    l_cur_objt_bpmn_id := g_objects.first;',
'    while l_cur_objt_bpmn_id is not null',
'    loop',
'      -- reset object id, we get it if insert done',
'      l_objt_id      := null;',
'      l_cur_object   := g_objects( l_cur_objt_bpmn_id );',
'',
'      -- check possible parent and lane',
'      -- either not set or ID already known',
'      l_parent_check :=',
'           l_cur_object.objt_parent_bpmn_id is null',
'        or (   l_cur_object.objt_parent_bpmn_id is not null',
'           and g_objt_lookup.exists( l_cur_object.objt_parent_bpmn_id )',
'           )',
'      ;',
'      l_lane_check :=',
'           not g_lane_refs.exists( l_cur_objt_bpmn_id )',
'        or ( g_lane_refs.exists( l_cur_objt_bpmn_id )',
'           and g_objt_lookup.exists( g_lane_refs( l_cur_objt_bpmn_id ) )',
'           )',
'      ;',
'',
'      -- checks passed insert into table',
'      if l_parent_check and l_lane_check  then',
'',
'        insert_object',
'        (',
'          pi_objt_bpmn_id      => l_cur_objt_bpmn_id',
'        , pi_objt_name         => l_cur_object.objt_name',
'        , pi_objt_tag_name     => l_cur_object.objt_tag_name',
'        , pi_objt_objt_id      => case when l_cur_object.objt_parent_bpmn_id is not null then g_objt_lookup( l_cur_object.objt_parent_bpmn_id ) else null end',
'        , pi_objt_objt_lane_id => case when g_lane_refs.exists( l_cur_objt_bpmn_id ) then g_objt_lookup( g_lane_refs( l_cur_objt_bpmn_id ) ) else null end',
'        , pi_objt_sub_tag_name => l_cur_object.objt_sub_tag_name',
'        , pi_objt_attached_to  => l_cur_object.objt_attached_to',
'        , pi_objt_interrupting => l_cur_object.objt_interrupting',
'        , pi_objt_attributes   => case when l_cur_object.objt_attributes is not null then l_cur_object.objt_attributes.to_clob else null end',
'        , po_objt_id           => l_objt_id',
'        );',
'',
'        process_object_expressions',
'        (',
'          pi_objt_id      => l_objt_id',
'        , pi_objt_bpmn_id => l_cur_objt_bpmn_id',
'        );',
'',
'      -- checks not passed skip record for now',
'      else',
'        null;',
'      end if;',
'',
'      -- Get next ID for lookup and if object was processed',
'      -- put it into lookup and remove from things to process',
'      l_next_objt_bpmn_id := g_objects.next( l_cur_objt_bpmn_id );',
'      if l_objt_id is not null then',
'',
'        g_objt_lookup( l_cur_objt_bpmn_id ) := l_objt_id;',
'        g_objects.delete( l_cur_objt_bpmn_id );',
'',
'      end if;',
'',
'      l_cur_objt_bpmn_id := l_next_objt_bpmn_id;',
'    end loop;',
'',
'    -- restart with remaining set if still objects to process',
'    if g_objects.count > 0 then',
'      process_objects;',
'    end if;',
'  end process_objects;',
'',
'  procedure process_connections',
'  as',
'    l_cur_conn_bpmn_id flow_types_pkg.t_bpmn_id;',
'    l_cur_conn         flow_parser_util.t_conn_rec;',
'    l_conn_id          flow_connections.conn_id%type;',
'    l_src_objt_id      flow_connections.conn_src_objt_id%type;',
'    l_tgt_objt_id      flow_connections.conn_tgt_objt_id%type;',
'  begin',
'',
'    l_cur_conn_bpmn_id := g_connections.first;',
'    while l_cur_conn_bpmn_id is not null',
'    loop',
'      l_conn_id  := null;',
'      l_src_objt_id := null;',
'      l_tgt_objt_id := null;',
'      l_cur_conn := g_connections( l_cur_conn_bpmn_id );',
'',
'      -- associations may reference connection BPMN IDs (e.g. a sequenceFlow).',
'      -- those endpoints cannot be stored in conn_*_objt_id, so we keep them null.',
'      if l_cur_conn.conn_src_bpmn_id is not null then',
'        if g_objt_lookup.exists( l_cur_conn.conn_src_bpmn_id ) then',
'          l_src_objt_id := g_objt_lookup( l_cur_conn.conn_src_bpmn_id );',
'        elsif l_cur_conn.conn_tag_name = flow_constants_pkg.gc_bpmn_association',
'           and g_connections.exists( l_cur_conn.conn_src_bpmn_id )',
'        then',
'          null;',
'        else',
'          raise_application_error(-20000, ''Connection Source or Target not found!'');',
'        end if;',
'      end if;',
'',
'      if l_cur_conn.conn_tgt_bpmn_id is not null then',
'        if g_objt_lookup.exists( l_cur_conn.conn_tgt_bpmn_id ) then',
'          l_tgt_objt_id := g_objt_lookup( l_cur_conn.conn_tgt_bpmn_id );',
'        elsif l_cur_conn.conn_tag_name = flow_constants_pkg.gc_bpmn_association',
'           and g_connections.exists( l_cur_conn.conn_tgt_bpmn_id )',
'        then',
'          null;',
'        else',
'          raise_application_error(-20000, ''Connection Source or Target not found!'');',
'        end if;',
'      end if;',
'',
'      insert_connection',
'      (',
'        pi_conn_bpmn_id      => l_cur_conn_bpmn_id',
'      , pi_conn_name         => l_cur_conn.conn_name',
'      , pi_conn_src_objt_id  => l_src_objt_id',
'      , pi_conn_tgt_objt_id  => l_tgt_objt_id',
'      , pi_conn_tag_name     => l_cur_conn.conn_tag_name',
'      , pi_conn_origin       => l_cur_conn.conn_origin',
'      , pi_conn_sequence     => l_cur_conn.conn_sequence',
'      , pi_conn_attributes   => case when l_cur_conn.conn_attributes is not null then l_cur_conn.conn_attributes.to_clob else null end',
'      , po_conn_id           => l_conn_id',
'      );',
'',
'      l_cur_conn_bpmn_id := g_connections.next( l_cur_conn_bpmn_id );',
'    end loop;',
'',
'  end process_connections;',
'',
'  procedure finalize',
'  as',
'  begin',
'',
'    process_objects;',
'    process_connections;',
'',
'  end finalize;',
'',
'  function upload_diagram',
'  (',
'    pi_dgrm_name     in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version  in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content  in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status   in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_force_overwrite in boolean default false',
'  )',
'    return flow_diagrams.dgrm_id%type',
'  as',
'    l_cnt     number;',
'    l_dgrm_id flow_diagrams.dgrm_id%type;',
'  begin',
'',
'    begin',
'      select dgrm_id',
'        into l_dgrm_id',
'        from flow_diagrams',
'       where dgrm_name = pi_dgrm_name',
'         and dgrm_version = pi_dgrm_version',
'      ;',
'    exception',
'      when no_data_found then',
'        l_dgrm_id := null;',
'    end;',
'',
'    if l_dgrm_id is null then',
'      insert',
'        into flow_diagrams ( dgrm_name, dgrm_version, dgrm_category, dgrm_status, dgrm_last_update, dgrm_content )',
'        values ( pi_dgrm_name, pi_dgrm_version, pi_dgrm_category, ',
'                 pi_dgrm_status,  systimestamp, pi_dgrm_content )',
'      returning dgrm_id into l_dgrm_id',
'      ;',
'    else',
'      if (pi_force_overwrite) then',
'        update flow_diagrams',
'          set dgrm_content = pi_dgrm_content',
'            , dgrm_last_update = systimestamp',
'            , dgrm_status  = pi_dgrm_status',
'        where dgrm_id = l_dgrm_id',
'        ;',
'      end if;',
'    end if;',
'',
'    return l_dgrm_id;',
'',
'  end upload_diagram;',
'',
'  procedure upload_diagram',
'  (',
'    pi_dgrm_name     in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version  in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content  in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status   in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_force_overwrite in boolean default false',
'  )',
'  as',
'  begin',
'    g_dgrm_id := upload_diagram( pi_dgrm_name => pi_dgrm_name, pi_dgrm_version => pi_dgrm_version,',
'                                 pi_dgrm_category => pi_dgrm_category, pi_dgrm_content => pi_dgrm_content,',
'                                 pi_dgrm_status => pi_dgrm_status, pi_force_overwrite => pi_force_overwrite',
'                                  );',
'  end upload_diagram;',
'',
'  procedure cleanup_parsing_tables',
'  as',
'  begin',
'    delete',
'      from flow_connections conn',
'     where conn.conn_dgrm_id = g_dgrm_id',
'    ;',
'',
'    delete',
'      from flow_objects objt',
'     where objt.objt_dgrm_id = g_dgrm_id',
'    ;',
'  end cleanup_parsing_tables;',
'',
'  procedure parse_page_items',
'  (',
'    pi_bpmn_id         in flow_types_pkg.t_bpmn_id',
'  , pi_page_items_xml  in sys.xmltype',
'  )',
'  as',
'    l_page_item   sys.json_object_t;',
'    l_page_items  sys.json_array_t := sys.json_array_t();',
'    l_apex_object sys.json_object_t;',
'  begin',
'    for rec in (',
'                select items.item_name',
'                     , items.item_value',
'                  from xmltable',
'                       (',
'                         xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'                       , ''*'' passing pi_page_items_xml',
'                         columns',
'                           item_name  varchar2(  50 char) path ''apex:itemName''',
'                         , item_value varchar2(4000 char) path ''apex:itemValue''',
'                       ) items',
'               )',
'    loop',
'      l_page_item := sys.json_object_t();',
'      l_page_item.put( ''name'', rec.item_name );',
'      l_page_item.put( ''value'', rec.item_value );',
'      l_page_items.append( l_page_item );',
'    end loop;',
'    flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_bpmn_id).objt_attributes);',
'',
'    -- Complex JSON types are handled by reference',
'    l_apex_object := g_objects(pi_bpmn_id).objt_attributes.get_object( ''apex'' );',
'    l_apex_object.put( ''pageItems'', l_page_items );',
'  end parse_page_items;',
'  ',
'  procedure parse_parameters',
'  (',
'    pi_bpmn_id        in flow_types_pkg.t_bpmn_id',
'  , pi_parameters_xml in sys.xmltype',
'  )',
'  as',
'    l_param_array clob;',
'    l_apex_object sys.json_object_t;',
'  begin',
'',
'    select json_arrayagg( json_object',
'                          (',
'                            key ''parStaticId'' is parameter_static_id',
'                          , key ''parDataType'' is parameter_data_type',
'                          , key ''parValue''    is parameter_value',
'                          )',
'                        ) as par_obj',
'      into l_param_array',
'      from xmltable',
'           (',
'             xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'           , ''*'' passing pi_parameters_xml',
'             columns',
'               parameter_static_id varchar2(  50 char) path ''apex:parStaticId''',
'             , parameter_data_type varchar2(  50 char) path ''apex:parDataType''',
'             , parameter_value     varchar2(4000 char) path ''apex:parValue''',
'           )',
'    ;',
'',
'    if l_param_array is not null then',
'      flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_bpmn_id).objt_attributes );',
'      l_apex_object := g_objects(pi_bpmn_id).objt_attributes.get_object( ''apex'' );',
'      l_apex_object.put( ''parameters'', sys.json_array_t.parse( l_param_array ) );',
'    end if;',
'  end parse_parameters;',
'',
'  procedure parse_task_parameters',
'  (',
'    pi_bpmn_id            in flow_types_pkg.t_bpmn_id',
'  , pi_parameter_set_name in varchar2',
'  , pi_parameters_xml     in sys.xmltype',
'  )',
'  as',
'    l_apex_object     sys.json_object_t;',
'    l_parameter_array sys.json_array_t := sys.json_array_t();',
'    l_parameter       sys.json_object_t;',
'    l_source          sys.json_object_t;',
'    l_apex_rendering  sys.json_object_t;',
'    l_default_json    sys.json_object_t;',
'    l_default_element sys.json_element_t;',
'    l_default_text    clob;',
'    l_parameter_type  varchar2(20 char);',
'    l_required_value  varchar2(20 char);',
'    l_enum_namespace  flow_types_pkg.t_vc200;',
'    l_enum_key        flow_types_pkg.t_vc200;',
'    l_enum_element    sys.json_element_t;',
'  begin',
'    for rec in (',
'      select parameter_name',
'           , parameter_type',
'           , parameter_required',
'           , parameter_default',
'           , parameter_description',
'           , source_expression_type',
'           , source_expression',
'           , apex_item_type',
'           , apex_max_length',
'           , apex_placeholder',
'           , apex_enum',
'        from xmltable',
'             (',
'               xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'             , ''*'' passing pi_parameters_xml',
'               columns',
'                 parameter_name          varchar2(4000 char) path ''apex:name''',
'               , parameter_type          varchar2(4000 char) path ''apex:type''',
'               , parameter_required      varchar2(  20 char) path ''apex:required''',
'               , parameter_default       clob                path ''apex:default''',
'               , parameter_description   clob                path ''apex:description''',
'               , source_expression_type  varchar2(4000 char) path ''apex:source/apex:expressionType''',
'               , source_expression       clob                path ''apex:source/apex:expression''',
'               , apex_item_type          varchar2(4000 char) path ''apex:apexRendering/apex:itemType''',
'               , apex_max_length         number              path ''apex:apexRendering/apex:maxLength''',
'               , apex_placeholder        clob                path ''apex:apexRendering/apex:placeholder''',
'               , apex_enum               clob                path ''apex:apexRendering/apex:enum''',
'             )',
'    )',
'    loop',
'      l_parameter := sys.json_object_t();',
'',
'      if rec.parameter_name is not null then',
'        l_parameter.put( ''name'', rec.parameter_name );',
'      end if;',
'',
'      if rec.parameter_type is not null then',
'        l_parameter.put( ''type'', rec.parameter_type );',
'      end if;',
'',
'      l_parameter_type := lower( trim( rec.parameter_type ) );',
'',
'      l_required_value := lower(trim(rec.parameter_required));',
'      if l_required_value = flow_constants_pkg.gc_vcbool_true then',
'        l_parameter.put( ''required'', true );',
'      elsif l_required_value = flow_constants_pkg.gc_vcbool_false then',
'        l_parameter.put( ''required'', false );',
'      elsif rec.parameter_required is not null then',
'        l_parameter.put( ''required'', rec.parameter_required );',
'      end if;',
'',
'      if rec.parameter_default is not null then',
'        l_default_text := trim( rec.parameter_default );',
'',
'        if l_parameter_type = ''string'' then',
'          l_parameter.put( ''default'', rec.parameter_default );',
'        elsif l_parameter_type = ''boolean'' then',
'          if lower( l_default_text ) = flow_constants_pkg.gc_vcbool_true then',
'            l_parameter.put( ''default'', true );',
'          elsif lower( l_default_text ) = flow_constants_pkg.gc_vcbool_false then',
'            l_parameter.put( ''default'', false );',
'          else',
'            l_parameter.put( ''default'', rec.parameter_default );',
'          end if;',
'        else',
'          begin',
'            l_default_json := sys.json_object_t.parse( ''{"default":'' || l_default_text || ''}'' );',
'            l_default_element := l_default_json.get( ''default'' );',
'            l_parameter.put( ''default'', l_default_element );',
'          exception',
'            when others then',
'              -- Keep backward-compatible behavior for plain text defaults like standard.',
'              l_parameter.put( ''default'', rec.parameter_default );',
'          end;',
'        end if;',
'      end if;',
'',
'      if rec.parameter_description is not null then',
'        l_parameter.put( ''description'', rec.parameter_description );',
'      end if;',
'',
'      if rec.source_expression_type is not null or rec.source_expression is not null then',
'        l_source := sys.json_object_t();',
'',
'        if rec.source_expression_type is not null then',
'          l_source.put( ''expressionType'', rec.source_expression_type );',
'        end if;',
'',
'        if rec.source_expression is not null then',
'          l_source.put( ''expression'', rec.source_expression );',
'        end if;',
'',
'        l_parameter.put( ''source'', l_source );',
'      end if;',
'',
'      if rec.apex_item_type is not null',
'         or rec.apex_max_length is not null',
'         or rec.apex_placeholder is not null',
'         or rec.apex_enum is not null',
'      then',
'        l_apex_rendering := sys.json_object_t();',
'',
'        if rec.apex_item_type is not null then',
'          l_apex_rendering.put( ''itemType'', rec.apex_item_type );',
'        end if;',
'',
'        if rec.apex_max_length is not null then',
'          l_apex_rendering.put( ''maxLength'', rec.apex_max_length );',
'        end if;',
'',
'        if rec.apex_placeholder is not null',
'           and length( trim( dbms_lob.substr( rec.apex_placeholder, 32767, 1 ) ) ) > 0',
'        then',
'          l_apex_rendering.put( ''placeholder'', rec.apex_placeholder );',
'        end if;',
'',
'        if rec.apex_enum is not null then',
'          begin',
'            flow_parser_util.property_to_json',
'            (',
'              pi_property_name => flow_constants_pkg.gc_apex_parameter_enum',
'            , pi_value         => rec.apex_enum',
'            , po_namespace     => l_enum_namespace',
'            , po_key           => l_enum_key',
'            , po_json_element  => l_enum_element',
'            );',
'            if l_enum_element is not null then',
'              l_apex_rendering.put( ''enum'', l_enum_element );',
'            else',
'              l_apex_rendering.put( ''enum'', rec.apex_enum );',
'            end if;',
'          exception',
'            when others then',
'              l_apex_rendering.put( ''enum'', rec.apex_enum );',
'          end;',
'        end if;',
'',
'        l_parameter.put( ''apexRendering'', l_apex_rendering );',
'      end if;',
'',
'      l_parameter_array.append( l_parameter );',
'    end loop;',
'',
'    if l_parameter_array.get_size > 0 then',
'      if not g_objects.exists( pi_bpmn_id ) then',
'        register_object( pi_objt_bpmn_id => pi_bpmn_id );',
'        g_objects(pi_bpmn_id).objt_attributes := sys.json_object_t();',
'      end if;',
'      flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_bpmn_id).objt_attributes );',
'      l_apex_object := g_objects(pi_bpmn_id).objt_attributes.get_object( ''apex'' );',
'      l_apex_object.put( flow_parser_util.get_property_key( pi_parameter_set_name ), l_parameter_array );',
'    end if;',
'  end parse_task_parameters;',
'',
'  procedure parse_task_subtypes',
'  (',
'    pi_bpmn_id     in flow_types_pkg.t_bpmn_id',
'  , pi_subtype_xml in sys.xmltype',
'  )',
'  as',
'    l_namespace        flow_types_pkg.t_vc200;',
'    l_attribute        flow_types_pkg.t_vc200;',
'    l_json_element     sys.json_element_t;',
'    l_namespace_object sys.json_object_t;',
'  begin',
'',
'    for rec in (',
'                select props.prop_name',
'                     , props.prop_value',
'                     , props.prop_children',
'                  from xmltable',
'                       (',
'                         xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                      , ''https://flowsforapex.org'' as "apex")',
'                       , ''*'' passing pi_subtype_xml',
'                         columns',
'                           prop_name     varchar2(50 char) path ''name()''',
'                         , prop_value    clob              path ''text()''',
'                         , prop_children sys.xmltype       path ''* except bpmn:incoming except bpmn:outgoing''',
'                       ) props',
'               )',
'    loop',
'      -- User Task: nested page items are handled separately',
'      if rec.prop_name = flow_constants_pkg.gc_apex_usertask_page_items then',
'        parse_page_items',
'        (',
'          pi_bpmn_id        => pi_bpmn_id',
'        , pi_page_items_xml => rec.prop_children',
'        );',
'      -- Array of Parameter Bindings, used by Unified Tasklist Integration',
'      elsif rec.prop_name = flow_constants_pkg.gc_apex_usertask_parameters then',
'        parse_parameters',
'        (',
'          pi_bpmn_id        => pi_bpmn_id',
'        , pi_parameters_xml => rec.prop_children',
'        );',
'      -- Task Input / Output Parameters',
'      elsif rec.prop_name in ( flow_constants_pkg.gc_apex_input_parameters',
'                             , flow_constants_pkg.gc_apex_output_parameters',
'                             )',
'      then',
'        parse_task_parameters',
'        (',
'          pi_bpmn_id            => pi_bpmn_id',
'        , pi_parameter_set_name => rec.prop_name',
'        , pi_parameters_xml     => rec.prop_children',
'        );',
'      elsif length(rec.prop_value) > 0 then',
'        flow_parser_util.property_to_json',
'        (',
'          pi_property_name => rec.prop_name',
'        , pi_value         => rec.prop_value',
'        , po_namespace     => l_namespace',
'        , po_key           => l_attribute',
'        , po_json_element  => l_json_element',
'        );',
'',
'        flow_parser_util.guarantee_named_object( pio_attributes => g_objects(pi_bpmn_id).objt_attributes, pi_key => l_namespace );',
'        l_namespace_object := g_objects(pi_bpmn_id).objt_attributes.get_object( l_namespace );',
'        if l_json_element is not null then',
'          l_namespace_object.put( l_attribute, l_json_element );',
'        else',
'          -- Need to create real booleans in JSON',
'          if rec.prop_value in ( flow_constants_pkg.gc_vcbool_true, flow_constants_pkg.gc_vcbool_false ) then',
'            l_namespace_object.put( l_attribute, ( rec.prop_value = flow_constants_pkg.gc_vcbool_true ) );',
'          else',
'            l_namespace_object.put( l_attribute, rec.prop_value );',
'          end if;',
'        end if;',
'      --Empty properties will not be stored',
'      else',
'        null;',
'      end if;',
'    end loop;',
'  end parse_task_subtypes;',
'',
'  procedure parse_process_variables',
' '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' (',
'    pi_bpmn_id         in flow_types_pkg.t_bpmn_id',
'  , pi_execution_point in varchar2',
'  , pi_proc_vars_xml   in sys.xmltype',
'  )',
'  as',
'  begin',
'    for rec in (',
'                select variable_sequence',
'                     , variable_name',
'                     , case variable_type',
'                         when ''TIMESTAMP_WITH_TIME_ZONE'' then ''TIMESTAMP WITH TIME ZONE''',
'                         else variable_type',
'                       end as variable_type',
'                     , expression_type',
'                     , expression_value',
'                     , source_type',
'                     , source',
'                  from xmltable',
'                       (',
'                         xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'                       , ''*'' passing pi_proc_vars_xml',
'                         columns',
'                           variable_sequence number              path ''apex:varSequence''',
'                         , variable_name     varchar2(50 char)   path ''apex:varName''',
'                         , variable_type     varchar2(50 char)   path ''apex:varDataType''',
'                         , expression_type   varchar2(200 char)  path ''apex:varExpressionType''',
'                         , expression_value  varchar2(4000 char) path ''apex:varExpression''',
'                         , source_type varchar2(50 char)         path ''apex:varSourceType''',
'                         , source      varchar2(50 char)         path ''apex:varSource''',
'                       )',
'               )',
'    loop',
'      register_object_expression',
'      (',
'        pi_objt_bpmn_id     => pi_bpmn_id',
'      , pi_expr_set         => pi_execution_point',
'      , pi_expr_order       => rec.variable_sequence',
'      , pi_expr_var_name    => rec.variable_name',
'      , pi_expr_var_type    => rec.variable_type',
'      , pi_expr_type        => rec.expression_type',
'      , pi_expr_expression  => rec.expression_value',
'      , pi_expr_source_type => rec.source_type',
'      , pi_expr_source      => rec.source',
'      );',
'    end loop;',
'  end parse_process_variables;',
'',
'  procedure parse_custom_timers',
'  (',
'    pi_bpmn_id     in flow_types_pkg.t_bpmn_id',
'  , pi_subtype_xml in sys.xmltype',
'  )',
'  as',
'    l_namespace        flow_types_pkg.t_vc200;',
'    l_attribute        flow_types_pkg.t_vc200;',
'    l_namespace_object sys.json_object_t;',
'    l_json_element     sys.json_element_t;',
'  begin',
'',
'    for rec in (',
'                select props.prop_name',
'                     , props.prop_value',
'                     , props.prop_children',
'                  from xmltable',
'                       (',
'                         xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                      , ''https://flowsforapex.org'' as "apex")',
'                       , ''*'' passing pi_subtype_xml',
'                         columns',
'                           prop_name     varchar2(50 char)    path ''name()''',
'                         , prop_value    varchar2(4000 char)  path ''text()''',
'                         , prop_children sys.xmltype          path ''* except bpmn:incoming except bpmn:outgoing''',
'                       ) props',
'               )',
'    loop',
'      if length(rec.prop_value) > 0 then',
'        flow_parser_util.property_to_json',
'        (',
'          pi_property_name => rec.prop_name',
'        , pi_value         => rec.prop_value',
'        , po_namespace     => l_namespace',
'        , po_key           => l_attribute',
'        , po_json_element  => l_json_element',
'        );',
'',
'        flow_parser_util.guarantee_named_object( pio_attributes => g_objects(pi_bpmn_id).objt_attributes, pi_key => l_namespace );',
'        l_namespace_object := g_objects(pi_bpmn_id).objt_attributes.get_object( l_namespace );',
'        if l_json_element is not null then',
'          l_namespace_object.put( l_attribute, l_json_element );',
'        else',
'          l_namespace_object.put( l_attribute, rec.prop_value );',
'        end if;',
'      end if;',
'    end loop;',
'  end parse_custom_timers;',
'',
'  procedure parse_simple_expression',
'  (',
'    pi_objt_bpmn_id in flow_types_pkg.t_bpmn_id',
'  , pi_ext_type     in varchar2',
'  , pi_exp_type     in varchar2',
'  , pi_exp_fmt_mask in varchar2',
'  , pi_exp_val      in clob',
'  )',
'  as',
'    l_apex_object sys.json_object_t;',
'    l_ext_object  sys.json_object_t := sys.json_object_t();',
'  begin',
'    if not g_objects.exists( pi_objt_bpmn_id ) then',
'      register_object( pi_objt_bpmn_id => pi_objt_bpmn_id );',
'      g_objects(pi_objt_bpmn_id).objt_attributes := sys.json_object_t();',
'    end if;',
'    flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_objt_bpmn_id).objt_attributes );',
'    l_apex_object := g_objects(pi_objt_bpmn_id).objt_attributes.get_object( ''apex'' );',
'',
'    l_ext_object.put( ''expressionType'', pi_exp_type );',
'    if pi_exp_type in ( flow_constants_pkg.gc_expr_type_sql, flow_constants_pkg.gc_expr_type_sql_delimited_list',
'                      , flow_constants_pkg.gc_expr_type_plsql_expression, flow_constants_pkg.gc_expr_type_plsql_function_body',
'                      , flow_constants_pkg.gc_expr_type_plsql_raw_expression, flow_constants_pkg.gc_expr_type_plsql_raw_function_body',
'                      )',
'    then',
'      l_ext_object.put( ''expression'', flow_parser_util.get_lines_array( pi_str => pi_exp_val ) );',
'    else',
'      l_ext_object.put( ''expression'', pi_exp_val );',
'    end if;',
'',
'    if pi_exp_fmt_mask is not null then',
'      l_ext_object.put( ''formatMask'', pi_exp_fmt_mask );',
'    end if;',
'',
'    l_apex_object.put( replace(pi_ext_type, ''apex:''), l_ext_object );',
'  end parse_simple_expression;',
'',
'  procedure parse_extension_elements',
'  (',
'    pi_bpmn_id       in flow_types_pkg.t_bpmn_id',
'  , pi_extension_xml in sys.xmltype',
'  )',
'  as',
'  begin',
'',
'    if g_log_enabled then',
'      flow_parser_util.log',
'      (',
'        pi_plog_dgrm_id    => g_dgrm_id',
'      , pi_plog_bpmn_id    => pi_bpmn_id',
'      , pi_plog_parse_step => ''parse_extension_elements''',
'      , pi_plog_payload    => pi_extension_xml',
'      );',
'    end if;',
'    ',
'    for rec in (',
'                select replace(extension_type, ''apex:'') as extension_type',
'                     , extension_type as orig_extension_type',
'                     , extension_data',
'                     , extension_exp_type',
'                     , extension_exp_val',
'                     , extension_fmt_mask',
'                     , extension_text',
'                  from xmltable',
'                       (',
'                         xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'                       , ''/bpmn:extensionElements/*'' passing pi_extension_xml',
'                         columns',
'                           extension_type     varchar2( 50 char) path ''name()''',
'                         , extension_data     sys.xmltype        path ''*''',
'                         , extension_exp_type varchar2( 50 char) path ''apex:expressionType''',
'                         , extension_exp_val  clob               path ''apex:expression''',
'                         , extension_fmt_mask varchar2(200 char) path ''apex:formatMask''',
'                         , extension_text     clob               path ''text()''',
'                       ) ',
'               )',
'    loop',
'      -- Process Variables',
'      if rec.extension_type in ( flow_constants_pkg.gc_expr_set_before_task, flow_constants_pkg.gc_expr_set_after_task',
'                               , flow_constants_pkg.gc_expr_set_before_split, flow_constants_pkg.gc_expr_set_after_merge',
'                               , flow_constants_pkg.gc_expr_set_before_event, flow_constants_pkg.gc_expr_set_on_event',
'                               , flow_constants_pkg.gc_expr_set_in_variables, flow_constants_pkg.gc_expr_set_out_variables',
'                               )',
'      then',
'        parse_process_variables',
'        (',
'          pi_bpmn_id         => pi_bpmn_id',
'        , pi_execution_point => rec.extension_type',
'        , pi_proc_vars_xml   => rec.extension_data',
'        );',
'      -- Task Subtypes',
'      elsif rec.extension_type in ( flow_constants_pkg.gc_apex_usertask_apex_page',
'                                  , flow_constants_pkg.gc_apex_usertask_apex_approval',
'                                  , flow_constants_pkg.gc_apex_usertask_apex_simple_form',
'                                  , flow_constants_pkg.gc_apex_usertask_external_url',
'                                  , flow_constants_pkg.gc_apex_servicetask_send_mail',
'                                  , flow_constants_pkg.gc_apex_task_execute_plsql',
'                                  )',
'      then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_bpmn_id',
'        , pi_attribute_name => flow_constants_pkg.gc_task_type_key',
'        , pi_value          => rec.extension_type',
'        );',
'  ',
'        -- parse properties',
'        parse_task_subtypes',
'        (',
'          pi_bpmn_id     => pi_bpmn_id',
'        , pi_subtype_xml => rec.extension_data',
'        );',
'      -- Custom Timers',
'      elsif rec.extension_type in ( flow_constants_pkg.gc_timer_type_oracle_date',
'                                  , flow_constants_pkg.gc_timer_type_oracle_duration',
'                                  , flow_constants_pkg.gc_timer_type_oracle_cycle',
'                                  )',
'      then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_bpmn_id',
'        , pi_attribute_name => flow_constants_pkg.gc_timer_type_key',
'        , pi_value          => rec.extension_type',
'        );',
'        g_objects(pi_bpmn_id).objt_sub_tag_name := flow_constants_pkg.gc_bpmn_timer_event_definition;',
'',
'        -- parse properties',
'        parse_custom_timers',
'        (',
'          pi_bpmn_id     => pi_bpmn_id',
'        , pi_subtype_xml => rec.extension_data',
'        );',
'      -- Task Input / Output Parameters stored as extensionElements siblings',
'      elsif rec.extension_type in ( flow_parser_util.get_property_key( flow_constants_pkg.gc_apex_input_parameters )',
'                                  , flow_parser_util.get_property_key( flow_constants_pkg.gc_apex_output_parameters )',
'                                  )',
'      then',
'        parse_task_parameters',
'        (',
'          pi_bpmn_id            => pi_bpmn_id',
'        , pi_parameter_set_name => rec.orig_extension_type',
'        , pi_parameters_xml     => rec.extension_data',
'        );',
'      -- Standard Expressions with expressionType and expression nested',
'      elsif rec.extension_exp_type is not null then',
'        if g_log_enabled then',
'          flow_parser_util.log',
'          (',
'            pi_plog_dgrm_id    => g_dgrm_id',
'          , pi_plog_bpmn_id    => pi_bpmn_id',
'          , pi_plog_parse_step => ''when standard expression''',
'          , pi_plog_payload    => ''extension_type: '' || rec.extension_type',
'          );',
'        end if;',
'',
'        parse_simple_expression',
'        (',
'          pi_objt_bpmn_id => pi_bpmn_id',
'        , pi_ext_type     => rec.extension_type',
'        , pi_exp_type     => rec.extension_exp_type',
'        , pi_exp_fmt_mask => rec.extension_fmt_mask',
'        , pi_exp_val      => rec.extension_exp_val',
'        );',
'      else',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_bpmn_id',
'        , pi_attribute_name => rec.orig_extension_type',
'        , pi_value          => rec.extension_text',
'        );',
'      end if;',
'    end loop;',
'  end parse_extension_elements;',
'',
'  procedure parse_iterator_attributes',
'  (',
'    pi_objt_bpmn_id       in flow_types_pkg.t_bpmn_id',
'  , pi_iterator_type      in varchar2',
'  , pi_is_sequential      in varchar2',
'  , pi_extension_elements in sys.xmltype',
'  )',
'  as',
'    l_apex_object      sys.json_object_t;',
'    l_iterator_object  sys.json_object_t := sys.json_object_t();',
'    l_ext_object       sys.json_object_t;',
'  begin',
'    if g_log_enabled then',
'      flow_parser_util.log',
'      (',
'        pi_plog_dgrm_id    => g_dgrm_id',
'      , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'      , pi_plog_parse_step => ''parse_iterator_attributes''',
'      , pi_plog_payload    => pi_extension_elements',
'      );',
'    end if;',
'',
'    if not g_objects.exists( pi_objt_bpmn_id ) then',
'      register_object( pi_objt_bpmn_id => pi_objt_bpmn_id );',
'      g_objects(pi_objt_bpmn_id).objt_attributes := sys.json_object_t();',
'    end if;',
'    flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_objt_bpmn_id).objt_attributes );',
'    l_apex_object := g_objects(pi_objt_bpmn_id).objt_attributes.get_object( ''apex'' );',
'',
'    l_iterator_object.put( key => ''isSequential'', val => case when pi_is_sequential = flow_constants_pkg.gc_vcbool_true then true else false end );',
'',
'    for rec in (',
'                select replace(extension_type, ''apex:'') as extension_type',
'                     , extension_type as orig_extension_type',
'                     , extension_data',
'                     , extension_exp_type',
'                     , extension_exp_val',
'                     , inside_variable',
'                     , extension_text',
'                  from xmltable',
'                       (',
'                         xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn", ''https://flowsforapex.org'' as "apex" )',
'                       , ''/bpmn:extensionElements/*'' passing pi_extension_elements',
'                         columns',
'                           extension_type     varchar2(  50 char) path ''name()''',
'                         , extension_data     sys.xmltype         path ''*''',
'                         , extension_exp_type varchar2(  50 char) path ''apex:expressionType''',
'                         , extension_exp_val  clob                path ''apex:expression''',
'                         , inside_variable    varchar2(4000 char) path ''apex:insideVariable''',
'                         , extension_text     clob                path ''text()''',
'                       ) ',
'               )',
'    loop',
'',
'      l_ext_object := sys.json_object_t();',
'',
'      if rec.extension_exp_type != flow_constants_pkg.gc_apex_iterator_description then',
'        l_ext_object.put( key => ''expressionType'', val => rec.extension_exp_type );',
'',
'        if rec.extension_exp_type in ( flow_constants_pkg.gc_expr_type_sql, flow_constants_pkg.gc_expr_type_sql_delimited_list',
'                                    , flow_constants_pkg.gc_expr_type_plsql_expression, flow_constants_pkg.gc_expr_type_plsql_function_body',
'                                    , flow_constants_pkg.gc_expr_type_plsql_raw_expression, flow_constants_pkg.gc_expr_type_plsql_raw_function_body',
'                                    )',
'        then',
'          l_ext_object.put( ''expression'', flow_parser_util.get_lines_array( pi_str => rec.extension_exp_val ) );',
'        else',
'          l_ext_object.put( ''expression'', rec.extension_exp_val );',
'        end if;',
'',
'        if rec.inside_variable is not null then',
'          l_ext_object.put( key => ''insideVariable'', val => rec.inside_variable );',
'        end if;',
'',
'        l_iterator_object.put( key => rec.extension_type, val => l_ext_object );',
'      else',
'        if rec.extension_text is not null then',
'          l_iterator_object.put( key => ''description'', val => rec.extension_text );',
'        end if;',
'      end if;',
'    end loop;',
'    ',
'    l_apex_object.put( key => replace( pi_iterator_type, ''bpmn:'' ), val => l_iterator_object );',
'',
'  end parse_iterator_attributes;',
'',
'  procedure parse_flow_node_refs',
'  (',
'    pi_lane_refs_xml  in sys.xmltype',
'  , pi_parent_bpmn_id in flow_types_pkg.t_bpmn_id',
'  )',
'  as',
'  begin',
'    for node_rec in (',
'        select nodes.node_ref',
'          from xmltable',
'             (',
'               xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'             , ''*'' passing pi_lane_refs_xml',
'               columns',
'                 node_ref   varchar2(50 char) path ''text()''',
'             ) nodes',
'    ) loop',
'      g_lane_refs( node_rec.node_ref ) := pi_parent_bpmn_id;',
'    end loop;',
'  end parse_flow_node_refs;',
'',
'  procedure parse_laneset',
'  (',
'    pi_laneset_xml    in sys.xmltype',
'  , pi_parent_bpmn_id in flow_types_pkg.t_bpmn_id',
'  )',
'  as',
'    l_laneset_id  flow_types_pkg.t_bpmn_id;',
'    l_laneset_tag flow_types_pkg.t_bpmn_id;',
'    l_lanes_xml   sys.xmltype;',
'  begin',
'',
'    select laneset_id',
'         , laneset_tag',
'         , lanes_xml',
'      into l_laneset_id',
'         , l_laneset_tag',
'         , l_lanes_xml',
'      from xmltable',
'           (',
'             xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                           , ''https://flowsforapex.org'' as "apex")',
'           , ''*'' passing pi_laneset_xml',
'             columns',
'               laneset_id    varchar2(50 char) path ''@id''',
'             , laneset_tag   varchar2(50 char) path ''name()''',
'             , lanes_xml     sys.xmltype       path ''*''',
'           )',
'    ;',
'',
'    register_object',
'    (',
'      pi_objt_bpmn_id        => l_laneset_id',
'    , pi_objt_tag_name       => l_laneset_tag',
'    , pi_objt_parent_bpmn_id => pi_parent_bpmn_id',
'    );',
'',
'    for lane_rec in (',
'      select lane_id',
'           , lane_name',
'           , lane_type',
'           , lane_is_role',
'           , lane_role',
'           , node_refs',
'           , child_laneset',
'           , lane_extensions',
'        from xmltable',
'             (',
'               xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                             , ''https://flowsforapex.org'' as "apex"',
'                             )',
'             , ''*'' passing l_lanes_xml',
'               columns',
'                 lane_id         varchar2( 50 char) path ''@id''',
'               , lane_name       varchar2(200 char) path ''@name''',
'               , lane_type       varchar2( 50 char) path ''name()''',
'               , lane_is_role    varchar2( 50 char) path ''@apex:isRole''',
'               , lane_role       varchar2(200 char) path ''@apex:role''',
'               , node_refs       sys.xmltype        path ''* except bpmn:childLaneSet except bpmn:extensionElements''',
'               , child_laneset   sys.xmltype        path ''bpmn:childLaneSet''',
'               , lane_extensions sys.xmltype        path ''bpmn:extensionElements''',
'             )',
'    ) loop',
'',
'      register_object',
'      (',
'        pi_objt_bpmn_id        => lane_rec.lane_id',
'      , pi_objt_name           => lane_rec.lane_name',
'      , pi_objt_tag_name       => lane_rec.lane_type',
'      , pi_objt_parent_bpmn_id => l_laneset_id',
'      );',
'',
'      if lane_rec.lane_is_role is not null then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => lane_rec.lane_id',
'        , pi_attribute_name => ''apex:isRole''',
'        , pi_value          => lane_rec.lane_is_role',
'        );',
'      end if;',
'',
'      if lane_rec.lane_is_role is not null then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => lane_rec.lane_id',
'        , pi_attribute_name => ''apex:role''',
'        , pi_value          => lane_rec.lane_role',
'        );',
'      end if;',
'',
'      parse_extension_elements',
'      (',
'        pi_bpmn_id       => lane_rec.lane_id',
'      , pi_extension_xml => lane_rec.lane_extensions',
'      );',
'',
'      if lane_rec.child_laneset is not null then',
'        -- ignore flowNodeRefs on this level as they duplicate lower levels',
'        -- jump into childLaneSet parsing (recursion)',
'        parse_laneset',
'        (',
'          pi_laneset_xml    => lane_rec.child_laneset',
'        , pi_parent_bpmn_id => lane_rec.lane_id',
'        );',
'      else',
'        parse_flow_node_refs',
'        (',
'          pi_lane_refs_xml  => lane_rec.node_refs',
'        , pi_parent_bpmn_id => lane_rec.lane_id',
'        );',
'      end if;',
'',
'    end loop;',
'',
'  end parse_laneset;',
'',
'  function find_subtag_name',
'  (',
'    pi_xml in sys.xmltype',
'  )',
'    return flow_types_pkg.t_bpmn_id',
'  as',
'    c_nsmap        constant flow_types_pkg.t_vc200 := flow_constants_pkg.gc_nsmap;',
'    l_return                flow_types_pkg.t_bpmn_id;',
'  begin',
'    l_return :=',
'      case',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_terminate_event_definition, nsmap => c_nsmap ) = 1   then flow_constants_pkg.gc_bpmn_terminate_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_timer_event_definition, nsmap => c_nsmap ) = 1       then flow_constants_pkg.gc_bpmn_timer_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_timer_type_date, nsmap => c_nsmap ) = 1                   then flow_constants_pkg.gc_timer_type_date',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_timer_type_duration, nsmap => c_nsmap ) = 1               then flow_constants_pkg.gc_timer_type_duration',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_timer_type_cycle, nsmap => c_nsmap ) = 1                  then flow_constants_pkg.gc_timer_type_cycle',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_error_event_definition, nsmap => c_nsmap ) = 1       then flow_constants_pkg.gc_bpmn_error_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_escalation_event_definition, nsmap => c_nsmap ) = 1  then flow_constants_pkg.gc_bpmn_escalation_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_link_event_definition, nsmap => c_nsmap ) = 1        then flow_constants_pkg.gc_bpmn_link_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_message_event_definition, nsmap => c_nsmap ) = 1     then flow_constants_pkg.gc_bpmn_message_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_conditional_event_definition, nsmap => c_nsmap ) = 1 then flow_constants_pkg.gc_bpmn_conditional_event_definition',
'        when pi_xml.existsNode( xpath => ''/'' || flow_constants_pkg.gc_bpmn_signal_event_definition, nsmap => c_nsmap ) = 1      then flow_constants_pkg.gc_bpmn_signal_event_definition',
'        else null',
'      end',
'    ;',
'',
'    return l_return;',
'  end find_subtag_name;',
'',
'  procedure parse_process_extensions',
'  (',
'    pi_objt_bpmn_id in flow_types_pkg.t_bpmn_id',
'  , pi_xml          in sys.xmltype',
'  )',
'  as',
'    l_apex_object  sys.json_object_t;',
'    l_var_array    flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    flow_parser_util.guarantee_apex_object( pio_attributes => g_objects(pi_objt_bpmn_id).objt_attributes );',
'    l_apex_object := g_objects(pi_objt_bpmn_id).objt_attributes.get_object( ''apex'' );',
'',
'    -- Extensions which use expressionType + expression structure',
'    for rec in (',
'      select ext_type',
'           , exp_type',
'           , exp_value',
'           , exp_fmt_mask',
'           , ext_text',
'        from xmltable',
'             (',
'               xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                             , ''https://flowsforapex.org'' as "apex")',
'             , ''/bpmn:extensionElements/*'' passing pi_xml',
'               columns',
'                 ext_type     varchar2( 50 char) path ''name()''',
'               , exp_type     varchar2( 50 char) path ''apex:expressionType''',
'               , exp_value    clob               path ''apex:expression''',
'               , exp_fmt_mask varchar2(200 char) path ''apex:formatMask''',
'               , ext_text     clob               path ''text()''',
'             ) ext',
'    ) loop',
'      if rec.exp_type is not null then',
'        parse_simple_expression',
'        (',
'          pi_objt_bpmn_id => pi_objt_bpmn_id',
'        , pi_ext_type     => rec.ext_type',
'        , pi_exp_type     => rec.exp_type',
'        , pi_exp_fmt_mask => rec.exp_fmt_mask',
'        , pi_exp_val      => rec.exp_value',
'        );',
'      elsif rec.ext_type = flow_constants_pkg.gc_apex_custom_extension then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_objt_bpmn_id',
'        , pi_attribute_name => rec.ext_type',
'        , pi_value          => rec.ext_text',
'        );',
'      end if;',
'    end loop;',
'',
'    -- Parse in vs. out variables separately',
'    -- Makes it easier to understand in the code',
'    -- while not hitting performance too much',
'',
'    select json_arrayagg',
'           (',
'             json_object',
'             (',
'               key ''varName''        is var_name',
'             , key ''varDataType''    is var_datatype',
'             , key ''varDescription'' is var_description',
'             )',
'           ) in_var_array',
'      into l_var_array',
'      from xmltable',
'           (',
'             xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                           , ''https://flowsforapex.org'' as "apex")',
'           , ''/bpmn:extensionElements/apex:inVariables/apex:processVariable[*]'' passing pi_xml',
'             columns',
'               var_name        varchar2(50 char) path ''apex:varName''',
'             , var_datatype    varchar2(50 char) path ''apex:varDataType''',
'             , var_description varchar2(50 char) path ''apex:varDescription''',
'           )',
'    ;',
'',
'    -- If no inVariables are found the variable is null',
'    if l_var_array is not null then',
'      l_apex_object.put( ''inVariables'', sys.json_array_t.parse( l_var_array ) );',
'    end if;',
'',
'    select json_arrayagg',
'           (',
'             json_object',
'             (',
'               key ''varName''        is var_name',
'             , key ''varDataType''    is var_datatype',
'             , key ''varDescription'' is var_description',
'             )',
'           ) in_var_array',
'      into l_var_array',
'      from xmltable',
'           (',
'             xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                           , ''https://flowsforapex.org'' as "apex")',
'           , ''/bpmn:extensionElements/apex:outVariables/apex:processVariable[*]'' passing pi_xml',
'             columns',
'               var_name        varchar2(50 char) path ''apex:varName''',
'             , var_datatype    varchar2(50 char) path ''apex:varDataType''',
'             , var_description varchar2(50 char) path ''apex:varDescription''',
'           )',
'    ;',
'',
'    if l_var_array is not null then',
'      l_apex_object.put( ''outVariables'', sys.json_array_t.parse( l_var_array ) );',
'    end if;',
'',
'  end parse_process_extensions;',
'',
'  procedure parse_child_elements',
'  (',
'    pi_objt_bpmn_id in flow_types_pkg.t_bpmn_id',
'  , pi_xml          in sys.xmltype',
'  )',
'  as',
'    l_child_type         flow_types_pkg.t_bpmn_id;',
'    l_child_id           flow_types_pkg.t_bpmn_id;',
'    l_child_value        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_child_details      sys.xmltype;',
'    l_detail_type        flow_types_pkg.t_bpmn_id;',
'    l_detail_id          flow_types_pkg.t_bpmn_id;',
'    l_detail_value       flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'',
'    if g_log_enabled then',
'      flow_parser_util.log',
'      (',
'        pi_plog_dgrm_id    => g_dgrm_id',
'      , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'      , pi_plog_parse_step => ''parse_child_elements''',
'      , pi_plog_payload    => pi_xml',
'      );',
'    end if;',
'',
'',
'    for rec in (',
'                select children.child_type',
'                     , children.child_id',
'                     , children.child_value',
'                     , children.child_details',
'                     , children.extension_elements',
'                     , children.message_ref',
'                     , children.is_sequential',
'                  from xmltable',
'                       (',
'                         xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                      , ''https://flowsforapex.org'' as "apex")',
'                       , ''*'' passing pi_xml',
'                         columns',
'                           child_type         varchar2(  50 char)  path ''name()''',
'                         , child_id           varchar2(  50 char)  path ''@id''',
'                         , child_value        varchar2(4000 char)  path ''text()''',
'                         , message_ref        varchar2(  50 char)  path ''@messageRef''',
'                         , is_sequential      varchar2(  50 char)  path ''@isSequential''',
'                         , child_details      sys.xmltype          path ''* except bpmn:incoming except bpmn:outgoing except bpmn:extensionElements''',
'                         , extension_elements sys.xmltype          path ''bpmn:extensionElements''',
'                       ) children',
'               )',
'    loop',
'',
'      if rec.child_details is null then',
'        -- register the child which does not have details',
'        if rec.child_value is not null then',
'          -- if needed distinguish here between different attributes',
'',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id    => pi_objt_bpmn_id',
'          , pi_attribute_name  => rec.child_type',
'          , pi_value           => rec.child_value',
'          );',
'        end if;',
'      end if;',
'      -- register the child which has details',
'      case rec.child_type',
'        when flow_constants_pkg.gc_bpmn_timer_event_definition then',
'        -- if custom (Flows) type then all processing is done by using the extension element',
'          if rec.extension_elements is not null then',
'            parse_extension_elements',
'            ( ',
'              pi_bpmn_id       => pi_objt_bpmn_id',
'            , pi_extension_xml => rec.extension_elements',
'            );',
'          -- if standard type just register value inside tag',
'          elsif rec.child_details is not null then',
'            if g_log_enabled then',
'              flow_parser_util.log',
'              (',
'                pi_plog_dgrm_id    => g_dgrm_id',
'              , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'              , pi_plog_parse_step => ''parse_child_elements - not timer''',
'              , pi_plog_payload    => rec.child_details',
'              );',
'            end if;',
'',
'            select details.detail_type',
'               '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  , details.detail_id',
'                 , details.detail_value',
'              into l_detail_type',
'                 , l_detail_id',
'                 , l_detail_value',
'              from xmltable',
'                   (',
'                     xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'                   , ''*'' passing rec.child_details',
'                     columns',
'                       detail_type        varchar2(50 char)    path ''name()''',
'                     , detail_id          varchar2(50 char)    path ''@id''',
'                     , detail_value       varchar2(4000 char)  path ''text()''',
'                   ) details',
'            ;',
'',
'            -- register the timer type',
'            register_object_attribute',
'            (',
'              pi_objt_bpmn_id   => pi_objt_bpmn_id',
'            , pi_attribute_name => flow_constants_pkg.gc_timer_type_key',
'            , pi_value          => l_detail_type',
'            );',
'',
'            register_object_attribute',
'            (',
'              pi_objt_bpmn_id   => pi_objt_bpmn_id',
'            , pi_attribute_name => flow_constants_pkg.gc_timer_def_key',
'            , pi_value          => l_detail_value',
'            );',
'          end if;',
'        -- custom processStatus attribute on terminateEndEvents',
'        when flow_constants_pkg.gc_bpmn_terminate_event_definition then',
'          if g_log_enabled then',
'            flow_parser_util.log',
'            (',
'              pi_plog_dgrm_id    => g_dgrm_id',
'            , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'            , pi_plog_parse_step => ''when '' || flow_constants_pkg.gc_bpmn_terminate_event_definition',
'            , pi_plog_payload    => rec.child_details',
'            );',
'          end if;',
'',
'          if rec.child_details is not null then',
'            select details.detail_type',
'                 , details.detail_value',
'              into l_detail_type',
'                 , l_detail_value',
'              from xmltable',
'                    (',
'                      xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'                    , ''*'' passing rec.child_details',
'                      columns',
'                        detail_type  varchar2(50 char) path   ''name()''',
'                      , detail_value varchar2(4000 char) path ''text()''',
'                    ) details',
'            ;',
'            if l_detail_type = flow_constants_pkg.gc_apex_process_status then',
'              register_object_attribute',
'              (',
'                pi_objt_bpmn_id   => pi_objt_bpmn_id',
'              , pi_attribute_name => flow_constants_pkg.gc_terminate_result',
'              , pi_value          => l_detail_value',
'              );',
'            end if;',
'          end if;',
'        when flow_constants_pkg.gc_bpmn_message_event_definition then',
'',
'          if g_log_enabled then',
'            flow_parser_util.log',
'            (',
'              pi_plog_dgrm_id    => g_dgrm_id',
'            , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'            , pi_plog_parse_step => ''when '' || flow_constants_pkg.gc_bpmn_message_event_definition',
'            , pi_plog_payload    => rec.extension_elements',
'            );',
'          end if;',
'',
'          if rec.message_ref is not null then',
'            register_object_attribute',
'            (',
'              pi_objt_bpmn_id   => pi_objt_bpmn_id',
'            , pi_attribute_name => ''messageRef''',
'            , pi_value          => rec.message_ref',
'            );',
'          end if;',
'          if rec.extension_elements is not null then',
'            parse_extension_elements',
'            ( ',
'              pi_bpmn_id       => pi_objt_bpmn_id',
'            , pi_extension_xml => rec.extension_elements',
'            );',
'          end if;',
'        when flow_constants_pkg.gc_bpmn_multi_instance_loop then',
'          if g_log_enabled then',
'            flow_parser_util.log',
'            (',
'              pi_plog_dgrm_id    => g_dgrm_id',
'            , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'            , pi_plog_parse_step => ''when '' || flow_constants_pkg.gc_bpmn_multi_instance_loop',
'            , pi_plog_payload    => ''isSequential: '' || rec.is_sequential',
'            );',
'          end if;',
'',
'          parse_iterator_attributes',
'          (',
'            pi_objt_bpmn_id       => pi_objt_bpmn_id',
'          , pi_iterator_type      => rec.child_type',
'          , pi_is_sequential      => rec.is_sequential',
'          , pi_extension_elements => rec.extension_elements',
'          );',
'        when flow_constants_pkg.gc_bpmn_standard_loop then',
'          if g_log_enabled then',
'            flow_parser_util.log',
'            (',
'              pi_plog_dgrm_id    => g_dgrm_id',
'            , pi_plog_bpmn_id    => pi_objt_bpmn_id',
'            , pi_plog_parse_step => ''when '' || flow_constants_pkg.gc_bpmn_standard_loop',
'            , pi_plog_payload    => ''isSequential: '' || rec.is_sequential',
'            );',
'          end if;',
'',
'          parse_iterator_attributes',
'          (',
'            pi_objt_bpmn_id       => pi_objt_bpmn_id',
'          , pi_iterator_type      => rec.child_type',
'          , pi_is_sequential      => rec.is_sequential',
'          , pi_extension_elements => rec.extension_elements',
'          );',
'        else',
'          null;',
'      end case;',
'',
'    end loop;',
'',
'  end parse_child_elements;',
'',
'  procedure parse_call_activity',
'  (',
'    pi_xml          in sys.xmltype',
'  , pi_objt_bpmn_id in flow_types_pkg.t_bpmn_id',
'  )',
'  as',
'  begin',
'',
'    for rec in (',
'                select activity.activity_diagram',
'                     , activity.activity_versionSelection',
'                     , activity.activity_version',
'                  from xmltable',
'                       (',
'                         xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                       , ''https://flowsforapex.org'' as "apex")',
'                       , ''*'' passing pi_xml',
'                         columns',
'                           activity_diagram          varchar2(50 char) path ''@apex:calledDiagram''',
'                         , activity_versionSelection varchar2(50 char) path ''@apex:calledDiagramVersionSelection''',
'                         , activity_version          varchar2(50 char) path ''@apex:calledDiagramVersion''',
'                       ) activity',
'               )',
'    loop',
'',
'      if rec.activity_diagram is not null then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_objt_bpmn_id',
'        , pi_attribute_name => flow_constants_pkg.gc_apex_called_diagram',
'        , pi_value          => rec.activity_diagram',
'        );',
'      end if;',
'',
'      if rec.activity_versionSelection is not null then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_objt_bpmn_id',
'        , pi_attribute_name => flow_constants_pkg.gc_apex_called_diagram_version_selection',
'        , pi_value          => rec.activity_versionSelection',
'        );',
'      end if;',
'',
'      if rec.activity_version is not null then',
'        register_object_attribute',
'        (',
'          pi_objt_bpmn_id   => pi_objt_bpmn_id',
'        , pi_attribute_name => flow_constants_pkg.gc_apex_called_diagram_version',
'        , pi_value          => rec.activity_version',
'        );',
'      end if;',
'',
'    end loop;',
'',
'  end parse_call_activity;',
'',
'  function get_connection_attributes',
'  (',
'    pi_conn_bpmn_id in flow_types_pkg.t_bpmn_id',
'  , pi_xml          in sys.xmltype',
'  ) return sys.json_object_t',
'  as',
'    l_condition_base       flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_condition_expression clob;',
'    l_condition_object     sys.json_object_t;',
'    l_expression_array     sys.json_array_t;',
'    l_attributes_json      sys.json_object_t := sys.json_object_t();',
'  begin',
'    select json_object( key ''language'' is condition_language )',
'         , condition_value',
'      into l_condition_base',
'         , l_condition_expression',
'      from xmltable',
'           (',
'             xmlnamespaces( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                          , ''https://flowsforapex.org'' as "apex")',
'           , ''/bpmn:conditionExpression'' passing pi_xml',
'             columns',
'               condition_language varchar2(50 char) path ''@language''',
'             , condition_value    clob              path ''text()''',
'           )',
'    ;',
'    l_condition_object := sys.json_object_t.parse( l_condition_base );',
'    l_expression_array := flow_parser_util.get_lines_array( pi_str => l_condition_expression );',
'    l_condition_object.put( ''expression'', l_expression_array );',
'',
'    l_attributes_json.put( ''conditionExpression'', l_condition_object );',
'    return l_attributes_json;',
'  exception',
'    when no_data_found then',
'      return null;',
'  end get_connection_attributes;',
'',
'  procedure parse_connection_extensions',
'  (',
'    pi_conn_bpmn_id     in     flow_types_pkg.t_bpmn_id',
'  , pi_xml              in     sys.xmltype',
'  , pio_conn_attributes in out sys.json_object_t',
'  )',
'  as',
'    l_apex_object sys.json_object_t;',
'    l_namespace    flow_types_pkg.t_bpmn_id;',
'    l_key          flow_types_pkg.t_bpmn_attributes_key;',
'    l_json_element sys.json_element_t;',
'  begin',
'    flow_parser_util.guarantee_apex_object( pio_attributes => pio_conn_attributes );',
'    l_apex_object := pio_conn_attributes.get_object( ''apex'' );',
'',
'    for rec in (',
'      select ext_type',
'           , ext_text',
'        from xmltable',
'             (',
'               xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                             , ''https://flowsforapex.org'' as "apex")',
'             , ''/bpmn:extensionElements/*'' passing pi_xml',
'               columns',
'                 ext_type  varchar2( 50 char) path ''name()''',
'               , ext_text  clob               path ''text()''',
'             ) ext',
'       where ext_type = flow_constants_pkg.gc_apex_custom_extension',
'    ) loop',
'      flow_parser_util.property_to_json',
'      (',
'        pi_property_name => rec.ext_type',
'      , pi_value         => rec.ext_text',
'      , po_namespace     => l_namespace',
'      , po_key           => l_key',
'      , po_json_element  => l_json_element',
'      );',
'      if l_json_element is not null then',
'        l_apex_object.put( l_key, l_json_element );',
'      end if;',
'    end loop;',
'  end parse_connection_extensions;',
'',
'  procedure parse_steps',
'  (',
'    pi_xml          in sys.xmltype',
'  , pi_proc_type    in flow_types_pkg.t_bpmn_id',
'  , pi_proc_bpmn_id in flow_types_pkg.t_bpmn_id',
'  )',
'  as',
'    l_objt_sub_tag_name flow_objects.objt_sub_tag_name%type;',
'    l_conn_attributes   sys.json_object_t;',
'  begin',
'    if g_log_enabled then',
'      flow_parser_util.log',
'      (',
'        pi_plog_dgrm_id    => g_dgrm_id',
'      , pi_plog_bpmn_id    => pi_proc_bpmn_id',
'      , pi_plog_parse_step => ''parse_steps''',
'      , pi_plog_payload    => pi_xml',
'      );',
'    end if;',
'',
'    for rec in (',
'                select steps.steps_type',
'                     , steps.steps_name',
'                     , steps.steps_id',
'                     , steps.source_ref',
'                     , steps.target_ref',
'                     , steps.default_conn',
'                     , steps.attached_to',
'                     , case steps.steps_type',
'                         when flow_constants_pkg.gc_bpmn_boundary_event then',
'                           case steps.interrupting',
'                             when flow_constants_pkg.gc_vcbool_false then 0',
'                             else 1',
'                           end',
'                         else',
'                           null',
'                       end as interrupting',
'                     , steps.conn_sequence',
'                     , steps.task_type',
'                     , steps.is_sequential',
'                     , steps.child_elements',
'                     , steps.extension_elements',
'                     , steps.step',
'                  from xmltable',
'                       (',
'                         xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                       , ''https://flowsforapex.org'' as "apex")',
'                       , ''*'' passing pi_xml',
'                         columns',
'                           steps_type         varchar2( 50 char) path ''name()''',
'                         , steps_name         varchar2(200 char) path ''@name''',
'                         , steps_id           varchar2( 50 char) path ''@id''',
'                         , source_ref         varchar2( 50 char) path ''@sourceRef''',
'                         , target_ref         varchar2( 50 char) path ''@targetRef''',
'                         , default_conn       varchar2( 50 char) path ''@default''',
'                         , attached_to        varchar2( 50 char) path ''@attachedToRef''',
'                         , interrupting       varchar2( 50 char) path ''@cancelActivity''',
'                         , conn_sequence      number             path ''@apex:sequence''',
'                         , task_type          varchar2( 50 char) path ''@apex:type''',
'                         , is_sequential      varchar2( 50 char) path ''@isSequential''',
'                         , child_elements     sys.xmltype        path ''* except bpmn:incoming except bpmn:outgoing except bpmn:extensionElements''',
'                         , extension_elements sys.xmltype        path ''bpmn:extensionElements''',
'                         , step               sys.xmltype        path ''.''',
'                       ) steps',
'               )',
'    loop',
'      if g_log_enabled then',
'',
'        if rec.steps_id is null then',
'          flow_parser_util.log',
'          (',
'            pi_plog_dgrm_id    => g_dgrm_id',
'          , pi_plog_bpmn_id    => pi_proc_bpmn_id',
'          , pi_plog_parse_step => ''parse_steps - loop''',
'          , pi_plog_payload    => ''No step_id. In process of type '' || pi_proc_type || '' with id '' || pi_proc_bpmn_id',
'          );',
'        end if;',
'',
'        flow_parser_util.log',
'        (',
'          pi_plog_dgrm_id    => g_dgrm_id',
'        , pi_plog_bpmn_id    => rec.steps_id',
'        , pi_plog_parse_step => ''parse_steps - loop step data''',
'        , pi_plog_payload    => rec.step',
'        );',
'',
'        flow_parser_util.log',
'        (',
'          pi_plog_dgrm_id    => g_dgrm_id',
'        , pi_plog_bpmn_id    => rec.steps_id',
'        , pi_plog_parse_step => ''parse_steps - loop childElements data''',
'        , pi_plog_payload    => rec.child_elements',
'        );',
'',
'        flow_parser_util.log',
'        (',
'          pi_plog_dgrm_id    => g_dgrm_id',
'        , pi_plog_bpmn_id    => rec.steps_id',
'        , pi_plog_parse_step => ''parse_steps - loop extensionElements data''',
'        , pi_plog_payload    => rec.extension_elements',
'        );',
'',
'      end if;',
'',
'      -- Iterator found as step, shortcut other processing',
'      if rec.steps_type in ( flow_constants_pkg.gc_bpmn_multi_instance_loop, flow_constants_pkg.gc_bpmn_standard_loop ) then',
'        if g_log_enabled then',
'          flow_parser_util.log',
'          (',
'            pi_plog_dgrm_id    => g_dgrm_id',
'          , pi_plog_bpmn_id    => pi_proc_bpmn_id',
'          , pi_plog_parse_step => ''parse_steps - loop -> found iterator of type '' || rec.steps_type',
'          , pi_plog_payload    => rec.extension_elements',
'          );',
'        end if;',
'',
'        parse_iterator_attributes',
'        (',
'          pi_objt_bpmn_id       => pi_proc_bpmn_id',
'        , pi_iterator_type      => rec.steps_type',
'        , pi_is_sequential      => rec.is_sequential',
'        , pi_extension_elements => rec.extension_elements',
'        );',
'      elsif rec.source_ref is null then -- assume objects don''t have a sourceRef attribute',
'',
'        -- Parse additional information from child elements',
'        -- relevant for e.g. terminateEndEvent',
'        -- Additionally collect generic attributes if possible',
'        if rec.child_elements is not null then',
'          l_objt_sub_tag_name := find_subtag_name( pi_xml => rec.child_elements );',
'          parse_child_elements',
'          (',
'            pi_objt_bpmn_id => rec.steps_id',
'          , pi_xml          => rec.child_elements',
'          );',
'        else',
'          l_objt_sub_tag_name := null;',
'        end if;',
'',
'        if rec.extension_elements is not null then',
'          parse_extension_elements',
'          ( ',
'            pi_bpmn_id       => rec.steps_id',
'          , pi_extension_xml => rec.extension_elements',
'          );',
'        end if;',
'',
'        if rec.default_conn is not null then',
'          g_default_cons(rec.default_conn) := 1;',
'        end if;',
'',
'        register_object',
'        (',
'          pi_objt_bpmn_id        => rec.steps_id',
'        , pi_objt_name           => rec.steps_name',
'        , pi_objt_tag_name       => rec.steps_type',
'        , pi_objt_sub_tag_name   => l_objt_sub_tag_name',
'        , pi_objt_parent_bpmn_id => pi_proc_bpmn_id',
'        , pi_objt_attached_to    => rec.attached_to',
'        , pi_objt_interrupting   => rec.interrupting',
'        );',
'',
'        if rec.task_type is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.steps_id',
'          , pi_attribute_name => flow_constants_pkg.gc_task_type_key',
'          , pi_value          => rec.task_type',
'          );',
'        end if;',
'',
'        if rec.steps_type = ''bpmn:callActivity'' then',
'          parse_call_activity',
'          (',
'            pi_xml          => rec.step',
'          , pi_objt_bpmn_id => rec.steps_id',
'          );',
'        end if;',
'      else',
'        l_conn_attributes := null;',
'        if rec.child_elements is not null then',
'          l_conn_attributes := ',
'            get_connection_attributes',
'            (',
'              pi_conn_bpmn_id   => rec.steps_id',
'            , pi_xml            => rec.child_elements',
'            );',
'        end if;',
'        if rec.extension_elements is not null then',
'          parse_connection_extensions',
'          (',
'            pi_conn_bpmn_id     => rec.steps_id',
'          , pi_xml              => rec.extension_elements',
'          , pio_conn_attributes => l_conn_attributes',
'          );',
'        end if;',
'        register_connection',
'        (',
'          pi_conn_bpmn_id     => rec.steps_id',
'        , pi_conn_name        => rec.steps_name',
'        , pi_conn_src_bpmn_id => rec.source_ref',
'        , pi_conn_tgt_bpmn_id => rec.target_ref',
'        , pi_conn_tag_name    => rec.steps_type',
'        , pi_conn_origin      => pi_proc_bpmn_id',
'        , pi_conn_sequence    => rec.conn_sequence',
'        , pi_conn_attributes  => l_conn_attributes',
'        );        ',
'      end if;',
'    end loop;  ',
'  end parse_steps;',
'',
'  procedure parse_xml',
'  (',
'    pi_xml        in sys.xmltype',
'  , pi_parent_id  in flow_types_pkg.t_bpmn_id',
'  , pi_child_type in flow_types_pkg.t_bpmn_id default null',
'  )',
'  as',
'  begin',
'',
'    if g_log_enabled then',
'',
'      flow_parser_util.log',
'      (',
'        pi_plog_dgrm_id    => g_dgrm_id',
'      , pi_plog_bpmn_id    => pi_parent_id',
'      , pi_plog_parse_step => ''parse_xml'' || case when pi_child_type is not null then '' - child type: '' || pi_child_type else '''' end',
'      , pi_plog_payload    => pi_xml',
'      );',
'',
'    end if;',
'',
'    if pi_parent_id is null then',
'      for rec in (',
'                 select proc.proc_id',
'                      , case proc.proc_type when ''bpmn:subProcess''      then ''SUB_PROCESS'' ',
'                                            when ''bpmn:adHocSubProcess'' then ''AD_HOC_SUB_PROCESS''',
'                                            else ''PROCESS''              end as proc_type_rem',
'                      , proc.proc_type',
'                      , proc.proc_callable',
'                      , proc.proc_startable',
'                      , proc.proc_min_logging_level',
'                      , proc.proc_instance_name',
'                      , proc.proc_application_id',
'                      , proc.proc_page_id',
'                      , proc.proc_username',
'                      , proc.proc_business_admin',
'                      , proc.proc_steps',
'                      , proc.proc_sub_procs',
'                      , proc.proc_ad_hoc_sub_procs',
'                      , proc.proc_name',
'                      , proc.proc_laneset',
'                      , proc.proc_extensions',
'                   from xmltable',
'                      (',
'                        xmlnamespaces ( ''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn"',
'                                      , ''https://flowsforapex.org'' as "apex")',
'                      , ''/bpmn:definitions/bpmn:process'' passing pi_xml',
'                        columns',
'                          proc_id                 varchar2( 50 char) path ''@id''',
'                        , proc_type               varchar2( 50 char) path ''name()''',
'                        , proc_name               varchar2(200 char) path ''@name''',
'                        , proc_callable           varchar2( 50 char) path ''@apex:isCallable''',
'                        , proc_startable          varchar2( 50 char) path ''@apex:isStartable''',
'                        , proc_min_logging_level  varchar2( 50 char) path ''@apex:minLoggingLevel''   ',
'                        , proc_instance_name      varchar2(200 char) path ''@apex:instanceName''',
'                        , proc_application_id     varchar2( 50 char) path ''@apex:applicationId''',
'                        , proc_page_id            varchar2( 50 char) path ''@apex:pageId''',
'                        , proc_username           varchar2( 50 char) path ''@apex:username''',
'                        , proc_business_admin     varchar2( 50 char) path ''@apex:businessAdmin''',
'                        , proc_steps              sys.xmltype        path ''* except bpmn:subProcess except bpmn:extensionElements ',
'                                                                             except bpmn:laneSet except bpmn:adHocSubProcess''',
'                        , proc_sub_procs          sys.xmltype        path ''bpmn:subProcess''',
'                        , proc_ad_hoc_sub_procs   sys.xmltype        path ''bpmn:adHocSubProcess''',
'                        , proc_laneset            sys.xmltype        path ''bpmn:laneSet''',
'                        , proc_extensions         sys.xmltype        path ''bpmn:extensionElements''',
'                      ) proc',
'                 )',
'      loop',
'',
'        -- register each process as an object so we can reference later',
'        register_object',
'        (',
'          pi_objt_bpmn_id        => rec.proc_id',
'        , pi_objt_tag_name       => rec.proc_type',
'        , pi_objt_name           => rec.proc_name',
'        , pi_objt_parent_bpmn_id => case when g_collab_refs.exists( rec.proc_id ) then g_collab_refs( rec.proc_id ) else null end',
'        );',
'',
'        if rec.proc_application_id is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_application_id',
'          , pi_value          => rec.proc_application_id',
'          );',
'        end if;',
'',
'        if rec.proc_page_id is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_page_id',
'          , pi_value          => rec.proc_page_id',
'          );',
'        end if;',
'',
'        if rec.proc_username is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_username',
'          , pi_value          => rec.proc_username',
'          );',
'        end if;',
'',
'        if rec.proc_business_admin is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_business_admin',
'          , pi_value          => rec.proc_business_admin',
'          );',
'        end if;',
'',
'        if rec.proc_callable is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_callable',
'          , pi_value          => rec.proc_callable',
'          );',
'        end if;',
'',
'        if rec.proc_startable is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_startable',
'          , pi_value          => rec.proc_startable',
'          );',
'        end if;',
'',
'        if rec.proc_min_logging_level is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_min_logging_level',
'          , pi_value          => rec.proc_min_logging_level',
'          );',
'        end if;',
'',
'        if rec.proc_instance_name is not null then',
'          register_object_attribute',
'          (',
'            pi_objt_bpmn_id   => rec.proc_id',
'          , pi_attribute_name => flow_constants_pkg.gc_apex_process_instance_name',
'          , pi_value          => rec.proc_instance_name',
'          );',
'        end if;',
'',
'        if rec.proc_extensions is not null then',
'          parse_process_extensions',
'          (',
'            pi_objt_bpmn_id => rec.proc_id',
'          , pi_xml          => rec.proc_extensions',
'          );',
'        end if;',
'',
'        -- parse LaneSet if existing',
'        if rec.proc_laneset is not null then',
'          parse_laneset',
'          (  ',
'            pi_laneset_xml    => rec.proc_laneset',
'          , pi_parent_bpmn_id => rec.proc_id',
'          );',
'        end if;',
'',
'        -- parse immediate steps        ',
'        parse_steps',
'        ( ',
'          pi_xml          => rec.proc_steps',
'        , pi_proc_type    => rec.proc_type_rem',
'        , pi_proc_bpmn_id => rec.proc_id',
'        );',
'',
'        -- recurse if sub processes found',
'        if rec.proc_sub_procs is not null then',
'',
'          parse_xml',
'          ( ',
'            pi_xml => rec.proc_sub_procs',
'          , pi_parent_id => rec.proc_id',
'          , pi_child_type => flow_constants_pkg.gc_bpmn_subprocess',
'          );',
'',
'        end if;',
'',
'        -- recurse if adhoc sub processes found',
'        if rec.proc_ad_hoc_sub_procs is not null then',
'',
'          parse_xml',
'          ( ',
'            pi_xml => rec.proc_ad_hoc_sub_procs',
'          , pi_parent_id => rec.proc_id',
'          , pi_child_type => flow_constants_pkg.gc_bpmn_adhoc_subprocess',
'          );',
'',
'        end if;',
'',
'      end loop;',
'    else -- it is a sub process or adhoc sub process (need to differentiate)',
'      if pi_child_type = flow_constants_pkg.gc_bpmn_subprocess then',
'        for rec in (',
'                   select proc.proc_id',
'                        , proc.proc_name',
'                        , case proc.proc_type when ''bpmn:subProcess'' then ''SUB_PROCESS'' ',
'                                              when ''bpmn:adHocSubProcess'' then ''ADHOC_SUB_PROCESS''',
'                                              else ''PROCESS'' end as proc_type_rem',
'                        , proc.proc_type',
'                        , proc.proc_steps',
'                        , proc.proc_sub_procs',
'                        , proc.proc_ad_hoc_sub_procs',
'                        , proc.proc_extensions',
'                     from xmltable',
'                        (',
'                          xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'                        , ''bpmn:subProcess'' passing pi_xml',
'                          columns',
'                            proc_id               varchar2(50  char) path ''@id''',
'                          , proc_name             varchar2(200 char) path ''@name''',
'                          , proc_type             varchar2(50  char) path ''name()''',
'                          , proc_steps            sys.xmltype        path ''* except bpmn:subProcess except bpmn:extensionElements except bpmn:adHocSubProcess''',
'                          , proc_sub_procs        sys.xmltype        path ''bpmn:subProcess''',
'                          , proc_ad_hoc_sub_procs sys.xmltype        path ''bpmn:adHocSubProcess''',
'                          , proc_extensions       sys.xmltype        path ''bpmn:extensionElements''',
'                        ) proc',
'                   )',
'        loop',
'          -- We add an entry for a sub process here,',
'          -- as it is an object within the master process',
'          register_object',
'          (',
'            pi_objt_bpmn_id        => rec.proc_id',
'          , pi_objt_tag_name       => rec.proc_type',
'          , pi_objt_name           => rec.proc_name',
'          , pi_objt_parent_bpmn_id => pi_parent_id',
'          );',
'',
'          if rec.proc_extensions is not null then',
'            parse_extension_elements',
'            (',
'              pi_bpmn_id       => rec.proc_id',
'            , pi_extension_xml => rec.proc_extensions',
'            );',
'          end if;',
'',
'          -- parse any immediate steps',
'          parse_steps',
'          ( ',
'            pi_xml          => rec.proc_steps',
'          , pi_proc_type    => rec.proc_type_rem',
'          , pi_proc_bpmn_id => rec.proc_id',
'          );',
'',
'          -- recurse if we found any sub process',
'          if rec.proc_sub_procs is not null then',
'            parse_xml',
'            (',
'              pi_xml        => rec.proc_sub_procs',
'            , pi_parent_id  => rec.proc_id',
'            , pi_child_type => flow_constants_pkg.gc_bpmn_subprocess',
'            );',
'          end if;   ',
'',
'          -- recurse if we found any adhoc sub process',
'          if rec.proc_ad_hoc_sub_procs is not null then',
'            parse_xml',
'            (',
'              pi_xml        => rec.proc_ad_hoc_sub_procs',
'            , pi_parent_id  => rec.proc_id',
'            , pi_child_type => flow_constants_pkg.gc_bpmn_adhoc_subprocess',
'            );     ',
'          end if;',
'        end loop;',
'      elsif pi_child_type = flow_constants_pkg.gc_bpmn_adhoc_subprocess then',
'        for rec in (',
'             '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'      select proc.proc_id',
'                        , proc.proc_name',
'                        , case proc.proc_type when ''bpmn:subProcess'' then ''SUB_PROCESS'' ',
'                                              when ''bpmn:adHocSubProcess'' then ''ADHOC_SUB_PROCESS''',
'                                              else ''PROCESS'' end as proc_type_rem',
'                        , proc.proc_type',
'                        , proc.proc_steps',
'                        , proc.proc_extensions',
'                        , proc.proc_sub_procs',
'                     from xmltable',
'                        (',
'                          xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'                        , ''bpmn:adHocSubProcess'' passing pi_xml',
'                          columns',
'                            proc_id               varchar2(50  char) path ''@id''',
'                          , proc_name             varchar2(200 char) path ''@name''',
'                          , proc_type             varchar2(50  char) path ''name()''',
'                          , proc_steps            sys.xmltype        path ''* except bpmn:extensionElements''',
'                          , proc_extensions       sys.xmltype        path ''bpmn:extensionElements''',
'                          , proc_sub_procs        sys.xmltype        path ''bpmn:subProcess''',
'                          , proc_ad_hoc_sub_procs sys.xmltype        path ''bpmn:adHocSubProcess''',
'                        ) proc',
'                   )',
'        loop',
'          -- We add an entry for a sub process here,',
'          -- as it is an object within the master process',
'          register_object',
'          (',
'            pi_objt_bpmn_id        => rec.proc_id',
'          , pi_objt_tag_name       => rec.proc_type',
'          , pi_objt_name           => rec.proc_name',
'          , pi_objt_parent_bpmn_id => pi_parent_id',
'          );',
'',
'          if rec.proc_extensions is not null then',
'            parse_extension_elements',
'            (',
'              pi_bpmn_id       => rec.proc_id',
'            , pi_extension_xml => rec.proc_extensions',
'            );',
'          end if;',
'',
'          -- parse any immediate steps',
'          parse_steps',
'          ( ',
'            pi_xml          => rec.proc_steps',
'          , pi_proc_type    => rec.proc_type_rem',
'          , pi_proc_bpmn_id => rec.proc_id',
'          );',
'',
'          -- recurse if we found any sub process',
'          if rec.proc_sub_procs is not null then',
'            parse_xml',
'            (',
'              pi_xml        => rec.proc_sub_procs',
'            , pi_parent_id  => rec.proc_id',
'            , pi_child_type => flow_constants_pkg.gc_bpmn_subprocess',
'            );',
'          end if;   ',
'',
'        end loop;',
'      end if;',
'    end if;',
'  end parse_xml;',
'',
'  procedure parse_collaboration',
'  (',
'    pi_xml in sys.xmltype',
'  )',
'  as',
'    l_collab_id         flow_types_pkg.t_bpmn_id;',
'    l_collab_name       flow_types_pkg.t_vc200;',
'    l_collab_type       flow_types_pkg.t_bpmn_id;',
'    l_collab_extensions sys.xmltype;',
'    l_collab_nodes      sys.xmltype;',
'',
'    l_conn_attributes   sys.json_object_t;',
'  begin',
'',
'    select collab_id',
'         , collab_name',
'         , collab_type',
'         , collab_extensions',
'         , collab_nodes',
'      into l_collab_id',
'         , l_collab_name',
'         , l_collab_type',
'         , l_collab_extensions',
'         , l_collab_nodes',
'      from xmltable',
'           (',
'             xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'           , ''/bpmn:definitions/bpmn:collaboration'' passing pi_xml',
'             columns',
'               collab_id         varchar2(50  char) path ''@id''',
'             , collab_name       varchar2(200 char) path ''@name''',
'             , collab_type       varchar2(50  char) path ''name()''',
'             , collab_extensions sys.xmltype        path ''bpmn:extensionElements''',
'             , collab_nodes      sys.xmltype        path ''*''',
'           ) collab',
'    ;',
'',
'    register_object',
'    (',
'      pi_objt_bpmn_id        => l_collab_id',
'    , pi_objt_tag_name       => l_collab_type',
'    , pi_objt_name           => l_collab_name',
'    );',
'',
'    if l_collab_extensions is not null then',
'      parse_extension_elements',
'      (',
'        pi_bpmn_id       => l_collab_id',
'      , pi_extension_xml => l_collab_extensions',
'      );',
'    end if;',
'',
'    for rec in (',
'                 select node_id',
'                      , node_name',
'                      , node_type',
'                      , node_proc_ref',
'                      , node_src_ref',
'                      , node_tgt_ref',
'                      , node_cat_ref',
'                      , node_extensions',
'                   from xmltable',
'                        (',
'                          xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'                        , ''*'' passing l_collab_nodes',
'                          columns',
'                            node_id         varchar2( 50 char) path ''@id''',
'                          , node_name       varchar2(200 char) path ''@name''',
'                          , node_type       varchar2( 50 char) path ''name()''',
'                          , node_proc_ref   varchar2( 50 char) path ''@processRef''',
'                          , node_src_ref    varchar2( 50 char) path ''@sourceRef''',
'                          , node_tgt_ref    varchar2( 50 char) path ''@targetRef''',
'                          , node_cat_ref    varchar2( 50 char) path ''@categoryValueRef''',
'                          , node_extensions sys.xmltype        path ''bpmn:extensionElements''',
'                        ) collab_nodes',
'    ) loop',
'',
'      l_conn_attributes := null;',
'',
'      case',
'        when rec.node_src_ref is null then',
'          register_object',
'          (',
'            pi_objt_bpmn_id        => rec.node_id',
'          , pi_objt_tag_name       => rec.node_type',
'          , pi_objt_name           => rec.node_name',
'          , pi_objt_parent_bpmn_id => l_collab_id',
'          );',
'          if rec.node_extensions is not null then',
'            parse_extension_elements',
'            (',
'              pi_bpmn_id       => rec.node_id',
'            , pi_extension_xml => rec.node_extensions',
'            );',
'          end if;',
'          case rec.node_type',
'            when flow_constants_pkg.gc_bpmn_participant then',
'              if rec.node_proc_ref is not null then',
'                g_collab_refs(rec.node_proc_ref) := rec.node_id;',
'              end if;',
'            else',
'              null;',
'          end case;',
'        else',
'',
'          if rec.node_extensions is not null then',
'            parse_connection_extensions',
'            (',
'              pi_conn_bpmn_id     => rec.node_id',
'            , pi_xml              => rec.node_extensions',
'            , pio_conn_attributes => l_conn_attributes',
'            );',
'          end if;',
'          register_connection',
'          (',
'            pi_conn_bpmn_id     => rec.node_id',
'          , pi_conn_name        => rec.node_name',
'          , pi_conn_src_bpmn_id => rec.node_src_ref',
'          , pi_conn_tgt_bpmn_id => rec.node_tgt_ref',
'          , pi_conn_tag_name    => rec.node_type',
'          , pi_conn_origin      => null',
'          , pi_conn_sequence    => null',
'          , pi_conn_attributes  => l_conn_attributes',
'          );',
'      end case;',
'    end loop;',
'  exception',
'    when no_data_found then',
'      -- if no collaboration present we can skip',
'      null;',
'  end parse_collaboration;',
'',
'  procedure parse_messages',
'  (',
'    pi_xml in sys.xmltype',
'  )',
'  as',
'  begin',
'',
'    for rec in (',
'      select message_id',
'           , message_name',
'           , message_type',
'        from xmltable',
'             (',
'               xmlnamespaces (''http://www.omg.org/spec/BPMN/20100524/MODEL'' as "bpmn")',
'             , ''/bpmn:definitions/bpmn:message'' passing pi_xml',
'               columns',
'                 message_id   varchar2(50  char) path ''@id''',
'               , message_name varchar2(200 char) path ''@name''',
'               , message_type varchar2(50  char) path ''name()''',
'             )',
'    ) loop',
'',
'      register_object',
'      (',
'        pi_objt_bpmn_id => rec.message_id',
'      , pi_objt_tag_name => rec.message_type',
'      , pi_objt_name => rec.message_name',
'      );',
'',
'    end loop;',
'',
'  end parse_messages;',
'',
'  procedure reset',
'  as',
'  begin',
'    g_dgrm_id := null;',
'    g_objects.delete;',
'    g_objt_expr.delete;',
'    g_connections.delete;',
'    g_lane_refs.delete;',
'    g_collab_refs.delete;',
'    g_default_cons.delete;',
'    g_objt_lookup.delete;',
'  end reset;',
'',
'  procedure parse',
'  as',
'    l_dgrm_content clob;',
'    l_has_changed boolean;',
'  begin',
'    -- Check if logging is enabled',
'    g_log_enabled := flow_parser_util.is_log_enabled;',
'',
'    -- delete any existing parsed information before parsing again',
'    cleanup_parsing_tables;',
'',
'    -- get the CLOB content',
'    select dgrm_content',
'      into l_dgrm_content',
'      from flow_diagrams',
'     where dgrm_id = g_dgrm_id',
'    ;',
'',
'    -- migrate old diagrams',
'    flow_migrate_xml_pkg.migrate_xml(',
'      p_dgrm_content => l_dgrm_content',
'    , p_has_changed => l_has_changed',
'    );',
'',
'    -- update diagram after change',
'    if l_has_changed then',
'      update flow_diagrams',
'         set dgrm_content = l_dgrm_content',
'       where dgrm_id = g_dgrm_id',
'      ;',
'    end if;',
'',
'    -- parse out collaboration part first',
'    parse_collaboration( pi_xml => sys.xmltype(l_dgrm_content) );',
'    -- grab any message definitions',
'    parse_messages( pi_xml => sys.xmltype(l_dgrm_content) );',
'    -- start recursive processsing of xml',
'    parse_xml( pi_xml => sys.xmltype(l_dgrm_content), pi_parent_id => null );',
'',
'    -- finally insert all parsed data',
'    finalize;',
'',
'  end parse;',
'',
'  procedure parse',
'  (',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type',
'  )',
'  as',
'  begin',
'    reset;',
'    g_dgrm_id := pi_dgrm_id;',
'    parse;',
'  end parse;',
'',
'  procedure parse',
'  (',
'    pi_dgrm_name in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version  in flow_diagrams.dgrm_version%type',
'  )',
'  as',
'  begin',
'    reset;',
'    select dgrm_id',
'      into g_dgrm_id',
'      from flow_diagrams',
'     where dgrm_name = pi_dgrm_name',
'       and dgrm_version = pi_dgrm_version',
'    ;',
'    parse;',
'  end parse;',
'',
'  procedure upload_and_parse',
'  (',
'    pi_dgrm_name     in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_version  in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content  in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status   in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_force_overwrite in boolean default false',
'  )',
'  as',
'  begin',
'    reset;',
'',
'    upload_diagram( pi_dgrm_name => pi_dgrm_name, pi_dgrm_version => pi_dgrm_version,',
'                    pi_dgrm_category => pi_dgrm_category, pi_dgrm_content => pi_dgrm_content,',
'                    pi_dgrm_status => pi_dgrm_status, pi_force_overwrite => pi_force_overwrite',
'                  );',
'    parse;',
'',
'  end upload_and_parse;',
'',
'  procedure update_diagram',
'  (',
'    pi_dgrm_id      in flow_diagrams.dgrm_id%type',
'  , pi_dgrm_content in flow_diagrams.dgrm_content%type',
'  )',
'  as',
'  begin',
'    reset;',
'    g_dgrm_id := pi_dgrm_id;',
'',
'    update flow_diagrams',
'       set dgrm_content = pi_dgrm_content',
'         , dgrm_last_update = systimestamp',
'     where dgrm_id = g_dgrm_id',
'    ;',
'',
'    parse;',
'  end update_diagram;',
'',
'end flow_bpmn_parser_pkg;',
'/',
'',
'create or replace package body flow_call_activities ',
'as',
'/* ',
'-- Flows for APEX - flow_call_activities.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2020,2022.',
'--',
'-- Created  19-Feb-2022  Richard Allen - Oracle  ',
'-- Modified 22-May-2022  Moritz Klein (MT AG)',
'--',
'*/',
'',
'  type t_call_def is record',
'    ( dgrm_name              flow_diagrams.dgrm_name%type',
'    , dgrm_version           flow_diagrams.dgrm_version%type',
'    , dgrm_id                flow_diagrams.dgrm_id%type',
'    , dgrm_version_selection flow_types_pkg.t_bpmn_attribute_vc2',
'    );',
'',
'  function is_called_activity',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type  ',
'    ) return boolean',
'  is',
'    l_prcs_dgrm_id flow_processes.prcs_dgrm_id%type;',
'    l_sbfl_dgrm_id flow_subflows.sbfl_dgrm_id%type;',
'  begin',
'    select prcs.prcs_dgrm_id',
'         , sbfl.sbfl_dgrm_id',
'      into l_prcs_dgrm_id',
'         , l_sbfl_dgrm_id',
'      from flow_subflows sbfl',
'      join flow_processes prcs',
'        on prcs.prcs_id = sbfl.sbfl_prcs_id',
'     where prcs.prcs_id = p_process_id',
'       and sbfl.sbfl_id = p_subflow_id',
'    ;',
'    return ( l_prcs_dgrm_id != l_sbfl_dgrm_id);',
'  end;',
'',
'  -- Note: process_call_activity_endEvent is performed by flow_subprocesses.process_process_level_endEvent',
'',
'',
'  function get_call_definition',
'    ( pi_call_objt_id       in   flow_objects.objt_id%type',
'    ) return t_call_def',
'  is ',
'    l_call_def                  t_call_def;',
'  begin',
'    apex_debug.enter',
'    ( ''get_call_definition''',
'    , ''callActivity objt id'' , pi_call_objt_id',
'    );',
'',
'    select objt.objt_attributes."apex"."calledDiagram" as dgrm_name',
'         , objt.objt_attributes."apex"."calledDiagramVersion" as dgrm_version',
'         , cast( null as number ) as dgrm_id',
'         , objt.objt_attributes."apex"."calledDiagramVersionSelection" as dgrm_version_selection',
'      into l_call_def',
'      from flow_objects objt',
'     where objt.objt_id = pi_call_objt_id',
'    ;',
'',
'    return l_call_def;',
'',
'  end get_call_definition;',
'',
'  procedure process_callActivity',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type',
'    , p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is',
'    l_call_definition           t_call_def;',
'    l_called_dgrm_id            flow_diagrams.dgrm_id%type;',
'    l_called_start_objt         flow_objects%rowtype;',
'    l_called_subflow_context    flow_types_pkg.t_subflow_context;',
'    l_calling_sbfl_scope        flow_subflows.sbfl_scope%type;',
'    l_prdg_id                   flow_instance_diagrams.prdg_id%type;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_callActivity''',
'    , ''object'', p_step_info.target_objt_tag ',
'    );',
'',
'    -- get Call activity Attributes',
'    l_call_definition := get_call_definition ( pi_call_objt_id  => p_step_info.target_objt_id );',
'',
'    -- find called diagram and lock it in the flow_instance_diagrams',
'',
'    select child_prdg.prdg_dgrm_id',
'         , child_prdg.prdg_id',
'      into l_called_dgrm_id',
'         , l_prdg_id',
'      from flow_instance_diagrams child_prdg',
'      join flow_instance_diagrams parent_prdg',
'        on parent_prdg.prdg_id = child_prdg.prdg_prdg_id',
'     where child_prdg.prdg_prcs_id = p_process_id',
'       and child_prdg.prdg_calling_dgrm = p_sbfl_info.sbfl_dgrm_id',
'       and child_prdg.prdg_calling_objt = p_step_info.target_objt_ref',
'       and parent_prdg.prdg_diagram_level = p_sbfl_info.sbfl_diagram_level',
'       for update of child_prdg.prdg_diagram_level wait 2',
'    ;',
'',
'    -- find start object',
'',
'    l_called_start_objt    := flow_diagram.get_start_event ',
'                                    ( p_dgrm_id       => l_called_dgrm_id',
'                                    , p_process_id    => p_process_id',
'                                    );',
'',
'    -- create initial subflow in called activity (set new dgrm id, new scope)',
'',
'    l_called_subflow_context := flow_engine_util.subflow_start ',
'      ( p_process_id              => p_process_id',
'      , p_parent_subflow          => p_subflow_id',
'      , p_starting_object         => p_step_info.target_objt_ref -- parent callActivity activity',
'      , p_current_object          => l_called_start_objt.objt_bpmn_id -- callActivity Start event',
'      , p_route                   => ''call main''',
'      , p_last_completed          => p_sbfl_info.sbfl_current',
'      , p_status                  => flow_constants_pkg.gc_sbfl_status_running ',
'      , p_parent_sbfl_proc_level  => p_sbfl_info.sbfl_process_level',
'      , p_new_proc_level          => true',
'      , p_new_scope               => true',
'      , p_new_diagram             => true',
'      , p_dgrm_id                 => l_called_dgrm_id',
'      );',
'',
'      -- Always do all updates to parent data first before performing any next step in the children.',
'      -- Reason: A subflow could immediately disappear if we''re stepping through it completly.',
'      -- check for any errors on the step',
'',
'    if not flow_globals.get_step_error then ',
'      -- set boundaryEvent Timers on parent, if any',
'      flow_boundary_events.set_boundary_events ',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_sbfl_info  => p_sbfl_info',
'      );  ',
'      if not flow_globals.get_step_error then ',
'        -- Check again, then Update parent subflow to ''in callActivity''',
'        update flow_subflows sbfl',
'        set   sbfl.sbfl_current         = p_step_info.target_objt_ref -- parent call Activity',
'            , sbfl.sbfl_last_completed  = p_sbfl_info.sbfl_last_completed',
'            , sbfl.sbfl_status          = flow_constants_pkg.gc_sbfl_status_in_callactivity',
'            , sbfl.sbfl_last_update     = systimestamp',
'            , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'        where sbfl.sbfl_id = p_subflow_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'        returning sbfl.sbfl_scope into l_calling_sbfl_scope',
'        ; ',
'',
'        -- update the instance_calls table with the new diagram_level',
'        update flow_instance_diagrams prdg',
'           set prdg.prdg_diagram_level = l_called_subflow_context.sbfl_id',
'         where prdg.prdg_id = l_prdg_id;',
'',
'',
'',
'',
'        -- map inVariables expressions for call (variables in called scope, expressions in calling scope)',
'        flow_expressions.process_expressions',
'        ( pi_objt_id => p_step_info.target_objt_id ',
'        , pi_set          => flow_constants_pkg.gc_expr_set_in_variables',
'        , pi_prcs_id      => p_process_id',
'        , pi_sbfl_id      => l_called_subflow_context.sbfl_id   --- should this be logged on calling or called subflows?  variables only in scope of called...',
'        , pi_step_key     => l_called_subflow_context.step_key',
'        , pi_var_scope    => l_called_subflow_context.scope',
'        , pi_expr_scope   => l_calling_sbfl_scope',
'        );',
'',
'        -- add diagram start to the instance log',
'        flow_logging.log_instance_event',
'        ( p_process_id    => p_process_id',
'        , p_objt_bpmn_id  => p_step_info.target_objt_ref',
'        , p_event         => flow_constants_pkg.gc_prcs_event_enter_call',
'        , p_event_level   => flow_constants_pkg.gc_logging_level_routine',
'        , p_comment       => ''Starting called diagram ''||l_call_definition.dgrm_name||',
'                             '' version ''||l_call_definition.dgrm_version||',
'                             '' in diagram level ''||l_called_subflow_context.sbfl_id',
'        );',
'',
'        if not flow_globals.get_step_error then ',
'          -- commit the transaction in the parent process level / diagram plsql_optimize_level',
'          commit;',
'',
'          apex_debug.info ( p_message => ''New Call Activity Parent Commited'');',
'',
'          -- reset step_had_error flag',
'          flow_globals.set_step_error ( p_has_error => false);',
'',
'          -- relock child subflow in new process level',
'          if flow_engine_util.lock_subflow',
'              ( p_subflow_id => l_called_subflow_context.sbfl_id',
'              )',
'          then',
'            -- run on-event expressions for child startEvent (inside called diagram scope)',
'            flow_expressions.process_expressions',
'            ( pi_objt_bpmn_id => l_called_start_objt.objt_bpmn_id ',
'            , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'            , pi_prcs_id      => p_process_id',
'            , pi_sbfl_id      => l_called_subflow_context.sbfl_id',
'            , pi_step_key     => l_called_subflow_context.step_key',
'            , pi_var_scope    => l_called_subflow_context.scope',
'            , pi_expr_scope   => l_called_subflow_context.scope',
'            );',
'            if not flow_globals.get_step_error then ',
'              -- check again for any errors from expressions before stepping forward in the called activity',
'              flow_engine.flow_complete_step   ',
'              ( p_process_id    => p_process_id',
'              , p_subflow_id    => l_called_subflow_context.sbfl_id',
'              , p_step_key      => l_called_subflow_context.step_key',
'              );',
'            end if;',
'          end if;',
'          -- reset step_had_error flag',
'          flow_globals.set_step_error ( p_has_error => false);',
'        end if;',
'      end if;',
'    end if;',
'  end process_callActivity; ',
'',
'end flow_call_activities;',
'/',
'',
'create or replace package body flow_db_exec',
'as ',
'/* ',
'-- Flows for APEX - flow_db_exec.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022-2023.',
'-- (c) Copyright Flowquest Limited and/ or its affiliates. 2024-2025',
'--',
'-- Created  08-Dec-2022  Richard Allen (Oracle Corporation)',
'-- Changed  21-FEB-2023  Moritz Klein (MT GmbH)',
'-- Changed  11-Feb-2024  Richard Allen (Flowquest)',
'--',
'*/',
'',
'  function exec_flows_sql',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_sql_text       varchar2',
'  , pi_result_type    varchar2  ',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_step_key       flow_subflows.sbfl_step_key%type default null',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  as  ',
'    l_sql_text        varchar2(4000) := pi_sql_text;',
'    l_bind_parameters apex_exec.t_parameters;',
'    l_context         apex_exec.t_context;',
'    l_result_column   apex_exec.t_column;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'    l_result_set_vc2  apex_t_varchar2;',
'    l_result          flow_process_variables.prov_var_vc2%type;',
'    l_indx            pls_integer;',
'',
'    e_var_exp_must_return_one_column exception;',
'    e_var_exp_sql_too_many_rows      exception;',
'  begin',
'      apex_debug.enter',
'    ( ''flow_expressions.exec_flows_sql''',
'    , ''type'', pi_result_type',
'    , ''sql text'' , pi_sql_text',
'    );',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := pi_result_type;',
'',
'    l_sql_text := rtrim ( l_sql_text, '';'');',
'',
'    if pi_prcs_id is not null then',
'      -- substitute any F4A Process Variables',
'      flow_proc_vars_int.do_substitution',
'      ( pi_prcs_id => pi_prcs_id',
'      , pi_sbfl_id => pi_sbfl_id',
'      , pi_scope   => pi_scope',
'      , pi_step_key => pi_step_key',
'      , pio_string => l_sql_text',
'      );',
'      -- get bind parameters',
'      l_bind_parameters := flow_proc_vars_int.get_parameter_list',
'                              ( pi_expr               => l_sql_text',
'                              , pi_prcs_id            => pi_prcs_id',
'                              , pi_sbfl_id            => pi_sbfl_id',
'                              , pi_step_key           => pi_step_key',
'                              , pi_scope              => pi_scope',
'                              );',
'    end if;',
'    l_context := apex_exec.open_query_context',
'                      ( p_location          => apex_exec.c_location_local_db',
'                      , p_sql_query         => l_sql_text',
'                      , p_sql_parameters    => l_bind_parameters',
'                      , p_total_row_count   => true',
'                      );',
'',
'    -- check row and column limits for single and list options for ',
'    if (   pi_expr_type in ( flow_constants_pkg.gc_expr_type_sql ',
'                           , flow_constants_pkg.gc_expr_type_sql_delimited_list)',
'       and apex_exec.get_column_count (p_context => l_context) <> 1 )',
'    then',
'      raise e_var_exp_must_return_one_column;',
'    end if;',
'    if (   pi_expr_type = flow_constants_pkg.gc_expr_type_sql ',
'       and apex_exec.get_total_row_count (p_context => l_context) > 1  )    ',
'    then',
'      raise e_var_exp_sql_too_many_rows;',
'    end if;',
'    -- for SQl Single we can return several datatypes, and convert to other datatypes',
'    -- for SQl multi, we can only return vc2 or number datatypes, but need to loop to return into array',
'    -- and then build concatenated colon separated string',
'    if pi_expr_type = flow_constants_pkg.gc_expr_type_sql  then',
'      -- SQl Single row',
'      -- result must be in only row/column returned',
'      if apex_exec.next_row (p_context => l_context) then',
'        -- if query returns values, set them.  If not, all values will be null (correctly)',
'        l_result_column := apex_exec.get_column ( p_context => l_context',
'                                                , p_column_idx => 1',
'                                                );',
'        case pi_result_type ',
'        when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'          if l_result_column.data_type = apex_exec.c_data_type_varchar2 then',
'            l_result_rec.var_vc2 := apex_exec.get_varchar2  ( p_context => l_context',
'                                                            , p_column_idx => 1',
'                                                            );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_date then',
'            l_result_rec.var_vc2 := to_char ( apex_exec.get_date ( p_context => l_context',
'                                                                 , p_column_idx => 1 )',
'                                            , flow_constants_pkg.gc_prov_default_date_format',
'                                            );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_number then',
'            l_result_rec.var_vc2 := to_char ( apex_exec.get_number ( p_context => l_context',
'                                                                   , p_column_idx => 1 )',
'                                            );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_timestamp_tz then',
'            l_result_rec.var_vc2 := to_char ( apex_exec.get_timestamp_tz ( p_context => l_context',
'                                                                         , p_column_idx => 1 )',
'                                            , flow_constants_pkg.gc_prov_default_tstz_format',
'                                            );',
'          -- add conversion CLOB to varchar2 if length OK?',
'          end if;',
'',
'        when flow_constants_pkg.gc_prov_var_type_date then',
'          if l_result_column.data_type = apex_exec.c_data_type_date then',
'            l_result_rec.var_date := apex_exec.get_date ( p_context => l_context',
'                                                        , p_column_idx => 1 );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_varchar2 then',
'            begin',
'              l_result_rec.var_date := to_date ( apex_exec.get_varchar2 ( p_context => l_context',
'                                                                        , p_column_idx => 1 )',
'                                               , flow_constants_pkg.gc_prov_default_date_format',
'                                               );  ',
'            exception',
'              when others then',
'                l_result_rec.var_date := null;',
'            end;',
'          elsif l_result_column.data_type = apex_exec.c_data_type_timestamp_tz then',
'            l_result_rec.var_date := cast (apex_exec.get_timestamp_tz ( p_context => l_context',
'                                                        , p_column_idx => 1 )',
'                                          as date );',
'          end if;',
'',
'        when flow_constants_pkg.gc_prov_var_type_number then',
'          if l_result_column.data_type = apex_exec.c_data_type_number then',
'            l_result_rec.var_num := apex_exec.get_number ( p_context => l_context',
'                                                         , p_column_idx => 1 );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_varchar2 then',
'            begin',
'              l_result_rec.var_num := to_number ( apex_exec.get_varchar2 ( p_context => l_context',
'                                                                         , p_column_idx => 1 )',
'                                                );  ',
'            exception',
'              when others then',
'                l_result_rec.var_num := null;',
'            end;',
'          end if;',
'',
'',
'        when flow_constants_pkg.gc_prov_var_type_tstz then',
'          if l_result_column.data_type = apex_exec.c_data_type_timestamp_tz then',
'            l_result_rec.var_tstz := apex_exec.get_timestamp_tz ( p_context => l_context',
'                                                              , p_column_idx => 1 );',
'          elsif l_result_column.data_type = apex_exec.c_data_type_varchar2 then',
'            begin',
'              l_result_rec.var_tstz := to_timestamp_tz ( apex_exec.get_varchar2 ( p_context => l_context',
'                                                                              , p_column_idx => 1 )',
'                                                     , flow_constants_pkg.gc_prov_default_tstz_format',
'                                                     );  ',
'            exception',
'              when others then',
'                l_result_rec.var_tstz := null;',
'            end;',
'          elsif l_result_column.data_type = apex_exec.c_data_type_date then',
'            -- convert date to timestamp_tz using current session timezone',
'             l_result_rec.var_tstz := cast (apex_exec.get_date ( p_context => l_context',
'                                                              , p_column_idx'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' => 1 )',
'                                          as timestamp with time zone);         ',
'          end if;',
'        end case;',
'      end if;',
'    elsif pi_expr_type = flow_constants_pkg.gc_expr_type_sql_delimited_list  then',
'      -- get the returned column info...',
'      l_result_column := apex_exec.get_column ( p_context => l_context',
'                                              , p_column_idx => 1',
'                                              );',
'      l_result_set_vc2 := apex_t_varchar2();',
'      loop ',
'        -- result must be in only row/column returned',
'        exit when not apex_exec.next_row (p_context => l_context); ',
'        l_result_set_vc2.extend;',
'        l_indx := l_result_set_vc2.last;',
'        if l_result_column.data_type = apex_exec.c_data_type_varchar2 then',
'          l_result_set_vc2(l_indx)  := apex_exec.get_varchar2  ( p_context => l_context',
'                                                               , p_column_idx => 1',
'                                                               );',
'        elsif l_result_column.data_type = apex_exec.c_data_type_number then',
'          l_result_set_vc2(l_indx)  := to_char ( apex_exec.get_number ( p_context => l_context',
'                                                                      , p_column_idx => 1 )',
'                                               );',
'        end if;',
'      end loop; ',
'      -- create delimited string output',
'      l_result_rec.var_vc2 := apex_string.join',
'                            ( p_table => l_result_set_vc2',
'                            , p_sep => '':''',
'                            );',
'      apex_debug.message(p_message => ''Delimited String created %s'', p0 => l_result_rec.var_vc2, p_level => 3);',
'    elsif pi_expr_type = flow_constants_pkg.gc_expr_type_sql_json_array  then',
'      ',
'      apex_json.initialize_clob_output (p_preserve => true);',
'      apex_json.write_context ( p_name       => null',
'                              , p_context    => l_context',
'                              , p_write_null => true);',
'      l_result_rec.var_json := apex_json.get_clob_output;',
'      apex_json.free_output;',
'      apex_debug.message(p_message => ''JSON Array created %s'', p0 => l_result_rec.var_json, p_level => 3);',
'    end if;',
'    -- close the cursor',
'    apex_exec.close (l_context);',
'    return l_result_rec;',
'  exception',
'    when e_var_exp_sql_too_many_rows then',
'      apex_exec.close (l_context);',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''exec_sql_too_many_rows''',
'      );',
'      -- $F4AMESSAGE ''exec_sql_too_many_rows'' || ''Error executing SQL Query - query returns more than one row.''  ',
'    when e_var_exp_must_return_one_column then',
'      apex_exec.close (l_context);',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''exec_sql_too_many_values''',
'      );',
'      -- $F4AMESSAGE ''exec_sql_too_many_values'' || ''Error executing SQL Query - query returns more than one value.''  ',
'    when others then',
'      apex_debug.error',
'      ( p_message => ''Error executing SQL query for process id %1. SQLERRM: %2''',
'      , p1        => pi_prcs_id',
'      , p2        => sqlerrm',
'      );',
'      apex_exec.close (l_context);',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_sql_other''',
'      );',
'      -- $F4AMESSAGE ''exec_sql_other'' || ''Error executing SQL Query.  SQL error shown in event log.''    ',
'  end exec_flows_sql;',
'',
'  function exec_flows_plsql_vc2',
'  ( pi_prcs_id         flow_processes.prcs_id%type default null',
'  , pi_sbfl_id         flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text      varchar2',
'  , pi_scope           flow_subflows.sbfl_scope%type default 0',
'  , pi_expr_type       flow_types_pkg.t_expr_type',
'  , pi_bind_parameters apex_exec.t_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin        varchar2(100);',
'    l_wrap_end          varchar2(100);',
'    l_expr              varchar2(4000) := pi_plsql_text;',
'    l_bind_parameters   apex_exec.t_parameters := pi_bind_parameters;',
'    l_result_rec        flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql_vc2''',
'    , ''plsql text'', pi_plsql_text',
'    );',
'    case ',
'    when pi_expr_type = flow_constants_pkg.gc_expr_type_plsql_expression ',
'      or pi_expr_type = flow_constants_pkg.gc_expr_type_plsql_raw_expression ',
'    then',
'      l_wrap_begin  := c_wrap_vc2_expr_pre;',
'      l_wrap_end    := c_wrap_vc2_expr_post;',
'    when pi_expr_type = flow_constants_pkg.gc_expr_type_plsql_function_body ',
'      or pi_expr_type = flow_constants_pkg.gc_expr_type_plsql_raw_function_body ',
'    then',
'      l_wrap_begin  := c_wrap_vc2_func_pre;',
'      l_wrap_end    := c_wrap_vc2_func_post;',
'    end case;',
'',
'    apex_exec.add_parameter ( l_bind_parameters, ''BIND_OUT_VAR'','''');',
'',
'    apex_exec.execute_plsql(',
'        p_plsql_code      => l_wrap_begin||pi_plsql_text||l_wrap_end,',
'        p_auto_bind_items => false,',
'        p_sql_parameters  => l_bind_parameters );',
'',
'    l_result_rec.var_vc2  := apex_exec.get_parameter_varchar2',
'                             ( p_parameters => l_bind_parameters',
'                             , p_name       => ''BIND_OUT_VAR''); ',
'',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := flow_constants_pkg.gc_prov_var_type_varchar2;',
'',
'    return l_result_rec;   ',
'  end exec_flows_plsql_vc2;',
'',
'  function exec_flows_plsql_num',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text     varchar2',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  , pi_bind_parameters apex_exec.t_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin      varchar2(100);',
'    l_wrap_end        varchar2(100);',
'    l_expr            varchar2(4000) := pi_plsql_text;',
'    l_bind_parameters apex_exec.t_parameters := pi_bind_parameters;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql_num''',
'    , ''plsql text'', pi_plsql_text',
'    );',
'    case ',
'    when pi_expr_type  = flow_constants_pkg.gc_expr_type_plsql_expression then',
'      l_wrap_begin  := c_wrap_num_expr_pre;',
'      l_wrap_end    := c_wrap_num_expr_post;',
'    when pi_expr_type = flow_constants_pkg.gc_expr_type_plsql_raw_expression then',
'      l_wrap_begin  := c_wrap_num_raw_expr_pre;',
'      l_wrap_end    := c_wrap_num_raw_expr_post;',
'    when pi_expr_type  = flow_constants_pkg.gc_expr_type_plsql_function_body then',
'      l_wrap_begin  := c_wrap_num_func_pre;',
'      l_wrap_end    := c_wrap_num_func_post;',
'    when pi_expr_type  = flow_constants_pkg.gc_expr_type_plsql_raw_function_body then',
'      l_wrap_begin  := c_wrap_num_raw_func_pre;',
'      l_wrap_end    := c_wrap_num_raw_func_post;',
'    end case;',
'',
'    apex_exec.add_parameter ( l_bind_parameters, ''BIND_OUT_VAR'','''');',
'',
'    apex_exec.execute_plsql(',
'        p_plsql_code      => l_wrap_begin||pi_plsql_text||l_wrap_end,',
'        p_auto_bind_items => false,',
'        p_sql_parameters  => l_bind_parameters );',
'',
'    l_result_rec.var_num  := cast ( apex_exec.get_parameter_varchar2',
'                                    ( p_parameters => l_bind_parameters',
'                                    , p_name       => ''BIND_OUT_VAR'')',
'                                  as number ); ',
'',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := flow_constants_pkg.gc_prov_var_type_number;',
'',
'    apex_debug.message(p_message => ''Number result %0'', p0 => l_result_rec.var_num, p_level => 3);',
'',
'    return l_result_rec;   ',
'  end exec_flows_plsql_num;',
'',
'  function exec_flows_plsql_date',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text     varchar2',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  , pi_bind_parameters apex_exec.t_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin      varchar2(100);',
'    l_wrap_end        varchar2(100);',
'    l_expr            varchar2(4000) := pi_plsql_text;',
'    l_bind_parameters apex_exec.t_parameters := pi_bind_parameters;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql_date''',
'    , ''plsql text'', pi_plsql_text',
'    );',
'    case pi_expr_type ',
'    when flow_constants_pkg.gc_expr_type_plsql_expression then',
'      -- legacy mode - expression will return a vc2 in our format',
'      l_wrap_begin  := c_wrap_date_expr_pre;',
'      l_wrap_end    := c_wrap_date_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_expression then',
'      -- new ''raw'' mode - expression will return a date',
'      l_wrap_begin  := c_wrap_date_raw_expr_pre;',
'      l_wrap_end    := c_wrap_date_raw_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_function_body then',
'      -- legacy mode - function will return a vc2 in our format',
'      l_wrap_begin  := c_wrap_date_func_pre;',
'      l_wrap_end    := c_wrap_date_func_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_function_body then',
'      -- new ''raw'' mode - function will return a date',
'      l_wrap_begin  := c_wrap_date_raw_func_pre;',
'      l_wrap_end    := c_wrap_date_raw_func_post;',
'    end case;',
'',
'    apex_exec.add_parameter ( l_bind_parameters, ''BIND_OUT_VAR'','''');',
'',
'    apex_exec.execute_plsql(',
'        p_plsql_code      => l_wrap_begin||pi_plsql_text||l_wrap_end,',
'        p_auto_bind_items => false,',
'        p_sql_parameters  => l_bind_parameters );',
'',
'    l_result_rec.var_date  := to_date ( apex_exec.get_parameter_varchar2',
'                                      ( p_parameters => l_bind_parameters',
'                                      , p_name       => ''BIND_OUT_VAR'')',
'                                     , flow_constants_pkg.gc_prov_default_date_format ); ',
'',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := flow_constants_pkg.gc_prov_var_type_date;',
'',
'    return l_result_rec;   ',
'  end exec_flows_plsql_date;',
'',
'  function exec_flows_plsql_tstz',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text     varchar2',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  , pi_bind_parameters apex_exec.t_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin      varchar2(100);',
'    l_wrap_end        varchar2(100);',
'    l_expr            varchar2(4000) := pi_plsql_text;',
'    l_bind_parameters apex_exec.t_parameters := pi_bind_parameters;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'    l_statement       varchar2(4000);',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql_tstz''',
'    , ''plsql text'', pi_plsql_text',
'    );',
'    case pi_expr_type ',
'    when flow_constants_pkg.gc_expr_type_plsql_expression then',
'      -- legacy mode - expression will return a vc2 in our format     ',
'      l_wrap_begin  := c_wrap_tstz_expr_pre;',
'      l_wrap_end    := c_wrap_tstz_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_expression then',
'      -- new ''raw'' mode - expression will return a tstz      ',
'      l_wrap_begin  := c_wrap_tstz_raw_expr_pre;',
'      l_wrap_end    := c_wrap_tstz_raw_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_function_body then',
'      -- legacy mode - function will return a vc2 in our format   ',
'      l_wrap_begin  := c_wrap_tstz_func_pre;',
'      l_wrap_end    := c_wrap_tstz_func_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_function_body then',
'      -- new ''raw'' mode - function will return a tstz',
'      l_wrap_begin  := c_wrap_tstz_raw_func_pre;',
'      l_wrap_end    := c_wrap_tstz_raw_func_post;',
'    end case;',
'',
'    apex_exec.add_parameter ( l_bind_parameters, ''BIND_OUT_VAR'','''');',
'',
'    l_statement := l_wrap_begin||pi_plsql_text||l_wrap_end;',
'   ',
'    apex_exec.execute_plsql(',
'        p_plsql_code      => l_statement,',
'        p_auto_bind_items => false,',
'        p_sql_parameters  => l_bind_parameters );',
'',
'    l_result_rec.var_tstz  := to_timestamp_tz ( apex_exec.get_parameter_varchar2',
'                                                ( p_parameters => l_bind_parameters',
'                                                , p_name       => ''BIND_OUT_VAR'')',
'                                              , flow_constants_pkg.gc_prov_default_tstz_format ); ',
'',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := flow_constants_pkg.gc_prov_var_type_tstz;',
'',
'    return l_result_rec;   ',
'  end exec_flows_plsql_tstz;',
'',
'  function exec_flows_plsql_bool',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text     varchar2',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  , pi_bind_parameters apex_exec.t_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin      varchar2(100);',
'    l_wrap_end        varchar2(100);',
'    l_expr            varchar2(4000) := pi_plsql_text;',
'    l_bind_parameters apex_exec.t_parameters := pi_bind_parameters;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql_bool''',
'    , ''plsql text'', pi_plsql_text',
'    );',
'    case pi_expr_type ',
'    when flow_constants_pkg.gc_expr_type_plsql_expression then',
'      -- legacy mode - expression returns boolean condition directly',
'      l_wrap_begin  := c_wrap_bool_expr_pre;',
'      l_wrap_end    := c_wrap_bool_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_expression then',
'      -- raw mode - expression returns boolean condition directly',
'      l_wrap_begin  := c_wrap_bool_raw_expr_pre;',
'      l_wrap_end    := c_wrap_bool_raw_expr_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_function_body then',
'      -- legacy mode - function body returns text ''true''/''false''',
'      l_wrap_begin  := c_wrap_bool_func_pre;',
'      l_wrap_end    := c_wrap_bool_func_post;',
'    when flow_constants_pkg.gc_expr_type_plsql_raw_function_body then',
'      -- raw mode - function body returns boolean',
'      l_wrap_begin  := c_wrap_bool_raw_func_pre;',
'      l_wrap_end    := c_wrap_bool_raw_func_post;',
'    else',
'      raise_application_error(-20001, ''Unsupported boolean expression type: '' || pi_expr_type);',
'    end case;',
'',
'    apex_exec.add_parameter ( l_bind_parameters, ''BIND_OUT_VAR'','''');',
'',
'    apex_exec.execute_plsql(',
'        p_plsql_code      => l_wrap_begin||pi_plsql_text||l_wrap_end,',
'        p_auto_bind_items => false,',
'        p_sql_parameters  => l_bind_parameters );',
'',
'    l_result_rec.var_vc2  :=  apex_exec.get_parameter_varchar2',
'                              ( p_parameters => l_bind_parameters',
'                              , p_name       => ''BIND_OUT_VAR'')',
'                              ; ',
'',
'    l_result_rec.var_name   := ''result'';',
'    l_result_rec.var_type   := flow_constants_pkg.gc_prov_var_type_varchar2;',
'',
'    return l_result_rec;   ',
'  end exec_flows_plsql_bool;',
'',
'  function exec_flows_plsql',
'  ( pi_prcs_id        flow_processes.prcs_id%type default null',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type default null',
'  , pi_plsql_text     varchar2',
'  , pi_result_type    varchar2  ',
'  , pi_scope          flow_subflows.sbfl_scope%type default 0',
'  , pi_step_key       flow_subflows.sbfl_step_key%type default null',
'  , pi_expr_type      flow_types_pkg.t_expr_type',
'  , pi_state_params   apex_exec.t_parameters default apex_exec.c_empty_parameters',
'  ) return flow_proc_vars_int.t_proc_var_value',
'  is',
'    l_wrap_begin      varchar2(100);',
'    l_wrap_end        varchar2(100);',
'    l_bind_parameters apex_exec.t_parameters;',
'    l_expr            varchar2(4000) := pi_plsql_text;',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_db_exec.exec_flows_plsql''',
'    , ''plsql text'', pi_plsql_text',
'    , ''plsql type'' , pi_expr_type ',
'    );',
'    if pi_prcs_id is not null then',
'      -- substitute any F4A Process Variables',
'      flow_proc_vars_int.do_substitution',
'      ( pi_prcs_id => pi_prcs_id',
'      , pi_sbfl_id => pi_sbfl_id',
'      , pi_scope   => pi_scope',
'      , pi_step_key => pi_step_key',
'      , pio_string => l_expr',
'      );',
'',
'      -- strip any trailing ; as our wrapper code adds it.',
'      -- But only for expressions, functions need it still.',
'      if pi_expr_type in ( flow_constants_pkg.gc_expr_type_plsql_expression, flow_constants_pkg.gc_expr_type_plsql_raw_expression )',
'      then',
'        l_expr := rtrim(l_expr, '';'');',
'      end if;',
'',
'      -- get bind parameters',
'      l_bind_parameters := flow_proc_vars_int.get_parameter_list',
'                              ( pi_expr               => l_expr',
'                              , pi_prcs_id            => pi_prcs_id',
'                              , pi_sbfl_id            => pi_sbfl_id',
'                              , pi_scope              => pi_scope',
'                              , pi_step_key           => pi_step_key',
'                              , pi_state_params       => pi_state_params',
'                              );    ',
'    end if;',
'',
'    case pi_result_type ',
'    when flow_constants_pkg.gc_prov_var_type_varchar2 then ',
'      l_result_rec := exec_flows_plsql_vc2  ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );',
'    when flow_constants_pkg.gc_prov_var_type_number then',
'      l_result_rec := exec_flows_plsql_num  ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type ',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );',
'    when flow_constants_pkg.gc_prov_var_type_date then',
'      l_result_rec := exec_flows_plsql_date ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type ',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );',
'    when flow_constants_pkg.gc_prov_var_type_tstz then',
'      l_result_rec := exec_flows_plsql_tstz ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type ',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );',
'    when flow_constants_pkg.gc_prov_var_type_json then -- use vc2',
'      l_result_rec := exec_flows_plsql_vc2  ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );    ',
'    when flow_constants_pkg.gc_prov_var_type_boolean then ',
'      l_result_rec := exec_flows_plsql_bool ( pi_prcs_id         => pi_prcs_id',
'                                            , pi_sbfl_id         => pi_sbfl_id',
'                                            , pi_plsql_text      => l_expr',
'                                            , pi_scope           => pi_scope',
'                                            , pi_expr_type       => pi_expr_type',
'                                            , pi_bind_parameters => l_bind_parameters',
'                                            );                                          ',
'    end case;    ',
'    return l_result_rec;',
'  exception',
'    when others then',
'      apex_debug.error',
'      ( p_message => ''Error executing PL/SQL (%0) for process id %1. SQLERRM: %2''',
'      , p0        => l_wrap_begin||pi_plsql_text||l_wrap_end',
'      , p1        => pi_prcs_id',
'      , p2        => sqlerrm',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''exec_plsql_other''',
'      );',
'      -- $F4AMESSAGE ''exec_plsql_other'' || ''Error executing PL/SQL.  PL/SQL error shown in event log.''    ',
'',
'  end exec_flows_plsql;',
'',
'end flow_db_exec;',
'/',
'',
'create or replace package body flow_diagram',
'as',
'/* ',
'-- Flows for APEX - flow_diagram.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022-2023.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and/or its affiliates. 2025.',
'--',
'-- Created  10-Dec-2021 Dennis Amthor - MT AG  ',
'-- Modified 22-May-2022 Moritz Klein - MT AG',
'-- Modified 16-Mar-2023 Richard Allen - Oracle',
'--',
'*/',
'  ',
'  function upload_diagram',
'  (',
'    pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content           in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status            in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_log_comment            in flow_flow_event_log.lgfl_comment%type default null',
'  , pi_force_overwrite        in boolean default false',
'  ) return flow_diagrams.dgrm_id%type',
'  as',
'    l_cnt     number;',
'    l_dgrm_id flow_diagrams.dgrm_id%type;',
'  begin',
'',
'    begin',
'      select dgrm_id',
'        into l_dgrm_id',
'        from flow_diagrams',
'       where dgrm_name = pi_dgrm_name',
'         and dgrm_version = pi_dgrm_version',
'      ;',
'    exception',
'      when no_data_found then',
'        l_dgrm_id := null;',
'    end;',
'',
'    if l_dgrm_id is null then',
'      insert',
'        into flow_diagrams ( dgrm_name, dgrm_short_description, dgrm_description, dgrm_icon, dgrm_version, dgrm_category, dgrm_status, dgrm_last_update, dgrm_content )',
'        values ( pi_dgrm_name, pi_dgrm_short_description, pi_dgrm_description, pi_dgrm_icon,',
'                 pi_dgrm_version, pi_dgrm_category,',
'                 pi_dgrm_status, systimestamp, pi_dgrm_content )',
'      returning dgrm_id into l_dgrm_id',
'      ;',
'    else',
'      if (pi_force_overwrite) then',
'        update flow_diagrams',
'          set dgrm_short_description = pi_dgrm_short_description',
'            , dgrm_description = pi_dgrm_description',
'            , dgrm_icon = pi_dgrm_icon',
'            , dgrm_content = pi_dgrm_content',
'            , dgrm_last_update = systimestamp',
'            , dgrm_status  = pi_dgrm_status',
'        where dgrm_id = l_dgrm_id',
'        ;',
'      end if;',
'    end if;',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => l_dgrm_id',
'    , p_dgrm_name       => pi_dgrm_name',
'    , p_dgrm_version    => pi_dgrm_version',
'    , p_dgrm_status     => pi_dgrm_status',
'    , p_dgrm_category   => pi_dgrm_category',
'    , p_dgrm_content    => pi_dgrm_content',
'    , p_comment         => pi_log_comment',
'    );',
'',
'    return l_dgrm_id;',
'',
'  end upload_diagram;',
'',
'  procedure upload_diagram',
'  (',
'    pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content           in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status            in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_log_comment            in flow_flow_event_log.lgfl_comment%type default null',
'  , pi_force_overwrite        in boolean default false',
'  )',
'  as',
'    l_dgrm_id       flow_diagrams.dgrm_id%type;',
'  begin',
'    l_dgrm_id := upload_diagram ( pi_dgrm_name => pi_dgrm_name, pi_dgrm_version => pi_dgrm_version,',
'                                  pi_dgrm_short_description => pi_dgrm_short_description, pi_dgrm_description => pi_dgrm_description, pi_dgrm_icon => pi_dgrm_icon,',
'                                  pi_dgrm_category => pi_dgrm_category, pi_dgrm_content => pi_dgrm_content,',
'                                  pi_dgrm_status => pi_dgrm_status, pi_force_overwrite => pi_force_overwrite,',
'                                  pi_log_comment => pi_log_comment',
'                                );',
'  end upload_diagram;',
'',
'  procedure upload_and_parse',
'  (',
'    pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_content           in flow_diagrams.dgrm_content%type',
'  , pi_dgrm_status            in flow_diagrams.dgrm_status%type default flow_constants_pkg.gc_dgrm_status_draft',
'  , pi_log_comment            in flow_flow_event_log.lgfl_comment%type default null ',
'  , pi_force_overwrite        in boolean default false',
'  )',
'  as',
'    l_dgrm_id  flow_diagrams.dgrm_id%type;',
'  begin',
'',
'    l_dgrm_id := upload_diagram ( pi_dgrm_name => pi_dgrm_name, pi_dgrm_version => pi_dgrm_version,',
'                                  pi_dgrm_short_description => pi_dgrm_short_description, pi_dgrm_description => pi_dgrm_description, pi_dgrm_icon => pi_dgrm_icon,',
'                                  pi_dgrm_category => pi_dgrm_category, pi_dgrm_content => pi_dgrm_content,',
'                                  pi_dgrm_status => pi_dgrm_status, pi_force_overwrite => pi_force_overwrite,',
'                                  pi_log_comment => pi_log_comment',
'                                );',
'    flow_bpmn_parser_pkg.parse ( pi_dgrm_id => l_dgrm_id);',
'  end upload_and_parse;',
'',
'  procedure update_diagram',
'  (',
'    pi_dgrm_id      in flow_diagrams.dgrm_id%type',
'  , pi_dgrm_content in flow_diagrams.dgrm_content%type',
'  )',
'  as',
'  begin',
'',
'    update flow_diagrams',
'       set dgrm_content     = pi_dgrm_content',
'         , dgrm_last_update = systimestamp',
'     where dgrm_id = pi_dgrm_id',
'    ;',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => pi_dgrm_id',
'    , p_dgrm_content    => pi_dgrm_content',
'    , p_comment         => ''Diagram updated''',
'    ); ',
'',
'    flow_bpmn_parser_pkg.parse ( pi_dgrm_id => pi_dgrm_id);',
'  end update_diagram;',
'',
'  function create_diagram(',
'    pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type)',
'  return flow_diagrams.dgrm_id%type',
'  as',
'    l_diagram_exists binary_integer;',
'    l_dgrm_id flow_diagrams.dgrm_id%type;',
'  begin',
'    select count(*)',
'      into l_diagram_exists',
'      from dual',
'     where exists(',
'           select null',
'             from flow_diagrams',
'            where dgrm_name = pi_dgrm_name',
'              and dgrm_version = pi_dgrm_version);',
'',
'    if l_diagram_exists = 0 then',
'      l_dgrm_id := upload_diagram',
'            ( pi_dgrm_name              => pi_dgrm_name',
'            , pi_dgrm_short_description => pi_dgrm_short_description',
'            , pi_dgrm_description       => pi_dgrm_description',
'            , pi_dgrm_icon              => pi_dgrm_icon',
'            , pi_dgrm_version           => pi_dgrm_version',
'            , pi_dgrm_category          => pi_dgrm_category',
'            , pi_dgrm_content           => replace ( flow_constants_pkg.gc_default_xml, ''#RANDOM_PRCS_ID#'',',
'                                              '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'       lower(sys.dbms_random.string(''X'',8))',
'                                                   )',
'            , pi_dgrm_status            => flow_constants_pkg.gc_dgrm_status_draft',
'            );',
'',
'            flow_logging.log_diagram_event ',
'            ( p_dgrm_id         => l_dgrm_id',
'            , p_dgrm_name       => pi_dgrm_name',
'            , p_dgrm_version    => pi_dgrm_version',
'            , p_dgrm_status     => flow_constants_pkg.gc_dgrm_status_draft',
'            , p_dgrm_category   => pi_dgrm_category',
'            , p_comment         => ''Diagram Created as template''',
'            );',
'',
'      flow_bpmn_parser_pkg.parse(',
'        pi_dgrm_id => l_dgrm_id);',
'    else',
'      raise diagram_exists;',
'    end if;',
'    return l_dgrm_id;',
'  end create_diagram;',
'  ',
'  function add_diagram_version(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type,',
'    pi_dgrm_version in flow_diagrams.dgrm_version%type)',
'  return flow_diagrams.dgrm_id%type',
'  as',
'    l_dgrm_id flow_diagrams.dgrm_id%type;',
'    r_diagrams flow_diagrams%rowtype;',
'  begin',
'    select * ',
'      into r_diagrams',
'      from flow_diagrams',
'     where dgrm_id = pi_dgrm_id;',
'',
'    l_dgrm_id := upload_diagram ',
'                 ( pi_dgrm_name              => r_diagrams.dgrm_name',
'                 , pi_dgrm_short_description => r_diagrams.dgrm_short_description',
'                 , pi_dgrm_description       => r_diagrams.dgrm_description',
'                 , pi_dgrm_icon              => r_diagrams.dgrm_icon',
'                 , pi_dgrm_version           => pi_dgrm_version',
'                 , pi_dgrm_category          => r_diagrams.dgrm_category',
'                 , pi_dgrm_content           => r_diagrams.dgrm_content',
'                 , pi_dgrm_status            => flow_constants_pkg.gc_dgrm_status_draft',
'                 , pi_log_comment            => ''Add new version''',
'                 );',
'',
'    --no need to log here - upload_diagram will log',
'',
'    flow_bpmn_parser_pkg.parse ( pi_dgrm_id => l_dgrm_id);',
'    return l_dgrm_id;',
'  end add_diagram_version;',
'',
'',
'  function import_diagram(',
'    pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type',
'  , pi_dgrm_content           in flow_diagrams.dgrm_content%type',
'  , pi_force_overwrite        in varchar2 default flow_constants_pkg.gc_false) ',
'  return flow_diagrams.dgrm_id%type',
'  as',
'    l_dgrm_id flow_diagrams.dgrm_id%type;',
'    l_dgrm_exists binary_integer;',
'    l_dgrm_status flow_diagrams.dgrm_status%type;',
'    l_diagram_unknown boolean;',
'    l_diagram_is_draft boolean;',
'  begin',
'    select count(*)',
'      into l_dgrm_exists',
'      from flow_diagrams',
'     where dgrm_name = pi_dgrm_name',
'       and dgrm_version = pi_dgrm_version;',
'',
'    if (l_dgrm_exists > 0) then',
'        select dgrm_status',
'        into l_dgrm_status',
'        from flow_diagrams',
'        where dgrm_name = pi_dgrm_name',
'        and dgrm_version = pi_dgrm_version;',
'    end if;',
'',
'    l_diagram_unknown  := l_dgrm_exists = 0;',
'    l_diagram_is_draft := l_dgrm_exists > 0 ',
'                      and pi_force_overwrite = flow_constants_pkg.gc_true',
'                      and l_dgrm_status = flow_constants_pkg.gc_dgrm_status_draft;',
'',
'    if l_diagram_unknown or l_diagram_is_draft then',
'      l_dgrm_id := upload_diagram',
'                   ( pi_dgrm_name              => pi_dgrm_name',
'                   , pi_dgrm_short_description => pi_dgrm_short_description',
'                   , pi_dgrm_description       => pi_dgrm_description',
'                   , pi_dgrm_icon              => pi_dgrm_icon',
'                   , pi_dgrm_version           => pi_dgrm_version',
'                   , pi_dgrm_category          => pi_dgrm_category',
'                   , pi_dgrm_content           => pi_dgrm_content',
'                   , pi_force_overwrite        => pi_force_overwrite = flow_constants_pkg.gc_true',
'                   , pi_log_comment            => ''import diagram''',
'                   );',
'      flow_bpmn_parser_pkg.parse ( pi_dgrm_id => l_dgrm_id );',
'    else',
'      if (l_dgrm_status = flow_constants_pkg.gc_dgrm_status_draft) then',
'        raise diagram_exists;',
'      else',
'        raise diagram_not_draft;',
'      end if;',
'    end if;',
'    return l_dgrm_id;',
'  end import_diagram;',
'  ',
'  ',
'  function diagram_is_modifiable(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type)',
'  return boolean',
'  as',
'    l_dgrm_status flow_diagrams.dgrm_status%type;',
'    l_is_draft boolean;',
'    l_is_released boolean;',
'    l_is_development boolean;',
'  begin',
'    if pi_dgrm_id is not null then',
'      select dgrm_status',
'        into l_dgrm_status',
'        from flow_diagrams',
'       where dgrm_id = pi_dgrm_id;',
'      ',
'      l_is_draft       := l_dgrm_status = flow_constants_pkg.gc_dgrm_status_draft;',
'      l_is_released    := l_dgrm_status = flow_constants_pkg.gc_dgrm_status_released;',
'      l_is_development := flow_engine_util.get_config_value(',
'                            p_config_key => ''engine_app_mode'',',
'                            p_default_value => flow_constants_pkg.gc_config_default_engine_app_mode)',
'                        = ''development'';',
'      return l_is_draft or (l_is_released and l_is_development);',
'    else',
'      return false;',
'    end if;',
'  end diagram_is_modifiable;',
'',
'  function get_start_event',
'  ( p_dgrm_id                 in flow_diagrams.dgrm_id%type',
'  , p_process_id              in flow_processes.prcs_id%type',
'  , p_event_starting_object   in flow_objects.objt_bpmn_id%type default null',
'  ) return flow_objects%rowtype',
'  is ',
'    l_starting_object     flow_objects%rowtype;',
'  begin',
'    begin',
'      if p_event_starting_object is null then ',
'        -- get the starting object ',
'        select objt.*',
'          into l_starting_object',
'          from flow_objects objt',
'          join flow_objects parent',
'            on parent.objt_id       = objt.objt_objt_id',
'           and parent.objt_dgrm_id  = objt.objt_dgrm_id',
'           and parent.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         where objt.objt_dgrm_id    = p_dgrm_id',
'           and objt.objt_tag_name   = flow_constants_pkg.gc_bpmn_start_event  ',
'           and (    objt.objt_sub_tag_name is null ',
'               or   objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition )',
'        ;',
'      else ',
'        -- get the specified starting object',
'        select objt.*',
'          into l_starting_object',
'          from flow_objects objt',
'         where objt.objt_dgrm_id = p_dgrm_id',
'           and objt.objt_bpmn_id = p_event_starting_object',
'           and objt.objt_tag_name   = flow_constants_pkg.gc_bpmn_start_event ',
'        ;',
'      end if;',
'',
'      apex_debug.info',
'      ( p_message => ''Found starting object %0''',
'      , p0 =>l_starting_object.objt_bpmn_id',
'      );',
'    exception',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''start-multiple-start-events''',
'        );',
'        -- $F4AMESSAGE ''start-multiple-start-events'' || ''You have multiple starting events defined. Make sure your diagram has only one start event.''',
'      when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''start-no-start-event''',
'        );',
'        -- $F4AMESSAGE ''start-no-start-event'' || ''No starting event is defined in the Flow diagram.''',
'    end;',
'    return l_starting_object;',
'  end get_start_event;',
'',
'  function get_bpmn_process_object',
'  ( p_dgrm_id                 in flow_diagrams.dgrm_id%type',
'  , p_process_id              in flow_processes.prcs_id%type',
'  , p_event_starting_object   in flow_objects.objt_bpmn_id%type default null',
'  ) return flow_objects%rowtype',
'  is ',
'    l_bpmn_process     flow_objects%rowtype;',
'  begin',
'    -- note: this function gets the bpmn:process object for the diagram.  ',
'    -- To avoid confusion with the process object in the flow_processes table,',
'    -- we refer to this as the ''bpmn_process'' and ''bpmn:process'' in this routine',
'    begin',
'      if p_event_starting_object is null then ',
'        -- get the diagram starting bpmn:process object ',
'        select parent.*',
'          into l_bpmn_process',
'          from flow_objects objt',
'          join flow_objects parent',
'            on parent.objt_id       = objt.objt_objt_id',
'           and parent.objt_dgrm_id  = objt.objt_dgrm_id',
'           and parent.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         where objt.objt_dgrm_id    = p_dgrm_id',
'           and objt.objt_tag_name   = flow_constants_pkg.gc_bpmn_start_event  ',
'           and (    objt.objt_sub_tag_name is null ',
'               or   objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition )',
'        ;',
'      else ',
'        -- get the specified starting object',
'        select parent.*',
'          into l_bpmn_process',
'          from flow_objects objt',
'          join flow_objects parent',
'            on parent.objt_id       = objt.objt_objt_id',
'           and parent.objt_dgrm_id  = objt.objt_dgrm_id',
'           and parent.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         where objt.objt_dgrm_id = p_dgrm_id',
'           and objt.objt_bpmn_id = p_event_starting_object',
'           and objt.objt_tag_name   = flow_constants_pkg.gc_bpmn_start_event ',
'        ;',
'      end if;',
'',
'      apex_debug.info',
'      ( p_message => ''Found bpmn:process object %0''',
'      , p0 => l_bpmn_process.objt_bpmn_id',
'      );',
'    exception',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''start-multiple-start-events''',
'        );',
'        -- $F4AMESSAGE ''start-multiple-start-events'' || ''You have multiple starting events defined. Make sure your diagram has only one start event.''',
'      when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''start-no-start-event''',
'        );',
'        -- $F4AMESSAGE ''start-no-start-event'' || ''No starting event is defined in the Flow diagram.''',
'    end;',
'    return l_bpmn_process;',
'  end get_bpmn_process_object;',
'',
'  function get_current_diagram',
'    ( pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'    , pi_dgrm_calling_method    in flow_types_pkg.t_bpmn_attribute_vc2',
'    , pi_dgrm_version           in flow_diagrams.dgrm_version%type',
'    , pi_prcs_id                in flow_processes.prcs_id%type default null',
'    )',
'  return flow_diagrams.dgrm_id%type',
'    -- gets the current dgrm_id to be used for a diagram name.',
'    -- returns the current ''released'' diagram or a ''draft'' of version ''0'' ',
'  is',
'    l_dgrm_id     flow_diagrams.dgrm_id%type;',
'  begin',
'    case pi_dgrm_calling_method ',
'    when flow_constants_pkg.gc_dgrm_version_latest_version then',
'      begin ',
'        -- look for the ''released'' version of the diagram',
'        select dgrm_id ',
'          into l_dgrm_id',
'          from flow_diagrams',
'         where dgrm_name = pi_dgrm_name',
'           and dgrm_status = flow_constants_pkg.gc_dgrm_status_released',
'        ;',
'        return l_dgrm_id;',
'      exception',
'        when no_data_found then',
'          -- look for the version 0 (default) of ''draft'' of the diagram',
'          begin',
'            select dgrm_id',
'              into l_dgrm_id',
'              from flow_diagrams',
'             where dgrm_name = pi_dgrm_name',
'               and dgrm_status = flow_constants_pkg.gc_dgrm_status_draft',
'               and dgrm_version = ''0''',
'            ;',
'            return l_dgrm_id;',
'          exception',
'            when no_data_found then',
'              if pi_prcs_id is null then ',
'                -- initial process start so call general error (instance not yet running)',
'                flow_errors.handle_general_error',
'                ( pi_message_key => ''version-no-rel-or-draft-v0''',
'                );',
'                -- $F4AMESSAGE ''version-no-rel-or-draft-v0'' || ''Cannot find released diagram or draft version 0 of diagram - please specify a version or diagram_id''',
'              else ',
'                -- callActivity so log an instance error',
'                flow_errors.handle_instance_error',
'                ( pi_prcs_id     => pi_prcs_id',
'                , pi_message_key => ''version-no-rel-or-draft-v0''',
'                );',
'                -- $F4AMESSAGE ''version-no-rel-or-draft-v0'' || ''Cannot find released diagram or draft version 0 of diagram - please specify a version or diagram_id''',
'              end if; ',
'          end;  ',
'      end;',
'',
'    when flow_constants_pkg.gc_dgrm_version_named_version then',
'      -- dgrm_version was specified',
'      begin',
'        select dgrm_id',
'          into l_dgrm_id',
'          from flow_diagrams',
'         where dgrm_name = pi_dgrm_name',
'           and dgrm_version = pi_dgrm_version',
'        ;',
'      exception',
'        when no_data_found then',
'          -- initial process start so call general error (instance not yet running)',
'          flow_errors.handle_general_error ( pi_message_key => ''version-not-found'');',
'          -- $F4AMESSAGE ''version-not-found'' || ''Cannot find specified diagram version.  Please check version specification.''',
'      end;',
'    end case;',
'    return l_dgrm_id;',
'  end get_current_diagram;',
'',
'',
'  procedure delete_diagram(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type,',
'    pi_cascade in varchar2)',
'  as',
'    type t_prcs_id  is table of flow_processes.prcs_id%type',
'         index by binary_integer;',
'    l_running_instances   t_prcs_id;',
'  begin',
'    if pi_cascade = flow_constants_pkg.gc_true then',
'      select prcs_id',
'        bulk collect into l_running_instances',
'        from flow_processes',
'       where prcs_dgrm_id = pi_dgrm_id;',
'                               ',
'      for i in 1..l_running_instances.count',
'      loop',
'        flow_instances.delete_process',
'        ( p_process_id  => l_running_instances(i)',
'        , p_comment     => ''Instance deleted on Diagram Deletion.''',
'        );',
'      end loop;',
'    end if;',
'    delete from flow_diagrams ',
'     where dgrm_id = pi_dgrm_id;',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => pi_dgrm_id',
'    , p_comment         => ''Diagram deleted.''',
'    );',
'',
'  end delete_diagram;',
'',
'',
'  procedure edit_diagram(',
'    pi_dgrm_id                in flow_diagrams.dgrm_id%type',
'  , pi_dgrm_name              in flow_diagrams.dgrm_name%type',
'  , pi_dgrm_short_description in flow_diagrams.dgrm_short_description%type default null',
'  , pi_dgrm_description       in flow_diagrams.dgrm_description%type default null',
'  , pi_dgrm_icon              in flow_diagrams.dgrm_icon%type default null',
'  , pi_dgrm_category          in flow_diagrams.dgrm_category%type',
'  , pi_dgrm_version           in flow_diagrams.dgrm_version%type)',
'  as',
'    l_dgrm_category flow_diagrams.dgrm_category%type;',
'  begin',
'    -- get existing category',
'    select dgrm_category',
'      into l_dgrm_category',
'      from flow_diagrams',
'     where dgrm_id = pi_dgrm_id;',
'',
'    -- update category of all diagrams with the same name (=all versions of this diagram)',
'    if coalesce(l_dgrm_category, chr(10)) != coalesce(pi_dgrm_category, chr(10) ) then',
'      -- category has changed',
'      update flow_diagrams',
'         set dgrm_category = pi_dgrm_category',
'       where dgrm_name = (',
'             select dgrm_name ',
'               from flow_diagrams',
'              where dgrm_id = pi_dgrm_id);',
'',
'    end if;',
'',
'    update flow_diagrams',
'       set dgrm_name = pi_dgrm_name,',
'           dgrm_short_description = pi_dgrm_short_description,',
'           dgrm_description =  pi_dgrm_description,',
'           dgrm_icon =  pi_dgrm_icon,',
'           dgrm_version = pi_dgrm_version,',
'           dgrm_category = pi_dgrm_category',
'     where dgrm_id = pi_dgrm_id;',
'',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => pi_dgrm_id',
'    , p_dgrm_name       => pi_dgrm_name',
'    , p_dgrm_version    => pi_dgrm_version',
'    , p_dgrm_category   => pi_dgrm_category',
'    , p_comment         => ''Diagram meta-data edited''',
'    );',
'',
'  end edit_diagram;',
'',
'  procedure subscribe_diagram_message_starts',
'  ( pi_dgrm_id        in flow_diagrams.dgrm_id%type',
'  , pi_draft_suffix   in varchar2 default null',
'  )',
'  is',
'    l_subscription    flow_message_flow.t_subscription_details;',
'    l_msub_id         flow_message_subscriptions.msub_id%type;',
'  begin',
'    for message_start_events in ',
'      ( select objt.objt_dgrm_id',
'             , objt.objt_bpmn_id',
'             , objt.objt_sub_tag_name',
'             , objt.objt_attributes."apex"."messageName"."expression" message_name',
'             , objt.objt_attributes."apex"."payloadVariable" payload_var',
'          from flow_objects objt',
'         where objt_dgrm_id      = pi_dgrm_id',
'           and objt_tag_name     = flow_constants_pkg.gc_bpmn_start_event',
'           and objt_sub_tag_name = flow_constants_pkg.gc_bpmn_message_event_definition',
'      )',
'    loop',
'',
'      l_subscription.message_name := message_start_events.message_name;',
'      l_subscription.dgrm_id      := pi_dgrm_id;',
'      l_subscription.callback     := flow_constants_pkg.gc_bpmn_start_event;',
'      l_subscription.callback_par := message_start_events.objt_bpmn_id;',
'      l_subscription.payload_var  := message_start_events.payload_var;',
'',
'      l_msub_id := flow_message_flow.subscribe (p_subscription_details => l_subscription);',
'',
'      apex_debug.message ( p_message => ''Message Start Event - Diagram %0 Start Event %1 Subscribed msub_id = %2.)''',
'      , p0 => pi_dgrm_id',
'      , p1 => message_start_events.objt_bpmn_id',
'      , p2 => l_msub_id',
'      );',
'    end loop;',
'  end subscribe_diagram_message_starts;',
'',
'',
'  procedure release_diagram(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type)',
'  as',
'    l_dgrm_id_deprecated  flow_diagrams.dgrm_id%type;',
'    l_dgrm_content        clob;',
'  begin',
'    -- deprecate existing released version of model if one exists',
'    begin',
'      select dgrm_id',
'        into l_dgrm_id_deprecated',
'        from flow_diagrams',
'       where dgrm_status = flow_constants_pkg.gc_dgrm_status_released',
'         and dgrm_name = (',
'             select dgrm_name ',
'               from flow_diagrams',
'              where dgrm_id = pi_dgrm_id);',
'    exception',
'      when no_data_found then',
'        l_dgrm_id_deprecated := null;',
'    end;',
'',
'    if l_dgrm_id_deprecated is not null then',
'      deprecate_diagram (pi_dgrm_id => l_dgrm_id_deprecated );',
'    end if;',
'',
'    -- logging needs to include copy of the new production diagram for secure modes',
'    select dgrm_content',
'      into l_dgrm_content',
'      from flow_diagrams',
'     where dgrm_id = pi_dgrm_id;',
'',
'    update flow_diagrams',
'       set dgrm_status = flow_constants_pkg.gc_dgrm_status_released',
'     where dgrm_id = pi_dgrm_id;',
'',
'    subscribe_diagram_message_starts (pi_dgrm_id => pi_dgrm_id );',
'',
'    apex_debug.message ( p_message => ''Release Diagram - Diagram %0 released.)''',
'    , p0 => pi_dgrm_id',
'    );',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => pi_dgrm_id',
'    , p_dgrm_status     => flow_constants_pkg.gc_dgrm_status_released',
'    , p_dgrm_content    => l_dgrm_content',
'    , p_comment         => ''Diagram released.''',
'    );',
'',
'  end release_diagram;',
'',
'  procedure release_diagram(',
'    pi_dgrm_name    in flow_diagrams.dgrm_name%type,',
'    pi_dgrm_version in flow_diagrams.dgrm_version%type default ''0'')',
'  is',
'    l_dgrm_id  flow_diagrams.dgrm_id%type;',
'  begin',
'    l_dgrm_id :=  get_current_diagram',
'                  ( pi_dgrm_name              => pi_dgrm_name',
'                  , pi_dgrm_calling_method    => flow_constants_pkg.gc_dgrm_version_named_version',
'                  , pi_dgrm_version           => pi_dgrm_version',
'                  );',
'    release_diagram (pi_dgrm_id => l_dgrm_id);',
'  end release_diagram;',
'',
'  procedure deprecate_diagram(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type)',
'  as',
'  begin',
'',
'    $IF flow_apex_env.ee $THEN',
'      flow_message_util_ee.cancel_diagram_subscriptions ',
'      ( p_dgrm_id   => pi_dgrm_id',
'      , p_callback  => flow_constants_pkg.gc_bpmn_start_event',
'      );',
'    $END',
'',
'    update flow_diagrams',
'       set dgrm_status = flow_constants_pkg.gc_dgrm_status_deprecated',
'     where dgrm_id = pi_dgrm_id;',
'',
'    apex_debug.message ( p_message => ''Release Diagram - Diagram %0 deprecated.)''',
'    , p0 => pi_dgrm_id',
'    );',
'',
'    flow_logging.log_diagram_event ',
'    ( p_dgrm_id         => pi_dgrm_id',
'    , p_dgrm_status     => flow_constants_pkg.gc_dgrm_status_deprecated',
'    , p_comment         => ''Diagram deprecated.''',
'    );   ',
'',
'  end deprecate_diagram;',
'',
'',
'  procedure archive_diagram(',
'    pi_dgrm_id in flow_diagrams.dgrm_id%type)',
'  as',
'    l_running_instances       number ;',
'    e_has_running_instances   exception;',
'  begin',
'    -- check that diagram has no current running process instances',
'    select count(prcs_id)',
'      into l_running_instances',
'      from flow_processes prcs',
'     where prcs.prcs_id in (',
'            select prdg.prdg_prcs_id',
'              from flow_instance_diagrams prdg',
'             where prdg.prdg_dgrm_id = pi_dgrm_id',
'            )',
'       and prcs.prcs_status not in  ( flow_constants_pkg.gc_prcs_status_completed',
'                                    , flow_constants_pkg.gc_prcs_status_terminated',
'                                    );',
'    if l_running_instances = 0 then',
'      update flow_diagrams',
'         set dgrm_status = flow_constants_pkg.gc_dgrm_status_archived',
'       where dgrm_id = pi_dgrm_id;',
'',
'      flow_logging.log_diagram_event ',
'      ( p_dgrm_id         => pi_dgrm_id',
'      , p_dgrm_status     => flow_constants_pkg.gc_dgrm_status_archived',
'      , p_comment         => ''Diagram archived.''',
'      );',
'    else                     ',
'      raise e_has_running_instances;',
'    end if;',
'  exception',
'    when e_has_running_instances then',
'          -- initial process start so call general error (instance not yet running)',
'          flow_errors.handle_general_error ( pi_message_key => ''diagram-archive-has-instances'');',
'          -- $F4AMESSAGE ''diagram-archive-has-instances'' || ''Cannot find specified diagram version.  Please check version specification.''',
'  end archive_diagram;   ',
'',
'  function get_diagram_name',
'    ( pi_dgrm_id       in flow_diagrams.dgrm_id%type)',
'  return flow_diagrams.dgrm_name%type',
'  is',
'    l_dgrm_name   flow_diagrams.dgrm_name%type;',
'  begin',
'    select dgrm_name',
'      into l_dgrm_name',
'      from flow_diagrams',
'     where dgrm_id = pi_dgrm_id',
'    ;',
'     return l_dgrm_name;',
'  end get_diagram_name;',
'',
'end flow_diagram;',
'/',
'',
'create or replace package body flow_engine_util',
'as ',
'/* ',
'-- Flows for APEX - flow_engine_util.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Consulting Limited. 2024-2025',
'--',
'-- Created  April-2021  Richard Allen (Flowquest) - from flow_engine.pkb',
'-- Modified 2022-07-18  Moritz Klein (MT AG)',
'-- Modified 09-Jan-2024  Richard Allen, Flowquest Consulting',
'--',
'*/',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  g_step_keys_enforced    boolean;',
'',
'  function get_config_value',
'  ( ',
'    p_config_key    in flow_configuration.cfig_key%type',
'  , p_default_value in flow_configuration.cfig_value%type',
'  ) return flow_configuration.cfig_value%type',
'  as  ',
'    l_config_value   flow_configuration.cfig_value%type;',
'  begin ',
'    select cfig.cfig_value',
'      into l_config_value',
'      from flow_configuration cfig',
'     where cfig.cfig_key = p_config_key',
'    ;',
'    return l_config_value;',
'  exception ',
'    when no_data_found then ',
'      return p_default_value;',
'  end get_config_value;',
'',
'  procedure set_config_value',
'  (',
'    p_config_key      in flow_configuration.cfig_key%type',
'  , p_value           in flow_configuration.cfig_value%type',
'  , p_update_if_set   in boolean default true',
'  )',
'  is',
'    l_exists      number;',
'  begin',
'    select count(cfig_key)',
'      into l_exists',
'      from flow_configuration',
'     where cfig_key = p_config_key;',
'    ',
'    if l_exists > 0 and p_update_if_set then ',
'      update flow_configuration',
'         set cfig_value = p_value',
'       where cfig_key = p_config_key;',
'    elsif l_exists = 0 then',
'      insert into flow_configuration',
'      ( cfig_key',
'      , cfig_value',
'      )',
'      values',
'      ( p_config_key',
'      , p_value',
'      );',
'    end if;',
'  end set_config_value;',
'',
'  function step_key',
'  ( pi_sbfl_id        in flow_subflows.sbfl_id%type default null',
'  , pi_current        in flow_subflows.sbfl_current%type default null',
'  , pi_became_current in flow_subflows.sbfl_became_current%type default null',
'  ) return flow_subflows.sbfl_step_key%type',
'  is',
'  begin',
'',
'      return sys.dbms_random.string(''A'', 10);',
'  end step_key;',
'',
'  function step_key_valid',
'  ( pi_prcs_id              in flow_processes.prcs_id%type',
'  , pi_sbfl_id              in flow_subflows.sbfl_id%type',
'  , pi_step_key_supplied    in flow_subflows.sbfl_step_key%type',
'  , pi_step_key_required    in flow_subflows.sbfl_step_key%type default null',
'  ) return boolean',
'  is ',
'    l_step_key_required   flow_subflows.sbfl_step_key%type := pi_step_key_required;',
'  begin',
'    if pi_step_key_required is null then',
'',
'      select sbfl.sbfl_step_key',
'        into l_step_key_required',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_id = pi_sbfl_id',
'         and sbfl.sbfl_prcs_id = pi_prcs_id',
'      ;',
'    end if;',
'',
'    apex_debug.info ',
'    ( p_message => ''Step Key Required: %0  Step Key Supplied: %1''',
'    , p0 => l_step_key_required',
'    , p1 => pi_step_key_supplied',
'    );',
'',
'    if pi_step_key_supplied = l_step_key_required then',
'      return true;',
'    elsif (pi_step_key_supplied is null ',
'           and not g_step_keys_enforced) then',
'      return true;',
'    else',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => pi_prcs_id',
'      , pi_sbfl_id     => pi_sbfl_id',
'      , pi_message_key => ''step-key-incorrect''',
'      , p0 => nvl(pi_step_key_supplied, ''"null"'')',
'      , p1 => l_step_key_required',
'      );',
'      -- $F4AMESSAGE ''step-key-incorrect'' || ''This Process Step has already occurred.  (Incorrect step key %0 supplied while exopecting step key %1).'' ',
'      return false;',
'    end if;',
'  end step_key_valid;',
'',
'  function check_subflow_exists',
'  ( ',
'    p_process_id in flow_processes.prcs_id%type',
'  , p_subflow_id in flow_subflows.sbfl_id%type',
'  ) return boolean',
'  is',
'    l_cnt number;',
'  begin',
'    select count(*)',
'      into l_cnt',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_id = p_subflow_id',
'       and sbfl.sbfl_prcs_id = p_process_id',
'    ;',
'    return ( l_cnt = 1 );',
'  end check_subflow_exists;',
'',
'function get_subprocess_parent_subflow',
'  ( p_sbfl_info   in flow_subflows%rowtype',
'  , p_current     in flow_objects.objt_bpmn_id%type -- an object in the subprocess',
'  ) return flow_types_pkg.t_subflow_context',
'  is',
'    l_parent_subflow          flow_types_pkg.t_subflow_context;',
'  begin',
'    -- should return the subprocess that called this subprocess, call activity, ',
'    -- or adhoc subprocess',
'    case p_sbfl_info.sbfl_is_adhoc ',
'    when flow_constants_pkg.gc_true then',
'      -- get parent subflow for an adhoc subprocess',
'      select calling_sbfl.sbfl_id',
'           , calling_sbfl.sbfl_step_key',
'           , calling_sbfl.sbfl_scope',
'        into l_parent_subflow.sbfl_id',
'           , l_parent_subflow.step_key',
'           , l_parent_subflow.scope',
'        from flow_subflows calling_sbfl',
'       where calling_sbfl.sbfl_id      = p_sbfl_info.sbfl_sbfl_id',
'         and calling_sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'         ;',
'      return l_parent_subflow;',
'    else ',
'    -- get parent subflow for a subprocess or a call_activity',
'    select calling_sbfl.sbfl_id',
'         , calling_sbfl.sbfl_step_key',
'         , calling_sbfl.sbfl_scope',
'      into l_parent_subflow.sbfl_id',
'         , l_parent_subflow.step_key',
'         , l_parent_subflow.scope',
'      from flow_subflows calling_sbfl',
'      join flow_subflows called_sbfl',
'        on called_sbfl.sbfl_calling_sbfl = calling_sbfl.sbfl_id',
'       and called_sbfl.sbfl_prcs_id = calling_sbfl.sbfl_prcs_id',
'     where called_sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'       and called_sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'       ;',
'    end case;',
'    return l_parent_subflow;',
'  exception',
'      when no_data_found then',
'        -- no subflow found running the parent process ',
'        return null;',
'  end get_subprocess_parent_subflow;',
'',
'procedure get_number_of_connections ',
'    ( pi_dgrm_id                  in flow_diagrams.dgrm_id%type',
'    , pi_objt_bpmn_id             in flow_objects.objt_bpmn_id%type',
'    , pi_conn_type                in flow_connections.conn_tag_name%type  ',
'    , po_num_forward_connections  out number',
'    , po_num_back_connections     out number',
'    , po_objt_tag_name            out flow_objects.objt_tag_name%type',
'    )',
'  is ',
'  begin   ',
'        select objt.objt_tag_name ',
'        ,  (select count(input_paths.conn_id) ',
'               from flow_connections input_paths ',
'              where input_paths.conn_dgrm_id     = objt.objt_dgrm_id ',
'                and input_paths.conn_tgt_objt_id = objt.objt_id',
'                and input_paths.conn_tag_name = pi_conn_type',
'            ) as objt_input_paths',
'        , (select count(output_paths.conn_id) ',
'               from flow_connections output_paths ',
'              where output_paths.conn_dgrm_id      = objt.objt_dgrm_id ',
'                and output_paths.conn_src_objt_id  = objt.objt_id',
'                and output_paths.conn_tag_name = pi_conn_t'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'ype',
'            ) as objt_output_paths',
'      into po_objt_tag_name',
'         , po_num_back_connections',
'         , po_num_forward_connections',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = pi_objt_bpmn_id',
'       and objt.objt_dgrm_id = pi_dgrm_id;',
'  end get_number_of_connections;',
'',
'  function get_object_subtag',
'  ( p_objt_bpmn_id in flow_objects.objt_bpmn_id%type',
'  , p_dgrm_id      in flow_diagrams.dgrm_id%type  ',
'  )',
'  return varchar2',
'  is',
'    l_objt_sub_tag_name  flow_objects.objt_bpmn_id%type;',
'  begin',
'    select objt.objt_sub_tag_name',
'      into l_objt_sub_tag_name',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_objt_bpmn_id',
'       and objt.objt_dgrm_id = p_dgrm_id',
'       ;',
'    return l_objt_sub_tag_name;',
'  end get_object_subtag;',
'',
'  function get_object_tag',
'  ( p_objt_bpmn_id in flow_objects.objt_bpmn_id%type',
'  , p_dgrm_id      in flow_diagrams.dgrm_id%type  ',
'  ) return flow_objects.objt_tag_name%type',
'  is',
'    l_objt_tag_name  flow_objects.objt_bpmn_id%type;',
'  begin',
'    select objt.objt_tag_name',
'      into l_objt_tag_name',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_objt_bpmn_id',
'       and objt.objt_dgrm_id = p_dgrm_id',
'       ;',
'    return l_objt_tag_name;',
'  end get_object_tag;',
'',
'function get_object_tag',
'( p_sbfl_info   in flow_subflows%rowtype',
') return flow_objects.objt_tag_name%type',
'is',
'  l_objt_tag_name   flow_objects.objt_tag_name%type;',
'begin',
'  select objt.objt_tag_name',
'    into l_objt_tag_name',
'    from flow_objects objt',
'   where objt.objt_bpmn_id = p_sbfl_info.sbfl_current',
'     and objt.objt_dgrm_id = p_sbfl_info.sbfl_dgrm_id',
'  ;',
'  return l_objt_tag_name;',
'end get_object_tag;',
'  ',
'  function get_subflow_info',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , p_lock_subflow  in boolean default false',
'  , p_lock_process  in boolean default false',
'  ) return flow_subflows%rowtype',
'  is ',
'    l_sbfl_rec          flow_subflows%rowtype;',
'    l_prcs_check_id     flow_processes.prcs_id%type;',
'  begin',
'    begin ',
'      if p_lock_process then',
'        begin',
'          select prcs.prcs_id',
'            into l_prcs_check_id',
'            from flow_processes prcs',
'          where prcs.prcs_id = p_process_id',
'          for update wait 2',
'          ;',
'        exception',
'          when no_data_found then',
'            flow_errors.handle_instance_error',
'            ( pi_prcs_id     => p_process_id',
'            , pi_sbfl_id     => p_subflow_id',
'            , pi_message_key => ''engine-util-prcs-not-found''',
'            , p0 => p_process_id',
'            );',
'            -- $F4AMESSAGE ''engine-util-prcs-not-found'' || ''Application Error: Process ID %0 not found).''  ',
'        end;',
'      end if;',
'      if p_lock_subflow then ',
'        select *',
'        into l_sbfl_rec',
'        from flow_subflows sbfl',
'        where sbfl.sbfl_prcs_id = p_process_id',
'        and sbfl.sbfl_id = p_subflow_id',
'        for update wait 2',
'        ;',
'      else ',
'        select *',
'        into l_sbfl_rec',
'        from flow_subflows sbfl',
'        where sbfl.sbfl_prcs_id = p_process_id',
'        and sbfl.sbfl_id = p_subflow_id',
'        ;',
'      end if;',
'    exception',
'      when no_data_found then',
'        -- check if subflow valid in process',
'        select sbfl.sbfl_prcs_id',
'          into l_prcs_check_id',
'          from flow_subflows sbfl',
'         where sbfl.sbfl_id = p_subflow_id',
'         ;',
'        if l_prcs_check_id != p_process_id then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id     => p_process_id',
'          , pi_sbfl_id     => p_subflow_id',
'          , pi_message_key => ''engine-util-sbfl-not-in-prcs''',
'          , p0 => p_subflow_id',
'          , p1 => p_process_id',
'          );',
'          -- $F4AMESSAGE ''engine-util-sbfl-not-in-prcs'' || ''Application Error: Subflow ID supplied ( %0 ) exists but is not child of Process ID Supplied ( %1 ).''  ',
'        end if;',
'      when lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''timeout_locking_subflow''',
'        , p0 => p_subflow_id',
'        );',
'        -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Retry your transaction later.''  ',
'    end;',
'    return l_sbfl_rec;',
'  exception',
'    when no_data_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => p_subflow_id',
'      , pi_message_key => ''engine-util-sbfl-not-found''',
'      , p0 => p_subflow_id',
'      );',
'      return null;',
'      -- $F4AMESSAGE ''engine-util-sbfl-not-found'' || ''Subflow ID supplied ( %0 ) not found. Check for process events that changed process flow (timeouts, errors, escalations).''  ',
'  end get_subflow_info;',
'',
'  function get_iteration_type',
'  ( p_step_info         flow_types_pkg.flow_step_info',
'  ) return varchar2',
'  is',
'    l_iteration_type          varchar2(10);',
'    l_sequential              boolean;',
'    l_target_objt_attributes  sys.json_object_t;',
'    l_target_iter_attributes  sys.json_object_t;',
'    l_multi_attributes        sys.json_object_t;',
'  begin',
'    -- get loop characteristics',
'    l_target_objt_attributes := sys.json_object_t.parse(p_step_info.target_objt_attributes);',
'    apex_debug.message (p_message => ''...l_target_objt_atributes: %0'', p0 => l_target_objt_attributes.to_string);',
'    if l_target_objt_attributes.has(''apex'') then',
'      apex_debug.message (p_message => ''...has apex'');',
'      l_target_iter_attributes := l_target_objt_attributes.get_object(''apex'');',
'      if l_target_objt_attributes.get_object(''apex'').has(''standardLoopCharacteristics'') then',
'        apex_debug.message (p_message => ''...has standardLoop'');',
'        l_iteration_type := flow_constants_pkg.gc_iteration_loop;',
'      elsif l_target_objt_attributes.get_object(''apex'').has(''multiInstanceLoopCharacteristics'') then',
'        apex_debug.message (p_message => ''...has multiIstanceLoop'');',
'        l_multi_attributes := l_target_objt_attributes.get_object(''apex'').get_object(''multiInstanceLoopCharacteristics'');',
'        l_sequential := l_multi_attributes.get_boolean(''isSequential'');',
'        case l_sequential',
'        when true then',
'          l_iteration_type := flow_constants_pkg.gc_iteration_sequential;',
'        when false then',
'          l_iteration_type := flow_constants_pkg.gc_iteration_parallel;',
'        end case;',
'      end if;',
'    else ',
'      l_iteration_type := null;',
'    end if;',
'    apex_debug.message (p_message => ''...Iteration Type: %0'', p0 => l_iteration_type);',
'    return l_iteration_type;',
'  end get_iteration_type;',
'',
'  function get_loop_counter',
'  ( pi_sbfl_id       in  flow_subflows.sbfl_id%type',
'  ) return flow_subflows.sbfl_loop_counter%type',
'  is',
'    l_loop_counter   flow_subflows.sbfl_loop_counter%type;',
'  begin',
'    select it.iter_loop_counter',
'      into l_loop_counter',
'      from flow_iterations it',
'      join flow_subflows s',
'        on s.sbfl_iter_id = it.iter_id',
'     where s.sbfl_id = pi_sbfl_id;',
'    apex_debug.message (p_message=>''--> get_loop_counter - value = %0'', p0=> l_loop_counter);',
'    return l_loop_counter;',
'  exception',
'    when others then',
'      return null;',
'  end get_loop_counter;',
'',
'',
'  function subflow_start',
'    ( ',
'      p_process_id                in flow_processes.prcs_id%type',
'    , p_parent_subflow            in flow_subflows.sbfl_id%type',
'    , p_starting_object           in flow_objects.objt_bpmn_id%type',
'    , p_current_object            in flow_objects.objt_bpmn_id%type',
'    , p_route                     in flow_subflows.sbfl_route%type',
'    , p_last_completed            in flow_objects.objt_bpmn_id%type',
'    , p_status                    in flow_subflows.sbfl_status%type default flow_constants_pkg.gc_sbfl_status_running',
'    , p_parent_sbfl_proc_level    in flow_subflows.sbfl_process_level%type  --- can remove?',
'    , p_new_proc_level            in boolean default false',
'    , p_new_scope                 in boolean default false',
'    , p_new_diagram               in boolean default false',
'    , p_dgrm_id                   in flow_diagrams.dgrm_id%type',
'    , p_follows_ebg               in boolean default false',
'    , p_loop_counter              in number default null',
'    , p_iteration_type            in flow_subflows.sbfl_iteration_type%type default null',
'    , p_loop_total_instances      in flow_subflows.sbfl_loop_total_instances%type default null',
'    , p_iteration_var             in flow_process_variables.prov_var_name%type default null',
'    , p_iteration_var_scope       in flow_subflows.sbfl_scope%type default null',
'    , p_iter_id                   in flow_iterations.iter_id%type default null    ',
'    , p_iterated_object           in flow_iterated_objects.iobj_id%type default null    ',
'    , p_is_adhoc                  in boolean default false ',
'    , p_hide_in_task_list         in varchar2 default null  ',
'    , p_task_input_parameters     in clob default null          ',
'    ) return flow_types_pkg.t_subflow_context',
'  is ',
'    l_timestamp           flow_subflows.sbfl_became_current%type;',
'    l_process_level       flow_subflows.sbfl_process_level%type := p_parent_sbfl_proc_level;',
'    l_diagram_level       flow_subflows.sbfl_diagram_level%type := 0;',
'    l_new_subflow_context flow_types_pkg.t_subflow_context;',
'    l_lane                flow_objects.objt_bpmn_id%type;',
'    l_lane_name           flow_objects.objt_name%type;',
'    l_lane_isRole         flow_subflows.sbfl_lane_isRole%type;',
'    l_lane_role           flow_subflows.sbfl_lane_role%type;',
'    l_scope               flow_subflows.sbfl_scope%type := 0;',
'    l_level_parent        flow_subflows.sbfl_id%type := 0;',
'    l_is_new_level        varchar2(1 byte) := flow_constants_pkg.gc_false;',
'    l_is_new_scope        varchar2(1 byte) := flow_constants_pkg.gc_false;',
'    l_is_adhoc            varchar2(1 byte) := flow_constants_pkg.gc_false;',
'    l_follows_ebg         flow_subflows.sbfl_is_following_ebg%type;',
'    l_new_iter_id         flow_iterations.iter_id%type;',
'  begin',
'    apex_debug.enter ',
'    ( ''>>  subflow_start''',
'    , ''Process'', p_process_id',
'    , ''Parent Subflow'', p_parent_subflow ',
'    , ''Loop Counter'', p_loop_counter',
'    );',
'    ',
'    -- convert boolean in parameters to varchar2 for use in SQL',
'    if p_new_proc_level then ',
'      l_is_new_level := flow_constants_pkg.gc_true;',
'    end if;',
'    if p_follows_ebg then',
'      l_follows_ebg := flow_constants_pkg.gc_true;',
'    end if;',
'    if p_is_adhoc then',
'      l_is_adhoc := flow_constants_pkg.gc_true;',
'    end if;',
'',
'    if p_parent_subflow is  null then',
'    -- initial subflow in process.   Get starting Lane info. (could be null)',
'    -- database 23.3 bug 35862529 means this will return NDF if there are no lanes so we handle (ignore) the NDF',
'    -- database 23.8 bug 36838600 requires that you add the column aliases isRole and role on the 3rd and 4th line of ',
'    --                            select list (or get ORA-600 [qolTextIdn:1])',
'    -- database 23.10 (aka 26.0)  bug introduced while fixing 33561572 means we have to add an optimiser instruction using ',
'    --                            fix_control to disable that fix to avoid another ORA-600 [qolTextIdn:1] ',
'    --                            adds - ( /*+ OPT_PARAM(''_fix_control'' ''33561572:0'') */ )',
'',
'      begin ',
'        select /*+ OPT_PARAM(''_fix_control'' ''33561572:0'') */',
'               lane_objt.objt_bpmn_id',
'             , lane_objt.objt_name',
'             , lane_objt.objt_attributes."apex"."isRole" isRole',
'             , lane_objt.objt_attributes."apex"."role"   role',
'          into l_lane',
'             , l_lane_name',
'             , l_lane_isRole',
'             , l_lane_role',
'          from flow_objects start_objt',
'          left join flow_objects lane_objt',
'            on start_objt.objt_objt_lane_id = lane_objt.objt_id',
'           and start_objt.objt_dgrm_id      = lane_objt.objt_dgrm_id',
'         where start_objt.objt_dgrm_id = p_dgrm_id',
'           and start_objt.objt_bpmn_id = p_starting_object',
'        ;',
'      exception',
'        when no_data_found then',
'          null;',
'      end;',
'    else',
'    -- new subflow in existing process',
'    -- get process level, diagram level, scope, calling subflow for copy down unless this is the initial subflow in a process',
'      select coalesce ( ahsp.ahsp_process_level, sbfl.sbfl_process_level)',
'           , sbfl.sbfl_diagram_level',
'           , sbfl.sbfl_scope',
'           , sbfl.sbfl_lane',
'           , sbfl.sbfl_lane_name',
'           , sbfl.sbfl_lane_isRole',
'           , sbfl.sbfl_lane_role',
'           , case l_is_new_level',
'                when ''Y'' then p_parent_subflow  ',
'                when ''N'' then ',
'                    case l_is_adhoc',
'                      when ''Y'' then p_parent_sbfl_proc_level',
'                      else sbfl.sbfl_calling_sbfl',
'                    end',
'             end ',
'           , coalesce(p_iter_id, sbfl_iter_id)',
'        into l_process_level',
'           , l_diagram_level',
'           , l_scope',
'           , l_lane',
'           , l_lane_name',
'           , l_lane_isRole',
'           , l_lane_role',
'           , l_level_parent',
'           , l_new_iter_id',
'        from flow_subflows sbfl',
'        left join flow_adhoc_subprocs ahsp',
'          on sbfl.sbfl_id = ahsp.ahsp_sbfl_id',
'       where sbfl.sbfl_id = p_parent_subflow;',
'    end if;',
'',
'    -- create the new subflow',
'',
'    insert',
'      into flow_subflows',
'         ( sbfl_prcs_id',
'         , sbfl_sbfl_id',
'         , sbfl_process_level',
'         , sbfl_starting_object',
'         , sbfl_route',
'         , sbfl_last_completed',
'         , sbfl_became_current',
'         , sbfl_current',
'         , sbfl_status',
'         , sbfl_last_update',
'         , sbfl_last_update_by',
'         , sbfl_dgrm_id',
'         , sbfl_diagram_level',
'         , sbfl_step_key',
'         , sbfl_calling_sbfl',
'         , sbfl_scope',
'         , sbfl_lane',
'         , sbfl_lane_name',
'         , sbfl_lane_isRole',
'         , sbfl_lane_role',
'         , sbfl_is_following_ebg',
'         , sbfl_loop_counter',
'         , sbfl_iteration_type',
'         , sbfl_loop_total_instances',
'         , sbfl_iteration_var',
'         , sbfl_iteration_var_scope',
'         , sbfl_iter_id',
'         , sbfl_iobj_id',
'         , sbfl_is_adhoc',
'         , sbfl_hide_in_task_list',
'         , sbfl_task_input_parameters',
'         )',
'    values',
'         ( p_process_id',
'         , p_parent_subflow',
'         , l_process_level',
'         , p_starting_object',
'         , p_route',
'         , p_last_completed',
'         , systimestamp',
'         , p_current_object',
'         , p_status',
'         , systimestamp',
'         , coalesce ( sys_context(''apex$session'',''app_user'') ',
'                    , sys_context(''userenv'',''os_user'')',
'                    , sys_context(''userenv'',''session_user'')',
'                    )  ',
'         , p_dgrm_id',
'         , l_diagram_level',
'         , flow_engine_util.step_key',
'         , l_level_parent',
'         , l_scope',
'         , l_lane',
'         , l_lane_name',
'         , l_lane_isRole',
'         , l_lane_role',
'         , l_follows_ebg',
'         , p_loop_counter',
'         , p_iteration_type',
'         , p_loop_total_instances ',
'         , p_iteration_var',
'         , p_iteration_var_scope',
'         , l_new_iter_id  ',
'         , p_iterated_object         ',
'         , l_is_adhoc ',
'         , p_hide_in_task_list',
'         , case l_is_adhoc',
'             when ''Y'' then p_task_input_parameters',
'             else null',
'           end',
'         )',
'    returning sbfl_id, sbfl_step_key, sbfl_route, sbfl_scope into l_new_subflow_context',
'    ;                                 ',
'',
'    if p_new_proc_level then',
'      -- starting new subprocess.  Reset sbfl_process_level to new sbfl_id (change on new subProcesss, callActivity)',
'      l_process_level := l_new_subflow_context.sbfl_id;',
'',
'      if p_new_scope then',
'        -- starting new variable scope.  Reset sbfl_scope to new sbfl_id. (change on callActivity (maybe others later...iteration, etc.) )',
'        l_new_subflow_context.scope := l_new_subflow_context.sbfl_id;',
'      end if;',
'',
'      if p_new_diagram then',
'        -- starting a new diagram.   set the diagram_level to new sbfl_id (change on new callActivity)',
'        l_diagram_level := l_new_subflow_context.sbfl_id;',
'      end if;',
'',
'      update flow_subflows',
'         set sbfl_process_level   = l_process_level',
'           , sbfl_scope           = l_new_subflow_context.scope',
'           , sbfl_diagram_level   = l_diagram_level',
'       where sbfl_id = l_new_subflow_context.sbfl_id;',
'',
'    end if;',
'',
'    apex_debug.info',
'    ( p_message => ''... New Subflow started.  Process: %0 Subflow: %1 Step Key: %2 Scope: %3 Lane: %4 ( %5 ) LoopCounter: %6. Iter_id: %7 Hide: %8''',
'    , p0        => p_process_id',
'    , p1        => l_new_subflow_context.sbfl_id',
'    , p2        => l_new_subflow_context.step_key',
'    , p3        => l_new_subflow_context.scope',
'    , p4        => l_lane',
'    , p5        => l_lane_name',
'    , p6        => p_loop_counter',
'    , p7        => l_new_iter_id',
'    , p8        => p_hide_in_task_list',
'    );',
'    return l_new_subflow_context;',
'  end subflow_start;',
'',
'  procedure terminate_level',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_process_level in flow_subflows.sbfl_process_level%type',
'    )',
'  is',
'    l_apex_task_id  number;',
'  begin',
'    apex_debug.enter',
'    ( ''>> terminate_level''',
'    , ''Process'',  p_process_id',
'    , ''Process Level'', p_process_level',
'    );',
'    -- find any running subprocesses with parent at this level',
'    begin',
'      for child_proc_levels in (',
'        select distinct child_sbfl.sbfl_process_level',
'          from flow_subflows parent_sbfl',
'          join flow_subflows child_sbfl',
'            on parent_sbfl.sbfl_current = child_sbfl.sbfl_starting_object',
'           and parent_sbfl.sbfl_prcs_id = child_sbfl.sbfl_prcs_id',
'           and parent_sbfl.sbfl_id      = child_sbfl.sbfl_calling_sbfl',
'--         where parent_sbfl.sbfl_status =  flow_constants_pkg.gc_sbfl_status_in_subprocess',
'         where parent_sbfl.sbfl_status in ( flow_constants_pkg.gc_sbfl_status_in_subprocess',
'                                          , flow_constants_pkg.gc_sbfl_status_in_callactivity ',
'                                          , flow_constants_pkg.gc_sbfl_status_iterating)',
'           and parent_sbfl.sbfl_process_level = p_process_level',
'           and parent_sbfl.sbfl_prcs_id = p_process_id',
'      )',
'      loop',
'        terminate_level',
'        ( p_process_id     => p_process_id',
'        , p_process_level  => child_proc_levels.sbfl_process_level);',
'      end loop;',
'    end;',
'    -- end all subflows in this level',
'',
'      -- first check if any subflows have current tasks that running external tasks, e,g., APEX approvals',
'      begin',
'        for subflows_with_tasks in (',
'          select sbfl.sbfl_id',
'               , sbfl.sbfl_current',
'               , sbfl.sbfl_scope',
'               , sbfl.sbfl_dgrm_id',
'               , sbfl.sbfl_apex_task_id',
'               , sbfl.sbfl_apex_business_admin',
'               , objt.objt_tag_name',
'               , objt.objt_sub_tag_name',
'               , objt.objt_attributes."taskType" tasktype',
'            from flow_subflows sbfl',
'            join flow_objects objt',
'              on sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'             and sbfl.sbfl_current = objt.objt_bpmn_id',
'           where sbfl.sbfl_prcs_id = p_process_id',
'             and sbfl.sbfl_process_level = p_process_level',
'             and objt.objt_tag_name in ( flow_constants_pkg.gc_bpmn_usertask',
'                                       , flow_constants_pkg.gc_bpmn_receiveTask',
'                                       , flow_constants_pkg.gc_bpmn_intermediate_catch_event )',
'        )',
'        loop',
'          -- clear any approval tasks ',
'          case subflows_with_tasks.tasktype ',
'          when flow_constants_pkg.gc_apex_usertask_apex_approval then',
'            -- cancel apex workflow task',
'            flow_usertask_pkg.cancel_apex_task',
'            ( p_process_id          => p_process_id',
'            , p_subflow_id          => subflows_with_tasks.sbfl_id',
'            , p_objt_bpmn_id        => subflows_with_tasks.sbfl_current',
'            , p_apex_task_id        => subflows_with_tasks.sbfl_apex_task_id',
'            , p_apex_business_admin => subflows_with_tasks.sbfl_apex_business_admin',
'            );',
'          when flow_constants_pkg.gc_simple_message then',
'            flow_message_util.cancel_subscription ( p_process_id  => p_process_id ',
'                                                  , p_subflow_id  => subflows_with_tasks.sbfl_id',
'                                                  );',
'          else',
'            null;',
'          end case;',
'        end loop;',
'      end;',
'',
'     -- then delete the subflows',
'    delete from flow_subflows',
'    where sbfl_process_level = p_process_level ',
'      and sbfl_prcs_id = p_process_id',
'      ;',
'    apex_debug.info ',
'    ( p_message => ''... Process %0 : All subflows at process level %1 terminated''',
'    , p0 => p_process_id',
'    , p1 => p_process_level',
'    );',
'  end terminate_level;',
'',
'  procedure subflow_complete',
'    ( p_process_id        in flow_processes.prcs_id%type',
'    , p_subflow_id        in flow_subflows.sbfl_id%type',
'    )',
'  is',
'    l_remaining_subflows              number;',
'    l_remaining_siblings              number;',
'    l_current_object                  flow_subflows.sbfl_current%type;',
'    l_current_subflow_status          flow_subflows.sbfl_status%type;',
'    l_current_subflow_process_level   flow_subflows.sbfl_process_level%type;',
'    l_parent_subflow_id               flow_subflows.sbfl_sbfl_id%type;',
'    l_parent_subflow_status           flow_subflows.sbfl_status%type;',
'    l_parent_subflow_last_completed   flow_subflows.sbfl_last_completed%type;',
'    l_parent_subflow_current          flow_subflows.sbfl_current%type;',
'  begin',
'    apex_debug.enter',
'    ( ''>> subflow_complete''',
'    , ''Subflow'' , p_subflow_id ',
'    );',
'    select sbfl.sbfl_sbfl_id',
'         , sbfl.sbfl_current',
'         , sbfl.sbfl_status',
'         , sbfl.sbfl_process_level',
'      into l_parent_subflow_id',
'         , l_current_object',
'         , l_current_subflow_status',
'         , l_current_subflow_process_level',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_id = p_subflow_id',
'       and sbfl.sbfl_prcs_id = p_process_id',
'    ; ',
'    ',
'    if l_parent_subflow_id is not null then   ',
'      -- get parent subflow info',
'      select sbfl.sbfl_status',
'           , sbfl.sbfl_last_completed',
'           , sbfl.sbfl_current',
'        into l_parent_subflow_status',
'           , l_parent_subflow_last_completed',
'           , l_parent_subflow_current',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_id = l_parent_subflow_id',
'         and sbfl.sbfl_prcs_id = p_process_id',
'      ;',
'    end if;',
'    -- delete the subflow',
'    delete from flow_subflows',
'     where sbfl_id = p_subflow_id',
'       and sbfl_prcs_id = p_process_id',
'    ;',
'',
'    -- handle parallel flows with their own end events.  Last one completing needs to clear up the parent ''split'' sbfl.',
'    -- if subflow has parent with   ',
'    -- a)  status ''split''  (flow_constants_pkg.gc_sbfl_status_split)',
'    -- b)  no other children, AND',
'    -- c)  is not a merging gateway',
'    -- then we have an ophan parent process to clean up (all opening gateway paths have run to conclusion)',
'    -- need to call this recursively in case you have nested open parallel gateways',
'',
'    if l_parent_subflow_id is not null then   ',
'        ',
'      select count(*)',
'        into l_remaining_siblings',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_prcs_id = p_process_id',
'         and sbfl.sbfl_starting_object = l_parent_subflow_last_completed',
'         and sbfl.sbfl_process_level   = l_current_subflow_process_level',
'      ;',
'      ',
'      if (   l_remaining_siblings = 0',
'         and l_parent_subflow_status =  flow_constants_pkg.gc_sbfl_status_split    ',
'         and l_current_subflow_status not in ( flow_constants_pkg.gc_sbfl_status_waiting_gateway',
'                                             , flow_constants_pkg.gc_sbfl_status_waiting_iter )',
'         )',
'      then',
'        -- call subflow_complete again recursively in case it has orphan grandparent',
'        subflow_complete ( p_process_id => p_process_id',
'                         , p_subflow_id => l_parent_subflow_id',
'                         );',
'      end if;  ',
'    end if;',
'  end subflow_complete;',
'',
'  function lock_subflow',
'  ( p_subflow_id    in flow_subflows.sbfl_id%type',
'  ) return boolean',
'  is ',
'    l_sbfl_prcs_id   flow_subflows.sbfl_prcs_id%type;',
'  begin ',
'',
'    apex_debug.enter ',
'    ( ''>> lock_subflow''',
'    , ''Subflow'', p_subflow_id ',
'    );',
'',
'    select sbfl.sbfl_prcs_id',
'      into l_sbfl_prcs_id',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_id = p_subflow_id',
'    for update wait 2',
'    ;',
'    return true;',
'  exception',
'    when no_data_found then',
'      return false;',
'    when lock_timeout then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id => l_sbfl_prcs_id',
'      , pi_sbfl_id => p_subflow_id',
'      , pi_message_key => ''timeout_locking_subflow''',
'      , p0 => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''',
'      return false;',
'  end lock_subflow;',
'',
'  procedure lock_all_for_process ',
'  ( p_process_id  in    flow_processes.prcs_id%type',
'  ) ',
'  is',
'    cursor c_lock_all is ',
'        select prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated, prdg_id',
'          from flow_subflows sbfl',
'          join flow_processes prcs',
'            on prcs.prcs_id = sbfl.sbfl_prcs_id ',
'          join flow_subflow_log sflg ',
'            on prcs.prcs_id = sflg.sflg_prcs_id',
'          join flow_instance_diagrams prdg',
'            on prcs.prcs_id = prdg.prdg_prcs_id',
'          where prcs.prcs_id = p_process_id',
'          order by sbfl.sbfl_process_level, sbfl.sbfl_id',
'            for update of prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated, prdg.prdg_id wait 2',
'    ;',
'  begin',
'    apex_debug.enter',
'    ( ''>> lock all_for_process''',
'    , ''process_id'', p_process_id',
'    );',
'    -- lock all objects',
'    begin',
'      open c_lock_all;',
'      flow_timers_pkg.lock_process_timers ( pi_prcs_id => p_process_id );  ',
'      flow_message_util.lock_instance_subscriptions ( p_process_id => p_process_id );',
'      close c_lock_all;',
'    exception ',
'      when lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''process-lock-timeout''',
'        , p0 => p_process_id          ',
'        );',
'        -- $F4AMESSAGE ''process-lock-timeout'' || ''Process objects for %0 currently locked by another user.  Try again later.''',
'        raise;',
'    end;',
'  end lock_all_for_process;',
'',
'  function get_scope',
'  (  p_process_id  in flow_processes.prcs_id%type',
'  ,  p_subflow_id  in flow_subflows.sbfl_id%type',
'  ) return flow_subflows.sbfl_scope%type',
'  is',
'    l_scope   flow_subflows.sbfl_scope%type;',
'  begin',
'    select sbfl_scope',
'      into l_scope',
'      from flow_subflows',
'     where sbfl_id = p_subflow_id',
'       and sbfl_prcs_id = p_process_id',
'    ;',
'    return l_scope;',
'  exception',
'    when no_data_found then ',
'    flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => p_subflow_id',
'      , pi_message_key => ''engine-util-sbfl-not-found''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );',
'      -- $F4AMESSAGE ''engine-util-sbfl-not-found'' || ''Subflow ID supplied ( %0 ) not found. Check for process events that changed process flow (timeouts, errors, escalations).'' ',
'  end get_scope;',
'',
'  function json_array_join',
'  (',
'    p_json_array in sys.json_array_t',
'  ) return clob',
'  as',
'    l_return clob;',
'  begin',
'    apex_debug.info( p_message => ''-- Joining JSON Array to CLOB, size %0'', p0 => p_json_array.get_size );',
'    for i in 0..p_json_array.get_size - 1 loop',
'      l_return := l_return || p_json_array.get_clob( i ) || apex_application.lf;',
'    end loop;',
'    return l_return;',
'  end json_array_join;',
'',
'  function json_array_join',
'  (',
'    p_json_array in clob',
'  ) return clob',
'  as',
'    l_json sys.json_array_t;',
'  begin',
'    if p_json_array is not null then',
'      apex_debug.info( p_message => ''-- Got CLOB parsing to JSON_ARRAY_T'' );',
'      l_json := sys.json_array_t.parse( p_json_array );',
'      return json_array_join( p_json_array => l_json );',
'    else',
'      return null;',
'    end if;',
'  end json_array_join;',
'',
'  function apex_json_array_join',
'  ( p_json_array in apex_t_varchar2',
'  )',
'  return clob',
'  is ',
'    l_return clob;',
'  begin',
'    apex_debug.info( p_message => ''-- Joining APEX JSON Array to vc2, size %0'', p0 => p_json_array.count );',
'',
'    l_return := apex_string.join_clob( p_table => p_json_array );',
'',
'    apex_debug.info( p_message => ''-- returned string'', p0 => l_return);',
'    return l_return;',
'  end apex_json_array_join;',
'',
'  function clob_to_blob',
'  ( ',
'    pi_clob in clob',
'  ) return blob',
'  as',
'  $if flow_apex_env.ver_le_22_1 $then',
'    l_blob   blob;',
'    l_dstoff pls_integer := 1;',
'    l_srcoff pls_integer := 1;',
'    l_lngctx pls_integer := 0;',
'    l_warn   pls_integer;',
'  $end',
'  begin',
'',
'  $if flow_apex_env.ver_le_22_1 $then',
'    sys.dbms_lob.createtemporary',
'    ( lob_loc => l_blob',
'    , cache   => true',
'    , dur     => sys.dbms_lob.call',
'    );    ',
'',
'    sys.dbms_lob.converttoblob',
'    ( dest_lob     => l_blob',
'    , src_clob     => pi_clob',
'    , amount       => sys.dbms_lob.lobmaxsize',
'    , dest_offset  => l_dstoff',
'    , src_offset   => l_srcoff',
'    , blob_csid    => nls_charset_id( ''AL32UTF8'' )',
'    , lang_context => l_lngctx',
'    , warning      => l_warn',
'    );',
'',
'    return l_blob;',
'  $else',
'    return apex_util.clob_to_blob( p_clob => pi_clob )'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
';',
'  $end',
'',
'  end clob_to_blob;',
'',
'  -- initialise step key enforcement parameter',
'',
'  begin',
'    g_step_keys_enforced :=  (  flow_engine_util.get_config_value',
'                                ( p_config_key => flow_constants_pkg.gc_config_dup_step_prevention',
'                                , p_default_value => flow_constants_pkg.gc_config_default_dup_step_prevention ',
'                                )',
'                                = flow_constants_pkg.gc_config_dup_step_prevention_strict',
'                             );  ',
'end flow_engine_util;',
'/',
'',
'create or replace package body flow_engine as ',
'/* ',
'-- Flows for APEX - flow_engine.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2020-2022.',
'-- (c) Copyright Flowquest Limited. 2024-2025.',
'--',
'-- Created  11-Sep-2020  Richard Allen (Flowquest)',
'-- Modified 30-May-2022  Moritz Klein (MT AG)',
'-- Modified 09-Jan-2024  Richard Allen, Flowquest Ltd',
'--',
'*/',
'',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  procedure run_step',
'  ( p_sbfl_rec              in flow_subflows%rowtype',
'  , p_step_info             in flow_types_pkg.flow_step_info',
'  , p_iteration_is_complete in boolean default false',
'  );',
'',
'  e_feature_requires_ee exception;',
'',
'  function async_ee_is_available',
'    return boolean',
'  is',
'    l_package_count pls_integer;',
'  begin',
'    select count(*)',
'      into l_package_count',
'      from user_objects',
'     where object_name = ''FLOW_ASYNC_TASKS_EE''',
'       and object_type = ''PACKAGE BODY''',
'       and status = ''VALID'';',
'',
'    return l_package_count = 1;',
'  end async_ee_is_available;',
'',
'  function is_async_step',
'  ( p_step_info in flow_types_pkg.flow_step_info',
'  ) return boolean',
'  is',
'  begin',
'    return coalesce( p_step_info.target_objt_treat_as_tag, p_step_info.target_objt_tag )',
'             in ( flow_constants_pkg.gc_bpmn_scripttask',
'                , flow_constants_pkg.gc_bpmn_servicetask );',
'  end is_async_step;',
'',
'  function current_step_has_async_before',
'  ( p_objt_id in flow_objects.objt_id%type',
'  ) return boolean',
'  is',
'    l_async_before varchar2(10 char);',
'  begin',
'    select coalesce ( objt.objt_attributes."apex"."asyncBefore"',
'                    , flow_constants_pkg.gc_vcbool_false )',
'      into l_async_before',
'      from flow_objects objt',
'     where objt.objt_id = p_objt_id;',
'',
'    apex_debug.info',
'    ( p_message => ''Current step asyncBefore value: %0''',
'    , p0        => l_async_before',
'    );',
'    ',
'    return l_async_before = flow_constants_pkg.gc_vcbool_true;',
'  exception',
'    when no_data_found then',
'      return false;',
'  end current_step_has_async_before;',
'',
'  function previous_step_has_async_after',
'  ( p_dgrm_id              in flow_diagrams.dgrm_id%type',
'  , p_previous_objt_bpmn   in flow_objects.objt_bpmn_id%type',
'  ) return boolean',
'  is',
'    l_async_after varchar2(10 char);',
'  begin',
'    if p_previous_objt_bpmn is null then',
'      return false;',
'    end if;',
'',
'    select coalesce ( objt.objt_attributes."apex"."asyncAfter"',
'                    , flow_constants_pkg.gc_vcbool_false )',
'      into l_async_after',
'      from flow_objects objt',
'     where objt.objt_dgrm_id = p_dgrm_id',
'       and objt.objt_bpmn_id = p_previous_objt_bpmn;',
'',
'    apex_debug.info',
'    ( p_message => ''Previous step asyncAfter value: %0''    ',
'    , p0        => l_async_after',
'    );',
'',
'    return l_async_after = flow_constants_pkg.gc_vcbool_true;',
'  exception',
'    when no_data_found then',
'      return false;',
'  end previous_step_has_async_after;',
'',
'  function get_async_enqueue_reason',
'  ( p_sbfl_rec   in flow_subflows%rowtype',
'  , p_step_info  in flow_types_pkg.flow_step_info',
'  ) return varchar2',
'  is',
'  begin',
'    if current_step_has_async_before( p_objt_id => p_step_info.target_objt_id ) then',
'      return flow_constants_pkg.gc_async_before_key;',
'    end if;',
'',
'    if previous_step_has_async_after',
'       ( p_dgrm_id            => p_sbfl_rec.sbfl_dgrm_id',
'       , p_previous_objt_bpmn => p_sbfl_rec.sbfl_last_completed',
'       )',
'    then',
'      return flow_constants_pkg.gc_async_after_key;',
'    end if;',
'',
'    return null;',
'  end get_async_enqueue_reason;',
'',
'  procedure dispatch_step',
'  ( p_sbfl_rec              in flow_subflows%rowtype',
'  , p_step_info             in flow_types_pkg.flow_step_info',
'  , p_iteration_is_complete in boolean default false',
'  )',
'  is',
'    l_enqueue_reason varchar2(100 char);',
'  begin',
'    if not flow_globals.get_is_async_session',
'       and async_ee_is_available',
'       and is_async_step( p_step_info => p_step_info )',
'    then',
'      l_enqueue_reason := get_async_enqueue_reason',
'                          ( p_sbfl_rec  => p_sbfl_rec',
'                          , p_step_info => p_step_info',
'                          );',
'    end if;',
'',
'    if l_enqueue_reason is not null then',
'    ',
'      apex_debug.info',
'      ( p_message => ''Step %0 is marked for async execution. Reason: %1''',
'      , p0        => p_sbfl_rec.sbfl_id',
'      , p1        => l_enqueue_reason',
'      );',
'',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_queued_async',
'           , sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )',
'       where sbfl.sbfl_prcs_id = p_sbfl_rec.sbfl_prcs_id',
'         and sbfl.sbfl_id      = p_sbfl_rec.sbfl_id;',
'',
'      flow_async_tasks_ee.enqueue_async_step',
'      ( p_process_id     => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id     => p_sbfl_rec.sbfl_id',
'      , p_step_key       => p_sbfl_rec.sbfl_step_key',
'      , p_enqueue_reason => l_enqueue_reason',
'      );',
'',
'      apex_debug.info',
'      ( p_message => ''Subflow %0 queued for async execution. Reason %1.''',
'      , p0        => p_sbfl_rec.sbfl_id',
'      , p1        => l_enqueue_reason',
'      );',
'    else',
'      run_step',
'      ( p_sbfl_rec              => p_sbfl_rec',
'      , p_step_info             => p_step_info',
'      , p_iteration_is_complete => p_iteration_is_complete',
'      );',
'    end if;',
'  end dispatch_step;',
'',
'  function flow_get_matching_link_object',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , pi_dgrm_id      in flow_diagrams.dgrm_id%type ',
'  , pi_link_bpmn_id in flow_objects.objt_name%type',
'  ) return varchar2',
'  is ',
'      l_matching_catch_event  flow_objects.objt_bpmn_id%type;',
'  begin ',
'      select catch_objt.objt_bpmn_id',
'        into l_matching_catch_event',
'        from flow_objects catch_objt',
'        join flow_objects throw_objt',
'          on catch_objt.objt_name = throw_objt.objt_name',
'          and catch_objt.objt_dgrm_id = throw_objt.objt_dgrm_id',
'          and catch_objt.objt_objt_id = throw_objt.objt_objt_id',
'        where throw_objt.objt_dgrm_id = pi_dgrm_id',
'          and throw_objt.objt_bpmn_id = pi_link_bpmn_id',
'          and catch_objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_link_event_definition',
'          and throw_objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_link_event_definition',
'          and catch_objt.objt_tag_name = flow_constants_pkg.gc_bpmn_intermediate_catch_event        ',
'          and throw_objt.objt_tag_name = flow_constants_pkg.gc_bpmn_intermediate_throw_event   ',
'          ;',
'      return l_matching_catch_event;',
'  exception',
'    when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''link-no-catch''',
'        , p0 => pi_link_bpmn_id',
'        );',
'        return null;',
'        -- $F4AMESSAGE ''link-no-catch'' || ''Unable to find matching link catch event named %0.''  ',
'    when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''link-too-many-catches''',
'        , p0 => pi_link_bpmn_id',
'        );',
'        return null;',
'        -- $F4AMESSAGE ''link-too-many-catches'' || ''More than one matching link catch event named %0.''  ',
'  end flow_get_matching_link_object;',
'',
'procedure flow_process_link_event',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'is ',
'    l_next_objt      flow_objects.objt_bpmn_id%type;',
'begin ',
'    apex_debug.enter ',
'    ( ''flow_process_link_event''',
'    , ''Process'', p_process_id',
'    , ''Subflow'', p_subflow_id',
'    );',
'    -- find matching link catching event and step to it',
'    l_next_objt := flow_get_matching_link_object ',
'      ( p_process_id    => p_process_id',
'      , p_subflow_id    => p_subflow_id',
'      , pi_dgrm_id      => p_step_info.dgrm_id',
'      , pi_link_bpmn_id => p_step_info.target_objt_ref',
'      );',
'  ',
'    -- proceed if link found cleanly',
'    if not flow_globals.get_step_error then',
'      -- update current step info before logging',
'      update flow_subflows sbfl',
'          set sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'            , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'            , sbfl.sbfl_last_update    = systimestamp',
'            , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'        where sbfl.sbfl_id = p_subflow_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'      ;',
'      -- log throw event as complete',
'      flow_logging.log_step_completion   ',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_completed_object => p_step_info.target_objt_ref',
'      );',
'      -- jump into matching catch event',
'      update flow_subflows sbfl',
'      set   sbfl.sbfl_current        = l_next_objt',
'          , sbfl.sbfl_last_completed = p_step_info.target_objt_ref',
'          , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'          , sbfl.sbfl_became_current = systimestamp ',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id = p_subflow_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'      ;',
'      -- pass the step_key through unchanged and use on the receiving ICE',
'      flow_complete_step',
'      ( p_process_id      => p_process_id',
'      , p_subflow_id      => p_subflow_id',
'      , p_step_key        => p_sbfl_info.sbfl_step_key',
'      , p_matching_object => p_step_info.target_objt_ref',
'      );',
'    else',
'      apex_debug.error(p_message  => ''error finding matching link object found'');    ',
'    end if;',
'end flow_process_link_event;',
'',
'--============================================================================================',
'--  B P M N   O B J E C T   P R O C E S S O R S ',
'--============================================================================================',
'',
'',
'  procedure process_endEvent',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type',
'    , p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is',
'    l_sbfl_context_par      flow_types_pkg.t_subflow_context;  ',
'    -- l_boundary_event        flow_objects.objt_bpmn_id%type;',
'    -- l_subproc_objt          flow_objects.objt_bpmn_id%type;',
'    l_exit_type             flow_objects.objt_sub_tag_name%type default null;',
'    l_remaining_subflows    number;',
'    l_process_end_status    flow_processes.prcs_status%type;',
'    -- l_parent_step_key       flow_subflows.sbfl_step_key%type;',
'    l_calling_subflow       flow_subflows.sbfl_id%type;   -- expected temporary variable',
'  begin',
'    apex_debug.enter ',
'    ( ''process_endEvent''',
'    , ''Process'', p_process_id',
'    , ''Subflow'', p_subflow_id',
'    );',
'    --next step can be either end of process, end of a call activity, or a sub-process returning to its parent',
'    -- get parent subflow',
'    l_sbfl_context_par := flow_engine_util.get_subprocess_parent_subflow',
'      ( p_sbfl_info  => p_sbfl_info',
'      , p_current    => p_sbfl_info.sbfl_current',
'      );',
'    -- process any variable expressions in the onEvent set',
'    flow_expressions.process_expressions',
'    ( pi_objt_id     => p_step_info.target_objt_id',
'    , pi_set         => flow_constants_pkg.gc_expr_set_on_event',
'    , pi_prcs_id     => p_process_id',
'    , pi_sbfl_id     => p_subflow_id',
'    , pi_step_key    => p_sbfl_info.sbfl_step_key',
'    , pi_var_scope   => p_sbfl_info.sbfl_scope',
'    , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'    );',
'    -- check for message throw end Event',
'    if p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_message_event_definition then',
'      $IF flow_apex_env.ee $THEN',
'        flow_message_util_ee.end_event_send_message',
'        ( p_sbfl_info  => p_sbfl_info',
'        , p_step_info  => p_step_info',
'        ); ',
'      $ELSE',
'        raise e_feature_requires_ee;',
'      $END ',
'    end if;',
'',
'    -- update the subflow before logging',
'     update flow_subflows sbfl',
'        set sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'          , sbfl.sbfl_current        = p_step_info.target_objt_ref',
'          , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_completed  ',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id = p_subflow_id',
'        and sbfl.sbfl_prcs_id = p_process_id',
'    ;',
'    -- log the current endEvent as completed',
'    flow_logging.log_step_completion',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_completed_object => p_step_info.target_objt_ref',
'      );  ',
'',
'    if p_sbfl_info.sbfl_calling_sbfl = 0 then   ',
'      -- in a top level process on the starting diagram',
'      apex_debug.info ',
'      ( p_message => ''Next Step is Process End %0''',
'      , p0        => p_step_info.target_objt_ref ',
'      );',
'      -- check for Terminate sub-Event',
'      if p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_terminate_event_definition then',
'        -- get desired process status after termination from model',
'        select coalesce( objt.objt_attributes."processStatus", flow_constants_pkg.gc_prcs_status_completed )',
'          into l_process_end_status',
'          from flow_objects objt',
'         where objt.objt_id = p_step_info.target_objt_id',
'        ;',
'        -- terminate the main level',
'        flow_engine_util.terminate_level',
'        ( ',
'          p_process_id     => p_process_id',
'        , p_process_level  => p_sbfl_info.sbfl_process_level',
'        );',
'      else ',
'        -- top process level but not a terminate end...',
'        flow_engine_util.subflow_complete',
'        ( p_process_id => p_process_id',
'        , p_subflow_id => p_subflow_id',
'        );',
'        l_process_end_status := flow_constants_pkg.gc_prcs_status_completed;',
'      end if;',
'',
'      -- check if there are ANY remaining subflows.  If not, close process',
'      select count(*)',
'        into l_remaining_subflows',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_prcs_id = p_process_id;',
'      ',
'      if l_remaining_subflows = 0 then ',
'',
'        update flow_processes prcs ',
'           set prcs.prcs_status         = l_process_end_status',
'             , prcs.prcs_last_update    = systimestamp',
'             , prcs.prcs_complete_ts    = systimestamp',
'             , prcs.prcs_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                    , sys_context(''userenv'',''os_user'')',
'                                                    , sys_context(''userenv'',''session_user'')',
'                                                    )  ',
'         where prcs.prcs_id = p_process_id',
'        ;',
'        -- log the completion',
'        flow_logging.log_instance_event',
'        ( p_process_id => p_process_id',
'        , p_event      => l_process_end_status',
'        , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'        );',
'        apex_debug.info ',
'        ( p_message => ''Process Completed with %1 Status: Process %0  ''',
'        , p0        => p_process_id',
'        , p1        => l_process_end_status',
'        );',
'',
'      end if;',
'    else  ',
'      -- in a lower process level (subProcess or CallActivity on another diagram) - process the Process Level endEvent (ouch)',
'      flow_subprocesses.process_process_level_endEvent',
'        ( p_process_id        => p_process_id',
'        , p_subflow_id        => p_subflow_id',
'        , p_sbfl_info         => p_sbfl_info',
'        , p_step_info         => p_step_info',
'        , p_sbfl_context_par  => l_sbfl_context_par',
'        );',
'    end if; ',
'  end process_endEvent;',
'',
'  procedure process_intermediateCatchEvent',
'  ( p_sbfl_info  in flow_subflows%rowtype',
'  , p_step_info  in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_new_status        flow_subflows.sbfl_status%type;',
'    l_msg_sub           flow_message_flow.t_subscription_details;',
'    l_msub_id           flow_message_subscriptions.msub_id%type;',
'  begin',
'    -- then we make everything behave like a simple activity unless specifically supported',
'    -- currently only supports timer and without checking its type is timer',
'    -- but this will have a case type = timer, emailReceive. ....',
'    -- this is currently just a stub.',
'    apex_debug.enter',
'    ( ''process_IntermediateCatchEvent''',
'    , ''p_step_info.target_objt_ref'', p_step_info.target_objt_ref',
'    );',
'',
'    case p_step_info.target_objt_subtag ',
'    when flow_constants_pkg.gc_bpmn_timer_event_definition then',
'      -- we have a timer.  Set status to waiting and schedule the timer.',
'      l_new_status  := flow_constants_pkg.gc_sbfl_status_waiting_timer;',
'',
'      flow_timers_pkg.start_timer',
'      ( ',
'        pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'      , pi_step_key     => p_sbfl_info.sbfl_step_key',
'      , pi_callback     => flow_constants_pkg.gc_bpmn_intermediate_catch_event',
'      );',
'    when flow_constants_pkg.gc_bpmn_message_event_definition then    ',
'      -- message catch event',
'      l_new_status  := flow_constants_pkg.gc_sbfl_status_waiting_message;',
'',
'      l_msg_sub            := flow_message_util.get_msg_subscription_details',
'                              ( p_msg_object_bpmn_id      => p_step_info.target_objt_ref',
'                              , p_dgrm_id                 => p_sbfl_info.sbfl_dgrm_id',
'                              , p_sbfl_info               => p_sbfl_info',
'                              );',
'      l_msg_sub.callback  := flow_constants_pkg.gc_bpmn_intermediate_catch_event;',
'',
'      -- create subscription for the awaited message ',
'      l_msub_id := flow_message_flow.subscribe ( p_subscription_details => l_msg_sub);',
'    else',
'      -- not a timer.  Just set it to running for now.  (other types to be implemented later)',
'      -- this includes bpmn:linkEventDefinition which should come here',
'      l_new_status  := flow_constants_pkg.gc_sbfl_status_running;',
'    end case;',
'',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_current        = p_step_info.target_objt_ref',
'         , sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'         , sbfl.sbfl_status         = l_new_status',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )  ',
'     where sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'       and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'    ;',
'  end process_intermediateCatchEvent;',
'',
'  procedure process_intermediateThrowEvent',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_par_sbfl            flow_types_pkg.t_subflow_context;',
'    l_injected_step_key   flow_subflows.sbfl_step_key%type;',
'    l_is_interrupting     boolean;',
'  begin',
'    -- currently  supports none, link, message and escalation Intermediate throw event ',
'    -- but this might later have other case type',
'    apex_debug.enter ',
'    ( ''process_IntermediateThrowEvent''',
'    , ''p_step_info.target_objt_ref'', p_step_info.target_objt_ref',
'    );',
'    -- process on-event expressions for the ITE',
'    flow_expressions.process_expressions',
'    ( pi_objt_id      => p_step_info.target_objt_id  ',
'    , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'    , pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'    , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'    , pi_step_key     => p_sbfl_info.sbfl_step_key',
'    , pi_var_scope    => p_sbfl_info.sbfl_scope',
'    , pi_expr_scope   => p_sbfl_info.sbfl_scope',
'    );',
'',
'    if p_step_info.target_objt_subtag is null then',
'      -- a none event.  Make the ITE the current event then just call flow_complete_step.  ',
'      update flow_subflows sbfl',
'      set   sbfl.sbfl_current        = p_step_info.target_objt_ref',
'          , sbfl.sbfl_last_completed = p_sbfl_info.sbfl_last_completed',
'          , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id      = p_sbfl_info.sbfl_id',
'        and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'      ;',
'      flow_complete_step',
'      ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_info.sbfl_id',
'      , p_step_key   => p_sbfl_info.sbfl_step_key',
'      );',
'    elsif p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_link_event_definition then',
'      flow_process_link_event',
'      ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_info.sbfl_id',
'      , p_sbfl_info  => p_sbfl_info',
'      , p_step_info  => p_step_info',
'      );   ',
'    elsif p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_message_event_definition then',
'      flow_message_flow.send_message',
'      ( p_sbfl_info  => p_sbfl_info',
'      , p_step_info  => p_step_info',
'      );',
'      flow_complete_step',
'      ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_info.sbfl_id',
'      , p_step_key   => p_sbfl_info.sbfl_step_key',
'      );',
'    elsif p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_escalation_event_definition then',
'      -- make the ITE the current step',
'      update  flow_subflows sbfl',
'          set sbfl.sbfl_current = p_step_info.target_objt_ref',
'            , sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'            , sbfl.sbfl_last_update = systimestamp',
'            , sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_running',
'        where sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'          and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'      ;',
'      -- find the subProcess event in the parent level',
'      l_par_sbfl := flow_engine_util.get_subprocess_parent_subflow',
'      ( p_sbfl_info  => p_sbfl_info',
'      , p_current    => p_step_info.target_objt_ref',
'      );',
'      -- escalate it to the boundary Event',
'      flow_boundary_events.process_escalation',
'      ( pi_sbfl_info        => p_sbfl_info',
'      , pi_step_info        => p_step_info',
'      , pi_par_sbfl         => l_par_sbfl.sbfl_id',
'      , pi_source_type      => flow_constants_pkg.gc_bpmn_intermediate_throw_event',
'      , po_step_key         => l_injected_step_key',
'      , po_is_interrupting  => l_is_interrupting',
'      ); ',
'',
'    else ',
'      --- other type of intermediateThrowEvent that is not currently supported',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_info.sbfl_id',
'      , pi_message_key => ''ITE-unsupported-type''',
'      , p0 => p_sbfl_info.sbfl_current',
'      );',
'      -- $F4AMESSAGE ''ITE-unsupported-type'' || ''Currently unsupported type of Intermediate Throw Event encountered at %0 .''  ',
'    end if;',
'end process_intermediateThrowEvent;',
'',
'',
'/* ',
'================================================================================',
'   E V E N T   H A N D L I N G ',
'================================================================================',
'*/',
'',
'procedure handle_event_gateway_event',
'  ( p_process_id         in flow_processes.prcs_id%type',
'  , p_parent_subflow_id  in flow_subflows.sbfl_id%type',
'  , p_cleared_subflow_id in flow_subflows.sbfl_id%type',
'  )',
'is ',
'    l_forward_route         flow_connections.conn_id%type;',
'    l_current_object        flow_subflows.sbfl_current%type;',
'    l_child_starting_object flow_subflows.sbfl_starting_object%type;',
'    l_parent_sbfl           flow_subflows.sbfl_id%type;',
'    l_timestamp             flow_subflows.sbfl_became_current%type;',
'    l_forward_step_key      flow_subflows.sbfl_step_key%type;',
'    l_return                varchar2(50);',
'begin',
'    -- called from any event that has cleared (so expired timer, received message or signal, etc) to move eBG forwards',
'    -- procedure has to:',
'    -- - check that gateway has not already been cleared by another event',
'    -- - resume the incoming subflow on the path of the first event to occur and call next_step',
'    -- - stop / terminate all of the child subflows that were created to wait for other events',
'    -- - including making sure any timers, message receivers, etc., are cleared up.',
'',
'    apex_debug.enter',
'    ( ''handle_event_gateway_event'' ',
'    , ''p_process_id'', p_process_id',
'    , ''parent_subflow'', p_parent_subflow_id',
'    , ''p_cleared_subflow_id'', p_cleared_subflow_id',
'    );',
'    begin',
'      select sbfl.sbfl_id',
'        into l_parent_sbfl',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_id = p_parent_subflow_id',
'         and sbfl.sbfl_prcs_id = p_process_id',
'         and sbfl.sbfl_status =  flow_constants_pkg.gc_sbfl_status_split  ',
'          ;',
'    exception',
'       when no_data_found then',
'        -- gateway aready cleared',
'         raise; ',
'    end;',
'    -- make the incoming (main) (split) parent subflow proceed along the path of the cleared event.clear(',
'    ',
'     select conn.conn_id',
'          , sbfl.sbfl_current',
'          , sbfl.sbfl_starting_object',
'       into l_forward_route',
'          , l_current_object',
'          , l_child_starting_object',
'       from flow_objects objt',
'       join flow_subflows sbfl ',
'         on sbfl.sbfl_current = objt.objt_bpmn_id',
'        and sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'       join flow_connections conn ',
'         on conn.conn_src_objt_id = objt.objt_id',
'        and conn.conn_dgrm_id = sbfl.sbfl_dgrm_id',
'      where sbfl.sbfl_id = p_cleared_subflow_id',
'        and sbfl.sbfl_prcs_id = p_process_id',
'        and conn.conn_tag_name = flow_constants_pkg.gc_bpmn_sequence_flow',
'          ; ',
'    -- generate a step key and insert in the update...use later',
'',
'    l_forward_step_key := flow_engine_util.step_key ( pi_sbfl_id   => p_parent_subflow_id',
'                                                    , pi_current => l_current_object',
'                                                    );',
'    l_timestamp := systimestamp;',
'',
'     update flow_subflows sbfl',
'        set sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'          , sbfl_current        = l_current_object',
'          , sbfl_last_completed = l_child_starting_object',
'          , sbfl_became_current = l_timestamp',
'          , sbfl_step_key       = l_forward_step_key',
'          , sbfl_last_update    = l_timestamp ',
'          , sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                           , sys_context(''userenv'',''os_user'')',
'                                           , sys_context(''userenv'',''session_user'')',
'                                           )  ',
'      where sbfl.sbfl_prcs_id = p_process_id',
'        and sbfl.sbfl_id = p_parent_subflow_id',
'        and sbfl.sbfl_status =  flow_constants_pkg.gc_sbfl_status_split  ',
'          ;',
'    -- now clear up all of the sibling subflows',
'    begin',
'      for child_subflows in (',
'        select sbfl.sbfl_id',
'             , sbfl.sbfl_current',
'             , objt.objt_sub_tag_name',
'          from flow_subflows sbfl',
'          join flow_objects objt ',
'            on objt.objt_bpmn_id = sbfl.sbfl_current',
'           and objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'         where sbfl.sbfl_sbfl_id = p_parent_subflow_id',
'           and sbfl.sbfl_starting_object = l_child_starting_object',
'           and sbfl.sbfl_prcs_id = p_process_id',
'      )',
'      loop',
'        -- clean up any event handlers (timers, etc.) (add more here when supporting messageEvent, SignalEvent, etc.)',
'        if child_subflows.objt_sub_tag_name = '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'flow_constants_pkg.gc_bpmn_timer_event_definition then',
'          flow_timers_pkg.terminate_timer',
'            ( pi_prcs_id => p_process_id',
'            , pi_sbfl_id => child_subflows.sbfl_id',
'            , po_return_code => l_return',
'            );',
'        end if;',
'        -- delete the completed subflow and log it as complete',
'            ',
'        delete',
'          from flow_subflows sbfl',
'         where sbfl.sbfl_prcs_id = p_process_id',
'           and sbfl.sbfl_id = child_subflows.sbfl_id',
'            ;',
'        -- logging - tbd',
'      end loop;',
'    end;  -- cleanup block',
'    -- now step forward on the forward path',
'    flow_complete_step           ',
'    ( p_process_id => p_process_id',
'    , p_subflow_id => p_parent_subflow_id',
'    , p_step_key   => l_forward_step_key',
'    , p_forward_route => null',
'    );',
'end handle_event_gateway_event;',
'',
'procedure handle_intermediate_catch_event',
'  ( p_process_id   in flow_processes.prcs_id%type',
'  , p_subflow_id   in flow_subflows.sbfl_id%type',
'  , p_step_key     in flow_subflows.sbfl_step_key%type',
'  , p_current_objt in flow_subflows.sbfl_current%type',
'  ) ',
'is',
'  l_sbfl_scope    flow_subflows.sbfl_scope%type;',
'begin',
'  apex_debug.enter',
'  ( ''handle_intermediate_catch_event''',
'  , ''Subflow'', p_subflow_id',
'  , ''Step Key'', p_step_key',
'  );',
'  update flow_subflows sbfl ',
'     set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'       , sbfl.sbfl_last_update    = systimestamp',
'       , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                             , sys_context(''userenv'',''os_user'')',
'                                             , sys_context(''userenv'',''session_user'')',
'                                             )  ',
'   where sbfl.sbfl_prcs_id = p_process_id',
'     and sbfl.sbfl_id = p_subflow_id',
'  returning sbfl_scope into l_sbfl_scope',
'  ;',
'  --  process any variable expressions in the OnEvent set',
'  flow_expressions.process_expressions',
'  ( pi_objt_bpmn_id => p_current_objt  ',
'  , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'  , pi_prcs_id      => p_process_id',
'  , pi_sbfl_id      => p_subflow_id',
'  , pi_step_key     => p_step_key',
'  , pi_var_scope    => l_sbfl_scope',
'  , pi_expr_scope   => l_sbfl_scope',
'  );',
'  -- test for any errors so far ',
'  if flow_globals.get_step_error then ',
'    -- has step errors from expressions',
'    flow_errors.set_error_status',
'    ( pi_prcs_id => p_process_id',
'    , pi_sbfl_id => p_subflow_id',
'    );',
'  else',
'    -- move onto next step',
'    flow_complete_step ',
'    ( p_process_id => p_process_id',
'    , p_subflow_id => p_subflow_id',
'    , p_step_key   => p_step_key',
'    , p_forward_route => null',
'    );',
'  end if;  ',
'end handle_intermediate_catch_event;',
'',
'procedure create_repeat_subflow ',
'  ( p_process_id      in flow_processes.prcs_id%type',
'  , p_last_subflow_id in flow_subflows.sbfl_id%type',
'  , p_timr_id         in flow_timers.timr_id%type default null',
'  , p_next_run        in flow_timers.timr_run%type default null',
'  )',
'is',
'  l_new_subflow_context  flow_types_pkg.t_subflow_context;',
'  l_last_subflow         flow_subflows%rowtype;',
'begin',
'  select * ',
'    into l_last_subflow',
'    from flow_subflows',
'   where sbfl_id = p_last_subflow_id',
'     and sbfl_prcs_id = p_process_id',
'  ;',
'',
'  l_new_subflow_context := flow_engine_util.subflow_start',
'          (',
'            p_process_id      => p_process_id',
'          , p_parent_subflow  => l_last_subflow.sbfl_sbfl_id',
'          , p_starting_object => l_last_subflow.sbfl_starting_object',
'          , p_current_object  => l_last_subflow.sbfl_starting_object',
'          , p_route           => ''from boundary event - run ''||to_char(p_next_run)',
'          , p_last_completed  => l_last_subflow.sbfl_last_completed',
'          , p_status          => flow_constants_pkg.gc_sbfl_status_waiting_timer',
'          , p_parent_sbfl_proc_level => l_last_subflow.sbfl_process_level',
'          , p_dgrm_id                => l_last_subflow.sbfl_dgrm_id',
'          );',
'',
'  flow_timers_pkg.start_timer',
'  ( pi_prcs_id      => p_process_id',
'  , pi_sbfl_id      => l_new_subflow_context.sbfl_id',
'  , pi_step_key     => l_new_subflow_context.step_key',
'  , pi_callback     => flow_constants_pkg.gc_bpmn_intermediate_catch_event',
'  , pi_callback_par => ''non-interrupting'' ',
'  , pi_timr_id      => p_timr_id',
'  , pi_run          => p_next_run',
'  );',
'',
'  if not flow_globals.get_step_error then ',
'      -- set timer flag on child (Self, Noninterrupting, Timer)',
'      update flow_subflows sbfl',
'          set sbfl.sbfl_has_events     = sbfl.sbfl_has_events||'':SNT''',
'            , sbfl.sbfl_last_update    = systimestamp',
'            , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'        where sbfl.sbfl_id = l_new_subflow_context.sbfl_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'      ;',
'  end if;',
'    ',
'end create_repeat_subflow;',
'',
'procedure timer_callback',
'  ( p_process_id in flow_processes.prcs_id%type',
'  , p_subflow_id in flow_subflows.sbfl_id%type',
'  , p_step_key   in flow_subflows.sbfl_step_key%type',
'  , p_timr_id    in flow_timers.timr_id%type default null',
'  , p_run        in flow_timers.timr_run%type default null',
'  , p_callback      in flow_timers.timr_callback%type default null',
'  , p_callback_par  in flow_timers.timr_callback_par%type default null',
'  , p_event_type    in flow_objects.objt_sub_tag_name%type',
'  ) ',
'is',
'  l_parent_subflow          flow_subflows.sbfl_id%type;',
'  l_prev_objt_tag_name      flow_objects.objt_tag_name%type;',
'  l_curr_objt_tag_name      flow_objects.objt_tag_name%type;',
'  l_curr_objt_sub_tag_name  flow_objects.objt_sub_tag_name%type;',
'  l_sbfl_current            flow_subflows.sbfl_current%type;',
'  l_follows_ebg             flow_subflows.sbfl_is_following_ebg%type;',
'begin',
'  -- currently handles callbacks from flow_timers and flow_message_flow when a timer fires / message is received',
'  apex_debug.enter ',
'  ( ''flow_handle_event''',
'  , ''subflow_id'',     p_subflow_id',
'  , ''process_id'',     p_process_id',
'  , ''event_type'',     p_event_type',
'  , ''p_callback'',     p_callback',
'  , ''p_callback_par'', p_callback_par',
'  );',
'  -- look at current event to check if it is a startEvent.  (this also has no previous event!)',
'  -- if not, examine previous event on the subflow to determine if it was eventBasedGateway (eBG)',
'  -- an intermediateCatchEvent (iCE) following an eBG will always have exactly 1 input (from the eBG)',
'  -- an independant iCE (not following an eBG) can have >1 inputs',
'  -- so look for preceding eBG.  If previous event not eBG or there are multiple prev events, it did not follow an eBG.',
'',
'  -- set context for scripts and variable expressions',
'  flow_globals.set_context',
'  ( pi_prcs_id  => p_process_id',
'  , pi_sbfl_id  => p_subflow_id',
'  , pi_step_key => p_step_key',
'  , pi_scope    => flow_engine_util.get_scope (p_process_id => p_process_id, p_subflow_id => p_subflow_id)',
'  );',
'  flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'  -- initialise step_had_error flag',
'  flow_globals.set_step_error ( p_has_error => false);',
'',
'',
'  -- lock subflow containing event',
'  if flow_engine_util.lock_subflow(p_subflow_id) then',
'    -- subflow_locked',
'    select curr_objt.objt_tag_name',
'         , curr_objt.objt_sub_tag_name',
'         , sbfl.sbfl_sbfl_id',
'         , sbfl.sbfl_current',
'         , sbfl.sbfl_is_following_ebg',
'      into l_curr_objt_tag_name',
'         , l_curr_objt_sub_tag_name',
'         , l_parent_subflow',
'         , l_sbfl_current',
'         , l_follows_ebg',
'      from flow_objects curr_objt ',
'      join flow_subflows sbfl ',
'        on sbfl.sbfl_current = curr_objt.objt_bpmn_id',
'       and sbfl.sbfl_dgrm_id = curr_objt.objt_dgrm_id',
'     where sbfl.sbfl_id = p_subflow_id',
'       and sbfl.sbfl_prcs_id = p_process_id',
'        ;',
'',
'    if l_curr_objt_tag_name = flow_constants_pkg.gc_bpmn_start_event then',
'      -- startEvent with associated event.',
'      handle_intermediate_catch_event -- startEvent behaves same as ICE',
'      (',
'        p_process_id   => p_process_id',
'      , p_subflow_id   => p_subflow_id',
'      , p_step_key     => p_step_key',
'      , p_current_objt => l_sbfl_current',
'      );',
'    elsif l_curr_objt_tag_name = flow_constants_pkg.gc_bpmn_boundary_event then',
'      -- if a repeating cycle timer, start next cycle before handling',
'      if p_timr_id is not null and p_run is not null then',
'        create_repeat_subflow ',
'        ( p_process_id      => p_process_id',
'        , p_last_subflow_id => p_subflow_id',
'        , p_timr_id         => p_timr_id',
'        , p_next_run        => p_run + 1',
'        );',
'      end if;',
'      -- Non-Interrupting Timer Boundary Event has required functionality same as iCE currently',
'      handle_intermediate_catch_event ',
'      (',
'        p_process_id   => p_process_id',
'      , p_subflow_id   => p_subflow_id',
'      , p_step_key     => p_step_key',
'      , p_current_objt => l_sbfl_current',
'      );',
'    elsif l_curr_objt_tag_name in ( flow_constants_pkg.gc_bpmn_subProcess',
'                                  , flow_constants_pkg.gc_bpmn_task ',
'                                  , flow_constants_pkg.gc_bpmn_userTask',
'                                  , flow_constants_pkg.gc_bpmn_manualTask',
'                                  , flow_constants_pkg.gc_bpmn_call_activity',
'                                  , flow_constants_pkg.gc_bpmn_receiveTask',
'                                  , flow_constants_pkg.gc_bpmn_adhoc_subprocess',
'                                  )   -- add any objects that can support timer boundary events here',
'          -- if any of these events have a timer on them, it must be an interrupting timer.',
'          -- because non-interupting timers are set on the boundary event itself',
'      then',
'      -- we have an interrupting timer boundary event',
'      flow_boundary_events.handle_interrupting_boundary_event',
'      ( p_process_id      => p_process_id',
'      , p_subflow_id      => p_subflow_id',
'      , p_event_type      => p_event_type',
'      , p_boundary_object => p_callback_par',
'      );',
'    elsif l_curr_objt_tag_name = flow_constants_pkg.gc_bpmn_intermediate_catch_event  then ',
'      -- we need to look at previous step to see if this follows an eventBasedGateway...',
'      case l_follows_ebg ',
'      when ''Y'' then',
'        -- we have an eventBasedGateway',
'        handle_event_gateway_event ',
'        (',
'          p_process_id => p_process_id',
'        , p_parent_subflow_id => l_parent_subflow',
'        , p_cleared_subflow_id => p_subflow_id',
'        );',
'      else ',
'        -- independant iCE not following an eBG',
'        -- set subflow status to running and call flow_complete_step',
'        handle_intermediate_catch_event ',
'        (',
'          p_process_id => p_process_id',
'        , p_subflow_id => p_subflow_id',
'        , p_step_key   => p_step_key',
'        , p_current_objt => l_sbfl_current',
'        );',
'      end case;',
'    end if;',
'  end if; -- sbfl locked',
'exception',
'  when others then',
'    flow_errors.handle_instance_error',
'    ( pi_prcs_id  => p_process_id',
'    , pi_sbfl_id  => p_subflow_id',
'    , pi_message_key  => ''eng_handle_event_int''',
'    , p0  => p_process_id',
'    , p1  => p_subflow_id ',
'    , p2  => ''flow_handle_event''',
'    , p3  => l_curr_objt_tag_name',
'    , p4  => l_sbfl_current',
'    );',
'      -- $F4AMESSAGE ''eng_handle_event_int'' || ''Flow Engine Internal Error: Process %0 Subflow %1 Module %2 Current %4 Current Tag %3''',
'',
'end timer_callback;',
'',
'/************************************************************************************************************',
'****',
'****                       SUBFLOW  NEXT_STEP',
'****',
'*************************************************************************************************************/',
'',
'function finish_current_step',
'( p_sbfl_rec                     in flow_subflows%rowtype',
', p_log_as_completed             in boolean default true',
', p_reset_step_key               in boolean default false',
', p_force_next_step              in boolean default false',
', p_execute_variable_expressions in boolean default true  -- only false for force next step',
', p_matching_object              in flow_objects.objt_bpmn_id%type default null -- only for closing parallel and inclusive gateways and link events',
') return flow_types_pkg.t_iteration_status',
'is',
'  l_current_step_tag      flow_objects.objt_tag_name%type;',
'  l_iteration_status      flow_types_pkg.t_iteration_status;',
'begin',
'  -- runs all of the post-step operations for the old current task (handling post- expressionsa, releasing reservations, etc.)',
'  apex_debug.enter ',
'  ( ''finish_current_step''',
'  , ''Process ID'',  p_sbfl_rec.sbfl_prcs_id',
'  , ''Subflow ID'', p_sbfl_rec.sbfl_id',
'  , ''Current Step'', p_sbfl_rec.sbfl_current',
'  , ''p_reset_step_key'', case p_reset_step_key ',
'                        when true then ''True'' ',
'                        when false then ''False'' ',
'                        else ''null'' end',
'  , ''p_force_next_step'', case p_force_next_step ',
'                        when true then ''True'' ',
'                        when false then ''False'' ',
'                        else ''null'' end',
'  , ''p_execute_variable_expressions'', case p_execute_variable_expressions ',
'                                      when true then ''True'' ',
'                                      when false then ''False'' ',
'                                      else ''null'' end',
'  );',
'',
'',
'  l_current_step_tag := flow_engine_util.get_object_tag (p_sbfl_info => p_sbfl_rec);',
'',
'  if p_execute_variable_expressions then',
'',
'    -- evaluate and set any post-step variable expressions on the last object',
'    -- only not executed if the next step is forced and flag set to false',
'    if l_current_step_tag in ',
'    ( flow_constants_pkg.gc_bpmn_task, flow_constants_pkg.gc_bpmn_usertask, flow_constants_pkg.gc_bpmn_servicetask',
'    , flow_constants_pkg.gc_bpmn_manualtask, flow_constants_pkg.gc_bpmn_scripttask, flow_constants_pkg.gc_bpmn_businessruletask ',
'    , flow_constants_pkg.gc_bpmn_sendtask , flow_constants_pkg.gc_bpmn_receivetask )',
'    and p_sbfl_rec.sbfl_iteration_type is null ',
'    then ',
'      flow_expressions.process_expressions',
'        ( pi_objt_bpmn_id   => p_sbfl_rec.sbfl_current',
'        , pi_set            => flow_constants_pkg.gc_expr_set_after_task',
'        , pi_prcs_id        => p_sbfl_rec.sbfl_prcs_id',
'        , pi_sbfl_id        => p_sbfl_rec.sbfl_id',
'        , pi_step_key       => p_sbfl_rec.sbfl_step_key',
'        , pi_var_scope      => p_sbfl_rec.sbfl_scope',
'        , pi_expr_scope     => p_sbfl_rec.sbfl_scope',
'      );',
'    end if;',
'',
'  end if;',
'  -- clean up any boundary events left over from the previous activity',
'  if (l_current_step_tag in ( flow_constants_pkg.gc_bpmn_subprocess',
'                            , flow_constants_pkg.gc_bpmn_call_activity',
'                            , flow_constants_pkg.gc_bpmn_task',
'                            , flow_constants_pkg.gc_bpmn_usertask',
'                            , flow_constants_pkg.gc_bpmn_manualtask',
'                            , flow_constants_pkg.gc_bpmn_receivetask',
'                            ) -- boundary event attachable types',
'      and p_sbfl_rec.sbfl_has_events is not null )            -- subflow has events attached',
'  then',
'      -- ',
'      apex_debug.info ',
'      ( p_message => ''boundary event cleanup triggered for subflow %0''',
'      , p0        => p_sbfl_rec.sbfl_id',
'      );',
'      flow_boundary_events.unset_boundary_events ',
'      ( p_process_id => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_rec.sbfl_id);',
'  end if;',
'',
'  if p_sbfl_rec.sbfl_loop_counter is not null then',
'    case p_sbfl_rec.sbfl_iteration_type',
'    when flow_constants_pkg.gc_iteration_sequential then',
'      l_iteration_status := flow_iteration.sequential_complete_step (p_sbfl_info => p_sbfl_rec);',
'    when flow_constants_pkg.gc_iteration_loop then ',
'     if not p_reset_step_key then',
'        -- skip complete_step on the step after loop_init has run...',
'        l_iteration_status := flow_iteration.loop_complete_step (p_sbfl_info => p_sbfl_rec); ',
'     end if;',
'    else ',
'      null;   ',
'    end case;',
'  end if;',
'',
'  if p_log_as_completed then',
'    -- log current step as completed before releasing the reservation',
'    flow_logging.log_step_completion   ',
'    ( p_process_id        => p_sbfl_rec.sbfl_prcs_id',
'    , p_subflow_id        => p_sbfl_rec.sbfl_id',
'    , p_completed_object  => p_sbfl_rec.sbfl_current',
'    , p_iteration_status  => l_iteration_status',
'    , p_matching_object   => case l_current_step_tag',
'                              when flow_constants_pkg.gc_bpmn_gateway_inclusive then p_matching_object',
'                              when flow_constants_pkg.gc_bpmn_gateway_parallel  then p_matching_object',
'                              when flow_constants_pkg.gc_bpmn_intermediate_catch_event then p_matching_object',
'                              else null end',
'    , p_notes             => case p_force_next_step',
'                              when true then ''Step Completion was Forced. Variable Expressions were not executed.''',
'                              else null end',
'    );',
'    flow_logging.log_step_event',
'    ( p_sbfl_rec        => p_sbfl_rec',
'    , p_event           => case p_force_next_step',
'                              when true then flow_constants_pkg.gc_step_event_error_forced',
'                              else flow_constants_pkg.gc_step_event_completed end',
'    , p_event_level     => case p_force_next_step',
'                              when true then flow_constants_pkg.gc_logging_level_abnormal_events',
'                              else flow_constants_pkg.gc_logging_level_major_events end',
'    );',
'  end if;',
'  -- release subflow reservation',
'  if p_sbfl_rec.sbfl_reservation is not null then',
'    flow_reservations.release_step',
'    ( p_process_id        => p_sbfl_rec.sbfl_prcs_id',
'    , p_subflow_id        => p_sbfl_rec.sbfl_id',
'    , p_called_internally => true',
'    );',
'  end if;',
'',
'  apex_debug.info',
'  ( p_message => ''Post Step Operations completed for current step %1 on subflow %0. Iteration Complete: %2''',
'  , p0        => p_sbfl_rec.sbfl_id',
'  , p1        => p_sbfl_rec.sbfl_current',
'  , p2        => case l_iteration_status.is_complete when true then ''True'' when false then ''False'' else ''Null'' end',
'  );',
'  return l_iteration_status;',
'end finish_current_step;',
'',
'function get_step_info',
'( p_sbfl_rec                in flow_subflows%rowtype',
', p_forward_route           in flow_connections.conn_bpmn_id%type default null',
', p_is_restart              in boolean default false',
', p_iteration_is_complete   in boolean default false',
', p_previous_step           in flow_objects.objt_bpmn_id%type default null',
') return flow_types_pkg.flow_step_info',
'is',
'  l_dgrm_id               flow_diagrams.dgrm_id%type;',
'  l_step_info             flow_types_pkg.flow_step_info;',
'  l_iteration_type        varchar2(10);',
'begin',
'  apex_debug.enter ',
'  ( ''get_step_info''',
'  , ''Process ID'',    p_sbfl_rec.sbfl_prcs_id',
'  , ''Subflow ID'',    p_sbfl_rec.sbfl_id',
'  , ''Restart'',       case p_is_restart when true then ''True'' else ''False'' end',
'  , ''Forward Route'', p_forward_route',
'  , ''Iteration Complete'', case p_iteration_is_complete when true then ''True'' else ''False'' end',
'  , ''Loop Counter'', p_sbfl_rec.sbfl_loop_counter',
'  );',
'  begin',
'    case',
'    when ( p_sbfl_rec.sbfl_iteration_type is null and not p_is_restart )  -- usual next step case',
'      or ( p_sbfl_rec.sbfl_iteration_type in ( flow_constants_pkg.gc_iteration_sequential ',
'                                             , flow_constants_pkg.gc_iteration_loop)',
'           and p_iteration_is_complete',
'           and p_sbfl_rec.sbfl_loop_counter is null) -- current step is final sequential or loop iteration',
'    then',
'      -- Find next subflow step',
'      -- rewritten original LEFT JOIN query because of database 23.3 bug 35862529 (fixed db 23.4) which returns incorrect values on left join when including json attributes',
'      -- workaround - remove json columns from select list and query separately if lane_bpmn_is is not null',
'      apex_debug.message (''Getting next step using standard query...'');',
'      select p_sbfl_rec.sbfl_dgrm_id',
'           , objt_source.objt_tag_name',
'           , objt_source.objt_id',
'           , ''N''',
'           , conn.conn_tgt_objt_id',
'           , objt_target.objt_name',
'           , objt_target.objt_bpmn_id',
'           , objt_target.objt_tag_name   ',
'           , null ',
'           , objt_target.objt_sub_tag_name',
'           , objt_lane.objt_bpmn_id',
'           , objt_lane.objt_name',
'           , null -- objt_lane.objt_attributes."apex"."isRole"',
'           , null -- objt_lane.objt_attributes."apex"."role"',
'           , objt_target.objt_attributes',
'           , null',
'           , null',
'        into l_step_info',
'        from flow_connections conn',
'        join flow_objects objt_source',
'          on conn.conn_src_objt_id = objt_source.objt_id',
'         and conn.conn_dgrm_id     = objt_source.objt_dgrm_id',
'        join flow_objects objt_target',
'          on conn.conn_tgt_objt_id = objt_target.objt_id',
'         and conn.conn_dgrm_id     = objt_target.objt_dgrm_id',
'        left ',
'        join flow_objects objt_lane',
'          on objt_target.objt_objt_lane_id = objt_lane.objt_id',
'         and objt_target.objt_dgrm_id      = objt_lane.objt_dgrm_id',
'       where conn.conn_tag_name  = flow_constants_pkg.gc_bpmn_sequence_flow',
'         and ( p_forward_route is null',
'               OR  ( p_forward_route is not null AND conn.conn_bpmn_id = p_forward_route )',
'             )',
'         and conn.conn_dgrm_id        = p_sbfl_rec.sbfl_dgrm_id',
'         and objt_source.objt_bpmn_id = coalesce (p_previous_step, p_sbfl_rec.sbfl_current)',
'      ;',
'    else',
'      apex_debug.message (''Getting next step using restart and iteration query...'');',
'      select p_sbfl_rec.sbfl_dgrm_id',
'           , null ',
'           , null',
'           , ''N''',
'           , objt_current.objt_id',
'           , objt_current.objt_name',
'           , objt_current.objt_bpmn_id',
'           , objt_current.objt_tag_name  ',
'           , null  ',
'           , objt_current.objt_sub_tag_name',
'           , objt_lane.objt_bpmn_id',
'           , objt_lane.objt_name',
'           , null -- objt_lane.objt_attributes."apex"."isRole"',
'           , null -- objt_lane.objt_attributes."apex"."role"',
'           , objt_current.objt_attributes',
'           , null',
'           , null',
'        into l_step_info',
'        from flow_objects objt_current',
'        left ',
'        join flow_objects objt_lane',
'          on objt_current.objt_objt_lane_id = objt_lane.objt_id',
'         and objt_current.objt_dgrm_id      = objt_lane.objt_dgrm_id',
'       where objt_current.objt_bpmn_id = p_sbfl_rec.sbfl_current',
'         and objt_current.objt_dgrm_id = p_sbfl_rec.sbfl_dgrm_id',
'      ;',
'    end case;',
'',
'    if l_step_info.target_objt_lane is not null then',
'      begin',
'        -- workaround for database 23.3 bug 35862529 ',
'        select lane.objt_attributes."apex"."isRole"',
'             , lane.objt_attributes."apex"."role"',
'          into l_step_info.target_objt_lane_isRole',
'             , l_step_info.target_objt_lane_role',
'          from flow_objects lane',
'         where lane.objt_bpmn_id  = l_step_info.target_objt_lane',
'           and lane.objt_dgrm_id  = l_step_info.dgrm_id',
'        ;',
'      exception',
'        when no_data_found then ',
'          apex_debug.message ',
'          ( p_message => ''-- Lane %0 json attributes data not found''',
'          , p0 => l_step_info.target_objt_lane',
'          );',
'          raise;',
'      end;',
'    end if;',
'',
'    if l_step_info.target_objt_attributes is not null then',
'      l_step_info.target_objt_iteration := flow_engine_util.get_iteration_type (l_step_info);',
'      if l_step_info.target_objt_iteration is not null then',
'        flow_iteration.add_iteration_to_step_info ',
'        ( p_step_info             => l_step_info',
'        , p_sbfl_rec              => p_sbfl_rec',
'        , p_iteration_is_complete => p_iteration_is_complete',
'        );',
'      end if;',
'    end if;',
'',
'    if l_step_info.target_objt_treat_as_tag is not null then',
'      apex_debug.message (p_message => ''--treat as tag set to %0'',',
'      p0 => l_step_info.target_objt_treat_as_tag);',
'    end if;',
'',
'  exception',
'    when no_data_found then',
'      -- check for adhoc subprocess (has no end events)',
'      if p_sbfl_rec.sbfl_is_adhoc = ''Y'' then',
'        l_step_info.source_is_adhoc_endpoint := flow_constants_pkg.gc_true;',
'        apex_debug.message (p_message => ''-- Adhoc Subprocess End Point reached on subflow %0'',',
'                            p0 => p_sbfl_rec.sbfl_id);',
'        return l_step_info;',
'      else',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_sbfl_rec.sbfl_prcs_id',
'        , pi_sbfl_id        => p_sbfl_rec.sbfl_id',
'        , pi_message_key    => ''no_next_step_found''',
'        , p0 => p_sbfl_rec.sbfl_id',
'        );',
'        -- $F4AMESSAGE ''no_next_step_found'' || ''No Next Step Found on subflow %0.  Check your process diagram.''',
'      end if;',
'    when too_many_rows then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_rec.sbfl_id',
'      , pi_message_key    => ''more_than_1_forward_path''',
'      , p0 => p_sbfl_rec.sbfl_id',
'      );',
'      -- $F4AMESSAGE ''more_than_1_forward_path'' || ''More than 1 forward path found when only 1 allowed.''',
'    when others then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id  => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id  => p_sbfl_rec.sbfl_id',
'      , pi_message_key  => ''eng_handle_event_int''',
'      , p0  => p_sbfl_rec.sbfl_prcs_id',
'      , p1  => p_sbfl_rec.sbfl_id',
'      , p2  => ''get_step_info''',
'      , p3  => null',
'      , p4  => null',
'      );',
'      -- $F4AMESSAGE ''eng_handle_event_int'' || ''Flow Engine Internal Error: Process %0 Subflow %1 Module %2 Current %4 Current Tag %3''',
'  end;',
'  return l_step_info;',
'end get_step_info;',
'',
'procedure restart_failed_timer_step',
'( p_sbfl_rec    in flow_subflows%rowtype',
', p_step_info   in flow_types_pkg.flow_step_info',
')',
'is',
'begin',
'  -- if an event with timer fails when the timer fires, we restart it by ignoring the timer',
'  -- and immediately running the on-event variable set and then moving forwards on the subflow',
'  apex_debug.enter ',
'  ( ''restart_failed_timer_step''',
'  , ''Process ID'',  p_sbfl_rec.sbfl_prcs_id',
'  , ''Subflow ID'', p_sbfl_rec.sbfl_id',
'  );',
'',
'  apex_debug.info ',
'  ( p_message => ''Restart Timer Step - Target object: %s.  More info at APP_TRACE level.''',
'  , p0        => coalesce(p_step_info.target_objt_tag, ''!NULL!'') ',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Restart Timer Info - dgrm_id : %0, source_objt_tag : %1, target_objt_id : %2, target_objt_ref : %3''',
'  , p0  => p_step_info.dgrm_id',
'  , p1  => p_step_info.source_objt_tag',
'  , p2  => p_step_info.target_objt_id',
'  , p3  => p_step_info.target_objt_ref',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Timer Step Info - target_objt_tag : %0, target_objt_subtag : %1''',
'  , p0 => p_step_info.target_objt_tag',
'  , p1 => p_step_info.target_objt_subtag',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Running Step Context - sbfl_id : %0, sbfl_last_completed : %1, sbfl_prcs_id : %2''',
'  , p0 => p_sbfl_rec.sbfl_id',
'  , p1 => p_sbfl_rec.sbfl_last_completed',
'  , p2 => p_sbfl_rec.sbfl_prcs_id',
'  );   ',
'  --  Set status to waiting and reschedule the timer with current time.',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_waiting_timer',
'           , sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )  ',
'       where sbfl.sbfl_id = p_sbfl_rec.sbfl_id',
'         and sbfl.sbfl_prcs_id = p_sbfl_rec.sbfl_prcs_id',
'      ;',
'      flow_timers_pkg.reschedule_timer',
'      ( ',
'        p_process_id          => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id          => p_sbfl_rec.sbfl_id',
'      , p_step_key            => p_sbfl_rec.sbfl_step_key',
'      , p_restart_immediate   => true',
'      , p_is_immediate        => true',
'      , p_comment             => ''Restart Immediate Broken Timer''',
'      );',
'',
'end restart_failed_timer_step;',
'',
'procedure run_step',
'( p_sbfl_rec              in flow_subflows%rowtype',
', p_step_info             in flow_types_pkg.flow_step_info',
', p_iteration_is_complete in boolean default false',
')',
'is',
'  l_iteration_status        flow_types_pkg.t_iteration_status;',
'  l_iteration_is_complete   boolean;',
'begin',
'  apex_debug.enter ',
'  ( ''run_step''',
'  , ''Process ID'',  p_sbfl_rec.sbfl_prcs_id',
'  , ''Subflow ID'', p_sbfl_rec.sbfl_id',
'  , ''Loop Counter'', p_sbfl_rec.sbfl_loop_counter',
'  , ''SBFL Iteration Type'', p_sbfl_rec.sbfl_iteration_type',
'  , ''Step Iteration Type'', p_step_info.target_objt_iteration',
'  , ''iteration_is_complete'' , case p_iteration_is_complete when true then ''True'' when false then ''False'' else ''null'' end',
'  );',
'',
'  apex_debug.info ',
'  ( p_message => ''Running Step - Target object: %s.  More info at APP_TRACE level.''',
'  , p0        => coalesce(p_step_info.target_objt_tag, ''!NULL!'') ',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Running Step Info - dgrm_id : %0, source_objt_tag : %1, target_objt_id : %2, target_objt_ref : %3''',
'  , p0  => p_step_info.dgrm_id',
'  , p1  => p_step_info.source_objt_tag',
'  , p2  => p_step_info.target_objt_id',
'  , p3  => p_step_info.target_objt_ref',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Running Step Info - target_objt_tag : %0 (treat like %2 ), target_objt_subtag : %1, iteration: %3 (lo'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'op: %4), iter_id: %5, iobj_id: %6 iteration var %7''',
'  , p0 => p_step_info.target_objt_tag',
'  , p1 => p_step_info.target_objt_subtag',
'  , p2 => coalesce (p_step_info.target_objt_treat_as_tag, p_step_info.target_objt_tag)',
'  , p3 => nvl ( p_step_info.target_objt_iteration, ''None'')',
'  , p4 => p_sbfl_rec.sbfl_loop_counter',
'  , p5 => p_sbfl_rec.sbfl_iter_id',
'  , p6 => p_sbfl_rec.sbfl_iobj_id',
'  , p7 => p_sbfl_rec.sbfl_iteration_var',
'  );',
'  apex_debug.trace',
'  ( p_message => ''Running Step Context - sbfl_id : %0, sbfl_last_completed : %1, sbfl_prcs_id : %2''',
'  , p0 => p_sbfl_rec.sbfl_id',
'  , p1 => p_sbfl_rec.sbfl_last_completed',
'  , p2 => p_sbfl_rec.sbfl_prcs_id',
'  );    ',
'',
'  -- log step as current',
'  flow_logging.log_step_event',
'  ( p_sbfl_rec    => p_sbfl_rec',
'  , p_event       => flow_constants_pkg.gc_step_event_became_current',
'  , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'  , p_comment     => case',
'                       when flow_globals.get_is_async_session',
'                        and is_async_step( p_step_info => p_step_info )',
'                       then ''running async in AQ session''',
'                     end',
'  );',
'  -- TODO - consider moving this into flow_tasks when you have priority, due on, reservation data...',
'',
'  -- evaluate and set any pre-step variable expressions on the next object',
'  if p_step_info.target_objt_tag in ',
'  ( flow_constants_pkg.gc_bpmn_task, flow_constants_pkg.gc_bpmn_usertask, flow_constants_pkg.gc_bpmn_servicetask',
'  , flow_constants_pkg.gc_bpmn_manualtask, flow_constants_pkg.gc_bpmn_scripttask, flow_constants_pkg.gc_bpmn_businessruletask ',
'  , flow_constants_pkg.gc_bpmn_sendtask , flow_constants_pkg.gc_bpmn_receivetask )',
'  and p_sbfl_rec.sbfl_loop_counter is null',
'  then ',
'    flow_expressions.process_expressions',
'      ( pi_objt_id     => p_step_info.target_objt_id',
'      , pi_set         => flow_constants_pkg.gc_expr_set_before_task',
'      , pi_prcs_id     => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_rec.sbfl_id',
'      , pi_step_key    => p_sbfl_rec.sbfl_step_key',
'      , pi_var_scope   => p_sbfl_rec.sbfl_scope',
'      , pi_expr_scope  => p_sbfl_rec.sbfl_scope',
'    );',
'  elsif p_step_info.target_objt_tag in ',
'  ( flow_constants_pkg.gc_bpmn_start_event, flow_constants_pkg.gc_bpmn_end_event ',
'  , flow_constants_pkg.gc_bpmn_intermediate_throw_event, flow_constants_pkg.gc_bpmn_intermediate_catch_event',
'  , flow_constants_pkg.gc_bpmn_boundary_event )',
'  then',
'    flow_expressions.process_expressions',
'      ( pi_objt_id     => p_step_info.target_objt_id',
'      , pi_set         => flow_constants_pkg.gc_expr_set_before_event',
'      , pi_prcs_id     => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_rec.sbfl_id',
'      , pi_step_key    => p_sbfl_rec.sbfl_step_key',
'      , pi_var_scope   => p_sbfl_rec.sbfl_scope',
'      , pi_expr_scope  => p_sbfl_rec.sbfl_scope',
'    );',
'  end if;',
'',
'  l_iteration_is_complete := p_iteration_is_complete;',
'  if l_iteration_is_complete is null then',
'    l_iteration_is_complete := false;',
'  end if;',
'',
'  apex_debug.message (p_message => ''run step --> start iterated step? Loop Counter %0 Iter_complete %1 iter_type %2''',
'  , p0 => p_sbfl_rec.sbfl_loop_counter',
'  , p1 => case l_iteration_is_complete when true then ''True'' when false then ''False'' else ''null'' end',
'  , p2 => p_sbfl_rec.sbfl_iteration_type',
'  );',
'',
'  if  ( p_sbfl_rec.sbfl_loop_counter is not null ',
'        and l_iteration_is_complete != true)  then',
'    case p_sbfl_rec.sbfl_iteration_type ',
'    when flow_constants_pkg.gc_iteration_sequential then',
'      apex_debug.message (p_message => ''run step --> calling sequential start step'');',
'      flow_iteration.sequential_start_step ( p_sbfl_info => p_sbfl_rec);',
'    when flow_constants_pkg.gc_iteration_loop then',
'      apex_debug.message (p_message => ''run step --> calling loop start step'');',
'      flow_iteration.loop_start_step ( p_sbfl_info => p_sbfl_rec);   ',
'    else',
'      null;',
'    end case;   ',
'  end if;',
'',
'  case coalesce (p_step_info.target_objt_treat_as_tag, p_step_info.target_objt_tag)',
'    when flow_constants_pkg.gc_bpmn_end_event then  --next step is either end of process or sub-process returning to its parent',
'      flow_engine.process_endEvent',
'      ( p_process_id => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_rec.sbfl_id',
'      , p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_gateway_exclusive then',
'      flow_gateways.process_exclusiveGateway',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_gateway_inclusive then',
'      flow_gateways.process_para_incl_Gateway',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_gateway_parallel then',
'      flow_gateways.process_para_incl_Gateway',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_subprocess then',
'      flow_subprocesses.process_subProcess',
'      ( p_process_id => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_rec.sbfl_id',
'      , p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_call_activity then',
'      flow_call_activities.process_callActivity',
'      ( p_process_id => p_sbfl_rec.sbfl_prcs_id',
'      , p_subflow_id => p_sbfl_rec.sbfl_id',
'      , p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when flow_constants_pkg.gc_bpmn_adhoc_subprocess then',
'      flow_adhoc_subprocesses.start_adhoc_SubProcess',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );      ',
'    when flow_constants_pkg.gc_bpmn_gateway_event_based then',
'      flow_gateways.process_eventBasedGateway',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when  flow_constants_pkg.gc_bpmn_intermediate_catch_event then ',
'      flow_engine.process_intermediateCatchEvent',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when  flow_constants_pkg.gc_bpmn_intermediate_throw_event then ',
'      flow_engine.process_intermediateThrowEvent',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      ); ',
'    when  flow_constants_pkg.gc_bpmn_task then ',
'      flow_tasks.process_task',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_usertask then',
'      flow_tasks.process_userTask',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_scripttask then ',
'      flow_tasks.process_scriptTask',
'      (p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_manualtask then ',
'      flow_tasks.process_manualTask',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_servicetask then ',
'      flow_tasks.process_serviceTask',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_businessruletask then ',
'      flow_tasks.process_businessRuleTask',
'         ( p_sbfl_info => p_sbfl_rec',
'         , p_step_info => p_step_info',
'         );',
'    when  flow_constants_pkg.gc_bpmn_sendtask then ',
'      flow_tasks.process_sendTask',
'      ( p_sbfl_info => p_sbfl_rec',
'      , p_step_info => p_step_info',
'      );',
'    when  flow_constants_pkg.gc_bpmn_receivetask then ',
'      flow_tasks.process_receiveTask',
'         ( p_sbfl_info => p_sbfl_rec',
'         , p_step_info => p_step_info',
'         );',
'    when flow_constants_pkg.gc_iteration_sequential then',
'      l_iteration_status := flow_iteration.sequential_init',
'         ( p_sbfl_info => p_sbfl_rec',
'         , p_step_info => p_step_info',
'         );',
'    when flow_constants_pkg.gc_iteration_loop then',
'      l_iteration_status := flow_iteration.loop_init',
'         ( p_sbfl_info => p_sbfl_rec',
'         , p_step_info => p_step_info',
'         );',
'    when ''sequentialIterationClose'' then',
'      flow_iteration.sequential_close_iteration',
'         ( p_sbfl_info => p_sbfl_rec',
'         , p_step_info => p_step_info',
'         );',
'    end case;',
'',
'  exception',
'    when case_not_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_rec.sbfl_id',
'      , pi_message_key => ''engine-unsupported-object''',
'      , p0 => p_step_info.target_objt_tag',
'      );',
'      -- $F4AMESSAGE ''engine-unsupported-object'' || ''Model Error: Process BPMN model next step uses unsupported object %0''  ',
'    when no_data_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_rec.sbfl_id',
'      , pi_message_key => ''no_next_step_found''',
'      , p0 => p_sbfl_rec.sbfl_id',
'      );',
'      -- $F4AMESSAGE ''no_next_step_found'' || ''No Next Step Found on subflow %0.  Check your process diagram.''  ',
'    when e_feature_requires_ee then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_sbfl_rec.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_rec.sbfl_id',
'      , pi_message_key => ''feature-requires-ee''',
'      );',
'      -- $F4AMESSAGE ''feature-requires-ee'' || ''Processing this feature requires licensing Flows for APEX Enterprise Edition.'' ',
'    when flow_plsql_runner_pkg.e_plsql_script_failed then',
'      null;',
'  -- let error run back to run_step',
'end run_step;',
'',
'',
'procedure flow_complete_step',
'( p_process_id                   in flow_processes.prcs_id%type',
', p_subflow_id                   in flow_subflows.sbfl_id%type ',
', p_step_key                     in flow_subflows.sbfl_step_key%type default null',
', p_forward_route                in flow_connections.conn_bpmn_id%type default null',
', p_log_as_completed             in boolean default true',
', p_reset_step_key               in boolean default false -- only set for initial call after splitting parallel iteration',
', p_recursive_call               in boolean default true',
', p_force_next_step              in boolean default false',
', p_execute_variable_expressions in boolean default true',
', p_matching_object              in flow_objects.objt_bpmn_id%type default null  -- only set when current object is a closing parallel or inclusive gateway or link',
')',
'is',
'  l_sbfl_rec                  flow_subflows%rowtype;',
'  l_step_info                 flow_types_pkg.flow_step_info;',
'  l_dgrm_id                   flow_diagrams.dgrm_id%type;',
'  l_timestamp                 flow_subflows.sbfl_became_current%type;',
'  l_step_key                  flow_subflows.sbfl_step_key%type;',
'  l_previous_step             flow_objects.objt_bpmn_id%type;  ',
'  l_new_status                flow_subflows.sbfl_status%type;',
'  l_next_loop_counter         number;',
'  l_existing_iter_id          flow_iterations.iter_id%type;',
'  l_existing_iobj_id          flow_iterated_objects.iobj_id%type;',
'  l_next_iter_id              flow_iterations.iter_id%type;',
'  l_next_iobj_id              flow_iterated_objects.iobj_id%type;',
'  l_total_loop_instances      number;',
'  l_iteration_status          flow_types_pkg.t_iteration_status;',
'  l_iter_info                 flow_types_pkg.t_iteration_status;',
'  l_next_step_confirmed       boolean := false;',
' -- l_prcs_check_id         flow_processes.prcs_id%type;',
'begin',
'  apex_debug.enter ',
'  ( ''flow_complete_step''',
'  , ''Process ID'',  p_process_id',
'  , ''Subflow ID'', p_subflow_id',
'  , ''Supplied Step Key'', p_step_key',
'  , ''recursive_call'', case when p_recursive_call then ''true''  else ''false''  end',
'  , ''reset_step_key'', case when p_reset_step_key then ''true''  else ''false''  end',
'  , ''forced_next_step'', case when p_force_next_step then ''true''  else ''false''  end',
'  , ''execute_var_exps'', case when p_execute_variable_expressions then ''true''  ',
'                             else ''false''  end',
'  );',
'  flow_globals.set_is_recursive_step (p_is_recursive_step => p_recursive_call);',
'  -- Get current object and current subflow info and lock it',
'  l_sbfl_rec := flow_engine_util.get_subflow_info ',
'                ( p_process_id   => p_process_id',
'                , p_subflow_id   => p_subflow_id',
'                , p_lock_process => false ',
'                , p_lock_subflow => true',
'                );',
'',
'  -- prevent any external complete_step calls when the process is suspended',
'  if  flow_instances.status (p_process_id) = flow_constants_pkg.gc_prcs_status_suspended ',
'      and not p_recursive_call then',
'      ',
'    apex_debug.info',
'    ( p_message => ''Process %0 is suspended.  Cannot complete step on subflow %1.''',
'    , p0        => p_process_id',
'    , p1        => p_subflow_id',
'    );',
'    flow_errors.handle_instance_error',
'    ( pi_prcs_id     => p_process_id',
'    , pi_sbfl_id     => p_subflow_id',
'    , pi_message_key => ''suspended-cannot-complete-step''',
'    , p0            => p_process_id',
'    , p1            => p_subflow_id',
'    );',
'    --F$MESSAGE ''suspended-cannot-complete-step'' || ''Process %0 is suspended.  Cannot complete step on subflow %1.''',
'  end if;',
'',
'  -- check step key is valid',
'  if flow_engine_util.step_key_valid( pi_prcs_id            => p_process_id',
'                                    , pi_sbfl_id            => p_subflow_id',
'                                    , pi_step_key_supplied  => p_step_key',
'                                    , pi_step_key_required  => l_sbfl_rec.sbfl_step_key) then ',
'    -- step key is valid ',
'    -- if subflow has any associated non-interrupting timers on current object, lock the subflows and timers',
'    -- (other boundary event types only create a subflow when they fire)',
'    if l_sbfl_rec.sbfl_has_events like ''%:CNT%'' then ',
'      flow_boundary_events.lock_child_boundary_timers',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_parent_objt_bpmn_id => l_sbfl_rec.sbfl_current ',
'      ); ',
'    end if;',
'    -- lock associated timers for interrupting boundary events',
'    if l_sbfl_rec.sbfl_has_events like ''%:S_T%'' then ',
'      flow_timers_pkg.lock_timer(p_process_id, p_subflow_id);',
'    end if;',
'',
'    -- complete the current step by doing the post-step operations',
'    l_iteration_status  :=  finish_current_step',
'                            ( p_sbfl_rec                     => l_sbfl_rec',
'                            , p_log_as_completed             => p_log_as_completed',
'                            , p_reset_step_key               => p_reset_step_key',
'                            , p_force_next_step              => p_force_next_step',
'                            , p_execute_variable_expressions => p_execute_variable_expressions',
'                            , p_matching_object              => p_matching_object',
'                            );',
'',
'    if flow_globals.get_step_error then',
'      rollback;',
'      if p_recursive_call then',
'        -- set error status on instance and subflow',
'        flow_errors.set_error_status',
'        ( pi_prcs_id => p_process_id',
'        , pi_sbfl_id => p_subflow_id',
'        );',
'      end if;',
'      apex_debug.info',
'      ( p_message => ''Subflow %0 : Step End Rollback due to earlier Error on Step %1''',
'      , p0        => p_subflow_id',
'      , p1        => l_sbfl_rec.sbfl_current',
'      );      ',
'    else',
'      l_previous_step := l_sbfl_rec.sbfl_current;',
'        --',
'        -- if next step is an iteration over a collection, check that the collection has members before confirming ',
'        -- it is the next step.  If not, step forward again by picking the next step',
'        -- start by finding the next subflow step',
'        l_step_info := get_step_info  ( p_sbfl_rec              => l_sbfl_rec',
'                                      , p_forward_route         => p_forward_route',
'                                      , p_iteration_is_complete => l_iteration_status.is_complete',
'                                      , p_previous_step         => l_previous_step',
'                                      );  ',
'        apex_debug.message ',
'        (p_message => ''flow_complete_step --> got next step info: target_objt_tag %0, target_objt_iteration %1, adhoc_endpoint %2''',
'        , p0 => l_step_info.target_objt_tag',
'        , p1 => nvl ( l_step_info.target_objt_iteration, ''None'')',
'        , p2 => l_step_info.source_is_adhoc_endpoint',
'        );',
'  ',
'        if l_step_info.source_is_adhoc_endpoint = flow_constants_pkg.gc_false then ',
'          -- get next step key',
'          l_step_info.target_objt_step_key  := flow_engine_util.step_key ( pi_sbfl_id         => p_subflow_id',
'                                                                    , pi_current         => l_step_info.target_objt_ref',
'                                                                    );',
'          -- control iteration progression',
'          l_existing_iter_id        := l_sbfl_rec.sbfl_iter_id;',
'          l_existing_iobj_id        := l_sbfl_rec.sbfl_iobj_id;',
'          case l_step_info.target_objt_iteration ',
'          when flow_constants_pkg.gc_iteration_sequential then',
'            if l_sbfl_rec.sbfl_current != l_step_info.target_objt_ref',
'            then',
'--              -- next step is a new sequential iteration',
'--              -- sequential iteration info is set when iteration subflows are create',
'              null;                                                           ',
'            elsif p_reset_step_key then',
'              -- the next step is the iterating object (not the 2nd phase of sequential init)',
'              -- so reset the step key in the iteration array',
'              apex_debug.message (''call from flow_engine...'');',
'              l_next_loop_counter    := 1;',
'              l_total_loop_instances := l_sbfl_rec.sbfl_loop_total_instances;',
'              l_next_iobj_id         := l_existing_iobj_id;',
'              l_next_step_confirmed  := true;',
'              l_next_iter_id := flow_iteration.get_iteration_id ( p_prcs_id      => p_process_id',
'                                                                , p_iobj_id      => l_next_iobj_id',
'                                                                , p_loop_counter => l_next_loop_counter',
'                                                                );                                                         ',
'            elsif l_sbfl_rec.sbfl_loop_counter is not null then',
'              if l_step_info.target_objt_treat_as_tag = ''sequentialIterationClose'' then',
'                -- this is the extra ''closing gateway'' step that we add to close the iteration subflow & return',
'                -- processing back to the parent subflow.',
'                null;',
'              else',
'              -- loop counter has value - so sequentia iteration is in progress',
'              -- next step is the next sequential iteration of an existing iteration',
'              l_next_loop_counter    := l_sbfl_rec.sbfl_loop_counter +1;',
'              l_total_loop_instances := l_sbfl_rec.sbfl_loop_total_instances;',
'              l_next_iobj_id         := l_existing_iobj_id;',
'',
'              l_next_iter_id := flow_iteration.get_iteration_id ( p_prcs_id      => p_process_id',
'                                                                 , p_iobj_id      => l_next_iobj_id',
'                                                                 , p_loop_counter => l_next_loop_counter',
'                                                                 );  ',
'',
'              end if;',
'            else',
'              null;',
'            end if; -- loop counter',
'          when flow_constants_pkg.gc_iteration_parallel then',
'            if p_reset_step_key then',
'              -- the next step is the iterating object (not the 2nd phase of the implicit parallel gateway)',
'              -- so reset the step key in the iteration array',
'              apex_debug.message (''call from flow_engine...'');',
'              flow_iteration.set_iteration_status',
'              ( pi_prcs_id        => p_process_id',
'              , pi_loop_counter   => l_sbfl_rec.sbfl_loop_counter',
'              , pi_new_status     => flow_constants_pkg.gc_iteration_status_running ',
'              , pi_step_key       => l_step_info.target_objt_step_key',
'              , pi_scope          => l_sbfl_rec.sbfl_iteration_var_scope',
'              , pi_prov_var_name  => l_sbfl_rec.sbfl_iteration_var',
'              , pi_iobj_id        => l_sbfl_rec.sbfl_iobj_id',
'              );',
'            end if;',
'            l_next_loop_counter := l_sbfl_rec.sbfl_loop_counter;',
'            l_total_loop_instances := l_sbfl_rec.sbfl_loop_total_instances;                                                      ',
'            l_next_iobj_id         := l_existing_iobj_id;',
'            l_next_iter_id         := l_existing_iter_id;',
'',
'          when flow_constants_pkg.gc_iteration_loop then',
'            if l_sbfl_rec.sbfl_current != l_step_info.target_objt_ref then',
'              -- next step is a new bpmn loop ',
'              -- for loop iteration we use the original subflow for the iterands so need ',
'              -- to set loop info on the original subflow. ',
'              -- loop iteration info is set when iteration subflows are created',
'              null;',
'            elsif p_reset_step_key then',
'              -- the next step is the iterating object (not the 2nd phase of sequential init)',
'              -- so reset the step key in the iteration array',
'              apex_debug.message (''call from flow_engine...'');',
'              l_next_loop_counter    := 1;',
'              l_total_loop_instances := 1;',
'              l_next_iobj_id         := l_existing_iobj_id;',
'',
'            elsif l_sbfl_rec.sbfl_loop_counter is not null then',
'              if l_step_info.target_objt_treat_as_tag = ''sequentialIterationClose'' then',
'                -- this is the extra ''closing gateway'' step that we add to close the iteration subflow & return',
'                -- processing back to the parent subflow.',
'                null;',
'              else',
'                -- loop counter has value - so sequentia iteration is in progress',
'                -- next step is the next sequential iteration of an existing iteration',
'                l_next_loop_counter    := l_sbfl_rec.sbfl_loop_counter +1;',
'                l_total_loop_instances := l_sbfl_rec.sbfl_loop_total_instances +1;',
'                l_next_iobj_id         := l_existing_iobj_id;',
'',
'                -- create new iteration and extend the iteration array',
'',
'                l_next_iter_id := flow_iteration.get_iteration_id ( p_prcs_id      => p_process_id',
'                                                                   , p_iobj_id      => l_next_iobj_id',
'                                                                   , p_loop_counter => l_next_loop_counter',
'                                                                   );  ',
'                                                         ',
'              end if; --treat as tag',
'            end if; -- loop counter',
'          else ',
'            apex_debug.message (p_message => ''next step not an iteration or loop'');',
'            -- next step is not an iteration or loop ',
'            l_next_loop_counter := null;',
'            l_total_loop_instances := l_sbfl_rec.sbfl_loop_total_instances; ',
'            l_next_step_confirmed  := true;',
'            l_next_iter_id := l_existing_iter_id;',
'          end case; -- iteration type',
'        end if; -- source is not adhoc endpoint',
'      end if; -- step error',
'    end if; -- step key valid',
'',
'    -- end of post-step operations for previous step',
'    if flow_globals.get_step_error then',
'      rollback;',
'      if p_recursive_call then',
'        -- set error status on instance and subflow',
'        flow_errors.set_error_status',
'        ( pi_prcs_id => p_process_id',
'        , pi_sbfl_id => p_subflow_id',
'        );',
'      end if;',
'      apex_debug.info',
'      ( p_message => ''Subflow %0 : Step End Rollback due to earlier Error on Step %1''',
'      , p0        => p_subflow_id',
'      , p1        => l_sbfl_rec.sbfl_current',
'      );',
'    elsif l_step_info.source_is_adhoc_endpoint = flow_constants_pkg.gc_true then',
'      -- if the source was an adhoc endpoint, then the subflow is now complete',
'      -- unlike normal subflow there is no end event to process - flow_adhoc_subprocesses.end_adhoc_activity should be called instead',
'      flow_adhoc_subprocesses.end_adhoc_activity ( p_sbfl_rec => l_sbfl_rec );',
'    else',
'      l_timestamp := systimestamp;',
'  ',
'      -- think about adding a check here if suspended and ee and certain object types',
'      -- will test using a case statement in the update of sbfl_status...',
'      l_new_status := case l_sbfl_rec.sbfl_status',
'                      when flow_constants_pkg.gc_sbfl_status_suspended then flow_constants_pkg.gc_sbfl_status_restart_on_resume',
'                      else flow_constants_pkg.gc_sbfl_status_running',
'                      end; ',
'   ',
'      -- update subflow with step completed, and prepare for next step before committing',
'      update flow_subflows sbfl',
'        set sbfl.sbfl_current             = l_step_info.target_objt_ref',
'          , sbfl.sbfl_last_completed      = l_sbfl_rec.sbfl_current',
'          , sbfl.sbfl_became_current      = l_timestamp',
'          , sbfl.sbfl_step_key            = l_step_info.target_objt_step_key',
'          , sbfl.sbfl_status              = l_new_status',
'          , sbfl.sbfl_work_started        = null',
'          , sbfl.sbfl_potential_users     = null',
'          , sbfl.sbfl_potential_groups    = null',
'          , sbfl.sbfl_excluded_users      = null',
'          , sbfl.sbfl_apex_task_id        = null',
'          , sbfl.sbfl_lane                = coalesce( l_step_info.target_objt_lane       , sbfl.sbfl_lane        , null)',
'          , sbfl.sbfl_lane_name           = coalesce( l_step_info.target_objt_lane_name  , sbfl.sbfl_lane_name   , null)',
'          , sbfl.sbfl_lane_isRole         = coalesce( l_step_info.target_objt_lane_isRole, sbfl.sbfl_lane_isRole , null)',
'          , sbfl.sbfl_lane_role           = case l_step_info.target_objt_lane_isRole',
'                                            when ''true'' then l_step_info.target_objt_lane_role',
'                                            when ''false'' then null',
'                                            else coalesce( sbfl.sbfl_lane_role   , null)',
'                                            end',
'          , sbfl.sbfl_iter_id             = coalesce(l_next_iter_id, sbfl.sbfl_iter_id)',
'          , sbfl.sbfl_iobj_id             = l_next_iobj_id                                  ',
'          , sbfl.sbfl_loop_counter        = l_next_loop_counter',
'          , sbfl.sbfl_iteration_type      = l_step_info.target_objt_iteration',
'          , sbfl.sbfl_loop_total_instances',
'                                          = coalesce(l_total_loop_instances, sbfl.sbfl_loop_total_instances)',
'          , sbfl.sbfl_iteration_var       = l_iteration_status.iteration_var',
'          , sbfl.sbfl_iteration_var_scope = l_iteration_status.var_scope',
'          , sbfl.sbfl_last_update         = l_timestamp',
'          , sbfl.sbfl_last_update_by      = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'      where sbfl.sbfl_prcs_id = p_process_id',
'        and sbfl.sbfl_id = p_subflow_id',
'      ;',
'      commit;',
'  ',
'      apex_debug.info',
'      ( p_message => ''Subflow %0 : Step End Committed for step %1.  New Sbfl Status %3''',
'      , p0        => p_subflow_id',
'      , p1        => l_sbfl_rec.sbfl_current',
'      , p2        => case l_sbfl_rec.sbfl_loop_counter ',
'                          when null then ''''',
'                          else '' [''||l_sbfl_rec.sbfl_loop_counter ||'']''',
'                          end',
'      , p3        => l_new_status',
'      );',
'    ',
'      if l_new_status = flow_constants_pkg.gc_sbfl_status_running then',
'        -- start of pre-phase for next step',
'        -- reset step_had_error flag',
'        flow_globals.set_step_error ( p_has_error => false);',
'        -- now into next step so is not part of users current step',
'        flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'        apex_debug.info ( p_message => ''Step now counted as recursive'');',
'        -- relock subflow',
'        l_sbfl_rec := flow_engine_util.get_subflow_info ',
'        ( p_process_id => p_process_id',
'        , p_subflow_id => p_subflow_id',
'        , p_lock_process => false',
'        , p_lock_subflow => true',
'        );',
'',
'   -- Run or queue the step',
'      dispatch_step ',
'        ( p_sbfl_rec                => l_sbfl_rec',
'        , p_step_info               => l_step_info ',
'        , p_iteration_is_complete   => l_iteration_status.is_complete',
'        );',
'        -- Commit transaction before returning',
'        if flow_globals.get_step_error then',
'          rollback;',
'    ',
'          -- set error status on instance and subflow',
'          flow_errors.set_error_status',
'          ( pi_prcs_id => p_process_id',
'          , pi_sbfl_id => p_subflow_id',
'          );',
'          commit;',
'    ',
'          apex_debug.info',
'          ( p_message => ''Subflow %0 : Step End Rollback due to earlier Error.  (Error Status Just Committed.)''',
'          , p0        => p_subflow_id',
'          );',
'  ',
'        else',
'          commit;',
'  ',
'          apex_debug.info',
'          ( p_message => ''Subflow %0 : Step End Committed''',
'          , p0        => p_subflow_id',
'          );',
'        end if;  -- step error',
'      end if; -- status = running',
'    end if;',
'  end flow_complete_step;',
'',
'  procedure start_step -- just (optionally) records the start time of work on the current step',
'    ( p_process_id         in flow_processes.prcs_id%type',
'    , p_subflow_id         in flow_subflows.sbfl_id%type',
'    , p_step_key           in flow_sub'))
);
end;
/
begin
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'flows.sbfl_step_key%type default null',
'    , p_called_internally  in boolean default false',
'    )',
'  is',
'    l_existing_start       flow_subflows.sbfl_work_started%type;',
'    l_sbfl_rec             flow_subflows%rowtype;',
'  begin',
'    apex_debug.enter',
'    ( ''start_step''',
'    , ''Subflow '', p_subflow_id',
'    , ''Process '', p_process_id ',
'    , ''Step Key'', p_step_key',
'    );',
'    -- subflow should already be locked when calling internally',
'    l_sbfl_rec := flow_engine_util.get_subflow_info ',
'                  ( p_process_id   => p_process_id',
'                  , p_subflow_id   => p_subflow_id',
'                  , p_lock_subflow => not p_called_internally',
'                  );',
'    -- check the step key',
'    if flow_engine_util.step_key_valid( pi_prcs_id  => p_process_id',
'                                      , pi_sbfl_id  => p_subflow_id',
'                                      , pi_step_key_supplied  => p_step_key',
'                                      , pi_step_key_required  => l_sbfl_rec.sbfl_step_key',
'                                      ) ',
'    then ',
'      -- set the start time if null (will happen first time work started)',
'      if l_existing_start is null then',
'        update flow_subflows sbfl',
'           set sbfl_work_started        = systimestamp',
'             , sbfl.sbfl_last_update    = systimestamp',
'             , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'        where sbfl_prcs_id = p_process_id',
'          and sbfl_id = p_subflow_id',
'        ;',
'      end if;',
'      -- log the start',
'      flow_logging.log_step_event ',
'      ( p_sbfl_rec    => l_sbfl_rec',
'      , p_event       => flow_constants_pkg.gc_step_event_work_started',
'      , p_event_level => flow_constants_pkg.gc_logging_level_routine',
'      );',
'      -- commit reservation if this is an external call',
'      if not p_called_internally then ',
'        commit;',
'      end if;',
'    end if;',
'  exception',
'    when no_data_found then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''startwork-sbfl-not-found''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );',
'      -- $F4AMESSAGE ''startwork-sbfl-not-found'' || ''Start Work time recording unsuccessful.  Subflow %0 in Process %1 not found.''  ',
'    when lock_timeout then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''timeout_locking_subflow''',
'      , p0 => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''        ',
'  end start_step;',
'',
'  procedure pause_step -- just (optionally) records the pause time of work on the current step',
'    ( p_process_id         in flow_processes.prcs_id%type',
'    , p_subflow_id         in flow_subflows.sbfl_id%type',
'    , p_step_key           in flow_subflows.sbfl_step_key%type default null',
'    , p_called_internally  in boolean default false',
'    )',
'  is',
'    l_existing_start       flow_subflows.sbfl_work_started%type;',
'    l_sbfl_rec             flow_subflows%rowtype;',
'  begin',
'    apex_debug.enter',
'    ( ''start_step''',
'    , ''Subflow '', p_subflow_id',
'    , ''Process '', p_process_id ',
'    , ''Step Key'', p_step_key',
'    );',
'    -- subflow should already be locked when calling internally',
'    l_sbfl_rec := flow_engine_util.get_subflow_info ',
'                  ( p_process_id   => p_process_id',
'                  , p_subflow_id   => p_subflow_id',
'                  , p_lock_subflow => not p_called_internally',
'                  );',
'    -- check the step key',
'    if flow_engine_util.step_key_valid( pi_prcs_id  => p_process_id',
'                                      , pi_sbfl_id  => p_subflow_id',
'                                      , pi_step_key_supplied  => p_step_key',
'                                      , pi_step_key_required  => l_sbfl_rec.sbfl_step_key',
'                                      ) ',
'    then ',
'      -- set the pause time - requires the step to have already started work',
'      if l_sbfl_rec.sbfl_work_started is not null then',
'        -- log the pause',
'        flow_logging.log_step_event ',
'        ( p_sbfl_rec    => l_sbfl_rec',
'        , p_event       => flow_constants_pkg.gc_step_event_work_paused',
'        , p_event_level => flow_constants_pkg.gc_logging_level_routine',
'        );',
'        -- commit pause if this is an external call',
'        if not p_called_internally then ',
'          commit;',
'        end if;',
'      end if;',
'    end if;',
'  exception',
'    when no_data_found then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''startwork-sbfl-not-found''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );',
'      -- $F4AMESSAGE ''startwork-sbfl-not-found'' || ''Start Work time recording unsuccessful.  Subflow %0 in Process %1 not found.''  ',
'    when lock_timeout then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''timeout_locking_subflow''',
'      , p0 => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''        ',
'end pause_step;',
'',
'/*----------------------------------------------------------------------------',
'-- Name: restart_step',
'-- Description: Rather than starting the next step, restart starts the current step.',
'-- This is used:',
'--   - to restart a step that has errored',
'--   - for restarting a subflow from a specific step after a process resume',
'--   - in starting a subflow inside an adhoc subprocess, where there is no start event',
'--     and the first step is to be started directly.',
'--',
'-- Parameters:',
'--   p_process_id      - process id',
'--   p_subflow_id      - subflow id',
'--   p_step_key        - step key (optional)',
'--   p_comment         - comment to add to instance log (optional)',
'--   p_check_for_error - if true (default) then check that the subflow is in error status',
'--                      if false then assume caller has already done the check',
'------------------------------------------------------------------------------*/',
'',
'procedure restart_step',
'  ( p_process_id          in flow_processes.prcs_id%type',
'  , p_subflow_id          in flow_subflows.sbfl_id%type',
'  , p_step_key            in flow_subflows.sbfl_step_key%type default null',
'  , p_comment             in flow_instance_event_log.lgpr_comment%type default null',
'  , p_check_for_error     in boolean default true',
'  , p_is_adhoc_start      in boolean default false',
'  )',
'is ',
'  l_sbfl_rec            flow_subflows%rowtype;',
'  l_step_info           flow_types_pkg.flow_step_info;',
'  l_num_error_subflows  number;',
'begin ',
'  apex_debug.enter ',
'  ( ''flow_restart_step''',
'  , ''Process ID'',  p_process_id',
'  , ''Subflow ID'', p_subflow_id',
'  );',
'  flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'   -- reset step_had_error flag',
'  flow_globals.set_step_error ( p_has_error => false);',
'',
'  -- lock the process and subflow',
'  l_sbfl_rec := flow_engine_util.get_subflow_info ',
'                ( p_process_id => p_process_id',
'                , p_subflow_id => p_subflow_id',
'                , p_lock_process => not p_is_adhoc_start',
'                , p_lock_subflow => true',
'                );',
'',
'  if p_check_for_error then',
'    -- called externally to restart an errored step (legacy)',
'    -- i.e., not being called to restart a process from a specific step',
'    -- check subflow current task is in error status',
'    if l_sbfl_rec.sbfl_status <> flow_constants_pkg.gc_sbfl_status_error then ',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''restart-no-error''',
'        );',
'        -- $F4AMESSAGE ''restart-no-error'' || ''No Current Error Found.  Check your process diagram.''  ',
'    end if;',
'  end if;',
'  ',
'  if flow_engine_util.step_key_valid( pi_prcs_id  => p_process_id',
'                                    , pi_sbfl_id  => p_subflow_id',
'                                    , pi_step_key_supplied  => p_step_key',
'                                    , pi_step_key_required  => l_sbfl_rec.sbfl_step_key',
'                                    ) ',
'  then ',
'    -- valid step key was supplied',
'    -- set up step context',
'    l_step_info :=  get_step_info',
'                    ( p_sbfl_rec        => l_sbfl_rec',
'                    , p_is_restart      => true',
'                    );',
'    -- set subflow status to running',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )  ',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id      = p_subflow_id',
'    ;',
'    if not p_is_adhoc_start then',
'      -- log the restart (now a step level event)',
'      flow_logging.log_step_event ',
'      ( p_sbfl_rec    => l_sbfl_rec',
'      , p_event       => case p_check_for_error',
'                         when true then ',
'                           flow_constants_pkg.gc_step_event_error_restart',
'                         else ',
'                           flow_constants_pkg.gc_step_event_resumed',
'                         end',
'      , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'      );',
'  ',
'      -- see if instance can be reset to running - mark instance as altered anyhow',
'      flow_instances.reset_process_to_running',
'      ( p_subflow_rec => l_sbfl_rec',
'      , p_comment     => p_comment',
'      );',
'    end if;',
'',
'    if l_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_timer_event_definition ',
'    and l_sbfl_rec.sbfl_status = flow_constants_pkg.gc_sbfl_status_error  then',
'      -- restart object contains a timer and sbfl in error => timer step with an error - run var exps and step forward immediately',
'      -- note l_sbfl_rec is the subflow status when the call was made.    subflow has been updated subsequently...',
'      restart_failed_timer_step',
'      ( p_sbfl_rec => l_sbfl_rec',
'      , p_step_info => l_step_info',
'      );',
'    else',
'      -- all other object types, including a timer that is being startded as part of a resume.  restart current task',
'      dispatch_step',
'      ( p_sbfl_rec => l_sbfl_rec',
'      , p_step_info => l_step_info',
'      );',
'    end if;',
'  end if;  -- valid step key',
'',
'  -- commit or rollback based on errors',
'  if flow_globals.get_step_error then',
'    rollback;',
'  else',
'    commit;',
'  end if;',
'end restart_step;',
'',
'procedure start_async_step',
'  ( p_process_id          in flow_processes.prcs_id%type',
'  , p_subflow_id          in flow_subflows.sbfl_id%type',
'  , p_step_key            in flow_subflows.sbfl_step_key%type default null',
'  )',
'is',
'  l_sbfl_rec   flow_subflows%rowtype;',
'  l_step_info  flow_types_pkg.flow_step_info;',
'begin',
'  apex_debug.enter',
'  ( ''start_async_step''',
'  , ''Process ID'', p_process_id',
'  , ''Subflow ID'', p_subflow_id',
'  , ''Step Key'',   p_step_key',
'  );',
'',
'  flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'  flow_globals.set_step_error ( p_has_error => false);',
'',
'  l_sbfl_rec := flow_engine_util.get_subflow_info',
'                ( p_process_id   => p_process_id',
'                , p_subflow_id   => p_subflow_id',
'                , p_lock_process => true',
'                , p_lock_subflow => true',
'                );',
'',
'  if flow_engine_util.step_key_valid( pi_prcs_id         => p_process_id',
'                                    , pi_sbfl_id         => p_subflow_id',
'                                    , pi_step_key_supplied => p_step_key',
'                                    , pi_step_key_required => l_sbfl_rec.sbfl_step_key',
'                                    )',
'  then',
'    l_step_info := get_step_info',
'                   ( p_sbfl_rec   => l_sbfl_rec',
'                   , p_is_restart => true',
'                   );',
'',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'')',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id      = p_subflow_id;',
'',
'    l_sbfl_rec := flow_engine_util.get_subflow_info',
'                  ( p_process_id   => p_process_id',
'                  , p_subflow_id   => p_subflow_id',
'                  , p_lock_subflow => true',
'                  );',
'',
'    dispatch_step',
'    ( p_sbfl_rec  => l_sbfl_rec',
'    , p_step_info => l_step_info',
'    );',
'  end if;',
'',
'  if flow_globals.get_step_error then',
'    rollback;',
'  else',
'    commit;',
'  end if;',
'  end start_async_step;',
'',
'end flow_engine;',
'/',
'',
'create or replace package body flow_errors',
'as ',
'',
'  g_logging_language        flow_configuration.cfig_value%type;',
'',
'  procedure autonomous_write_to_instance_log',
'  ( pi_prcs_id        in flow_processes.prcs_id%type',
'  , pi_sbfl_id        in flow_subflows.sbfl_id%type default null',
'  , pi_objt_bpmn_id   in flow_subflows.sbfl_current%type default null',
'  , pi_message        in flow_instance_event_log.lgpr_comment%type',
'  , pi_error_info     in flow_instance_event_log.lgpr_error_info%type',
'  )',
'  is',
'    pragma autonomous_transaction;',
'  begin',
'    -- add to instance_event_log',
'    flow_logging.log_instance_event',
'    ( p_process_id        => pi_prcs_id',
'    , p_objt_bpmn_id      => pi_objt_bpmn_id',
'    , p_event             => flow_constants_pkg.gc_prcs_event_error',
'    , p_event_level       => flow_constants_pkg.gc_logging_level_abnormal_events',
'    , p_comment           => pi_message',
'    , p_error_info        => pi_error_info',
'    );',
'    --  commit the autonomous transaction',
'    commit;',
'  end autonomous_write_to_instance_log;',
'',
'  procedure set_error_status',
'  ( pi_prcs_id        in flow_processes.prcs_id%type',
'  , pi_sbfl_id        in flow_subflows.sbfl_id%type',
'  )',
'  is ',
'  begin  ',
'      apex_debug.enter',
'      ( ''set_error_status''',
'      , ''pi_prcs_id'', pi_prcs_id',
'      , ''pi_sbfl_id'', pi_sbfl_id',
'      );',
'      -- set sbfl & prcs error status',
'      update flow_subflows sbfl',
'        set sbfl_status              = flow_constants_pkg.gc_sbfl_status_error',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id = pi_sbfl_id',
'      ;',
'      update flow_processes prcs',
'        set prcs.prcs_status         = flow_constants_pkg.gc_prcs_status_error',
'          , prcs.prcs_last_update    = systimestamp',
'          , prcs.prcs_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )  ',
'      where prcs.prcs_id = pi_prcs_id',
'      ;   ',
'  end set_error_status;',
'',
'  function make_error_message',
'  ( pi_message_key    in flow_messages.fmsg_message_key%type ',
'  , pi_lang           in flow_messages.fmsg_lang%type',
'  , p0                in varchar2 default null',
'  , p1                in varchar2 default null',
'  , p2                in varchar2 default null',
'  , p3                in varchar2 default null',
'  , p4                in varchar2 default null',
'  , p5                in varchar2 default null',
'  , p6                in varchar2 default null',
'  , p7                in varchar2 default null',
'  , p8                in varchar2 default null',
'  , p9                in varchar2 default null',
'  ) return flow_messages.fmsg_message_content%type',
'  is',
'    l_message_content  flow_messages.fmsg_message_content%type;',
'    l_message          flow_instance_event_log.lgpr_comment%type;',
'  begin ',
'    -- get the message template in the correct language, or fall through to default language',
'    begin',
'      select fmsg.fmsg_message_content',
'        into l_message_content',
'        from flow_messages fmsg',
'       where fmsg.fmsg_message_key = pi_message_key',
'         and fmsg.fmsg_lang = pi_lang',
'      ;',
'    exception',
'      when no_data_found then',
'        begin',
'          select fmsg.fmsg_message_content',
'            into l_message_content',
'            from flow_messages fmsg',
'           where fmsg.fmsg_message_key = pi_message_key',
'             and fmsg.fmsg_lang = flow_constants_pkg.gc_config_default_logging_language',
'          ;',
'        exception',
'          when no_data_found then',
'            l_message_content := ''Missing Message Key ''||pi_message_key||'' language ''',
'                                 ||flow_constants_pkg.gc_config_default_logging_language;',
'          when others then',
'            l_message_content := ''Problem getting error message - check flow_messages loaded'';',
'        end;',
'      when others then',
'        l_message_content := ''Problem getting error message - check flow_messages loaded'';',
'    end;',
'    -- now make the error message in local language for log & apex_error',
'    l_message :=  apex_string.format',
'                  ( p_message => l_message_content',
'                  , p0 => p0',
'                  , p1 => p1',
'                  , p2 => p2',
'                  , p3 => p3',
'                  , p4 => p4',
'                  , p5 => p5',
'                  , p6 => p6',
'                  , p7 => p7',
'                  , p8 => p8',
'                  , p9 => p9',
'                  );',
'    return l_message;',
'  end make_error_message;',
'',
'  procedure handle_instance_error',
'  ( pi_prcs_id        in flow_processes.prcs_id%type',
'  , pi_sbfl_id        in flow_subflows.sbfl_id%type default null',
'  , pi_message_key    in varchar2',
'  , p0                in varchar2 default null',
'  , p1                in varchar2 default null',
'  , p2                in varchar2 default null',
'  , p3                in varchar2 default null',
'  , p4                in varchar2 default null',
'  , p5                in varchar2 default null',
'  , p6                in varchar2 default null',
'  , p7                in varchar2 default null',
'  , p8                in varchar2 default null',
'  , p9                in varchar2 default null',
'  )',
'  is',
'    l_message_content  flow_messages.fmsg_message_content%type;',
'    l_message          flow_instance_event_log.lgpr_comment%type;',
'    l_error_info       flow_instance_event_log.lgpr_error_info%type;',
'    l_current          flow_subflows.sbfl_current%type;',
'  begin ',
'    apex_debug.enter',
'    ( ''handle_instance_error''',
'    , ''pi_sbfl_id'', pi_sbfl_id',
'    , ''pi_message_key'', pi_message_key',
'    , ''p0'', p0',
'    , ''p1'', p1',
'    , ''p2'', p2',
'    , ''p3'', p3',
'    , ''p4'', p4',
'    , ''is_recursive'' , case when flow_globals.get_is_recursive_step then ''true'' else ''false'' end',
'    );',
'    -- get the message template in the correct language, or fall through to default language',
'    -- for log & apex_error',
'    l_message :=  make_error_message',
'                  ( pi_message_key   => pi_message_key',
'                  , pi_lang          => g_logging_language',
'                  , p0               => p0',
'                  , p1               => p1',
'                  , p2               => p2',
'                  , p3               => p3',
'                  , p4               => p4',
'                  , p5               => p5',
'                  , p6               => p6',
'                  , p7               => p7',
'                  , p8               => p8',
'                  , p9               => p9',
'                  );',
'    -- get the error stack and step type',
'    l_error_info   := dbms_utility.format_error_stack;',
'    -- get the current step, if known & available',
'    begin',
'      if pi_sbfl_id is not null then',
'        select sbfl.sbfl_current',
'          into l_current',
'          from flow_subflows sbfl',
'        where sbfl.sbfl_id = pi_sbfl_id',
'        ;',
'      else',
'        l_current := null;',
'      end if;',
'    exception',
'      when others then',
'        l_current := null;',
'    end; ',
'    -- add to instance_event_log',
'    autonomous_write_to_instance_log',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => l_current',
'    , pi_message        => l_message',
'    , pi_error_info     => l_error_info',
'    );',
'    -- decide where to put error message',
'    if flow_globals.get_is_recursive_step then',
'      -- errors written to log, status already set to error in autonomous session',
'      flow_globals.set_step_error (p_has_error => true);',
'    elsif flow_globals.rest_call then',
'      raise_application_error(-20001, l_message);',
'    else',
'      -- step belongs to current user''s current session - use apex_error',
'      apex_error.add_error',
'      ( p_message => l_message',
'      , p_display_location => apex_error.c_on_error_page',
'      );',
'    end if;',
'  end handle_instance_error;',
'',
'  procedure handle_general_error',
'  ( pi_message_key    in varchar2',
'  , p0                in varchar2 default null',
'  , p1                in varchar2 default null',
'  , p2                in varchar2 default null',
'  , p3                in varchar2 default null',
'  , p4                in varchar2 default null',
'  , p5                in varchar2 default null',
'  , p6                in varchar2 default null',
'  , p7                in varchar2 default null',
'  , p8                in varchar2 default null',
'  , p9                in varchar2 default null',
'  )',
'  is',
'    l_message_content  flow_messages.fmsg_message_content%type;',
'    l_message          flow_instance_event_log.lgpr_comment%type;',
'  begin ',
'    apex_debug.enter',
'    ( ''handle_instance_error''',
'    , ''pi_message_key'', pi_message_key',
'    );',
'    -- get the message template in the correct language, or fall through to default language',
'    -- for log & apex_error',
'    l_message :=  make_error_message',
'                  ( pi_message_key   => pi_message_key',
'                  , pi_lang          => g_logging_language',
'                  , p0               => p0',
'                  , p1               => p1',
'                  , p2               => p2',
'                  , p3               => p3',
'                  , p4               => p4',
'                  , p5               => p5',
'                  , p6               => p6',
'                  , p7               => p7',
'                  , p8               => p8',
'                  , p9               => p9',
'                  );',
'',
'    if flow_globals.rest_call then',
'      raise_application_error(-20001, l_message);',
'    else',
'      apex_error.add_error',
'        ( p_message => l_message',
'        , p_display_location => apex_error.c_on_error_page',
'        );',
'    end if;',
'  end handle_general_error;',
'',
'  -- initialize logging parameters',
'',
'  begin ',
'    g_logging_language := flow_engine_util.get_config_value',
'                       ( p_config_key => flow_constants_pkg.gc_config_logging_language',
'                       , p_default_value => flow_constants_pkg.gc_config_default_logging_language',
'                       );',
'',
'end flow_errors;',
'/',
'',
'create or replace package body flow_expressions',
'as ',
'  /* ',
'  -- Flows for APEX - flow_expressions.pkb',
'  -- ',
'  -- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'  -- (c) Copyright MT AG, 2021-2022.',
'  -- (c) Copyright Flowquest Limited and / or affiliates. 2021-2025.',
'  --',
'  -- Created    22-Mar-2021  Richard Allen (Flowquest, for MT AG)',
'  -- Modified   12-Apr-2022  Richard Allen (Oracle)',
'  -- Modified   11-Feb-2024  Richard Allen (Flowquest)',
'  --',
'  */  ',
'  type t_expr_rec is record',
'  ( expr_id             flow_object_expressions.expr_id%type',
'  , expr_objt_id        flow_object_expressions.expr_objt_id%type',
'  , expr_set            flow_object_expressions.expr_set%type',
'  , expr_order          flow_object_expressions.expr_order%type',
'  , expr_var_name       flow_object_expressions.expr_var_name%type',
'  , expr_var_type       flow_object_expressions.expr_var_type%type',
'  , expr_type           flow_object_expressions.expr_type%type',
'  , expr_expression     flow_object_expressions.expr_expression%type',
'  , expr_source_type    flow_object_expressions.expr_source_type%type',
'  , expr_source         flow_object_expressions.expr_source%type',
'  , expr_objt_bpmn_id   flow_objects.objt_bpmn_id%type',
'  );',
'',
'  type t_expr_set is table of t_expr_rec;',
'',
'  function get_expression_set',
'  ( pi_objt_id      flow_objects.objt_id%type',
'  , pi_set          flow_object_expressions.expr_set%type',
'  ) return t_expr_set',
'  as',
'    l_expressions   t_expr_set;',
'  begin',
'    select expr.expr_id',
'         , expr.expr_objt_id',
'         , expr.expr_set',
'         , expr.expr_order',
'         , expr.expr_var_name',
'         , expr.expr_var_type',
'         , expr.expr_type',
'         , expr.expr_expression',
'          , expr.expr_source_type',
'          , expr.expr_source',
'         , objt.objt_bpmn_id as expr_objt_bpmn_id',
'    bulk collect into l_expressions',
'      from flow_object_expressions expr',
'      join flow_objects objt',
'        on objt.objt_id = expr.expr_objt_id',
'     where expr.expr_objt_id = pi_objt_id',
'       and expr.expr_set = pi_set',
'     order by expr.expr_order asc',
'    ;',
'    return l_expressions;',
'  end get_expression_set;',
'',
'  /**********************************************************************',
'  **',
'  ** Process various expression types',
'  **',
'  ***********************************************************************',
'  */',
'',
'  procedure set_static',
'  ( pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_step_key     flow_subflows.sbfl_step_key%type',
'  , pi_expression   t_expr_rec',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type  ',
'  )',
'  as ',
'    l_expression_text   flow_object_expressions.expr_expression%type;',
'    l_result_rec        flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_expressions.set_static''',
'    , ''expr_var_name'', pi_expression.expr_var_name',
'    , ''pi_expression.expr_var_type'', pi_expression.expr_var_type',
'    , ''pi_expression.expr_expression'' , pi_expression.expr_expression',
'    );',
'',
'    l_expression_text := pi_expression.expr_expression;',
'    -- substitute any F4A Process Variables',
'    flow_proc_vars_int.do_substitution',
'    ( pi_prcs_id => pi_prcs_id',
'    , pi_sbfl_id => pi_sbfl_id',
'    , pi_scope   => pi_expr_scope',
'    , pi_step_key => pi_step_key',
'    , pio_string => l_expression_text',
'    );',
'',
'    l_result_rec.var_name := pi_expression.expr_var_name;',
'    l_result_rec.var_type := pi_expression.expr_var_type;',
'    ',
'    case pi_expression.expr_var_type ',
'    when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'        l_result_rec.var_vc2   := l_expression_text;',
'    when flow_constants_pkg.gc_prov_var_type_number then',
'        l_result_rec.var_num   := l_expression_text;',
'    when flow_constants_pkg.gc_prov_var_type_date then',
'        -- test date is in our required format',
'        begin',
'          if l_expression_text != to_char  ( to_date ( l_expression_text',
'                                                    , flow_constants_pkg.gc_prov_default_date_format )',
'                                          , flow_constants_pkg.gc_prov_default_date_format ) then ',
'          raise e_var_exp_date_format_error;',
'          end if;',
'        exception',
'          when others then',
'            raise e_var_exp_date_format_error;',
'        end;',
'        l_result_rec.var_date   := to_date(l_expression_text, flow_constants_pkg.gc_prov_default_date_format);',
'    when flow_constants_pkg.gc_prov_var_type_tstz then',
'        -- test timestamp is in our required format',
'        begin',
'          if l_expression_text != to_char ( to_timestamp_tz ( l_expression_text',
'                                          , flow_constants_pkg.gc_prov_default_tstz_format )',
'                                          , flow_constants_pkg.gc_prov_default_tstz_format ) then ',
'            raise e_var_exp_date_format_error;',
'          end if;',
'        exception',
'          when others then',
'            raise e_var_exp_date_format_error;',
'        end;',
'        l_result_rec.var_tstz := to_timestamp_tz(l_expression_text, flow_constants_pkg.gc_prov_default_tstz_format);',
'    when flow_constants_pkg.gc_prov_var_type_json then',
'        -- test is correct json (lax)',
'        begin',
'          if l_expression_text is not json then',
'            raise e_var_exp_json_format_error;',
'          end if;',
'        exception',
'          when others then',
'            raise e_var_exp_json_format_error;',
'        end;',
'        l_result_rec.var_json := l_expression_text;',
'    end case;',
'    -- set proc variable',
'    flow_proc_vars_int.set_var ',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_var_value      => l_result_rec',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => pi_expression.expr_objt_bpmn_id',
'    , pi_expr_set       => pi_expression.expr_set    ',
'    , pi_scope          => pi_var_scope',
'    );',
'  exception',
'    when e_var_exp_date_format_error then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_date_format''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_date_format'' || ''Error setting Process Variable %1: Incorrect Date Format (Subflow: %0, Set: %3.)''   ',
'    when e_var_exp_json_format_error then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_json_format''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_json_format'' || ''Error setting Process Variable %1: Incorrect JSON Format (Subflow: %0, Set: %3.)''     ',
'    when others then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_static_general''',
'      , p0 => pi_prcs_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_static_general'' || ''Error setting process variable %1 in process id %0 (set %2).  See error in event log.''',
'  end set_static;',
'',
'  procedure set_proc_var',
'  ( pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_expression   t_expr_rec',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type',
'  )',
'  as ',
'    l_result_rec        flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_expressions.set_proc_var''',
'    , ''expr_var_name'', pi_expression.expr_var_name',
'    , ''proc var'' , pi_expression.expr_expression',
'    );',
'',
'    l_result_rec.var_name := pi_expression.expr_var_name;',
'    l_result_rec.var_type := pi_expression.expr_var_type;',
'',
'    case pi_expression.expr_var_type ',
'    when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'        l_result_rec.var_vc2 :=   flow_proc_vars_int.get_var_vc2 ',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope',
'                                    );    ',
'    when flow_constants_pkg.gc_prov_var_type_date then',
'        l_result_rec.var_date  := flow_proc_vars_int.get_var_date ',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope',
'                                    );  ',
'    when flow_constants_pkg.gc_prov_var_type_number then',
'        l_result_rec.var_num   := flow_proc_vars_int.get_var_num',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope                             ',
'                                    );   ',
'    when flow_constants_pkg.gc_prov_var_type_clob then',
'        l_result_rec.var_clob  := flow_proc_vars_int.get_var_clob ',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope',
'                                    );',
'    when flow_constants_pkg.gc_prov_var_type_tstz then',
'        l_result_rec.var_tstz :=  flow_proc_vars_int.get_var_tstz',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope',
'                                    );  ',
'    when flow_constants_pkg.gc_prov_var_type_json then',
'        l_result_rec.var_json  := flow_proc_vars_int.get_var_json ',
'                                    ( pi_prcs_id  => pi_prcs_id',
'                                    , pi_var_name => pi_expression.expr_expression',
'                                    , pi_scope    => pi_expr_scope',
'                                    );',
'    end case; ',
'    -- set proc variable',
'    flow_proc_vars_int.set_var ',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_var_value      => l_result_rec',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => pi_expression.expr_objt_bpmn_id',
'    , pi_expr_set       => pi_expression.expr_set    ',
'    , pi_scope          => pi_var_scope',
'    );',
'  exception',
'    when others then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_static_general''',
'      , p0 => pi_prcs_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_static_general'' || ''Error setting process variable %1 in process id %0 (set %2).  See error in event log.''      ',
'  end set_proc_var;',
'',
'  procedure set_sql',
'  ( pi_prcs_id        flow_processes.prcs_id%type',
'  , pi_expression     t_expr_rec',
'  , pi_sbfl_id        flow_subflows.sbfl_id%type',
'  , pi_step_key       flow_subflows.sbfl_step_key%type',
'  , pi_var_scope      flow_subflows.sbfl_scope%type',
'  , pi_expr_scope     flow_subflows.sbfl_scope%type',
'  ) ',
'  as  ',
'    l_result_rec      flow_proc_vars_int.t_proc_var_value;',
'  begin',
'      apex_debug.enter',
'    ( ''flow_expressions.set_sql''',
'    , ''expr_var_name'', pi_expression.expr_var_name',
'    , ''sql text'' , pi_expression.expr_expression',
'    );',
'',
'    l_result_rec := flow_db_exec.exec_flows_sql',
'                    ( pi_prcs_id      => pi_prcs_id',
'                    , pi_sbfl_id      => pi_sbfl_id',
'                    , pi_sql_text     => pi_expression.expr_expression',
'                    , pi_result_type  => pi_expression.expr_var_type',
'                    , pi_scope        => pi_expr_scope',
'                    , pi_step_key     => pi_step_key',
'                    , pi_expr_type    => pi_expression.expr_type',
'                    );',
'',
'    l_result_rec.var_name   := pi_expression.expr_var_name;',
'',
'    flow_proc_vars_int.set_var ',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_var_value      => l_result_rec',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => pi_expression.expr_objt_bpmn_id',
'    , pi_expr_set       => pi_expression.expr_set',
'    , pi_scope          => pi_var_scope',
'    );',
'',
'  exception',
'    when others then',
'      apex_debug.error',
'      ( p_message => ''Error setting process variable %0 for process id %1. SQLERRM: %2''',
'      , p0        => pi_expression.expr_var_name',
'      , p1        => pi_prcs_id',
'      , p2        => sqlerrm',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_sql_other''',
'      , p0 => pi_prcs_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_sql_other'' || ''Error setting process variable %1 in process id %0 (set %2).  SQL error shown in event log.''    ',
'  end set_sql;',
'',
'  procedure set_plsql         ',
'  ( pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_expression   t_expr_rec',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_step_key     flow_subflows.sbfl_step_key%type',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type',
'  )',
'  as ',
'    l_result_rec                flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_expressions.set_plsql''',
'    , ''expr_var_name'', pi_expression.expr_var_name',
'    , ''plsql text'' , pi_expression.expr_expression',
'    );',
'',
'    l_result_rec := flow_db_exec.exec_flows_plsql',
'                    ( pi_prcs_id      => pi_prcs_id',
'                    , pi_sbfl_id      => pi_sbfl_id',
'                    , pi_plsql_text   => pi_expression.expr_expression',
'                    , pi_result_type  => pi_expression.expr_var_type',
'                    , pi_scope        => pi_expr_scope',
'                    , pi_step_key     => pi_step_key',
'                    , pi_expr_type   => pi_expression.expr_type',
'                    );',
'    l_result_rec.var_name   := pi_expression.expr_var_name;',
'',
'    -- set proc variable',
'    flow_proc_vars_int.set_var ',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_var_value      => l_result_rec',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => pi_expression.expr_objt_bpmn_id',
'    , pi_expr_set       => pi_expression.expr_set    ',
'    , pi_scope          => pi_var_scope',
'    );',
'',
'  exception',
'    when others then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_plsql_error''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_plsql_error'' || ''Subflow : %0 Error in %2 expression for Variable : %1''',
'  end set_plsql;  ',
'',
'  procedure set_json_path',
'  ( pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_expression   t_expr_rec',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_step_key     flow_subflows.sbfl_step_key%type',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type',
'  )',
'  as',
'    l_result_rec        flow_proc_vars_int.t_proc_var_value;',
'    l_source_json       clob;',
'    l_source_type       varchar2(50 char);',
'    l_source_name       varchar2(50 char);',
'    l_path              varchar2(4000 char);',
'    l_json_fragment     clob;',
'    l_scalar_text       varchar2(32767);',
'    l_json_scalar       clob;',
'    l_has_value         boolean := false;',
'  begin',
'    apex_debug.enter',
'    ( ''flow_expressions.set_json_path''',
'    , ''expr_var_name'', pi_expression.expr_var_name',
'    , ''expr_var_type'', pi_expression.expr_var_type',
'    , ''expr_path'', pi_expression.expr_expression',
'    , ''expr_source_type'', pi_expression.expr_source_type',
'    , ''expr_source'', pi_expression.expr_source',
'    );',
'',
'    l_result_rec.var_name := pi_expression.expr_var_name;',
'    l_result_rec.var_type := pi_expression.expr_var_type;',
'',
'    l_source_type := lower(pi_expression.expr_source_type);',
'    l_source_name := pi_expression.expr_source;',
'    l_path := pi_expression.expr_expression;',
'',
'    if l_source_type is null then',
'      l_source_type := ''processvariable'';',
'    end if;',
'',
'    case l_source_type',
'      when ''processvariable'' then',
'        if l_source_name is null then',
'          apex_debug.warn(''JSONPath expression missing source variable name.'');',
'        else',
'          l_source_json := flow_proc_vars_int.get_var_json',
'                           ( pi_prcs_id  => pi_prcs_id',
'                           , pi_var_name => l_source_name',
'                           , pi_scope    => pi_expr_scope',
'                           );',
'          if l_source_json is null then',
'            l_source_json := flow_proc_vars_int.get_var_clob',
'                             ( pi_prcs_id  => pi_prcs_id',
'                             , pi_var_name => l_source_name',
'                             , pi_scope    => pi_expr_scope',
'                             );',
'          end if;',
'        end if;',
'',
'      when ''taskoutput'' then',
'        if pi_expression.expr_set not in ( flow_constants_pkg.gc_expr_set_after_task',
'                                         , flow_constants_pkg.gc_expr_set_on_event ) then',
'          apex_debug.warn(''taskOutput source used outside afterTask/onEvent expression set.'');',
'        else',
'          select sbfl_task_output_parameters',
'            into l_source_json',
'            from flow_subflows',
'           where sbfl_id = pi_sbfl_id;',
'        end if;',
'',
'      when ''taskinput'' then',
'        if pi_expression.expr_set != flow_constants_pkg.gc_expr_set_after_task then',
'          apex_debug.warn(''taskInput source used outside afterTask expression set.'');',
'        else',
'          select sbfl_task_input_parameters',
'            into l_source_json',
'            from flow_subflows',
'           where sbfl_id = pi_sbfl_id;',
'        end if;',
'',
'      else',
'        apex_debug.warn(''Unsupported JSONPath source type: '' || pi_expression.expr_source_type);',
'    end case;',
'',
'    if l_source_json is null or l_source_json is not json then',
'      apex_debug.warn(''JSONPath source is null or not JSON for variable %0.'', pi_expression.expr_var_name);',
'    else',
'      if pi_expression.expr_var_type = flow_constants_pkg.gc_prov_var_type_json then',
'        begin',
'          l_json_fragment := json_query(l_source_json, l_path returning clob);',
'        exception',
'          when others then',
'            apex_debug.error(',
'              p_message => ''JSONPath error for path %0: %1''',
'            , p0 => l_path',
'            , p1 => sqlerrm',
'            );',
'            raise e_var_exp_jsonpath_error;',
'        end;',
'',
'        if l_json_fragment is not null then',
'          l_has_value := true;',
'          if pi_expression.expr_var_type = flow_constants_pkg.gc_prov_var_type_json then',
'            l_result_rec.var_json := l_json_fragment;',
'          else',
'            l_result_rec.var_clob := l_json_fragment;',
'          end if;',
'        end if;',
'      end if;',
'',
'      if not l_has_value then',
'        case pi_expression.expr_var_type',
'          when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'            l_scalar_text := json_value(l_source_json, l_path returning varchar2);',
'            l_result_rec.var_vc2 := l_scalar_text;',
'            l_has_value := (l_scalar_text is not null);',
'          when flow_constants_pkg.gc_prov_var_type_number then',
'            l_result_rec.var_num := json_value(l_source_json, l_path returning number);',
'            l_has_value := (l_result_rec.var_num is not null);',
'          when flow_constants_pkg.gc_prov_var_type_date then',
'            l_scalar_text := json_value(l_source_json, l_path returning varchar2);',
'            if l_scalar_text is not null then',
'              begin',
'                if l_scalar_text != to_char( to_date( l_scalar_text, flow_constants_pkg.gc_prov_default_date_format )',
'                                           , flow_constants_pkg.gc_prov_default_date_format ) then',
'                  raise e_var_exp_date_format_error;',
'                end if;',
'              exception',
'                when others then',
'                  raise e_var_exp_date_format_error;',
'              end;',
'              l_result_rec.var_date := to_date(l_scalar_text, flow_constants_pkg.gc_prov_default_date_format);',
'              l_has_value := true;',
'            end if;',
'          when flow_constants_pkg.gc_prov_var_type_tstz then',
'            l_scalar_text := json_value(l_source_json, l_path returning varchar2);',
'            if l_scalar_text is not null then',
'              begin',
'                if l_scalar_text != to_char( to_timestamp_tz( l_scalar_text, flow_constants_pkg.gc_prov_default_tstz_format )',
'                                           , flow_constants_pkg.gc_prov_default_tstz_format ) then',
'                  raise e_var_exp_date_format_error;',
'                end if;',
'              exception',
'                when others then',
'                  raise e_var_exp_date_format_error;',
'              end;',
'              l_result_rec.var_tstz := to_timestamp_tz(l_scalar_text, flow_constants_pkg.gc_prov_default_tstz_format);',
'              apex_debug.message (''Parsed timestamp with timezone: %0'', l_result_rec.var_tstz);',
'              l_has_value := true;',
'            end if;',
'          when flow_constants_pkg.gc_prov_var_type_clob then',
'            l_scalar_text := json_value(l_source_json, l_path returning varchar2(32767));',
'            if l_scalar_text is not null then',
'              l_result_rec.var_clob := to_clob(l_scalar_text);',
'              l_has_value := true;',
'            else',
'              l_result_rec.var_clob := json_query(l_source_json, l_path returning clob);',
'              l_has_value := (l_result_rec.var_clob is not null);',
'            end if;',
'        end case;',
'      end if;',
'    end if;',
'',
'    if not l_has_value then',
'      apex_debug.warn(''JSONPath expression returned null for variable %0.'', pi_expression.expr_var_name);',
'    end if;',
'',
'    flow_proc_vars_int.set_var',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_var_value      => l_result_rec',
'    , pi_sbfl_id        => pi_sbfl_id',
'    , pi_objt_bpmn_id   => pi_expression.expr_objt_bpmn_id',
'    , pi_expr_set       => pi_expression.expr_set',
'    , pi_scope          => pi_var_scope',
'    );',
'',
'  exception',
'    when e_var_exp_date_format_error then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_date_format''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'    when e_var_exp_json_format_error then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_json_format''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_json_format'' || ''Error setting Process Variable %1: Incorrect JSON Format (Subflow: %0, Set: %3.)''',
'    when e_var_exp_jsonpath_error then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_jsonpath_error''',
'      , p0 => pi_sbfl_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_expression',
'      , p3 => pi_expression.expr_set',
'      );',
'      -- $F4AMESSAGE ''var_exp_jsonpath_error'' || ''Error setting Process Variable %1: Invalid JSONPath expression "%2" (Subflow: %0, Set: %3).''',
'    when others then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_static_general''',
'      , p0 => pi_prcs_id',
'      , p1 => pi_expression.expr_var_name',
'      , p2 => pi_expression.expr_set',
'      );',
'  end set_json_path;',
'',
'  /**********************************************************************',
'  **',
'  ** Main Procedure',
'  **',
'  ***********************************************************************',
'  */',
'',
'  procedure process_expressions',
'  ( pi_objt_id      flow_objects.objt_id%type',
'  , pi_set          flow_object_expressions.expr_set%type',
'  , pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_step_key     flow_subflows.sbfl_step_key%type',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type',
'  )',
'  as',
'    l_expressions   t_expr_set;',
'  begin',
'    apex_debug.enter',
'    ( ''process_expressions''',
'    , ''pi_objt_id'', pi_objt_id',
'    , ''pi_set'' , pi_set',
'    , ''pi_var_scope'' , pi_var_scope',
'    , ''pi_expr_scope'', pi_expr_scope',
'    );',
'',
'    l_expressions := get_expression_set',
'    ( pi_objt_id => pi_objt_id',
'    , pi_set     => pi_set',
'    );',
'    if l_expressions.count > 0 then ',
'      -- set context',
'      flow_globals.set_context',
'      ( pi_prcs_id      => pi_prcs_id',
'      , pi_sbfl_id      => pi_sbfl_id',
'      , pi_scope        => pi_expr_scope',
'      , pi_step_key     => pi_step_key',
'      , pi_loop_counter => flow_engine_util.get_loop_counter(pi_sbfl_id => pi_sbfl_id)',
'      );',
'      apex_debug.trace ',
'      ( p_message => ''l_expressions.count: %0''',
'      , p0        => l_expressions.count',
'      );',
'      -- step through expressions',
'      for i in 1..l_expressions.count loop',
'        -- process expression',
'        case ',
'          when l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_static then',
'            set_static ',
'            ( pi_prcs_id      => pi_prcs_id',
'            , pi_sbfl_id      => pi_sbfl_id',
'            , pi_expression   => l_expressions(i)',
'            , pi_var_scope    => pi_var_scope',
'            , pi_step_key     => pi_step_key',
'            , pi_expr_scope   => pi_expr_scope ',
'            );',
'          when l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_proc_var then',
'            set_proc_var',
'            ( pi_prcs_id      => pi_prcs_id',
'            , pi_sbfl_id      => pi_sbfl_id',
'            , pi_expression   => l_expressions(i)',
'            , pi_var_scope    => pi_var_scope',
'            , pi_expr_scope   => pi_expr_scope ',
'            );',
'          when l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_sql  ',
'            or l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_sql_delimited_list',
'            or l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_sql_json_array',
'          then',
'            set_sql',
'            ( pi_prcs_id      => pi_prcs_id',
'            , pi_expression   => l_expressions(i)',
'            , pi_sbfl_id      => pi_sbfl_id',
'            , pi_step_key     => pi_step_key',
'            , pi_var_scope    => pi_var_scope',
'            , pi_expr_scope   => pi_expr_scope             ',
'            );  ',
'          when l_expressions(i).expr_type in ( flow_constants_pkg.gc_expr_type_plsql_expression',
'                                             , flow_constants_pkg.gc_expr_type_plsql_raw_expression',
'                                             , flow_constants_pkg.gc_expr_type_plsql_function_body',
'                                             , flow_constants_pkg.gc_expr_type_plsql_raw_function_body )',
'          then',
'            set_plsql',
'            ( pi_prcs_id      => pi_prcs_id',
'            , pi_expression   => l_expressions(i)',
'            , pi_sbfl_id      => pi_sbfl_id',
'            , pi_step_key     => pi_step_key',
'            , pi_var_scope    => pi_var_scope',
'            , pi_expr_scope   => pi_expr_scope             ',
'            );  ',
'          when l_expressions(i).expr_type = flow_constants_pkg.gc_expr_type_json_path then',
'            set_json_path',
'            ( pi_prcs_id      => pi_prcs_id',
'            , pi_expression   => l_expressions(i)',
'            , pi_sbfl_id      => pi_sbfl_id',
'            , pi_step_key     => pi_step_key',
'            , pi_var_scope    => pi_var_scope',
'            , pi_expr_scope   => pi_expr_scope',
'            );',
'          else',
'              pragma coverage (''not_feasible'');',
'              null;',
'        end case;',
'      end loop;',
'    end if;',
'  end process_expressions;',
'',
'  -- overloaded process_expressions that accepts a objt_bpmn_id rather than an objt_id',
'  procedure process_expressions',
'  ( pi_objt_bpmn_id flow_objects.objt_bpmn_id%type',
'  , pi_set          flow_object_expressions.expr_set%type',
'  , pi_prcs_id      flow_processes.prcs_id%type',
'  , pi_sbfl_id      flow_subflows.sbfl_id%type',
'  , pi_step_key     flow_subflows.sbfl_step_key%type',
'  , pi_var_scope    flow_subflows.sbfl_scope%type',
'  , pi_expr_scope   flow_subflows.sbfl_scope%type',
'  )',
'  is ',
'    l_objt_id       flow_objects.objt_id%type;',
'  begin ',
'    apex_debug.enter',
'    ( ''process_expressions''',
'    , ''pi_objt_bpmn_id'', pi_objt_bpmn_id',
'    , ''pi_set'' , pi_set',
'    , ''pi_var_scope'' , pi_var_scope',
'    , ''pi_expr_scope'', pi_expr_scope',
'    );',
'    -- look up the objt_id',
'    select objt.objt_id',
'      into l_objt_id',
'      from flow_objects objt',
'      join flow_subflows sbfl ',
'        on sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'     where sbfl.sbfl_id = pi_sbfl_id ',
'       and objt.objt_bpmn_id = pi_objt_bpmn_id',
'    ;',
'    process_expressions',
'    ( pi_objt_id      => l_objt_id',
'    , pi_set          => pi_set',
'    , pi_prcs_id      => pi_prcs_id',
'    , pi_sbfl_id      => pi_sbfl_id',
'    , pi_step_key     => pi_step_key',
'    , pi_var_scope    => pi_var_scope',
'    , pi_expr_scope   => pi_expr_scope ',
'    );',
'  exception',
'    when no_data_found then',
'      pragma coverage (''not_feasible'');',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''var_exp_object_not_found''',
'      , p0 => pi_objt_bpmn_id',
'      );',
'      -- $F4AMESSAGE ''var_exp_object_not_found'' || ''Internal error looking up object %0 in process_expressions.  SQL error shown in debug output.''  ',
'  end process_expressions; ',
'  ',
'end flow_expressions;',
'/',
'',
'create or replace package body flow_gateways',
'as ',
'/* ',
'-- Flows for APEX - flow_gateways.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Consulting Limited. 2021-2025',
'--',
'-- Created    06-May-2021  Richard Allen (Flowquest, for MT AG)',
'-- Modified   12-Apr-2022  Richard Allen (Oracle)',
'-- Modified   2022-07-18   Moritz Klein (MT AG)',
'-- Modified   09-Jan-2024  Richard Allen, Flowquest Consulting',
'--',
'*/',
'  type t_new_sbfls is table of flow_types_pkg.t_subflow_context;',
'',
'  e_no_route_found          exception;',
'  e_bad_routing_expression  exception;',
'  lock_timeout              exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  procedure get_nearest_previous_opening_parincl_gateway',
'  ( pi_sbfl_rec                in  flow_subflows%rowtype',
'  , po_nearest_gateway_bpmn_id out flow_objects.objt_bpmn_id%type',
'  , po_nearest_gateway_type    out flow_objects.objt_tag_name%type',
'  , po_nearest_gateway_name    out flow_objects.objt_name%type',
'  , po_num_steps               out integer',
'  )',
'  is',
'    l_gateway_bpmn_id   flow_objects.objt_bpmn_id%type;',
'    l_current_object    flow_objects.objt_bpmn_id%type;',
'    l_gateway_type      flow_objects.objt_tag_name%type;',
'    l_gateway_name      flow_objects.objt_name%type;',
'    l_num_steps         integer;',
'  begin',
'    apex_debug.enter',
'    ( ''get_nearest_previous_opening_parincl_gateway''',
'    , ''pi_sbfl_rec.sbfl_current'' , pi_sbfl_rec.sbfl_current',
'    );',
'    begin',
'       -- get nearest previous opening parallel or inclusve gateway',
'       with candidate_gateways as    ',
'        ( select distinct prev_obj.objt_bpmn_id ',
'               , prev_obj.objt_tag_name',
'               , coalesce( prev_obj.objt_name, prev_obj.objt_bpmn_id) objt_name',
'               , prev_obj.objt_id',
'               , prev_obj.objt_dgrm_id',
'               , level as num_steps',
'            from flow_objects prev_obj',
'            join flow_connections conn',
'              on conn.conn_src_objt_id = prev_obj.objt_id',
'             and conn.conn_dgrm_id     = prev_obj.objt_dgrm_id',
'             and conn.conn_tag_name    = flow_constants_pkg.gc_bpmn_sequence_flow',
'            join flow_objects curr_obj',
'              on conn.conn_tgt_objt_id = curr_obj.objt_id',
'             and conn.conn_dgrm_id     = curr_obj.objt_dgrm_id',
'             and conn.conn_tag_name    = flow_constants_pkg.gc_bpmn_sequence_flow',
'           where curr_obj.objt_dgrm_id = pi_sbfl_rec.sbfl_dgrm_id',
'             and prev_obj.objt_tag_name in (''bpmn:inclusiveGateway'',''bpmn:parallelGateway'')',
'           start with curr_obj.objt_bpmn_id = pi_sbfl_rec.sbfl_current',
'          connect by  curr_obj.objt_tag_name not in (''bpmn:inclusiveGateway'',''bpmn:parallelGateway'', ''bpmn:startEvent'', ''bpmn:boundaryEvent'')',
'                  and curr_obj.objt_id = prior prev_obj.objt_id',
'          order by level ',
'        )',
'     select candidate_gateways.objt_bpmn_id',
'          , candidate_gateways.objt_tag_name',
'          , candidate_gateways.objt_name',
'          , candidate_gateways.num_steps',
'       into l_gateway_bpmn_id',
'          , l_gateway_type',
'          , l_gateway_name',
'          , l_num_steps',
'      from candidate_gateways',
'      where ( select count (back_links.conn_id)',
'                from flow_connections back_links',
'               where back_links.conn_tgt_objt_id = candidate_gateways.objt_id',
'                 and back_links.conn_tag_name    = flow_constants_pkg.gc_bpmn_sequence_flow',
'                 and back_links.conn_dgrm_id     = candidate_gateways.objt_dgrm_id',
'            ) = 1',
'        ;',
'    exception',
'      when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id      => pi_sbfl_rec.sbfl_prcs_id',
'        , pi_message_key  => ''gateway-no-previous-gw''',
'        );',
'        -- $F4AMESSAGE ''gateway-no-previous-gw'' || ''No previous opening parallel or inclusive gateway found for subflow %0.''',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id      => pi_sbfl_rec.sbfl_prcs_id',
'        , pi_message_key  => ''gateway-multiple-previous-gws''',
'        );',
'        -- $F4AMESSAGE ''gateway-multiple-previous-gws'' || ''Multiple previous opening parallel or inclusive gateways found for subflow %0.''',
'    end;',
'    apex_debug.message ( ''Nearest previous opening parallel or inclusive gateway: %0 %1 %2 %3''',
'                       , l_gateway_bpmn_id',
'                       , l_gateway_type',
'                       , l_gateway_name',
'                       , l_num_steps',
'                       );',
'    po_nearest_gateway_bpmn_id := l_gateway_bpmn_id;',
'    po_nearest_gateway_type    := l_gateway_type;',
'    po_nearest_gateway_name    := l_gateway_name;  ',
'    po_num_steps               := l_num_steps;  ',
'  end get_nearest_previous_opening_parincl_gateway;',
'',
'  function get_matching_opening_gateway',
'  ( pi_sbfl_rec       in flow_subflows%rowtype',
'  ) return flow_objects.objt_bpmn_id%type',
'  is',
'    l_gateway_rec         flow_objects%rowtype;',
'    l_tgt_objt_bpmn_id    flow_objects.objt_bpmn_id%type;',
'  begin',
'    apex_debug.enter',
'    ( ''get_matching_opening_gateway''',
'    , ''pi_sbfl_rec.sbfl_current'' , pi_sbfl_rec.sbfl_current',
'    , ''pi_sbfl_rec.sbfl_dgrm_id'' , pi_sbfl_rec.sbfl_dgrm_id',
'    , ''pi_sbfl_rec.sbfl_status''  , pi_sbfl_rec.sbfl_status',
'    );',
'    -- get the matching object from the subflow_log record for the completed closing gateway',
'    begin',
'      select distinct sflg.sflg_matching_object',
'        into l_tgt_objt_bpmn_id',
'        from flow_subflow_log sflg',
'       where sflg'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'_prcs_id        = pi_sbfl_rec.sbfl_prcs_id',
'         and sflg_sbfl_id        = pi_sbfl_rec.sbfl_id',
'         and sflg_objt_id        = pi_sbfl_rec.sbfl_current',
'      ;',
'    exception',
'      when no_data_found then',
'        -- migration issue from pre 25.1 - no matching object - just can''t rewind here!',
'        l_tgt_objt_bpmn_id  := null;',
'      when others then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id      => pi_sbfl_rec.sbfl_prcs_id',
'        , pi_message_key  => ''gateway-matching-object-error''',
'        );',
'        -- $F4AMESSAGE ''gateway-matching-object-error'' || ''Error retrieving matching gateway object for subflow %0, current step %1.''',
'    end;',
'    ',
'    apex_debug.message ( p_message => ''Matching opening gateway: %0 ''',
'                       , p0 => l_tgt_objt_bpmn_id',
'                       );',
'    return l_tgt_objt_bpmn_id;',
'  end get_matching_opening_gateway;',
'',
'  procedure get_nearest_previous_gateway',
'  ( pi_sbfl_rec                in  flow_subflows%rowtype',
'  , po_nearest_gateway_bpmn_id out flow_objects.objt_bpmn_id%type',
'  , po_nearest_gateway_type    out flow_objects.objt_tag_name%type',
'  , po_nearest_gateway_name    out flow_objects.objt_name%type',
'  , po_num_steps               out integer',
'  )',
'  is',
'    l_gateway_bpmn_id   flow_objects.objt_bpmn_id%type;',
'    l_current_object    flow_objects.objt_bpmn_id%type;',
'    l_gateway_type      flow_objects.objt_tag_name%type;',
'    l_gateway_name      flow_objects.objt_name%type;',
'    l_num_steps         integer;',
'  begin',
'    -- get nearest previous gateway',
'    begin',
'        select prev_obj.objt_bpmn_id ',
'             , prev_obj.objt_tag_name',
'             , coalesce( prev_obj.objt_name, prev_obj.objt_bpmn_id)',
'             , level',
'          into l_gateway_bpmn_id',
'             , l_gateway_type',
'             , l_gateway_name',
'             , l_num_steps',
'          from flow_objects prev_obj',
'          join flow_connections conn',
'            on conn.conn_src_objt_id = prev_obj.objt_id',
'           and conn.conn_dgrm_id     = prev_obj.objt_dgrm_id',
'           and conn.conn_tag_name    = flow_constants_pkg.gc_bpmn_sequence_flow',
'          join flow_objects curr_obj',
'            on conn.conn_tgt_objt_id = curr_obj.objt_id',
'           and conn.conn_dgrm_id     = curr_obj.objt_dgrm_id',
'           and conn.conn_tag_name    = flow_constants_pkg.gc_bpmn_sequence_flow',
'         where curr_obj.objt_dgrm_id = pi_sbfl_rec.sbfl_dgrm_id',
'           and prev_obj.objt_tag_name in (''bpmn:eventBasedGateway'',''bpmn:inclusiveGateway'',''bpmn:parallelGateway'',  ''bpmn:exclusiveGateway'')',
'         start with curr_obj.objt_bpmn_id = pi_sbfl_rec.sbfl_current',
'        connect by  curr_obj.objt_tag_name not in (''bpmn:eventBasedGateway'',''bpmn:inclusiveGateway'',''bpmn:parallelGateway'', ''bpmn:startEvent'', ''bpmn:exclusiveGateway'', ''bpmn:boundaryEvent'')',
'                and curr_obj.objt_id = prior prev_obj.objt_id',
'        order by level',
'        fetch first 1 row only',
'        ;',
'    exception',
'      when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id      => pi_sbfl_rec.sbfl_prcs_id',
'        , pi_message_key  => ''gateway-no-previous-gw''',
'        );',
'        -- $F4AMESSAGE ''gateway-no-previous-gw'' || ''No previous gateway found for subflow %0.''',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id      => pi_sbfl_rec.sbfl_prcs_id',
'        , pi_message_key  => ''gateway-multiple-previous-gws''',
'        );',
'        -- $F4AMESSAGE ''gateway-multiple-previous-gws'' || ''Multiple previous gateways found for subflow %0.''',
'    end;',
'    po_nearest_gateway_bpmn_id := l_gateway_bpmn_id;',
'    po_nearest_gateway_type    := l_gateway_type;',
'    po_nearest_gateway_name    := l_gateway_name;',
'    po_num_steps               := l_num_steps;  ',
'  end get_nearest_previous_gateway;',
'',
'  function get_valid_routing_variable_routes',
'    ( pi_prcs_id            in flow_processes.prcs_id%type',
'    , pi_sbfl_id            in flow_subflows.sbfl_id%type',
'    , pi_objt_bpmn_id       in flow_objects.objt_bpmn_id%type',
'    , pi_objt_tag           in flow_objects.objt_tag_name%type ',
'    , pi_routing_variable   in flow_process_variables.prov_var_vc2%type  ',
'    ) return apex_t_varchar2',
'  is ',
'    l_forward_routes          apex_t_varchar2;  -- routes specified in the routing variable',
'    l_possible_routes         apex_t_varchar2;  -- all possible forward routes from the splitting gateway',
'    l_bad_routes              apex_t_varchar2;  -- specified routes which are not valid routes',
'    l_bad_route_string        varchar2 (2000);',
'    e_gateway_invalid_route   exception;',
'  begin',
'    begin',
'      l_forward_routes := apex_string.split ( p_str => pi_routing_variable',
'                                            , p_sep => '':''',
'                                            );',
'      if pi_objt_tag = flow_constants_pkg.gc_bpmn_gateway_exclusive then',
'        if (l_forward_routes.count > 1) then',
'          l_bad_route_string := pi_routing_variable;',
'          apex_debug.info ( p_message => ''-- exclusive gateway - routing variable contains more than one forward route %0''',
'                          , p0 => l_bad_route_string',
'                          );',
'          raise e_gateway_invalid_route;',
'        end if;',
'      end if;',
'      -- get the possible forward routes',
'      select conn.conn_bpmn_id',
'        bulk collect into l_possible_routes',
'        from flow_connections conn',
'        join flow_objects objt ',
'          on objt.objt_id      = conn.conn_src_objt_id',
'         and objt.objt_dgrm_id = conn.conn_dgrm_id ',
'        join flow_subflows sbfl',
'          on sbfl.sbfl_dgrm_id = conn.conn_dgrm_id',
'       where sbfl.sbfl_id      = pi_sbfl_id',
'         and objt.objt_bpmn_id = pi_objt_bpmn_id',
'      ;',
'      -- check all specified routes are valid',
'      l_bad_routes := l_forward_routes multiset except l_possible_routes;',
'',
'      if l_bad_routes.count > 0 then',
'        -- we have some invalid routes in the routing variable',
'        l_bad_route_string := apex_string.join(l_bad_routes,'','');',
'        apex_debug.message ( ',
'          p_message => ''Invalid routes found - count %0, bad routes: %1)''',
'        , p0 => l_bad_routes.count',
'        , p1 => l_bad_route_string ',
'        );',
'        raise e_gateway_invalid_route;',
'      end if;',
'    exception',
'      when e_gateway_invalid_route then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => pi_prcs_id',
'        , pi_sbfl_id        => pi_sbfl_id',
'        , pi_message_key    => ''gateway-invalid-route''',
'        , p0 => pi_objt_bpmn_id ',
'        , p1 => pi_objt_bpmn_id||flow_constants_pkg.gc_prov_suffix_route',
'        , p2 => l_bad_route_string',
'        );',
'        -- $F4AMESSAGE ''gateway-invalid-route'' || ''Error at gateway %0. Supplied variable %1 contains invalid route: %2''  ',
'    end;',
'    return l_forward_routes;',
'  end get_valid_routing_variable_routes;',
'',
'  function get_valid_routing_expression_routes',
'    ( pi_prcs_id            in flow_processes.prcs_id%type',
'    , pi_sbfl_id            in flow_subflows.sbfl_id%type',
'    , pi_scope              in flow_subflows.sbfl_scope%type',
'    , pi_objt_bpmn_id       in flow_objects.objt_bpmn_id%type',
'    , pi_objt_tag           in flow_objects.objt_tag_name%type ',
'    ) return apex_t_varchar2',
'  is',
'    l_forward_routes    apex_t_varchar2 := apex_t_varchar2();',
'    type t_possible_route  is record ',
'      ( conn_id         flow_connections.conn_id%type',
'      , conn_is_default flow_connections.conn_is_default%type',
'      , conn_sequence   flow_connections.conn_sequence%type',
'      , conn_bpmn_id    flow_connections.conn_bpmn_id%type',
'      , conn_expression clob',
'      , conn_language   flow_types_pkg.t_expr_type',
'      );',
'    type t_possible_routes is table of t_possible_route;',
'    l_possible_routes       t_possible_routes;',
'    l_take_route            boolean;',
'    l_expr                  clob;',
'    l_expr_type             flow_types_pkg.t_expr_type;',
'    l_bind_list             apex_plugin_util.t_bind_list;',
'    l_expressions           number;',
'    l_has_default           boolean;',
'    l_default_has_condition boolean;',
'    l_num_expected_exprs    number;',
'  begin',
'    -- get all valid forward routes, ordered by ',
'    select conn.conn_id',
'         , conn.conn_is_default',
'         , conn.conn_sequence',
'         , conn.conn_bpmn_id',
'         , conn.conn_attributes."conditionExpression"."expression" as conn_expression',
'         , conn.conn_attributes."conditionExpression"."language"   as conn_language',
'      bulk collect into l_possible_routes',
'      from flow_connections conn',
'      join flow_objects objt',
'        on conn.conn_dgrm_id      = objt.objt_dgrm_id',
'       and conn.conn_src_objt_id  = objt.objt_id',
'      join flow_subflows sbfl',
'        on sbfl.sbfl_dgrm_id      = objt.objt_dgrm_id',
'     where objt.objt_bpmn_id      = pi_objt_bpmn_id',
'       and sbfl.sbfl_id           = pi_sbfl_id',
'       and conn.conn_tag_name     = flow_constants_pkg.gc_bpmn_sequence_flow',
'     order by conn.conn_is_default asc, conn.conn_sequence asc',
'    ;',
'',
'    apex_debug.info( p_message => ''-- Found %0 possible routes.'', p0 => l_possible_routes.count );',
'',
'    -- check whether expressions are being used',
'    -- if so, raise exception if any non default path is missing an expression - assume a missing gw routing var)',
'',
'    l_expressions           := 0;',
'    l_has_default           := false;',
'    l_default_has_condition  := false;',
'',
'    for route in 1 ..l_possible_routes.count',
'    loop',
'      if l_possible_routes(route).conn_expression is not null then',
'        l_expressions := l_expressions +1;',
'      end if;',
'      if l_possible_routes(route).conn_is_default = 1 then',
'        l_has_default           := true;',
'        if l_possible_routes(route).conn_expression is not null then',
'          l_default_has_condition  := true;',
'        end if;',
'      end if;',
'    end loop;',
'',
'    l_num_expected_exprs := l_possible_routes.count;',
'    if l_has_default and not l_default_has_condition then',
'      l_num_expected_exprs := l_num_expected_exprs - 1;',
'    end if;',
'',
'    if l_expressions > 0  then',
'      if l_num_expected_exprs > l_expressions then',
'        raise e_no_route_found;',
'      end if;',
'    end if;',
'',
'    -- evaluate each routing condition in sequence.  Treat no expression as unconditional',
'',
'    if l_possible_routes.count > 0 then',
'      -- loop over routes',
'      for route in 1 .. l_possible_routes.count',
'      loop',
'        l_bind_list := apex_plugin_util.c_empty_bind_list;',
'        apex_debug.info( p_message => ''-- Evaluating Route #%0, Language: %1, Expression: %2'', p0 => route, p1 => l_possible_routes(route).conn_language, p2 => l_possible_routes(route).conn_expression );',
'        l_take_route := false;',
'        -- evaluate route expression',
'        l_expr      :=',
'          flow_engine_util.json_array_join',
'          ( ',
'            p_json_array => l_possible_routes(route).conn_expression',
'          );',
'        l_expr_type := l_possible_routes(route).conn_language;',
'',
'        apex_debug.info (p_message => ''--- unpacked gateway expression : %0 type : %1  ''',
'          , p0 => l_expr',
'          , p1 => l_expr_type);',
'',
'        if l_expr is null and l_possible_routes(route).conn_is_default = 0 then',
'          -- treat forward path as being false',
'          l_take_route := false;',
'',
'          apex_debug.info (p_message => ''Expression contains no condition and will not be taken.''); ',
'        else ',
'          -- evaluate condition',
'',
'          flow_proc_vars_int.do_substitution  ( pi_prcs_id   => pi_prcs_id ',
'                                              , pi_sbfl_id   => pi_sbfl_id ',
'                                              , pi_scope     => pi_scope ',
'                                              , pio_string   => l_expr ',
'                                              );      ',
'',
'          apex_debug.info (p_message => ''--- after substitution - expression : %0 type : %1  ''',
'            , p0 => l_expr',
'            , p1 => l_expr_type);',
'',
'          l_bind_list := flow_proc_vars_int.get_bind_list ( pi_expr    => l_expr',
'                                                          , pi_prcs_id => pi_prcs_id',
'                                                          , pi_sbfl_id => pi_sbfl_id',
'                                                          , pi_scope   => pi_scope',
'                                                          );',
'',
'          begin',
'            case l_expr_type  ',
'            when flow_constants_pkg.gc_expr_type_plsql_expression then',
'              l_take_route := apex_plugin_util.get_plsql_expr_result_boolean ( p_plsql_expression => l_expr ',
'                                                                             , p_auto_bind_items  => false',
'                                                                             , p_bind_list        => l_bind_list',
'                                                                             );',
'            when flow_constants_pkg.gc_expr_type_plsql_function_body then',
'              l_take_route := apex_plugin_util.get_plsql_func_result_boolean ( p_plsql_function => l_expr ',
'                                                                             , p_auto_bind_items  => false',
'                                                                             , p_bind_list        => l_bind_list',
'                                                                             );          ',
'            else       ',
'              l_take_route := false;',
'            end case;',
'          exception',
'            when others then',
'              raise e_bad_routing_expression;',
'          end;',
'        end if;',
'',
'        apex_debug.info (p_message => ''Routing Expresion evaluation result : %0  ''',
'            , p0 => case l_take_route when true then ''true'' else ''false'' end );',
'',
'        -- if valid, add to forward_routes',
'        if l_take_route or ( l_possible_routes(route).conn_is_default = 1 ',
'                             and l_forward_routes.count = 0 )',
'        then',
'          l_forward_routes.extend;',
'          l_forward_routes(l_forward_routes.last) := l_possible_routes(route).conn_bpmn_id;',
'          if l_possible_routes(route).conn_is_default = 1 then',
'            apex_debug.info ( p_message => ''--- gateway routing using default routing''); ',
'          end if;',
'          -- if exclusive gateway, break out - we have our route',
'          if pi_objt_tag = flow_constants_pkg.gc_bpmn_gateway_exclusive then',
'            return l_forward_routes;',
'          end if;',
'        end if;',
'      end loop;',
'    else',
'      raise e_no_route_found;',
'    end if;',
'    -- check that some routes were found',
'    if l_forward_routes.count = 0 then',
'      raise e_no_route_found;',
'    end if;',
'    return l_forward_routes;',
'  end get_valid_routing_expression_routes;',
'',
'  function get_gateway_route',
'    ( pi_prcs_id        in flow_processes.prcs_id%type',
'    , pi_sbfl_id        in flow_subflows.sbfl_id%type',
'    , pi_objt_bpmn_id   in flow_objects.objt_bpmn_id%type',
'    , pi_objt_tag       in flow_objects.objt_tag_name%type',
'    , pi_scope          in flow_subflows.sbfl_scope%type',
'    ) return apex_t_varchar2',
'  is',
'    l_routing_variable      varchar2(2000);  -- 1 route for exclusiveGateway, 1 or more for inclusive (:sep)',
'    l_forward_routes        apex_t_varchar2 := apex_t_varchar2();',
'    l_num_routes            number := 0;',
'    l_default_route         flow_connections.conn_bpmn_id%type;',
'',
'  begin',
'    begin',
'      -- check if route is in process variable',
'      l_routing_variable := flow_proc_vars_int.get_var_vc2 ',
'                            ( pi_prcs_id  => pi_prcs_id',
'                            , pi_var_name => pi_objt_bpmn_id||flow_constants_pkg.gc_prov_suffix_route',
'                            , pi_scope    => pi_scope',
'                            );',
'      if l_routing_variable is not null then',
'        apex_debug.info( p_message => ''-- Using Routing Variable (Legacy Mode).'' );',
'        -- route from routing variable',
'        l_forward_routes := get_valid_routing_variable_routes ( pi_prcs_id          => pi_prcs_id',
'                                                              , pi_sbfl_id          => pi_sbfl_id',
'                                                              , pi_objt_bpmn_id     => pi_objt_bpmn_id',
'                                                              , pi_objt_tag         => pi_objt_tag',
'                                                              , pi_routing_variable => l_routing_variable',
'                                                              );   ',
'        apex_debug.info ( p_message => ''-- gateway routing using gateway routing variable.  Forward path: %0''',
'                        , p0 => l_routing_variable',
'                        );                                                                ',
'      else ',
'        apex_debug.info( p_message => ''-- Using Gateway Route Expressions or Default Routing.'' );',
'        -- look for gateway routing expressions or default routing',
'        l_forward_routes := get_valid_routing_expression_routes ( pi_prcs_id          => pi_prcs_id',
'                                                                , pi_sbfl_id          => pi_sbfl_id',
'                                                                , pi_objt_bpmn_id     => pi_objt_bpmn_id',
'                                                                , pi_objt_tag         => pi_objt_tag',
'                                                                , pi_scope            => pi_scope',
'                                                                ); ',
'        apex_debug.info ( p_message => ''-- gateway routing using gateway routing expressions or default path. Forward path: %0''',
'                        , p0 => apex_string.join (p_table => l_forward_routes, p_sep => '':'')',
'                        );   ',
'      end if; ',
'      if l_forward_routes.count = 0 then',
'        raise e_no_route_found;',
'      end if;',
'    exception',
'      when e_no_route_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => pi_prcs_id',
'        , pi_sbfl_id        => pi_sbfl_id',
'        , pi_message_key    => ''gateway-no-route''',
'        , p0 => pi_objt_bpmn_id||flow_constants_pkg.gc_prov_suffix_route',
'        );',
'        -- $F4AMESSAGE ''gateway-no-route'' || ''No gateway routing instruction provided in variable %0 and model contains no default route.''  ',
'      when e_bad_routing_expression then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => pi_prcs_id',
'        , pi_sbfl_id        => pi_sbfl_id',
'        , pi_message_key    => ''gateway-bad-expression''',
'        , p0 => pi_objt_bpmn_id||flow_constants_pkg.gc_prov_suffix_route',
'        );',
'        -- $F4AMESSAGE ''gateway-bad-expression'' || ''Bad gateway routing expression.  This can occur if you attempt to bind a variable with embedded colon (:).''  ',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => pi_prcs_id',
'        , pi_sbfl_id        => pi_sbfl_id',
'        , pi_message_key    => ''gateway-too-many-defaults''',
'        , p0 => pi_objt_bpmn_id',
'        );',
'        -- $F4AMESSAGE ''gateway-too-many-defaults'' || ''More than one default route specified in model for Gateway %0.'' ',
'    end;',
'    return l_forward_routes;',
'  end get_gateway_route;',
'',
'  function gateway_merge',
'    ( p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    ) return varchar2 -- returns forward status ''wait'' or ''proceed''',
'  is ',
'    l_num_unfinished_subflows   number;',
'    l_gateway_forward_status    varchar2(10)  := ''wait'';',
'    l_subflow                   flow_subflows.sbfl_id%type;',
'  begin  ',
'    apex_debug.enter ',
'    ( ''gateway_merge''',
'    , ''p_sbfl_info.sbfl_current'' , p_sbfl_info.sbfl_current',
'    , ''p_step_info.target_objt_ref'' , p_step_info.target_objt_ref',
'    , ''p_sbfl_info.sbfl_last_completed'', p_sbfl_info.sbfl_last_completed',
'    );',
'    -- set current subflow to status waiting,       ',
'    update flow_subflows sbfl',
'        set sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_waiting_gateway',
'          , sbfl.sbfl_current        = p_step_info.target_objt_ref',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )            ',
'      where sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'        and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'    ;',
'    -- check if we are waiting for other flows or can proceed',
'    select count(*)',
'      into l_num_unfinished_subflows',
'      from flow_subflows sbfl',
'      where sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'        and sbfl.sbfl_diagram_level = p_sbfl_info.sbfl_diagram_level',
'        and sbfl.sbfl_starting_object = p_sbfl_info.sbfl_starting_object',
'        and (  sbfl.sbfl_current != p_step_info.target_objt_ref',
'            or sbfl.sbfl_status != flow_constants_pkg.gc_sbfl_status_waiting_gateway',
'            )',
'    ;',
'    if l_num_unfinished_subflows = 0 then',
'      -- all task to be merged have completed.  So we do the merge... ',
'      -- lock parent subflow first',
'      if flow_engine_util.lock_subflow(p_sbfl_info.sbfl_sbfl_id) then',
'        begin',
'          -- proceed from gateway, locking child subflows',
'          for completed_subflows in ( select completed_sbfl.sbfl_id',
'                                        from flow_subflows completed_sbfl ',
'                                        where completed_sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'                                          and completed_sbfl.sbfl_diagram_level = p_sbfl_info.sbfl_diagram_level',
'                                          and completed_sbfl.sbfl_starting_object = p_sbfl_info.sbfl_starting_object',
'                                          and completed_sbfl.sbfl_current = p_step_info.target_objt_ref ',
'                                          and completed_sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_waiting_gateway',
'                                          for update wait 2',
'                                    )',
'          loop',
'            l_subflow := completed_subflows.sbfl_id;',
'            flow_engine_util.subflow_complete',
'            ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'            , p_subflow_id => completed_subflows.sbfl_id',
'            );',
'          end loop;',
'',
'          --mark parent split subflow ready to restart',
'          l_subflow := p_sbfl_info.sbfl_sbfl_id;',
'          update flow_subflows parent_sbfl',
'              set parent_sbfl.sbfl_status                   = flow_constants_pkg.gc_sbfl_status_proceed_gateway',
'                , parent_sbfl.sbfl_current                  = p_step_info.target_objt_ref',
'                , parent_sbfl.sbfl_iteration_type           = null',
'                , parent_sbfl.sbfl_loop_counter             = null',
'                , parent_sbfl.sbfl_loop_total_instances     = null',
'                , parent_sbfl.sbfl_last_completed           = p_sbfl_info.sbfl_current  -- last step of final child sbfl pre-merge',
'                , parent_sbfl.sbfl_last_update              = systimestamp',
'                , parent_sbfl.sbfl_last_update_by           = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                                       , sys_context(''userenv'',''os_user'')',
'                                                                       , sys_context(''userenv'',''session_user'')',
'                                                                       )  ',
'            where parent_sbfl.sbfl_last_completed           = p_sbfl_info.sbfl_starting_object',
'              and parent_sbfl.sbfl_status                   = flow_constants_pkg.gc_sbfl_status_split  ',
'              and parent_sbfl.sbfl_id                       = p_sbfl_info.sbfl_sbfl_id',
'          ;',
'        exception',
'          when lock_timeout then',
'            flow_errors.handle_instance_error',
'            ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'            , pi_sbfl_id => l_subflow',
'            , pi_message_key => ''timeout_locking_subflow''',
'            , p0 => l_subflow',
'            );',
'            -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''',
'          when others then',
'            flow_errors.handle_instance_error',
'            ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'            , pi_message_key => ''gateway-merge-error''',
'            , p0 => l_subflow',
'            );          ',
'            -- $F4AMESSAGE ''gateway-merge-error'' || ''Internal error processing merging gateway on subflow %0'' ',
'        end;',
'        -- test for any errors so far ',
'        if not flow_globals.get_step_error then ',
'          -- process any after-merge expression set',
'          flow_expressions.process_expressions',
'          ( pi_objt_id     => p_step_info.target_objt_id',
'          , pi_set         => flow_constants_pkg.gc_expr_set_after_merge',
'          , pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id     => p_sbfl_info.sbfl_sbfl_id',
'          , pi_step_key    => p_sbfl_info.sbfl_step_key',
'          , pi_var_scope   => p_sbfl_info.sbfl_scope',
'          , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'          );',
'          -- test again for any errors so far - if so, don''t commit',
'          if not flow_globals.get_step_error then ',
'            -- commit tx',
'            commit;',
'            -- start new tx by locking parent subflow',
'            if not flow_engine_util.lock_subflow(p_sbfl_info.sbfl_sbfl_id) then',
'              -- unable to lock parent ''split'' subflow.',
'              flow_errors.handle_instance_error',
'              ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'              , pi_sbfl_id => p_sbfl_info.sbfl_sbfl_id',
'              , pi_message_key => ''timeout_locking_subflow''',
'              , p0 => p_sbfl_info.sbfl_sbfl_id',
'              );',
'              -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''',
'            end if;',
'            l_gateway_forward_status := ''proceed'';',
'          else',
'            -- has step errors from expressions',
'            flow_errors.set_error_status',
'            ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'            , pi_sbfl_id => p_sbfl_info.sbfl_sbfl_id',
'            );',
'          end if;  ',
'        else ',
'          -- has step errors from merge',
'          flow_errors.set_error_status',
'          ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id => p_sbfl_info.sbfl_sbfl_id',
'          );',
'        end if;       ',
'      else ',
'        -- unable to lock parent ''split'' subflow.',
'        -- exception already handled in lock_subflow so no need to throw an error here.',
'        -- has step errors from locking',
'        flow_errors.set_error_status',
'        ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'        , pi_sbfl_id => p_sbfl_info.sbfl_sbfl_id',
'        );',
'      end if;',
'    end if; ',
'    return l_gateway_forward_status;',
'  end gateway_merge;',
'',
'  procedure gateway_split',
'    ( p_subflow_id     in flow_subflows.sbfl_id%type ',
'    , p_sbfl_info      in flow_subflows%rowtype',
'    , p_step_info      in flow_types_pkg.flow_step_info',
'    , p_gateway_routes in apex_t_varchar2',
'    )',
'  is ',
'    l_new_subflows      t_new_sbfls := t_new_sbfls();',
'    l_new_subflow       flow_types_pkg.t_subflow_context;',
'  begin ',
'    apex_debug.enter ',
'    ( ''gateway_split''',
'    , ''p_sbfl_info.sbfl_current'' , p_sbfl_info.sbfl_current',
'    , ''p_step_info.target_objt_ref'' , p_step_info.target_objt_ref',
'    );',
'    -- note that p_subflow_id might be different to the subflow in p_sbfl_info.sbfl_id',
'    -- we have splitting gateway going forward',
'    -- Current Subflow into status split ',
'    update flow_subflows sbfl',
'        set sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'          , sbfl.sbfl_current        = p_step_info.target_objt_ref',
'          , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_split  ',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id = p_subflow_id',
'        and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'    ;',
'    -- get all forward parallel paths and create subflows for them',
'    -- these are paths forward of p_step_info.target_objt_ref as we are doing double step',
'    -- create subflows in one loop then step through them again in second loop',
'    -- to prevent some subflows getting to following merge gateway before all subflows are created (causes race condition)',
'',
'    for new_path in ( select conn.conn_bpmn_id route',
'                           , ultimate_tgt_objt.objt_bpmn_id target',
'                        from flow_connections conn',
'                        join flow_objects ultimate_tgt_objt -- first object in each child',
'                          on ultimate_tgt_objt.objt_id = conn.conn_tgt_objt_id',
'                         and conn.conn_dgrm_id = ultimate_tgt_objt.objt_dgrm_id',
'                        join flow_objects objt  -- gateway object',
'                          on objt.objt_id = conn.conn_src_objt_id',
'                         and conn.conn_dgrm_id = objt.objt_dgrm_id',
'                       where conn.conn_dgrm_id = p_step_info.dgrm_id',
'                         and conn.conn_src_objt_id = p_step_info.target_objt_id',
'                         and conn.conn_tag_name = flo'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'w_constants_pkg.gc_bpmn_sequence_flow',
'                         and ( objt.objt_tag_name = flow_constants_pkg.gc_bpmn_gateway_parallel',
'                             OR ',
'                             ( objt.objt_tag_name = flow_constants_pkg.gc_bpmn_gateway_inclusive',
'                             and ',
'                               conn.conn_bpmn_id member of p_gateway_routes',
'                             ))',
'                    )',
'    loop',
'      -- path is included in list of chosen forward paths.',
'      apex_debug.info',
'      ( p_message => ''starting parallel flow for %0''',
'      , p0        => p_step_info.target_objt_tag',
'      );',
'',
'      l_new_subflow :=',
'        flow_engine_util.subflow_start',
'        ( p_process_id             => p_sbfl_info.sbfl_prcs_id         ',
'        , p_parent_subflow         => p_subflow_id       ',
'        , p_starting_object        => p_step_info.target_objt_ref         ',
'        , p_current_object         => p_step_info.target_objt_ref          ',
'        , p_route                  => new_path.route         ',
'        , p_last_completed         => p_sbfl_info.sbfl_current ',
'        , p_status                 => flow_constants_pkg.gc_sbfl_status_created',
'        , p_parent_sbfl_proc_level => p_sbfl_info.sbfl_process_level',
'        , p_new_proc_level         => false',
'        , p_dgrm_id                => p_sbfl_info.sbfl_dgrm_id',
'        )',
'      ;',
'      l_new_subflow.route   := new_path.route;',
'      l_new_subflows.extend;',
'      l_new_subflows (l_new_subflows.last) := l_new_subflow;',
'    end loop;',
'    -- log gateway as completed',
'    flow_logging.log_step_completion   ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_subflow_id',
'    , p_completed_object => p_step_info.target_objt_ref ',
'    );',
'    -- update parent status now split and no current object',
'     update flow_subflows sbfl',
'        set sbfl.sbfl_current        = null',
'          , sbfl.sbfl_last_completed = p_step_info.target_objt_ref',
'          , sbfl.sbfl_last_update    = systimestamp',
'          , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'      where sbfl.sbfl_id = p_subflow_id',
'        and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id;',
'',
'    -- commit the transaction',
'    commit;',
'    ',
'    apex_debug.info ( p_message => ''New Subflow Creation Commited'');',
'    ',
'    for new_subflow in 1.. l_new_subflows.count',
'    loop',
'      -- reset step_had_error flag',
'      flow_globals.set_step_error ( p_has_error => false);',
'      -- check subflow still exists and lock it(in case earlier loop terminated everything in level)',
'      if flow_engine_util.lock_subflow( p_subflow_id => l_new_subflows(new_subflow).sbfl_id)',
'      then',
'        -- step into first step on the new path',
'        flow_engine.flow_complete_step    ',
'        ( p_process_id        => p_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id        => l_new_subflows(new_subflow).sbfl_id',
'        , p_step_key          => l_new_subflows(new_subflow).step_key',
'        , p_forward_route     => l_new_subflows(new_subflow).route',
'        , p_log_as_completed  => false',
'        );',
'      end if;',
'    end loop;',
'    -- reset step_had_error flag',
'    flow_globals.set_step_error ( p_has_error => false);',
'  end gateway_split;',
'',
'  procedure process_para_incl_Gateway',
'    ( p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is',
'    l_gateway_forward_status    varchar2(10);',
'    l_sbfl_id                   flow_subflows.sbfl_id%type;',
'    l_sbfl_id_sub               flow_subflows.sbfl_id%type;',
'    l_sbfl_id_par               flow_subflows.sbfl_id%type; ',
'    l_num_back_connections      number;   -- number of connections leading into object',
'    l_num_forward_connections   number;   -- number of connections forward from object',
'    l_num_unfinished_subflows   number;',
'    l_forward_routes            apex_t_varchar2 := apex_t_varchar2();',
'    l_step_key                  flow_subflows.sbfl_step_key%type;',
'    l_tag_name                  flow_objects.objt_tag_name%type; -- not used',
'    l_is_actual_gateway         boolean;  -- set if the object is really a gateway (vs. an iteration acting as a gateway)',
'    l_matching_object           flow_objects.objt_bpmn_id%type;',
'/*    l_new_subflows              t_new_sbfls := t_new_sbfls();',
'    l_new_subflow               flow_types_pkg.t_subflow_context; */ -- think these not used',
'  begin',
'    apex_debug.enter ',
'    ( ''process_para_incl_Gateway''',
'    , ''p_step_info.target_objt_tag''       , p_step_info.target_objt_tag',
'    , ''p_step_info.target_objt_ref''       , p_step_info.target_objt_ref',
'    , ''p_step_info.target_objt_iteration'' , nvl( p_step_info.target_objt_iteration, ''Null'')',
'    );',
'    if p_step_info.target_objt_treat_as_tag is null and p_sbfl_info.sbfl_loop_counter is null then ',
'      -- for actual gateway get number of forward and backward connections',
'      flow_engine_util.get_number_of_connections',
'      ( pi_dgrm_id                  => p_step_info.dgrm_id',
'      , pi_objt_bpmn_id             => p_step_info.target_objt_ref',
'      , pi_conn_type                => flow_constants_pkg.gc_bpmn_sequence_flow',
'      , po_num_back_connections     => l_num_back_connections',
'      , po_num_forward_connections  => l_num_forward_connections',
'      , po_objt_tag_name            => l_tag_name  -- not used',
'      );',
'      l_is_actual_gateway := true;',
'    elsif p_step_info.target_objt_treat_as_tag = flow_constants_pkg.gc_bpmn_gateway_parallel ',
'    and p_sbfl_info.sbfl_loop_counter is null then',
'      l_is_actual_gateway := false;',
'      l_num_back_connections    := 1;',
'      l_num_forward_connections := 99;',
'    elsif p_step_info.target_objt_treat_as_tag = flow_constants_pkg.gc_bpmn_gateway_parallel ',
'    and p_sbfl_info.sbfl_loop_counter is not null then',
'      l_is_actual_gateway := false;',
'      l_num_back_connections    := 99;',
'      l_num_forward_connections := 1;',
'    end if;',
'',
'    l_gateway_forward_status := ''proceed'';',
'    l_sbfl_id  := p_sbfl_info.sbfl_id;',
'',
'    if l_num_back_connections > 1  then',
'      apex_debug.info',
'      ( p_message => ''%0 Parallel Merging %1''',
'      , p0        => p_step_info.target_objt_tag',
'      , p1        => p_step_info.target_objt_ref',
'      );  ',
'      if p_sbfl_info.sbfl_iteration_type = flow_constants_pkg.gc_iteration_parallel ',
'         and p_sbfl_info.sbfl_loop_counter is not null ',
'      then',
'        -- we have merging gateway.  do the merge. returns ''wait'' if flow is waiting at gateway, ''proceed'' if merged',
'        l_gateway_forward_status := flow_iteration.parallel_merge ( p_sbfl_info  => p_sbfl_info',
'                                                                    , p_step_info  => p_step_info',
'                                                                    );',
'      else      ',
'        -- we have merging gateway.  do the merge. returns ''wait'' if flow is waiting at gateway, ''proceed'' if merged',
'        l_gateway_forward_status := gateway_merge ( p_sbfl_info  => p_sbfl_info',
'                                                  , p_step_info  => p_step_info',
'                                                  );',
'        l_matching_object := p_sbfl_info.sbfl_starting_object;',
'      end if;                                        ',
'      -- switch to parent subflow ',
'      l_sbfl_id := p_sbfl_info.sbfl_sbfl_id;',
'    end if;',
'    ',
'    -- now do forward path, if you have token to ''proceed''',
'    if l_gateway_forward_status = ''proceed'' then ',
'      if l_num_forward_connections > 1 then',
'        -- we have splitting gateway going forward',
'        apex_debug.info ',
'        ( p_message => ''%0 Parallel Splitting %1 - %2 forward paths''',
'        , p0 => p_step_info.target_objt_tag',
'        , p1 => p_step_info.target_objt_ref',
'        , p2 => l_num_forward_connections',
'        );       ',
'        if l_is_actual_gateway then',
'          -- process any before-split expression set',
'          flow_expressions.process_expressions',
'          ( pi_objt_id     => p_step_info.target_objt_id',
'          , pi_set         => flow_constants_pkg.gc_expr_set_before_split',
'          , pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id     => l_sbfl_id',
'          , pi_step_key    => p_sbfl_info.sbfl_step_key',
'          , pi_var_scope   => p_sbfl_info.sbfl_scope',
'          , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'          );',
'        end if;      ',
'        -- test for any errors so far - if so, skip finding a route',
'        if not flow_globals.get_step_error then ',
'          apex_debug.info ( p_message => ''process_para_incl_Gateway: step has no errors after evaluating expressions'');',
'',
'          if l_is_actual_gateway then',
'            case p_step_info.target_objt_tag',
'            when flow_constants_pkg.gc_bpmn_gateway_inclusive then ',
'              -- actual inclusive gateway',
'              l_forward_routes := get_gateway_route',
'              ( pi_prcs_id       => p_sbfl_info.sbfl_prcs_id',
'              , pi_sbfl_id       => l_sbfl_id --l_sbfl_id?',
'              , pi_objt_bpmn_id   => p_step_info.target_objt_ref',
'              , pi_objt_tag       => p_step_info.target_objt_tag',
'              , pi_scope          => p_sbfl_info.sbfl_scope',
'              );',
'              apex_debug.info',
'              ( p_message => ''Forward routes for inclusiveGateway %0 : %1''',
'              , p0 => p_step_info.target_objt_ref',
'              , p1 => apex_string.join(l_forward_routes,'':'')',
'              );',
'              flow_logging.log_step_event',
'              ( p_sbfl_rec      => p_sbfl_info',
'--              , p_objt_bpmn_id  => p_step_info.target_objt_ref',
'              , p_event  => flow_constants_pkg.gc_step_event_route_chosen',
'              , p_event_level => flow_constants_pkg.gc_logging_level_routine',
'              , p_comment  => ''Chosen Paths : ''||apex_string.join(l_forward_routes,'':'')',
'              );',
'            when flow_constants_pkg.gc_bpmn_gateway_parallel then ',
'              -- actual parallel gateway',
'              l_forward_routes.extend;',
'              l_forward_routes(l_forward_routes.first) := ''parallel'';  -- just needs to be some not null string',
'            end case;',
'          end if; ',
'          -- test for any errors again - if so, skip doing the split',
'          if not flow_globals.get_step_error then ',
'            apex_debug.info ( p_message => ''process_para_incl_Gateway: step has no errors after evaluating routes'');',
'            if l_is_actual_gateway then',
'              gateway_split',
'              ( p_subflow_id => l_sbfl_id',
'              , p_sbfl_info  => p_sbfl_info',
'              , p_step_info  => p_step_info',
'              , p_gateway_routes => l_forward_routes',
'              );',
'            else',
'              -- is a parallel iteration split...',
'              ---- Add Edition IFDEF code here... If Enterprise compile this',
'              flow_iteration.parallel_split',
'              ( p_subflow_id => l_sbfl_id',
'              , p_sbfl_info  => p_sbfl_info',
'              , p_step_info  => p_step_info',
'              );   ',
'              ---- Add Edition IFDEF code here... else include this stubb',
'              -- raise feature_not_in_this_edition error',
'              --',
'              --',
'              -- End of Edition IFDEF code.       ',
'            end if;',
'          else',
'            -- has step errors from evaluating route',
'            flow_errors.set_error_status',
'            ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'            , pi_sbfl_id => l_sbfl_id',
'            );',
'          end if;',
'        else',
'          -- has step errors from expressions',
'          flow_errors.set_error_status',
'          ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id => l_sbfl_id',
'          );',
'        end if;',
'      elsif l_num_forward_connections = 1 then',
'        -- only single path going forward',
'        update  flow_subflows sbfl',
'            set sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'              , sbfl.sbfl_current = p_step_info.target_objt_ref',
'              , sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_running',
'              , sbfl.sbfl_last_update = systimestamp ',
'          where sbfl.sbfl_id = l_sbfl_id',
'            and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'        ;',
'        -- get step key from parent ',
'        select sbfl.sbfl_step_key',
'          into l_step_key',
'          from flow_subflows sbfl',
'         where sbfl.sbfl_id = l_sbfl_id; ',
'',
'        -- step into first step on the new path',
'        flow_engine.flow_complete_step   ',
'        ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => l_sbfl_id',
'        , p_step_key   => l_step_key',
'        , p_forward_route => null',
'        , p_matching_object => l_matching_object',
'        );',
'      end if;  -- single path',
'    end if;  -- forward token',
'  end process_para_incl_Gateway;',
'',
'  procedure process_exclusiveGateway',
'    ( p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is ',
'    l_num_forward_connections   number;   -- number of connections forward from object',
'    l_num_back_connections      number;   -- number of connections back from object',
'    l_forward_routes            apex_t_varchar2 := apex_t_varchar2();',
'    l_forward_route             flow_connections.conn_bpmn_id%type;',
'    l_tag_name                  flow_objects.objt_tag_name%type;  -- not used',
'  begin',
'    -- handles opening and closing and closing and reopening',
'    apex_debug.enter ',
'    ( ''process_exclusiveGateway''',
'    , ''p_step_info.target_objt_tag'' , p_step_info.target_objt_tag',
'    );',
'    flow_engine_util.get_number_of_connections',
'    ( pi_dgrm_id => p_step_info.dgrm_id',
'    , pi_objt_bpmn_id => p_step_info.target_objt_ref',
'    , pi_conn_type => flow_constants_pkg.gc_bpmn_sequence_flow',
'    , po_num_back_connections => l_num_back_connections',
'    , po_num_forward_connections => l_num_forward_connections',
'    , po_objt_tag_name => l_tag_name  -- not used',
'    );',
'',
'    if l_num_forward_connections > 1 then',
'      -- opening gateway ',
'      -- process any before-split expression set before gateway chooses route',
'      flow_expressions.process_expressions',
'      ( pi_objt_id     => p_step_info.target_objt_id',
'      , pi_set         => flow_constants_pkg.gc_expr_set_before_split',
'      , pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_info.sbfl_id',
'      , pi_step_key    => p_sbfl_info.sbfl_step_key',
'      , pi_var_scope   => p_sbfl_info.sbfl_scope',
'      , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'      );',
'      -- test for any errors so far - if so, skip finding a route',
'      if not flow_globals.get_step_error then ',
'        -- get route choice',
'        l_forward_routes := get_gateway_route',
'        ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'        , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'        , pi_objt_bpmn_id   => p_step_info.target_objt_ref',
'        , pi_objt_tag       => p_step_info.target_objt_tag',
'        , pi_scope          => p_sbfl_info.sbfl_scope',
'        );',
'        if l_forward_routes.count > 0 then',
'          l_forward_route := l_forward_routes(l_forward_routes.first);',
'        end if;',
'      else',
'        -- has step errors from expressions',
'        flow_errors.set_error_status',
'        ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'        , pi_sbfl_id => p_sbfl_info.sbfl_id',
'        );',
'      end if;',
'    else ',
'      -- closing gateway ',
'      -- process any after-merge expression set',
'      flow_expressions.process_expressions',
'      ( pi_objt_id     => p_step_info.target_objt_id',
'      , pi_set         => flow_constants_pkg.gc_expr_set_after_merge',
'      , pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id     => p_sbfl_info.sbfl_id',
'      , pi_step_key    => p_sbfl_info.sbfl_step_key',
'      , pi_var_scope   => p_sbfl_info.sbfl_scope',
'      , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'      );      ',
'      -- keep going',
'      l_forward_route := null;',
'    end if;  ',
'',
'    if not flow_globals.get_step_error then ',
'      -- all good so step forward',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_current        = p_step_info.target_objt_ref',
'           , sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'           , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'           , sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )  ',
'       where sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'         and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'      ;  ',
'      flow_engine.flow_complete_step   ',
'      ( p_process_id    => p_sbfl_info.sbfl_prcs_id',
'      , p_subflow_id    => p_sbfl_info.sbfl_id',
'      , p_step_key      => p_sbfl_info.sbfl_step_key',
'      , p_forward_route => l_forward_route',
'      );',
'    else        ',
'      -- has step errors from evaluating route',
'      flow_errors.set_error_status',
'      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'      );',
'    end if;',
'',
'  end process_exclusiveGateway; ',
'',
'  procedure process_eventBasedGateway',
'    ( p_sbfl_info  in flow_subflows%rowtype',
'    , p_step_info  in flow_types_pkg.flow_step_info',
'    )',
'  is ',
'    l_new_subflow       flow_types_pkg.t_subflow_context;',
'    l_new_subflows      t_new_sbfls := t_new_sbfls();',
'  begin',
'    -- eventGateway can have multiple inputs and outputs, but there is no waiting, etc.',
'    -- incoming subflow continues on the first output path.',
'    -- additional output paths create new subflows',
'    apex_debug.enter',
'    (',
'      p_routine_name => ''process_EventBasedGateway''',
'    , p_name01       => ''p_step_info.target_objt_ref''',
'    , p_value01      => p_step_info.target_objt_ref',
'    );',
'    -- process any before-split expression set',
'    flow_expressions.process_expressions',
'    ( pi_objt_id     => p_step_info.target_objt_id',
'    , pi_set         => flow_constants_pkg.gc_expr_set_before_split',
'    , pi_prcs_id     => p_sbfl_info.sbfl_prcs_id',
'    , pi_sbfl_id     => p_sbfl_info.sbfl_id',
'    , pi_step_key    => p_sbfl_info.sbfl_step_key',
'    , pi_var_scope   => p_sbfl_info.sbfl_scope',
'    , pi_expr_scope  => p_sbfl_info.sbfl_scope',
'    );',
'',
'    -- log gateway as completed here so only logged once',
'    flow_logging.log_step_completion   ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_completed_object => p_step_info.target_objt_ref ',
'    );',
'    -- get all forward parallel paths and create subflows for them',
'    -- these are paths forward of p_step_info.target_objt_ref as we are doing double step',
'    for new_path in ( select conn.conn_bpmn_id route',
'                           , objt.objt_bpmn_id target',
'                        from flow_connections conn',
'                        join flow_objects objt',
'                          on objt.objt_id = conn.conn_tgt_objt_id',
'                         and conn.conn_dgrm_id = objt.objt_dgrm_id',
'                       where conn.conn_dgrm_id = p_step_info.dgrm_id',
'                         and conn.conn_tag_name = flow_constants_pkg.gc_bpmn_sequence_flow',
'                         and conn.conn_src_objt_id = p_step_info.target_objt_id',
'                    )',
'    loop',
'      -- create new subflows for forward event paths starting here',
'      -- don''t start them yet...',
'      apex_debug.info',
'      ( p_message => ''starting parallel flow from Event Based Gateway for %0''',
'      , p0        => p_step_info.target_objt_tag',
'      );',
'',
'     l_new_subflow :=  flow_engine_util.subflow_start',
'        ( ',
'          p_process_id             => p_sbfl_info.sbfl_prcs_id        ',
'        , p_parent_subflow         => p_sbfl_info.sbfl_id       ',
'        , p_starting_object        => p_step_info.target_objt_ref         ',
'        , p_current_object         => p_step_info.target_objt_ref          ',
'        , p_route                  => new_path.route         ',
'        , p_last_completed         => p_step_info.target_objt_ref ',
'        , p_status                 => flow_constants_pkg.gc_sbfl_status_created   ',
'        , p_parent_sbfl_proc_level => p_sbfl_info.sbfl_process_level',
'        , p_new_proc_level         => false    ',
'        , p_dgrm_id                => p_sbfl_info.sbfl_dgrm_id',
'        , p_follows_ebg            => true',
'        )',
'      ;',
'      l_new_subflow.route   := new_path.route;',
'      l_new_subflows.extend;',
'      l_new_subflows (l_new_subflows.last) := l_new_subflow;',
'    end loop;      ',
'    -- mark parent flow as split',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_last_completed = p_sbfl_info.sbfl_current',
'         , sbfl.sbfl_current        = p_step_info.target_objt_ref',
'         , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_split  ',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )  ',
'     where sbfl.sbfl_id = p_sbfl_info.sbfl_id',
'       and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id',
'    ;',
'    -- commit the transaction',
'    commit;',
'    apex_debug.info ( p_message => ''New Subflow Creation Commited'');',
'    ',
'    for new_subflow in 1.. l_new_subflows.count',
'    loop',
'      -- reset step_had_error flag',
'      flow_globals.set_step_error ( p_has_error => false);',
'      -- check subflow still exists and lock it(in case earlier loop terminated everything in level)',
'      if flow_engine_util.lock_subflow',
'        ( p_subflow_id => l_new_subflows(new_subflow).sbfl_id',
'        )',
'      then    ',
'        -- step into first step on the new path',
'        flow_engine.flow_complete_step   ',
'        (',
'          p_process_id        => p_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id        => l_new_subflows(new_subflow).sbfl_id',
'        , p_step_key          => l_new_subflows(new_subflow).step_key',
'        , p_forward_route     => l_new_subflows(new_subflow).route',
'        , p_log_as_completed  => false',
'        );',
'      end if;',
'    end loop;',
'    -- reset step_had_error flag',
'    flow_globals.set_step_error ( p_has_error => false);',
'  end process_eventBasedGateway;',
'',
'end flow_gateways;',
'/',
'',
'create or replace package body flow_globals',
'/* ',
'-- Flows for APEX - flow_globals.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and / or its affiliates. 2026.',
'--',
'-- Created    25-Aug-2021  Richard Allen (Flowquest, for MT AG)',
'-- Modified   12-Apr-2022  Richard Allen (Oracle)',
'-- Modified   16-Feb-2026  Richard Allen (Flowquest)',
'--',
'*/',
'as',
'',
'  g_error_on_step  boolean := false;  ',
'  -- g_error_on_step starts false when every step is processed but is set true if an error',
'  -- occurs in the engine during processing.  It is then used to determine whether to ',
'  -- commit or rollback the engine transaction at the end of step processing',
'  g_is_recursive_step boolean := false;',
'  -- g_recursive_step is set to false for steps that are being performed by the user, and true',
'  -- for subsequent recursive steps that are performed by the engine (such as gateway steps, scriptTasks, etc.)',
'  g_is_async_session boolean := false;',
'  -- g_is_async_session is true for the lifetime of an AQ-driven async callback session.',
'',
'',
'  procedure set_context',
'  ( pi_prcs_id          in flow_processes.prcs_id%type',
'  , pi_sbfl_id          in flow_subflows.sbfl_id%type default null',
'  , pi_step_key         in flow_subflows.sbfl_step_key%type default null',
'  , pi_scope            in flow_subflows.sbfl_scope%type default null',
'  , pi_loop_counter     in flow_subflows.sbfl_loop_counter%type default null',
'  , pi_input_parameters in flow_subflows.sbfl_task_input_parameters%type default null',
'  )',
'  is',
'  begin ',
'    process_id        := pi_prcs_id;',
'    subflow_id        := pi_sbfl_id;',
'    step_key          := pi_step_key;',
'    scope             := pi_scope;',
'    loop_counter      := pi_loop_counter;',
'    input_parameters  := pi_input_parameters;    ',
'    output_parameters := null; -- Initialize as empty for each task execution  ',
'  end set_context;',
'',
'  procedure set_context',
'  ( pi_sbfl_rec   in flow_subflows%rowtype',
'  )',
'  is',
'  begin',
'    set_context ( pi_prcs_id          => pi_sbfl_rec.sbfl_prcs_id',
'                , pi_sbfl_id          => pi_sbfl_rec.sbfl_id',
'                , pi_step_key         => pi_sbfl_rec.sbfl_step_key',
'                , pi_scope            => pi_sbfl_rec.sbfl_scope',
'                , pi_loop_counter     => pi_sbfl_rec.sbfl_loop_counter',
'                , pi_input_parameters => pi_sbfl_rec.sbfl_task_input_parameters',
'                );',
'  end set_context;',
'',
'  procedure set_step_error',
'  ( p_has_error  in boolean default false)',
'  is',
'  begin',
'    /*apex_debug.enter',
'    ( ''set_step_error''',
'    , ''p_has_error'', case when p_has_error then ''true'' else ''false'' end',
'    );*/',
'    g_error_on_step := p_has_error;',
'  end set_step_error;',
'',
'  function get_step_error return boolean',
'  is',
'  begin',
'    /*apex_debug.enter',
'    ( ''get_step_error''',
'    , ''g_error_on_step'', case when g_error_on_step then ''true'' else ''false'' end',
'    );*/',
'    return g_error_on_step;',
'  end get_step_error; ',
'',
'  procedure set_is_recursive_step',
'  ( p_is_recursive_step  in boolean default false)',
'  is',
'  begin',
'    g_is_recursive_step := p_is_recursive_step;',
'  end set_is_recursive_step;',
'',
'  function get_is_recursive_step return boolean',
'  is',
'  begin',
'    return g_is_recursive_step;',
'  end get_is_recursive_step; ',
'',
'  procedure set_is_async_session',
'  ( p_is_async_session  in boolean default false)',
'  is',
'  begin',
'    g_is_async_session := p_is_async_session;',
'  end set_is_async_session;',
'',
'  function get_is_async_session return boolean',
'  is',
'  begin',
'    return g_is_async_session;',
'  end get_is_async_session;',
'  ',
'  procedure set_output_parameter',
'  ( pi_parameter_name in varchar2',
'  , pi_value          in varchar2',
'  )',
'  is',
'    l_json_obj json_object_t;',
'  begin',
'    -- Initialize JSON object if needed',
'    if output_parameters is null or output_parameters is not json then',
'      l_json_obj := json_object_t();',
'    else',
'      l_json_obj := json_object_t(output_parameters);',
'    end if;',
'    ',
'    -- Set the parameter value',
'    l_json_obj.put(pi_parameter_name, pi_value);',
'    ',
'    -- Update the global variable',
'    output_parameters := l_json_obj.to_clob();',
'  exception',
'    when others then',
'      -- If JSON operations fail, create new JSON object with just this parameter',
'      l_json_obj := json_object_t();',
'      l_json_obj.put(pi_parameter_name, pi_value);',
'      output_parameters := l_json_obj.to_clob();',
'  end set_output_parameter;',
'',
'  procedure set_output_parameter_object',
'  ( pi_parameter_name  in varchar2',
'  , pi_key1            in varchar2 default null',
'  , pi_value1          in varchar2 default null',
'  , pi_key2            in varchar2 default null',
'  , pi_value2          in varchar2 default null',
'  , pi_key3            in varchar2 default null',
'  , pi_value3          in varchar2 default null',
'  , pi_key4            in varchar2 default null',
'  , pi_value4          in varchar2 default null',
'  , pi_key5            in varchar2 default null',
'  , pi_value5          in varchar2 default null',
'  , pi_key6            in varchar2 default null',
'  , pi_value6          in varchar2 default null',
'  )',
'  is',
'    l_nested_obj   json_object_t;',
'  begin',
'    l_nested_obj := json_object_t();',
'',
'    if pi_key1 is not null then',
'      l_nested_obj.put(pi_key1, pi_value1);',
'    end if;',
'    if pi_key2 is not null then',
'      l_nested_obj.put(pi_key2, pi_value2);',
'    end if;',
'    if pi_key3 is not null then',
'      l_nested_obj.put(pi_key3, pi_value3);',
'    end if;',
'    if pi_key4 is not null then',
'      l_nested_obj.put(pi_key4, pi_value4);',
'    end if;',
'    if pi_key5 is not null then',
'      l_nested_obj.put(pi_key5, pi_value5);',
'    end if;',
'    if pi_key6 is not null then',
'      l_nested_obj.put(pi_key6, pi_value6);',
'    end if;',
'',
'    set_output_parameter_object',
'    ( pi_parameter_name  => pi_parameter_name',
'    , pi_object_json     => l_nested_obj.to_clob()',
'    );',
'  end set_output_parameter_object;',
'',
'  procedure set_output_parameter_object',
'  ( pi_parameter_name  in varchar2',
'  , pi_object_json     in clob',
'  )',
'  is',
'    l_json_obj     json_object_t;',
'    l_nested_obj   json_object_t;',
'  begin',
'    -- Initialize main JSON object, falling back to empty object if existing JSON is invalid.',
'    begin',
'      if output_parameters is null or output_parameters is not json then',
'        l_json_obj := json_object_t();',
'      else',
'        l_json_obj := json_object_t(output_parameters);',
'      end if;',
'    exception',
'      when others then',
'        l_json_obj := json_object_t();',
'    end;',
'    ',
'    -- Parse payload as object; empty object if null/invalid.',
'    begin',
'      if pi_object_json is not null and pi_object_json is json then',
'        l_nested_obj := json_object_t(pi_object_json);',
'      else',
'        l_nested_obj := json_object_t();',
'      end if;',
'    exception',
'      when others then',
'        l_nested_obj := json_object_t();',
'    end;',
'    ',
'    -- Add the nested object to the main object',
'    l_json_obj.put(pi_parameter_name, l_nested_obj);',
'    ',
'    -- Update the global variable',
'    output_parameters := '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'l_json_obj.to_clob();',
'  end set_output_parameter_object;',
'',
'  function get_output_parameters',
'  return flow_subflows.sbfl_task_output_parameters%type',
'  is',
'  begin',
'    return output_parameters;',
'  end get_output_parameters;',
'',
'  function input_parameter',
'  ( pi_parameter_name in varchar2',
'  ) return varchar2',
'  is',
'    l_json_obj json_object_t;',
'  begin',
'    if input_parameters is null or input_parameters is not json then',
'      return null;',
'    end if;',
'    ',
'    l_json_obj := json_object_t(input_parameters);',
'    ',
'    if l_json_obj.has(pi_parameter_name) then',
'      return l_json_obj.get_string(pi_parameter_name);',
'    else',
'      return null;',
'    end if;',
'  exception',
'    when others then',
'      return null;',
'  end input_parameter;',
'',
'  function business_ref',
'  (pi_scope       flow_subflows.sbfl_scope%type default 0)',
'  return flow_process_variables.prov_var_vc2%type',
'  is',
'  begin',
'    return flow_proc_vars_int.get_business_ref ',
'                              ( pi_prcs_id => process_id',
'                              , pi_scope   => pi_scope',
'                              );',
'  end business_ref;',
'',
'  function business_ref',
'  (pi_sbfl_id     flow_subflows.sbfl_id%type)',
'  return flow_process_variables.prov_var_vc2%type',
'  is',
'    l_scope     flow_subflows.sbfl_scope%type;',
'  begin',
'    l_scope := flow_engine_util.get_scope ( p_process_id => process_id',
'                                          , p_subflow_id => pi_sbfl_id);             ',
'    return business_ref ( pi_scope   => l_scope );',
'  end business_ref;',
'',
'  procedure set_call_origin',
'  (',
'    p_origin in varchar2',
'  )',
'  as',
'  begin',
'    case p_origin',
'      when ''REST'' then',
'        rest_call := true;',
'      else',
'        null;',
'    end case;',
'  end set_call_origin;',
'',
'  procedure unset_call_origin',
'  as',
'  begin',
'    rest_call := false;',
'  end unset_call_origin;',
'',
'end flow_globals;',
'/',
'',
'create or replace package body flow_instances as',
'/* ',
'-- Flows for APEX - flow_instances.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022-2023.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and/or its affiliates, 2025',
'--',
'-- Created  25-May-2021  Richard Allen (Flowquest) for  MT AG  - refactor from flow_engine',
'-- Modified 30-May-2022  Moritz Klein (MT AG)',
'-- Modified 28-Jan-2025  Richard Allen (Flowquest)',
'--',
'*/',
'',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  e_unsupported_start_event exception;',
'',
'  type t_call_def is record',
'    ( dgrm_name              flow_diagrams.dgrm_name%type',
'    , dgrm_version           flow_diagrams.dgrm_version%type',
'    , dgrm_id                flow_diagrams.dgrm_id%type',
'    , dgrm_version_selection flow_types_pkg.t_bpmn_attribute_vc2',
'    );',
'',
'  function call_is_recursive',
'    ( p_prcs_id   flow_processes.prcs_id%type',
'    , p_prdg_id   flow_instance_diagrams.prdg_id%type',
'    , p_dgrm_id   flow_diagrams.dgrm_id%type  ',
'    ) return boolean',
'  is',
'    l_num_recursive_nodes number;',
'  begin',
'    -- tests id p_dgrm_id exists in the instance diagram tree above p_prdg_id',
'    select  count(1)',
'    into    l_num_recursive_nodes',
'    from    flow_instance_diagrams',
'    where   prdg_prcs_id = p_prcs_id',
'    and     prdg_dgrm_id = p_dgrm_id',
'    and     level        > 1',
'    start with prdg_id   = p_prdg_id',
'    connect by prior prdg_prdg_id = prdg_id',
'    ;',
'    return l_num_recursive_nodes > 0;',
'  end call_is_recursive;',
'',
'  function diagram_is_callable',
'    ( p_dgrm_id   flow_diagrams.dgrm_id%type',
'    ) return boolean',
'  is',
'    l_is_callable   flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'      select nvl( objt.objt_attributes."apex"."isCallable" ,''false'')',
'        into l_is_callable',
'        from flow_objects objt',
'       where objt.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         and objt.objt_dgrm_id = p_dgrm_id',
'      ;',
'      return l_is_callable = ''true'';',
'  end diagram_is_callable;',
'',
'  procedure find_nested_calls',
'    ( p_dgrm_id         flow_diagrams.dgrm_id%type',
'    , p_prcs_id         flow_processes.prcs_id%type',
'    , p_parent_prdg_id  flow_instance_diagrams.prdg_id%type',
'    )',
'  is ',
'    l_child_dgrm_id                         flow_diagrams.dgrm_id%type;',
'    l_call_def                              t_call_def;',
'    l_current_prdg_id                       flow_instance_diagrams.prdg_id%type;',
'  begin',
'    for call_activity in (',
'      select objt.objt_bpmn_id',
'           , objt.objt_id',
'           , objt.objt_attributes."apex"."calledDiagram" as dgrm_name',
'           , objt.objt_attributes."apex"."calledDiagramVersion" as dgrm_version',
'           , objt.objt_attributes."apex"."calledDiagramVersionSelection" as dgrm_version_selection',
'        from flow_objects objt',
'       where objt.objt_tag_name = flow_constants_pkg.gc_bpmn_call_activity',
'         and objt.objt_dgrm_id = p_dgrm_id',
'      )',
'    loop',
'      l_child_dgrm_id :=',
'        flow_diagram.get_current_diagram',
'        ( pi_dgrm_name            => call_activity.dgrm_name',
'        , pi_dgrm_calling_method  => call_activity.dgrm_version_selection',
'        , pi_dgrm_version         => call_activity.dgrm_version',
'        , pi_prcs_id              => p_prcs_id',
'        );',
'      -- check diagram is callable',
'      if  diagram_is_callable (p_dgrm_id => l_child_dgrm_id) then',
'        -- diagram is callable ',
'        -- Check for self-reference',
'        -- If Diagram is calling itself stop processing and error out.',
'        if l_child_dgrm_id = p_dgrm_id then',
'          flow_errors.handle_general_error',
'          ( pi_message_key => ''start-diagram-calls-itself''',
'          , p0 => p_dgrm_id',
'          );',
'          -- $F4AMESSAGE ''start-diagram-calls-itself'' || ''You tried to start a diagram %0 that contains a callActivity calling itself.'' ',
'        else',
'          -- insert an instance_diagram record',
'          insert into flow_instance_diagrams',
'          ( prdg_prcs_id',
'          , prdg_dgrm_id',
'          , prdg_calling_dgrm',
'          , prdg_calling_objt',
'          , prdg_prdg_id',
'          )',
'          values ',
'          ( p_prcs_id',
'          , l_child_dgrm_id',
'          , p_dgrm_id',
'          , call_activity.objt_bpmn_id',
'          , p_parent_prdg_id',
'          )',
'          returning prdg_id into l_current_prdg_id',
'          ;',
'          -- check for indirect recursion',
'          if call_is_recursive  ( p_prcs_id => p_prcs_id',
'                                , p_dgrm_id => l_child_dgrm_id',
'                                , p_prdg_id => l_current_prdg_id) ',
'          then',
'            flow_errors.handle_general_error',
'            ( pi_message_key => ''start-diagram-calls-itself''',
'            , p0 => p_dgrm_id',
'            );',
'            -- $F4AMESSAGE ''start-diagram-calls-itself'' || ''You tried to start a diagram %0 that contains a callActivity calling itself.''           ',
'          -- find any nested calls in child',
'          end if;',
'          find_nested_calls ( p_dgrm_id         => l_child_dgrm_id',
'                            , p_prcs_id         => p_prcs_id ',
'                            , p_parent_prdg_id  => l_current_prdg_id',
'                            );',
'        end if;',
'      else',
'        -- diagram is not callable - raise error',
'        apex_debug.info',
'        ( p_message  => ''Building Diagram Call Tree - Diagram %0 (called by diagram %1 is set as not-callable''',
'        , p0  => l_child_dgrm_id',
'        , p1  => p_dgrm_id',
'        );',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''call-diagram-not-callable''',
'        , p0 => l_child_dgrm_id',
'        );',
'        -- $F4AMESSAGE ''call-diagram-not-callable'' || ''You tried to call a diagram %0 that is marked as being not callable.''        ',
'      end if;',
'    end loop; ',
'  end find_nested_calls;',
'',
'  procedure create_call_structure',
'    ( p_prcs_id  in flow_processes.prcs_id%type',
'    , p_dgrm_id  in flow_diagrams.dgrm_id%type',
'    )',
'  is ',
'    l_parent_prdg_id  flow_instance_diagrams.prdg_id%type;',
'  begin',
'    -- put top level diagram into the call structure',
'    insert into flow_instance_diagrams',
'      ( prdg_prcs_id',
'      , prdg_dgrm_id',
'      , prdg_diagram_level',
'      )',
'    values ',
'      ( p_prcs_id',
'      , p_dgrm_id',
'      , 0',
'      )',
'    returning prdg_id into l_parent_prdg_id;',
'    -- find any nested calls ',
'    find_nested_calls ( p_dgrm_id         => p_dgrm_id',
'                      , p_prcs_id         => p_prcs_id',
'                      , p_parent_prdg_id  => l_parent_prdg_id',
'                      );',
'  end create_call_structure;',
'',
'  procedure get_instance_attributes',
'    ( p_prcs_id                     in  flow_processes.prcs_id%type',
'    , p_dgrm_id                     in  flow_diagrams.dgrm_id%type',
'    , p_starting_object             in  flow_objects.objt_bpmn_id%type default null',
'    , p_requested_logging_level     in  flow_processes.prcs_logging_level%type default null',
'    , p_calculated_logging_level    out flow_processes.prcs_logging_level%type',
'    , p_process_bpmn_id             out flow_objects.objt_bpmn_id%type',
'    )',
'  is',
'    l_bpmn_process_objt flow_objects%rowtype;',
'    l_logging_level     flow_processes.prcs_logging_level%type;',
'    j_objt_attributes   sys.json_object_t;',
'    j_apex_attributes   sys.json_object_t;',
'    j_custom_extensions sys.json_object_t;',
'  begin',
'    -- This is used to calculate the instance logging level, taking into account',
'    --    - the default logging level from the diagram',
'    --    - the logging level requested from the process create call',
'    --    - the default logging level set in flow configuration',
'    -- We''ll also use this to set the instance description / subject in a later project.',
'',
'    -- find the bpmn:process object for the diagram to get logging info ',
'    l_bpmn_process_objt := flow_diagram.get_bpmn_process_object',
'                            ( p_dgrm_id               => p_dgrm_id',
'                            , p_process_id            => p_prcs_id',
'                            , p_event_starting_object => p_starting_object',
'                            );',
'    apex_debug.message (p_message => ''BPMN Process Object : %0'', p0 => l_bpmn_process_objt.objt_id);',
'',
'    if l_bpmn_process_objt.objt_attributes is null then',
'      l_logging_level := flow_engine_util.get_config_value ',
'                          ( p_config_key    => flow_constants_pkg.gc_config_logging_default_level ',
'                          , p_default_value => 0 );',
'    else',
'      -- get the logging level from the bpmn process object',
'      l_logging_level := json_value (l_bpmn_process_objt.objt_attributes, ''$.apex.minLoggingLevel'' returning number); ',
'      if l_logging_level is null then',
'        l_logging_level := flow_engine_util.get_config_value ',
'                            ( p_config_key    => flow_constants_pkg.gc_config_logging_default_level ',
'                            , p_default_value => 0 );',
'      end if;',
'    end if;',
'    l_logging_level := greatest ( nvl(p_requested_logging_level,0)',
'                                , l_logging_level );',
'    p_calculated_logging_level := l_logging_level;',
'    p_process_bpmn_id          := l_bpmn_process_objt.objt_bpmn_id;',
'  end get_instance_attributes;',
'',
'  procedure set_instance_name',
'    ( p_prcs_id            in flow_processes.prcs_id%type',
'    , p_sbfl_id            in flow_subflows.sbfl_id%type',
'    , p_instance_name_def  in flow_types_pkg.t_bpmn_attribute_vc2',
'    )',
'  is',
'    l_instance_name  varchar2(200) := p_instance_name_def;',
'  begin',
'    -- set the instance name',
'    if l_instance_name is not null then',
'      flow_proc_vars_int.do_substitution',
'      ( pi_prcs_id => p_prcs_id',
'      , pi_sbfl_id => p_sbfl_id',
'      , pi_scope   => 0',
'      , pio_string => l_instance_name',
'      );',
'      update flow_processes prcs',
'         set prcs.prcs_name = l_instance_name',
'       where prcs.prcs_id   = p_prcs_id',
'       ;',
'    end if;',
'  end set_instance_name;',
'',
'',
'  function create_process',
'    ( p_dgrm_id         in flow_diagrams.dgrm_id%type',
'    , p_prcs_name       in flow_processes.prcs_name%type default null',
'    , p_logging_level   in flow_processes.prcs_logging_level%type default null',
'    , p_starting_object in flow_objects.objt_bpmn_id%type default null',
'    , p_auto_commit     in boolean default true',
'    ) return flow_processes.prcs_id%type',
'  is',
'    l_new_prcs_id            flow_processes.prcs_id%type;',
'    l_calc_logging_level     flow_processes.prcs_logging_level%type;',
'    l_instance_name          flow_processes.prcs_name%type;',
'    l_process_objt_bpmn_id   flow_objects.objt_bpmn_id%type;',
'  begin',
'    apex_debug.enter',
'    (''create_process''',
'    , ''dgrm_id'', p_dgrm_id',
'    , ''p_prcs_name'', p_prcs_name ',
'    , ''p_logging_level'', p_logging_level',
'    , ''p_starting_object'', p_starting_object',
'    );',
'',
'    if p_prcs_name is not null then',
'      l_instance_name := p_prcs_name;',
'    else',
'      select substr (dgrm.dgrm_name,1,50) || '' - '' || to_char(systimestamp,''DD-MON-YYYY HH24:MI:SS'')',
'        into l_instance_name',
'        from flow_diagrams dgrm',
'       where dgrm.dgrm_id = p_dgrm_id;',
'    end if;',
'',
'    insert into flow_processes prcs',
'          ( prcs.prcs_name',
'          , prcs.prcs_dgrm_id',
'          , prcs.prcs_status',
'          , prcs.prcs_init_ts',
'          , prcs.prcs_last_update',
'          , prcs.prcs_init_by',
'          )',
'    values',
'          ( l_instance_name',
'          , p_dgrm_id',
'          , flow_constants_pkg.gc_prcs_status_created',
'          , systimestamp',
'          , systimestamp',
'          , coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                      , sys_context(''userenv'',''os_user'')',
'                      , sys_context(''userenv'',''session_user'')',
'                      )  ',
'          )',
'      returning prcs.prcs_id into l_new_prcs_id',
'    ;',
'    -- build the call structure for the process instance and any diagram calls ',
'    create_call_structure ( p_prcs_id => l_new_prcs_id, p_dgrm_id => p_dgrm_id);',
'',
'    -- get the instance attributes',
'    get_instance_attributes ( p_prcs_id                   => l_new_prcs_id',
'                            , p_dgrm_id                   => p_dgrm_id',
'                            , p_starting_object           => p_starting_object',
'                            , p_requested_logging_level   => p_logging_level',
'                            , p_calculated_logging_level  => l_calc_logging_level',
'                            , p_process_bpmn_id           => l_process_objt_bpmn_id',
'                            );',
'',
'    -- update the process with the logging level',
'    update flow_processes prcs',
'       set prcs.prcs_logging_level    = l_calc_logging_level',
'         , prcs.prcs_process_bpmn_id  = l_process_objt_bpmn_id',
'     where prcs.prcs_id = l_new_prcs_id',
'       ;',
'',
'    -- log the process creation',
'    flow_logging.log_instance_event',
'    ( p_process_id  => l_new_prcs_id',
'    , p_event       => flow_constants_pkg.gc_prcs_event_created',
'    , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'    , p_comment     => ''Instance name set to '' || l_instance_name',
'    );',
'    ',
'    if p_auto_commit then',
'      commit;',
'    end if;',
'',
'    apex_debug.info',
'    ( p_message => ''Flow Instance created.  DGRM_ID : %0, PRCS_ID : %1, Logging Level: %2''',
'    , p0 => p_dgrm_id',
'    , p1 => l_new_prcs_id ',
'    , p2 => l_calc_logging_level ',
'    );',
'',
'    return l_new_prcs_id;',
'  end create_process;',
'',
'  procedure start_process',
'  ( p_process_id              in flow_processes.prcs_id%type',
'  , p_event_starting_object   in flow_objects.objt_bpmn_id%type default null -- only for messageStart, etc.',
'  , p_is_recursive_step       in boolean default false',
'  )',
'  is',
'    l_dgrm_id               flow_diagrams.dgrm_id%type;',
'    l_process_status        flow_processes.prcs_status%type;',
'    l_main_subflow          flow_types_pkg.t_subflow_context;',
'    l_new_subflow_status    flow_subflows.sbfl_status%type;',
'    l_priority_json         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority              flow_processes.prcs_priority%type;',
'    l_due_on_json           flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_due_on                flow_processes.prcs_due_on%type;',
'    l_starting_object       flow_objects%rowtype;',
'    l_instance_name_def     flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    apex_debug.enter',
'    (''start_process''',
'    , ''Process_ID'', p_process_id ',
'    , ''Event Starting Object'' , p_event_starting_object',
'    );',
'    -- check process exists, is not running, and lock it',
'    begin',
'',
'      flow_globals.set_is_recursive_step (p_is_recursive_step => p_is_recursive_step);',
'      -- initialise step_had_error flag',
'      flow_globals.set_step_error ( p_has_error => false);',
'',
'      select prcs.prcs_status',
'           , prcs.prcs_dgrm_id',
'        into l_process_status',
'           , l_dgrm_id',
'        from flow_processes prcs ',
'       where prcs.prcs_id = p_process_id',
'      for update wait 2',
'      ;',
'      if l_process_status != ''created'' then',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''start-already-running''',
'        , p0 => p_process_id',
'        );',
'        -- $F4AMESSAGE ''start-already-running'' || ''You tried to start a process (id %0) that is already running.''',
'      end if;',
'      ',
'    exception',
'      when no_data_found then',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''start-not-created''',
'        , p0 => p_process_id',
'        );',
'        -- $F4AMESSAGE ''start-not-created'' || ''You tried to start a process (id %0) that does not exist.'' ',
'      when too_many_rows then',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''start-multiple-already-running''',
'        , p0 => p_process_id',
'        );',
'        -- $F4AMESSAGE ''start-multiple-already-running'' || ''You tried to start a process (id %0) with multiple copies already running.'' ',
'    end;',
'',
'    if not flow_globals.get_step_error then',
'      -- get the starting object',
'      l_starting_object := flow_diagram.get_start_event ( p_dgrm_id               => l_dgrm_id',
'                                                        , p_process_id            => p_process_id',
'                                                        , p_event_starting_object => p_event_starting_object);',
'',
'    begin',
'      -- get instance scheduling information for the process being started',
'      select objt.objt_attributes."apex"."priority"',
'           , objt.objt_attributes."apex"."dueOn"',
'           , objt.objt_attributes."apex"."instanceName"  ',
'        into l_priority_json',
'           , l_due_on_json',
'           , l_instance_name_def ',
'        from flow_objects objt',
'       where objt.objt_dgrm_id  = l_dgrm_id',
'         and objt.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         and objt.objt_id       = l_starting_object.objt_objt_id',
'      ;',
'      if l_priority_json is not null then',
'        l_priority := flow_settings.get_priority ( pi_prcs_id => p_process_id, pi_expr => l_priority_json);',
'      end if;',
'      if l_due_on_json is not null then ',
'        l_due_on   := flow_settings.get_due_on (pi_prcs_id => p_process_id, pi_expr => l_due_on_json);',
'      end if;',
'      apex_debug.info (p_message => ''Process Priority : %0  Due On : %1'', p0 => l_priority, p1 => l_due_on );',
'    end;',
'',
'      if not flow_globals.get_step_error then',
'        -- mark process as running',
'        update flow_processes prcs',
'           set prcs.prcs_status         = flow_constants_pkg.gc_prcs_status_running',
'             , prcs.prcs_start_ts       = systimestamp',
'             , prcs.prcs_last_update    = systimestamp',
'             , prcs.prcs_last_update_by =  coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                     , sys_context(''userenv'',''os_user'')',
'                                                     , sys_context(''userenv'',''session_user'')',
'                                                     )  ',
'             , prcs.prcs_priority       = l_priority',
'             , prcs.prcs_due_on         = l_due_on',
'         where prcs.prcs_dgrm_id   = l_dgrm_id',
'           and prcs.prcs_id        = p_process_id',
'             ;    ',
'        -- log the start',
'        flow_logging.log_instance_event',
'        ( p_process_id  => p_process_id',
'        , p_event       => flow_constants_pkg.gc_prcs_event_started',
'        , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'        );',
'        -- create the status for new subflow based on start subtype',
'        case',
'          when l_starting_object.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition then',
'            l_new_subflow_status := flow_constants_pkg.gc_sbfl_status_waiting_timer;',
'          when (   l_starting_object.objt_sub_tag_name is null ',
'               or  l_starting_object.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_message_event_definition ) then',
'            l_new_subflow_status := flow_constants_pkg.gc_sbfl_status_running;',
'          else',
'            raise e_unsupported_start_event;',
'        end case;',
'',
'        if not flow_globals.get_step_error then',
'          -- create the main subflow',
'',
'          l_main_subflow := flow_engine_util.subflow_start ',
'            ( p_process_id => p_process_id',
'            , p_parent_subflow => null',
'            , p_starting_object => l_starting_object.objt_bpmn_id',
'            , p_current_object  => l_starting_object.objt_bpmn_id',
'            , p_route => ''main''',
'            , p_last_completed => null',
'            , p_status => l_new_subflow_status ',
'            , p_parent_sbfl_proc_level => 0 ',
'            , p_new_proc_level => false',
'            , p_dgrm_id => l_dgrm_id',
'            );',
'',
'          apex_debug.info',
'          ( p_message => ''Initial Subflow created %0 with Step Key %1''',
'          , p0 => l_main_subflow.sbfl_id',
'          , p1 => l_main_subflow.step_key',
'          );',
'          if l_starting_object.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition then ',
'            -- process any before-event variable expressions on the starting object',
'            flow_expressions.process_expressions',
'            ( pi_objt_bpmn_id   => l_starting_object.objt_bpmn_id',
'            , pi_set            => flow_constants_pkg.gc_expr_set_before_event',
'            , pi_prcs_id        => p_process_id',
'            , pi_sbfl_id        => l_main_subflow.sbfl_id',
'            , pi_step_key       => l_main_subflow.step_key',
'            , pi_var_scope      => l_main_subflow.scope',
'            , pi_expr_scope     => l_main_subflow.scope',
'            );',
'            -- test for any step errors',
'            if not flow_globals.get_step_error then ',
'',
'              -- set the instance name if defined',
'              if l_instance_name_def is not null then',
'                set_instance_name',
'                ( p_prcs_id => p_process_id',
'                , p_sbfl_id => l_main_subflow.sbfl_id',
'                , p_instance_name_def => l_instance_name_def',
'                );',
'              end if;',
'',
'              if not flow_globals.get_step_error then',
'    ',
'                -- start the timer',
'                flow_timers_pkg.start_timer',
'                (',
'                  pi_prcs_id    => p_process_id',
'                , pi_sbfl_id    => l_main_subflow.sbfl_id',
'                , pi_step_key   => l_main_subflow.step_key',
'                , pi_callback   => flow_constants_pkg.gc_bpmn_start_event',
'                ); ',
'              else',
'                -- set error status on instance and subflow',
'                flow_errors.set_error_status',
'                ( pi_prcs_id => p_process_id',
'                , pi_sbfl_id => l_main_subflow.sbfl_id',
'                );',
'',
'              end if;',
'            end if;       ',
'',
'          elsif (  l_starting_object.objt_sub_tag_name is null ',
'                or l_starting_object.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_message_event_definition ) then',
'            -- plain (none) startEvent or messageStartEvent',
'            -- process any variable expressions on the starting object',
'            flow_expressions.process_expressions',
'            ( pi_objt_bpmn_id  => l_starting_object.objt_bpmn_id',
'            , pi_set           => flow_constants_pkg.gc_expr_set_on_event',
'            , pi_prcs_id       => p_process_id',
'            , pi_sbfl_id       => l_main_subflow.sbfl_id',
'            , pi_step_key      => l_main_subflow.step_key',
'            , pi_var_scope     => l_main_subflow.scope',
'            , pi_expr_scope    => l_main_subflow.scope      ',
'            );',
'',
'            if not flow_globals.get_step_error then ',
'',
'              -- set the instance name if defined',
'              if l_instance_name_def is not null then',
'                set_instance_name',
'                ( p_prcs_id => p_process_id',
'                , p_sbfl_id => l_main_subflow.sbfl_id',
'                , p_instance_name_def => l_instance_name_def',
'                );',
'              end if;',
'',
'              if not flow_globals.get_step_error then ',
'                -- step into first step',
'                flow_engine.flow_complete_step  ',
'                ( p_process_id => p_process_id',
'                , p_subflow_id => l_main_subflow.sbfl_id',
'                , p_step_key   => l_main_subflow.step_key',
'                , p_forward_route => null',
'                , p_recursive_call => false',
'                );',
'              else ',
'                -- set error status on instance and subflow',
'                flow_errors.set_error_status',
'                ( pi_prcs_id => p_process_id',
'                , pi_sbfl_id => l_main_subflow.sbfl_id',
'                );',
'              end if;',
'            end if; -- not step error processing expressions',
'          else ',
'            raise e_unsupported_start_event;',
'          end if;',
'        else',
'          -- set error status on instance and subflow',
'          flow_errors.set_error_status',
'          ( pi_prcs_id => p_process_id',
'          , pi_sbfl_id => l_main_subflow.sbfl_id',
'          );',
'        end if; -- not step error creating main subflow',
'      end if; -- not step error finding start object and setting priority and due on',
'    end if; -- not step error finding a created process',
'',
'  exception',
'    when e_unsupported_start_event then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_process_id',
'      , pi_sbfl_id        => l_main_subflow.sbfl_id',
'      , pi_message_key    => ''start-type-unsupported''',
'      , p0                => l_starting_object.objt_sub_tag_name       ',
'      );',
'      -- $F4AMESSAGE ''start-type-unsupported'' || ''Unsupported start event type (%0). Only None (standard) Start Event, Message and Timer Start Event are currently supported.''',
'  end start_process;',
'',
'  procedure reset_process',
'    ( p_process_id  in flow_processes.prcs_id%type',
'    , p_comment     in flow_instance_event_log.lgpr_comment%type default null',
'    )',
'  is',
'    l_return_code   number;',
'  begin',
'    apex_debug.enter',
'    ( ''reset_process''',
'    , ''process_id'', p_process_id',
'    );',
'    -- lock all objects',
'    begin',
'      flow_engine_util.lock_all_for_process (p_process_id => p_process_id);',
'    exception ',
'      when lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''process-lock-timeout''',
'        , p0 => p_process_id          ',
'        );',
'        -- $F4AMESSAGE ''process-lock-timeout'' || ''Process objects for %0 currently locked by another user.  Try again later.''',
'    end;',
'',
'    -- kill any timers still running in the process',
'    flow_timers_pkg.terminate_process_timers',
'    ( pi_prcs_id => p_process_id',
'    , po_return_code => l_return_code',
'    );  ',
'    -- cancel any message subscriptions',
'    flow_message_util.cancel_instance_subscriptions',
'    ( p_process_id => p_process_id',
'    );',
'    -- cancel any apex human tasks',
'    flow_usertask_pkg.cancel_all_apex_tasks ( p_process_id => p_process_id );',
'    -- clear out run-time object_log',
'    delete',
'      from flow_subflow_log sflg ',
'     where sflg_prcs_id = p_process_id',
'    ;',
'    -- clean up iteration arrays',
'    delete',
'      from flow_iterated_objects',
'     where iobj_prcs_id = p_process_id',
'     ;',
'    -- clean up any adhoc subprocesses',
'    delete',
'      from flow_adhoc_subprocs ',
'     where ahsp_prcs_id = p_process_id',
'    ;',
'    -- delete the subflows',
'    delete',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'    ;',
'    -- delete all process variables except the builtins (new behaviour in 21.1)',
'    flow_proc_vars_int.delete_all_for_process ',
'    ( pi_prcs_id => p_process_id',
'    , pi_retain_builtins => true',
'    );',
'    -- reset the instance diagrams / call structure',
'    update flow_instance_diagrams prdg',
'    set prdg.prdg_diagram_level = null',
'    where prdg.prdg_prcs_id = p_process_id',
'      and prdg.prdg_diagram_level != 0',
'    ;',
'    -- reset the process status to ''created''',
'    update flow_processes prcs',
'       set prcs.prcs_status         = flow_constants_pkg.gc_prcs_status_created',
'         , prcs_start_ts            = null',
'         , prcs_complete_ts         = null',
'         , prcs_archived_ts         = null',
'         , prcs.prcs_last_update    = systimestamp',
'         , prcs.prcs_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'     where prcs.prcs_id = p_process_id',
'    ;',
'    -- log the reset',
'    flow_logging.log_instance_event',
'    ( p_process_id => p_process_id',
'    , p_event      => flow_constants_pkg.gc_prcs_event_reset',
'    , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'    , p_comment    => p_comment',
'    );',
'    commit;',
'  end reset_process;',
'',
'',
'  procedure suspend_process',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_c'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'omment     in flow_instance_event_log.lgpr_comment%type default null',
'    )',
'  is',
'    e_feature_requires_ee              exception;',
'    e_prcs_not_suspendable             exception;',
'    l_status                           flow_processes.prcs_status%type;',
'  begin',
'    $IF flow_apex_env.ee $THEN',
'      -- check current process state in running or errored',
'      select prcs_status',
'        into l_status',
'        from flow_processes',
'       where prcs_id = p_process_id;',
'',
'      if l_status not in ( flow_constants_pkg.gc_prcs_status_running ',
'                         , flow_constants_pkg.gc_prcs_status_error) then ',
'        raise e_prcs_not_suspendable;',
'      end if;',
'',
'      -- lock process, subflows, subflog log, subscriptions, prdg',
'      flow_engine_util.lock_all_for_process (p_process_id => p_process_id);',
'      flow_instances_util_ee.suspend_process (p_process_id => p_process_id);',
'',
'    $ELSE',
'      raise e_feature_requires_ee;',
'    $END',
'    -- if process status in (running, error)',
'  exception',
'    when e_feature_requires_ee then',
'      -- feature not supported without Enterprise Edition licence',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id      => p_process_id',
'      , pi_message_key  => ''feature-requires-ee''',
'      );',
'      -- F4A$MESSAGE ''feature-requires-ee'' || ''Processing this feature requires licensing Flows for APEX Enterprise Edition.''',
'      raise;',
'    when e_prcs_not_suspendable then',
'      -- only running or errored process can be suspended',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id      => p_process_id',
'      , pi_message_key  => ''suspend-invalid-status''',
'      );',
'      -- F4A$MESSAGE ''suspend-invalid-status'' || ''Only process instances currently in running or error status can be suspended.''',
'      raise;',
'  end suspend_process;',
'',
'  procedure resume_process',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_comment     in flow_instance_event_log.lgpr_comment%type default null',
'    )',
'  is',
'    e_feature_requires_ee              exception;',
'    e_prcs_not_suspended               exception;',
'    l_status                           flow_processes.prcs_status%type;',
'  begin',
'    $IF flow_apex_env.ee $THEN',
'      -- check current process state is suspended',
'      select prcs_status',
'        into l_status',
'        from flow_processes',
'       where prcs_id = p_process_id;',
'',
'      if l_status != flow_constants_pkg.gc_prcs_status_suspended then ',
'        raise e_prcs_not_suspended;',
'      end if;',
'',
'      -- lock process, subflows, subflog log, subscriptions, prdg',
'      flow_engine_util.lock_all_for_process (p_process_id => p_process_id);',
'      flow_instances_util_ee.resume_process (p_process_id => p_process_id);',
'',
'    $ELSE',
'      raise e_feature_requires_ee;',
'    $END',
'    -- if process status in (running, error)',
'  exception',
'    when e_feature_requires_ee then',
'      -- feature not supported without Enterprise Edition licence',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id      => p_process_id',
'      , pi_message_key  => ''feature-requires-ee''',
'      );',
'      -- F4A$MESSAGE ''feature-requires-ee'' || ''Processing this feature requires licensing Flows for APEX Enterprise Edition.''',
'      raise;',
'    when e_prcs_not_suspended then',
'      -- only suspended process can be resumed',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id      => p_process_id',
'      , pi_message_key  => ''resume-invalid-status''',
'      );',
'      -- F4A$MESSAGE ''resume-invalid-status'' || ''Only process instances currently in suspended status can be resumed.''',
'      raise;',
'  end resume_process;',
'',
'  procedure reset_process_to_running',
'  (',
'    p_subflow_rec  in flow_subflows%rowtype ',
'  , p_comment      in flow_instance_event_log.lgpr_comment%type default null',
'  ) ',
'  is',
'    l_num_error_subflows  number;',
'  begin',
'    -- tries to reset the process instance to running after subflow errors are cleared',
'    -- used on - subflow restart step, force next step, and resume process',
'    -- assumes the flow_processes record is already locked',
'    apex_debug.enter',
'    ( ''reset_process_to_running''',
'    , ''process_id'', p_subflow_rec.sbfl_prcs_id',
'    , ''subflow_id'', p_subflow_rec.sbfl_id',
'    );',
'    -- see if instance can be reset to running',
'    select count(sbfl_id)',
'      into l_num_error_subflows',
'      from flow_subflows sbfl ',
'     where sbfl.sbfl_prcs_id = p_subflow_rec.sbfl_prcs_id',
'       and sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_error ',
'    ;',
'    if l_num_error_subflows = 0 then',
'      update flow_processes prcs',
'         set prcs.prcs_status = flow_constants_pkg.gc_prcs_status_running',
'           , prcs.prcs_was_altered = ''Y''',
'           , prcs.prcs_last_update = systimestamp',
'           , prcs.prcs_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'       where prcs.prcs_id = p_subflow_rec.sbfl_prcs_id',
'      ;',
'      flow_logging.log_instance_event',
'      ( p_process_id    => p_subflow_rec.sbfl_prcs_id',
'      , p_objt_bpmn_id  => p_subflow_rec.sbfl_current',
'      , p_event         => flow_constants_pkg.gc_prcs_status_running',
'      , p_event_level   => flow_constants_pkg.gc_logging_level_abnormal_events',
'      );',
'    else',
'      -- mark instance as altered anyhow',
'      flow_instances.set_was_altered (p_process_id => p_subflow_rec.sbfl_prcs_id);',
'    end if;',
'  end reset_process_to_running;',
'',
'  procedure terminate_process',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_comment     in flow_instance_event_log.lgpr_comment%type default null',
'    )',
'  is',
'    l_return_code   number;',
'    cursor c_lock_all is ',
'      select prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated',
'        from flow_subflows sbfl',
'        join flow_processes prcs',
'          on prcs.prcs_id = sbfl.sbfl_prcs_id ',
'        join flow_subflow_log sflg ',
'          on prcs.prcs_id = sflg.sflg_prcs_id',
'       where prcs.prcs_id = p_process_id',
'       order by sbfl.sbfl_process_level, sbfl.sbfl_id',
'         for update of prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated wait 2;',
'  begin',
'    apex_debug.enter',
'    ( ''terminate_process''',
'    , ''process_id'', p_process_id',
'    );',
'    begin ',
'      -- lock all timers, logs, subflows and the process.  ',
'      open c_lock_all;',
'      flow_message_util.lock_instance_subscriptions ( p_process_id => p_process_id );',
'      flow_timers_pkg.lock_process_timers ( pi_prcs_id => p_process_id ); ',
'      close c_lock_all; ',
'    exception ',
'      when lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''process-lock-timeout''',
'        , p0 => p_process_id          ',
'        );',
'        -- $F4AMESSAGE ''process-lock-timeout'' || ''Process objects for %0 currently locked by another user.  Try again later.''',
'    end;',
'',
'    -- kill any message subscriptions or timers sill running in the process',
'    flow_message_util.cancel_instance_subscriptions ( p_process_id => p_process_id );',
'    flow_timers_pkg.delete_process_timers',
'    (',
'        pi_prcs_id => p_process_id',
'      , po_return_code => l_return_code',
'    );  ',
'    -- cancel any apex human tasks',
'    flow_usertask_pkg.cancel_all_apex_tasks ( p_process_id => p_process_id );',
'    -- stop processing ',
'    flow_engine_util.terminate_level',
'    ( p_process_id => p_process_id',
'    , p_process_level => 0',
'    );',
'    apex_debug.info',
'    ( p_message => ''Flow Instance %0 terminated''',
'    , p0        => p_process_id',
'    );',
'    -- mark process as terminated',
'    update flow_processes prcs',
'       set prcs.prcs_status = flow_constants_pkg.gc_prcs_status_terminated',
'         , prcs.prcs_last_update = systimestamp',
'         , prcs.prcs_complete_ts = systimestamp',
'         , prcs.prcs_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'     where prcs.prcs_id = p_process_id',
'    ; ',
'    -- log termination',
'    flow_logging.log_instance_event',
'    ( p_process_id => p_process_id',
'    , p_event      => flow_constants_pkg.gc_prcs_event_terminated',
'    , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'    , p_comment    => p_comment',
'    );',
'    -- finalize',
'    commit;',
'  end terminate_process;',
'',
'  procedure delete_process',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_comment     in flow_instance_event_log.lgpr_comment%type default null',
'    )',
'  is',
'    l_return_code             number;',
'    l_is_not_archived         boolean := false;',
'    l_cur_prcs_id             flow_processes.prcs_id%type;',
'    l_cur_sbfl_id             flow_subflows.sbfl_id%type;',
'    l_cur_sflg_updated        flow_subflow_log.sflg_last_updated%type;',
'    l_cur_prdg_id             flow_instance_diagrams.prdg_id%type;',
'    l_cur_prcs_archived_ts    flow_processes.prcs_archived_ts%type;',
'    cursor c_lock_all is ',
'      select prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated, prdg.prdg_id, prcs.prcs_archived_ts',
'        from flow_subflows sbfl',
'        join flow_processes prcs',
'          on prcs.prcs_id = sbfl.sbfl_prcs_id ',
'        join flow_subflow_log sflg ',
'          on prcs.prcs_id = sflg.sflg_prcs_id',
'        join flow_instance_diagrams prdg',
'          on prcs.prcs_id = prdg.prdg_prcs_id',
'       where prcs.prcs_id = p_process_id',
'       order by sbfl.sbfl_process_level, sbfl.sbfl_id',
'         for update of prcs.prcs_id, sbfl.sbfl_id, sflg.sflg_last_updated, prdg.prdg_id wait 2;',
'  begin',
'    apex_debug.enter',
'    ( ''delete_process''',
'    , ''process_id'', p_process_id',
'    );',
'    begin ',
'      -- lock all timers, logs, subflows, instance diagrams and the process',
'      open c_lock_all;',
'      fetch c_lock_all into l_cur_prcs_id',
'                          , l_cur_sbfl_id',
'                          , l_cur_sflg_updated',
'                          , l_cur_prdg_id',
'                          , l_cur_prcs_archived_ts;',
'      flow_message_util.lock_instance_subscriptions (p_process_id => p_process_id);',
'      flow_timers_pkg.lock_process_timers',
'      ( pi_prcs_id => p_process_id',
'      ); ',
'      if l_cur_prcs_archived_ts is null then',
'        l_is_not_archived := true;',
'      end if;',
'      close c_lock_all; ',
'',
'    exception ',
'      when lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''process-lock-timeout''',
'        , p0 => p_process_id          ',
'        );',
'        -- $F4AMESSAGE ''process-lock-timeout'' || ''Process objects for %0 currently locked by another user.  Try again later.''',
'    end;',
'    -- log the deletion before process data deleted',
'    flow_logging.log_instance_event',
'    ( p_process_id => p_process_id',
'    , p_event      => flow_constants_pkg.gc_prcs_event_deleted',
'    , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'    , p_comment    => p_comment',
'    );',
'    -- kill any message subscriptions or  timers still running in the instance',
'    flow_message_util.cancel_instance_subscriptions (p_process_id => p_process_id);',
'    flow_timers_pkg.delete_process_timers(',
'        pi_prcs_id => p_process_id',
'      , po_return_code => l_return_code',
'    );  ',
'    -- cancel any apex human tasks',
'    flow_usertask_pkg.cancel_all_apex_tasks ( p_process_id => p_process_id );',
'    -- if instance archiving is enabled and instance is not yet archived, run instance archive now before',
'    -- process data is deleted from run time tables to ensure archive is full audit trail',
'    if l_is_not_archived then',
'      if flow_engine_util.get_config_value ( p_config_key => flow_constants_pkg.gc_config_logging_archive_enabled ',
'                                           , p_default_value => flow_constants_pkg.gc_config_default_logging_archive_enabled',
'                                           ) = ''true'' ',
'      then',
'        flow_log_admin.archive_completed_instances (p_process_id => p_process_id);',
'      end if;',
'    end if;',
'    -- clear out run-time object_log',
'    delete',
'      from flow_subflow_log sflg ',
'     where sflg_prcs_id = p_process_id',
'    ;',
'    -- clear out any iterations',
'    delete',
'      from flow_iterated_objects',
'     where iobj_prcs_id = p_process_id',
'     ;',
'    -- clean up any adhoc subprocesses',
'    delete',
'      from flow_adhoc_subprocs ',
'     where ahsp_prcs_id = p_process_id',
'    ;',
'    delete',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'    ;',
'    flow_proc_vars_int.delete_all_for_process ',
'    ( pi_prcs_id => p_process_id',
'    , pi_retain_builtins => false',
'    );',
'    delete ',
'      from flow_instance_diagrams prdg',
'     where prdg_prcs_id = p_process_id',
'    ;',
'    delete',
'      from flow_processes prcs',
'     where prcs.prcs_id = p_process_id',
'    ;',
'',
'    commit;',
'  end delete_process;',
'',
'  procedure set_priority',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_priority    in flow_processes.prcs_priority%type',
'    )',
'  is',
'  begin',
'      update flow_processes prcs',
'      set prcs.prcs_priority = p_priority',
'        , prcs.prcs_last_update = systimestamp',
'        , prcs.prcs_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                              , sys_context(''userenv'',''os_user'')',
'                                              , sys_context(''userenv'',''session_user'')',
'                                              )  ',
'      where prcs.prcs_id = p_process_id;',
'      -- log the priority change',
'      flow_logging.log_instance_event',
'      ( p_process_id  => p_process_id',
'      , p_event       => flow_constants_pkg.gc_prcs_event_priority_set',
'      , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'      , p_comment     => ''Process priority set to ''||p_priority',
'      );      ',
'  end set_priority;',
'',
'  function priority',
'    ( p_process_id  in flow_processes.prcs_id%type',
'    ) return flow_processes.prcs_priority%type',
'  is',
'      l_priority    flow_processes.prcs_priority%type;',
'  begin',
'      select prcs_priority',
'        into l_priority',
'        from flow_processes',
'       where prcs_id = p_process_id;',
'      return l_priority;',
'  end priority;',
'',
'  procedure set_due_on',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    , p_due_on      in flow_processes.prcs_due_on%type',
'    )',
'  is',
'  begin',
'      update flow_processes prcs',
'      set prcs.prcs_due_on = p_due_on',
'        , prcs.prcs_last_update = systimestamp',
'        , prcs.prcs_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                              , sys_context(''userenv'',''os_user'')',
'                                              , sys_context(''userenv'',''session_user'')',
'                                              )  ',
'      where prcs.prcs_id = p_process_id;',
'      -- log the priority change',
'      flow_logging.log_instance_event',
'      ( p_process_id  => p_process_id',
'      , p_event       => flow_constants_pkg.gc_prcs_event_due_on_set',
'      , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'      , p_comment     => ''Instance Due On set to ''||to_char(p_due_on, flow_constants_pkg.gc_prov_default_tstz_format)',
'      );  ',
'  end set_due_on;',
'',
'  function due_on',
'    ( p_process_id  in flow_processes.prcs_id%type',
'    ) return flow_processes.prcs_due_on%type',
'  is',
'      l_due_on    flow_processes.prcs_due_on%type;',
'  begin',
'      select prcs_due_on',
'        into l_due_on',
'        from flow_processes',
'       where prcs_id = p_process_id;',
'      return l_due_on;',
'  end due_on;',
'',
'  function status',
'    ( p_process_id  in flow_processes.prcs_id%type',
'    ) return flow_processes.prcs_status%type',
'  is',
'      l_status    flow_processes.prcs_status%type;',
'  begin',
'      select prcs_status',
'        into l_status',
'        from flow_processes',
'       where prcs_id = p_process_id;',
'      return l_status;',
'  end status;',
'',
'  procedure set_was_altered',
'    (',
'      p_process_id  in flow_processes.prcs_id%type',
'    )',
'  is',
'  begin ',
'      update flow_processes prcs',
'      set prcs.prcs_was_altered = ''Y''',
'        , prcs.prcs_last_update = systimestamp',
'        , prcs.prcs_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                              , sys_context(''userenv'',''os_user'')',
'                                              , sys_context(''userenv'',''session_user'')',
'                                              )  ',
'      where prcs.prcs_id = p_process_id;',
'  end set_was_altered;',
'',
'  procedure set_logging_level',
'    (',
'      p_process_id      in flow_processes.prcs_id%type',
'    , p_logging_level  in flow_processes.prcs_logging_level%type',
'    )',
'  is',
'  begin',
'      -- check logging level is valid',
'      if p_logging_level not in ( flow_constants_pkg.gc_logging_level_none',
'                               , flow_constants_pkg.gc_logging_level_abnormal_events',
'                               , flow_constants_pkg.gc_logging_level_major_events',
'                               , flow_constants_pkg.gc_logging_level_routine',
'                               , flow_constants_pkg.gc_logging_level_full)',
'      then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_message_key    => ''invalid-logging-level''',
'        , p0                => p_logging_level       ',
'        );',
'        -- $F4AMESSAGE ''invalid-logging-level'' || ''Invalid logging level (%0) specified. Valid levels are none, abnormal_events, major_events, routine, full.''',
'      end if; ',
'      ',
'      update flow_processes prcs',
'      set prcs.prcs_logging_level = p_logging_level',
'        , prcs.prcs_last_update = systimestamp',
'        , prcs.prcs_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                              , sys_context(''userenv'',''os_user'')',
'                                              , sys_context(''userenv'',''session_user'')',
'                                              )  ',
'      where prcs.prcs_id = p_process_id;',
'      -- log the logging level change',
'      flow_logging.log_instance_event',
'      ( p_process_id  => p_process_id',
'      , p_event       => flow_constants_pkg.gc_prcs_event_logging_level_set',
'      , p_event_level => flow_constants_pkg.gc_logging_level_major_events',
'      , p_comment     => ''Process logging level set to ''||p_logging_level',
'      );      ',
'  end set_logging_level;  ',
'',
'end flow_instances;',
'/',
'',
'create or replace package body flow_log_admin as',
'  /* ',
'  -- Flows for APEX - flow_log_admin.pkb',
'  -- ',
'  -- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'  -- (c) Copyright Flowquest Consulting Limited. 2024-25',
'  --',
'  -- Created    18-Feb-2023  Richard Allen (Oracle)',
'  -- Modified   11-Feb-2024  Richard Allen (Flowquest Consulting)',
'  --',
'  -- Package flow_log_admin manages the Flows for APEX log tables, including',
'  --    - creation of instance archive summary',
'  --    - archiving of instance logs',
'  --    - purging of instance log tables ',
'  */  ',
'',
'  type t_archive_location is record',
'  ( destination_type               flow_types_pkg.t_vc200',
'  , db_table_name                  flow_types_pkg.t_vc200',
'  , db_id_column                   flow_types_pkg.t_vc200',
'  , db_timestamp_column            flow_types_pkg.t_vc200',
'  , db_blob_column                 flow_types_pkg.t_vc200',
'  , oci_base_url                   flow_types_pkg.t_vc200',
'  , oci_bucket_name                flow_types_pkg.t_vc200',
'  , oci_document_prefix            flow_types_pkg.t_vc200',
'  , oci_request_url                flow_types_pkg.t_vc200  -- url to use for request',
'  , oci_credential_static_id       flow_types_pkg.t_vc200  -- APEX Static ID of Credential',
'  );',
'',
'  function get_instance_json_summary',
'  ( p_process_id     in flow_processes.prcs_id%type',
'  ) return clob',
'  is',
'    l_archive_json    clob;',
'  begin',
'    with p as',
'       (  select prcs_id',
'               , prcs_dgrm_id',
'               , prcs_name',
'               , prcs_priority',
'               , prcs_status',
'               , prcs_init_ts',
'               , prcs_init_by',
'               , prcs_start_ts',
'               , prcs_complete_ts',
'               , prcs_was_altered',
'               , prcs_due_on',
'          from   flow_processes prcs',
'          where  prcs_id = p_process_id               ',
'      ),',
'     s as',
'        ( select distinct sc.lgvr_scope scope, sc.lgvr_prcs_id',
'          from   flow_variable_event_log sc',
'        )',
'    select json_object (',
'       ''processID''        value p.prcs_id,',
'       ''mainDiagram''      value p.prcs_dgrm_id,',
'       ''processName''      value p.prcs_name,',
'       ''businessID''       value prov.prov_var_vc2,',
'       ''priority''         value p.prcs_priority,',
'       ''prcs_status''      value p.prcs_status,',
'       ''prcs_was_altered'' value p.prcs_was_altered,',
'       ''prcs_init_ts''     value p.prcs_init_ts,',
'       ''prcs_init_by''     value p.prcs_init_by,',
'       ''prcs_due_on''      value p.prcs_due_on,',
'       ''prcs_start_ts''    value p.prcs_start_ts,',
'       ''prcs_complete_ts'' value p.prcs_complete_ts,',
'       ''json_created''     value systimestamp,',
'       ''diagramsUsed''     value',
'            (select json_arrayagg ',
'                       ( json_object ',
'                           (',
'                           ''diagramLevel''               value prdg_diagram_level,',
'                           ''diagramId''                  value prdg_dgrm_id,',
'                           ''diagramName''                value dgrm_name,',
'                           ''diagramVersion''             value dgrm_version,',
'                           ''diagramStatus''              value dgrm_status,',
'                           ''callingDiagram''             value prdg_calling_dgrm,',
'                           ''callingObject''              value prdg_calling_objt',
'                           ) order by prdg_diagram_level asc ',
'                       returning clob)',
'               from flow_instance_diagrams prdg',
'               join flow_diagrams dgrm',
'                 on dgrm.dgrm_id = prdg.prdg_dgrm_id',
'              where prdg.prdg_prcs_id = p.prcs_id   ',
'           ),',
'       ''events'' : ',
'           (select json_arrayagg ',
'                       ( json_object ',
'                           (',
'                           ''event''                      value lgpr_prcs_event,',
'                           ''severity''                   value lgpr_severity,',
'                           ''object''                     value lgpr_objt_id,',
'                           ''stepKey''                    value lgpr_step_key,',
'                           ''subflowID''                  value lgpr_sbfl_id,',
'                           ''processLevel''               value lgpr_process_level,',
'                           ''diagram''                    value lgpr_dgrm_id,',
'                           ''timestamp''                  value lgpr_timestamp,',
'                           ''user''                       value lgpr_user,',
'                           ''error-info''                 value lgpr_error_info,',
'                           ''apexTaskId''                 value lgpr_apex_task_id,',
'                           ''comment''                    value lgpr_comment absent on null',
'                           ) order by lgpr_timestamp ',
'                        returning clob )',
'              from flow_instance_event_log lgpr',
'             where lgpr.lgpr_prcs_id = p.prcs_id',
'           ),       ',
'       ''steps'' :',
'           (select json_arrayagg',
'                       (json_object ',
'                           (',
'                           ''object''                     value lgsf_objt_id,',
'                           ''subflowID''                  value lgsf_sbfl_id,',
'                           ''stepKey''                    value lgsf_step_key,',
'                           ''processLevel''               value lgsf_sbfl_process_level,',
'                           ''priority''                   value lgsf_priority,',
'                           ''lastCompleted''              value lgsf_last_completed,',
'                           ''wasCurrent''                 value lgsf_was_current,',
'                           ''wasStarted''                 value lgsf_started,',
'                           ''wasCompleted''               value lgsf_completed,',
'                           ''statusWhenComplete''         Value lgsf_status_when_complete,',
'                           ''subflowDiagram''             value lgsf_sbfl_dgrm_id,',
'                           ''reservation''                value lgsf_reservation,',
'                           ''priority''                   value lgsf_priority,',
'                           ''dueOn''                      value lgsf_due_on,',
'                           ''user''                       value lgsf_user,',
'                           ''comment''                    value lgsf_comment absent on null',
'                           ) order by lgsf_was_current',
'                       returning clob )',
'             from flow_step_event_log lgsf',
'            where lgsf.lgsf_prcs_id = p.prcs_id',
'            ),',
'       ''processVariablesSet'' :',
'               (  select json_arrayagg (',
'                       json_object (',
'                           ''scope''         value s.scope,',
'                           ''variables''     value',
'                               ( select json_arrayagg ',
'                                           (',
'                                           json_object ',
'                                               (',
'                                               ''var_name''        value lgvr.lgvr_var_name,',
'                                               ''subflowID''       value lgvr.lgvr_sbfl_id,',
'                                               ''objectId''        value lgvr.lgvr_objt_id,',
'                                               ''expr_set''        value lgvr.lgvr_expr_set,',
'                                               ''type''            value lgvr.lgvr_var_type,',
'                                               ''timestamp''       value lgvr.lgvr_timestamp,',
'                                               ''user''            value lgvr.lgvr_user,',
'                                               ''newValue''        value case lgvr.lgvr_var_type',
'                                                          when ''VARCHAR2''                   then lgvr.lgvr_var_vc2',
'                                                          when ''NUMBER''                     then to_char(lgvr.lgvr_var_num)',
'                                                          when ''DATE''                       then to_char(lgvr.lgvr_var_date,''YYYY-MM-DD"T"HH24:MI:SS"Z"'')',
'                                                          when ''TIMESTAMP WITH TIME ZONE''   then to_char(lgvr.lgvr_var_tstz,''YYYY-MM-DD"T"HH24:MI:SSTZR'')',
'                                                          when ''CLOB''                       then ''CLOB Value''',
'                                                          when ''JSON''                       then cast(dbms_lob.substr(lgvr_var_json, 4000) as  varchar2(4000))',
'                                                          end ',
'                                               )',
'                                           order by lgvr.lgvr_timestamp ',
'                                           returning clob )',
'                                   from flow_variable_event_log lgvr',
'                                  where lgvr.lgvr_prcs_id = p.prcs_id',
'                                    and lgvr.lgvr_scope   = s.scope',
'                               ) returning clob',
'                           )',
'                       returning clob )',
'                   from s',
'                  where s.lgvr_prcs_id = p.prcs_id',
'               )',
'           returning clob )',
'     into l_archive_json',
'     from p ',
'     left join flow_process_variables prov',
'       on prov.prov_prcs_id    = p.prcs_id',
'      and prov.prov_var_name   = ''BUSINESS_REF''',
'      and prov.prov_scope      = 0',
'    ;',
'    return l_archive_json;',
'  end get_instance_json_summary;',
'',
'  procedure purge_instance_logs',
'  ( p_retention_period_days  in number default null',
'  )',
'  is',
'    l_log_retain_days    flow_configuration.cfig_value%type;',
'    l_purge_interval     interval day(4) to second(0);',
'  begin',
'    apex_debug.enter (''purge_instance_logs''',
'    , ''p_retention_period_days'', p_retention_period_days);',
'',
'    -- if retention period not specified, get configuration parameter or default',
'    if p_retention_period_days is null then',
'      l_log_retain_days     := flow_engine_util.get_config_value ',
'                               ( p_config_key  => flow_constants_pkg.gc_config_logging_retain_logs',
'                               , p_default_value  => flow_constants_pkg.gc_config_default_log_retain_logs',
'                               );   ',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from l_log_retain_days)||''D'');',
'    else',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from p_retention_period_days)||''D'');   ',
'    end if;',
'    -- delete',
'    delete from flow_variable_event_log',
'    where lgvr_prcs_id in (select lgpr_prcs_id',
'                           from   flow_instance_event_log',
'                           where  lgpr_prcs_event = flow_constants_pkg.gc_prcs_event_completed',
'                           and    lgpr_timestamp < systimestamp - l_purge_interval);',
'',
'',
'    delete from flow_step_event_log',
'    where lgsf_prcs_id in (select lgpr_prcs_id',
'                           from   flow_instance_event_log',
'                           where  lgpr_prcs_event = flow_constants_pkg.gc_prcs_event_completed',
'             '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'              and    lgpr_timestamp < systimestamp - l_purge_interval);',
'',
'    delete from flow_instance_event_log',
'    where lgpr_prcs_id in (select lgpr_prcs_id',
'                           from   flow_instance_event_log',
'                           where  lgpr_prcs_event = flow_constants_pkg.gc_prcs_event_completed',
'                           and    lgpr_timestamp < systimestamp - l_purge_interval);',
'',
'    flow_log_admin.purge_message_logs(p_retention_period_days => p_retention_period_days);',
'',
'    flow_log_admin.purge_rest_logs(p_retention_period_days => p_retention_period_days);',
'',
'  end purge_instance_logs;',
'',
'  procedure purge_message_logs',
'  ( p_retention_period_days    in number default null',
'  )',
'  is',
'    l_log_retain_days    flow_configuration.cfig_value%type;',
'    l_purge_interval     interval day(4) to second(0);',
'  begin',
'    apex_debug.enter (''purge_message_logs''',
'    , ''p_retention_period_days'', p_retention_period_days);',
'',
'    -- if retention period not specified, get configuration parameter or default',
'    if p_retention_period_days is null then',
'      l_log_retain_days     := flow_engine_util.get_config_value ',
'                               ( p_config_key  => flow_constants_pkg.gc_config_logging_retain_msg_flow ',
'                               , p_default_value  => flow_constants_pkg.gc_config_default_log_retain_msg_flow_logs',
'                               );   ',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from l_log_retain_days)||''D'');',
'    else',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from p_retention_period_days)||''D'');   ',
'    end if;',
'',
'    delete from flow_message_received_log',
'    where lgrx_received_on < systimestamp - l_purge_interval;',
'',
'  end purge_message_logs;',
'',
'  procedure purge_rest_logs',
'  ( p_retention_period_days    in number default null',
'  )',
'  is',
'    l_log_retain_days    flow_configuration.cfig_value%type;',
'    l_purge_interval     interval day(4) to second(0);',
'  begin',
'    apex_debug.enter (''purge_rest_logs''',
'    , ''p_retention_period_days'', p_retention_period_days);',
'',
'    -- if retention period not specified, get configuration parameter or default',
'    if p_retention_period_days is null then',
'      l_log_retain_days     := flow_engine_util.get_config_value ',
'                               ( p_config_key  => flow_rest_logging.c_log_rest_incoming_retain_days',
'                               , p_default_value  => flow_rest_logging.c_log_rest_incoming_retain_days_default',
'                               );   ',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from l_log_retain_days)||''D'');',
'    else',
'      l_purge_interval   := to_dsinterval (''P''||trim( both from p_retention_period_days)||''D'');   ',
'    end if;',
'',
'    delete from flow_rest_event_log',
'    where lgrt_timestamp < systimestamp - l_purge_interval;',
'',
'  end purge_rest_logs;',
'',
'  function get_archive_location',
'  ( p_archive_type   in varchar2',
'  )',
'  return t_archive_location',
'  is',
'    l_archive_location              t_archive_location;',
'    l_destination_json              flow_configuration.cfig_value%type;',
'  begin',
'    apex_debug.enter ( ''get_archive_location'');',
'',
'    l_destination_json      := flow_engine_util.get_config_value ',
'                             ( p_config_key  => p_archive_type',
'                             , p_default_value  => null);',
'',
'         ',
'    if l_destination_json is null then',
'      raise e_archive_destination_null;',
'    end if;   ',
'    apex_debug.message ',
'    ( p_message => ''Retrieved configuration parameter %0 contents %1''',
'    , p0 => p_archive_type',
'    , p1 => l_destination_json',
'    );             ',
'    -- dbms_output.put_line(''archive destination''||l_destination_json);',
'    apex_json.parse (p_source => l_destination_json);',
'',
'    l_archive_location.destination_type            := apex_json.get_varchar2 (p_path => ''destinationType'');',
'',
'    apex_debug.message (p_message => ''--- Destination Type : %0'', p0=> l_archive_location.destination_type);  ',
'    -- dbms_output.put_line(''--- Destination Type : ''||l_archive_location.destination_type);',
'',
'    case l_archive_location.destination_type ',
'    when flow_constants_pkg.gc_config_archive_destination_table then',
'      l_archive_location.db_table_name             := apex_json.get_varchar2 (p_path => ''tableDetails.tableName'');',
'      l_archive_location.db_id_column              := apex_json.get_varchar2 (p_path => ''tableDetails.idColumn'');',
'      l_archive_location.db_timestamp_column       := apex_json.get_varchar2 (p_path => ''tableDetails.timestampColumn'');',
'      l_archive_location.db_blob_column            := apex_json.get_varchar2 (p_path => ''tableDetails.blobColumn'');',
'',
'    when flow_constants_pkg.gc_config_archive_destination_oci_api then',
'      l_archive_location.oci_base_url              := apex_json.get_varchar2 (p_path => ''ociApiDetails.baseUrl'');',
'      apex_debug.message (p_message => ''--- Base URL : %0'', p0=> l_archive_location.oci_base_url);  ',
'      l_archive_location.oci_bucket_name           := apex_json.get_varchar2 (p_path => ''ociApiDetails.bucketName'');',
'      apex_debug.message (p_message => ''--- Bucket Name : %0'', p0=> l_archive_location.oci_bucket_name);',
'      l_archive_location.oci_document_prefix       := apex_json.get_varchar2 (p_path => ''ociApiDetails.documentPrefix'');',
'      l_archive_location.oci_credential_static_id  := apex_json.get_varchar2 (p_path => ''ociApiDetails.credentialApexStaticId'');',
'',
'      l_archive_location.oci_request_url :=  l_archive_location.oci_base_url',
'                                         || ''b/'' ',
'                                         || l_archive_location.oci_bucket_name ',
'                                         || ''/o/'';',
'      apex_debug.message (p_message => ''--- Request URL : %0'', p0=> l_archive_location.oci_request_url);',
'    when flow_constants_pkg.gc_config_archive_destination_oci_preauth then',
'      l_archive_location.oci_request_url           := apex_json.get_varchar2 (p_path => ''ociPreAuthDetails.preAuthUrl'');',
'      apex_debug.message (p_message => ''--- Request URL : %0'', p0=> l_archive_location.oci_request_url);',
'      l_archive_location.oci_document_prefix       := apex_json.get_varchar2 (p_path => ''ociPreAuthDetails.documentPrefix'');',
'      l_archive_location.oci_credential_static_id  := apex_json.get_varchar2 (p_path => ''ociPreAuthDetails.credentialApexStaticId'');',
'    end case;',
'    return l_archive_location;',
'    exception',
'    when e_archive_destination_null then',
'        raise;',
'      when others then ',
'        apex_debug.info ',
'        ( p_message => '' --- Error in %0 configuration parameter definition. Value :''',
'        , p0  => flow_constants_pkg.gc_config_logging_archive_location',
'        , p1  => l_destination_json',
'        );',
'        raise e_archive_bad_destination_json;',
'  end get_archive_location;',
'',
'  procedure archive_to_database',
'  ( p_object_id         in number',
'  , p_archive           in blob',
'  , p_archive_location  in t_archive_location',
'  )',
'  is',
'    l_insert_sql           varchar2(4000);',
'    l_update_sql           varchar2(4000);',
'    e_db_archive_fail      exception;',
'',
'  begin',
'    apex_debug.enter ( ''archive_to_database'',',
'    ''instance'', p_object_id',
'    );   ',
'',
'    l_insert_sql := ''insert into ''',
'                    ||p_archive_location.db_table_name',
'                    ||'' ( '' ||p_archive_location.db_id_column ',
'                    ||'' , '' ||p_archive_location.db_timestamp_column ',
'                    ||'' , '' ||p_archive_location.db_blob_column',
'                    ||'' ) values ( :1, systimestamp,  :2 )''',
'                    ;',
'    execute immediate l_insert_sql using p_object_id, p_archive;',
'    apex_debug.message ',
'    ( p_message => ''-- Object %0 inserted into archive to %1.%2''',
'    , p0 => p_object_id',
'    , p1 => p_archive_location.db_table_name',
'    , p2 => p_archive_location.db_blob_column',
'    ); ',
'  exception',
'  /*  when dup_val_on_index then  -- added timestap column so this will not be called now...',
'      -- handle re-archive if the archive already exists.   This usually occurs if the process ',
'      -- was reset after archiving.',
'      l_update_sql := ''update ''',
'                      ||p_archive_location.db_table_name',
'                      ||'' set ''',
'                      ||p_archive_location.db_blob_column',
'                      ||'' = :1 where ''',
'                      ||p_archive_location.db_id_column',
'                      ||'' = :2 ''',
'                      ;',
'      execute immediate l_update_sql using p_archive, p_object_id;',
'      apex_debug.message ',
'      ( p_message => ''-- Object %0 archive updated in %1.%2''',
'      , p0 => p_object_id',
'      , p1 => p_archive_location.db_table_name',
'      , p2 => p_archive_location.db_blob_column',
'      ); */',
'    when others then',
'      apex_debug.message ',
'      ( p_message => ''Archiving object %0 into database column %1.%2 failed. Failed SQL: %3.''',
'      , p0 => p_object_id',
'      , p1 => p_archive_location.db_table_name',
'      , p2 => p_archive_location.db_blob_column',
'      , p3 => l_insert_sql',
'      ); ',
'      raise e_db_archive_fail;',
'  end archive_to_database;',
'',
'  procedure archive_to_oci',
'  ( p_archive           in blob',
'  , p_archive_location  in t_archive_location',
'  , p_object_name       in varchar2',
'  , p_content_type      in varchar2',
'  )',
'  is',
'    l_url                       varchar2(4000);',
'    l_response                  clob;',
'    e_upload_failed_exception   exception;',
'  begin',
'    l_url := p_archive_location.oci_request_url',
'              ||p_archive_location.oci_document_prefix',
'              ||p_object_name;',
'    apex_debug.message ',
'    ( p_message => ''Preparing Archive URL - URL : %0 Credential Static ID: %1''',
'    , p0 => l_url',
'    , p1 => p_archive_location.oci_credential_static_id',
'    );',
'    apex_web_service.g_request_headers(1).name :=  ''Content-Type'';',
'    apex_web_service.g_request_headers(1).value :=  p_content_type;',
'    l_response :=  apex_web_service.make_rest_request',
'                   ( p_url          => l_url',
'                   , p_http_method  => ''PUT''',
'                   , p_body_blob    => p_archive',
'                   , p_credential_static_id => p_archive_location.oci_credential_static_id',
'                   );',
'    if apex_web_service.g_status_code != 200 then',
'      raise e_upload_failed_exception;',
'    end if;',
'  end archive_to_oci;',
'',
'  function archive_bpmn_diagram',
'  ( p_dgrm_id            flow_diagrams.dgrm_id%type',
'  , p_dgrm_content       flow_diagrams.dgrm_content%type',
'  ) return flow_flow_event_log.lgfl_dgrm_archive_location%type',
'  is',
'    l_archive_blob        blob;',
'    l_archive_location    t_archive_location;',
'    l_timestamp           timestamp with time zone;',
'    l_stored_location     flow_flow_event_log.lgfl_dgrm_archive_location%type;',
'    l_object_name         flow_flow_event_log.lgfl_dgrm_archive_location%type;',
'  begin',
'    -- fix timestamp',
'    l_timestamp := systimestamp at time zone ''UTC'';',
'    -- create bpmn blob',
'    l_archive_blob := flow_engine_util.clob_to_blob( pi_clob  => p_dgrm_content );',
'    -- get archive location',
'    l_archive_location := get_archive_location (p_archive_type => flow_constants_pkg.gc_config_logging_bpmn_location);',
'    -- store in preferred location',
'    case l_archive_location.destination_type',
'    when flow_constants_pkg.gc_config_archive_destination_table then',
'      archive_to_database ( p_object_id        => p_dgrm_id',
'                          , p_archive          => l_archive_blob',
'                          , p_archive_location => l_archive_location',
'                          );',
'      return l_archive_location.db_table_name;',
'    when flow_constants_pkg.gc_config_archive_destination_oci_api then',
'      l_object_name := trim(to_char(p_dgrm_id,''099999''))||''-''||to_char(l_timestamp,''YYYYMMDD-HH24MISS'')||''.bpmn'';',
'      archive_to_oci      ( p_archive          => l_archive_blob',
'                          , p_archive_location => l_archive_location',
'                          , p_object_name      => l_object_name',
'                          , p_content_type     => flow_constants_pkg.gc_mime_type_bpmn',
'                          );   ',
'      return l_object_name;',
'    when flow_constants_pkg.gc_config_archive_destination_oci_preauth then',
'      l_object_name := trim(to_char(p_dgrm_id,''099999''))||''-''||to_char(l_timestamp,''YYYYMMDD-HH24MISS'')||''.bpmn'';',
'      archive_to_oci      ( p_archive          => l_archive_blob',
'                          , p_archive_location => l_archive_location',
'                          , p_object_name      => l_object_name',
'                          , p_content_type     => flow_constants_pkg.gc_mime_type_bpmn',
'                          );  ',
'      return l_object_name;',
'    end case;',
'  end archive_bpmn_diagram;',
'',
'  procedure archive_instance',
'  ( p_process_id         flow_processes.prcs_id%type',
'  , p_archive_location   t_archive_location',
'  )',
'  is',
'    l_archive_blob   blob;',
'  begin',
'    -- create instance summary json',
'    l_archive_blob := flow_engine_util.clob_to_blob( pi_clob  => get_instance_json_summary (p_process_id => p_process_id) );',
'    -- store in preferred location',
'    case p_archive_location.destination_type',
'    when flow_constants_pkg.gc_config_archive_destination_table then',
'      archive_to_database ( p_object_id        => p_process_id',
'                          , p_archive          => l_archive_blob',
'                          , p_archive_location => p_archive_location',
'                          );',
'    when flow_constants_pkg.gc_config_archive_destination_oci_api then',
'      archive_to_oci      ( p_archive          => l_archive_blob',
'                          , p_archive_location => p_archive_location',
'                          , p_object_name      => trim(to_char(p_process_id,''09999999''))||''.json''',
'                          , p_content_type     => flow_constants_pkg.gc_mime_type_json',
'                          );  ',
'    when flow_constants_pkg.gc_config_archive_destination_oci_preauth then',
'      archive_to_oci      ( p_archive          => l_archive_blob',
'                          , p_archive_location => p_archive_location',
'                          , p_object_name      => trim(to_char(p_process_id,''09999999''))||''.json''',
'                          , p_content_type     => flow_constants_pkg.gc_mime_type_json',
'                          );  ',
'    end case;',
'    -- update instance with archive timestamp',
'    update flow_processes',
'    set prcs_archived_ts = systimestamp',
'      , prcs_last_update = systimestamp',
'    where prcs_id = p_process_id;',
'  end archive_instance;',
'',
'  procedure archive_completed_instances',
'  ( p_completed_before         in date default trunc(sysdate)',
'  , p_process_id               in flow_processes.prcs_id%type default null  ',
'  )',
'  is',
'    type t_instance           is record (',
'      prcs_id                 flow_processes.prcs_id%type);',
'    type t_instances          is table of t_instance;',
'',
'    l_response                clob;',
'    l_archive_location        t_archive_location;',
'    l_instances               t_instances;',
'',
'    e_upload_failed_exception exception;',
'  begin',
'    apex_debug.enter (''archive_completed_instances''',
'    ,''p_completed_before'',p_completed_before',
'    , ''p_process_id'', p_process_id',
'    );',
'    -- get list of process instances to archive, if a single p_process_id was not passed in.',
'    -- get all completed (''completed'' or ''terminated'') non-archived instances',
'    -- dbms_output.put_line(''Archiving starting'');',
'    if p_process_id is null then',
'      select prcs.prcs_id',
'        bulk collect into l_instances',
'        from flow_processes prcs',
'       where prcs.prcs_status in ( flow_constants_pkg.gc_prcs_status_completed',
'                                 , flow_constants_pkg.gc_prcs_status_terminated )',
'         and trunc(prcs.prcs_complete_ts) < p_completed_before',
'         and prcs.prcs_archived_ts is null',
'      ;',
'    else',
'      select p_process_id',
'        bulk collect into l_instances',
'        from dual;',
'    end if;',
'',
'    apex_debug.message (p_message => ''Instances to be Archived : %0''',
'    , p0 => l_instances.count);',
'',
'    if l_instances.count > 0 then',
'      -- dbms_output.put_line(''getting location'');',
'      -- get archive location',
'      l_archive_location := get_archive_location (p_archive_type => flow_constants_pkg.gc_config_logging_archive_location);',
'      --dbms_output.put_line(''got location'');',
'      -- loop over instances',
'      for instance in 1 .. l_instances.count',
'      loop',
'        -- lock flow_processes?',
'        -- dbms_output.put_line(''Archiving process ''||l_instances(instance).prcs_id);',
'        archive_instance ( p_process_id => l_instances(instance).prcs_id',
'                         , p_archive_location => l_archive_location',
'                         );',
'        ',
'        -- commit?',
'      end loop;      ',
'    end if;',
'  exception  ',
'    when e_archive_destination_null then',
'      flow_errors.handle_general_error',
'      ( pi_message_key  => ''archive-destination-null''',
'      , p0 => flow_constants_pkg.gc_config_logging_archive_location',
'      );',
'      -- $F4AMESSAGE ''archive-destination-null'' || ''No archive or logging destination has been configured - See Configurations > Logging or Archiving''',
'      raise;',
'    when e_archive_bad_destination_json then',
'      flow_errors.handle_general_error',
'      ( pi_message_key  => ''archive-destination-bad-json''',
'      , p0 => flow_constants_pkg.gc_config_logging_archive_location',
'      );',
'      -- $F4AMESSAGE ''archive-destination-bad-json'' || ''Error in archive destination configuration parameter.  Parameter: %0''',
'      raise;',
'    when e_upload_failed_exception then',
'      flow_errors.handle_general_error( pi_message_key  => ''log-archive-error''',
'                                      , p0 => apex_web_service.g_status_code);',
'      -- $F4AMESSAGE ''log-archive-error'' || ''Error occurred while archiving log for process %0.''',
'      raise;',
'    ',
'    when others then',
'      flow_errors.handle_general_error( pi_message_key  => ''log-archive-error''',
'                                      , p0 => apex_web_service.g_status_code);',
'      -- $F4AMESSAGE ''log-archive-error'' || ''Error occurred while archiving log for process %0.''',
'      raise;',
'  end archive_completed_instances;',
'',
'end flow_log_admin;',
'/',
'',
'create or replace package body flow_logging as',
'/* ',
'-- Flows for APEX - flow_logging.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022-2023.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and / or its affiliates, 2025.',
'--',
'-- Created 29-Jul-2021  Richard Allen (Flowquest) for  MT AG',
'-- Updated 10-Feb-2023  Richard Allen (Oracle)  ',
'-- Updated 25-Feb-2025  Richard Allen (Flowquest Limited)',
'--',
'*/',
'  g_logging_level           flow_configuration.cfig_value%type; ',
'  g_logging_hide_userid     flow_configuration.cfig_value%type;',
'',
'  function event_logging_level ',
'  ( p_prcs_id in flow_processes.prcs_id%type',
'  ) return flow_configuration.cfig_value%type',
'  is',
'    l_logging_level  flow_processes.prcs_logging_level%type;',
'  begin ',
'    -- gets logging level for run-time events - so instance, step, and variable logging events',
'    select prcs_logging_level',
'      into l_logging_level',
'      from flow_processes',
'     where prcs_id = p_prcs_id',
'    ;',
'    return l_logging_level;',
'  exception',
'    when no_data_found then',
'      return 0;',
'    when others then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''logging-event-level''',
'      );',
'      -- $F4AMESSAGE ''logging-event-level'' || ''Flows - Internal error while getting the logging level''',
'      raise;',
'  end event_logging_level;',
'',
'  function diagram_logging_level  ',
'  return flow_configuration.cfig_value%type',
'  is',
'  begin',
'    -- gets logging level for diagram events',
'    return flow_engine_util.get_config_value',
'                       ( p_config_key => flow_constants_pkg.gc_config_logging_bpmn_enabled',
'                       , p_default_value => flow_constants_pkg.gc_config_default_logging_bpmn_enabled',
'                       );',
'  end;',
'',
'  procedure log_diagram_event',
'  ( p_dgrm_id           in flow_diagrams.dgrm_id%type',
'  , p_dgrm_name         in flow_diagrams.dgrm_name%type default null',
'  , p_dgrm_version      in flow_diagrams.dgrm_version%type default null',
'  , p_dgrm_status       in flow_diagrams.dgrm_status%type default null',
'  , p_dgrm_category     in flow_diagrams.dgrm_category%type default null',
'  , p_dgrm_content      in flow_diagrams.dgrm_content%type default null',
'  , p_comment           in flow_flow_event_log.lgfl_comment%type default null',
'  )',
'  is',
'    l_log_dgrm_content  boolean;',
'    l_diagram_location  flow_flow_event_log.lgfl_dgrm_archive_location%type;',
'    l_dgrm_name         flow_diagrams.dgrm_name%type;',
'    l_dgrm_version      flow_diagrams.dgrm_version%type;',
'    l_dgrm_status       flow_diagrams.dgrm_status%type;',
'    l_dgrm_category     flow_diagrams.dgrm_category%type;',
'  begin',
'    apex_debug.enter(''Log diagram event'');',
'    if diagram_logging_level = ''true''',
'    then',
'      if p_dgrm_content is not null and coalesce(p_dgrm_status, ''X'') != flow_constants_pkg.gc_dgrm_status_draft then',
'        l_log_dgrm_content := true;',
'        -- copy the new bpmn content to the bpmn archive (table or OCI object storage)',
'        l_diagram_location := flow_log_admin.archive_bpmn_diagram ( p_dgrm_id       => p_dgrm_id',
'                                                                  , p_dgrm_content  => p_dgrm_content',
'                                                                  );',
'      end if;',
'',
'      begin',
'        select ',
'            coalesce(p_dgrm_name, dgrm_name)',
'          , coalesce(p_dgrm_version, dgrm_version)',
'          , coalesce(p_dgrm_status, dgrm_status)',
'          , coalesce(p_dgrm_category, dgrm_category)',
'          into l_dgrm_name, l_dgrm_version, l_dgrm_status, l_dgrm_category',
'          from flow_diagrams',
'        where dgrm_id = p_dgrm_id;',
'      exception ',
'        when no_data_found then',
'          l_dgrm_name     := p_dgrm_name;',
'          l_dgrm_version  := p_dgrm_version;',
'          l_dgrm_status   := p_dgrm_status;',
'          l_dgrm_category := p_dgrm_category;',
'      end;',
'',
'      insert into flow_flow_event_log',
'      ( lgfl_dgrm_id',
'      , lgfl_dgrm_name',
'      , lgfl_dgrm_version',
'      , lgfl_dgrm_status',
'      , lgfl_dgrm_category',
'      , lgfl_dgrm_archive_location',
'      , lgfl_user',
'      , lgfl_comment',
'      , lgfl_timestamp',
'      )',
'      values',
'      ( p_dgrm_id',
'      , l_dgrm_name',
'      , l_dgrm_version',
'      , l_dgrm_status',
'      , l_dgrm_category',
'      , l_diagram_location',
'      , coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                  , sys_context(''userenv'',''os_user'')',
'                  , sys_context(''userenv'',''session_user'')',
'                  ) ',
'      , p_comment',
'      , systimestamp at time zone ''UTC''',
'      );',
'    end if;',
'  exception',
'    when flow_log_admin.e_archive_destination_null then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''archive-destination-null''',
'      );',
'      --$F4AMESSAGE ''archive-destination-null'' || ''No archive or logging destination has been configured - See Configurations > Logging or Archiving'' ',
'      raise;',
'    when flow_log_admin.e_archive_bad_destination_json then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''archive-destination-bad-json''',
'      , p0 => ''archive destination bad JSON''',
'      );',
'      -- $F4AMESSAGE ''archive-destination-bad-json'' || ''Error in archive destination configuration parameter.  Parameter: %0''',
'      raise;',
'    when others then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''logging-diagram-event''',
'      );',
'      -- $F4AMESSAGE ''logging-diagram-event'' || ''Flows - Internal error while logging a Diagram Event''',
'      raise;',
'  end log_diagram_event;',
'',
'  procedure log_instance_event',
'  ( p_process_id        in flow_subflow_log.sflg_prcs_id%type',
'  , p_objt_bpmn_id      in flow_objects.objt_bpmn_id%type default null',
'  , p_event             in flow_instance_event_log.lgpr_prcs_event%type ',
'  , p_event_level       in flow_processes.prcs_logging_level%type',
'  , p_comment           in flow_instance_event_log.lgpr_comment%type default null',
'  , p_error_info        in flow_instance_event_log.lgpr_error_info%type default null',
'  )',
'  is ',
'  begin ',
'    if event_logging_level(p_process_id) >= p_event_level',
'    then',
'      insert into flow_instance_event_log',
'      ( lgpr_prcs_id ',
'      , lgpr_objt_id',
'      , lgpr_dgrm_id ',
'      , lgpr_prcs_name ',
'      , lgpr_business_id',
'      , lgpr_prcs_event',
'      , lgpr_severity',
'      , lgpr_timestamp',
'      , lgpr_duration ',
'      , lgpr_user ',
'      , lgpr_comment',
'      , lgpr_error_info',
'      )',
'      select prcs.prcs_id',
'          , p_objt_bpmn_id',
'          , prcs.prcs_dgrm_id',
'          , prcs.prcs_name',
'          , flow_proc_vars_int.get_business_ref (p_process_id)  --- ',
'          , p_event',
'          , p_event_level',
'          , systimestamp ',
'          , case p_event',
'            when flow_constants_pkg.gc_prcs_event_completed then',
'              prcs.prcs_complete_ts - prcs.prcs_start_ts',
'            when flow_constants_pkg.gc_prcs_event_terminated then',
'              prcs.prcs_complete_ts - prcs.prcs_start_ts',
'            else',
'              null',
'            end',
'          , case g_logging_hide_userid ',
'            when ''true'' then ',
'              null',
'            else ',
'              coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                        , sys_context(''userenv'',''os_user'')',
'                        , sys_context(''userenv'',''session_user'')',
'                        )  ',
'            end ',
'          , p_comment',
'          , p_error_info',
'        from flow_processes prcs ',
'      where prcs.prcs_id = p_process_id',
'      ;',
'    end if;',
'  exception',
'    when others then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''logging-instance-event''',
'      );',
'      -- $F4AMESSAGE ''logging-instance-event'' || ''Flows - Internal error while logging an Instance Event''',
'      raise;',
'  end log_instance_event;',
'',
'  procedure log_step_completion',
'  ( p_process_id        in flow_subflow_log.sflg_prcs_id%type',
'  , p_subflow_id        in flow_subflow_log.sflg_sbfl_id%type',
'  , p_completed_object  in flow_subflow_log.sflg_objt_id%type',
'  , p_iteration_status  in flow_types_pkg.t_iteration_status default null',
'  , p_matching_object   in flow_objects.objt_bpmn_id%type default null',
'  , p_notes             in flow_subflow_log.sflg_notes%type default null',
'  , p_log_to_subflow_log in boolean default true',
'  )',
'  is ',
'    l_notes    varchar2(20);',
'  begin',
'    if p_iteration_status.is_complete then ',
'      l_notes := ''COMPLETE''; ',
'    else ',
'      l_notes := null;',
'    end if;',
'    -- current instance status / progress logging',
'    if p_log_to_subflow_log then',
'      insert into flow_subflow_log sflg',
'      ( sflg_prcs_id',
'      , sflg_objt_id',
'      , sflg_sbfl_id',
'      , sflg_step_key',
'      , sflg_last_updated',
'      , sflg_dgrm_id',
'      , sflg_diagram_level',
'      , sflg_matching_object',
'      , sflg_notes',
'      , sflg_iter_id',
'      )',
'      select p_process_id',
'           , p_completed_object',
'           , p_subflow_id',
'           , sbfl.sbfl_step_key',
'           , sysdate',
'           , sbfl.sbfl_dgrm_id',
'           , sbfl.sbfl_diagram_level',
'           , p_matching_object',
'           , p_notes',
'           , sbfl.sbfl_iter_id',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_id = p_subflow_id',
'        ;',
'    end if;',
'',
'    -- system event logging',
'    if event_logging_level(p_process_id) >= flow_constants_pkg.gc_logging_level_abnormal_events',
'    then',
'      insert into flow_step_event_log',
'      ( lgsf_prcs_id ',
'      , lgsf_objt_id ',
'      , lgsf_sbfl_id ',
'      , lgsf_step_key',
'      , lgsf_sbfl_process_level',
'      , lgsf_last_completed',
'      , lgsf_status_when_complete',
'      , lgsf_sbfl_dgrm_id',
'      , lgsf_was_current ',
'      , lgsf_started ',
'      , lgsf_completed',
'      , lgsf_reservation',
'      , lgsf_due_on',
'      , lgsf_priority',
'      , lgsf_user',
'      , lgsf_apex_task_id',
'      , lgsf_comment',
'      )',
'      select sbfl.sbfl_prcs_id',
'           , p_completed_object',
'           , sbfl.sbfl_id',
'           , sbfl.sbfl_step_key',
'           , sbfl.sbfl_process_level',
'           , sbfl.sbfl_last_completed',
'           , sbfl.sbfl_status',
'           , sbfl.sbfl_dgrm_id',
'           , sbfl.sbfl_became_current',
'           , sbfl.sbfl_work_started',
'           , systimestamp',
'           , sbfl.sbfl_reservation',
'           , sbfl.sbfl_due_on',
'           , sbfl.sbfl_priority',
'          , case g_logging_hide_userid ',
'            when ''true'' then ',
'              null',
'            else ',
'              coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                        , sys_context(''userenv'',''os_user'')',
'                        , sys_context(''userenv'',''session_user'')',
'                        )  ',
'            end ',
'           , sbfl.sbfl_apex_task_id',
'           , p_notes        ',
'        from flow_subflows sbfl ',
'       where sbfl.sbfl_id = p_subflow_id',
'      ;',
'    end if;',
'  exception',
'    when others then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''logging-step-event''',
'      );',
'      -- $F4AMESSAGE ''logging-step-event'' || ''Flows - Internal error while logging a Step Event''',
'      raise;',
'  end log_step_completion;',
'',
'  procedure log_step_event',
'  ( p_sbfl_rec         in flow_subflows%rowtype',
'  , p_event            in flow_instance_event_log.lgpr_prcs_event%type',
'  , p_event_level      in flow_processes.prcs_logging_level%type',
'  , p_comment          in flow_instance_event_log.lgpr_comment%type default null',
'  , p_error_info       in flow_instance_event_log.lgpr_error_info%type default null',
'  , p_new_reservation  in flow_subflows.sbfl_reservation%type default null',
'  , p_new_due_on       in flow_subflows.sbfl_due_on%type default null'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'  , p_new_priority     in flow_subflows.sbfl_priority%type default null',
'  )',
'  is',
'    l_instance_log_rec  flow_instance_event_log%rowtype;',
'  begin',
'    if event_logging_level(p_sbfl_rec.sbfl_prcs_id) >= p_event_level',
'    then',
'',
'',
'      l_instance_log_rec.lgpr_prcs_id         := p_sbfl_rec.sbfl_prcs_id;',
'      l_instance_log_rec.lgpr_step_key        := p_sbfl_rec.sbfl_step_key;',
'      l_instance_log_rec.lgpr_sbfl_id         := p_sbfl_rec.sbfl_id;',
'      l_instance_log_rec.lgpr_process_level   := p_sbfl_rec.sbfl_process_level;',
'      l_instance_log_rec.lgpr_dgrm_id         := p_sbfl_rec.sbfl_dgrm_id;',
'      l_instance_log_rec.lgpr_objt_id         := p_sbfl_rec.sbfl_current;',
'      l_instance_log_rec.lgpr_prcs_event      := p_event;   ',
'      l_instance_log_rec.lgpr_severity        := p_event_level;',
'      l_instance_log_rec.lgpr_timestamp       := systimestamp;',
'      l_instance_log_rec.lgpr_user            := case g_logging_hide_userid ',
'                                             when ''true'' then ',
'                                               null',
'                                             else ',
'                                               coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                         , sys_context(''userenv'',''os_user'')',
'                                                         , sys_context(''userenv'',''session_user'')',
'                                                         )  ',
'                                             end;',
'      l_instance_log_rec.lgpr_apex_task_id    := p_sbfl_rec.sbfl_apex_task_id;',
'      l_instance_log_rec.lgpr_comment         := case p_event',
'                                             when flow_constants_pkg.gc_step_event_reserved then',
'                                               ''reserved for ''||p_new_reservation',
'                                             when flow_constants_pkg.gc_step_event_rescheduled then ',
'                                               ''step rescheduled to ''||to_char ( p_new_due_on',
'                                                                               , flow_constants_pkg.gc_prov_default_tstz_format)',
'                                             when flow_constants_pkg.gc_step_event_reprioritized then',
'                                               ''priority set to ''||p_new_priority',
'                                             else',
'                                               p_comment',
'                                             end;',
'',
'      insert into flow_instance_event_log',
'      values l_instance_log_rec;',
'    end if;',
'    exception',
'      when others then',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''logging-step-event''',
'        );',
'        -- $F4AMESSAGE ''logging-step-event'' || ''Flows - Internal error while logging a Step Event''',
'        raise;',
'  end log_step_event;',
'',
'  -- overload for log_step_event for se when p_sbfl_rec is not available',
'  procedure log_step_event',
'  ( p_process_id       in flow_processes.prcs_id%type',
'  , p_subflow_id       in flow_subflows.sbfl_id%type',
'  , p_event            in flow_instance_event_log.lgpr_prcs_event%type',
'  , p_event_level      in flow_processes.prcs_logging_level%type',
'  , p_comment          in flow_instance_event_log.lgpr_comment%type default null',
'  , p_error_info       in flow_instance_event_log.lgpr_error_info%type default null',
'  , p_new_reservation  in flow_subflows.sbfl_reservation%type default null',
'  , p_new_due_on       in flow_subflows.sbfl_due_on%type default null',
'  , p_new_priority     in flow_subflows.sbfl_priority%type default null',
'  )',
'  is',
'    l_sbfl_rec  flow_subflows%rowtype;',
'    l_comment  flow_instance_event_log.lgpr_comment%type := p_comment;',
'  begin',
'--    begin',
'      select * ',
'        into l_sbfl_rec',
'        from flow_subflows',
'       where sbfl_id      = p_subflow_id',
'         and sbfl_prcs_id = p_process_id',
'      ;    ',
'      ',
'    log_step_event',
'    ( p_sbfl_rec         => l_sbfl_rec',
'    , p_event            => p_event',
'    , p_event_level      => p_event_level',
'    , p_comment          => l_comment',
'    , p_error_info       => p_error_info',
'    , p_new_reservation  => p_new_reservation',
'    , p_new_due_on       => p_new_due_on',
'    , p_new_priority     => p_new_priority',
'    );',
'',
'  exception',
'    when others then',
'      if p_event = flow_constants_pkg.gc_step_event_error then',
'        -- this is an error event that should have already been logged as an instance event.',
'        -- so we can ignore the secondary error trying to log it as a step event',
'        null;',
'      else',
'        flow_errors.handle_general_error',
'        ( pi_message_key => ''logging-step-event''',
'        );',
'        -- $F4AMESSAGE ''logging-step-event'' || ''Flows - Internal error while logging a Step Event''',
'        raise;',
'      end if;',
'  end log_step_event;',
'',
'  procedure log_variable_event -- logs process variable set events',
'  ( p_process_id        in flow_subflow_log.sflg_prcs_id%type',
'  , p_scope             in flow_process_variables.prov_scope%type',
'  , p_var_name          in flow_process_variables.prov_var_name%type',
'  , p_objt_bpmn_id      in flow_objects.objt_bpmn_id%type default null',
'  , p_subflow_id        in flow_subflow_log.sflg_sbfl_id%type default null',
'  , p_expr_set          in flow_object_expressions.expr_set%type default null',
'  , p_var_type          in flow_process_variables.prov_var_type%type',
'  , p_var_vc2           in flow_process_variables.prov_var_vc2%type default null',
'  , p_var_num           in flow_process_variables.prov_var_num%type default null',
'  , p_var_date          in flow_process_variables.prov_var_date%type default null',
'  , p_var_clob          in flow_process_variables.prov_var_clob%type default null',
'  , p_var_tstz          in flow_process_variables.prov_var_tstz%type default null',
'  , p_var_json          in flow_process_variables.prov_var_json%type default null',
'  )',
'  as ',
'    l_logging_user  flow_variable_event_log.lgvr_user%type;',
'  begin ',
'    if event_logging_level(p_process_id) >= flow_constants_pkg.gc_logging_level_full then',
'      ',
'      l_logging_user := case g_logging_hide_userid ',
'        when ''true'' then ',
'          null',
'        else ',
'          coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                    , sys_context(''userenv'',''os_user'')',
'                    , sys_context(''userenv'',''session_user'')',
'                    )  ',
'        end;',
'',
'      insert into flow_variable_event_log',
'      ( lgvr_prcs_id  ',
'      , lgvr_scope',
'      , lgvr_var_name	  ',
'      , lgvr_objt_id	  ',
'      , lgvr_sbfl_id	  ',
'      , lgvr_expr_set	  ',
'      , lgvr_timestamp ',
'      , lgvr_user ',
'      , lgvr_var_type	  ',
'      , lgvr_var_vc2 	  ',
'      , lgvr_var_num  ',
'      , lgvr_var_date   ',
'      , lgvr_var_clob   ',
'      , lgvr_var_tstz  ',
'      , lgvr_var_json',
'      )',
'      values',
'      ( p_process_id',
'      , p_scope',
'      , p_var_name          ',
'      , p_objt_bpmn_id    ',
'      , p_subflow_id ',
'      , p_expr_set ',
'      , systimestamp',
'      , l_logging_user ',
'      , p_var_type ',
'      , p_var_vc2 ',
'      , p_var_num  ',
'      , p_var_date ',
'      , p_var_clob  ',
'      , p_var_tstz ',
'      , p_var_json',
'      );',
'    end if;',
'  exception',
'    when others then',
'      flow_errors.handle_general_error',
'      ( pi_message_key => ''logging-variable-event''',
'      );',
'      -- $F4AMESSAGE ''logging-variable-event'' || ''Flows - Internal error while logging a Variable Event''',
'      raise;',
'  end log_variable_event;',
'',
'  -- initialize logging parameters',
'',
'  begin ',
'    g_logging_level := flow_engine_util.get_config_value',
'                       ( p_config_key => flow_constants_pkg.gc_config_logging_level',
'                       , p_default_value => flow_constants_pkg.gc_config_default_logging_level',
'                       );',
'    g_logging_hide_userid := lower (flow_engine_util.get_config_value',
'                                      ( p_config_key => flow_constants_pkg.gc_config_logging_hide_userid ',
'                                      , p_default_value => flow_constants_pkg.gc_config_default_logging_hide_userid ',
'                                      )',
'                                   );',
'  ',
'    apex_debug.message ( p_message  => ''Logging level: %0''',
'                       , p0         => g_logging_level',
'                       , p_level    => 4 ',
'                       );',
'end flow_logging;',
'/',
'',
'create or replace package body flow_message_flow as',
'/* ',
'-- Flows for APEX - flow_message_flow.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'-- (c) Copyright Flowquest Limited, 2023-25',
'--',
'-- Created  04-Mar-2023  Richard Allen (Oracle Corporation)',
'-- Edited      May-2024  Richard Allen, (Flowquest)',
'--',
'*/',
'  e_lock_timeout exception;',
'  pragma exception_init (e_lock_timeout, -3006);',
'',
'',
'  function subscribe',
'  ( p_subscription_details     in t_subscription_details',
'  ) return flow_message_subscriptions.msub_id%type',
'  is',
'    l_msub_id      flow_message_subscriptions.msub_id%type;',
'  begin',
'    apex_debug.message ( p_message => ''Trying to create subscription for Message %0 Key %1 Value %2 Payload %3''',
'    , p0 => p_subscription_details.message_name',
'    , p1 => p_subscription_details.key_name',
'    , p2 => p_subscription_details.key_value',
'    , p3 => p_subscription_details.payload_var',
'    );',
'',
'    insert into flow_message_subscriptions',
'    ( msub_message_name',
'    , msub_key_name',
'    , msub_key_value',
'    , msub_prcs_id',
'    , msub_sbfl_id',
'    , msub_step_key',
'    , msub_dgrm_id',
'    , msub_callback',
'    , msub_callback_par',
'    , msub_created',
'    , msub_payload_var',
'    )',
'    values ',
'    ( p_subscription_details.message_name',
'    , p_subscription_details.key_name',
'    , p_subscription_details.key_value',
'    , p_subscription_details.prcs_id',
'    , p_subscription_details.sbfl_id',
'    , p_subscription_details.step_key',
'    , p_subscription_details.dgrm_id',
'    , p_subscription_details.callback',
'    , p_subscription_details.callback_par',
'    , systimestamp',
'    , p_subscription_details.payload_var',
'    ) returning msub_id into l_msub_id;',
'',
'    apex_debug.message ( p_message => ''..Message subscription %0 created for Message %1 Key %2 Value %3 Payload %4''',
'    , p0 => l_msub_id',
'    , p1 => p_subscription_details.message_name',
'    , p2 => p_subscription_details.key_name',
'    , p3 => p_subscription_details.key_value',
'    , p4 => p_subscription_details.payload_var',
'    );',
'    return l_msub_id;',
'  end subscribe;',
'',
'  procedure receive_message',
'    ( p_message_name  flow_message_subscriptions.msub_message_name%type',
'    , p_key_name      flow_message_subscriptions.msub_key_name%type',
'    , p_key_value     flow_message_subscriptions.msub_key_value%type',
'    , p_payload       clob default null',
'    )',
'  is',
'    l_received_message    t_flow_simple_message;',
'    l_corr_msg            flow_t_correlated_message;',
'    l_session_id          number;',
'  begin',
'      l_received_message := t_flow_simple_message();',
'',
'      l_received_message.message_name     := p_message_name;',
'      l_received_message.key_name         := p_key_name;   ',
'      l_received_message.key_value        := p_key_value;',
'      l_received_message.payload_is_json  := false;',
'      l_received_message.payload          := p_payload;',
'',
'      -- Correlate and Log Message',
'      l_corr_msg := flow_message_util.correlate_received_message (p_msg => l_received_message);      ',
'',
'      -- message is correlated.  create an APEX session if coming from outside',
'      if v(''APP_SESSION'') is null then',
'        l_session_id := flow_apex_session.create_api_session (p_subflow_id => l_corr_msg.sbfl_id);',
'      end if; ',
'',
'      $IF flow_apex_env.ee $THEN',
'        -- Enterprise Edition - queue into correlated message AQ',
'        flow_message_util_ee.enqueue_correlated_message  ( p_corr_msg => l_corr_msg);  ',
'        -- remove  the subscription as part of the enqueue transaction, unless a start event',
'        if l_corr_msg.callback != flow_constants_pkg.gc_bpmn_start_event then',
'                delete from flow_message_subscriptions',
'                where       msub_id = l_corr_msg.msub_id;',
'        end if;',
'      $ELSE',
'        -- Community Edition - synchronous message handling',
'        flow_message_util.handle_correlated_message  ( p_corr_msg => l_corr_msg);   ',
'      $END                                             ',
'',
'      -- tear down APEX Session if this was an external call.',
'      if l_session_id is not null then',
'        flow_apex_session.delete_session (p_session_id => l_session_id );',
'      end if;      ',
'  exception',
'    when others then',
'      if l_session_id is not null then',
'        flow_apex_session.delete_session (p_session_id => l_session_id );',
'      end if;',
'      raise;',
'  end receive_message;',
'',
'  procedure send_message',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is',
'    l_message               flow_message_flow.t_flow_simple_message;',
'    e_msgflow_bad_endpoint  exception;',
'  begin',
'    apex_debug.enter ',
'    ( ''> send_message''',
'    , ''p_msg_object_bpmn_id'', p_step_info.target_objt_ref',
'    );',
'    l_message := flow_message_util.prepare_message( p_msg_object_bpmn_id  => p_step_info.target_objt_ref',
'                                              , p_dgrm_id             => p_sbfl_info.sbfl_dgrm_id',
'                                              , p_sbfl_info           => p_sbfl_info ',
'                                              );',
'',
'    apex_debug.trace',
'    (',
'      p_message => ''..Received message details -- name %0 ;key %1 ;value %2 ;payload %3''',
'    , p0 => l_message.message_name',
'    , p1 => l_message.key_name',
'    , p2 => l_message.key_value',
'    , p3 => l_message.payload',
'    );',
'',
'    case l_message.endpoint ',
'    when ''local'' then',
'      begin',
'        flow_message_flow.receive_message',
'        ( p_message_name    => l_message.message_name',
'        , p_key_name        => l_message.key_name',
'        , p_key_value       => l_message.key_value',
'        , p_payload         => l_message.payload',
'        );',
'      exception',
'        when e_msgflow_msg_not_correlated then',
'          -- message sent did not match an existing subscription',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'          , pi_message_key  => ''msgflow-not-correlated'' ',
'          );',
'          -- F4A$MESSAGE ''msgflow-not-correlated'' || ''Received message does not match an expected message.''',
'        when e_msgflow_correlated_msg_locked then',
'          -- message sent correated but is locked by another message',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'          , pi_message_key  => ''msgflow-lock-timeout-msub'' ',
'          );',
'          -- F4A$MESSAGE ''msgflow-lock-timeout-msub'' || ''Message Subscription locked by another user.   Try again.''',
'        when e_msgflow_mag_already_consumed then',
'          -- message correlated but receiving object is no longer the current object in its subflow',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'          , pi_message_key  => ''msgflow-no-longer-current-step''',
'          );',
'          -- F4A$MESSAGE ''msgflow-no-longer-current-step'' || ''Message correlated but receiving object is no longer the current object in its subflow.''',
'        when e_msgflow_feature_requires_ee then',
'          -- feature not supported without Enterprise Edition licence',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'          , pi_message_key  => ''feature-requires-ee''',
'          );',
'          -- F4A$MESSAGE ''feature-requires-ee'' || ''Processing this feature requires licensing Flows for APEX Enterprise Edition.''',
'      end;',
'    else',
'      begin',
'        raise e_msgflow_bad_endpoint;',
'      exception',
'        when e_msgflow_bad_endpoint then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id      => p_sbfl_info.sbfl_prcs_id',
'          , pi_sbfl_id      => p_sbfl_info.sbfl_id',
'          , pi_message_key  => ''msgflow-endpoint-not-supported'' ',
'          , p0 => l_message.endpoint',
'          );',
'          -- F4A$MESSAGE ''msgflow-endpoint-not-supported'' || ''Message endpoint specified ( %0) not supported.''',
'      end;',
'    end case;',
'',
'  end;',
'',
'end flow_message_flow;',
'/',
'',
'create or replace package body flow_message_util as',
'/* ',
'-- Flows for APEX - flow_message_util.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'-- (c) Copyright Flowquest Limited and / or its afiliates, 2025',
'--',
'-- Created  04-Mar-2023  Richard Allen (Oracle Corporation)',
'-- Edited   18-Jan-2025  Richard Allen (flowquest)',
'--',
'-- Contains utility and common routines for messageFlow used by',
'-- bpmn:sendTask, bpmn:receiveTask, message catch and throw events, message start events, etc.',
'--',
'*/',
'  e_lock_timeout exception;',
'  pragma exception_init (e_lock_timeout, -3006);',
'',
'  procedure autonomous_write_to_messageflow_log',
'    ( p_message_name     in flow_message_received_log.lgrx_message_name%type ',
'    , p_key_name         in flow_message_received_log.lgrx_key_name%type   ',
'    , p_key_value        in flow_message_received_log.lgrx_key_value%type ',
'    , p_payload          in flow_message_received_log.lgrx_payload%type ',
'    , p_was_correlated   in flow_message_received_log.lgrx_was_correlated%type    ',
'    , p_prcs_id          in flow_message_received_log.lgrx_prcs_id%type ',
'    , p_sbfl_id          in flow_message_received_log.lgrx_sbfl_id%type    ',
'    )',
'  is',
'    pragma autonomous_transaction;',
'  begin',
'      apex_debug.enter (''> autonomous_write_to_messageflow_log'');',
'      insert into flow_message_received_log',
'      ( lgrx_message_name',
'      , lgrx_key_name',
'      , lgrx_key_value',
'      , lgrx_payload',
'      , lgrx_was_correlated',
'      , lgrx_prcs_id',
'      , lgrx_sbfl_id',
'      , lgrx_received_on',
'      )',
'      values',
'      ( p_message_name',
'      , p_key_name',
'      , p_key_value',
'      , p_payload',
'      , p_was_correlated',
'      , p_prcs_id',
'      , p_sbfl_id',
'      , systimestamp',
'      );',
'      -- commit as an autonomous transaction',
'      commit;',
'  end autonomous_write_to_messageflow_log;',
'',
'  function get_msg_subscription_details',
'  ( p_msg_object_bpmn_id        flow_objects.objt_bpmn_id%type',
'  , p_dgrm_id                   flow_diagrams.dgrm_id%type',
'  , p_sbfl_info                 flow_subflows%rowtype',
'  ) return flow_message_flow.t_subscription_details',
'  is ',
'    l_message_name_json flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_message_name      flow_message_subscriptions.msub_message_name%type;',
'    l_key_json          flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_key               flow_message_subscriptions.msub_key_name%type;',
'    l_value_json        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_value             flow_message_subscriptions.msub_key_value%type;',
'    l_msub_id           flow_message_subscriptions.msub_id%type;',
'    l_msg_sub           flow_message_flow.t_subscription_details;',
'    l_payload_variable  flow_process_variables.prov_var_name%type;',
'',
'  begin',
'    apex_debug.enter ',
'    ( ''> get_msg_subscription_details''',
'    , ''p_msg_object_bpmn_id'', p_msg_object_bpmn_id',
'    );',
'',
'    l_msg_sub   := flow_message_flow.t_subscription_details();',
'',
'    -- get message and correlation settings and evaluate them',
'      -- get the userTask subtype  ',
'    select objt.objt_attributes."apex"."messageName"',
'         , objt.objt_attributes."apex"."correlationKey"',
'         , objt.objt_attributes."apex"."correlationValue"',
'         , objt.objt_attributes."apex"."payloadVariable"',
'      into l_message_name_json',
'         , l_key_json',
'         , l_value_json',
'         , l_msg_sub.payload_var',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_msg_object_bpmn_id',
'       and objt.objt_dgrm_id = p_dgrm_id ',
'       ;',
'',
'    apex_debug.message ',
'    ( p_message => ''.. message settings: messageName %0, key %1, value %2, payload var %3''',
'    , p0 => l_message_name_json',
'    , p1 => l_key_json',
'    , p2 => l_value_json',
'    , p3 => l_msg_sub.payload_var',
'    );',
'',
'      if l_message_name_json is not null then',
'        l_msg_sub.message_name := flow_settings.get_vc2_expression ',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_message_name_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_key_json is not null then ',
'        l_msg_sub.key_name     := flow_settings.get_vc2_expression ',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_key_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_value_json is not null then ',
'        l_msg_sub.key_value    := flow_settings.get_vc2_expression',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_value_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'',
'    apex_debug.message ',
'    ( p_message => ''.. ReceiveTask settings: messageName "%0", key "%1", value "%2", payload var "%3".''',
'    , p0 => l_msg_sub.message_name',
'    , p1 => l_msg_sub.key_name',
'    , p2 => l_msg_sub.key_value',
'    , p3 => l_msg_sub.payload_var',
'    );',
'',
'    l_msg_sub.prcs_id        := p_sbfl_info.sbfl_prcs_id;',
'    l_msg_sub.sbfl_id        := p_sbfl_info.sbfl_id;',
'    l_msg_sub.step_key       := p_sbfl_info.sbfl_step_key;',
'  ',
'    return l_msg_sub;',
'  end get_msg_subscription_details;',
'  ',
'  function prepare_message',
'  ( p_msg_object_bpmn_id        flow_objects.objt_bpmn_id%type',
'  , p_dgrm_id                   flow_diagrams.dgrm_id%type',
'  , p_sbfl_info                 flow_subflows%rowtype',
'  ) return flow_message_flow.t_flow_simple_message',
'  is',
'    l_endpoint_json     flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_endpoint          flow_types_pkg.t_vc200;',
'    l_message_name_json flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_message_name      flow_message_subscriptions.msub_message_name%type;',
'    l_key_json          flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_key               flow_message_subscriptions.msub_key_name%type;',
'    l_value_json        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_value             flow_message_subscriptions.msub_key_value%type;',
'    l_payload_json      clob;',
'    l_payload           clob;',
'    l_message           flow_message_flow.t_flow_simple_message;',
'',
'  begin',
'    apex_debug.enter ',
'    ( ''> prepare_message''',
'    , ''p_msg_object_bpmn_id'', p_msg_object_bpmn_id',
'    );',
'',
'    l_message   := flow_message_flow.t_flow_simple_message();',
'',
'    -- get message and correlation settings and evaluate them',
'      -- get the userTask subtype  ',
'    select objt.objt_attributes."apex"."endpoint"',
'         , objt.objt_attributes."apex"."messageName"',
'         , objt.objt_attributes."apex"."correlationKey"',
'         , objt.objt_attributes."apex"."correlationValue"',
'         , objt.objt_attributes."apex"."payload"',
'      into l_endpoint_json',
'         , l_message_name_json',
'         , l_key_json',
'         , l_value_json',
'         , l_payload_json',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_msg_object_bpmn_id',
'       and objt.objt_dgrm_id = p_dgrm_id ',
'       ;',
'',
'    apex_debug.message ',
'    ( p_message => ''.. message settings: messageName %0, key %1, value %2, payload %3, endpoint %4''',
'    , p0 => l_message_name_json',
'    , p1 => l_key_json',
'    , p2 => l_value_json',
'    , p3 => l_payload_json',
'    , p4 => l_endpoint_json',
'    );',
'',
'      if l_message_name_json is not null then',
'        l_message.message_name := flow_settings.get_vc2_expression ',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_message_name_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_key_json is not null then ',
'        l_message.key_name     := flow_settings.get_vc2_expression ',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_key_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_value_json is not null then ',
'        l_message.key_value    := flow_settings.get_vc2_expression',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_value_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_payload_json is not null then ',
'        l_message.payload    := flow_settings.get_clob_expression',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_payload_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;',
'      if l_endpoint_json is not null then ',
'        l_message.endpoint    := flow_settings.get_vc2_expression',
'                                ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                , pi_expr    => l_endpoint_json',
'                                , pi_scope   => p_sbfl_info.sbfl_scope',
'                                );',
'      end if;      ',
'',
'    apex_debug.message ',
'    ( p_message => ''.. ReceiveTask settings: messageName "%0", key "%1", value "%2", payload "%3", endpoint "%4%".''',
'    , p0 => l_message.message_name',
'    , p1 => l_message.key_name',
'    , p2 => l_message.key_value',
'    , p3 => l_message.payload',
'    , p4 => l_message.endpoint',
'    );',
'  ',
'    return l_message;',
'  end prepare_message;',
'',
'',
'  procedure save_payload',
'  ( p_process_id             in  flow_processes.prcs_id%type',
'  , p_subflow_id             in  flow_subflows.sbfl_id%type default null',
'  , p_payload_var            in  flow_process_variables.prov_var_name%type',
'  , p_payload                in  clob',
'  , p_scope                  in  flow_subflows.sbfl_scope%type default 0',
'  , p_objt_bpmn_id           in  flow_objects.objt_bpmn_id%type',
'  )',
'  is',
'  begin',
'    apex_debug.enter ',
'    ( ''> save_payload''',
'    , ''p_payload_var'', p_payload_var',
'    , ''p_payload'', p_payload',
'    );',
'',
'    if ( p_payload is not null ',
'       and p_payload_var is not null ) then ',
'',
'      flow_proc_vars_int.set_var',
'      ( pi_prcs_id      => p_process_id',
'      , pi_sbfl_id      => p_subflow_id',
'      , pi_var_name     => p_payload_var',
'      , pi_clob_value   => p_payload',
'      , pi_objt_bpmn_id => p_objt_bpmn_id',
'      , pi_scope        => p_scope',
'      );',
'      apex_debug.message ',
'      ( p_message => ''.. incoming mesage payload stored in proc var %0''',
'      , p0 => p_payload_var',
'      );    ',
'    end if;',
'  end save_payload;',
'',
'  procedure log_received_message',
'  ( p_received_message     in  flow_message_flow.t_flow_simple_message',
'  , p_subscription         in  flow_message_subscriptions%rowtype',
'  , p_was_correlated       in  boolean',
'  ) ',
'  is',
'    l_log_msg     flow_configuration.cfig_value%type;',
'  begin',
'      apex_debug.enter (''> log_received_message'');',
'',
'      l_log_msg := flow_engine_util.get_config_value ( p_config_key     => flow_constants_pkg.gc_config_logging_message_flow_recd',
'                                                     , p_default_value  => flow_constants_pkg.gc_config_default_logging_recd_msg ',
'                                                     );',
'',
'      if l_log_msg = flow_constants_pkg.gc_vcbool_true then',
'        flow_message_util.autonomous_write_to_messageflow_log',
'        ( p_message_name        => p_received_message.message_name ',
'        , p_key_name            => p_received_message.key_name',
'        , p_key_value           => p_received_message.key_value',
'        , p_payload             => p_received_message.payload',
'        , p_was_correlated      => case p_was_correlated',
'                                   when true then flow_constants_pkg.gc_true',
'                                   else flow_constants_pkg.gc_false',
'                                   end',
'        , p_prcs_id             => p_subscription.msub_prcs_id',
'        , p_sbfl_id             => p_subscription.msub_sbfl_id   ',
'        );',
'      end if;',
'  end log_received_message;',
'',
'  function correlate_catch_event',
'    ( p_msg           flow_message_flow.t_flow_simple_message',
'    ) return flow_message_subscriptions%rowtype',
'  is',
'    l_msub              flow_message_subscriptions%rowtype;',
'  begin',
'    begin',
'      -- attempt the correlation based on 100% match of message name, key and value',
'      select msub.*',
'        into l_msub',
'        from flow_message_subscriptions msub',
'       where msub.msub_message_name    = p_msg.message_name',
'         and msub.msub_key_name        = p_msg.key_name',
'    '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'     and msub.msub_key_value       = p_msg.key_value',
'         for update of msub_id wait 2',
'      ;',
'    exception',
'        when no_data_found then',
'          raise flow_message_flow.e_msgflow_msg_not_correlated;',
'          -- logging of incorrect message handled in procedure exceptions below...',
'        when e_lock_timeout then',
'          raise flow_message_flow.e_msgflow_correlated_msg_locked;          ',
'    end;',
'    return l_msub;',
'  end correlate_catch_event;',
'',
'  function correlate_received_message  ',
'  ( p_msg     in  flow_message_flow.t_flow_simple_message',
'  ) return flow_t_correlated_message',
'  is',
'    l_sub                 flow_message_subscriptions%rowtype;',
'    l_corr_msg            flow_t_correlated_message;',
'    l_was_correlated      boolean  := false;',
'  begin',
'    if (p_msg.key_name is null and p_msg.key_value is null) then',
'      $IF flow_apex_env.ee $THEN',
'        l_sub := flow_message_util_ee.correlate_start_event ( p_msg => p_msg);',
'        l_was_correlated  := true;',
'        ',
'        apex_debug.message ( p_message => ''..start event correlated'');                                                  ',
'      $ELSE',
'        apex_debug.message ( p_message => ''..trying to correlate a message startEvent, which requires Enterprise Edition'');  ',
'        raise flow_message_flow.e_msgflow_feature_requires_ee;',
'      $END',
'    else',
'      -- intermediate message catch / receive',
'      l_sub := flow_message_util.correlate_catch_event ( p_msg => p_msg);',
'      apex_debug.message ( p_message => ''..intermediate catch or receive message event correlated'');                                                  ',
'      -- message is correlated.  ',
'      l_was_correlated  := true;                                             ',
'    end if;',
'    log_received_message  ( p_received_message   => p_msg  ',
'                          , p_subscription       => l_sub',
'                          , p_was_correlated     => l_was_correlated',
'                          ); ',
'    -- build correlated message record',
'    l_corr_msg  := flow_t_correlated_message ( null,null,null,null,null',
'                                             , null,null,null,null,null',
'                                             , null,null,null,null,null',
'                                             );',
'',
'    l_corr_msg.message_name   := p_msg.message_name;',
'    l_corr_msg.key_name       := p_msg.key_name;',
'    l_corr_msg.key_value      := p_msg.key_value;',
'    l_corr_msg.clob_payload   := p_msg.payload; ',
'    l_corr_msg.json_payload   := null;',
'    l_corr_msg.msub_id        := l_sub.msub_id;',
'    l_corr_msg.prcs_id        := l_sub.msub_prcs_id;',
'    l_corr_msg.sbfl_id        := l_sub.msub_sbfl_id;',
'    l_corr_msg.step_key       := l_sub.msub_step_key;',
'    l_corr_msg.dgrm_id        := l_sub.msub_dgrm_id;',
'    l_corr_msg.callback       := l_sub.msub_callback;',
'    l_corr_msg.callback_par   := l_sub.msub_callback_par;',
'    l_corr_msg.payload_var    := l_sub.msub_payload_var;',
'    l_corr_msg.received_tstz  := systimestamp;',
'    l_corr_msg.extension      := null;',
'    return l_corr_msg;',
'  exception',
'    when flow_message_flow.e_msgflow_msg_not_correlated then',
'      apex_debug.message  (''..received message did NOT correlate with waiting existing subscription'');',
'      log_received_message  ( p_received_message   => p_msg ',
'                            , p_subscription       => l_sub',
'                            , p_was_correlated     => l_was_correlated',
'                            ); ',
'      raise flow_message_flow.e_msgflow_msg_not_correlated;',
'  end correlate_received_message;',
'',
'  procedure handle_correlated_message',
'  ( p_corr_msg    in flow_t_correlated_message',
'  )',
'  is',
'    l_sbfl_info     flow_subflows%rowtype;',
'  begin',
'    apex_debug.enter (''> handle_correlated_message'');',
'    if p_corr_msg.sbfl_id is not null then',
'      -- get subflow information and lock subflow',
'      l_sbfl_info := flow_engine_util.get_subflow_info ( p_process_id   => p_corr_msg.prcs_id',
'                                                       , p_subflow_id   => p_corr_msg.sbfl_id',
'                                                       , p_lock_subflow => true',
'                                                       );',
'      apex_debug.message (''..subflow %0 locked'', p0 => l_sbfl_info.sbfl_id);',
'    end if;',
'    case ',
'    when p_corr_msg.callback = flow_constants_pkg.gc_bpmn_receivetask then',
'      apex_debug.message ',
'      ( p_message => ''..receivetask callback. prcs_id %0 sbfl_id %1 l_current %2 scope %3 msub_id %4''',
'      , p0 => p_corr_msg.prcs_id',
'      , p1 => p_corr_msg.sbfl_id',
'      , p2 => l_sbfl_info.sbfl_current',
'      , p3 => l_sbfl_info.sbfl_scope',
'      , p4 => p_corr_msg.msub_id',
'      );',
'      -- Call Back is for a bpmn:receiveTask message',
'      flow_message_util.save_payload',
'      ( p_process_id      => p_corr_msg.prcs_id',
'      , p_subflow_id      => p_corr_msg.sbfl_id',
'      , p_payload_var     => p_corr_msg.payload_var',
'      , p_payload         => p_corr_msg.clob_payload',
'      , p_objt_bpmn_id    => l_sbfl_info.sbfl_current',
'      , p_scope           => l_sbfl_info.sbfl_scope',
'      );',
'',
'      -- do the delete before the callback because the callback will do a next-step, which commits at step end',
'      delete from flow_message_subscriptions',
'       where msub_id = p_corr_msg.msub_id;',
'',
'      flow_tasks.receiveTask_callback ',
'      ( p_process_id    => p_corr_msg.prcs_id',
'      , p_subflow_id    => p_corr_msg.sbfl_id',
'      , p_step_key      => p_corr_msg.step_key',
'      , p_msub_id       => p_corr_msg.msub_id',
'      );',
'    when p_corr_msg.callback = flow_constants_pkg.gc_bpmn_intermediate_catch_event then',
'      apex_debug.message ',
'      ( p_message => ''..ICE callback. prcs_id %0 sbfl_id %1 l_current %2 scope %3 msub_id %4 callback param: %5''',
'      , p0 => p_corr_msg.prcs_id',
'      , p1 => p_corr_msg.sbfl_id',
'      , p2 => l_sbfl_info.sbfl_current',
'      , p3 => l_sbfl_info.sbfl_scope',
'      , p4 => p_corr_msg.msub_id',
'      , p5 => p_corr_msg.callback_par',
'      );',
'      flow_message_util.intermed_save_payload_and_callback',
'      ( p_corr_msg => p_corr_msg',
'      , p_current  => l_sbfl_info.sbfl_current',
'      , p_scope    => l_sbfl_info.sbfl_scope',
'      );',
'    when  p_corr_msg.callback = flow_constants_pkg.gc_bpmn_boundary_event then',
'      $IF flow_apex_env.ee $THEN',
'        flow_message_util_ee.b_event_save_payload_and_callback',
'        ( p_corr_msg => p_corr_msg',
'        , p_current  => l_sbfl_info.sbfl_current',
'        , p_scope    => l_sbfl_info.sbfl_scope',
'        );',
'      $ELSE',
'        raise flow_message_flow.e_msgflow_feature_requires_ee;',
'      $END',
'    when p_corr_msg.callback = flow_constants_pkg.gc_bpmn_start_event then',
'      $IF flow_apex_env.ee $THEN',
'        flow_message_util_ee.start_event_save_payload_and_callback',
'        ( p_corr_msg     => p_corr_msg',
'        );',
'      $ELSE',
'        raise flow_message_flow.e_msgflow_feature_requires_ee;',
'      $END',
'',
'    end case;',
'  end handle_correlated_message;',
'',
'  procedure intermed_save_payload_and_callback',
'   ( p_corr_msg       in flow_t_correlated_message',
'   , p_current        in flow_objects.objt_bpmn_id%type ',
'   , p_scope          in flow_subflows.sbfl_scope%type',
'   ) ',
'  is',
'  begin',
'      -- Call Back is for a bpmn:intermediateCatchEvent - message subtype (Message Catch Event)',
'      save_payload',
'      ( p_process_id      => p_corr_msg.prcs_id',
'      , p_subflow_id      => p_corr_msg.sbfl_id',
'      , p_payload_var     => p_corr_msg.payload_var',
'      , p_payload         => p_corr_msg.clob_payload',
'      , p_objt_bpmn_id    => p_current',
'      , p_scope           => p_scope',
'      );',
'',
'      -- do the delete before the callback because the callback will do a next-step, which commits at step end',
'      delete from flow_message_subscriptions',
'       where msub_id = p_corr_msg.msub_id;',
'',
'      flow_engine.timer_callback ',
'      ( p_process_id    => p_corr_msg.prcs_id',
'      , p_subflow_id    => p_corr_msg.sbfl_id',
'      , p_step_key      => p_corr_msg.step_key',
'      , p_callback      => p_corr_msg.callback',
'      , p_callback_par  => p_corr_msg.callback_par',
'      , p_event_type    => flow_constants_pkg.gc_bpmn_message_event_definition',
'      );',
'',
'  end intermed_save_payload_and_callback;',
'',
'  procedure lock_subscription',
'  ( p_process_id                    flow_processes.prcs_id%type',
'  , p_subflow_id                    flow_subflows.sbfl_id%type',
'  )',
'  is',
'    cursor c_lock_sub is',
'      select msub_id',
'        from flow_message_subscriptions',
'       where msub_prcs_id = p_process_id',
'         and msub_sbfl_id = p_subflow_id',
'         for update of msub_id;',
'  begin',
'    apex_debug.enter',
'    ( ''> lock_subscription''',
'    , ''process_id'', p_process_id',
'    , ''subflow_id'', p_subflow_id',
'    );',
'    open c_lock_sub;',
'    close c_lock_sub;',
'  end lock_subscription;',
'  ',
'  procedure cancel_subscription',
'  ( p_process_id                    flow_processes.prcs_id%type',
'  , p_subflow_id                    flow_subflows.sbfl_id%type',
'  )',
'  is',
'  begin',
'    delete from flow_message_subscriptions',
'          where msub_prcs_id = p_process_id',
'            and msub_sbfl_id = p_subflow_id;',
'  end cancel_subscription;',
'  ',
'  procedure cancel_subscription',
'  ( p_msub_id                       flow_message_subscriptions.msub_id%type',
'  )',
'  is',
'  begin',
'    delete from flow_message_subscriptions',
'          where msub_id = p_msub_id;',
'  end cancel_subscription;',
'',
'  procedure lock_instance_subscriptions',
'  ( p_process_id                    flow_processes.prcs_id%type',
'  )',
'  is',
'    cursor c_lock_subs is',
'      select msub_id',
'        from flow_message_subscriptions',
'       where msub_prcs_id = p_process_id',
'         for update of msub_id;',
'  begin',
'    apex_debug.enter',
'    ( ''> lock_instance_subscription''',
'    , ''process_id'', p_process_id',
'    );',
'    open c_lock_subs;',
'    close c_lock_subs;',
'',
'  end lock_instance_subscriptions;',
'',
'  procedure cancel_instance_subscriptions',
'  ( p_process_id                    flow_processes.prcs_id%type',
'  )',
'  is',
'  begin',
'    delete from flow_message_subscriptions',
'          where msub_prcs_id = p_process_id;',
'  end cancel_instance_subscriptions;',
'',
'end flow_message_util;',
'/',
'',
'create or replace package body flow_migrate_xml_pkg',
'as',
'',
'  function is_exporter_version_current(',
'    p_domdoc dbms_xmldom.DOMDocument',
'  ) return boolean',
'  as',
'    l_exporter varchar2(50);',
'    l_exporter_version varchar2(10);',
'    l_domnodelist dbms_xmldom.DOMNodeList;',
'    l_domnode dbms_xmldom.DOMNode;',
'    l_domelement dbms_xmldom.DOMElement;',
'    l_exporter_below_22 boolean;',
'  begin',
'    l_domnodelist := dbms_xmldom.getelementsbytagname(',
'      doc => p_domdoc',
'    , tagname => ''definitions''',
'    );',
'    for i in 0 .. dbms_xmldom.getlength(l_domnodelist) - 1',
'      loop',
'        l_domnode := dbms_xmldom.item(l_domnodelist, i);',
'        l_domelement := dbms_xmldom.makeelement(l_domnode);',
'        l_exporter := dbms_xmldom.getattribute(',
'                        elem => l_domelement',
'                      , name => ''exporter''',
'                      );',
'        l_exporter_version := dbms_xmldom.getattribute(',
'                              elem => l_domelement',
'                            , name => ''exporterVersion''',
'                            );',
'        l_exporter_below_22 := ( to_number(substr(l_exporter_version, 1, instr(l_exporter_version, ''.'') - 1)) < 22 );',
'      end loop;    ',
'    return (l_exporter = ''Flows for APEX'' and ( not l_exporter_below_22 or l_exporter_version = flow_constants_pkg.gc_version ));',
'  end is_exporter_version_current;',
'  ',
'  procedure set_exporter(',
'    p_domdoc in out dbms_xmldom.DOMDocument',
'  , p_exporter varchar2',
'  , p_exporter_version varchar2',
'  )',
'  as',
'    l_domnodelist dbms_xmldom.DOMNodeList;',
'    l_domnode dbms_xmldom.DOMNode;',
'    l_domelement dbms_xmldom.DOMElement;',
'  begin',
'    l_domnodelist := dbms_xmldom.getelementsbytagname(',
'      doc => p_domdoc',
'    , tagname => ''definitions''',
'    );',
'    for i in 0 .. dbms_xmldom.getlength(l_domnodelist) - 1',
'      loop',
'        l_domnode := dbms_xmldom.item(l_domnodelist, i);',
'        l_domelement := dbms_xmldom.makeelement(l_domnode);',
'        dbms_xmldom.setattribute(',
'          elem => l_domelement',
'        , name => ''exporter''',
'        , newValue => p_exporter',
'        );',
'        dbms_xmldom.setattribute(',
'          elem => l_domelement',
'        , name => ''exporterVersion''',
'        , newValue => p_exporter_version',
'        );',
'      end loop;    ',
'  end set_exporter;',
'',
'  procedure append_page_item(',
'    p_domdoc in out dbms_xmldom.DOMDocument',
'  , p_page_items in out dbms_xmldom.DOMNode',
'  , p_item_name varchar2',
'  , p_item_value varchar2',
'  )',
'  as',
'    l_item_node dbms_xmldom.DOMNode;',
'    l_item_name_node dbms_xmldom.DOMNode;',
'    l_item_value_node dbms_xmldom.DOMNode;',
'    l_item_text_node dbms_xmldom.DOMNode;',
'  begin',
'    -- create page item node',
'    l_item_node := dbms_xmldom.makenode( ',
'      elem => dbms_xmldom.createelement( ',
'                doc => p_domdoc',
'              , tagName => ''apex:pageItem''',
'              , ns => flow_constants_pkg.gc_nsapex',
'              )',
'    );',
'    -- append',
'    l_item_node := dbms_xmldom.appendchild(',
'      n => p_page_items',
'    , newchild => l_item_node',
'    );',
'    -- create item name node ',
'    l_item_name_node := dbms_xmldom.makenode( ',
'      elem => dbms_xmldom.createelement( ',
'                doc => p_domdoc',
'              , tagName => ''apex:itemName''',
'              , ns => flow_constants_pkg.gc_nsapex',
'              ) ',
'    );',
'    -- create text node',
'    l_item_text_node := dbms_xmldom.makenode( ',
'      t => dbms_xmldom.createtextnode(',
'            doc => p_domdoc',
'          , data => p_item_name',
'          )',
'    );',
'    -- append text',
'    l_item_text_node := dbms_xmldom.appendchild(',
'      n => l_item_name_node',
'    , newchild => l_item_text_node',
'    );',
'    -- append',
'    l_item_name_node := dbms_xmldom.appendchild(',
'      n => l_item_node',
'    , newchild => l_item_name_node',
'    );',
'    -- create item value node ',
'    l_item_value_node := dbms_xmldom.makenode( ',
'      elem => dbms_xmldom.createelement( ',
'                doc => p_domdoc',
'              , tagName => ''apex:itemValue''',
'              , ns => flow_constants_pkg.gc_nsapex',
'              )',
'    );',
'     -- create text node',
'    l_item_text_node := dbms_xmldom.makenode( ',
'      t => dbms_xmldom.createtextnode(',
'            doc => p_domdoc',
'          , data => p_item_value',
'          )',
'    );',
'    -- append text',
'    l_item_text_node := dbms_xmldom.appendchild(',
'      n => l_item_value_node',
'    , newchild => l_item_text_node',
'    );',
'    -- append',
'    l_item_value_node := dbms_xmldom.appendchild(',
'      n => l_item_node',
'    , newchild => l_item_value_node',
'    );',
'  end append_page_item;    ',
'',
'  procedure update_apex_namespace(',
'    p_domdoc in out dbms_xmldom.DOMDocument',
'  )',
'  as',
'    l_domnodelist dbms_xmldom.DOMNodeList;',
'    l_domnode dbms_xmldom.DOMNode;',
'    l_domelement dbms_xmldom.DOMElement;',
'  begin',
'    l_domnodelist := dbms_xmldom.getelementsbytagname(',
'      doc => p_domdoc',
'    , tagname => ''definitions''',
'    );',
'    for i in 0 .. dbms_xmldom.getlength(l_domnodelist) - 1',
'      loop',
'        l_domnode := dbms_xmldom.item(l_domnodelist, i);',
'        l_domelement := dbms_xmldom.makeelement(l_domnode);',
'        dbms_xmldom.setattribute(',
'          elem => l_domelement',
'        , name => ''xmlns:apex''',
'        , newValue => flow_constants_pkg.gc_nsapex',
'        );',
'      end loop; ',
'  end update_apex_namespace;',
'',
'  procedure migrate_xml(',
'    p_dgrm_content in out clob',
'  , p_has_changed out boolean  ',
'  )',
'  as',
'    l_data XMLTYPE;',
'    l_domdoc dbms_xmldom.DOMDocument;',
'    l_domnodelist dbms_xmldom.DOMNodeList;',
'    -- task',
'    l_domnode dbms_xmldom.DOMNode;',
'    l_domelement dbms_xmldom.DOMElement;',
'    -- extension element',
'    l_extension_node dbms_xmldom.DOMNode;',
'    -- task type',
'    l_task_type_node dbms_xmldom.DOMNode;',
'    -- children (old)',
'    l_children dbms_xmldom.DOMNodeList;',
'    l_children_count number;',
'    l_child_node dbms_xmldom.DOMNode;',
'    -- child value',
'    l_child_text_node dbms_xmldom.DOMNode;',
'    -- children (new)',
'    l_ext_child_node dbms_xmldom.DOMNode;',
'    l_ext_child_tag_name varchar2(50);',
'',
'    -- user task',
'    l_items varchar2(4000);',
'    l_items_arr apex_t_varchar2;',
'    l_values varchar2(4000);',
'    l_values_arr apex_t_varchar2;',
'    l_valid_items number;',
'',
'    l_return clob;',
'',
'    function get_or_create_ext_elements',
'    (',
'      p_domdoc  dbms_xmldom.DOMDocument',
'    , p_domnode dbms_xmldom.DOMNode',
'    , p_elem    dbms_xmldom.DOMElement',
'    )',
'      return dbms_xmldom.DOMNode',
'    as',
'      l_new_ext_node     dbms_xmldom.DOMNode;',
'      l_cur_ext_elements dbms_xmldom.DOMNodeList;',
'    begin',
'        ',
'      l_cur_ext_elements :=',
'        dbms_xmldom.getchildrenbytagname',
'        (',
'          elem => p_elem',
'        , name => ''extensionElements''',
'        );',
'',
'      if dbms_xmldom.getlength(l_cur_ext_elements) > 0 then',
'        l_new_ext_node := dbms_xmldom.item(l_cur_ext_elements, 0);',
'      else',
'        -- create extension element node ',
'        l_new_ext_node :=',
'          dbms_xmldom.makenode( elem => ',
'            dbms_xmldom.createelement',
'            ( ',
'              doc     => p_domdoc',
'            , tagName => ''extensionElements''',
'            )',
'          );',
'        -- append',
'        l_new_ext_node :=',
'          dbms_xmldom.appendchild',
'          (',
'            n        => p_domnode',
'          , newchild => l_new_ext_node',
'          );',
'      end if;',
'      return l_new_ext_node;',
'    end get_or_create_ext_elements',
'    ;',
'  begin',
'    -- get xml document',
'    l_data := XMLTYPE(p_dgrm_content);',
'    l_domdoc := dbms_xmldom.newDOMDocument(l_data);',
'',
'    -- retrieve exporter version',
'    if not is_exporter_version_current(l_domdoc) then',
'',
'      -- get tags',
'      l_domnodelist := dbms_xmldom.getelementsbytagname(',
'        doc => l_domdoc',
'      , tagname => ''*''',
'      );',
'  ',
'      -- loop over all tags',
'      for i in 0 .. dbms_xmldom.getlength(l_domnodelist) - 1',
'      loop',
'        l_domnode := dbms_xmldom.item(l_domnodelist, i);',
'        case',
'          -- user tasks',
'          when dbms_xmldom.getnodename(l_domnode) = ''bpmn:userTask'' then',
'            l_domelement := dbms_xmldom.makeelement(l_domnode);',
'            -- set task type attribute',
'            dbms_xmldom.setattribute(',
'              elem => l_domelement',
'            , name => ''apex:type''',
'            , newValue => ''apexPage''',
'            , ns => flow_constants_pkg.gc_nsapex',
'            );',
'',
'            l_extension_node :=',
'              get_or_create_ext_elements',
'              ( ',
'                p_domdoc  => l_domdoc',
'              , p_domnode => l_domnode',
'              , p_elem    => l_domelement',
'              );',
'',
'            -- create apex page node ',
'            l_task_type_node := dbms_xmldom.makenode( ',
'              elem => dbms_xmldom.createelement( ',
'                doc => l_domdoc',
'              , tagName => ''apex:apexPage''',
'              , ns => flow_constants_pkg.gc_nsapex',
'              ) ',
'            );',
'            -- append',
'            l_task_type_node := dbms_xmldom.appendchild(',
'              n => l_extension_node',
'            , newchild => l_task_type_node',
'            );  ',
'            -- get child nodes',
'            l_children := dbms_xmldom.getchildnodes(l_domnode);',
'            l_children_count := dbms_xmldom.getlength(l_children);',
'            -- loop over child nodes',
'            for j in 0 .. l_children_count - 1',
'            loop',
'              l_child_node := dbms_xmldom.item(l_children, j);',
'              case dbms_xmldom.getnodename(l_child_node)',
'                when ''apex:apex-application'' then',
'                  l_ext_child_tag_name := ''apex:applicationId'';',
'                when ''apex:apex-page'' then',
'                  l_ext_child_tag_name := ''apex:pageId'';',
'                when ''apex:apex-request'' then',
'                  l_ext_child_tag_name := ''apex:request'';',
'                when ''apex:apex-cache'' then',
'                  l_ext_child_tag_name := ''apex:cache'';',
'                when ''apex:apex-item'' then',
'                  l_ext_child_tag_name := '''';',
'                  -- get text',
'                  l_items := dbms_xmldom.getnodevalue(dbms_xmldom.getfirstchild(l_child_node));',
'                  -- remove old child',
'                  l_child_node := dbms_xmldom.removechild(',
'                    n => l_domnode',
'                  , oldchild => l_child_node',
'                  ); ',
'                when ''apex:apex-value'' then',
'                  l_ext_child_tag_name := '''';',
'                  -- get text',
'                  l_values := dbms_xmldom.getnodevalue(dbms_xmldom.getfirstchild(l_child_node));',
'                  -- remove old child',
'                  l_child_node := dbms_xmldom.removechild(',
'                    n => l_domnode',
'                  , oldchild => l_child_node',
'                  ); ',
'                else',
'                  l_ext_child_tag_name := '''';',
'              end case;',
'              if length(l_ext_child_tag_name) > 0 then',
'                  -- create new child element node ',
'                  l_ext_child_node := dbms_xmldom.makenode( ',
'                    elem => dbms_xmldom.createelement( ',
'                              doc => l_domdoc',
'                            , tagName => l_ext_child_tag_name',
'                            , ns => flow_constants_pkg.gc_nsapex',
'                            ) ',
'                  );',
'                  -- get text node',
'                  l_child_text_node := dbms_xmldom.getfirstchild(l_child_node);',
'                  if not dbms_xmldom.isnull(l_child_text_node) then',
'                      -- add text node',
'                      l_child_text_node := dbms_xmldom.appendchild(',
'                        n => l_ext_child_node',
'                      , newchild => l_child_text_node',
'                      );',
'                      -- append',
'                      l_ext_child_node := dbms_xmldom.appendchild(',
'                        n => l_task_type_node',
'                      , newchild => l_ext_child_node',
'                      );',
'                  end if;      ',
'                  -- remove old child',
'                  l_child_node := dbms_xmldom.removechild(',
'                    n => l_domnode',
'                  , oldchild => l_child_node',
'                  );  ',
'              end if;',
'            end loop;',
'            -- add page items',
'            if (length(l_items) > 0 or length(l_values) > 0) then',
'              -- create new page items node ',
'              l_ext_child_node := dbms_xmldom.makenode( ',
'                elem => dbms_xmldom.createelement( ',
'                          doc => l_domdoc',
'                        , tagName => ''apex:pageItems''',
'                        , ns => flow_constants_pkg.gc_nsapex',
'                        )',
'              );',
'              -- append',
'              l_ext_child_node := dbms_xmldom.appendchild(',
'                n => l_task_type_node',
'              , newchild => l_ext_child_node',
'              );',
'              l_items_arr := apex_string.split(p_str => l_items, p_sep => '','');',
'              l_values_arr := apex_string.split(p_str => l_values, p_sep => '','');',
'              l_valid_items := least(l_items_arr.count, l_values_arr.count);',
'              for i in 1 .. l_valid_items',
'              loop',
'                append_page_item(',
'                  p_domdoc => l_domdoc',
'                , p_page_items => l_ext_child_node',
'                , p_item_name => l_items_arr(i)',
'                , p_item_value => l_values_arr(i)',
'                );',
'              end loop;',
'              -- item names without values',
'              if l_items_arr.count > l_valid_items then',
'                for i in l_valid_items+1 .. l_items_arr.count',
'                loop',
'                  append_page_item(',
'                    p_domdoc => l_domdoc',
'                  , p_page_items => l_ext_child_node',
'                  , p_item_name => l_items_arr(i)',
'                  , p_item_value => ''''',
'                  );',
'                end loop;',
'              end if;    ',
'              -- item values without names',
'              if l_values_arr.count > l_valid_items then',
'                for i in l_valid_items+1 .. l_values_arr.count',
'                loop',
'                  append_page_item(',
'                    p_domdoc => l_domdoc',
'                  , p_page_items => l_ext_child_node',
'                  , p_item_name => ''''',
'                  , p_item_value => l_values_arr(i)',
'                  );',
'                end loop;',
'              end if;    ',
'              -- reset variables',
'              l_items := null;',
'              l_values := null;',
'            end if;',
'            -- script + service tasks',
'          when dbms_xmldom.getnodename(l_domnode) = ''bpmn:scriptTask'' or dbms_xmldom.getnodename(l_domnode) = ''bpmn:serviceTask'' then  ',
'              l_domelement := dbms_xmldom.makeelement(l_domnode);',
'              -- set task type attribute',
'              dbms_xmldom.setattribute(',
'                elem => l_domelement',
'              , name => ''apex:type''',
'              , newValue => ''executePlsql''',
'              , ns => flow_constants_pkg.gc_nsapex',
'              );',
'',
'            l_extension_node :=',
'              get_or_create_ext_elements',
'              ( ',
'                p_domdoc  => l_domdoc',
'              , p_domnode => l_domnode',
'              , p_elem    => l_domelement',
'              );',
'',
'              -- create execute Plsql node ',
'              l_task_type_node := dbms_xmldom.makenode( ',
'                elem => dbms_xmldom.createelement( ',
'                          doc => l_domdoc',
'                        , tagName => ''apex:executePlsql''',
'                        , ns => flow_constants_pkg.gc_nsapex',
'                        )',
'              );',
'              -- append',
'              l_task_type_node := dbms_xmldom.appendchild(',
'                n => l_extension_node',
'              , newchild => l_task_type_node',
'              );  ',
'              -- get child nodes',
'              l_children := dbms_xmldom.getchildnodes(l_domnode);',
'              l_children_count := dbms_xmldom.getlength(l_children);',
'              -- loop over child nodes',
'              for j in 0 .. l_children_count - 1',
'              loop',
'                l_child_node := dbms_xmldom.item(l_children, j);',
'                case dbms_xmldom.getnodename(l_child_node)',
'                  when ''apex:engine'' then',
'                    l_ext_child_tag_name := ''apex:engine'';',
'                  when ''apex:autoBinds'' then',
'                    l_ext_child_tag_name := ''apex:autoBinds'';',
'                  when ''apex:plsqlCode'' then',
'                    l_ext_child_tag_name := ''apex:plsqlCode'';',
'                  else',
'                    l_ext_child_tag_name := '''';',
'                end case;',
'                if length(l_ext_child_tag_name) > 0 then',
'                  -- create new child node ',
'                  l_ext_child_node := dbms_xmldom.makenode( ',
'                    elem => dbms_xmldom.createelement( ',
'                              doc => l_domdoc',
'                            , tagName => l_ext_child_tag_name',
'                            , ns => flow_constants_pkg.gc_nsapex',
'                            )',
'                  );',
'                  -- get text node',
'                  l_child_text_node := dbms_xmldom.getfirstchild(l_child_node);',
'                  if not dbms_xmldom.isnull(l_child_text_node) then',
'                      -- add text node',
'                      l_child_text_node := dbms_xmldom.appendchild(',
'                        n => l_ext_child_node',
'                      , newchild => l_child_text_node',
'                      );',
'                      -- append',
'                      l_ext_child_node := dbms_xmldom.appendchild(',
'                        n => l_task_type_node',
'                      , newchild => l_ext_child_node',
'                      );',
'                  end if;      ',
'                  -- remove old child',
'                  l_child_node := dbms_xmldom.removechild(',
'                    n => l_domnode',
'                  , oldchild => l_child_node',
'                  );  ',
'                end if;',
'              end loop;',
'          else null;',
'        end case;    ',
'      end loop;',
'  ',
'      -- set new exporter',
'      set_exporter(',
'        p_domdoc => l_domdoc',
'      , p_exporter => ''Flows for APEX''',
'      , p_exporter_version => flow_constants_pkg.gc_version',
'      );',
'',
'      -- update apex namespace',
'      update_apex_namespace(l_domdoc);',
'  ',
'      dbms_lob.createtemporary(l_return, false); ',
'      dbms_xmldom.writetoclob(',
'        doc => l_domdoc ',
'      , cl => l_return',
'      );',
'      p_dgrm_content := l_return;',
'      p_has_changed := true;',
'    else',
'      p_has_changed := false;',
'    end if;',
'  end migrate_xml;',
'',
'end flow_migrate_xml_pkg;',
'/',
'',
'create or replace package body flow_parameters',
'as',
'/* ',
'-- Flows for APEX - flow_parameters.pkb',
'-- ',
'-- (c) Copyright Flowquest Limited and / or its affiliates. 2026.',
'--',
'-- Created    07-Feb-2026  Richard Allen (Flowquest Limited)',
'--',
'-- Package for processing BPMN task input/output parameters',
'*/',
'',
'  function process_input_parameters',
'  (',
'    pi_parameter_definitions  in clob',
'  , pi_user_input_data        in clob  ',
'  , pi_process_id             in flow_processes.prcs_id%type',
'  , pi_subflow_id             in flow_subflows.sbfl_id%type default null',
'  , pi_scope                  in flow_subflows.sbfl_scope%type default 0',
'  , pi_allow_user_input       in boolean default true',
'  ) return clob',
'  is',
'    e_user_input_not_allowed exception;',
'    l_param_defs       json_array_t;',
'    l_user_input       json_object_t;',
'    l_result_params    json_object_t;',
'    l_param            json_object_t;',
'    l_source           json_object_t;',
'    l_param_name       varc'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'har2(128);',
'    l_expression_type  varchar2(50);',
'    l_expression       varchar2(4000);',
'    l_param_value      clob;',
'    l_proc_var         flow_proc_vars_int.t_proc_var_value;',
'  begin',
'    apex_debug.enter(''process_input_parameters'', ''pi_process_id'', pi_process_id, ''pi_scope'', pi_scope);',
'    ',
'    -- Initialize result object',
'    l_result_params := json_object_t();',
'    ',
'    -- Parse user input if provided',
'    if pi_user_input_data is not null and pi_user_input_data is json then',
'      l_user_input := json_object_t(pi_user_input_data);',
'    else',
'      l_user_input := json_object_t();',
'    end if;',
'    ',
'    -- Parse parameter definitions',
'    if pi_parameter_definitions is null or pi_parameter_definitions is not json then',
'      return l_result_params.to_clob();',
'    end if;',
'    ',
'    l_param_defs := json_array_t(pi_parameter_definitions);',
'    ',
'    -- Process each parameter definition',
'    for i in 0 .. l_param_defs.get_size - 1 loop',
'      l_param := json_object_t(l_param_defs.get(i));',
'      l_param_name := l_param.get_string(''name'');',
'      ',
'      if l_param.has(''source'') then',
'        l_source := json_object_t(l_param.get(''source''));',
'        l_expression_type := l_source.get_string(''expressionType'');',
'        ',
'        case l_expression_type',
'          when ''userInput'' then',
'            if not pi_allow_user_input then',
'              flow_errors.handle_instance_error',
'              ( pi_prcs_id     => pi_process_id',
'              , pi_sbfl_id     => pi_subflow_id',
'              , pi_message_key => ''task-param-no-user-input''',
'              , p0             => l_param_name',
'              , p1             => pi_process_id',
'              , p2             => pi_subflow_id',
'              );',
'              -- $F4AMESSAGE ''task-param-no-user-input'' || ''Input parameter %0 in process %1 subflow %2 uses userInput source, which is only allowed for AHSP activities.''',
'              raise e_user_input_not_allowed;',
'            end if;',
'',
'            -- Get value from user input JSON',
'            if l_user_input.has(l_param_name) then',
'              l_param_value := l_user_input.get_string(l_param_name);',
'              l_result_params.put(l_param_name, l_param_value);',
'            end if;',
'            ',
'          when ''processVariable'' then',
'            -- Get value from process variable - handle all data types',
'            l_expression := l_source.get_string(''expression'');',
'            l_proc_var := flow_proc_vars_int.get_var_value',
'                         ( pi_prcs_id   => pi_process_id',
'                         , pi_var_name  => l_expression',
'                         , pi_scope     => pi_scope',
'                         );',
'            ',
'            -- Convert to appropriate JSON value based on variable type',
'            case l_proc_var.var_type',
'              when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'                if l_proc_var.var_vc2 is not null then',
'                  l_result_params.put(l_param_name, l_proc_var.var_vc2);',
'                end if;',
'              when flow_constants_pkg.gc_prov_var_type_number then',
'                if l_proc_var.var_num is not null then',
'                  l_result_params.put(l_param_name, l_proc_var.var_num);',
'                end if;',
'              when flow_constants_pkg.gc_prov_var_type_date then',
'                if l_proc_var.var_date is not null then',
'                  l_result_params.put(l_param_name, to_char(l_proc_var.var_date, ''YYYY-MM-DD"T"HH24:MI:SS''));',
'                end if;',
'              when flow_constants_pkg.gc_prov_var_type_clob then',
'                if l_proc_var.var_clob is not null then',
'                  -- For CLOB, try to parse as JSON if possible, otherwise treat as string',
'--                  if l_proc_var.var_clob is json then',
'--                    l_result_params.put_parse(l_param_name, l_proc_var.var_clob);',
'--                  else',
'                    l_result_params.put(l_param_name, l_proc_var.var_clob);',
'--',
'                end if;',
'              when flow_constants_pkg.gc_prov_var_type_tstz then',
'                if l_proc_var.var_tstz is not null then',
'                  l_result_params.put(l_param_name, to_char(l_proc_var.var_tstz, ''YYYY-MM-DD"T"HH24:MI:SS.FFTZH:TZM''));',
'                end if;',
'              else',
'                -- Default to varchar2 for unknown types',
'                if l_proc_var.var_vc2 is not null then',
'                  l_result_params.put(l_param_name, l_proc_var.var_vc2);',
'                end if;',
'            end case;',
'            ',
'          when ''static'' then',
'            -- Use static value from expression',
'            l_expression := l_source.get_string(''expression'');',
'            l_result_params.put(l_param_name, l_expression);',
'            ',
'          else',
'            -- Future: expression, sqlQuery, systemValue, etc.',
'            apex_debug.warn(''Unsupported expressionType: '' || l_expression_type);',
'        end case;',
'      end if;',
'    end loop;',
'    ',
'    return l_result_params.to_clob();',
'    ',
'  exception',
'    when e_user_input_not_allowed then',
'      raise;',
'    when others then',
'      apex_debug.error(''Error in process_input_parameters: '' || sqlerrm);',
'      return json_object_t().to_clob();',
'  end process_input_parameters;',
'',
'  function get_user_input_schema',
'  (',
'    pi_parameter_definitions  in clob',
'  ) return clob',
'  is',
'  begin',
'    -- Delegate to the parameters_to_json_schema function with user_data_only = true',
'    return parameters_to_json_schema(pi_parameter_definitions, true);',
'  end get_user_input_schema;',
'',
'  function validate_parameters',
'  (',
'    pi_parameter_definitions  in clob',
'  , pi_parameter_values       in clob',
'  ) return boolean',
'  is',
'    l_param_defs     json_array_t;',
'    l_param_values   json_object_t;',
'    l_param          json_object_t;',
'    l_param_name     varchar2(128);',
'    l_is_required    boolean;',
'  begin',
'    -- Parse inputs',
'    if pi_parameter_definitions is null or pi_parameter_definitions is not json then',
'      return true; -- No definitions to validate against',
'    end if;',
'    ',
'    if pi_parameter_values is null or pi_parameter_values is not json then',
'      return false; -- Invalid parameter values',
'    end if;',
'    ',
'    l_param_defs := json_array_t(pi_parameter_definitions);',
'    l_param_values := json_object_t(pi_parameter_values);',
'    ',
'    -- Check each required parameter',
'    for i in 0 .. l_param_defs.get_size - 1 loop',
'      l_param := json_object_t(l_param_defs.get(i));',
'      l_param_name := l_param.get_string(''name'');',
'      l_is_required := l_param.get_boolean(''required'');',
'      ',
'      if l_is_required and not l_param_values.has(l_param_name) then',
'        apex_debug.error(''Required parameter missing: '' || l_param_name);',
'        return false;',
'      end if;',
'    end loop;',
'    ',
'    return true;',
'    ',
'  exception',
'    when others then',
'      apex_debug.error(''Error in validate_parameters: '' || sqlerrm);',
'      return false;',
'  end validate_parameters;',
'',
'  function get_input_parameter_definitions',
'  (',
'    pi_objt_id  in flow_objects.objt_id%type',
'  ) return clob',
'  is',
'    l_objt_attributes clob;',
'    l_attributes_json json_object_t;',
'    l_apex_json       json_object_t;',
'  begin',
'    -- Get object attributes',
'    select objt.objt_attributes',
'      into l_objt_attributes  ',
'      from flow_objects objt',
'     where objt.objt_id = pi_objt_id;',
'    ',
'    if l_objt_attributes is null or l_objt_attributes is not json then',
'      return json_array_t().to_clob();',
'    end if;',
'    ',
'    l_attributes_json := json_object_t(l_objt_attributes);',
'',
'    if l_attributes_json.has(''apex'') then',
'      l_apex_json := json_object_t(l_attributes_json.get(''apex''));',
'      if l_apex_json.has(''inputParameters'') then',
'        return l_apex_json.get_array(''inputParameters'').to_clob();',
'      end if;',
'    end if;',
'',
'    return json_array_t().to_clob();',
'    ',
'  exception',
'    when others then',
'      apex_debug.error(''Error in get_input_parameter_definitions: '' || sqlerrm);',
'      return json_array_t().to_clob();',
'  end get_input_parameter_definitions;',
'',
'  function get_output_parameter_definitions',
'  (',
'    pi_objt_id  in flow_objects.objt_id%type',
'  ) return clob  ',
'  is',
'    l_objt_attributes clob;',
'    l_attributes_json json_object_t;',
'    l_apex_json       json_object_t;',
'  begin',
'    -- Get object attributes',
'    select objt.objt_attributes',
'      into l_objt_attributes',
'      from flow_objects objt  ',
'     where objt.objt_id = pi_objt_id;',
'    ',
'    if l_objt_attributes is null or l_objt_attributes is not json then',
'      return json_array_t().to_clob();',
'    end if;',
'    ',
'    l_attributes_json := json_object_t(l_objt_attributes);',
'',
'    if l_attributes_json.has(''apex'') then',
'      l_apex_json := json_object_t(l_attributes_json.get(''apex''));',
'      if l_apex_json.has(''outputParameters'') then',
'        return l_apex_json.get_array(''outputParameters'').to_clob();',
'      end if;',
'    end if;',
'',
'    return json_array_t().to_clob();',
'    ',
'  exception',
'    when others then',
'      apex_debug.error(''Error in get_output_parameter_definitions: '' || sqlerrm);',
'      return json_array_t().to_clob();',
'  end get_output_parameter_definitions;',
'',
'  function parameters_to_json_schema',
'  (',
'    pi_parameters      in clob',
'  , pi_user_data_only  in boolean default false',
'  ) return clob',
'  is',
'    l_input_array     json_array_t;',
'    l_schema          json_object_t;',
'    l_properties      json_object_t;',
'    l_required_array  json_array_t;',
'    l_param           json_object_t;',
'    l_property        json_object_t;',
'    l_param_name      varchar2(128);',
'    l_param_type      varchar2(32);',
'    l_is_required     boolean;',
'    l_default_value   varchar2(4000);',
'    l_description     varchar2(4000);',
'    l_apex_props      json_object_t;',
'    l_source          json_object_t;',
'    l_expression_type varchar2(50);',
'  begin',
'    -- Return empty schema if no parameters provided',
'    if pi_parameters is null or pi_parameters is not json then',
'      l_schema := json_object_t();',
'      l_schema.put(''type'', ''object'');',
'      l_schema.put(''properties'', json_object_t());',
'      return l_schema.to_clob();',
'    end if;',
'',
'    -- Parse input parameters array',
'    l_input_array := json_array_t(pi_parameters);',
'    ',
'    -- Initialize schema structure',
'    l_schema := json_object_t();',
'    l_schema.put(''type'', ''object'');',
'    l_properties := json_object_t();',
'    l_required_array := json_array_t();',
'',
'    -- Process each parameter',
'    for i in 0 .. l_input_array.get_size - 1 loop',
'      l_param := json_object_t(l_input_array.get(i));',
'      ',
'      -- Check if we should include this parameter',
'      if pi_user_data_only then',
'        -- Only include userInput parameters when user_data_only = true',
'        if l_param.has(''source'') then',
'          l_source := json_object_t(l_param.get(''source''));',
'          l_expression_type := l_source.get_string(''expressionType'');',
'          if l_expression_type != ''userInput'' then',
'            continue; -- Skip this parameter',
'          end if;',
'        else',
'          continue; -- Skip parameters without source (shouldn''t happen)',
'        end if;',
'      end if;',
'      ',
'      -- Extract parameter details',
'      l_param_name := l_param.get_string(''name'');',
'      l_param_type := l_param.get_string(''type'');',
'      l_is_required := l_param.get_boolean(''required'');',
'      ',
'      -- Create property object',
'      l_property := json_object_t();',
'      l_property.put(''type'', l_param_type);',
'      l_property.put(''title'', initcap(replace(l_param_name, ''_'', '' '')));',
'      ',
'      -- Add default value if present',
'      if l_param.has(''default'') then',
'        l_default_value := l_param.get_string(''default'');',
'        l_property.put(''default'', l_default_value);',
'      end if;',
'      ',
'      -- Handle APEX-specific properties and description',
'      l_apex_props := json_object_t();',
'',
'      -- Put onto new line with full width for modern style',
'      l_apex_props.put(''newRow'', true);',
'      l_apex_props.put(''colSpan'', 12);',
'      ',
'      -- Add description as help text under apex object',
'      if l_param.has(''description'') then',
'        l_description := l_param.get_string(''description'');',
'        l_apex_props.put(''help'', l_description);',
'      end if;',
'      ',
'      -- Add other APEX rendering properties if present',
'      if l_param.has(''apexRendering'') then',
'        declare',
'          l_apex_rendering json_object_t := json_object_t(l_param.get(''apexRendering''));',
'          l_keys json_key_list := l_apex_rendering.get_keys();',
'          l_enum_object json_object_t;',
'          l_enum_keys json_key_list;',
'          l_enum_array json_array_t;',
'        begin',
'          -- Copy all apexRendering properties into the apex object',
'          for j in 1 .. l_keys.count loop',
'            l_apex_props.put(l_keys(j), l_apex_rendering.get(l_keys(j)));',
'          end loop;',
'          ',
'          -- Special handling for enum - extract keys to main schema level',
'          if l_apex_rendering.has(''enum'') then',
'            begin',
'              -- Preferred shape: enum stored as JSON object.',
'              l_enum_object := json_object_t(l_apex_rendering.get(''enum''));',
'            exception',
'              when others then',
'                begin',
'                  -- Backward-compatible/tolerant path: enum stored as JSON text.',
'                  l_enum_object := json_object_t.parse(l_apex_rendering.get_string(''enum''));',
'                exception',
'                  when others then',
'                    l_enum_object := null;',
'                end;',
'            end;',
'',
'            if l_enum_object is not null then',
'              l_enum_keys := l_enum_object.get_keys();',
'              l_enum_array := json_array_t();',
'',
'              -- Add enum keys to main schema',
'              for k in 1 .. l_enum_keys.count loop',
'                l_enum_array.append(l_enum_keys(k));',
'              end loop;',
'',
'              l_property.put(''enum'', l_enum_array);',
'            end if;',
'          end if;',
'        end;',
'      end if;',
'      ',
'      -- Add apex object to property if it has any content',
'      if l_apex_props.get_size() > 0 then',
'        l_property.put(''apex'', l_apex_props);',
'      end if;',
'      ',
'      -- Add to properties',
'      l_properties.put(l_param_name, l_property);',
'      ',
'      -- Add to required array if required',
'      if l_is_required then',
'        l_required_array.append(l_param_name);',
'      end if;',
'    end loop;',
'',
'    -- Build final schema',
'    l_schema.put(''properties'', l_properties);',
'    if l_required_array.get_size > 0 then',
'      l_schema.put(''required'', l_required_array);',
'    end if;',
'',
'    return l_schema.to_clob();',
'',
'  exception',
'    when others then',
'      -- Return basic schema on error',
'      l_schema := json_object_t();',
'      l_schema.put(''type'', ''object'');',
'      l_schema.put(''properties'', json_object_t());',
'      l_schema.put(''error'', ''Failed to parse parameters: '' || sqlerrm);',
'      return l_schema.to_clob();',
'  end parameters_to_json_schema;',
'',
'  function parameters_to_json_schema',
'  (',
'    pi_parameters        in clob',
'  , pi_user_data_only_yn in varchar2 default ''N''',
'  ) return clob',
'  is',
'  begin',
'    -- Convert varchar2 to boolean and delegate to boolean version',
'    return parameters_to_json_schema(',
'      pi_parameters      => pi_parameters,',
'      pi_user_data_only  => (pi_user_data_only_yn = ''Y'')',
'    );',
'  end parameters_to_json_schema;',
'',
'end flow_parameters;',
'/',
'create or replace package body flow_parser_util',
'as',
'',
'  procedure split_property_name',
'  (',
'    pi_property_name  in        varchar2',
'  , po_namespace     out nocopy varchar2',
'  , po_key           out nocopy varchar2',
'  )',
'  as',
'    l_token_pos pls_integer;',
'  begin',
'    l_token_pos := instr( pi_property_name, '':'' );',
'    if l_token_pos > 0 then',
'      po_namespace := substr( pi_property_name, 1, l_token_pos - 1);',
'      po_key       := substr( pi_property_name, l_token_pos + 1 );',
'    else',
'      po_namespace := null;',
'      po_key       := pi_property_name;',
'    end if;',
'',
'  end split_property_name;',
'',
'  function get_property_key( pi_property_name in varchar2 )',
'    return varchar2',
'  as',
'    l_namespace varchar2(32767);',
'    l_key       varchar2(32767);',
'  begin',
'    split_property_name',
'    (',
'      pi_property_name => pi_property_name',
'    , po_namespace     => l_namespace',
'    , po_key           => l_key',
'    );',
'    return l_key;',
'  end get_property_key;',
'',
'  procedure guarantee_apex_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  )',
'  as',
'    c_key constant varchar2(20) := ''apex'';',
'  begin',
'    -- Initialize the main object if not done already',
'    pio_attributes := coalesce( pio_attributes, sys.json_object_t() );',
'    -- Create empty "apex" object if not existing',
'    if not pio_attributes.has( c_key ) then',
'      pio_attributes.put( c_key, sys.json_object_t() );',
'    end if;',
'  end guarantee_apex_object;',
'',
'  procedure guarantee_bpmn_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  )',
'  as',
'    c_key constant varchar2(20) := ''bpmn'';',
'  begin',
'    -- Initialize the main object if not done already',
'    pio_attributes := coalesce( pio_attributes, sys.json_object_t() );',
'    -- Create empty "bpmn" object if not existing',
'    if not pio_attributes.has( c_key ) then',
'      pio_attributes.put( c_key, sys.json_object_t() );',
'    end if;',
'  end guarantee_bpmn_object;',
'',
'  procedure guarantee_named_object',
'  (',
'    pio_attributes in out nocopy sys.json_object_t',
'  , pi_key         in varchar2',
'  )',
'  as',
'  begin',
'    -- Initialize the main object if not done already',
'    pio_attributes := coalesce( pio_attributes, sys.json_object_t() );',
'    -- Create empty "pi_key" object if not existing',
'    if not pio_attributes.has( pi_key ) then',
'      pio_attributes.put( pi_key, sys.json_object_t() );',
'    end if;',
'  end guarantee_named_object;',
'',
'  /**',
'   * Description: Takes a CLOB and splits it of linefeed or 4000 characters and emits a JSON_ARRAY_T representation',
'   *',
'   * Author:  Moritz Klein',
'   * Created: 4/20/2022',
'   *',
'   * Param: pi_str Input to tokenize at linefeed or 4000 characters',
'   * Return: JSON_ARRAY_T representation of input',
'   */',
'  function get_lines_array',
'  (',
'    pi_str in clob',
'  ) return sys.json_array_t',
'  as',
'    l_values apex_t_varchar2;',
'    l_return sys.json_array_t := sys.json_array_t();',
'  begin',
'    l_values := apex_string.split( p_str => pi_str );',
'    for i in 1..l_values.count loop',
'      if l_values(i) is not null then',
'        l_return.append( l_values(i) );',
'      else -- seems awkward, but this gives you an empty string instead of null into the JSON',
'        l_return.append( '''' );',
'      end if;',
'    end loop;',
'    return l_return;',
'  end get_lines_array;',
'',
'  procedure property_to_json',
'  (',
'    pi_property_name  in        varchar2',
'  , pi_value          in        clob',
'  , po_namespace     out nocopy varchar2',
'  , po_key           out nocopy varchar2',
'  , po_json_element  out nocopy sys.json_element_t',
'  )',
'  as',
'    l_json_text clob;',
'  begin',
'',
'    split_property_name',
'    (',
'      pi_property_name => pi_property_name',
'    , po_namespace     => po_namespace',
'    , po_key           => po_key',
'    );',
'',
'    if pi_property_name in ( flow_constants_pkg.gc_apex_task_plsql_code',
'                           , flow_constants_pkg.gc_bpmn_text',
'                           , flow_constants_pkg.gc_apex_servicetask_body_text',
'                           , flow_constants_pkg.gc_apex_servicetask_body_html',
'                           , flow_constants_pkg.gc_apex_servicetask_attachment',
'                           , flow_constants_pkg.gc_apex_expression',
'                           )',
'    then',
'      po_json_element := get_lines_array( pi_str => pi_value );',
'    elsif pi_property_name in ( flow_constants_pkg.gc_apex_servicetask_placeholder',
'                              , flow_constants_pkg.gc_apex_custom_extension',
'                              , flow_constants_pkg.gc_apex_parameter_enum',
'                              )',
'    then',
'      -- This value should be a JSON object. Some model payloads serialize JSON as escaped text,',
'      -- so we normalize common escape sequences before a second parse attempt.',
'      l_json_text := replace( pi_value, chr(38)||''amp;'', chr(38) );',
'      begin',
'        po_json_element := sys.json_object_t.parse( l_json_text );',
'      exception',
'        when others then',
'          l_json_text := replace( l_json_text, ''\\n'', chr(10) );',
'          l_json_text := replace( l_json_text, ''\\r'', chr(13) );',
'          l_json_text := replace( l_json_text, ''\\t'', chr(9) );',
'          l_json_text := replace( l_json_text, ''\\"'', ''"'' );',
'          po_json_element := sys.json_object_t.parse( l_json_text );',
'      end;',
'    ',
'    elsif po_key = ''priority''',
'    then',
'      -- if the attribute priority ends up here it is the pre 23.1 way',
'      -- we don''t touch the diagram but will store the new definition in objt_attributes',
'      po_json_element := sys.json_object_t.parse( ''{ "expressionType":"plsqlRawExpression","expression":["'' || pi_value || ''"]}'' );',
'    else',
'      po_json_element := null;',
'    end if; ',
'  end property_to_json;',
'',
'  function is_log_enabled',
'    return boolean',
'  as',
'    l_value flow_configuration.cfig_value%type;',
'  begin',
'',
'    select cfig_value',
'      into l_value',
'      from flow_configuration',
'     where cfig_key = ''parser_log_enabled''',
'    ;',
'',
'    return ( l_value = flow_constants_pkg.gc_vcbool_true );',
'',
'  exception',
'    when no_data_found then',
'      return false;',
'  end is_log_enabled;',
'',
'  procedure log_internal',
'  (',
'    pi_plog_dgrm_id    in flow_parser_log.plog_dgrm_id%type',
'  , pi_plog_bpmn_id    in flow_parser_log.plog_bpmn_id%type',
'  , pi_plog_parse_step in flow_parser_log.plog_parse_step%type',
'  , pi_plog_payload    in flow_parser_log.plog_payload%type',
'  )',
'  as',
'    pragma autonomous_transaction;',
'  begin',
'    insert into flow_parser_log ( plog_dgrm_id, plog_bpmn_id, plog_parse_step, plog_payload, plog_log_time )',
'      values ( pi_plog_dgrm_id, pi_plog_bpmn_id, pi_plog_parse_step, pi_plog_payload, systimestamp )',
'    ;',
'    commit;',
'  end log_internal;',
'',
'  procedure log',
'  (',
'    pi_plog_dgrm_id    in flow_parser_log.plog_dgrm_id%type',
'  , pi_plog_bpmn_id    in flow_parser_log.plog_bpmn_id%type',
'  , pi_plog_parse_step in flow_parser_log.plog_parse_step%type',
'  , pi_plog_payload    in flow_parser_log.plog_payload%type',
'  )',
'  as',
'  begin',
'',
'    flow_parser_util.log_internal',
'    (',
'      pi_plog_dgrm_id    => pi_plog_dgrm_id',
'    , pi_plog_bpmn_id    => pi_plog_bpmn_id',
'    , pi_plog_parse_step => pi_plog_parse_step',
'    , pi_plog_payload    => pi_plog_payload',
'    );',
'',
'  end log;',
'',
'  procedure log',
'  (',
'    pi_plog_dgrm_id    in flow_parser_log.plog_dgrm_id%type',
'  , pi_plog_bpmn_id    in flow_parser_log.plog_bpmn_id%type',
'  , pi_plog_parse_step in flow_parser_log.plog_parse_step%type',
'  , pi_plog_payload    in sys.xmltype',
'  )',
'  as',
'  begin',
'',
'    flow_parser_util.log_internal',
'    (',
'        pi_plog_dgrm_id    => pi_plog_dgrm_id',
'      , pi_plog_bpmn_id    => pi_plog_bpmn_id',
'      , pi_plog_parse_step => pi_plog_parse_step',
'      , pi_plog_payload    => case when pi_plog_payload is not null then pi_plog_payload.getclobval else null end',
'    );',
'',
'  end log;',
'',
'  procedure clear_log',
'  (',
'    pi_plog_dgrm_id in flow_parser_log.plog_dgrm_id%type',
'  )',
'  as',
'  begin',
'    delete from flow_parser_log where plog_dgrm_id = pi_plog_dgrm_id;',
'  end clear_log;',
'',
'end flow_parser_util;',
'/',
'',
'create or replace package body flow_plsql_runner_pkg',
'as',
'/* ',
'-- Flows for APEX - flow_plsql_runner_pkg.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2020-2022.',
'--',
'-- Created    15-Nov-2020  Moritz Klein (MT AG)',
'-- Modified   12-Apr-2022  Richard Allen (Oracle)',
'-- Modified   20-May-2022  Moritz Klein (MT AG)',
'-- Modified   2022-07-18   Moritz Klein (MT AG)',
'--',
'*/',
'',
'  type t_runner_config is',
'    record',
'    (',
'      use_apex_exec varchar2(1) default ''N''',
'    , do_autobinds  varchar2(1) default ''N''',
'    , plsql_code    clob',
'    )',
'  ;',
'',
'  g_current_prcs_id flow_processes.prcs_id%type;',
'  g_current_sbfl_id flow_subflows.sbfl_id%type;',
'',
'  procedure init_globals',
'  (',
'    pi_prcs_id in flow_processes.prcs_id%type',
'  , pi_sbfl_id in flow_subflows.sbfl_id%type',
'  )',
'  as',
'  begin',
'    g_current_prcs_id := pi_prcs_id;',
'    g_current_sbfl_id := pi_sbfl_id;',
'  end init_globals;',
'',
'  function get_current_prcs_id',
'    return flow_processes.prcs_id%type',
'  as',
'  begin',
'    return flow_globals.process_id;',
'  end get_current_prcs_id;',
'',
'  function get_current_sbfl_id',
'    return flow_subflows.sbfl_id%type',
'  as',
'  begin',
'    return flow_globals.subflow_id;',
'  end get_current_sbfl_id;',
'',
'  procedure execute_plsql',
'  (',
'    p_plsql_code in clob',
'  )',
'  as',
'  begin',
'    apex_debug.enter ',
'    (''execute_plsql''',
'    , ''p_plsql_code'', dbms_lob.substr(p_plsql_code, 2000, 1)',
'    );',
'    -- Always wrap code into begin..end',
'    -- Developers are allowed to omit those if no declaration section needed',
'',
'    execute immediate',
'      ''begin'' || apex_application.lf ||',
'      p_plsql_code || apex_application.lf ||',
'      ''end;''',
'    ;',
'  ',
'  end execute_plsql;',
'',
'  procedure get_runner_config',
'  (',
'    pi_objt_id        in flow_objects.objt_id%type',
'  , po_use_apex_exec out nocopy boolean',
'  , po_do_autobinds  out nocopy boolean',
'  , po_plsql_code    out nocopy clob',
'  )',
'  as',
'    l_plain_json  clob;',
'    l_json_config sys.json_object_t;',
'    l_code_json   sys.json_array_t;',
'  begin',
'    select json_query( objt.objt_attributes format json, ''$.apex'' returning clob ) as json_data',
'      into l_plain_json',
'      from flow_objects objt',
'     where objt.objt_id = pi_objt_id',
'    ;',
'',
'    l_json_config    := sys.json_object_t( l_plain_json );',
'    po_use_apex_exec := coalesce( l_json_config.get_boolean( ''engine'' ), false );',
'    po_do_autobinds  := coalesce( l_json_config.get_boolean( ''autoBinds'' ), false );',
'    l_code_json      := l_json_config.get_array( ''plsqlCode'' );',
'    po_plsql_code    := flow_engine_util.json_array_join( p_json_array => l_code_json );',
'  end get_runner_config;',
'',
'  procedure run_task_script',
'  (',
'    pi_sbfl_rec in flow_subflows%rowtype',
'  , pi_objt_id  in flow_objects.objt_id%type',
'  )',
'  as',
'    l_use_apex_exec boolean := false;',
'    l_plsql_code    clob;',
'    l_do_autobind   boolean := false;',
'    l_input_parameter_definitions clob;',
'    l_input_parameters            clob;',
'',
'    l_sql_parameters apex_exec.t_parameters;',
'  begin',
'    apex_debug.enter ',
'    ( ''run_task_script''',
'    , ''pi_objt_id'', pi_objt_id',
'    , ''pi_sbfl_id'', pi_sbfl_rec.sbfl_id',
'    );',
'',
'    -- AHSP starts may provide precomputed input parameters. For standard PL/SQL tasks,',
'    -- compute them from the BPMN definitions at execution time.',
'    l_input_parameters := pi_sbfl_rec.sbfl_task_input_parameters;',
'',
'    if l_input_parameters is null then',
'      l_input_parameter_definitions := flow_parameters.get_input_parameter_definitions',
'                                       ( pi_objt_id => pi_objt_id );',
'',
'      if l_input_parameter_definitions is not null',
'         and l_input_parameter_definitions is json then',
'        l_input_parameters := flow_parameters.process_input_parameters',
'                              ( pi_parameter_definitions => l_input_parameter_definitions',
'                              , pi_user_input_data       => null',
'                              , pi_process_id            => pi_sbfl_rec.sbfl_prcs_id',
'                              , pi_subflow_id            => pi_sbfl_rec.sbfl_id',
'                              , pi_scope                 => pi_sbfl_rec.sbfl_scope',
'                              , pi_allow_user_input      => (pi_sbfl_rec.sbfl_is_adhoc = flow_constants_pkg.gc_true)',
'                              );',
'',
'        update flow_subflows',
'           set sbfl_task_input_parameters = l_input_parameters',
'         where sbfl_id = pi_sbfl_rec.sbfl_id;',
'      end if;',
'    end if;',
'',
'    flow_globals.set_context',
'    ( pi_prcs_id          => pi_sbfl_rec.sbfl_prcs_id',
'    , pi_sbfl_id          => pi_sbfl_rec.sbfl_id',
'    , pi_step_key         => pi_sbfl_rec.sbfl_step_key',
'    , pi_scope            => flow_engine_util.get_scope ( p_process_id => pi_sbfl_rec.sbfl_prcs_id, p_subflow_id => pi_sbfl_rec.sbfl_id)',
'    , pi_loop_counter     => flow_engine_util.get_loop_counter (pi_sbfl_id => pi_sbfl_rec.sbfl_id)',
'    , pi_input_parameters => l_input_parameters',
'    );',
'',
'    apex_debug.message',
'    ( p_message => ''run_task_script input parameters JSON (first 2000 chars): %0''',
'    , p0        => dbms_lob.substr(l_input_parameters, 2000, 1)',
'    );',
'',
'    get_runner_config',
'    (',
'      pi_objt_id       => pi_objt_id',
'    , po_use_apex_exec => l_use_apex_exec',
'    , po_do_autobinds  => l_do_autobind',
'    , po_plsql_code    => l_plsql_code',
'    );',
'',
'    flow_proc_vars_int.do_substitution',
'    (',
'      pi_prcs_id  => pi_sbfl_rec.sbfl_prcs_id',
'    , pi_sbfl_id  => pi_sbfl_rec.sbfl_id',
'    , pi_scope    => flow_globals.scope',
'    , pi_step_key => pi_sbfl_rec.sbfl_step_key',
'    , pio_string  => l_plsql_code',
'    );',
'',
'    if not l_do_autobind then',
'      -- bind in process variables rather than APEX session state',
'      l_sql_parameters := flow_proc_vars_int.get_parameter_list',
'                          ( pi_expr       => l_plsql_code',
'                          , pi_prcs_id     => pi_sbfl_rec.sbfl_prcs_id',
'                          , pi_sbfl_id    => pi_sbfl_rec.sbfl_id',
'                          , pi_step_key   => pi_sbfl_rec.sbfl_step_key',
'                          , pi_scope      => flow_globals.scope',
'                          );',
'    end if;',
'      ',
'    if l_use_apex_exec then',
'      apex_exec.execute_plsql',
'      (',
'        p_plsql_code      => l_plsql_code',
'      , p_auto_bind_items => l_do_autobind',
'      , p_sql_parameters  => l_sql_parameters',
'      );',
'    else',
'      execute_plsql',
'      (',
'        p_plsql_code => l_plsql_code',
'      );',
'    end'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' if;',
'',
'    apex_debug.message',
'    ( p_message => ''run_task_script output parameters JSON (first 2000 chars): %0''',
'    , p0        => dbms_lob.substr(flow_globals.get_output_parameters, 2000, 1)',
'    );',
'               ',
'    -- Save output parameters back to the database if any were set',
'    if flow_globals.get_output_parameters is not null then',
'      update flow_subflows',
'         set sbfl_task_output_parameters = flow_globals.get_output_parameters',
'       where sbfl_id = pi_sbfl_rec.sbfl_id;',
'    end if;',
'',
'  exception',
'    when e_plsql_script_requested_stop then ',
'      apex_debug.error',
'      (',
'        p_message => ''User script run by flow_plsql_runner_pkg.run_task_script requested stop.''',
'      , p0        => sqlerrm',
'      );',
'      raise flow_globals.request_stop_engine;  ',
'    when flow_globals.request_stop_engine then   ',
'      apex_debug.error',
'      (',
'        p_message => ''User script run by flow_plsql_runner_pkg.run_task_script requested stop.''',
'      , p0        => sqlerrm',
'      );',
'      raise flow_globals.request_stop_engine;  ',
'    when flow_globals.throw_bpmn_error_event then',
'      apex_debug.error',
'      (',
'        p_message => ''User script run by flow_plsql_runner_pkg.run_task_script threw BPMN error.''',
'      , p0        => sqlerrm',
'      );',
'      raise flow_globals.throw_bpmn_error_event;',
'    when others then',
'      -- common error is that l_plsql_code is missing a final semicolon. Test if final char is a semicolon and give a helpful message if not.',
'      if l_plsql_code is not null and dbms_lob.substr(l_plsql_code,-1) <> '';'' then',
'        apex_debug.error',
'        (',
'          p_message => ''Error during flow_plsql_runner_pkg.run_task_script. Possible missing semicolon at end of PL/SQL code. Code: "%1" SQLERRM: %0''',
'        , p0        => sqlerrm',
'        , p1        => l_plsql_code',
'        );',
'      else',
'        apex_debug.error',
'        (',
'          p_message => ''Error during flow_plsql_runner_pkg.run_task_script. Code: "%1" SQLERRM: %0''',
'        , p0        => sqlerrm',
'        , p1        => l_plsql_code',
'        );',
'      end if;',
'      raise e_plsql_script_failed;',
'  end run_task_script;',
'',
'end flow_plsql_runner_pkg;',
'/',
'',
'create or replace package body flow_proc_vars_int',
'as',
'',
'/* ',
'-- Flows for APEX - flow_proc_vars_int.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright Flowquest Consulting Limited. 2024-25',
'--',
'-- Created    12-Apr-2022  Richard Allen (Oracle)',
'-- Modified   11-Aug-2022  Moritz Klein (MT AG)',
'-- Modified   11-jan-2024  Richard Allen (Flowquest Consulting Ltd)',
'--',
'*/',
'',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'function scope_is_valid',
'( pi_prcs_id in flow_processes.prcs_id%type',
', pi_scope   in flow_subflows.sbfl_scope%type',
') return boolean',
'is ',
'  l_count number;',
'begin',
'  -- first check if the scope is valid from a call activity',
'  select count(prdg_id)',
'    into l_count',
'    from flow_instance_diagrams',
'   where prdg_prcs_id = pi_prcs_id',
'     and prdg_diagram_level = pi_scope;',
'  -- if not, check if it comes from an iteration',
'  -- initially check by seeing if a variable already exists in the scope',
'  -- replace this later with a check on the iteration scopes',
'  if l_count = 0 then ',
'    select count (prov_var_name)',
'      into l_count',
'      from flow_process_variables',
'     where prov_prcs_id = pi_prcs_id',
'       and prov_scope   = pi_scope;',
'  end if;',
'  return (l_count > 0);',
'end;',
'',
'-- set_var signature 1 - set varchar2',
'',
'procedure set_var',
'( pi_prcs_id      in flow_processes.prcs_id%type',
', pi_scope        in flow_process_variables.prov_scope%type default 0',
', pi_var_name     in flow_process_variables.prov_var_name%type',
', pi_vc2_value    in flow_process_variables.prov_var_vc2%type',
', pi_sbfl_id      in flow_subflows.sbfl_id%type default null',
