'/',
'',
'create or replace package body flow_reservations',
'/* ',
'-- Flows for APEX - flow_reservations.pkb',
'-- ',
'-- (c) Copyright Flowquest Limited and / or its affiliates, 2021-2025.',
'--',
'-- Created 05-May-2021  Richard Allen (Flowquest)',
'-- Updated 25-Feb-2025  Richard Allen (Flowquest Limited)',
'--',
'*/',
'as ',
'  lock_timeout exception;',
'  pragma exception_init (lock_timeout, -3006);',
'',
'  procedure reserve_step',
'    ( p_process_id         in flow_processes.prcs_id%type',
'    , p_subflow_id         in flow_subflows.sbfl_id%type',
'    , p_step_key           in flow_subflows.sbfl_step_key%type ',
'    , p_reservation        in flow_subflows.sbfl_reservation%type ',
'    , p_called_internally  in boolean default false',
'    )',
'  is',
'    l_sbfl_rec              flow_subflows%rowtype;',
'    e_reserved_by_other     exception;',
'    e_reserved_by_same      exception;',
'  begin',
'    apex_debug.enter',
'    (''reserve_step''',
'    , ''Subflow '', p_subflow_id',
'    , ''Process '', p_process_id',
'    , ''Step Key'', p_step_key',
'    , ''Reservation'', p_reservation',
'    );',
'',
'    -- check step is not already reserved and lock the subflow',
'    l_sbfl_rec := flow_engine_util.get_subflow_info ( p_process_id => p_process_id',
'                                                    , p_subflow_id => p_subflow_id',
'                                                    , p_lock_subflow => true',
'                                                    );',
'    -- first check the step key',
'    if flow_engine_util.step_key_valid( pi_prcs_id  => p_process_id',
'                                      , pi_sbfl_id  => p_subflow_id',
'                                      , pi_step_key_supplied  => p_step_key',
'                                      , pi_step_key_required => l_sbfl_rec.sbfl_step_key',
'                                      ) ',
'    then ',
'      -- step key valid',
'      if l_sbfl_rec.sbfl_reservation is not null then',
'        if p_reservation = l_sbfl_rec.sbfl_reservation then ',
'          -- step already reserved by required reservation',
'          raise e_reserved_by_same;',
'        else ',
'          raise e_reserved_by_other;',
'        end if;',
'      end if;',
'      -- place the reservation',
'      update flow_subflows sbfl',
'         set sbfl_reservation         = p_reservation',
'           , sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )  ',
'       where sbfl_prcs_id = p_process_id',
'         and sbfl_id = p_subflow_id',
'      ;',
'      flow_logging.log_step_event',
'      ( p_sbfl_rec         => l_sbfl_rec',
'      , p_event            => flow_constants_pkg.gc_step_event_reserved',
'      , p_event_level      => flow_constants_pkg.gc_logging_level_routine',
'      , p_new_reservation  => p_reservation',
'      );',
'      -- commit reservation if this is an external call',
'      if not p_called_internally then ',
'        commit;',
'      end if;',
'    end if;',
'',
'  exception',
'    when no_data_found then',
'        flow_errors.handle_general_error',
'        ( pi_message_key    => ''reservation-failed-not-found''',
'        , p0 => p_subflow_id         ',
'	      , p1 => p_process_id',
'        , p2 => p_reservation',
'        );',
'        -- $F4AMESSAGE ''reservation-failed-not-found'' || ''Reservation for %2 unsuccessful.  Subflow %0 in Process %1 not found.''',
'    when e_reserved_by_other then',
'        flow_errors.handle_general_error',
'        ( pi_message_key    => ''reservation-by-other_user''',
'        , p0 => p_reservation',
'        , p1 => l_sbfl_rec.sbfl_reservation',
'        );',
'        -- $F4AMESSAGE ''reservation-by-other_user'' || ''Reservation for %0 unsuccessful.  Step already reserved by another user (%1).''           ',
'    when e_reserved_by_same then',
'        flow_errors.handle_general_error',
'        ( pi_message_key    => ''reservation-already-placed''',
'        );',
'        -- $F4AMESSAGE ''reservation-already-placed'' || ''Reservation already placed on next task for you.''',
'    when lock_timeout then',
'        flow_errors.handle_general_error',
'        ( pi_message_key    => ''reservation-lock-timeout''',
'        );',
'        -- $F4AMESSAGE ''reservation-lock-timeout'' || ''Subflow currently locked (not reserved) by another user.  Try your reservation again later.''     ',
'  end reserve_step;',
'',
'  procedure release_step',
'    ( p_process_id         in flow_processes.prcs_id%type',
'    , p_subflow_id         in flow_subflows.sbfl_id%type',
'    , p_step_key           in flow_subflows.sbfl_step_key%type default null',
'    , p_called_internally  in boolean default false',
'    )',
'  is',
'    l_existing_reservation      flow_subflows.sbfl_reservation%type;',
'    l_step_key_required         flow_subflows.sbfl_step_key%type;',
'    l_sbfl_rec                  flow_subflows%rowtype;',
'    e_reserved_wrong_step_key   exception;',
'  begin',
'    apex_debug.enter',
'    ( ''release_step''',
'    , ''Subflow '', p_subflow_id',
'    , ''Process '', p_process_id ',
'    , ''Step Key'', p_step_key',
'    );',
'    -- get the subflow details (subflow should already be locked when calling internally)',
'    l_sbfl_rec := flow_engine_util.get_subflow_info ( p_process_id => p_process_id',
'                                                    , p_subflow_id => p_subflow_id',
'                                                    , p_lock_subflow => not p_called_internally',
'                                                    );',
'    -- check step key called externally',
'    if not p_called_internally then ',
'      -- check step key is valid (internal calls have already checked this so no need to check again)',
'      if not flow_engine_util.step_key_valid( pi_prcs_id           => p_process_id',
'                                            , pi_sbfl_id           => p_subflow_id',
'                                            , pi_step_key_supplied => p_step_key',
'                                            , pi_step_key_required => l_sbfl_rec.sbfl_step_key',
'                                            ) ',
'      then ',
'        raise e_reserved_wrong_step_key;',
'      end if;',
'',
'    end if;',
'    -- release the reservation',
'    update flow_subflows sbfl',
'       set sbfl_reservation         = null',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                               , sys_context(''userenv'',''os_user'')',
'                                               , sys_context(''userenv'',''session_user'')',
'                                               )  ',
'    where sbfl_prcs_id = p_process_id',
'      and sbfl_id = p_subflow_id',
'    ;',
'',
'    -- log the release',
'    flow_logging.log_step_event',
'    ( p_sbfl_rec         => l_sbfl_rec',
'    , p_event            => flow_constants_pkg.gc_step_event_released',
'    , p_event_level      => flow_constants_pkg.gc_logging_level_routine',
'    );',
'',
'    -- commit reservation if this is an external call',
'    if not p_called_internally then ',
'      commit;',
'    end if;',
'',
'  exception',
'    when no_data_found then',
'      flow_errors.handle_general_error',
'      ( pi_message_key    => ''reservation-release-not-found''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );',
'      -- $F4AMESSAGE ''reservation-release-not-found'' || ''Reservation release unsuccessful.  Subflow %0 in Process %1 not found.''',
'    when lock_timeout then',
'      flow_errors.handle_general_error',
'      ( pi_message_key    => ''reservation-lock-timeout''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );',
'      -- $F4AMESSAGE ''reservation-lock-timeout'' || ''Subflow currently locked (not reserved) by another user.  Try your reservation again later.''',
'    when e_reserved_wrong_step_key then',
'      flow_errors.handle_general_error',
'      ( pi_message_key    => ''reservation-incorrect-step-key''',
'      , p0 => p_subflow_id',
'      , p1 => p_process_id',
'      );      ',
'      -- $F4AMESSAGE ''reservation-incorrect-step-key'' || ''Task is no longer current.  Please refresh your Inbox.''',
'  end release_step;',
'',
'end flow_reservations;',
'/',
'',
'create or replace package body flow_rest_api_v1',
'as',
'',
'  function get_path( pi_path_endpoint  varchar2, pi_object_id  varchar2)',
'    return varchar2',
'  is',
'  begin',
'',
'    if flow_rest.get_apex_host is null then ',
'      flow_rest.set_apex_host;',
'    end if;',
'',
'    return replace( flow_rest.get_apex_host || flow_rest_constants.c_module || pi_path_endpoint,'':id'', pi_object_id);',
'  end get_path;',
'  ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_link_json( pi_rel       varchar2',
'                        , pi_path      varchar2',
'                        , pi_object_id varchar2',
'                        , pi_action    varchar2 )',
'    return json_object_t',
'  as',
'    l_link_jo  json_object_t;',
'  begin',
'    l_link_jo := new json_object_t;',
'    l_link_jo.put(key => ''rel'',    val => pi_rel);',
'    l_link_jo.put(key => ''href'',   val => get_path(pi_path, pi_object_id));',
'    l_link_jo.put(key => ''action'', val => pi_action);',
'    l_link_jo.put(key => ''types'',  val => json_array_t.parse(''["application/json"]''));',
'    return l_link_jo;',
'  end get_link_json;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure add_usertask_url( pi_links  in out nocopy json_array_t',
'                            , pi_rel       varchar2',
'                            , pi_sbfl_id   flow_subflows.sbfl_id%type',
'                            , pi_action    varchar2 )',
'  as',
'    l_link_jo  json_object_t;',
'    l_url      varchar2(4000);',
'  begin',
'',
'    begin',
'      l_url := flow_api_pkg.get_current_usertask_url( p_process_id => flow_rest.get_process_id(p_sbfl_id => pi_sbfl_id)',
'                                                    , p_subflow_id => pi_sbfl_id',
'                                                    , p_step_key   => flow_rest.get_step_key(p_sbfl_id => pi_sbfl_id) );',
'      exception ',
'        when others then ',
'          null; -- TODO: implement logic to check if usertask url should be created instead of catching exception',
'    end;',
'    ',
'    if l_url is not null then ',
'      l_link_jo := new json_object_t;',
'      l_link_jo.put(key => ''rel'',    val => pi_rel);',
'      l_link_jo.put(key => ''href'',   val => l_url);',
'      l_link_jo.put(key => ''action'', val => pi_action);',
'      l_link_jo.put(key => ''types'',  val => json_array_t.parse(''["application/json"]''));',
'',
'      pi_links.append(l_link_jo);',
'    end if;',
'',
'  end add_usertask_url;',
'  ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_links_array ( pi_object_type  varchar2',
'                           , pi_object_id    varchar2)',
'    return json_array_t',
'  as',
'    l_links  json_array_t;',
'    l_link   json_object_t;',
'  begin ',
'    l_links := new json_array_t();',
'',
'    case lower(pi_object_type)',
'      when flow_rest_constants.c_object_type_diagram then ',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_diagram, flow_rest_constants.c_path_diagrams, pi_object_id, flow_rest_constants.c_http_action_get));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_diagram_processes, pi_object_id, flow_rest_constants.c_http_action_get));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_diagram_processes, pi_object_id, flow_rest_constants.c_http_action_post));',
'      when flow_rest_constants.c_object_type_process then ',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_processes, pi_object_id, flow_rest_constants.c_http_action_get));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_processes, pi_object_id, flow_rest_constants.c_http_action_delete));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_process_start, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_process_reset, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process, flow_rest_constants.c_path_process_terminate, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process_vars, flow_rest_constants.c_path_process_vars, pi_object_id, flow_rest_constants.c_http_action_get));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_process_vars, flow_rest_constants.c_path_process_vars, pi_object_id, flow_rest_constants.c_http_action_put));',
'      when flow_rest_constants.c_object_type_step then',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_start, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_reserve, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_release, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_complete, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_restart, pi_object_id, flow_rest_constants.c_http_action_put));',
'        l_links.append( get_link_json( flow_rest_constants.c_object_type_step, flow_rest_constants.c_path_steps_reschedule_timer, pi_object_id, flow_rest_constants.c_http_action_put));',
'        add_usertask_url( l_links, flow_rest_constants.c_object_type_step_usertask, pi_object_id, flow_rest_constants.c_http_action_get);',
'      else ',
'        null;',
'    end case;',
'',
'    return l_links;',
'  end get_links_array;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_links_object ( pi_object_type  varchar2',
'                            , pi_object_id    varchar2)',
'    return json_object_t',
'  as',
'    l_json_object  json_object_t;',
'  begin',
'',
'    l_json_object := new json_object_t();',
'    l_json_object.put(key => ''links'', val => get_links_array ( pi_object_type  => pi_object_type',
'                                                             , pi_object_id    => pi_object_id));',
'    return l_json_object;                                                         ',
'  end get_links_object;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'  ',
'  function get_links_string_http_GET ( pi_object_type  varchar2',
'                            , pi_object_id    varchar2)',
'    return clob',
'  as',
'    l_json_string  clob;',
'  begin',
'',
'    l_json_string := get_links_array ( pi_object_type  => pi_object_type',
'                                     , pi_object_id    => pi_object_id).stringify;',
'    return trim( trailing '']'' from trim( leading ''['' from l_json_string));',
'  end get_links_string_http_GET;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_business_ref_object( pi_business_ref  varchar2 )',
'    return json_object_t',
'  as',
'    l_business_ref  json_object_t;',
'  begin',
'    l_business_ref := new json_object_t();',
'    l_business_ref.put( ''name'', ''business_ref'');',
'    l_business_ref.put( ''type'', ''varchar'');',
'    l_business_ref.put( ''value'', pi_business_ref );',
'    return l_business_ref;',
'',
'  end get_business_ref_object;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure processes_post( pi_dgrm_id  flow_diagrams.dgrm_id%type',
'                          , pi_payload  json_element_t',
'                          , pi_current_user     varchar2',
'                          , po_status_code      out number',
'                          , po_forward_location out varchar2 ',
'                          , po_exc_payload      out json_element_t',
'                          , po_exc_payload_attr_name out varchar2 )',
'  as',
'    pragma autonomous_transaction;',
'',
'    l_item_object   json_object_t;',
'    l_prcs_id       flow_processes.prcs_id%type;',
'    l_business_ref_arr  json_array_t;',
'    l_error_occured     boolean := false;',
'',
'  begin',
'',
'    flow_rest.verify_and_prepare_payload( pi_payload              => pi_payload ',
'                                        , pi_array_allowed        => false ',
'                                        , po_payload_object       => l_item_object );',
'',
'    flow_rest.verify_diagram_exists( pi_dgrm_id       => pi_dgrm_id',
'                                   , pi_dgrm_version  => l_item_object.get_String( flow_rest_constants.c_check_item_dgrm_version ) );',
'',
'   ',
'    l_prcs_id := flow_api_pkg.flow_create ( pi_dgrm_id    => pi_dgrm_id',
'                                          , pi_prcs_name  => l_item_object.get_String( ''name'' ));',
'',
'    -- if business_ref was provided set process variable after creation',
'    if l_item_object.has( ''business_ref'' ) then',
'      l_business_ref_arr := flow_rest.get_json_array_t( get_business_ref_object( l_item_object.get_string( ''business_ref'' )));',
'      flow_rest.process_vars_update( pi_prcs_id    => l_prcs_id',
'                                   , pio_prov_arr  => l_business_ref_arr',
'                                   , pi_add_error_msg  => true );',
'    end if;',
'',
'    po_forward_location := get_path( pi_path_endpoint => flow_rest_constants.c_path_processes',
'                                   , pi_object_id     => l_prcs_id );',
'',
'    commit;',
'',
'    exception ',
'      when others then ',
'        raise;',
'      ',
'  end processes_post;                       ',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure processes_start_put( pi_prcs_id          flow_processes.prcs_id%type',
'                               , pi_current_user     varchar2',
'                               , po_status_code      out number ',
'                               , po_forward_location out varchar2',
'                               , po_exc_payload      out json_element_t',
'                               , po_exc_payload_attr_name out varchar2 )',
'  as ',
'    l_item_object      json_object_t;   ',
'  begin',
'    ',
'    flow_rest.verify_process_exists( pi_prcs_id  => pi_prcs_id );',
'',
'    l_item_object := new json_object_t();',
'',
'    l_item_object.put( flow_rest_constants.c_process_status, flow_rest_constants.c_process_status_start);',
'',
'    flow_rest.process_status_update( pi_prcs_id  => pi_prcs_id',
'                                   , pi_payload  => l_item_object );',
'',
'    ',
'    ',
'    flow_rest_response.send_success( pi_success_message => ''status updated'' ',
'                                   , pi_payload         => get_links_array ( pi_object_type  => flow_rest_constants.c_object_type_process',
'                                                                           , pi_object_id    => pi_prcs_id )',
'                                   , pi_payload_attr_name => ''links''',
'                                   , po_status_code       => po_status_code );',
'',
'    exception ',
'      when others then ',
'        po_exc_payload := l_item_object;',
'        po_exc_payload_attr_name := ''item'';',
'        raise;',
'',
'  end processes_start_put;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure processes_reset_put( pi_prcs_id          flow_processes.prcs_id%type',
'                               , pi_payload          json_element_t  ',
'                               , pi_current_user     varchar2',
'                               , po_status_code      out number ',
'                               , po_forward_location out varchar2 ',
'                               , po_exc_payload      out json_element_t',
'                               , po_exc_payload_attr_name out varchar2)       ',
'  as ',
'    l_item_object      json_object_t;   ',
'  begin',
'',
'    if pi_payload is null then ',
'      l_item_object := new json_object_t();',
'    else ',
'      flow_rest.verify_and_prepare_payload( pi_payload        => pi_payload ',
'                                          , pi_array_allowed  => false ',
'                                          , po_payload_object => l_item_object );',
'    end if;',
'',
'    l_item_object.put( flow_rest_constants.c_process_status, flow_rest_constants.c_process_status_reset);',
'',
'    flow_rest.verify_process_exists( pi_prcs_id  => pi_prcs_id );',
'',
'    flow_rest.process_status_update( pi_prcs_id  => pi_prcs_id',
'                                   , pi_payload  => l_item_object );',
'',
'    ',
'    ',
'    flow_rest_response.send_success( pi_success_message => ''status updated'' ',
'                                   , pi_payload         => get_links_array ( pi_object_type  => flow_rest_constants.c_object_type_process',
'                                                                           , pi_object_id    => pi_prcs_id )',
'                                   , pi_payload_attr_name => ''links''',
'                                   , po_status_code       => po_status_code );',
'',
'    exception ',
'      when others then ',
'        po_exc_payload := l_item_object;',
'        po_exc_payload_attr_name := ''item'';',
'        raise;',
'',
'  end processes_reset_put;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure processes_terminate_put( pi_prcs_id          flow_processes.prcs_id%type',
'                                   , pi_payload          json_element_t  ',
'                                   , pi_current_user     varchar2',
'                                   , po_status_code      out number ',
'                                   , po_forward_location out varchar2',
'                                   , po_exc_payload      out json_element_t',
'                                   , po_exc_payload_attr_name out varchar2 )                                                         ',
'  as',
'    l_item_object      json_object_t;   ',
'  begin',
'',
'    if pi_payload is null then ',
'      l_item_object := new json_object_t();',
'    else',
'      flow_rest.verify_and_prepare_payload( pi_payload        => pi_payload ',
'                                          , pi_array_allowed  => false ',
'                                          , po_payload_object => l_item_object );',
'    end if;',
'',
'    l_item_object.put( flow_rest_constants.c_process_status, flow_rest_constants.c_process'))
);
end;
