'',
'  procedure dispatch( pi_method           varchar2  --PUT/POST/DELETE',
'                    , pi_endpoint         varchar2',
'                    , pi_dgrm_id          flow_diagrams.dgrm_id%type default null',
'                    , pi_prcs_id          flow_processes.prcs_id%type default null',
'                    , pi_sbfl_id          flow_subflows.sbfl_id%type default null',
'                    , pi_message_name     flow_message_subscriptions.msub_message_name%type default null',
'                    , pi_payload          blob ',
'                    , pi_current_user     varchar2',
'                    , po_status_code      out number ',
'                    , po_forward_location out varchar2',
'                    )',
'  as',
'    l_payload                json_element_t;',
'    l_exc_payload            json_element_t;',
'    l_exc_payload_attr_name  varchar2(200);',
'  begin',
'',
'    flow_rest.initialize( pi_client_id => pi_current_user',
'                        , pi_method    => pi_method ',
'                        , pi_endpoint  => pi_endpoint );',
'    ',
'    begin',
'      l_payload := flow_rest.blob_to_json(pi_payload);',
'      exception ',
'        when others then',
'          l_exc_payload_attr_name := ''payload'';',
'          l_exc_payload := new json_object_t(''{ "content": "''|| apex_escape.json(to_clob(pi_payload)) ||''" }'' ); ',
'          raise;',
'    end;',
'',
'    flow_rest_logging.enter( pi_payload => l_payload );',
'    ',
'    case upper(pi_method)',
'      when ''POST'' then',
'',
'        case ',
'          when regexp_like(pi_endpoint, ''^v1/diagrams/[[:digit:]]+/processes$'', ''i'') then',
'            flow_rest_api_v1.processes_post(  pi_dgrm_id          => pi_dgrm_id',
'                                            , pi_payload          => l_payload',
'                                            , pi_current_user     => pi_current_user',
'                                            , po_status_code      => po_status_code',
'                                            , po_forward_location => po_forward_location',
'                                            , po_exc_payload      => l_exc_payload',
'                                            , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          else ',
'            raise flow_rest_constants.e_not_implemented;',
'        end case;',
'',
'      when ''PUT'' then',
'',
'        case ',
'          when regexp_like(pi_endpoint, ''^v1/messages/[[:alnum:][:blank:][:punct:]]+$'', ''i'') then',
'            flow_rest_api_v1.messages_put( pi_message_name     => pi_message_name',
'                                         , pi_payload          => l_payload',
'                                         , pi_current_user     => pi_current_user',
'                                         , po_status_code      => po_status_code',
'                                         , po_forward_location => po_forward_location ',
'                                         , po_exc_payload      => l_exc_payload',
'                                         , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+/start$'', ''i'') then',
'            flow_rest_api_v1.processes_start_put( pi_prcs_id          => pi_prcs_id',
'                                                , pi_current_user     => pi_current_user',
'                                                , po_status_code      => po_status_code',
'                                                , po_forward_location => po_forward_location ',
'                                                , po_exc_payload      => l_exc_payload',
'                                                , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+/reset$'', ''i'') then',
'            flow_rest_api_v1.processes_reset_put( pi_prcs_id          => pi_prcs_id',
'                                                , pi_payload          => l_payload',
'                                                , pi_current_user     => pi_current_user',
'                                                , po_status_code      => po_status_code',
'                                                , po_forward_location => po_forward_location  ',
'                                                , po_exc_payload      => l_exc_payload',
'                                                , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+/terminate$'', ''i'') then',
'            flow_rest_api_v1.processes_terminate_put( pi_prcs_id          => pi_prcs_id',
'                                                    , pi_payload          => l_payload',
'                                                    , pi_current_user     => pi_current_user',
'                                                    , po_status_code      => po_status_code',
'                                                    , po_forward_location => po_forward_location ',
'                                                    , po_exc_payload      => l_exc_payload',
'                                                    , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/start$'', ''i'') then',
'            flow_rest_api_v1.steps_start_put( pi_sbfl_id          => pi_sbfl_id',
'                                            , pi_payload          => l_payload',
'                                            , pi_current_user     => pi_current_user',
'                                            , po_status_code      => po_status_code',
'                                            , po_forward_location => po_forward_location ',
'                                            , po_exc_payload      => l_exc_payload',
'                                            , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/reserve$'', ''i'') then',
'            flow_rest_api_v1.steps_reserve_put( pi_sbfl_id          => pi_sbfl_id',
'                                              , pi_payload          => l_payload',
'                                              , pi_current_user     => pi_current_user',
'                                              , po_status_code      => po_status_code',
'                                              , po_forward_location => po_forward_location ',
'                                              , po_exc_payload      => l_exc_payload',
'                                              , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/release$'', ''i'') then',
'            flow_rest_api_v1.steps_release_put( pi_sbfl_id          => pi_sbfl_id',
'                                              , pi_payload          => l_payload',
'                                              , pi_current_user     => pi_current_user',
'                                              , po_status_code      => po_status_code',
'                                              , po_forward_location => po_forward_location ',
'                                              , po_exc_payload      => l_exc_payload',
'                                              , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/complete$'', ''i'') then',
'            flow_rest_api_v1.steps_complete_put( pi_sbfl_id          => pi_sbfl_id',
'                                               , pi_payload          => l_payload',
'                                               , pi_current_user     => pi_current_user',
'                                               , po_status_code      => po_status_code',
'                                               , po_forward_location => po_forward_location ',
'                                               , po_exc_payload      => l_exc_payload',
'                                               , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/restart$'', ''i'') then',
'            flow_rest_api_v1.steps_restart_put( pi_sbfl_id          => pi_sbfl_id',
'                                              , pi_payload          => l_payload',
'                                              , pi_current_user     => pi_current_user',
'                                              , po_status_code      => po_status_code',
'                                              , po_forward_location => po_forward_location ',
'                                              , po_exc_payload      => l_exc_payload',
'                                              , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/steps/[[:digit:]]+/reschedule_timer$'', ''i'') then',
'            flow_rest_api_v1.steps_reschedule_timer_put( pi_sbfl_id          => pi_sbfl_id',
'                                                       , pi_payload          => l_payload',
'                                                       , pi_current_user     => pi_current_user',
'                                                       , po_status_code      => po_status_code',
'                                                       , po_forward_location => po_forward_location ',
'                                                       , po_exc_payload      => l_exc_payload',
'                                                       , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+/process_vars$'', ''i'') then',
'            flow_rest_api_v1.process_vars_put( pi_prcs_id          => pi_prcs_id',
'                                             , pi_payload          => l_payload',
'                                             , pi_current_user     => pi_current_user',
'                                             , po_status_code      => po_status_code',
'                                             , po_forward_location => po_forward_location ',
'                                             , po_exc_payload      => l_exc_payload',
'                                             , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          else ',
'            raise flow_rest_constants.e_not_implemented;',
'        end case;',
'',
'      when ''DELETE'' then',
'        case ',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+$'', ''i'') then',
'            flow_rest_api_v1.processes_delete( pi_prcs_id      => pi_prcs_id',
'                                             , pi_payload      => l_payload',
'                                             , pi_current_user => pi_current_user',
'                                             , po_status_code  => po_status_code ',
'                                             , po_exc_payload  => l_exc_payload',
'                                             , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          when regexp_like(pi_endpoint, ''^v1/processes/[[:digit:]]+/process_vars$'', ''i'') then',
'            flow_rest_api_v1.process_vars_delete( pi_prcs_id       => pi_prcs_id',
'                                                , pi_payload       => l_payload',
'                                                , pi_current_user  => pi_current_user',
'                                                , po_status_code   => po_status_code ',
'                                                , po_exc_payload   => l_exc_payload',
'                                                , po_exc_payload_attr_name => l_exc_payload_attr_name );',
'          else',
'            raise flow_rest_constants.e_not_implemented;',
'        end case;                                                ',
'      else ',
'        raise flow_rest_constants.e_not_implemented;',
'    end case;',
'',
'    flow_rest_logging.finished( pi_payload => l_payload );',
'    flow_rest.cleanup;',
'    commit;',
'',
'    exception ',
'      when others then ',
'        flow_rest_errors.handle_error( pi_sqlcode            => SQLCODE',
'     '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'                                , pi_message            => SQLERRM ',
'                                     , pi_stacktrace         => dbms_utility.format_error_backtrace ',
'                                     , pi_payload            => l_exc_payload',
'                                     , pi_payload_attr_name  => l_exc_payload_attr_name',
'                                     , po_status_code        => po_status_code );',
'',
'  end dispatch;',
'',
'end flow_rest_api_v1;',
'/',
'',
'create or replace package body flow_rest_auth',
'as',
'',
'  function get_rest_roles',
'    return flow_rest_roles_nt',
'    pipelined',
'  as',
'    l_roles apex_application_global.vc_arr2;  ',
'  begin',
'',
'    l_roles(1) := flow_rest_constants.c_rest_role_read;',
'    l_roles(2) := flow_rest_constants.c_rest_role_write;',
'    l_roles(3) := flow_rest_constants.c_rest_role_admin;',
'    l_roles(4) := flow_rest_constants.c_rest_role_messages;',
'',
'    for rec_roles in (select id, name ',
'                        from user_ords_roles ',
'                        where name in (select column_value from table(l_roles)))',
'    loop',
'      PIPE ROW (flow_rest_auth.flow_rest_role_ot ( rec_roles.id, rec_roles.name ));',
'    end loop;',
'    return;',
'',
'  end get_rest_roles;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_client_id( pi_name  user_ords_clients.name%type )',
'    return user_ords_clients.id%type',
'  as',
'    l_id  user_ords_clients.id%type;',
'  begin',
'    select id ',
'      into l_id ',
'      from user_ords_clients',
'      where name = pi_name;',
'    return l_id;',
'  end get_client_id;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_client_roles( pi_id   user_ords_clients.id%type )',
'    return apex_application_global.vc_arr2',
'  as',
'    l_roles  apex_application_global.vc_arr2;',
'  begin',
'    select role_id ',
'      bulk collect into l_roles',
'      from user_ords_client_roles',
'      where client_id = pi_id;',
'    return l_roles;',
'  end get_client_roles;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function has_privilege( pi_client_id       varchar2 -- client_id is returned by implicit parameter :current_user',
'                        , pi_privilege_name  varchar2)',
'    return boolean',
'  as',
'    l_check number;',
'  begin',
'',
'    select count(1)',
'      into l_check',
'      from user_ords_clients oc ',
'      join user_ords_client_roles ocr on oc.id = ocr.client_id',
'      join user_ords_privilege_roles opr on ocr.role_id = opr.role_id',
'      where oc.client_id = pi_client_id',
'        and opr.privilege_name = pi_privilege_name;',
'',
'    if l_check > 0 then',
'      return true;',
'    else',
'      return false;',
'    end if;',
'',
'  end has_privilege;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function has_privilege_read( pi_client_id       varchar2)',
'    return number',
'  as',
'  begin',
'',
'    if has_privilege( pi_client_id       => pi_client_id',
'                    , pi_privilege_name  => flow_rest_constants.c_rest_priv_read)',
'    then ',
'      return 1;',
'    else',
'      return 0;',
'    end if;',
'',
'  end has_privilege_read;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function has_privilege_admin( pi_client_id       varchar2)',
'    return number',
'  as',
'  begin',
'',
'    if has_privilege( pi_client_id       => pi_client_id',
'                    , pi_privilege_name  => flow_rest_constants.c_rest_priv_admin)',
'    then ',
'      return 1;',
'    else',
'      return 0;',
'    end if;',
'',
'  end has_privilege_admin;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure check_privilege( pi_client_id       varchar2 -- client_id is returned by implicit parameter :current_user',
'                           , pi_privilege_name  varchar2 )',
'  as',
'  begin',
'',
'    if not has_privilege( pi_client_id      => pi_client_id ',
'                        , pi_privilege_name => pi_privilege_name )',
'    then ',
'      raise flow_rest_constants.e_privilege_not_granted;',
'    end if;',
'',
'  end check_privilege;                       ',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure create_client( pi_name           varchar2',
'                         , pi_owner          varchar2',
'                         , pi_description    varchar2',
'                         , pi_support_email  varchar2',
'                         , pi_support_uri    varchar2 )',
'  as',
'  begin   ',
'    OAUTH.CREATE_CLIENT( p_name            => pi_name,',
'                         p_grant_type      => flow_rest_constants.c_rest_grant_type,',
'                         p_owner           => pi_owner,',
'                         p_description     => pi_description,',
'                         p_support_email   => pi_support_email,',
'                         p_support_uri     => pi_support_uri,',
'                         p_privilege_names => flow_rest_constants.c_rest_priv_access );',
'  end create_client;                     ',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'  procedure update_client_roles( pi_id     user_ords_clients.id%type',
'                               , pi_roles  apex_application_global.vc_arr2)',
'  as',
'    l_client_name  user_ords_clients.name%type;',
'',
'    cursor c_update_roles is  ',
'        with cur_roles as (',
'          select ocr.role_id   as cur_role_id',
'                , ocr.role_name as cur_role_name',
'            from user_ords_clients c ',
'            join user_ords_client_roles ocr on c.id = ocr.client_id',
'            where c.id = pi_id ),',
'          set_roles as (',
'              select uor.id  as set_role_id',
'                    , uor.name as set_role_name',
'                from table(pi_roles) t',
'                join user_ords_roles uor on t.column_value = uor.id )',
'        select cur_role_id',
'              , cur_role_name',
'              , set_role_id',
'              , set_role_name',
'          from cur_roles ocr_cur',
'          full outer join set_roles sr on ocr_cur.cur_role_id = sr.set_role_id ;',
'',
'    procedure get_client_name',
'    as',
'    begin',
'      select name ',
'        into l_client_name ',
'        from user_ords_clients',
'        where id = pi_id;',
'    end;',
'  begin',
'',
'    get_client_name;',
'',
'    for rec_update_roles in c_update_roles',
'    loop',
'',
'      if    rec_update_roles.cur_role_id is not null ',
'        and rec_update_roles.set_role_id is null ',
'      then ',
'        ',
'        oauth.revoke_client_role( p_client_name => l_client_name',
'                                , p_role_name   => rec_update_roles.cur_role_name );',
'',
'      elsif rec_update_roles.cur_role_id is null ',
'        and rec_update_roles.set_role_id is not null ',
'      then ',
'        apex_debug.info(''add role %s to client %s'', rec_update_roles.cur_role_name, l_client_name);',
'        oauth.grant_client_role( p_client_name => l_client_name',
'                               , p_role_name   => rec_update_roles.set_role_name );',
'',
'      end if; ',
'',
'    end loop;',
'',
'  end update_client_roles;                         ',
'',
'end flow_rest_auth;',
'/',
'',
'create or replace package body flow_rest_errors',
'as',
'',
'  procedure handle_error( pi_sqlcode            number ',
'                        , pi_message            varchar2 ',
'                        , pi_stacktrace         varchar2 ',
'                        , pi_payload            json_element_t default null',
'                        , pi_payload_attr_name  varchar2 default null',
'                        , po_status_code        out number )',
'  as',
'',
'    l_message  varchar2(2000);',
'    ',
'    function remove_ora_numer( pi_msg  varchar2 )',
'      return varchar2',
'    is',
'    begin',
'      return regexp_replace( pi_msg, ''ORA-[0-9]+: +'','''');',
'    end;',
'',
'  begin                                ',
'',
'    rollback;',
'',
'    case pi_sqlcode',
'',
'      when -20101 then -- e_payload_not_acceptable',
'        l_message :=  ''Payload not accepted'';',
'      when -20102 then -- e_multiple_object_error',
'        l_message :=  ''Multiple objects found'';',
'      when -20103 then -- e_attribute_not_found',
'        l_message :=  ''Attribute not found'';',
'      when -20104 then -- e_item_not_found',
'        l_message :=  ''Item not found'';',
'      when -20105 then -- e_processing_error',
'        l_message :=  ''Processing Error'';',
'      when -20106 then -- e_process_unknown_status',
'        l_message :=  ''Status unknown'';',
'      when -20107 then -- e_step_unknown_operation',
'        l_message :=  ''Unkown operation for step'';',
'      when -20108 then -- e_privilege_not_granted',
'        flow_rest_response.send_error( pi_sqlerrm     => ''Necessary privilege not granted''',
'                                     , po_status_code => po_status_code );',
'        po_status_code := 401;',
'      when -20109 then --e_payload_processing',
'        l_message :=  ''JSON Payload can not be processed'';',
'      when -20200 then -- e_not_implemented',
'        l_message :=  ''Not implemented'';',
'      else',
'',
'        l_message := pi_message;',
'',
'    end case;',
'',
'    flow_rest_logging.error( pi_payload            => pi_payload',
'                           , pi_error_code         => pi_sqlcode',
'                           , pi_error_msg          => l_message',
'                           , pi_error_stacktrace   => pi_stacktrace',
'                           );',
' ',
'',
'    if nvl(po_status_code, -1) != 401 then ',
'      flow_rest_response.send_error(  pi_sqlerrm            => remove_ora_numer(l_message)',
'                                    , pi_stacktrace         => pi_stacktrace',
'                                    , pi_payload            => pi_payload',
'                                    , pi_payload_attr_name  => pi_payload_attr_name',
'                                    , po_status_code        => po_status_code',
'                                    );',
'    end if;',
'    ',
'    po_status_code := nvl(po_status_code, flow_rest_constants.c_http_code_ERROR) ;',
'',
'    flow_rest.cleanup;',
'',
'  end handle_error;',
'',
'end flow_rest_errors;',
'/',
'',
'create or replace package body flow_rest_install',
'as',
'',
'  function is_rest_enabled( pi_schema varchar2 default apex_application.g_flow_owner )',
'    return boolean',
'  as',
'    l_status varchar2(50);',
'  begin',
'    select upper(max(status))',
'      into l_status',
'      from user_ords_schemas',
'      where parsing_schema = pi_schema;',
'',
'    return nvl(l_status, flow_rest_constants.c_rest_schema_status_disabled) = flow_rest_constants.c_rest_schema_status_enabled;',
'',
'  end is_rest_enabled;',
'  ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function is_module_published( pi_schema varchar2 default apex_application.g_flow_owner',
'                              , pi_module_prefix varchar2 default flow_rest_constants.c_rest_current_version )',
'    return boolean',
'  as',
'    l_status varchar2(50);',
'  begin',
'    select upper(max(om.status))',
'      into l_status',
'      from user_ords_modules om',
'      join user_ords_schemas os on om.schema_id = os.id',
'      where os.parsing_schema = pi_schema',
'        and trim(''/'' from om.uri_prefix) = pi_module_prefix;',
'',
'    return nvl(l_status, ''X'') = flow_rest_constants.c_rest_module_status_published;',
'',
'  end is_module_published;',
'    ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure set_base_url( pi_base_url  varchar2 )',
'  as',
'  begin',
'    flow_engine_util.set_config_value( p_config_key => flow_rest_constants.c_config_prefix || flow_rest_constants.c_config_key_base',
'                                     , p_value      => pi_base_url );',
'  end set_base_url;',
'',
'',
'end flow_rest_install;',
'/',
'',
'create or replace package body flow_rest_logging',
'as',
'',
'  req_call_guid  raw(16);',
'  req_method     varchar2(10);',
'  req_endpoint   varchar2(2000);',
'  req_client_id  varchar2(200);',
'  req_token      varchar2(200);',
'',
'  req_log_rest_incoming varchar2(1);',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure initialize',
'  as',
'  begin',
'    req_call_guid  := sys_guid();',
'    req_method     := owa_util.get_cgi_env(''REQUEST_METHOD'');',
'    req_endpoint   := owa_util.get_cgi_env(''X-APEX-PATH'');',
'    req_client_id  := owa_util.get_cgi_env(''REMOTE_USER'');',
'    req_token      := replace(owa_util.get_cgi_env(''Authorization''),''Bearer '');',
'    ',
'    req_log_rest_incoming := flow_engine_util.get_config_value( p_config_key     => flow_rest_logging.c_log_rest_incoming',
'                                                              , p_default_value  => flow_rest_logging.c_log_rest_incoming_default );',
'',
'  end initialize;',
'  ',
'  procedure cleanup',
'  as',
'  begin',
'    req_call_guid  := null;',
'    req_method     := null;',
'    req_endpoint   := null;',
'    req_client_id  := null;',
'    req_token      := null;',
'    req_log_rest_incoming := null;',
'  end cleanup;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function is_event_log_enabled',
'    return boolean',
'  as',
'  begin',
'',
'    if nvl(req_log_rest_incoming, ''Y'') = ''Y'' then',
'      return true;',
'    end if;',
'',
'    return false;',
'    ',
'  end is_event_log_enabled;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure enter( pi_payload          json_element_t ',
'                 )',
'  as',
'    PRAGMA AUTONOMOUS_TRANSACTION;',
'    l_payload_clob  clob;',
'  begin',
'    ',
'    if is_event_log_enabled ',
'    then',
'',
'      l_payload_clob := pi_payload.to_clob;',
'',
'      INSERT INTO flow_rest_event_log (',
'          lgrt_call_guid',
'        , lgrt_client_id',
'        , lgrt_log_info',
'        , lgrt_token',
'        , lgrt_timestamp',
'        , lgrt_http_method',
'        , lgrt_endpoint',
'        , lgrt_payload',
'      ) VALUES (',
'          req_call_guid',
'        , req_client_id',
'        , flow_rest_logging.c_log_info_enter',
'        , req_token',
'        , systimestamp',
'        , req_method',
'        , req_endpoint',
'        , l_payload_clob',
'      );',
'',
'      commit;',
'',
'    end if;',
'',
'    exception ',
'      when others then ',
'        rollback;',
'        raise;',
'  end enter;',
'    ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure finished( pi_payload          json_element_t ',
'                    )',
'  as',
'    PRAGMA AUTONOMOUS_TRANSACTION;',
'    l_payload_clob  clob;',
'  begin',
'',
'    if is_event_log_enabled ',
'    then',
'      l_payload_clob := pi_payload.to_clob;',
'',
'      INSERT INTO flow_rest_event_log (',
'          lgrt_call_guid',
'        , lgrt_client_id',
'        , lgrt_log_info',
'        , lgrt_token',
'        , lgrt_timestamp',
'        , lgrt_http_method',
'        , lgrt_endpoint',
'        , lgrt_payload',
'      ) VALUES (',
'          req_call_guid',
'        , req_client_id',
'        , flow_rest_logging.c_log_info_finished',
'        , req_token',
'        , systimestamp',
'        , req_method',
'        , req_endpoint',
'        , l_payload_clob',
'      );',
'',
'      commit;',
'',
'    end if;',
'',
'    exception ',
'      when others then ',
'        rollback;',
'        raise;',
'  end finished;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure error( pi_payload            json_element_t',
'                 , pi_error_code         flow_rest_event_log.lgrt_error_code%type',
'                 , pi_error_msg          flow_rest_event_log.lgrt_error_msg%type',
'                 , pi_error_stacktrace   flow_rest_event_log.lgrt_error_stacktrace%type',
'                 )',
'  as',
'    PRAGMA AUTONOMOUS_TRANSACTION;',
'    l_payload_clob  clob;',
'  begin',
'',
'    if is_event_log_enabled ',
'    then',
'    ',
'      if pi_payload is not null then ',
'        l_payload_clob := pi_payload.to_clob;',
'      end if;',
'',
'      INSERT INTO flow_rest_event_log (',
'          lgrt_call_guid',
'        , lgrt_client_id',
'        , lgrt_log_info',
'        , lgrt_token',
'        , lgrt_timestamp',
'        , lgrt_http_method',
'        , lgrt_endpoint',
'        , lgrt_payload',
'        , lgrt_error_code',
'        , lgrt_error_msg',
'        , lgrt_error_stacktrace',
'      ) VALUES (',
'          req_call_guid',
'        , req_client_id',
'        , flow_rest_logging.c_log_info_error',
'        , req_token',
'        , systimestamp',
'        , req_method',
'        , req_endpoint',
'        , l_payload_clob',
'        , pi_error_code',
'        , pi_error_msg',
'        , pi_error_stacktrace',
'      );',
'',
'      commit;',
'    ',
'    end if;',
'',
'    exception ',
'      when others then ',
'        rollback;',
'        raise;',
'',
'  end error;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure set_logging_config( pi_log_rest_incoming         varchar2',
'                              , pi_log_rest_incoming_retain  varchar2 )',
'  as',
'  begin',
'',
'    flow_engine_util.set_config_value( p_config_key => flow_rest_logging.c_log_rest_incoming',
'                                     , p_value      => pi_log_rest_incoming );',
'',
'    flow_engine_util.set_config_value( p_config_key => flow_rest_logging.c_log_rest_incoming_retain_days',
'                                     , p_value      => pi_log_rest_incoming_retain );',
'',
'  end set_logging_config;',
'',
'end flow_rest_logging;',
'/',
'',
'create or replace package body flow_rest_response',
'as',
'',
'  procedure send_error( pi_sqlerrm            varchar2 ',
'                      , pi_stacktrace         varchar2 default null',
'                      , pi_payload            json_element_t default null',
'                      , pi_payload_attr_name  varchar2 default null',
'                      , po_status_code        out number )',
'  as',
'    l_error_jo  json_object_t;',
'  begin',
'    l_error_jo := new json_object_t();',
'    l_error_jo.put( key => ''success'', val => false);',
'    l_error_jo.put( key => ''message'', val => pi_sqlerrm);',
'',
'    /*',
'    if pi_stacktrace is not null then ',
'      l_error_jo.put( key => ''stacktrace'', val => pi_stacktrace);',
'    end if;',
'    */',
'',
'    if pi_payload is not null then ',
'      l_error_jo.put( key => pi_payload_attr_name, val => pi_payload );   ',
'    end if;',
'    ',
'    --apex_util.prn(p_clob => l_error_jo.stringify, p_escape => false);',
'    sys.htp.p(l_error_jo.stringify);',
'    po_status_code := flow_rest_constants.c_http_code_ERROR;',
'',
'  end send_error;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure send_success( pi_success_message   varchar2',
'                        , pi_payload           json_element_t default null',
'                        , pi_payload_attr_name varchar2 default null',
'                        , po_status_code       out number )',
'  as',
'    l_success_jo  json_object_t;',
'  begin',
'    l_success_jo := new json_object_t();',
'    l_success_jo.put( key => ''success'', val => true);',
'    l_success_jo.put( key => ''message'', val => pi_success_message);',
'    if pi_payload is not null then ',
'      l_success_jo.put( key => pi_payload_attr_name, val => pi_payload );   ',
'    end if;',
'',
'    --apex_util.prn(p_clob => l_success_jo.stringify, p_escape => false);',
'    sys.htp.p(l_success_jo.stringify);',
'    po_status_code := flow_rest_constants.c_http_code_OK;',
'',
'  end send_success;',
'',
'end flow_rest_response;',
'/',
'',
'create or replace package body flow_rest',
'as',
'',
'  req_apex_host  varchar2(4000);',
'',
'  function get_apex_host',
'    return varchar2',
'  as',
'  begin',
'    return req_apex_host;',
'  end get_apex_host;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure set_apex_host',
'  as',
'  begin',
'',
'    req_apex_host := flow_rest.get_config_value( pi_key => flow_rest_constants.c_config_key_base);',
'',
'    if req_apex_host is null then',
'      begin',
'        req_apex_host :=  owa_util.get_cgi_env(''X-APEX-BASE'');',
'      exception',
'        when others then ',
'          null;',
'      end;',
'    end if;',
'',
'    if req_apex_host is not null and trim(req_apex_host) not like ''%/'' then',
'      req_apex_host := req_apex_host || ''/'';',
'    end if;',
'    ',
'  end set_apex_host;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  function get_config_value( pi_key  flow_configuration.cfig_key%type )',
'    return flow_configuration.cfig_value%type',
'  as',
'    l_key    flow_configuration.cfig_key%type := flow_rest_constants.c_config_prefix || pi_key;',
'    l_value  flow_configuration.cfig_value%type;',
'  begin ',
'    select cfig_value',
'      into l_value',
'      from flow_configuration ',
'      where cfig_key = l_key;',
'    return l_value;',
'  end get_config_value;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'  ',
'  procedure initialize( pi_client_id varchar2',
'                      , pi_method    varchar2 ',
'                      , pi_endpoint  varchar2 )',
'  as',
'    l_check_privilege  varchar2(50 char);',
'  begin',
'',
'    case upper(pi_method) ',
'      when ''POST'' then',
'        l_check_privilege := flow_rest_constants.c_rest_priv_write;',
'      when ''PUT''  then         ',
'        if regexp_like(pi_endpoint, ''^v1/messages/[[:alnum:][:blank:][:punct:]]+$'', ''i'') then',
'          l_check_privilege := flow_rest_constants.c_rest_priv_messages;',
'        else',
'          l_check_privilege := flow_rest_constants.c_rest_priv_write;',
'        end if;',
'      when ''DELETE'' then ',
'        l_check_privilege := flow_rest_constants.c_rest_priv_admin;',
'    end case;',
'',
'    flow_rest.initialize( pi_client_id        => pi_client_id',
'                        , pi_check_privilege  => l_check_privilege ) ;             ',
'',
'  end initialize;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure initialize( pi_client_id        varchar2',
'                      , pi_check_privilege  varchar2 )',
'  as',
'  begin',
'',
'    flow_rest_logging.initialize;',
'',
'    set_apex_host;',
'',
'    flow_globals.set_call_origin( p_origin => flow_rest_constants.c_config_origin );',
'',
'    owa_util.mime_header (''application/json'', true); ',
'',
'    flow_rest_auth.check_privilege( pi_client_id       => pi_client_id ',
'                                  , pi_privilege_name  => pi_check_privilege );                              ',
'',
'  end initialize;',
'',
