'',
'  procedure process_status_update( pi_prcs_id   flow_processes.prcs_id%type ',
'                                 , pi_payload   in out nocopy json_object_t )',
'  as',
'  begin',
'',
'    if not chk_attributes_exist( pio_object_jo       => pi_payload',
'                               , pi_attributes_list  => flow_rest_constants.c_check_attr_process_update',
'                               , pi_add_error_msg    => true ) ',
'    then',
'      raise flow_rest_constants.e_attribute_not_found;',
'    end if;',
'',
'    case lower(pi_payload.get_string( ''status'' ))',
'      when flow_rest_constants.c_process_status_start then',
'        flow_api_pkg.flow_start( p_process_id => pi_prcs_id );',
'',
'      when flow_rest_constants.c_process_status_reset then',
'        flow_api_pkg.flow_reset( p_process_id => pi_prcs_id',
'                               , p_comment    => pi_payload.get_string( ''comment'' ));',
'',
'      when flow_rest_constants.c_process_status_terminate then',
'        flow_api_pkg.flow_terminate( p_process_id  => pi_prcs_id',
'                                   , p_comment     => pi_payload.get_string( ''comment'' ));    ',
'',
'      else',
'        raise flow_rest_constants.e_process_unknown_status;',
'    end case;',
'',
'  end process_status_update;                          ',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure process_vars_update( pi_prcs_id    flow_processes.prcs_id%type ',
'                               , pio_prov_arr  in out nocopy json_array_t ',
'                               , pi_add_error_msg   boolean default true )',
'  as ',
'    l_prov_object  json_object_t;',
'    l_error_occured boolean := false;',
'  begin',
'',
'    verify_process_exists( pi_prcs_id => pi_prcs_id );',
'',
'    for idx_json in 0..pio_prov_arr.get_size-1',
'    loop',
'      begin',
'        l_prov_object := treat(pio_prov_arr.get(idx_json) as json_object_t);',
'',
'        if not chk_attributes_exist( pio_object_jo       => l_prov_object',
'                                   , pi_attributes_list  => flow_rest_constants.c_check_attr_process_var_update',
'                                   , pi_add_error_msg    => pi_add_error_msg ) ',
'        then',
'          raise flow_rest_constants.e_attribute_not_found;',
'        end if;',
'',
'        if not l_prov_object.has( flow_rest_constants.c_json_prov_sbfl_id ) then',
'          case lower( l_prov_object.get_string( flow_rest_constants.c_json_prov_type ) )',
'            when flow_rest_constants.c_pvar_type_varchar then',
'              flow_process_vars.set_var( pi_prcs_id   => pi_prcs_id',
'                                       , pi_var_name  => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_scope     => nvl( l_prov_object.get_string( flow_rest_constants.c_json_prov_scope ), 0)',
'                                       , pi_vc2_value => l_prov_object.get_string( flow_rest_constants.c_json_prov_value ) );',
'            when flow_rest_constants.c_pvar_type_number then',
'              flow_process_vars.set_var( pi_prcs_id   => pi_prcs_id',
'                                       , pi_var_name  => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_scope     => nvl( l_prov_object.get_string( flow_rest_constants.c_json_prov_scope ), 0)',
'                                       , pi_num_value => to_number(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'            when flow_rest_constants.c_pvar_type_date then',
'              flow_process_vars.set_var( pi_prcs_id    => pi_prcs_id',
'                                       , pi_var_name   => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_scope      => nvl( l_prov_object.get_string( flow_rest_constants.c_json_prov_scope ), 0)',
'                                       , pi_date_value => to_date(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'            when flow_rest_constants.c_pvar_type_clob then',
'              flow_process_vars.set_var( pi_prcs_id    => pi_prcs_id',
'                                       , pi_var_name   => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_scope      => nvl( l_prov_object.get_string( flow_rest_constants.c_json_prov_scope ), 0)',
'                                       , pi_clob_value => to_clob(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'          end case;',
'        else',
'          case lower( l_prov_object.get_string( flow_rest_constants.c_json_prov_type ) )',
'            when flow_rest_constants.c_pvar_type_varchar then',
'              flow_process_vars.set_var( pi_prcs_id   => pi_prcs_id',
'                                       , pi_var_name  => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_sbfl_id   => l_prov_object.get_number( flow_rest_constants.c_json_prov_sbfl_id )',
'                                       , pi_vc2_value => l_prov_object.get_string( flow_rest_constants.c_json_prov_value ) );',
'            when flow_rest_constants.c_pvar_type_number then',
'              flow_process_vars.set_var( pi_prcs_id   => pi_prcs_id',
'                                       , pi_var_name  => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_sbfl_id   => l_prov_object.get_number( flow_rest_constants.c_json_prov_sbfl_id )',
'                                       , pi_num_value => to_number(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'            when flow_rest_constants.c_pvar_type_date then',
'              flow_process_vars.set_var( pi_prcs_id    => pi_prcs_id',
'                                       , pi_var_name   => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_sbfl_id    => l_prov_object.get_number( flow_rest_constants.c_json_prov_sbfl_id )',
'                                       , pi_date_value => to_date(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'            when flow_rest_constants.c_pvar_type_clob then',
'              flow_process_vars.set_var( pi_prcs_id    => pi_prcs_id',
'                                       , pi_var_name   => l_prov_object.get_string( flow_rest_constants.c_json_prov_name )',
'                                       , pi_sbfl_id    => l_prov_object.get_number( flow_rest_constants.c_json_prov_sbfl_id )',
'                                       , pi_clob_value => to_clob(l_prov_object.get_string( flow_rest_constants.c_json_prov_value )) );',
'          end case;',
'        end if;',
'',
'',
'      exception ',
'        when flow_rest_constants.e_attribute_not_found then',
'          l_error_occured := true;     ',
'        when others then ',
'          l_error_occured := true;',
'          if pi_add_error_msg then ',
'            add_error( pio_object_jo  => l_prov_object',
'                     , pi_error_type  => flow_rest_constants.c_json_error_type_processing_error',
'                     , pi_error_msg   => SQLERRM );',
'          end if;',
'      end;',
'    ',
'    end loop;',
'',
'    if l_error_occured then ',
'      raise flow_rest_constants.e_processing_error;',
'    end if;',
'',
'  end process_vars_update;',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure process_vars_delete( pi_prcs_id    flow_processes.prcs_id%type ',
'                               , pio_prov_arr  in out nocopy json_array_t ',
'                               , pi_add_error_msg   boolean default true )',
'  as ',
'    l_prov_object    json_object_t;',
'    l_error_occured  boolean := false;',
'  begin',
'',
'    verify_process_exists( pi_prcs_id => pi_prcs_id );',
'',
'    for idx_json in 0..pio_prov_arr.get_size-1',
'    loop',
'      begin',
'        l_prov_object := treat(pio_prov_arr.get(idx_json) as json_object_t);',
'',
'        -- check if necessary parameters exists',
'        if not chk_attributes_exist( pio_object_jo       => l_prov_object',
'                                   , pi_attributes_list  => flow_rest_constants.c_check_attr_process_var_delete',
'                                   , pi_add_error_msg    => pi_add_error_msg ) ',
'        then',
'          raise flow_rest_constants.e_attribute_not_found;',
'        end if;',
'',
'        if not l_prov_object.has(''sbfl_id'') then',
'          flow_process_vars.delete_var( pi_prcs_id   => pi_prcs_id',
'                                      , pi_scope     => nvl( l_prov_object.get_string(''scope''), 0) ',
'                                      , pi_var_name  => l_prov_object.get_string(''name'') );',
'        else',
'          flow_process_vars.delete_var( pi_prcs_id   => pi_prcs_id',
'                                      , pi_sbfl_id   => l_prov_object.get_number(''sbfl_id'')',
'                                      , pi_var_name  => l_prov_object.get_string(''name'') );',
'        end if;',
'',
'        exception ',
'        when flow_rest_constants.e_attribute_not_found then',
'          l_error_occured := true;     ',
'        when others then ',
'          l_error_occured := true;',
'          if pi_add_error_msg then ',
'            add_error( pio_object_jo  => l_prov_object',
'                     , pi_error_type  => flow_rest_constants.c_json_error_type_processing_error',
'                     , pi_error_msg   => SQLERRM );',
'          end if;',
'      end;',
'    end loop;         ',
'                      ',
'    if l_error_occured then ',
'      raise flow_rest_constants.e_processing_error;',
'    end if;',
'',
'  end process_vars_delete;',
'  ',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure step_update( pi_sbfl_id  flow_subflows.sbfl_id%type',
'                       , pi_payload   in out nocopy json_object_t )',
'  as',
'  begin',
'',
'    verify_subflow_exists( pi_sbfl_id => pi_sbfl_id );',
'    ',
'    if not chk_attributes_exist(pio_object_jo      => pi_payload',
'                              , pi_attributes_list => flow_rest_constants.c_check_attr_step_update',
'                              , pi_add_error_msg   => true)',
'    then ',
'      raise flow_rest_constants.e_attribute_not_found;',
'    end if; ',
'',
'    case lower( pi_payload.get_string(flow_rest_constants.c_step_status_status) )',
'      when flow_rest_constants.c_step_status_start then',
'        flow_api_pkg.flow_start_step( p_process_id => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                    , p_subflow_id => pi_sbfl_id ',
'                                    , p_step_key   => pi_payload.get_string(''step_key'') );',
'      when flow_rest_constants.c_step_status_reserve then',
'        flow_api_pkg.flow_reserve_step( p_process_id  => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                      , p_subflow_id  => pi_sbfl_id ',
'                                      , p_step_key    => pi_payload.get_string(''step_key'')',
'                                      , p_reservation => pi_payload.get_string(''reservation'') );',
'      when flow_rest_constants.c_step_status_release then',
'        flow_api_pkg.flow_release_step( p_process_id => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                      , p_subflow_id => pi_sbfl_id',
'                                      , p_step_key   => pi_payload.get_string(''step_key'') );',
'      when flow_rest_constants.c_step_status_complete then',
'        flow_api_pkg.flow_complete_step( p_process_id  => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                        , p_subflow_id  => pi_sbfl_id',
'                                        , p_step_key    => pi_payload.get_string(''step_key'') );',
'      when flow_rest_constants.c_step_status_restart then',
'        flow_api_pkg.flow_restart_step( p_process_id  => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                      , p_subflow_id  => pi_sbfl_id',
'                                      , p_step_key    => pi_payload.get_string(''step_key'') );',
'      when flow_rest_constants.c_step_status_reschedule_timer then',
'        flow_api_pkg.flow_reschedule_timer( p_process_id    => get_process_id( p_sbfl_id => pi_sbfl_id )',
'                                          , p_subflow_id    => pi_sbfl_id',
'                                          , p_step_key      => pi_payload.get_string(''step_key'')',
'                                          , p_is_immediate  => pi_payload.get_boolean(''is_immediate'') ',
'                                          , p_new_timestamp => cast(pi_payload.get_date(''new_timestamp'') as timestamp)',
'                                          , p_comment       => pi_payload.get_string(''comment'') );',
'      else',
'        raise flow_rest_constants.e_step_unknown_operation;',
'    end case;',
'',
'  end step_update;                       ',
'',
'  -------------------------------------------------------------------------------------------------------------------',
'',
'  procedure messages_update( pi_message_name   flow_message_subscriptions.msub_message_name%type ',
'                           , pi_msg_arr        in out nocopy json_array_t )',
'  as ',
'    l_msg_object  json_object_t;',
'    l_error_occured boolean := false;',
'  begin',
'',
'    for idx_json in 0..pi_msg_arr.get_size-1',
'    loop',
'      begin',
'        l_msg_object := treat(pi_msg_arr.get(idx_json) as json_object_t);',
'',
'        -- check if necessary parameters exists',
'        if not chk_attributes_exist(pio_object_jo      => l_msg_object',
'                                  , pi_attributes_list => flow_rest_constants.c_check_attr_message_update',
'                                  , pi_add_error_msg   => true)',
'        then ',
'          raise flow_rest_constants.e_attribute_not_found;',
'        end if;',
'',
'        flow_api_pkg.receive_message( p_message_name  => pi_message_name',
'                                    , p_key_name      => l_msg_object.get_string(''key'')',
'                                    , p_key_value     => l_msg_object.get_string(''value'')',
'                                    , p_payload       => l_msg_object.get_clob(''payload'') );',
'',
'        exception ',
'            when flow_rest_constants.e_attribute_not_found then ',
'              l_error_occured := true;',
'      end;',
'    end loop;',
'',
'    if l_error_occured then ',
'      raise flow_rest_constants.e_processing_error;',
'    end if;',
'',
'  end messages_update;',
'  ',
'',
'end flow_rest;',
'/',
'',
'create or replace package body flow_services',
'/* ',
'-- Flows for APEX - flow_services.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and/or its affiliates. 2025.',
'--',
'-- Created  21-Nov-2021  Louis Moreaux (Insum, for MT AG) ',
'-- Edited   13-Apr-2022  Richard Allen (Oracle)',
'-- Modified 01-Jun-2022  Moritz Klein (MT AG)',
'-- Edited   09-Apr-2025  Richard Allen (Flowquest)',
'--',
'*/',
'as',
'  g_workspace varchar2(100) := flow_engine_util.get_config_value(',
'                                   p_config_key    => ''default_workspace''',
'                                 , p_default_value => flow_constants_pkg.gc_config_default_default_workspace',
'                               );',
'',
'  g_email_sender varchar2(100) := flow_engine_util.get_config_value(',
'                                   p_config_key    => ''default_email_sender''',
'                                 , p_default_value => ''''  ',
'                               );',
'',
'  procedure set_workspace_id',
'  (',
'    p_workspace_name in varchar2',
'  )',
'  is',
'    l_workspace_id number;',
'  begin',
'    l_workspace_id := apex_util.find_security_group_id (p_workspace => p_workspace_name);',
'    if (l_workspace_id is null) then',
'      raise e_wrong_default_workspace;',
'    end if;',
'    apex_util.set_security_group_id (p_security_group_id => l_workspace_id);',
'  end set_workspace_id;',
'',
'  procedure get_config',
'  (',
'    pi_objt_id           in flow_objects.objt_id%type',
'  , po_from             out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_to               out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_cc               out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_bcc              out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_reply_to         out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_use_template     out nocopy boolean',
'  , po_template_id      out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_placeholders     out nocopy clob',
'  , po_immediate        out nocopy boolean',
'  , po_application_id   out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_subject          out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  , po_body             out nocopy clob',
'  , po_body_html        out nocopy clob',
'  , po_attachment_query out nocopy flow_types_pkg.t_bpmn_attribute_vc2',
'  )',
'  as',
'    l_plain_config     clob;',
'    l_json_config      sys.json_object_t;',
'    l_body             sys.json_array_t;',
'    l_body_html        sys.json_array_t;',
'    l_attachment_query sys.json_array_t;',
'    l_placeholders     sys.json_object_t;',
'    procedure json_array_to_clob',
'    (',
'      pi_array  in sys.json_array_t',
'    , po_clob  out nocopy clob',
'    )',
'    as',
'    begin',
'      if pi_array is not null then',
'        for i in 0..pi_array.get_size - 1 loop',
'          po_clob := po_clob || pi_array.get_string(i) || apex_application.lf;',
'        end loop;',
'      end if;',
'    end json_array_to_clob;',
'  begin',
'    select json_query( objt.objt_attributes format json, ''$.apex'' returning clob ) as json_data',
'      into l_plain_config',
'      from flow_objects objt',
'     where objt.objt_id = pi_objt_id',
'    ;',
'    l_json_config      := sys.json_object_t.parse( l_plain_config );',
'',
'    po_from           := l_json_config.get_string( ''emailFrom'' );',
'    po_to             := l_json_config.get_string( ''emailTo'' );',
'    po_cc             := l_json_config.get_string( ''emailCC'' );',
'    po_bcc            := l_json_config.get_string( ''emailBCC'' );',
'    po_reply_to       := l_json_config.get_string( ''emailReplyTo'' );',
'    po_use_template   := coalesce( l_json_config.get_boolean( ''useTemplate'' ), false );',
'    po_application_id := l_json_config.get_string( ''applicationId'' );',
'    po_template_id    := l_json_config.get_string( ''templateId'' );',
'    po_subject        := l_json_config.get_string( ''subject'' );',
'    po_immediate      := coalesce( l_json_config.get_boolean( ''immediately'' ), false );',
'',
'    if l_json_config.has( ''placeholder'' ) then',
'      l_placeholders  := l_json_config.get_object( ''placeholder'' );',
'      po_placeholders := l_placeholders.to_clob;',
'    end if;',
'',
'    json_array_to_clob( pi_array => l_json_config.get_array( ''bodyText'' ),   po_clob => po_body );',
'    json_array_to_clob( pi_array => l_json_config.get_array( ''bodyHTML'' ),   po_clob => po_body_html );',
'    json_array_to_clob( pi_array => l_json_config.get_array( ''attachment'' ), po_clob => po_attachment_query );',
'',
'  end get_config;',
'',
'  procedure send_email',
'  (',
'    pi_prcs_id in flow_processes.prcs_id%type',
'  , pi_sbfl_id in flow_subflows.sbfl_id%type',
'  , pi_objt_id in flow_objects.objt_id%type',
'  )',
'  is',
'    l_from             flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_to               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_cc               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_bcc              flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_reply_to         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_use_template     boolean := false;',
'    l_template_id      flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_placeholders     clob;',
'    l_immediate        boolean := false;',
'    l_application_id   flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_subject          flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_body             clob;',
'    l_body_html        clob;',
'    l_attachment_query flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_mail_id          number;',
'    type t_attachment  is record (file_name varchar2(200), mime_type varchar2(200), blob_content blob );',
'    type t_attachments is table of t_attachment;',
'    l_attachments      t_attachments;',
'    l_workspace        varchar2(100);',
'    l_session          varchar2(20) := v(''APP_SESSION'');',
'    l_json_object      sys.json_object_t;',
'    l_scope            flow_subflows.sbfl_scope%type;',
'  begin',
'    apex_debug.enter( p_routine_name => ''send_email'', p_name01 => ''pi_objt_id'', p_value01 => pi_objt_id );',
'',
'    l_scope := flow_engine_util.get_scope ( p_process_id => pi_prcs_id, p_subflow_id => pi_sbfl_id );',
'    flow_globals.set_context( pi_prcs_id        => pi_prcs_id',
'                            , pi_sbfl_id        => pi_sbfl_id',
'                            , pi_scope          => l_scope ',
'                            , pi_loop_counter   => flow_engine_util.get_loop_counter (pi_sbfl_id => pi_sbfl_id));',
'',
'    -- Pull all configuration from objt_attributes JSON structure',
'    get_config',
'    (',
'      pi_objt_id          => pi_objt_id',
'    , po_from             => l_from',
'    , po_to               => l_to',
'    , po_cc               => l_cc',
'    , po_bcc              => l_bcc',
'    , po_reply_to         => l_reply_to',
'    , po_use_template     => l_use_template',
'    , po_template_id      => l_template_id',
'    , po_placeholders     => l_placeholders',
'    , po_immediate        => l_immediate',
'    , po_application_id   => l_application_id',
'    , po_subject          => l_subject',
'    , po_body             => l_body',
'    , po_body_html        => l_body_html',
'    , po_attachment_query => l_attachment_query',
'    );',
'',
'    -- Substitute process variables where needed',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_from );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_to );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_cc );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_bcc );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_reply_to );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_application_id );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_template_id );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_placeholders );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_subject );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_body );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_body_html );',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_scope => l_scope, pio_string => l_attachment_query );',
'',
'    l_from := coalesce( l_from, g_email_sender );',
'    -- Raise error if needed',
'    -- no sender',
'    if l_from is null then',
'        raise e_email_no_from;',
'    end if;',
'    --no recipient',
'    if l_to is null then',
'      raise e_email_no_to;',
'    end if;',
'',
'    -- Set the workspace if no session',
'    -- Useful for timers',
'    if ( l_session is null ) then',
'      if ( l_use_template ) then',
'        begin',
'          select workspace ',
'            into l_workspace',
'            from apex_applications',
'           where application_id = l_application_id;',
'        exception when no_data_found then',
'          raise e_workspace_not_found;',
'        end;',
'      else',
'        l_workspace := g_workspace;         ',
'      end if;',
'',
'      set_workspace_id(p_workspace_name => l_workspace);',
'    end if;',
'',
'    if l_use_template then',
'      if l_application_id is null or l_template_id is null then',
'        raise e_email_no_template;',
'      end if;',
'',
'      apex_debug.message(''sys.dbms_lob.getlength(l_placeholders) '' ||sys.dbms_lob.getlength(l_placeholders));',
'      if sys.dbms_lob.getlength(l_placeholders) > 0  then',
'        begin',
'          l_json_object := json_object_t(l_placeholders);',
'        exception',
'          when others then',
'            raise e_json_not_valid;',
'        end;',
'      end if;',
'',
'      l_mail_id := apex_mail.send(',
'        p_template_static_id => l_template_id,',
'        p_placeholders       => l_placeholders,',
'        p_to                 => l_to,',
'        p_cc                 => l_cc,',
'        p_bcc                => l_bcc,',
'        p_from               => l_from,',
'        p_replyto            => l_reply_to,',
'        p_application_id     => l_application_id',
'      );',
'',
'    else',
'',
'      if l_body is null then',
'        raise e_email_no_body;',
'      end if;',
'',
'      l_mail_id := apex_mail.send(',
'        p_to        => l_to, ',
'        p_from      => l_from,',
'        p_cc        => l_cc,',
'        p_bcc       => l_bcc,',
'        p_replyto   => l_reply_to,',
'        p_body      => l_body,',
'        p_body_html => l_body_html,',
'        p_subj      => l_subject',
'      );',
'',
'    end if;',
'',
'    if (l_attachment_query is not null ) then',
'',
'      execute immediate l_attachment_query ',
'      bulk collect into  l_attachments;',
'',
'      for i in 1..l_attachments.count()',
'      loop',
'        apex_mail.add_attachment(',
'          p_mail_id    => l_mail_id,',
'          p_attachment => l_attachments(i).blob_content,',
'          p_filename   => l_attachments(i).file_name,',
'          p_mime_type  => l_attachments(i).mime_type',
'        );',
'      end loop;',
'    end if;',
'',
'    if (l_immediate ) then',
'      apex_mail.push_queue;',
'    end if;',
'    ',
'  exception',
'    when e_wrong_default_workspace then',
'      apex_debug.error',
'      (',
'        p_message => ''Default workspace %s is not valid''',
'      , p0        => g_workspace',
'      );',
'      raise e_wrong_default_workspace;',
'    when e_workspace_not_found then',
'      apex_debug.error',
'      (',
'        p_message => ''Unable to find the workspace for application id %s''',
'      , p0        => l_application_id',
'      );',
'      raise e_workspace_not_found;',
'    when e_email_no_from then ',
'      apex_debug.error',
'      (',
'        p_message => ''Email service task requires from attribute''',
'      );',
'      raise e_email_no_from; ',
'    when e_email_no_to then ',
'      apex_debug.error',
'      (',
'        p_message => ''Email service task requires to attribute''',
'      );',
'      raise e_email_no_to;  ',
'    when e_email_no_template then',
'      apex_debug.error',
'      (',
'        p_message => ''Email service task use email template but no template id define''',
'      );',
'      raise e_email_no_template;  ',
'    when e_email_no_body then',
'      apex_debug.error',
'      (',
'        p_message => ''Email service task body is missing''',
'      );',
'      raise e_email_no_body;',
'    when e_json_not_valid then',
'      apex_debug.error',
'      (',
'        p_message => ''Placeholder JSON object is invalid.''',
'      );',
'      apex_debug.log_long_message',
'      (',
'          p_message => l_placeholders',
'        , p_level   => apex_debug.c_log_level_error',
'      );',
'      raise e_json_not_valid;',
'    when others then',
'      apex_debug.error',
'      (',
'        p_message => ''Error during flow_services.send_email. SQLERRM: %s''',
'      , p0        => sqlerrm',
'      );',
'      raise e_email_failed;',
'',
'    end send_email;',
'',
'  procedure apex_AI_generation ',
'  ( p_sbfl_info   in flow_subflows%rowtype  ',
'  , p_step_info   in flow_types_pkg.flow_step_info',
'  )',
'  is',
'    l_ai_model_setting         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_ai_prompt_setting        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_ai_temperature_setting   flow_types_pkg.t_bpmn_attribut'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'e_vc2; ',
'    l_ai_model                 flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_ai_prompt                flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_ai_temperature           flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_result_var               flow_types_pkg.t_bpmn_attribute_vc2; ',
'    l_result                   clob;',
'  begin',
'    apex_debug.enter( p_routine_name => ''service task - type apex_AI_generation'' );',
'',
'    -- Pull all configuration from objt_attributes JSON structure',
'    l_ai_model_setting       := json_query ( p_step_info.target_objt_attributes, ''$.apex.aiService''     returning varchar2);',
'    l_ai_prompt_setting      := json_query ( p_step_info.target_objt_attributes, ''$.apex.aiPrompt''      returning varchar2);',
'    l_ai_temperature_setting := json_query ( p_step_info.target_objt_attributes, ''$.apex.aiTemperature'' returning varchar2);',
'    l_result_var             := json_value ( p_step_info.target_objt_attributes, ''$.apex.resultVariable''    returning varchar2);',
'',
'    -- Get the AI model and prompt',
'    l_ai_model       := flow_settings.get_vc2_expression ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                                         , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                                         , pi_scope   => p_sbfl_info.sbfl_scope',
'                                                         , pi_expr    => l_ai_model_setting ',
'                                                        );',
'    l_ai_prompt      := flow_settings.get_vc2_expression ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                                         , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                                         , pi_scope   => p_sbfl_info.sbfl_scope',
'                                                         , pi_expr    => l_ai_prompt_setting ',
'                                                        );',
'    l_ai_temperature := flow_settings.get_vc2_expression ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                                                         , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                                                         , pi_scope   => p_sbfl_info.sbfl_scope',
'                                                         , pi_expr    => l_ai_temperature_setting ',
'                                                        );                                    ',
' ',
'    -- Call the AI service with the model and prompt',
'    apex_debug.message (p_message => '' Calling APEX AI generation -  service: %0 with prompt: %1'', p0 => l_ai_model, p1 => l_ai_prompt);',
'    l_result := apex_ai.generate',
'                ( p_prompt              => l_ai_prompt',
'                , p_service_static_id   => l_ai_model',
'                , p_temperature         => to_number(l_ai_temperature)',
'                );',
'    -- Set the result in the process variable',
'    flow_proc_vars_int.set_var ',
'    ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'    , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'    , pi_scope          => p_sbfl_info.sbfl_scope',
'    , pi_var_name       => l_result_var',
'    , pi_clob_value    => l_result',
'    );',
'    -- Log the result ',
'    --TODO after merge with dev (needs new logging) before production',
'',
'  end apex_AI_generation;',
'',
'end flow_services;',
'/',
'',
'create or replace package body flow_settings',
'as ',
'/* ',
'-- Flows for APEX - flow_settings.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022-2023.',
'-- (c) Copyright Flowquest Limited. 2024',
'--',
'-- Created    23-Nov-2022  Richard Allen (Oracle)',
'-- Modified   13-Apr-2023  Moritz Klein (MT GmbH)',
'-- Modified   11-Feb-2024  Richard Allen (Flowquest Limited)',
'--',
'*/',
'',
'  type expression_details_t is',
'    record',
'    (',
'      expr_type         flow_types_pkg.t_bpmn_attribute_vc2',
'    , expr_value        clob',
'    , expr_fmt          flow_types_pkg.t_bpmn_attribute_vc2',
'    , expr_inside_var   flow_types_pkg.t_bpmn_attribute_vc2',
'    , expr_description  flow_types_pkg.t_bpmn_attribute_vc2',
'    );',
'',
'  function get_expression_details( pi_expr_json in json_object_t )',
'    return expression_details_t',
'  as',
'    l_return    expression_details_t;',
'  begin',
'    apex_debug.enter (''get_expression_details'',''pi_expr_json'',pi_expr_json.to_string);',
'    l_return.expr_type := pi_expr_json.get_string( key => ''expressionType'' );',
'',
'    case pi_expr_json.get_type( key => ''expression'' )',
'      when ''SCALAR'' then',
'        l_return.expr_value := pi_expr_json.get_string( key => ''expression'' );',
'      when ''ARRAY'' then',
'        l_return.expr_value := flow_engine_util.json_array_join( pi_expr_json.get_array( key => ''expression'' ) );',
'      else',
'       null;',
'    end case;',
'    ',
'    l_return.expr_fmt               := pi_expr_json.get_string( key => ''formatMask'' );',
'    l_return.expr_inside_var        := pi_expr_json.get_string( key => ''insideVariable'' );',
'    l_return.expr_description       := pi_expr_json.get_string( key => ''description'');',
'',
'    apex_debug.message (p_message => ''get_expression_details - results.  expr_value %0 expr_type %1 expr_fmt %2 expr_inside_var %3 expr_desc %4''',
'    , p0 => l_return.expr_value',
'    , p1 => l_return.expr_type',
'    , p2 => l_return.expr_fmt',
'    , p3 => l_return.expr_inside_var',
'    , p4 => l_return.expr_description',
'    );',
'    return l_return;',
'  end get_expression_details;',
'',
'  function get_expression_details( pi_expr_data in flow_objects.objt_attributes%type )',
'    return expression_details_t',
'  as',
'    l_expr_json sys.json_object_t;',
'    l_return    expression_details_t;',
'  begin',
'    l_expr_json        := sys.json_object_t( jsn => pi_expr_data );',
'    return get_expression_details (pi_expr_json => l_expr_json);',
'  end get_expression_details;',
'',
'  function get_due_on',
'  ( pi_prcs_id       flow_processes.prcs_id%type',
'  , pi_sbfl_id       flow_subflows.sbfl_id%type default null',
'  , pi_expr          flow_objects.objt_attributes%type',
'  , pi_scope         flow_subflows.sbfl_scope%type default 0',
'  ) return timestamp with time zone',
'  is',
'',
'    l_expr_details      expression_details_t;',
'    l_result_rec        flow_proc_vars_int.t_proc_var_value;',
'    l_return_tstz       timestamp with time zone;',
'',
'    e_invalid_interval_spec    exception;',
'    pragma exception_init (e_invalid_interval_spec , -1867);  ',
'',
'  begin',
'    apex_debug.enter',
'    ( p_routine_name => ''flow_settings.get_due_on''',
'    , p_name01       => ''scope''',
'    , p_value01      => pi_scope',
'    , p_name02       => ''expr''',
'    , p_value02      => substr(pi_expr, 4000)',
'    );',
'',
'    l_expr_details := get_expression_details( pi_expr_data  => pi_expr );',
'',
'    apex_debug.message',
'    ( p_message => '' --- JSON Content - expression type: %1, expression :%0, formatMask :%2''',
'    , p0        => substr(l_expr_details.expr_value, 4000)',
'    , p1        => l_expr_details.expr_type',
'    , p2        => l_expr_details.expr_fmt',
'    );',
'',
'    if l_expr_details.expr_type in ( flow_constants_pkg.gc_expr_type_static ',
'                                   , flow_constants_pkg.gc_date_value_type_interval',
'                                   , flow_constants_pkg.gc_date_value_type_oracle_scheduler',
'                                   ) then',
'      -- static types - timestamp, duration and scheduler statics - start by doing substitutions',
'      flow_proc_vars_int.do_substitution',
'        ( pi_prcs_id => pi_prcs_id',
'        , pi_sbfl_id => pi_sbfl_id',
'        , pi_scope   => pi_scope',
'        , pio_string => l_expr_details.expr_value ',
'        );',
'    end if;',
'',
'    case ',
'    when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_static then    ',
'      if l_expr_details.expr_fmt is null then',
'        -- log warning then try to use the F4A default mask',
'        flow_logging.log_step_event ( p_process_id      => pi_prcs_id',
'                                    , p_subflow_id      => pi_sbfl_id',
'                                    , p_event           => flow_constants_pkg.gc_step_event_warning',
'                                    , p_event_level     => flow_constants_pkg.gc_logging_level_routine',
'                                    , p_comment         => ''Timestamp formatMask not present.   Attempting to convert using default Flows for APEX format''',
'                                    );',
'        l_expr_details.expr_fmt := flow_constants_pkg.gc_prov_default_tstz_format;',
'      end if;',
'      l_return_tstz := to_timestamp_tz ( l_expr_details.expr_value, l_expr_details.expr_fmt);',
'    when l_expr_details.expr_type = flow_constants_pkg.gc_date_value_type_interval then',
'      l_return_tstz := systimestamp + to_dsinterval( l_expr_details.expr_value );',
'    when l_expr_details.expr_type = flow_constants_pkg.gc_date_value_type_oracle_scheduler then',
'      sys.dbms_scheduler.evaluate_calendar_string ( calendar_string   => l_expr_details.expr_value',
'                                                  , start_date        => systimestamp -- to get correct TZ, should this be localtimestamp?',
'                                                  , return_date_after => systimestamp',
'                                                  , next_run_date     => l_return_tstz',
'                                                  );',
'      l_return_tstz := l_return_tstz;',
'',
'    when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_proc_var then',
'      l_return_tstz := flow_proc_vars_int.get_var_tstz  ( pi_prcs_id    => pi_prcs_id',
'                                                        , pi_var_name   => l_expr_details.expr_value',
'                                                        , pi_scope      => pi_scope',
'                                                        );       ',
'  ',
'    when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_sql then',
'      l_result_rec := flow_db_exec.exec_flows_sql ',
'                      ( pi_prcs_id      => pi_prcs_id',
'                      , pi_sbfl_id      => pi_sbfl_id',
'                      , pi_sql_text     => l_expr_details.expr_value',
'                      , pi_result_type  => flow_constants_pkg.gc_prov_var_type_tstz',
'                      , pi_scope        => pi_scope',
'                      , pi_expr_type    => flow_constants_pkg.gc_expr_type_sql ',
'                      );',
'      l_return_tstz := l_result_rec.var_tstz;',
'    when l_expr_details.expr_type in ( flow_constants_pkg.gc_expr_type_plsql_function_body ',
'                                     , flow_constants_pkg.gc_expr_type_plsql_raw_function_body ',
'                                     , flow_constants_pkg.gc_expr_type_plsql_expression',
'                                     , flow_constants_pkg.gc_expr_type_plsql_raw_expression )   ',
'    then',
'      l_result_rec := flow_db_exec.exec_flows_plsql ',
'                      ( pi_prcs_id      => pi_prcs_id',
'                      , pi_sbfl_id      => pi_sbfl_id',
'                      , pi_plsql_text   => l_expr_details.expr_value',
'                      , pi_result_type  => flow_constants_pkg.gc_prov_var_type_tstz',
'                      , pi_scope        => pi_scope',
'                      , pi_expr_type    => l_expr_details.expr_type ',
'                      );',
'      l_return_tstz := l_result_rec.var_tstz;',
'    else ',
'      l_return_tstz := null;',
'    end case;',
'    return l_return_tstz;',
'  exception',
'    when e_invalid_interval_spec then',
'      apex_debug.info ',
'      ( p_message => '' --- Error evaluating Due On.  Interval expression is invalid.  Interval: %0.''',
'      , p0        => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_message_key    => ''due-on-interval-error''',
'      , p0                => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      -- $F4AMESSAGE ''due-on-interval-error'' || ''Error evaluating Due On.  Interval expression is invalid.  Interval: %0.''  ',
'      return null;  ',
'    when others then',
'      apex_debug.info ',
'      ( p_message => '' --- Error evaluating Due On.  Due On expression is invalid.  Interval Expression: %0.  ''',
'      , p0 => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_message_key    => ''due-on-error''',
'      , p0 => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      -- $F4AMESSAGE ''due-on-error'' || ''Error evaluating Due On.  Due On expression is invalid.  Interval Expression: %0.''  ',
'      return null;  ',
'  end get_due_on;',
'',
'  function get_priority',
'  ( pi_prcs_id       flow_processes.prcs_id%type',
'  , pi_sbfl_id       flow_subflows.sbfl_id%type default null',
'  , pi_expr          flow_types_pkg.t_bpmn_attribute_vc2',
'  , pi_scope         flow_subflows.sbfl_scope%type default 0',
'  ) return flow_processes.prcs_priority%type',
'  is',
'    l_expr_details                expression_details_t;',
'    l_result_rec                  flow_proc_vars_int.t_proc_var_value;',
'    l_priority                    flow_processes.prcs_priority%type;',
'',
'    e_param_proc_var_invalid_type exception;',
'    e_param_expr_invalid_type     exception;',
'    e_priority_invalid            exception;',
'  begin',
'',
'    l_expr_details := get_expression_details( pi_expr_data  => pi_expr );',
'',
'    case ',
'      when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_static then',
'        flow_proc_vars_int.do_substitution ',
'        ( pi_prcs_id   => pi_prcs_id',
'        , pi_sbfl_id   => pi_sbfl_id',
'        , pi_scope     => pi_scope',
'        , pio_string   => l_expr_details.expr_value',
'        );',
'        apex_debug.info (P_message => ''Set Priority Evaluation : %0 '', p0 => to_number (l_expr_details.expr_value));',
'        l_priority := to_number (l_expr_details.expr_value);',
'      when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_proc_var then',
'        if l_expr_details.expr_value = flow_constants_pkg.gc_substitution_process_priority then',
'          select prcs_priority',
'            into l_priority',
'            from flow_processes',
'          where prcs_id = pi_prcs_id; ',
'        else',
'          case flow_proc_vars_int.get_var_type ( pi_prcs_id   => pi_prcs_id',
'                                              , pi_var_name  => l_expr_details.expr_value',
'                                              , pi_scope     => pi_scope',
'                                              )',
'          when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'            l_priority :=  to_number ( flow_proc_vars_int.get_var_vc2 ( pi_prcs_id   => pi_prcs_id',
'                                                                      , pi_scope     => pi_scope',
'                                                                      , pi_var_name  => l_expr_details.expr_value',
'                                                                      ) );',
'          when flow_constants_pkg.gc_prov_var_type_number then',
'            l_priority :=  flow_proc_vars_int.get_var_num ( pi_prcs_id   => pi_prcs_id',
'                                                          , pi_scope     => pi_scope',
'                                                          , pi_var_name  => l_expr_details.expr_value',
'                                                          );',
'          else',
'            raise e_param_proc_var_invalid_type;',
'          end case;',
'        end if;',
'      when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_sql then',
'        l_result_rec := flow_db_exec.exec_flows_sql ',
'                        ( pi_prcs_id      => pi_prcs_id',
'                        , pi_sbfl_id      => pi_sbfl_id',
'                        , pi_sql_text     => l_expr_details.expr_value',
'                        , pi_result_type  => flow_constants_pkg.gc_prov_var_type_number',
'                        , pi_scope        => pi_scope',
'                        , pi_expr_type    => flow_constants_pkg.gc_expr_type_sql ',
'                        );',
'        l_priority := l_result_rec.var_num;',
'      when l_expr_details.expr_type in ( flow_constants_pkg.gc_expr_type_plsql_expression ',
'                                , flow_constants_pkg.gc_expr_type_plsql_raw_expression',
'                                , flow_constants_pkg.gc_expr_type_plsql_function_body',
'                                , flow_constants_pkg.gc_expr_type_plsql_raw_function_body) ',
'      then',
'        l_result_rec := flow_db_exec.exec_flows_plsql ',
'                        ( pi_prcs_id      => pi_prcs_id',
'                        , pi_sbfl_id      => pi_sbfl_id',
'                        , pi_plsql_text   => l_expr_details.expr_value',
'                        , pi_result_type  => flow_constants_pkg.gc_prov_var_type_number',
'                        , pi_scope        => pi_scope',
'                        , pi_expr_type    => l_expr_details.expr_type ',
'                        );',
'        l_priority := l_result_rec.var_num;',
'      else',
'        pragma coverage (''not_feasible'');',
'        raise e_param_expr_invalid_type;',
'    end case;',
'    -- test priority is valid (1-5)',
'    if l_priority not between 1 and 5 then',
'      raise e_priority_invalid;',
'    end if;',
'    return l_priority;',
'  exception',
'    when e_priority_invalid then',
'      apex_debug.info ',
'      ( p_message => '' --- Error evaluating Priority.  Priority be between 1 and 5.  Priority: %0''',
'      , p0 => l_priority',
'      );  ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_message_key    => ''apex-task-priority-error''',
'      , p0 => l_priority',
'      );  ',
'      -- $F4AMESSAGE ''apex-task-priority-error'' || ''Error evaluating Priority.  Priority must be between 1 and 5.  Priority: %0. Priority 3 used instead.''   ',
'      return null; ',
'    when others then ',
'      apex_debug.info ',
'      ( p_message => '' --- Error evaluating Priority.  Priority expression is invalid.  Expression: %0.  priority 3 returned.''',
'      , p0        => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => pi_prcs_id',
'      , pi_message_key => ''settings-priority-error''',
'      , p0             => substr(l_expr_details.expr_value, 4000)',
'      );  ',
'      -- $F4AMESSAGE ''settings-priority-error'' || ''Error evaluating Priority. Priority expression is invalid.  Expression: %0.  Priority 3 used instead.''  ',
'      return 3;',
'  end get_priority;',
'',
'  function get_vc2_expression',
'  ( pi_prcs_id       flow_processes.prcs_id%type default null',
'  , pi_sbfl_id       flow_subflows.sbfl_id%type default null',
'  , pi_expr          flow_types_pkg.t_bpmn_attribute_vc2 default null',
'  , pi_scope         flow_subflows.sbfl_scope%type default 0',
'  , pi_step_key      flow_subflows.sbfl_step_key%type default null',
'  ) return flow_types_pkg.t_bpmn_attribute_vc2',
'  is',
'    l_expr_details expression_details_t;',
'    l_result_rec   flow_proc_vars_int.t_proc_var_value;',
'    l_return_value flow_types_pkg.t_bpmn_attribute_vc2;',
'',
'    e_param_proc_var_invalid_type exception;',
'    e_param_expr_invalid_type     exception;',
'    e_param_type_requires_prcs_id exception;',
'  begin',
'    apex_debug.enter ',
'    ( ''get_vc2_expression''',
'    , ''pi_expr''   , pi_expr',
'    );',
'    ',
'    if pi_expr is null then',
'      return null;',
'    end if;',
'',
'    l_expr_details := get_expression_details( pi_expr_data  => pi_expr );',
'',
'   case ',
'      when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_static then',
'        flow_proc_vars_int.do_substitution ',
'        ( pi_prcs_id   => pi_prcs_id',
'        , pi_sbfl_id   => pi_sbfl_id',
'        , pi_scope     => pi_scope',
'        , pi_step_key  => pi_step_key',
'        , pio_string   => l_expr_details.expr_value',
'        );',
'        l_return_value := l_expr_details.expr_value;',
'      when l_expr_details.expr_type = flow_constants_pkg.gc_expr_type_proc_var then',
'        if pi_prcs_id is null then ',
'          -- proc var setting type cannot be used without a prcs_id',
'          raise e_param_type_requires_prcs_id; ',
'        end if;',
'        case flow_proc_vars_int.get_var_type ( pi_prcs_id   => pi_prcs_id',
'                                             , pi_var_name  => l_expr_details.expr_value',
'                                             , pi_scope     => pi_scope',
'                                             )',
'          when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'            l_return_value := ( flow_proc_vars_int.get_var_vc2  ( pi_prcs_id   => pi_prcs_id',
'                                                                , pi_scope     => pi_scope',
'                                                                , pi_var_name  => l_expr_details.expr_value',
'                                                                ) );',
'          when flow_constants_pkg.gc_prov_var_type_number then',
'            l_return_value := to_char ( flow_proc_vars_int.get_var_num  ( pi_prcs_id   => pi_prcs_id',
'                                                                , pi_scope     => pi_scope',
'                                                                , pi_var_name  => l_expr_details.expr_value',
'                                                                ) );',
'          when flow_constants_pkg.gc_prov_var_type_clob then',
'            l_return_value := ( flow_proc_vars_int.get_var_clob ( pi_prcs_id   => pi_prcs_id',
'                                                                , pi_scope     => pi_scope',
'                                                                , pi_var_name  => l_expr_details.expr_value',
'                                                                ) );                                                         ',
'          else',
'            raise e_param_proc_var_invalid_type;',
'          end case;',
'      when l_expr_details.expr_type in ( flow_constants_pkg.gc_expr_type_sql, flow_constants_pkg.gc_expr_type_sql_delimited_list ) then',
'        l_result_rec := flow_db_exec.exec_flows_sql',
'                        ( pi_prcs_id      => pi_prcs_id',
'                        , pi_sbfl_id      => pi_sbfl_id',
'                        , pi_sql_text     => l_expr_details.expr_value',
'                        , pi_result_type  => flow_constants_pkg.gc_prov_var_type_varchar2',
'                        , pi_scope        => pi_scope',
'                        , pi_expr_type    => l_expr_details.expr_type',
'                        );',
'        l_return_value := l_result_rec.var_vc2;',
'      when l_expr_details.expr_type in ( flow_constants_pkg.gc_expr_type_plsql_expression ',
'                                       , flow_constants_pkg.gc_expr_type_plsql_raw_expression ',
'                                       , flow_constants_pkg.gc_expr_type_plsql_function_body',
'                                       , flow_constants_pkg.gc_expr_type_plsql_raw_function_body',
'                                       )',
'      then',
'        l_result_rec := flow_db_exec.exec_flows_plsql ',
'                        ( pi_prcs_id      => pi_prcs_id',
'                        , pi_sbfl_id      => pi_sbfl_id',
'                        , pi_plsql_text   => l_expr_details.expr_value',
'                        , pi_result_type  => flow_constants_pkg.gc_prov_var_type_varchar2',
'                        , pi_scope        => pi_scope',
'                        , pi_expr_type    => l_expr_details.expr_type ',
'                        );',
'        l_return_value := l_result_rec.var_vc2;',
'      else',
'        raise e_param_expr_invalid_type;',
'    end case;',
'    return l_return_value;',
'  exception',
'    when e_param_type_requires_prcs_id then',
'      flow_errors.handle_general_error (pi_message_key => ''settings-procvar-no-prcs'');',
'      return null;',
'      -- $F4AMESSAGE ''settings-procvar-no-prcs'' || ''Settings cannot specify Process Variable without a Process ID.''',
'    when others then ',
'      apex_debug.info ',
'      ( p_message => '' --- Error evaluating Setting.  Expression is invalid.  Expression: %0. SQL Error: %1''',
'      , p0 => substr(l_expr_details.expr_value, 4000)',
'      , p1 => sqlerrm',
'      );  ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_message_key    => ''settings-error''',
'      , p0 => substr(l_expr_details.expr_value, 4000)',
'      , p1 => sqlerrm',
'      ); ',
'      return null;',
'      -- $F4AMESSAGE ''settings-error'' || ''Error evaluating Setting. Expression is invalid.  Expression: %0. SQL Error: %1'' ',
'  end get_vc2_expression;',
'',
'  function get_clob_expression',
'  ( pi_prcs_id       flow_processes.prcs_id%type',
'  , pi_sbfl_id       flow_subflows.sbfl_id%type',
'  , pi_expr          clob',
'  , pi_scope         flow_subflows.sbfl_scope%type default 0',
'  , pi_step_key      flow_subflows.sbfl_step_key%type default null',
'  ) return clob',
'  is',
'    l_expr_details expression_details_t;',
'    l_return_value clob;',
'    l_result_rec   flow_proc_vars_int.t_proc_var_value;',
'',
'    e_param_proc_var_invalid_type exception;',
'    e_param_expr_invalid_type     exception;',
'  begin',
