'create or replace package body flow_simple_form_template',
'as',
'/* ',
'-- Flows for APEX - flow_simple_form_template.pkb',
'-- ',
'-- (c) Copyright Hyand, 2024',
'--',
'-- Created  20-Aug-2024  Dennis Amthor - Hyand',
'--',
'*/',
'  function create_template(',
'    pi_sfte_name      in flow_simple_form_templates.sfte_name%type',
'  , pi_sfte_static_id in flow_simple_form_templates.sfte_static_id%type',
'  , pi_sfte_content   in flow_simple_form_templates.sfte_content%type)',
'  return flow_simple_form_templates.sfte_id%type',
'  as',
'    l_template_exists binary_integer;',
'    l_sfte_id flow_simple_form_templates.sfte_id%type;',
'  begin',
'    select count(*)',
'      into l_template_exists',
'      from dual',
'     where exists(',
'           select null',
'             from flow_simple_form_templates',
'            where sfte_static_id = pi_sfte_static_id);',
'',
'    if l_template_exists = 0 then',
'      insert into flow_simple_form_templates',
'        (sfte_name, sfte_static_id, sfte_content)',
'      values',
'        (pi_sfte_name, pi_sfte_static_id, pi_sfte_content)',
'      returning',
'        sfte_id into l_sfte_id;',
'    else',
'      raise template_exists;',
'    end if;',
'    return l_sfte_id;',
'',
'  end create_template;',
'  ',
'  ',
'  procedure edit_template(',
'    pi_sfte_id        in flow_simple_form_templates.sfte_id%type',
'  , pi_sfte_name      in flow_simple_form_templates.sfte_name%type',
'  , pi_sfte_static_id in flow_simple_form_templates.sfte_static_id%type',
'  , pi_sfte_content   in flow_simple_form_templates.sfte_content%type)',
'  as',
'  begin',
'    update flow_simple_form_templates',
'       set sfte_name = pi_sfte_name',
'         , sfte_static_id = pi_sfte_static_id',
'         , sfte_content = pi_sfte_content',
'     where sfte_id = pi_sfte_id;',
'',
'  end edit_template;',
'',
'',
'  procedure delete_template(',
'    pi_sfte_id in flow_simple_form_templates.sfte_id%type)',
'  as',
'  begin',
'    delete from flow_simple_form_templates ',
'     where sfte_id = pi_sfte_id;',
'',
'  end delete_template;',
'',
'end flow_simple_form_template;',
'/',
'',
'create or replace package body flow_statistics',
'as',
'/* ',
'-- Flows for APEX - flow_statistics.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2023.',
'--',
'-- Created    11-Jan-2023  Richard Allen (Oracle)',
'--',
'*/',
'',
'',
'',
'',
'------------------',
'---  collect daily step stats',
'-------------------',
'  procedure create_daily_step_summary',
'  ( p_start_date   in   date',
'  )',
'  is',
'  begin',
'      insert into flow_step_stats ',
'          ( stsf_dgrm_id',
'          , stsf_tag_name',
'          , stsf_objt_bpmn_id',
'          , stsf_period_start',
'          , stsf_period',
'          , stsf_duration_10pc_ivl',
'          , stsf_duration_50pc_ivl',
'          , stsf_duration_90pc_ivl',
'          , stsf_duration_max_ivl',
'          , stsf_duration_10pc_sec',
'          , stsf_duration_50pc_sec',
'          , stsf_duration_90pc_sec',
'          , stsf_duration_max_sec',
'          , stsf_waiting_10pc_ivl',
'          , stsf_waiting_50pc_ivl',
'          , stsf_waiting_90pc_ivl',
'          , stsf_waiting_max_ivl',
'          , stsf_waiting_10pc_sec',
'          , stsf_waiting_50pc_sec',
'          , stsf_waiting_90pc_sec',
'          , stsf_waiting_max_sec  ',
'          , stsf_completed',
'          ) ',
'      with ivl_stats as',
'        ( select  lgsf_sbfl_dgrm_id                                                   as dgrm_id',
'                  , objt.objt_tag_name                                                as objt_tag_name',
'                  , lgsf_objt_id                                                      as objt_bpmn_id',
'                  , trunc (sys_extract_utc ( lgsf_completed ))                        as period_start',
'                  , approx_percentile (0.10 )',
'                      within group (order by (lgsf_completed - lgsf_was_current) ASC) as duration_10pc_ivl',
'                  , approx_percentile (0.50 )',
'                      within group (order by lgsf_completed - lgsf_was_current ASC)   as duration_50pc_ivl',
'                  , approx_percentile (0.90 )',
'                      within group (order by lgsf_completed - lgsf_was_current ASC)   as duration_90pc_ivl',
'                  , max ( lgsf_completed - lgsf_was_current)                          as duration_max_ivl',
'                  , approx_percentile (0.10 )',
'                      within group (order by (lgsf_started - lgsf_was_current) ASC)   as waiting_10pc_ivl',
'                  , approx_percentile (0.50 )',
'                      within group (order by lgsf_started - lgsf_was_current ASC)     as waiting_50pc_ivl',
'                  , approx_percentile (0.90 )',
'                      within group (order by lgsf_started - lgsf_was_current ASC)     as waiting_90pc_ivl',
'                  , max ( lgsf_started - lgsf_was_current)                            as waiting_max_ivl',
'                  , count (*)                                                         as completed',
'             from flow_step_event_log lgsf',
'        left join flow_objects objt',
'               on objt.objt_dgrm_id = lgsf.lgsf_sbfl_dgrm_id',
'              and objt.objt_bpmn_id = lgsf.lgsf_objt_id',
'            where objt.objt_tag_name in ( ''bpmn:userTask'', ''bpmn:serviceTask'', ''bpmn:manualTask''',
'                                        , ''bpmn:subProcess'', ''bpmn:callActivity'', ''bpmn:scriptTask'', ''bpmn:task'')',
'         group by lgsf_sbfl_dgrm_id, objt.objt_tag_name, lgsf_objt_id, trunc (sys_extract_utc ( lgsf_completed ))',
'        )',
'      select i.dgrm_id',
'           , i.objt_tag_name',
'           , i.objt_bpmn_id',
'           , i.period_start',
'           , flow_constants_pkg.gc_stats_period_day ',
'           , i.duration_10pc_ivl',
'           , i.duration_50pc_ivl',
'           , i.duration_90pc_ivl',
'           , i.duration_max_ivl',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.duration_10pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.duration_50pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.duration_90pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.duration_max_ivl)',
'           , i.waiting_10pc_ivl',
'           , i.waiting_50pc_ivl',
'           , i.waiting_90pc_ivl',
'           , i.waiting_max_ivl',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.waiting_10pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.waiting_50pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.waiting_90pc_ivl)',
'           , flow_api_pkg.intervaldstosec (p_intervalds  => i.waiting_max_ivl) ',
'           , i.completed ',
'      from ivl_stats i',
'      where i.period_start between p_start_date and trunc(sysdate)-1',
'      ;',
'  end create_daily_step_summary;',
'  ',
'  ',
'  procedure create_monthly_step_summaries',
'  ( p_start_date in date',
'  )',
'  is',
'  begin',
'    -- now create ''MONTH'' summaries for any month that doesn''t yet exist and MTD to current month',
'    merge into flow_step_stats tgt',
'    using (        ',
'    with mon as ',
'    (',
'      select stsf_dgrm_id, ',
'             stsf_tag_name,',
'             stsf_objt_bpmn_id,',
'             trunc(stsf_period_start, ''MM'') period_start, ',
'             sum ( ds.stsf_duration_10pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_10pc_sec,',
'             sum ( ds.stsf_duration_50pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_50pc_sec, ',
'             sum ( ds.stsf_duration_90pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_90pc_sec, ',
'             sum ( ds.stsf_duration_max_sec  * ds.stsf_completed ) / sum (ds.stsf_completed) duration_max_sec,',
'             sum ( ds.stsf_waiting_10pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_10pc_sec,',
'             sum ( ds.stsf_waiting_50pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_50pc_sec, ',
'             sum ( ds.stsf_waiting_90pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_90pc_sec, ',
'             sum ( ds.stsf_waiting_max_sec  * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_max_sec,',
'             sum ( stsf_completed) completed',
'      from   flow_step_stats ds',
'      where  ds.stsf_period = ''DAY''',
'      group by stsf_dgrm_id, stsf_tag_name, stsf_objt_bpmn_id, trunc(stsf_period_start, ''MM'')',
'      order by stsf_dgrm_id, stsf_tag_name, stsf_objt_bpmn_id, trunc(stsf_period_start, ''MM'')',
'    )',
'    select mon.stsf_dgrm_id ',
'         , mon.stsf_tag_name',
'         , mon.stsf_objt_bpmn_id',
'         , mon.period_start as stsf_period_start',
'         , case when mon.period_start = trunc(sys_extract_utc(systimestamp),''MM'') then ''MTD''',
'                else ''MONTH'' end as stsf_period',
'         , numtodsinterval (mon.duration_10pc_sec , ''SECOND'') as duration_10pc_ivl',
'         , numtodsinterval (mon.duration_50pc_sec , ''SECOND'') as duration_50pc_ivl',
'         , numtodsinterval (mon.duration_90pc_sec , ''SECOND'') as duration_90pc_ivl',
'         , numtodsinterval (mon.duration_max_sec  , ''SECOND'') as duration_max_ivl',
'         , mon.duration_10pc_sec',
'         , mon.duration_50pc_sec',
'         , mon.duration_90pc_sec',
'         , mon.duration_max_sec',
'         , numtodsinterval (mon.waiting_10pc_sec , ''SECOND'') as waiting_10pc_ivl',
'         , numtodsinterval (mon.waiting_50pc_sec , ''SECOND'') as waiting_50pc_ivl',
'         , numtodsinterval (mon.waiting_90pc_sec , ''SECOND'') as waiting_90pc_ivl',
'         , numtodsinterval (mon.waiting_max_sec  , ''SECOND'') as waiting_max_ivl',
'         , mon.waiting_10pc_sec',
'         , mon.waiting_50pc_sec',
'         , mon.waiting_90pc_sec',
'         , mon.waiting_max_sec',
'         , mon.completed',
'    from mon',
'    where mon.period_start >= trunc(p_start_date,''MM'')',
'    ) src ',
'    on  ( src.stsf_dgrm_id      = tgt.stsf_dgrm_id',
'      and src.stsf_tag_name     = tgt.stsf_tag_name',
'      and src.stsf_objt_bpmn_id = tgt.stsf_objt_bpmn_id',
'      and src.stsf_period_start = tgt.stsf_period_start',
'      and src.stsf_period       = tgt.stsf_period )',
'    when matched then ',
'    update set tgt.stsf_duration_10pc_ivl  = src.duration_10pc_ivl',
'            ,  tgt.stsf_duration_50pc_ivl  = src.duration_50pc_ivl',
'            ,  tgt.stsf_duration_90pc_ivl  = src.duration_90pc_ivl',
'            ,  tgt.stsf_duration_max_ivl   = src.duration_max_ivl',
'            ,  tgt.stsf_duration_10pc_sec  = src.duration_10pc_sec',
'            ,  tgt.stsf_duration_50pc_sec  = src.duration_50pc_sec',
'            ,  tgt.stsf_duration_90pc_sec  = src.duration_90pc_sec',
'            ,  tgt.stsf_duration_max_sec   = src.duration_max_sec',
'            ,  tgt.stsf_waiting_10pc_ivl   = src.waiting_10pc_ivl',
'            ,  tgt.stsf_waiting_50pc_ivl   = src.waiting_50pc_ivl',
'            ,  tgt.stsf_waiting_90pc_ivl   = src.waiting_90pc_ivl',
'            ,  tgt.stsf_waiting_max_ivl    = src.waiting_max_ivl',
'            ,  tgt.stsf_waiting_10pc_sec   = src.waiting_10pc_sec',
'            ,  tgt.stsf_waiting_50pc_sec   = src.waiting_50pc_sec',
'            ,  tgt.stsf_waiting_90pc_sec   = src.waiting_90pc_sec',
'            ,  tgt.stsf_waiting_max_sec    = src.waiting_max_sec',
'            ,  tgt.stsf_completed          = src.completed',
'    when not matched then ',
'    insert (  tgt.stsf_dgrm_id',
'            , tgt.stsf_tag_name',
'            , tgt.stsf_objt_bpmn_id',
'            , tgt.stsf_period_start',
'            , tgt.stsf_period',
'            , tgt.stsf_duration_10pc_ivl',
'            , tgt.stsf_duration_50pc_ivl',
'            , tgt.stsf_duration_90pc_ivl',
'            , tgt.stsf_duration_max_ivl',
'            , tgt.stsf_duration_10pc_sec',
'            , tgt.stsf_duration_50pc_sec',
'            , tgt.stsf_duration_90pc_sec',
'            , tgt.stsf_duration_max_sec',
'            , tgt.stsf_waiting_10pc_ivl',
'            , tgt.stsf_waiting_50pc_ivl',
'            , tgt.stsf_waiting_90pc_ivl',
'            , tgt.stsf_waiting_max_ivl',
'            , tgt.stsf_waiting_10pc_sec',
'            , tgt.stsf_waiting_50pc_sec',
'            , tgt.stsf_waiting_90pc_sec',
'            , tgt.stsf_waiting_max_sec  ',
'            , tgt.stsf_completed',
'            )',
'    values  ( src.stsf_dgrm_id',
'            , src.stsf_tag_name',
'            , src.stsf_objt_bpmn_id',
'            , src.stsf_period_start',
'            , src.stsf_period',
'            , src.duration_10pc_ivl',
'            , src.duration_50pc_ivl',
'            , src.duration_90pc_ivl',
'            , src.duration_max_ivl',
'            , src.duration_10pc_sec',
'            , src.duration_50pc_sec',
'            , src.duration_90pc_sec',
'            , src.duration_max_sec',
'            , src.waiting_10pc_ivl',
'            , src.waiting_50pc_ivl',
'            , src.waiting_90pc_ivl',
'            , src.waiting_max_ivl',
'            , src.waiting_10pc_sec',
'            , src.waiting_50pc_sec',
'            , src.waiting_90pc_sec',
'            , src.waiting_max_sec  ',
'            , src.completed',
'            );',
'  end create_monthly_step_summaries; ',
'',
'  -- quarter step stats',
'',
'  procedure create_quarterly_step_summaries  ',
'  ( p_start_date   in date',
'  )',
'  is',
'  begin',
'    insert into flow_step_stats ',
'        ( stsf_dgrm_id',
'        , stsf_tag_name',
'        , stsf_objt_bpmn_id',
'        , stsf_period_start',
'        , stsf_period',
'        , stsf_duration_10pc_ivl',
'        , stsf_duration_50pc_ivl',
'        , stsf_duration_90pc_ivl',
'        , stsf_duration_max_ivl',
'        , stsf_duration_10pc_sec',
'        , stsf_duration_50pc_sec',
'        , stsf_duration_90pc_sec',
'        , stsf_duration_max_sec',
'        , stsf_waiting_10pc_ivl',
'        , stsf_waiting_50pc_ivl',
'        , stsf_waiting_90pc_ivl',
'        , stsf_waiting_max_ivl',
'        , stsf_waiting_10pc_sec',
'        , stsf_waiting_50pc_sec',
'        , stsf_waiting_90pc_sec',
'        , stsf_waiting_max_sec  ',
'        , stsf_completed',
'        )',
'    with mon as ',
'    (',
'    select stsf_dgrm_id, ',
'           stsf_tag_name,',
'           stsf_objt_bpmn_id,',
'           trunc(stsf_period_start, ''Q'') period_start, ',
'           sum ( ds.stsf_duration_10pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_10pc_sec,',
'           sum ( ds.stsf_duration_50pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_50pc_sec, ',
'           sum ( ds.stsf_duration_90pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) duration_90pc_sec, ',
'           sum ( ds.stsf_duration_max_sec  * ds.stsf_completed ) / sum (ds.stsf_completed) duration_max_sec,',
'           sum ( ds.stsf_waiting_10pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_10pc_sec,',
'           sum ( ds.stsf_waiting_50pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_50pc_sec, ',
'           sum ( ds.stsf_waiting_90pc_sec * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_90pc_sec, ',
'           sum ( ds.stsf_waiting_max_sec  * ds.stsf_completed ) / sum (ds.stsf_completed) waiting_max_sec,',
'           sum ( stsf_completed) stsf_completed',
'     from  flow_step_stats ds',
'    where  ds.stsf_period = ''MONTH''',
'      and  ds.stsf_period_start >= p_start_date',
'    group by stsf_dgrm_id, stsf_tag_name, stsf_objt_bpmn_id, trunc(stsf_period_start, ''Q'')',
'    order by stsf_dgrm_id, stsf_tag_name, stsf_objt_bpmn_id, trunc(stsf_period_start, ''Q'')',
'    )',
'    select mon.stsf_dgrm_id',
'         , mon.stsf_tag_name',
'         , mon.stsf_objt_bpmn_id',
'         , mon.period_start',
'         , ''QUARTER'' as period',
'         , numtodsinterval (mon.duration_10pc_sec , ''SECOND'') as duration_10pc_ivl',
'         , numtodsinterval (mon.duration_50pc_sec , ''SECOND'') as duration_50pc_ivl',
'         , numtodsinterval (mon.duration_90pc_sec , ''SECOND'') as duration_90pc_ivl',
'         , numtodsinterval (mon.duration_max_sec  , ''SECOND'') as duration_max_ivl',
'         , mon.duration_10pc_sec',
'         , mon.duration_50pc_sec',
'         , mon.duration_90pc_sec',
'         , mon.duration_max_sec',
'         , numtodsinterval (mon.waiting_10pc_sec , ''SECOND'') as waiting_10pc_ivl',
'         , numtodsinterval (mon.waiting_50pc_sec , ''SECOND'') as waiting_50pc_ivl',
'         , numtodsinterval (mon.waiting_90pc_sec , ''SECOND'') as waiting_90pc_ivl',
'         , numtodsinterval (mon.waiting_max_sec  , ''SECOND'') as waiting_max_ivl',
'         , mon.waiting_10pc_sec',
'         , mon.waiting_50pc_sec',
'         , mon.waiting_90pc_sec',
'         , mon.waiting_max_sec',
'         , mon.stsf_completed',
'    from mon',
'    where mon.period_start between p_start_date and add_months ( trunc( sys_extract_utc (systimestamp), ''Q'' ), -3)',
'    ;',
'  end create_quarterly_step_summaries;',
'',
'  ------------------',
'  ---  collect daily process stats',
'  -------------------',
'  procedure create_daily_instance_summary',
'  ( p_start_date   in   date',
'  )',
'  is',
'  begin',
'    insert into flow_instance_stats',
'        ( stpr_dgrm_id    ',
'        , stpr_period_start  ',
'        , stpr_period',
'        , stpr_created    ',
'        , stpr_started    ',
'        , stpr_error      ',
'        , stpr_completed  ',
'        , stpr_terminated ',
'        , stpr_reset      ',
'        , stpr_duration_10pc_ivl',
'        , stpr_duration_50pc_ivl',
'        , stpr_duration_90pc_ivl',
'        , stpr_duration_max_ivl ',
'        , stpr_duration_10pc_sec',
'        , stpr_duration_50pc_sec',
'        , stpr_duration_90pc_sec',
'        , stpr_duration_max_sec ',
'        )',
'    with daily_event_completion_times as',
'        (   select lgpr_dgrm_id dgrm_id',
'                 , trunc (sys_extract_utc (lgpr_timestamp )) period_start',
'                 , lgpr_prcs_event event',
'                 , count (*) times',
'                 , approx_percentile (0.10 )',
'                        within group (order by (lgpr_duration) ASC) duration_10pc_ivl',
'                 , approx_percentile (0.50 )',
'                        within group (order by (lgpr_duration) ASC) duration_50pc_ivl',
'                 , approx_percentile (0.90 )',
'                        within group (order by (lgpr_duration) ASC) duration_90pc_ivl',
'                 , max (lgpr_duration) duration_Max_ivl',
'            from flow_instance_event_log lgpr',
'            where lgpr.lgpr_prcs_event in (''created'',''started'', ''error'', ''completed'', ''terminated'', ''reset'')',
'            group by lgpr_dgrm_id',
'                   , trunc (sys_extract_utc (lgpr_timestamp )) ',
'                   , lgpr_prcs_event',
'            order by lgpr_dgrm_id',
'                   , trunc (sys_extract_utc (lgpr_timestamp )) ',
'                   , lgpr_prcs_event ',
'        ),',
'    prcs_pivot_totals as ',
'        (    select * from ',
'                (select dgrm_id, period_start, event, times ',
'                from daily_event_completion_times',
'                ) tot pivot (sum (times)',
'                for event in ( ''created'' as CREATED, ''started'' as STARTED, ''error'' as ERROR',
'                             , ''completed'' as COMPLETED, ''terminated'' as TERMINATED, ''reset'' as RESET))',
'            order by dgrm_id  ',
'        )',
'    select t.dgrm_id',
'         , t.period_start',
'         , flow_constants_pkg.gc_stats_period_day ',
'         , p.created, p.started, p.error, p.completed, p.terminated, p.reset',
'         , t.duration_10pc_ivl',
'         , t.duration_50pc_ivl',
'         , t.duration_90pc_ivl',
'         , t.duration_Max_ivl',
'         , flow_api_pkg.intervalDStoSec (t.duration_10pc_ivl) duration_10pc_sec',
'         , flow_api_pkg.intervalDStoSec (t.duration_50pc_ivl) duration_50pc_sec',
'         , flow_api_pkg.intervalDStoSec (t.duration_90pc_ivl) duration_90pc_sec',
'         , flow_api_pkg.intervalDStoSec (t.duration_max_ivl ) duration_max_sec',
'     from  prcs_pivot_totals p',
'     join  daily_event_completion_times t',
'       on  t.dgrm_id = p.dgrm_id',
'      and  t.period_start = p.period_start',
'    where  t.event = ''completed''',
'      and  t.period_start between p_start_date and trunc(sysdate)-1',
'    ;',
'  end create_daily_instance_summary;',
'',
'',
'  -- creeate monthly instance summaries',
'  procedure create_monthly_instance_summaries',
'  ( p_start_date in date',
'  )',
'  is',
'  begin',
'    -- now create ''MONTH'' and ''MTD'' summaries for any month that doesn''t yet exist and MTD to current month',
'    merge into flow_instance_stats tgt',
'    using (',
'      with mon as ',
'      (',
'      select stpr_dgrm_id, ',
'             trunc(stpr_period_start, ''MM'') period_start, ',
'             sum (stpr_created) stpr_created,',
'             sum (stpr_started) stpr_started,',
'             sum (stpr_error) stpr_error,',
'             sum (stpr_completed) stpr_completed,',
'             sum (stpr_terminated) stpr_terminated,',
'             sum (stpr_reset) stpr_reset,',
'             sum ( ds.stpr_duration_10pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_10pc_sec,',
'             sum ( ds.stpr_duration_50pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_50pc_sec, ',
'             sum ( ds.stpr_duration_90pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_90pc_sec, ',
'             sum ( ds.stpr_duration_max_sec * ds.stpr_completed  ) / sum (ds.stpr_completed) duration_max_sec',
'      from   flow_instance_stats ds',
'      where  ds.stpr_period = ''DAY''',
'      group by stpr_dgrm_id, trunc(stpr_period_start, ''MM'')',
'      order by stpr_dgrm_id, trunc(stpr_period_start, ''MM'')',
'      )',
'      select mon.stpr_dgrm_id',
'           , mon.period_start as stpr_period_start',
'           , case when mon.period_start = trunc(sys_extract_utc(systimestamp),''MM'') then ''MTD''',
'                  else ''MONTH'' end as stpr_period',
'           , mon.stpr_created',
'           , mon.stpr_started',
'           , mon.stpr_error',
'           , mon.stpr_completed',
'           , mon.stpr_terminated',
'           , mon.stpr_reset',
'           , numtoDSinterval( mon.duration_10pc_sec, ''SECOND'' ) as stpr_duration_10pc_ivl',
'           , numtoDSinterval( mon.duration_50pc_sec, ''SECOND'' ) as stpr_duration_50pc_ivl',
'           , numtoDSinterval( mon.duration_90pc_sec, ''SECOND'' ) as stpr_duration_90pc_ivl',
'           , numtoDSinterval( mon.duration_max_sec , ''SECOND'' ) as stpr_duration_max_ivl',
'           , mon.duration_10pc_sec as stpr_duration_10pc_sec',
'           , mon.duration_50pc_sec as stpr_duration_50pc_sec',
'           , mon.duration_90pc_sec as stpr_duration_90pc_sec',
'           , mon.duration_max_sec  as stpr_duration_max_sec',
'      from mon',
'      where mon.period_start >= trunc(p_start_date,''MM'')',
'      ) src',
'    on (   src.stpr_dgrm_id      = tgt.stpr_dgrm_id    ',
'       and src.stpr_period_start = tgt.stpr_period_start  ',
'       and src.stpr_period       = tgt.stpr_period',
'       )',
'    when matched then ',
'    update set tgt.stpr_created           = src.stpr_created',
'             , tgt.stpr_started           = src.stpr_started',
'             , tgt.stpr_error             = src.stpr_error',
'             , tgt.stpr_completed         = src.stpr_completed',
'             , tgt.stpr_terminated        = src.stpr_terminated',
'             , tgt.stpr_reset             = src.stpr_reset',
'             , tgt.stpr_duration_10pc_ivl = src.stpr_duration_10pc_ivl',
'             , tgt.stpr_duration_50pc_ivl = src.stpr_duration_50pc_ivl',
'             , tgt.stpr_duration_90pc_ivl = src.stpr_duration_90pc_ivl',
'             , tgt.stpr_duration_max_ivl  = src.stpr_duration_max_ivl',
'             , tgt.stpr_duration_10pc_sec = src.stpr_duration_10pc_sec',
'             , tgt.stpr_duration_50pc_sec = src.stpr_duration_50pc_sec',
'             , tgt.stpr_duration_90pc_sec = src.stpr_duration_90pc_sec',
'             , tgt.stpr_duration_max_sec  = src.stpr_duration_max_sec',
'    when not matched then',
'    insert ( tgt.stpr_dgrm_id    ',
'           , tgt.stpr_period_start  ',
'           , tgt.stpr_period',
'           , tgt.stpr_created    ',
'           , tgt.stpr_started    ',
'           , tgt.stpr_error      ',
'           , tgt.stpr_completed  ',
'           , tgt.stpr_terminated ',
'           , tgt.stpr_reset      ',
'           , tgt.stpr_duration_10pc_ivl',
'           , tgt.stpr_duration_50pc_ivl',
'           , tgt.stpr_duration_90pc_ivl',
'           , tgt.stpr_duration_max_ivl ',
'           , tgt.stpr_duration_10pc_sec',
'           , tgt.stpr_duration_50pc_sec',
'           , tgt.stpr_duration_90pc_sec',
'           , tgt.stpr_duration_max_sec ',
'           )',
'    values ( src.stpr_dgrm_id    ',
'           , src.stpr_period_start  ',
'           , src.stpr_period',
'           , src.stpr_created    ',
'           , src.stpr_started    ',
'           , src.stpr_error      ',
'           , src.stpr_completed  ',
'           , src.stpr_terminated ',
'           , src.stpr_reset      ',
'           , src.stpr_duration_10pc_ivl',
'           , src.stpr_duration_50pc_ivl',
'           , src.stpr_duration_90pc_ivl',
'           , src.stpr_duration_max_ivl ',
'           , src.stpr_duration_10pc_sec',
'           , src.stpr_duration_50pc_sec',
'           , src.stpr_duration_90pc_sec',
'           , src.stpr_duration_max_sec ',
'           ) ; ',
'',
'  end create_monthly_instance_summaries;',
'',
'  -- quarter summary',
'',
'  procedure create_quarterly_instance_summaries  ',
'  ( p_start_date   in date',
'  )',
'  is',
'  begin',
'',
'    insert into flow_instance_stats',
'      ( stpr_dgrm_id    ',
'      , stpr_period_start  ',
'      , stpr_period',
'      , stpr_created    ',
'      , stpr_started    ',
'      , stpr_error      ',
'      , stpr_completed  ',
'      , stpr_terminated ',
'      , stpr_reset      ',
'      , stpr_duration_10pc_ivl',
'      , stpr_duration_50pc_ivl',
'      , stpr_duration_90pc_ivl',
'      , stpr_duration_max_ivl ',
'      , stpr_duration_10pc_sec',
'      , stpr_duration_50pc_sec',
'      , stpr_duration_90pc_sec',
'      , stpr_duration_max_sec ',
'      )',
'    with mon as ',
'    (',
'    select stpr_dgrm_id, ',
'         trunc(stpr_period_start, ''Q'') period_start, ',
'         sum (stpr_created) stpr_created,',
'         sum (stpr_started) stpr_started,',
'         sum (stpr_error) stpr_error,',
'         sum (stpr_completed) stpr_completed,',
'         sum (stpr_terminated) stpr_terminated,',
'         sum (stpr_reset) stpr_reset,',
'         sum ( ds.stpr_duration_10pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_10pc_sec,',
'         sum ( ds.stpr_duration_50pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_50pc_sec, ',
'         sum ( ds.stpr_duration_90pc_sec * ds.stpr_completed ) / sum (ds.stpr_completed) duration_90pc_sec, ',
'         sum ( ds.stpr_duration_max_sec * ds.stpr_completed  ) / sum (ds.stpr_completed) duration_max_sec',
'    from   flow_instance_stats ds',
'    where  ds.stpr_period = ''MONTH''',
'      and  ds.stpr_period_start >= p_start_date',
'    group by stpr_dgrm_id, trunc(stpr_period_start, ''Q'')',
'    order by stpr_dgrm_id, trunc(stpr_period_start, ''Q'')',
'    )',
'    select mon.stpr_dgrm_id',
'       , mon.period_start',
'       , ''QUARTER'' as period',
'       , mon.stpr_created',
'       , mon.stpr_started',
'       , mon.stpr_error',
'       , mon.stpr_completed',
'       , mon.stpr_terminated',
'       , mon.stpr_reset',
'       , numtoDSinterval( mon.duration_10pc_sec, ''SECOND'' )',
'       , numtoDSinterval( mon.duration_50pc_sec, ''SECOND'' )',
'       , numtoDSinterval( mon.duration_90pc_sec, ''SECOND'' )',
'       , numtoDSinterval( mon.duration_max_sec , ''SECOND'' )',
'       , mon.duration_10pc_sec',
'       , mon.duration_50pc_sec',
'       , mon.duration_90pc_sec',
'       , mon.duration_max_sec',
'    from mon',
'    where mon.period_start between p_start_date and add_months ( trunc( sys_extract_utc (systimestamp), ''Q'' ), -3)',
'    ;',
'',
'  end create_quarterly_instance_summaries;',
'',
'/*-- instance stats query - showing quarterly, monthly and daily summaries',
'',
'-- used to dri'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
've process performance history charts on engine app p16',
'--  current day statistics are based on live data',
'--  next previous 6 days summaries ',
'--  current month and previous 3-6 months summary data (depending on where month lies in the quarter)',
'--  quarterly summary data before that for upto 4 quarters',
'--  note that label value is in a specific format so that all of the sets sort into the correct calender order',
'',
'with summary_dates as',
'(',
'    select trunc(sysdate) - 7 + level dt, ''DAY'' as period, 8-level sort_order',
'    from dual',
'    connect by level <= ( sysdate - sysdate +7)',
'    union',
'    select add_months( trunc(sysdate,''MM'')',
'                     , - floor (months_between ( trunc ( sysdate)',
'                                               , trunc ( add_months(sysdate,-6) , ''Q'')',
'                                               ) - 3',
'                                ) + level-1',
'                     )',
'                     ,''MONTH''',
'                     , 10*(7-level)',
'    from dual',
'    connect by level <= ( sysdate - sysdate + floor (months_between ( trunc (sysdate)',
'                                                                    , trunc (add_months ( sysdate ,-6) , ''Q'')',
'                                                                    ) - 2',
'                                                    )',
'                        )',
'    union ',
'    select add_months(trunc(sysdate,''Q''), -3 - (3*level)),''QUARTER'', 100*level',
'    from dual',
'    connect by level <= (sysdate -sysdate +4)',
')',
'select sd.dt, ',
'       sd.period, ',
'       case sd.period',
'          when ''DAY''     then to_char(dt,''YYYY-MM-DD'')',
'          when ''MONTH''   then to_char(dt,''YYYY-MM'')',
'          when ''QUARTER'' then to_char(dt,''YYYY-"0"Q'')',
'       end PeriodLabel,',
'       sd.sort_order,',
'       ist.stpr_created,',
'       ist.stpr_started,',
'       ist.stpr_completed,',
'       ist.stpr_error,',
'       ist.stpr_terminated,',
'       ist.stpr_reset,',
'       ist.stpr_duration_10pc_sec,',
'       ist.stpr_duration_50pc_sec,',
'       ist.stpr_duration_90pc_sec,',
'       ist.stpr_duration_max_sec',
'  from summary_dates sd',
'  left join flow_instance_stats ist',
'    on sd.dt     = ist.stpr_period_start',
'   and sd.period = ist.stpr_period',
' where ist.stpr_dgrm_id = :P16_DGRM_ID',
' order by sd.sort_order desc',
'union all',
'   select trunc(sysdate)',
'        , ''DAY''',
'        , to_char (sysday,''YYYY-MM-DD'')',
'        , 0',
'        , sum ( case lgpr_prcs_event when ''created''    then 1 else 0 end) num_created',
'        , sum ( case lgpr_prcs_event when ''started''    then 1 else 0 end) num_started',
'        , sum ( case lgpr_prcs_event when ''completed''  then 1 else 0 end) num_completed',
'        , sum ( case lgpr_prcs_event when ''error    ''  then 1 else 0 end) num_error',
'        , sum ( case lgpr_prcs_event when ''terminated'' then 1 else 0 end) num_terminated',
'        , sum ( case lgpr_prcs_event when ''reset''      then 1 else 0 end) num_reset',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.10 )',
'               within group (order by (lgpr_duration) ASC)) duration_10pc_sec',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.50 )',
'               within group (order by (lgpr_duration) ASC)) duration_50pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.90 )',
'               within group (order by (lgpr_duration) ASC)) duration_90pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( max (lgpr_duration)) duration_max_sec                                  ',
'         from flow_instance_event_log lgpr',
'        where lgpr.lgpr_prcs_event in (''created'',''started'', ''error'', ''completed'', ''terminated'', ''reset'')',
'        and   trunc (sys_extract_utc(lgpr_timestamp)) = trunc(sysdate)',
'        and  lgpr_dgrm_id = :P16_DGRM_ID',
'        group by lgpr_dgrm_id',
'        order by lgpr_dgrm_id',
';',
'',
'-- step stats query - showing quarterly, monthly and daily summaries',
'',
'-- used to drive process performance history charts on engine app p17',
'--  current day statistics are based on live data',
'--  next previous 6 days summaries ',
'--  current month and previous 3-6 months summary data (depending on where month lies in the quarter)',
'--  quarterly summary data before that for upto 4 quarters',
'--  note that label value is in a specific format so that all of the sets sort into the correct calender order',
'',
'with summary_dates as',
'(',
'    select trunc(sysdate) - 7 + level dt, ''DAY'' as period, 8-level sort_order',
'    from dual',
'    connect by level <= ( sysdate - sysdate +7)',
'    union',
'    select add_months( trunc(sysdate,''MM'')',
'                     , - floor (months_between ( trunc ( sysdate)',
'                                               , trunc ( add_months(sysdate,-6) , ''Q'')',
'                                               ) - 3',
'                                ) + level-1',
'                     )',
'                     ,''MONTH''',
'                     , 10*(7-level)',
'    from dual',
'    connect by level <= ( sysdate - sysdate + floor (months_between ( trunc (sysdate)',
'                                                                    , trunc (add_months ( sysdate ,-6) , ''Q'')',
'                                                                    ) - 2',
'                                                    )',
'                        )',
'    union ',
'    select add_months(trunc(sysdate,''Q''), -3 - (3*level)),''QUARTER'', 100*level',
'    from dual',
'    connect by level <= (sysdate -sysdate +4)',
')',
'select sd.dt, ',
'       sd.period, ',
'       case sd.period',
'          when ''DAY''     then to_char(dt,''YYYY-MM-DD'')',
'          when ''MONTH''   then to_char(dt,''YYYY-MM'')',
'          when ''QUARTER'' then to_char(dt,''YYYY-"0"Q'')',
'       end PeriodLabel,',
'       sd.sort_order,',
'       ist.stsf_completed,',
'       ist.stsf_duration_10pc_sec,',
'       ist.stsf_duration_50pc_sec,',
'       ist.stsf_duration_90pc_sec,',
'       ist.stsf_duration_max_sec,',
'       ist.stsf_waiting_10pc_sec,',
'       ist.stsf_waiting_50pc_sec,',
'       ist.stsf_waiting_90pc_sec,',
'       ist.stsf_waiting_max_sec',
'  from summary_dates sd',
'  left join flow_step_stats ist',
'    on sd.dt     = ist.stsf_period_start',
'   and sd.period = ist.stsf_period',
' where ist.stsf_dgrm_id = :P17_DGRM_ID',
'   and ist.stsf_objt_bpmn_id = :P17_OBJT_BPMN_ID',
'union all',
'   select trunc(sysdate)',
'        , ''DAY''',
'        , to_char (sysdate,''YYYY-MM-DD'')',
'        , 0',
'        , count(lgsf_prcs_id) num_completed',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.10 )',
'               within group (order by (lgsf_completed - lgsf_was_current) ASC))   duration_10pc_sec',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.50 )',
'               within group (order by (lgsf_completed - lgsf_was_current) ASC))   duration_50pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.90 )',
'               within group (order by (lgsf_completed - lgsf_was_current) ASC))   duration_90pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( max (lgsf_completed - lgsf_was_current)) duration_max_sec                                  ',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.10 )',
'               within group (order by (lgsf_started - lgsf_was_current) ASC))   waiting_10pc_sec',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.50 )',
'               within group (order by (lgsf_started - lgsf_was_current) ASC))   waiting_50pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( approx_percentile (0.90 )',
'               within group (order by (lgsf_started - lgsf_was_current) ASC))   waiting_90pc_sec             ',
'        , flow_api_pkg.intervaldstosec ( max (lgsf_started - lgsf_was_current)) waiting_max_sec           ',
'        from flow_step_event_log lgsf',
'        where trunc (sys_extract_utc(lgsf_completed)) = trunc(sysdate)',
'        and  lgsf_sbfl_dgrm_id = :P17_DGRM_ID',
'        and  lgsf_objt_id = :P17_OBJT_BPMN_ID',
'        group by lgsf_sbfl_dgrm_id, lgsf_objt_id',
'*/',
'',
'  function get_last_successful_summary',
'  ( p_type        flow_stats_history.sths_type%type',
'  , p_operation   flow_stats_history.sths_operation%type',
'  )',
'  return date',
'  is',
'    l_last_successful_summary  date;',
'  begin',
'    select nvl( trunc( max( sths.sths_date)), to_date(''01-JAN-2020'',''DD-MON-YYYY''))',
'        -- deemed start of Flows for APEX epoch!',
'      into l_last_successful_summary',
'      from flow_stats_history sths',
'     where sths.sths_type      = p_type',
'       and sths.sths_operation = p_operation',
'       and sths.sths_status    = flow_constants_pkg.gc_stats_outcome_success',
'    ;',
'    return l_last_successful_summary;',
'  exception',
'    when no_data_found then',
'      return to_date(''01-JAN-2020'',''DD-MON-YYYY''); -- deemed start of Flows for APEX epoch!',
'  end get_last_successful_summary;',
'',
'',
'',
'  procedure create_daily_summaries',
'  ( p_start_date    in  date',
'  )',
'  is',
'  begin',
'    -- creates daily Summaries for all days between last successful run up to yesterday',
'    -- create daily instance summary',
'    create_daily_instance_summary (p_start_date => p_start_date);',
'    -- create daily step summary',
'    create_daily_step_summary (p_start_date => p_start_date);',
'',
'    -- if successful update Stats history',
'    insert into flow_stats_history',
'    ( sths_date ',
'    , sths_status  ',
'    , sths_type',
'    , sths_operation',
'    , sths_errors',
'    , sths_created_on',
'    )',
'    values ',
'    ( trunc(sys_extract_utc(systimestamp))-1',
'    , flow_constants_pkg.gc_stats_outcome_success',
'    , flow_constants_pkg.gc_stats_period_day',
'    , flow_constants_pkg.gc_stats_operation_generate',
'    , null',
'    , systimestamp',
'    );',
'',
'    commit;',
'',
'  end create_daily_summaries;',
'',
'  procedure create_monthly_summaries',
'  is',
'    l_last_summary_date date;',
'    l_start_date        date;',
'  begin',
'    -- creates monthly Summaries for all months between last successful run up to yesterday',
'    -- get last successful quarterly summmary date',
'    l_last_summary_date := get_last_successful_summary ( p_type      => flow_constants_pkg.gc_stats_period_month',
'                                                       , p_operation => flow_constants_pkg.gc_stats_operation_generate',
'                                                       )  ;',
'    l_start_date := l_last_summary_date + 1;                                                   ',
'',
'    -- create monthly instance summary',
'    create_monthly_instance_summaries (p_start_date => l_start_date);',
'    -- create monthly step summary',
'    create_monthly_step_summaries (p_start_date => l_start_date);   ',
'    ',
'    -- if successful update Stats history',
'    insert into flow_stats_history',
'    ( sths_date ',
'    , sths_status  ',
'    , sths_type',
'    , sths_operation',
'    , sths_errors',
'    , sths_created_on',
'    )',
'    values ',
'    ( trunc(sys_extract_utc(systimestamp))-1',
'    , flow_constants_pkg.gc_stats_outcome_success',
'    , flow_constants_pkg.gc_stats_period_month',
'    , flow_constants_pkg.gc_stats_operation_generate',
'    , null',
'    , systimestamp',
'    );',
'',
'    commit;  ',
'        --',
'  end create_monthly_summaries;',
'',
'  procedure create_quarterly_summaries',
'  is',
'    l_last_summary_date                 date;',
'    l_start_date                        date;',
'    l_final_quarter                     date;  -- final quarter start date included in this new summary',
'',
'  begin',
'    -- get last successful quarterly summmary date',
'    l_last_summary_date := get_last_successful_summary ( p_type      => flow_constants_pkg.gc_stats_period_quarter',
'                                                       , p_operation => flow_constants_pkg.gc_stats_operation_generate',
'                                                       );',
'    l_start_date := add_months (l_last_summary_date, 3);',
'    -- create quarterly instance summary',
'    create_quarterly_instance_summaries (p_start_date => l_start_date);',
'    -- create quarterly step summary',
'    create_quarterly_step_summaries (p_start_date => l_start_date);     ',
'    -- set last quarterly summary in hstory',
'    l_final_quarter := add_months( trunc(sysdate,''Q'') , -3);',
'',
'    insert into flow_stats_history',
'    ( sths_date ',
'    , sths_status',
'    , sths_type',
'    , sths_operation',
'    , sths_errors',
'    , sths_created_on',
'    )',
'    values ',
'    ( l_final_quarter',
'    , flow_constants_pkg.gc_stats_outcome_success',
'    , flow_constants_pkg.gc_stats_period_quarter',
'    , flow_constants_pkg.gc_stats_operation_generate',
'    , null',
'    , systimestamp',
'    );',
'',
'    commit;',
'  end create_quarterly_summaries;       ',
'',
'  procedure run_daily_stats',
'  is',
'    l_last_successful_daily             date;',
'    l_last_successful_quarterly         date;',
'    e_daily_summary_generation_error    exception;',
'    e_monthly_summary_generation_error  exception;',
'  begin',
'    begin',
'      -- get last successfully completed day',
'      l_last_successful_daily := get_last_successful_summary ',
'                                       ( p_type => flow_constants_pkg.gc_stats_period_day',
'                                       , p_operation => flow_constants_pkg.gc_stats_operation_generate);',
'      -- make daily summaries from last successfully completed day to yesterday night',
'      create_daily_summaries (p_start_date => l_last_successful_daily +1 );',
'    exception',
'      when others then',
'        raise e_daily_summary_generation_error;',
'    end;',
'    begin',
'    -- run monthly and MTD summary',
'      create_monthly_summaries;',
'    exception',
'      when others then ',
'        raise e_monthly_summary_generation_error;',
'    end;',
'    -- run quarterlies if required',
'    l_last_successful_quarterly := get_last_successful_summary ',
'                                   ( p_type => flow_constants_pkg.gc_stats_period_quarter',
'                                   , p_operation => flow_constants_pkg.gc_stats_operation_generate);',
'    if trunc(l_last_successful_quarterly,''Q'') != trunc(sysdate,''Q'') then',
'         create_quarterly_summaries ;',
'    end if;',
'  end run_daily_stats;',
'',
'  procedure purge_statistics',
'  is',
'    l_daily_summary_purge_date      date;',
'    l_monthly_summary_purge_date    date;',
'    l_quarterly_summary_purge_date  date;',
'  begin',
'    apex_debug.enter(p_routine_name  => ''purge_statistics'');',
'',
'    l_daily_summary_purge_date      := sysdate - flow_engine_util.get_config_value',
'                                      ( p_config_key => flow_constants_pkg.gc_config_stats_retain_summary_daily ',
'                                      , p_default_value => flow_constants_pkg.gc_config_default_stats_retain_summary_daily   ',
'                                      );',
'    l_monthly_summary_purge_date    := add_months ( sysdate, -1 * flow_engine_util.get_config_value',
'                                                      ( p_config_key => flow_constants_pkg.gc_config_stats_retain_summary_month ',
'                                                      , p_default_value => flow_constants_pkg.gc_config_default_stats_retain_summary_month  ',
'                                                      )',
'                                                  );                                      ',
'    l_quarterly_summary_purge_date  := add_months ( sysdate, -1 * flow_engine_util.get_config_value',
'                                                      ( p_config_key => flow_constants_pkg.gc_config_stats_retain_summary_qtr ',
'                                                      , p_default_value => flow_constants_pkg.gc_config_default_stats_retain_summary_qtr  ',
'                                                      )',
'                                                  );',
'',
'    apex_debug.message',
'    ( p_message => ''Statistics purge starting for daily before %0, monthly before %1 and quarterly before %2''',
'    , p0 => to_char(l_daily_summary_purge_date)',
'    , p1 => to_char(l_monthly_summary_purge_date)',
'    , p2 => to_char(l_quarterly_summary_purge_date)',
'    );',
'    --',
'    begin',
'      -- dailies',
'      delete from flow_instance_stats',
'      where stpr_period = flow_constants_pkg.gc_stats_period_day',
'      and stpr_period_start < l_daily_summary_purge_date;',
'',
'      delete from flow_step_stats',
'      where stsf_period = flow_constants_pkg.gc_stats_period_day',
'      and stsf_period_start < l_daily_summary_purge_date;',
'',
'      -- monthlies',
'      delete from flow_instance_stats',
'      where stpr_period = flow_constants_pkg.gc_stats_period_month',
'      and stpr_period_start < l_monthly_summary_purge_date;',
'',
'      delete from flow_step_stats',
'      where stsf_period = flow_constants_pkg.gc_stats_period_month',
'      and stsf_period_start < l_monthly_summary_purge_date;',
'',
'      -- quarterlies',
'      delete from flow_instance_stats',
'      where stpr_period = flow_constants_pkg.gc_stats_period_quarter',
'      and stpr_period_start < l_quarterly_summary_purge_date;',
'',
'      delete from flow_step_stats',
'      where stsf_period = flow_constants_pkg.gc_stats_period_quarter',
'      and stsf_period_start < l_quarterly_summary_purge_date;',
'      --',
'      insert into flow_stats_history',
'        ( sths_date',
'        , sths_status',
'        , sths_type',
'        , sths_operation',
'        , sths_comments',
'        , sths_created_on',
'        )',
'      values',
'        ( sysdate',
'        , flow_constants_pkg.gc_stats_outcome_success',
'        , flow_constants_pkg.gc_stats_period_day',
'        , flow_constants_pkg.gc_stats_operation_purge',
'        , ''purge completed''',
'        , systimestamp',
'        );        ',
'    end;',
'    exception',
'      when others then',
'        insert into flow_stats_history',
'        ( sths_date',
'        , sths_status',
'        , sths_type',
'        , sths_operation',
'        , sths_comments',
'        , sths_errors',
'        , sths_created_on',
'        )',
'        values',
'        ( sysdate',
'        , flow_constants_pkg.gc_stats_outcome_error',
'        , flow_constants_pkg.gc_stats_period_day',
'        , flow_constants_pkg.gc_stats_operation_purge',
'        , ''error on purge''',
'        , dbms_utility.format_error_stack',
'        , systimestamp',
'        ); ',
'        raise;  ',
'  end purge_statistics;',
'',
'',
'end flow_statistics;',
'/',
'',
'/* ',
'-- Flows for APEX - flow_subprocesses.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2020,2022.',
'--',
'-- Created 22-Feb-2022   Richard Allen - Refactor SubProcess code from flow_engine',
'--',
'*/',
'',
'create or replace package body flow_subprocesses',
'as',
'',
'/* -----------------------------------------------------------------------------',
'--',
'--  process_process_level_endEvent',
'--',
'--  handles endEvents that complete a process level, e.g., subProcesses and callActivities',
'--',
'--------------------------------------------------------------------------------',
'*/',
'',
'  procedure process_process_level_endEvent',
'    ( p_process_id        in flow_processes.prcs_id%type',
'    , p_subflow_id        in flow_subflows.sbfl_id%type',
'    , p_sbfl_info         in flow_subflows%rowtype',
'    , p_step_info         in flow_types_pkg.flow_step_info',
'    , p_sbfl_context_par  in flow_types_pkg.t_subflow_context',
'    )',
'  is',
'    l_boundary_event        flow_objects.objt_bpmn_id%type;',
'    l_subproc_objt          flow_objects.objt_bpmn_id%type;',
'    l_remaining_subflows    number;',
'    l_parent_step_key       flow_subflows.sbfl_step_key%type;',
'    l_end_is_interrupted    boolean;  ',
'    l_par_objt_type         flow_objects.objt_tag_name%type;',
'    l_par_dgrm_id           flow_diagrams.dgrm_id%type;',
'    l_par_objt_id           flow_objects.objt_id%type;',
'  begin',
'    apex_debug.enter',
'      ( ''Process Level End Event''',
'      , ''End Event''       , p_step_info.target_objt_ref',
'      , ''Event Type''      , p_step_info.target_objt_subtag',
'      , ''Parent Event''    , p_sbfl_context_par.sbfl_id',
'      , ''Parent Step Key'' , p_sbfl_context_par.step_key',
'      ); ',
'    if p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_error_event_definition then',
'      -- error exit event - return to errorBoundaryEvent if it exists and if not to normal exit',
'      begin',
'        select boundary_objt.objt_bpmn_id',
'             , subproc_objt.objt_bpmn_id',
'             , par_sbfl.sbfl_step_key',
'          into l_boundary_event',
'             , l_subproc_objt',
'             , l_parent_step_key',
'          from flow_objects boundary_objt',
'          join flow_objects subproc_objt',
'            on subproc_objt.objt_bpmn_id = boundary_objt.objt_attached_to ',
'           and subproc_objt.objt_dgrm_id = boundary_objt.objt_dgrm_id',
'          join flow_subflows par_sbfl',
'            on par_sbfl.sbfl_current = subproc_objt.objt_bpmn_id',
'           and par_sbfl.sbfl_dgrm_id = subproc_objt.objt_dgrm_id',
'         where par_sbfl.sbfl_id = p_sbfl_context_par.sbfl_id',
'           and par_sbfl.sbfl_prcs_id = p_process_id',
'           and boundary_objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_error_event_definition',
'        ;',
'        -- first remove any non-interrupting events that are on the parent event',
'        flow_boundary_events.unset_boundary_events (p_process_id, p_sbfl_context_par.sbfl_id);',
'        -- set current event on parent process to the error Boundary Event',
'        update flow_subflows sbfl',
'        set sbfl.sbfl_current         = l_boundary_event',
'          , sbfl.sbfl_last_completed  = l_subproc_objt  -- is this done in next_step?',
'          , sbfl.sbfl_status          = flow_constants_pkg.gc_sbfl_status_running',
'          , sbfl.sbfl_last_update     = systimestamp',
'          , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                 , sys_context(''userenv'',''os_user'')',
'                                                 , sys_context(''userenv'',''session_user'')',
'                                                 )  ',
'        where sbfl.sbfl_id = p_sbfl_context_par.sbfl_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'          ;',
'        -- execute the on-event expressions for the boundary event',
'        flow_expressions.process_expressions',
'        ( pi_objt_bpmn_id => l_boundary_event  ',
'        , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'        , pi_prcs_id      => p_process_id',
'        , pi_sbfl_id      => p_sbfl_context_par.sbfl_id',
'        , pi_step_key     => p_sbfl_context_par.step_key',
'        , pi_var_scope    => p_sbfl_context_par.scope',
'        , pi_expr_scope   => p_sbfl_context_par.scope        ',
'        );',
'        l_end_is_interrupted := true;',
'',
'      exception',
'        when no_data_found then',
'          -- error exit with no Boundary Event specified -- return to normal exit',
'          l_end_is_interrupted := true;',
'        when too_many_rows then',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id     => p_process_id',
'          , pi_sbfl_id     => p_subflow_id',
'          , pi_message_key => ''boundary-event-too-many''',
'          , p0 => ''error''',
'          );',
'          -- $F4AMESSAGE ''boundary-event-too-many'' || ''More than one %0 boundaryEvent found on sub process.''  ',
'      end;',
'      -- stop processing in process level and all its children levels',
'      flow_engine_util.terminate_level',
'      ( p_process_id => p_process_id',
'      , p_process_level => p_sbfl_info.sbfl_process_level',
'      );',
'      -- normal end processing will be ignored but we neeed to step forward on the parent',
'      flow_engine.flow_complete_step ',
'      ( p_process_id        => p_process_id',
'      , p_subflow_id        => p_sbfl_context_par.sbfl_id',
'      , p_step_key          => p_sbfl_context_par.step_key',
'      , p_log_as_completed  => true ',
'      );',
'    elsif p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_terminate_event_definition then',
'      -- sub process terminate end',
'      -- stop processing in sub process and all children',
'      flow_engine_util.terminate_level',
'      ( p_process_id    => p_process_id',
'      , p_process_level => p_sbfl_info.sbfl_process_level',
'      ); ',
'      l_end_is_interrupted := true;',
'      -- normal end processing will be ignored but we neeed to step forward on the parent',
'      flow_engine.flow_complete_step ',
'      ( p_process_id  => p_process_id',
'      , p_subflow_id  => p_sbfl_context_par.sbfl_id',
'      , p_step_key  => p_sbfl_context_par.step_key',
'      , p_log_as_completed  => false',
'      );',
'    elsif p_step_info.target_objt_subtag = flow_constants_pkg.gc_bpmn_escalation_event_definition then',
'      -- sub process escalation end',
'      -- this can be interrupting or non-interupting',
'      flow_boundary_events.process_escalation',
'      ( pi_sbfl_info        => p_sbfl_info',
'      , pi_step_info        => p_step_info',
'      , pi_par_sbfl         => p_sbfl_context_par.sbfl_id',
'      , pi_source_type      => flow_constants_pkg.gc_bpmn_end_event',
'      , po_step_key         => l_parent_step_key',
'      , po_is_interrupting  => l_end_is_interrupted',
'      );',
'    else ',
'      -- sub process - null or other (inc message) end event',
'      flow_engine_util.subflow_complete',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      );',
'      l_end_is_interrupted := false;',
'    end if;',
'',
'    if not l_end_is_interrupted then',
'      -- normal process level processing.  ',
'      -- check if there are ANY remaining subflows in the process level.  ',
'      -- If none, close process level',
'      select count(*)',
'        into l_remaining_subflows',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_prcs_id = p_process_id',
'         and sbfl.sbfl_process_level = p_sbfl_info.sbfl_process_level;',
'',
'      if l_remaining_subflows = 0 then ',
'        -- No remaining subflows so process level has completed ',
'        select objt.objt_tag_name',
'             , par_sbfl.sbfl_dgrm_id',
'             , objt.objt_id',
'          into l_par_objt_type',
'             , l_par_dgrm_id',
'             , l_par_objt_id',
'          from flow_objects objt',
'          join flow_subflows par_sbfl',
'            on par_sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'           and par_sbfl.sbfl_current = objt.objt_bpmn_id',
'         where par_sbfl.sbfl_id = p_sbfl_context_par.sbfl_id',
'        ;',
'        if l_par_objt_type = flow_constants_pkg.gc_bpmn_call_activity then',
'          -- map outVariables expressions for call return (variables in calling scope, expressions in called scope)',
'          -- note: outVariable processing only occurs if the callActivit has a non-interrupted return',
'          flow_expressions.process_expressions',
'          ( pi_objt_id      => l_par_objt_id',
'          , pi_set          => flow_constants_pkg.gc_expr_set_out_variables',
'          , pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => p_sbfl_context_par.sbfl_id  ',
'          , pi_step_key     => p_sbfl_context_par.step_key ',
'          , pi_var_scope    => p_sbfl_context_par.scope',
'          , pi_expr_scope   => p_sbfl_info.sbfl_scope',
'          );      ',
'          -- log the diagram as being completed',
'          flow_logging.log_instance_event',
'          ( p_process_id    => p_process_id',
'          , p_objt_bpmn_id  => p_step_info.target_objt_ref',
'          , p_event         => flow_constants_pkg.gc_prcs_event_leave_call',
'          , p_event_level   => flow_constants_pkg.gc_logging_level_routine',
'          , p_comment       => ''Leaving called diagram ''||',
'                               flow_diagram.get_diagram_name (pi_dgrm_id => p_sbfl_info.sbfl_dgrm_id) ||''.''',
'          );  ',
'        end if;',
'        -- return to parent level and do next step',
'        apex_debug.info (''Process Level Completed: Process level %0'', p_sbfl_info.sbfl_process_level );',
'        flow_engine.flow_complete_step ',
'        ( p_process_id => p_process_id',
'        , p_subflow_id => p_sbfl_context_par.sbfl_id',
'        , p_step_key   => p_sbfl_context_par.step_key',
'        );  ',
'      end if;',
'    end if;',
'  end process_process_level_endEvent;',
'',
'  procedure process_subProcess',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type',
'    , p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is',
'    l_target_objt_sub        flow_objects.objt_bpmn_id%type; --target object in subprocess',
'    l_sbfl_context_sub       flow_types_pkg.t_subflow_context;   ',
'  begin',
'    apex_debug.enter ',
'    ( ''process_subprocess''',
'    , ''object'', p_step_info.target_objt_tag ',
'    );',
'    begin',
'       select objt.objt_bpmn_id',
'         into l_target_objt_sub',
'         from flow_objects objt',
'        where objt.objt_objt_id  = p_step_info.target_objt_id',
'          and objt.objt_tag_name = flow_constants_pkg.gc_bpmn_start_event  ',
'          and objt.objt_dgrm_id  = p_step_info.dgrm_id',
'       ;',
'    exception',
'      when no_data_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''subProcess-no-start''',
'        );',
'      -- $F4AMESSAGE ''subProcess-no-start'' || ''Unable to find Sub-Process Start Event.''  ',
'      when too_many_rows then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''subProcess-too-many-starts''',
'        );',
'        -- $F4AMESSAGE ''subProcess-too-many-starts'' || ''More than one Sub-Process Start found.''  ',
'    end;',
'    -- start subflow for the sub-process',
'    l_sbfl_context_sub := ',
'      flow_engine_util.subflow_start',
'      ( p_process_id => p_process_id',
'      , p_parent_subflow => p_subflow_id',
'      , p_starting_object => p_step_info.target_objt_ref -- parent subProc activity',
'      , p_current_object => l_target_objt_sub -- subProc startEvent',
'      , p_route => ''sub main''',
'      , p_last_completed => p_sbfl_info.sbfl_last_completed -- previous activity on parent proc',
'      , p_parent_sbfl_proc_level => null',
'      , p_new_proc_level => true',
'      , p_dgrm_id => p_sbfl_info.sbfl_dgrm_id',
'      );',
'',
'    -- Always do all updates to parent data first before performing any next step in the children.',
'    -- Reason: A subflow could immed'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'iately disappear if we''re stepping through it completely.',
'    -- check for any errors on the step',
'    if not flow_globals.get_step_error then ',
'      -- set boundaryEvent events, if any',
'      flow_boundary_events.set_boundary_events ',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_sbfl_info  => p_sbfl_info',
'      );  ',
'      if not flow_globals.get_step_error then ',
'        -- Check again, then Update parent subflow',
'        update flow_subflows sbfl',
'        set   sbfl.sbfl_current         = p_step_info.target_objt_ref -- parent subProc Activity',
'            , sbfl.sbfl_last_completed  = p_sbfl_info.sbfl_last_completed',
'            , sbfl.sbfl_status          = flow_constants_pkg.gc_sbfl_status_in_subprocess',
'            , sbfl.sbfl_last_update     = systimestamp',
'            , sbfl.sbfl_last_update_by  = coalesce ( sys_context(''apex$session'',''app_user'') ',
'                                                   , sys_context(''userenv'',''os_user'')',
'                                                   , sys_context(''userenv'',''session_user'')',
'                                                   )  ',
'        where sbfl.sbfl_id = p_subflow_id',
'          and sbfl.sbfl_prcs_id = p_process_id',
'        ;  ',
'',
'        --  commit parent here',
'        commit;',
'',
'        apex_debug.info (p_message => ''SubProcess Parent Transaction commited'');',
'',
'        -- reset step_had_error flag',
'        flow_globals.set_step_error ( p_has_error => false);',
'',
'        -- relock child subflow(in case earlier loop terminated everything in level)',
'        if flow_engine_util.lock_subflow',
'          ( p_subflow_id => l_sbfl_context_sub.sbfl_id',
'          )',
'        then',
'          -- run on-event expressions for child startEvent',
'          flow_expressions.process_expressions',
'          ( pi_objt_bpmn_id => l_target_objt_sub  ',
'          , pi_set          => flow_constants_pkg.gc_expr_set_on_event',
'          , pi_prcs_id      => p_process_id',
'          , pi_sbfl_id      => l_sbfl_context_sub.sbfl_id',
'          , pi_step_key     => l_sbfl_context_sub.step_key',
'          , pi_var_scope    => l_sbfl_context_sub.scope',
'          , pi_expr_scope   => l_sbfl_context_sub.scope',
'          );',
'',
'          if not flow_globals.get_step_error then ',
'',
'            -- check again for any errors from expressions before stepping forward in the sub_process',
'            flow_engine.flow_complete_step   ',
'            ( p_process_id    => p_process_id',
'            , p_subflow_id    => l_sbfl_context_sub.sbfl_id',
'            , p_step_key      => l_sbfl_context_sub.step_key',
'            , p_forward_route => null',
'            );',
'          end if;',
'        end if;',
'        -- reset step_had_error flag',
'        flow_globals.set_step_error ( p_has_error => false);',
'      end if;',
'    end if;',
'  end process_subProcess; ',
'',
'end flow_subprocesses;',
'/',
'',
'',
'',
'',
'',
'create or replace package body flow_tasks as ',
'/* ',
'-- Flows for APEX - flow_tasks.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2021-2022.',
'-- (c) Copyright Flowquest Limited and / or its affiliates, 2021-2025.',
'--',
'-- Created 13-May-2021  Richard Allen (Flowquest Consuting, for MT AG) ',
'-- Edited  13-Apr-2022  Richard Allen (Oracle)',
'-- Edited  23-May-2022  Moritz Klein (MT AG)',
'-- Edited  02-Apr-2025  Richard Allen (Flowquest)',
'--',
'*/',
'  function get_task_type',
'  (',
'    pi_objt_id in flow_objects.objt_id%type',
'  )',
'    return flow_types_pkg.t_bpmn_attribute_vc2',
'  as',
'    l_return flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'',
'    select objt.objt_attributes."taskType"',
'      into l_return',
'      from flow_objects objt',
'     where objt_id = pi_objt_id',
'    ;',
'    if l_return is null then',
'      apex_debug.warn',
'      (',
'        p_message => ''No task type found for object %0''',
'      , p0        =>  pi_objt_id',
'      );',
'    else',
'      apex_debug.message',
'      (',
'        p_message => ''Task type %0''',
'      , p0        =>  l_return',
'      );    ',
'    end if;',
'',
'    return l_return;',
'  end get_task_type;',
'',
'  procedure process_task',
'    ( p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is',
'  begin',
'    apex_debug.enter ',
'    ( ''process_task''',
'    , ''object: '', p_step_info.target_objt_tag ',
'    );',
'    -- set boundaryEvent Events, if any',
'    flow_boundary_events.set_boundary_events',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_sbfl_info  => p_sbfl_info',
'    );  ',
'  end process_task;',
'',
'  procedure process_userTask',
'    ( p_sbfl_info     in flow_subflows%rowtype',
'    , p_step_info     in flow_types_pkg.flow_step_info',
'    )',
'  is ',
'    l_usertask_type         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_subject_template      flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority_json         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority              flow_subflows.sbfl_priority%type;',
'    l_due_on_json         flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_due_on              flow_subflows.sbfl_due_on%type;',
'  begin',
'  -- current implementation is limited to 3 userTask types, which are:',
'  --   - to run a user defined APEX page via the Task Inbox View',
'  --   - to call an APEX Approval Task ',
'  --   - to run a user defined APEX page via the Task Inbox View, but with a simple form (from Flows v24.1 onwards)',
'  -- future userTask types could include parameterised, standarised template pages , template scripts ??',
'    apex_debug.enter ',
'    ( ''process_userTask''',
'    , ''p_step_info.target_objt_tag''   , p_step_info.target_objt_tag ',
'    , ''p_step_info.target_objt_subtag'', p_step_info.target_objt_subtag ',
'    );',
'    -- set boundaryEvent Events, if any',
'    flow_boundary_events.set_boundary_events ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_sbfl_info  => p_sbfl_info',
'    );  ',
'    -- get the userTask subtype and optional subject template',
'    select objt.objt_attributes."taskType"',
'         , objt.objt_attributes."apex"."subject"',
'      into l_usertask_type',
'         , l_subject_template',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_step_info.target_objt_ref',
'       and objt.objt_dgrm_id = p_sbfl_info.sbfl_dgrm_id',
'       ;',
'',
'    if l_subject_template is not null then',
'      flow_proc_vars_int.do_substitution',
'      ( pi_prcs_id  => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id  => p_sbfl_info.sbfl_id',
'      , pi_scope    => p_sbfl_info.sbfl_scope',
'      , pi_step_key => p_sbfl_info.sbfl_step_key',
'      , pio_string  => l_subject_template',
'      );',
'    end if;',
'',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_subject        = substr(l_subject_template,1, 1000)',
'         , sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_last_update_by = coalesce',
'                                       ( sys_context(''apex$session'',''app_user'')',
'                                       , sys_context(''userenv'',''os_user'')',
'                                       , sys_context(''userenv'',''session_user'')',
'                                       )',
'     where sbfl.sbfl_id      = p_sbfl_info.sbfl_id',
'       and sbfl.sbfl_prcs_id = p_sbfl_info.sbfl_prcs_id;',
'',
'    case l_usertask_type',
'      when flow_constants_pkg.gc_apex_usertask_apex_approval then',
'       flow_usertask_pkg.process_apex_approval_task',
'       ( p_sbfl_info => p_sbfl_info',
'       , p_step_info => p_step_info',
'       );',
'      when flow_constants_pkg.gc_apex_usertask_apex_page then',
'       flow_usertask_pkg.process_apex_page_task',
'       ( p_sbfl_info => p_sbfl_info',
'       , p_step_info => p_step_info',
'       );',
'      when flow_constants_pkg.gc_apex_usertask_apex_simple_form then',
'       flow_usertask_pkg.process_apex_page_task',
'       ( p_sbfl_info => p_sbfl_info',
'       , p_step_info => p_step_info',
'       );',
'      else',
'        null;',
'    end case;',
'',
'  end process_userTask;',
'',
'  procedure process_scriptTask',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_usertask_type    flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_scriptTask''',
'    , ''p_step_info.target_objt_tag'', p_step_info.target_objt_tag ',
'    );',
'    -- current implementation is limited to one scriptTask type, which is to run a user defined PL/SQL script',
'    -- future scriptTask types could include standarised template scripts ??',
'    -- current implementation is limited to synchronous script execution (i.e., script is run as part of Flows for APEX process)',
'    -- future implementations could include async scriptTasks, where script execution is queued.',
'  ',
'    -- set work started time',
'    flow_engine.start_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    , p_called_internally => true',
'    );',
'    ',
'    flow_plsql_runner_pkg.run_task_script(',
'      pi_sbfl_rec => p_sbfl_info',
'    , pi_objt_id  => p_step_info.target_objt_id',
'    );',
'',
'    flow_engine.flow_complete_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    );',
'',
'  exception',
'    when flow_plsql_runner_pkg.e_plsql_script_failed then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script failed in plsql script runner''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- $F4AMESSAGE ''plsql_script_failed'' || ''Process %0: ScriptTask %1 failed due to PL/SQL error - see event log.''',
'    when flow_globals.request_stop_engine then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script requested stop_engine in plsql script runner''',
'      ); ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_requested_stop''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );  ',
'      -- $F4AMESSAGE ''plsql_script_requested_stop'' || ''Process %0: ScriptTask %1 requested processing stop - see event log.''',
'    when flow_globals.throw_bpmn_error_event then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script throws BPMN error event in plsql script runner''',
'      );',
'      flow_boundary_events.handle_task_error_boundary_event ( pi_sbfl_info => p_sbfl_info);',
'    when others then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after process script task failed (outside of plsql script runner)''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- $F4AMESSAGE ''plsql_script_failed'' || ''Process %0: ScriptTask %1 failed due to PL/SQL error - see event log.''',
'',
'  end process_scriptTask;',
'',
'  procedure process_serviceTask ',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_custom_service_task flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_serviceTask''',
'    , ''p_step_info.target_objt_tag'', p_step_info.target_objt_tag ',
'    );',
'  ',
'    -- future serviceTask types could include text message, tweet, AOP document via email, AI, etc.',
'    -- current implementation is limited to synchronous email send (i.e., email sent as part of Flows for APEX process) + AI Generation',
'    -- future implementations could include async serviceTask, where message generation is queued, or non-email services',
'',
'    flow_engine.start_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    , p_called_internally => true',
'    );',
'',
'    case get_task_type( pi_objt_id => p_step_info.target_objt_id )  ',
'      when flow_constants_pkg.gc_apex_task_execute_plsql then',
'            flow_plsql_runner_pkg.run_task_script',
'            ( pi_sbfl_rec => p_sbfl_info',
'            , pi_objt_id  => p_step_info.target_objt_id',
'            );',
'      when flow_constants_pkg.gc_apex_servicetask_send_mail then ',
'           flow_services.send_email',
'           ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'           , pi_sbfl_id => p_sbfl_info.sbfl_id',
'           , pi_objt_id => p_step_info.target_objt_id',
'           );',
'      when flow_constants_pkg.gc_apex_servicetask_ai_generation then',
'           flow_services.apex_AI_generation ',
'           ( p_sbfl_info     => p_sbfl_info',
'           , p_step_info     => p_step_info',
'           );',
'      else',
'        null;',
'    end case;',
'',
'    flow_engine.flow_complete_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id ',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    );',
'',
'  exception',
'    when flow_services.e_wrong_default_workspace then',
'      rollback;',
'      apex_debug.info( p_message => ''Rollback initiated after default workspace not valid''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''wrong-default-workspace''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''wrong-default-workspace'' || ''Process %0: ServiceTask %1 failed: the default workspace defined in the configuration parameter is not valid.''',
'    when flow_services.e_workspace_not_found then',
'      rollback;',
'      apex_debug.info( p_message => ''Rollback initiated after workspace not found''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''workspace-not-found''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''workspace-not-found'' || ''Process %0: ServiceTask %1 failed: unable to find the workspace associated with the application id defined in the diagram. Please check the model.''',
'    when flow_services.e_email_no_from then ',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after from attribute not found''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-no-from''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''email-no-from'' || ''Process %0: ServiceTask %1 failed: attribute "From" and default email sender are not defined. Please check the model and or the configuration parameter.''',
'    when flow_services.e_email_no_to then ',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after to attribute not found''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-no-to''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''email-no-to'' || ''Process %0: ServiceTask %1 failed: attribute "To" not defined. Please check the model.''',
'',
'    when flow_services.e_email_no_template then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after template or app_alias attributes not found''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-no-template''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      ); ',
'      -- F4A$MESSAGE ''email-no-template'' || ''Process %0: ServiceTask %1 failed: attribute "Template" not defined. Please check the model.''',
'    when flow_services.e_email_no_body then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after body attribute not found''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-no-body''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''email-no-body'' || ''Process %0: ServiceTask %1 failed: attribute "Body" not defined. Please check the model.''',
'    when flow_services.e_json_not_valid then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after placeholder JSON object not valid''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-placeholder-json-invalid''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''email-placeholder-json-invalid'' || ''Process %0: ServiceTask %1 failed: placeholder JSON object is not valid. Please check the model.''',
'    when flow_services.e_email_failed then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after send_email failed in service task''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''email-failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- F4A$MESSAGE ''email-failed'' || ''Process %0: ServiceTask %1 failed see error log and check the model.''',
'    when flow_plsql_runner_pkg.e_plsql_script_failed then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script failed in plsql script runner''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- $F4AMESSAGE ''plsql_script_failed'' || ''Process %0: PLSQL Script %1 failed due to PL/SQL error - see event log.''',
'    when flow_globals.request_stop_engine then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script requested stop_engine in plsql script runner''',
'      ); ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_requested_stop''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );  ',
'      -- $F4AMESSAGE ''plsql_script_requested_stop'' || ''Process %0: PL/SQL Script %1 requested processing stop - see event log.''',
'    when flow_globals.throw_bpmn_error_event then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script throws BPMN error event in plsql script runner''',
'      );',
'      flow_boundary_events.handle_task_error_boundary_event ( pi_sbfl_info => p_sbfl_info);',
'',
'  end process_serviceTask;',
'',
'  procedure process_manualTask',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'  begin',
'    apex_debug.enter ',
'    (''process_manualTask''',
'    , ''p_step_info.target_objt_tag'', p_step_info.target_objt_tag ',
'    );',
'',
'    -- current implementation of manualTask performs exactly like a standard Task, without attached boundary timers',
'    -- future implementation could include auto-call of an APEX page telling you what the manual task is and providing information about it?',
'',
'    -- set boundaryEvent Events, if any',
'    flow_boundary_events.set_boundary_events ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_sbfl_info  => p_sbfl_info',
'    );  ',
'  end process_manualTask;',
'',
'  procedure process_businessRuleTask',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'  begin',
'    apex_debug.enter ',
'    ( ''process_businessRuleTask''',
'    , ''p_step_info.target_objt_tag'', p_step_info.target_objt_tag ',
'    );',
'    -- current implementation is limited to one businessRuleTask type, ',
'    -- which is to run a user defined PL/SQL script',
'    -- future scriptTask types could include DMN or REST calls to other DecisionRule Engines',
'    -- current implementation is limited to synchronous script execution (i.e., script is run as part of Flows for APEX process)',
'    -- future implementations could include async scriptTasks, where script execution is queued.',
'  ',
'    -- set work started time',
'    flow_engine.start_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    , p_called_internally => true',
'    );',
'    ',
'    case get_task_type( p_step_info.target_objt_id )',
'      when flow_constants_pkg.gc_apex_task_execute_plsql then',
'        flow_plsql_runner_pkg.run_task_script',
'        ( pi_sbfl_rec => p_sbfl_info',
'        , pi_objt_id => p_step_info.target_objt_id',
'        );',
'      else',
'        null;',
'    end case;',
'    ',
'    flow_engine.flow_complete_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    );',
'',
'  exception',
'    when flow_plsql_runner_pkg.e_plsql_script_failed then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script failed in plsql script runner''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- $F4AMESSAGE ''plsql_script_failed'' || ''Process %0: PL/SQL Script %1 failed due to PL/SQL error - see event log.''',
'    when flow_globals.request_stop_engine then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script requested stop_engine in plsql script runner''',
'      ); ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_requested_stop''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );  ',
'      -- $F4AMESSAGE ''plsql_script_requested_stop'' || ''Process %0: PL/SQL Script %1 requested processing stop - see event log.''',
'    when flow_globals.throw_bpmn_error_event then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script throws BPMN error event in plsql script runner''',
'      );',
'      flow_boundary_events.handle_task_error_boundary_event ( pi_sbfl_info => p_sbfl_info);',
'  end process_businessRuleTask;',
'',
'  procedure process_sendTask',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'  begin',
'    apex_debug.enter ',
'    ( ''process_sendTask''',
'    , ''p_step_info.target_objt_ref'', p_step_info.target_objt_ref',
'    , ''p_step_info.target_objt_id'', p_step_info.target_objt_id',
'    , ''taret object task type'', get_task_type( pi_objt_id => p_step_info.target_objt_id )',
'    );',
'    -- current implementation is limited to one sendTask type, ',
'    -- which is to run a user defined PL/SQL script',
'    -- future scriptTask types could include pre-built REST calls',
'    -- current implementation is limited to synchronous script execution (i.e., script is run as part of Flows for APEX process)',
'  ',
'    -- set work started time',
'    flow_engine.start_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    , p_called_internally => true',
'    );',
'    ',
'    case get_task_type( pi_objt_id => p_step_info.target_objt_id )',
'    when flow_constants_pkg.gc_simple_message then',
'        -- Flows for APEX Basic MessageFlow',
'        flow_message_flow.send_message',
'        ( p_sbfl_info => p_sbfl_info',
'        , p_step_info => p_step_info',
'        );',
'    when flow_constants_pkg.gc_apex_task_execute_plsql then',
'        flow_plsql_runner_pkg.run_task_script',
'        ( pi_sbfl_rec => p_sbfl_info',
'        , pi_objt_id => p_step_info.target_objt_id',
'        );',
'    end case;',
'    ',
'    flow_engine.flow_complete_step ',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_step_key   => p_sbfl_info.sbfl_step_key',
'    );',
'',
'  exception',
'    when flow_plsql_runner_pkg.e_plsql_script_failed then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script failed in plsql script runner''',
'      );',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_failed''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );',
'      -- $F4AMESSAGE ''plsql_script_failed'' || ''Process %0: PL/SQL Script %1 failed due to PL/SQL error - see event log.''',
'    when flow_globals.request_stop_engine then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script requested stop_engine in plsql script runner''',
'      ); ',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => p_sbfl_info.sbfl_prcs_id',
'      , pi_sbfl_id        => p_sbfl_info.sbfl_id',
'      , pi_message_key    => ''plsql_script_requested_stop''',
'      , p0 => p_sbfl_info.sbfl_prcs_id',
'      , p1 => p_step_info.target_objt_ref',
'      );  ',
'      -- $F4AMESSAGE ''plsql_script_requested_stop'' || ''Process %0: PL/SQL Script %1 requested processing stop - see event log.''',
'    when flow_globals.throw_bpmn_error_event then',
'      rollback;',
'      apex_debug.info ',
'      ( p_message => ''Rollback initiated after script throws BPMN error event in plsql script runner''',
'      );',
'      flow_boundary_events.handle_task_error_boundary_event ( pi_sbfl_info => p_sbfl_info);',
'  end process_sendTask;  ',
'',
'  procedure process_receiveTask',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_message_name_json flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_message_name      flow_message_subscriptions.msub_message_name%type;',
'    l_key_json          flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_key               flow_message_subscriptions.msub_key_name%type;',
'    l_value_json        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_value             flow_message_subscriptions.msub_key_value%type;',
'    l_payload_variable  flow_process_variables.prov_var_name%type;',
'    l_msub_id           flow_message_subscriptions.msub_id%type;',
'    l_msg_sub           flow_message_flow.t_subscription_details;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_receiveTask''',
'    , ''p_step_info.target_objt_tag'', p_step_info.target_objt_tag ',
'    );',
'',
'    -- set boundaryEvent Events, if any',
'    flow_boundary_events.set_boundary_events',
'    ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'    , p_subflow_id => p_sbfl_info.sbfl_id',
'    , p_sbfl_info  => p_sbfl_info',
'    );  ',
'        ',
'    case get_task_type( p_step_info.target_objt_id )',
'      when flow_constants_pkg.gc_simple_message then',
' ',
'        l_msg_sub            := flow_message_util.get_msg_subscription_details',
'                                ( p_msg_object_bpmn_id      => p_step_info.target_objt_ref',
'                                , p_dgrm_id                 => p_sbfl_info.sbfl_dgrm_id',
'                                , p_sbfl_info               => p_sbfl_info',
'                                );',
'        l_msg_sub.callback  := flow_constants_pkg.gc_bpmn_receivetask;',
'',
'        if not flow_globals.get_step_error then',
'',
'          -- create subscription for the awaited message ',
'          l_msub_id := flow_message_flow.subscribe ( p_subscription_details => l_msg_sub);',
'    ',
'          -- update subflow into ''waiting for message'' status',
'          update flow_subflows sbfl',
'            set sbfl.sbfl_last_update    = systimestamp',
'              , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_waiting_message',
'              , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                      , sys_context(''userenv'',''os_user'')',
'                                                      , sys_context(''userenv'',''session_user'')',
'                                                      )  ',
'          where sbfl.sbfl_id       = p_sbfl_info.sbfl_id',
'            and sbfl.sbfl_prcs_id  = p_sbfl_info.sbfl_prcs_id',
'            ;',
'          -- log subscription event',
'          apex_debug.message ',
'          ( p_message => ''-- ReceiveTask subscription created - message subscription id: %0''',
'          , p0 => l_msub_id',
'          );',
'        end if;',
'',
'      when  flow_constants_pkg.gc_apex_task_execute_plsql then',
'        -- se'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
't work started time',
'        flow_engine.start_step ',
'        ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => p_sbfl_info.sbfl_id',
'        , p_step_key   => p_sbfl_info.sbfl_step_key',
'        , p_called_internally => true',
'        );',
'',
'        flow_plsql_runner_pkg.run_task_script',
'        ( pi_sbfl_rec => p_sbfl_info',
'        , pi_objt_id  => p_step_info.target_objt_id',
'        );',
'',
'        flow_engine.flow_complete_step   --- remove the complete step?',
'        ( p_process_id => p_sbfl_info.sbfl_prcs_id',
'        , p_subflow_id => p_sbfl_info.sbfl_id',
'        , p_step_key   => p_sbfl_info.sbfl_step_key',
'        );',
'',
'    end case;',
'',
'  end process_receiveTask;  ',
'',
'  procedure receiveTask_callback',
'  ( p_process_id    flow_processes.prcs_id%type',
'  , p_subflow_id    flow_subflows.sbfl_id%type',
'  , p_step_key      flow_subflows.sbfl_step_key%type',
'  , p_msub_id       flow_message_subscriptions.msub_id%type',
'  )',
'  is',
'    l_msub_id             flow_message_subscriptions.msub_id%type;',
'    l_required_step_key   flow_subflows.sbfl_step_key%type;',
'    l_current             flow_objects.objt_bpmn_id%type;',
'    l_scope               flow_process_variables.prov_scope%type;',
'    l_dgrm_id             flow_diagrams.dgrm_id%type;',
'    l_follows_ebg         flow_subflows.sbfl_is_following_ebg%type; ',
'    l_parent_sbfl         flow_subflows.sbfl_sbfl_id%type;',
'    e_incorrect_step_key  exception;',
'  begin',
'    apex_debug.enter ',
'    ( ''receiveTask_callback''',
'    , ''p_process_id'', p_process_id',
'    , ''p_subflow_id'', p_subflow_id',
'    , ''p_step_key'', p_step_key',
'    );',
'',
'    -- get subflow info, step info, validate step key',
'    flow_engine.start_step ',
'    ( p_process_id => p_process_id',
'    , p_subflow_id => p_subflow_id',
'    , p_step_key   => p_step_key',
'    , p_called_internally => true',
'    );',
'',
'    begin',
'      select sbfl.sbfl_step_key',
'           , sbfl.sbfl_current',
'           , sbfl.sbfl_dgrm_id',
'           , sbfl.sbfl_is_following_ebg',
'           , sbfl.sbfl_sbfl_id',
'        into l_required_step_key',
'           , l_current',
'           , l_dgrm_id',
'           , l_follows_ebg',
'           , l_parent_sbfl',
'        from flow_objects objt',
'        join flow_subflows sbfl',
'          on sbfl.sbfl_dgrm_id = objt.objt_dgrm_id',
'         and sbfl.sbfl_current = objt.objt_bpmn_id',
'       where sbfl.sbfl_id = p_subflow_id',
'         and sbfl_prcs_id = p_process_id',
'         ;',
'      if l_required_step_key != p_step_key then',
'        raise e_incorrect_step_key;',
'      end if;',
'    exception',
'      when no_data_found then',
'        null; -- tbi',
'      when e_incorrect_step_key then',
'        null; -- tbi',
'      when others then',
'        null; -- tbi',
'    end; ',
'',
'    -- handle a receivetask following an Event Based Gateway',
'',
'    case  l_follows_ebg ',
'    when  ''Y'' then',
'        -- we have an eventBasedGateway - handle cleaning up the other forward paths',
'        flow_engine.handle_event_gateway_event ',
'        (',
'          p_process_id => p_process_id',
'        , p_parent_subflow_id => l_parent_sbfl',
'        , p_cleared_subflow_id => p_subflow_id',
'        );      ',
'',
'    else ',
'      -- set subflow to running',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_work_started   = systimestamp',
'           , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_running',
'           , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'       where sbfl.sbfl_id       = p_subflow_id',
'         and sbfl.sbfl_prcs_id  = p_process_id',
'        ;',
'      -- log message receipt event',
'',
'',
'      -- step subflow forward',
'      flow_engine.flow_complete_step ',
'      ( p_process_id => p_process_id',
'      , p_subflow_id => p_subflow_id',
'      , p_step_key   => p_step_key',
'      );',
'    end case;',
'',
'  end receiveTask_callback;',
'  ',
'',
'end flow_tasks;',
'/',
'',
'create or replace package body flow_timers_pkg as',
'/* ',
'-- Flows for APEX - flow_timers_pkg.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates. 2022.',
'-- (c) Copyright Flowquest Limited and / or its affiliates. 2025.',
'--',
'-- Created 2020        Franco Soldaro',
'-- Edited  2020        Moritz Klein - MT AG  ',
'-- Edited  24-Feb-2023 Richard Allen, Oracle',
'-- Edited  05-Jun-2023 Louis Moreaux, Insum',
'-- Edited  20-May-2024 Richard Allen, Flowquest',
'--',
'*/',
'  lock_timeout             exception;',
'  e_invalid_duration       exception;',
'  pragma exception_init (lock_timeout, -3006);  ',
'',
'  type t_timer_def is record',
'  ( timer_type            flow_types_pkg.t_bpmn_attribute_vc2',
'  , timer_definition      flow_types_pkg.t_bpmn_attribute_vc2',
'  , oracle_date           flow_types_pkg.t_bpmn_attribute_vc2',
'  , oracle_format_mask    flow_types_pkg.t_bpmn_attribute_vc2',
'  , oracle_duration_ds    flow_types_pkg.t_bpmn_attribute_vc2',
'  , oracle_duration_ym    flow_types_pkg.t_bpmn_attribute_vc2',
'  , start_interval_ds     flow_types_pkg.t_bpmn_attribute_vc2',
'  , repeat_interval_ds    flow_types_pkg.t_bpmn_attribute_vc2',
'  , max_runs              flow_types_pkg.t_bpmn_attribute_vc2',
'  );',
'',
'  function timer_exists',
'  (',
'    pi_timr_id in flow_timers.timr_id%type',
'  ) return boolean',
'  as',
'    l_cnt number;',
'  begin',
'    select count(*)',
'      into l_cnt',
'      from flow_timers',
'     where timr_id = pi_timr_id',
'    ;',
'    return ( l_cnt = 1 );',
'  end timer_exists;',
'',
'  procedure lock_timer',
'  (',
'    pi_prcs_id  in  flow_processes.prcs_id%type',
'  , pi_sbfl_id  in  flow_subflows.sbfl_id%type',
'  )',
'  as',
'    cursor c_lock is ',
'      select timr.timr_id ',
'        from flow_timers timr',
'       where timr.timr_prcs_id = pi_prcs_id',
'         and timr.timr_sbfl_id = pi_sbfl_id',
'      for update of timr.timr_id wait 2;',
'  begin',
'    open c_lock;',
'    close c_lock;',
'  exception',
'    when lock_timeout then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''timer-lock-timeout''',
'      , p0 => pi_sbfl_id         ',
'      );',
'      -- $F4AMESSAGE ''timer-lock-timeout'' || ''Timer for subflow %0 currently locked by another user.  Try again later.''',
'  end lock_timer;',
'',
'  procedure lock_process_timers',
'  (',
'    pi_prcs_id  in  flow_processes.prcs_id%type',
'  )',
'  as',
'    cursor c_lock is ',
'      select timr.timr_id ',
'        from flow_timers timr',
'       where timr.timr_prcs_id = pi_prcs_id',
'       order by timr.timr_id',
'      for update of timr.timr_id;',
'  begin',
'    open c_lock;',
'    close c_lock;',
'  exception',
'  when lock_timeout then',
'    flow_errors.handle_instance_error',
'    ( pi_prcs_id        => pi_prcs_id',
'    , pi_message_key    => ''timers-lock-timeout''',
'    , p0 => pi_prcs_id        ',
'    );',
'    -- $F4AMESSAGE ''timers-lock-timeout'' || ''Timers for process %0 currently locked by another user.  Try again later.''',
'  end lock_process_timers;',
'',
'  function get_timer_definition',
'  (',
'    pi_prcs_id    in         flow_processes.prcs_id%type',
'  , pi_sbfl_id    in         flow_subflows.sbfl_id%type',
'  --, po_timer_type out nocopy flow_object_attributes.obat_vc_value%type',
'  --, po_timer_def  out nocopy flow_object_attributes.obat_vc_value%type',
'  ) return t_timer_def',
'  is',
'    l_timer_def                   t_timer_def;',
'    l_objt_with_timer             flow_objects.objt_id%type;',
'    l_objt_with_timer_bpmn_id     flow_objects.objt_bpmn_id%type;',
'  begin',
'    -- get objt that timers are attached to (object or attached boundaryEvent)',
'    begin ',
'      select objt.objt_id',
'           , objt.objt_bpmn_id',
'        into l_objt_with_timer',
'           , l_objt_with_timer_bpmn_id',
'        from flow_subflows sbfl',
'        join flow_objects objt',
'          on objt.objt_bpmn_id = sbfl.sbfl_current',
'         and objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'       where sbfl.sbfl_id = pi_sbfl_id',
'         and sbfl.sbfl_prcs_id = pi_prcs_id',
'         and objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition',
'      ;',
'    exception',
'      when no_data_found then',
'        -- check for an interupting timer boundary event attached',
'        begin',
'          select boundary_objt.objt_id',
'            into l_objt_with_timer',
'            from flow_subflows sbfl',
'            join flow_objects main_objt',
'              on main_objt.objt_bpmn_id = sbfl.sbfl_current',
'             and main_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'            join flow_objects boundary_objt',
'              on boundary_objt.objt_attached_to = main_objt.objt_bpmn_id',
'             and boundary_objt.objt_dgrm_id = sbfl.sbfl_dgrm_id',
'           where sbfl.sbfl_id = pi_sbfl_id',
'             and sbfl.sbfl_prcs_id = pi_prcs_id',
'             and boundary_objt.objt_sub_tag_name = flow_constants_pkg.gc_bpmn_timer_event_definition',
'             and boundary_objt.objt_interrupting = 1',
'          ;',
'        exception',
'          when no_data_found then',
'            flow_errors.handle_instance_error',
'            ( pi_prcs_id        => pi_prcs_id',
'            , pi_sbfl_id        => pi_sbfl_id',
'            , pi_message_key    => ''timer-object-not-found''',
'            , p0 => pi_sbfl_id          ',
'            );',
'            -- $F4AMESSAGE ''timer-object-not-found'' || ''Object with timer not found in get_timer_definition. Subflow %0.''',
'          when too_many_rows then',
'            flow_errors.handle_instance_error',
'            ( pi_prcs_id     => pi_prcs_id',
'            , pi_sbfl_id     => pi_sbfl_id',
'            , pi_message_key => ''boundary-event-too-many''',
'            , p0 => flow_constants_pkg.gc_bpmn_timer_event_definition',
'            );',
'            -- $F4AMESSAGE ''boundary-event-too-many'' || ''More than one %0 boundaryEvent found on sub process.''              ',
'        end;',
'    end;',
'    apex_debug.info',
'    (',
'      p_message => ''get_timer_definition.  Getting timer definition for object %s on subflow %s''',
'    , p0        => l_objt_with_timer_bpmn_id',
'    , p1        => pi_sbfl_id',
'    );',
'    ',
'    select jt.timer_type',
'         , jt.timer_definition',
'         , jt.oracle_date',
'         , jt.oracle_format_mask',
'         , jt.oracle_duration_ds',
'         , jt.oracle_duration_ym',
'         , jt.start_interval_ds',
'         , jt.repeat_interval_ds',
'         , jt.max_runs',
'      into l_timer_def',
'      from flow_objects objt',
'         , json_table( objt.objt_attributes, ''$''',
'             columns',
'               timer_type         varchar2(4000) path ''$.timerType''',
'             , timer_definition   varchar2(4000) path ''$.timerDefinition''',
'             , oracle_date        varchar2(4000) path ''$.apex.date''',
'             , oracle_format_mask varchar2(4000) path ''$.apex.formatMask''',
'             , oracle_duration_ds varchar2(4000) path ''$.apex.intervalDS''',
'             , oracle_duration_ym varchar2(4000) path ''$.apex.intervalYM''',
'             , start_interval_ds  varchar2(4000) path ''$.apex.startIntervalDS''',
'             , repeat_interval_ds varchar2(4000) path ''$.apex.repeatIntervalDS''',
'             , max_runs           varchar2(4000) path ''$.apex.maxRuns''',
'           ) jt',
'     where objt.objt_id = l_objt_with_timer',
'    ;',
'',
'    if l_timer_def.timer_type is null',
'       or',
'       ( l_timer_def.timer_type in  ( flow_constants_pkg.gc_timer_type_date ',
'                                    , flow_constants_pkg.gc_timer_type_duration',
'                                    , flow_constants_pkg.gc_timer_type_cycle',
'                                    )',
'         and  l_timer_def.timer_definition is null )',
'       or ',
'       ( l_timer_def.timer_type = flow_constants_pkg.gc_timer_type_oracle_date',
'         and  (l_timer_def.oracle_date is null ',
'              or l_timer_def.oracle_format_mask is null )',
'       )',
'       or ',
'       ( l_timer_def.timer_type = flow_constants_pkg.gc_timer_type_oracle_duration',
'         and  l_timer_def.oracle_duration_ds is null ',
'         and  l_timer_def.oracle_duration_ym is null',
'       )',
'       or ',
'       ( l_timer_def.timer_type = flow_constants_pkg.gc_timer_type_oracle_cycle',
'         and  (l_timer_def.start_interval_ds is null ',
'              or l_timer_def.repeat_interval_ds is null ',
'               )  -- note - maxRuns is allowed to be null (means no limit)',
'       )',
'    then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id        => pi_prcs_id',
'      , pi_sbfl_id        => pi_sbfl_id',
'      , pi_message_key    => ''timer-incomplete-definition''',
'      , p0 => l_objt_with_timer_bpmn_id         ',
'	    , p1 => coalesce ( l_timer_def.timer_type,  ''!NULL!'')',
'      , p2 => coalesce ( l_timer_def.timer_definition, l_timer_def.oracle_date',
'                       , l_timer_def.oracle_duration_ds, l_timer_def.start_interval_ds , ''!NULL!'')',
'      , p3 => coalesce ( l_timer_def.oracle_format_mask',
'                       , l_timer_def.oracle_duration_ym, l_timer_def.repeat_interval_ds,''!NULL!'')',
'      , p4 => coalesce ( l_timer_def.max_runs,''!NULL!'')                       ',
'      );',
'      -- $F4AMESSAGE ''timer-incomplete-definition'' || ''Incomplete timer definitions for object %0. Type: %1; Value1: %2 Value2: %3  Value3: %4''',
'    end if;',
'    return l_timer_def;',
'  end get_timer_definition;',
'',
'  procedure step_timers',
'  as',
'    e_resource_timeout      exception;',
'    pragma                  exception_init(e_resource_timeout, -30006);',
'',
'    l_timers                flow_timers%rowtype;',
'    l_run_time              flow_timers.timr_last_run%type := systimestamp;',
'    l_new_status            flow_timers.timr_status%type;',
'    l_timr_id               flow_timers.timr_id%type;',
'    l_timr_run              flow_timers.timr_run%type;',
'    l_apex_session          number;',
'  begin',
'    -- set error_handling to recursive step mode',
'    flow_globals.set_is_recursive_step (p_is_recursive_step => true);',
'    loop -- until no records found',
'      -- could add a functional index on flow_timers to improve performance of this query',
'      -- eg. create index flow_timr_n1 on flow_timers (',
'      --          case when timr_status in ( ''C'', ''A'' ) then coalesce( timr_last_run, timr_created_on ) end);',
'      select * into l_timers',
'        from flow_timers',
'       where rowid in (',
'          select max(rowid) keep (dense_rank first order by timr_start_on) trowid',
'            from flow_timers',
'           where timr_status = c_created',
'             --and coalesce( timr_last_run, timr_created_on )  < l_run_time ',
'             and timr_start_on <= l_run_time',
'          )',
'      for update wait 5',
'      ;',
'',
'      update flow_timers',
'      set timr_last_run = systimestamp',
'          , timr_status = c_ended',
'      where timr_id = l_timers.timr_id',
'        and timr_run = l_timers.timr_run',
'      ;',
'',
'      begin',
'        -- create an APEX session for the timer operation',
'        l_apex_session := flow_apex_session.create_async_session  ( p_process_id => l_timers.timr_prcs_id',
'                                                                  , p_subflow_id => l_timers.timr_sbfl_id',
'                                                                  );',
'',
'        -- ideally the flow_engine should lock the subflow and this procedure should handle the resource ',
'        -- timeout, deadlock and not found exceptions. This would happen if the subflow is locked waiting ',
'        -- to delete the timer through a cascade delete.',
'        if l_timers.timr_type in  ( flow_constants_pkg.gc_timer_type_cycle',
'                                  , flow_constants_pkg.gc_timer_type_oracle_cycle ',
'                                  ) ',
'        then ',
unistr('          -- repeating / cycle timer.  If unlimited or less than max repeats, run again...\220F'),
'          if l_timers.timr_run < l_timers.timr_repeat_times ',
'          or l_timers.timr_repeat_times is null then ',
'            l_timr_id   := l_timers.timr_id;',
'            l_timr_run  := l_timers.timr_run;',
'          end if;',
'        else',
'          l_timr_id   := null;      ',
'          l_timr_run  := null;',
'        end if;',
'        flow_engine.timer_callback',
'        (',
'          p_process_id    => l_timers.timr_prcs_id',
'        , p_subflow_id    => l_timers.timr_sbfl_id',
'        , p_step_key      => l_timers.timr_step_key',
'        , p_timr_id       => l_timr_id',
'        , p_run           => l_timr_run',
'        , p_callback      => l_timers.timr_callback',
'        , p_callback_par  => l_timers.timr_callback_par',
'        , p_event_type    => flow_constants_pkg.gc_bpmn_timer_event_definition',
'        );',
'        -- drop the session',
'        if l_apex_session is not null then',
'          flow_apex_session.delete_session ( p_session_id => l_apex_session );',
'        end if;',
'        commit;',
'      exception ',
'        -- Some exception happened during processing the timer',
'        -- We trap it here and mark respective timer as broken.',
'        when others then',
'          update flow_timers',
'            set timr_status = c_broken',
'          where timr_id = l_timers.timr_id',
'            and timr_run = l_timers.timr_run',
'          ;',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id    => l_timers.timr_prcs_id',
'          , pi_sbfl_id    => l_timers.timr_sbfl_id',
'          , pi_message_key => ''timer-broken''',
'          , p0 => l_timers.timr_id',
'          , p1 => l_timers.timr_prcs_id',
'          , p2 => l_timers.timr_sbfl_id',
'          , p3 => l_timers.timr_run',
'          );',
'          -- $F4AMESSAGE ''timer-broken'' || ''Timer %0 Run %4 broken in process %1 , subflow : %2.  See error_info.''',
'          -- set error status on subflow & Process',
'          flow_errors.set_error_status ( pi_prcs_id  => l_timers.timr_prcs_id ',
'                                       , pi_sbfl_id  => l_timers.timr_sbfl_id',
'                                       );',
'          commit;',
'      end;',
'',
'    end loop;',
'    exception ',
'      when no_data_found then return;',
'      when e_resource_timeout then',
'        -- record requiring update is locked by another process, could put some logging in here',
'        rollback;',
'        return;',
'',
'  end step_timers;',
'',
'  procedure get_iso_duration',
'  (',
'    in_string       in     varchar2',
'  , in_start_tstz   in     timestamp with time zone default null',
'  , out_start_tstz  out    timestamp with time zone',
'  , out_interv_ym   in out interval year to month',
'  , out_interv_ds   in out interval day to second',
'  )',
'  as',
'    type t_duration_components is table of number index by varchar2(1 char);',
'',
'    l_start_pos_time  pls_integer;',
'    l_token_count     pls_integer;',
'    l_before_t        varchar2(200 char);',
'    l_after_t         varchar2(200 char);',
'    l_ym_part         varchar2(200 char);',
'    l_ds_part         varchar2(200 char);',
'',
'    l_cur_component   varchar2(200 char);    ',
'  begin',
'    -- first split the string to year-month and day-second parts',
'    -- afterwards operate on both separately',
'    -- because M before T means months and M after T means minutes',
'',
'    l_start_pos_time := instr( in_string, ''T'' );',
'    if l_start_pos_time = 0 then',
'      l_before_t := in_string;',
'    else',
'      l_before_t       := substr( in_string, 1, l_start_pos_time - 1 );',
'      l_after_t        := substr( in_string, l_start_pos_time);',
'    end if;',
'',
'    -- The day indicator comes before the "T"',
'    -- however day needs to be handle with ds_interval',
'    l_token_count := regexp_count( l_before_t, ''\d+\w'' );',
'    for i in 1..l_token_count loop',
'      l_cur_component := regexp_substr(l_before_t, ''\d+\w'', 1, i);',
'',
'      case substr(l_cur_component, -1)',
'        when ''Y'' then l_ym_part := l_ym_part || l_cur_component;',
'        when ''M'' then l_ym_part := l_ym_part || l_cur_component;',
'        when ''D'' then l_ds_part := l_ds_part || l_cur_component;',
'        else null;',
'      end case;',
'    end loop;',
'',
'    l_ds_part := l_ds_part || l_after_t;',
'',
'    if l_ym_part is not null or l_ds_part is not null then',
'      out_interv_ym := to_yminterval( ''P'' || coalesce(l_ym_part, ''0Y'') );',
'      out_interv_ds := to_dsinterval( ''P'' || coalesce(l_ds_part, ''0D'') );',
'',
'      out_start_tstz  := coalesce( in_start_tstz, systimestamp ) + out_interv_ym + out_interv_ds;',
'    else',
'      raise e_invalid_duration;',
'    end if;',
'',
'  end get_iso_duration;',
'',
'/******************************************************************************',
'  START_TIMER',
'******************************************************************************/',
'',
'  procedure start_new_timer',
'  (',
'    pi_prcs_id    in flow_processes.prcs_id%type',
'  , pi_sbfl_id    in flow_subflows.sbfl_id%type ',
'  , pi_step_key   in flow_subflows.sbfl_step_key%type default null',
'  , pi_callback     in flow_timers.timr_callback%type',
'  , pi_callback_par in flow_timers.timr_callback_par%type  ',
'  )',
'  as',
'    l_parsed_tstz         flow_timers.timr_start_on%type;',
'    l_parsed_duration_ym  flow_timers.timr_interval_ym%type;',
'    l_parsed_duration_ds  flow_timers.timr_interval_ds%type;',
'    l_repeat_times        flow_timers.timr_repeat_times%type;',
'    l_repeat_def          varchar2(200);',
'    l_timer_def           t_timer_def;',
'    l_time_string         varchar2(20);',
'    e_invalid_repeat      exception;',
'    l_scope               flow_subflows.sbfl_scope%type;',
'  begin',
'    apex_debug.enter ',
'    ( ''start_new_timer''',
'    , ''prcs_id'', pi_prcs_id',
'    , ''sbfl_id'', pi_sbfl_id',
'    , ''step_key'', pi_step_key',
'    );',
'    -- preset async session parameters in proc variables',
'    flow_apex_session.set_async_proc_vars',
'        ( p_process_id  => pi_prcs_id',
'        , p_subflow_id  => pi_sbfl_id',
'        );',
'    -- set up scheduled firing time',
'    l_timer_def := get_timer_definition',
'                  (',
'                    pi_prcs_id    => pi_prcs_id',
'                  , pi_sbfl_id    => pi_sbfl_id',
'                  );',
'    apex_debug.info',
'    (',
'      p_message => ''starting new timer on subflow %0, type %1, key1: %2, key2 : %3 , key3: %4''',
'    , p0        => pi_sbfl_id',
'    , p1        => l_timer_def.timer_type',
'    , p2        => coalesce( l_timer_def.timer_definition , l_timer_def.oracle_date',
'                           , l_timer_def.oracle_duration_DS,  l_timer_def.start_Interval_DS , ''<null>'')',
'    , p3        => coalesce( l_timer_def.oracle_format_mask, l_timer_def.repeat_interval_ds, ''<null>'')',
'    , p4        => coalesce( l_timer_def.max_runs, ''<null>'')',
'    );',
'',
'    l_scope := flow_engine_util.get_scope (p_process_id => pi_prcs_id, p_subflow_id => pi_sbfl_id );',
'',
'    begin',
'      case l_timer_def.timer_type',
'        when flow_constants_pkg.gc_timer_type_date then',
'          -- ISO 8601 date - check for substitution of process variable',
'          if upper(substr(l_timer_def.timer_definition,1,5)) = flow_constants_pkg.gc_substitution_prefix || flow_constants_pkg.gc_substitution_flow_identifier then',
'            case flow_proc_vars_int.get_var_type ( pi_prcs_id  => pi_prcs_id',
'                                                 , pi_var_name => substr(l_timer_def.timer_definition,6,length(l_timer_def.timer_definition)-6)',
'                                                 , pi_scope    => l_scope',
'                                                )',
'            when flow_constants_pkg.gc_prov_var_type_date then',
'                -- substitution parameter is a date process var = already an Oracle date',
'                l_parsed_tstz :=',
'                  flow_proc_vars_int.get_var_date',
'                  ( ',
'                    pi_prcs_id  => pi_prcs_id',
'                  , pi_var_name => substr(l_timer_def.timer_definition,6,length(l_timer_def.timer_definition)-6)',
'                  , pi_scope    => l_scope',
'                  )',
'                ;',
'            when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'                l_parsed_tstz := to_timestamp_tz ( flow_proc_vars_int.get_var_vc2',
'                                                  ( pi_prcs_id  => pi_prcs_id',
'                                                  , pi_var_name => substr  ( l_timer_def.timer_definition,6',
'                                                                           , length(l_timer_def.timer_definition)-6',
'                                                                           )',
'                                                  , pi_scope    => l_scope',
'                                                  ),',
'                                                   flow_constants_pkg.gc_prov_default_date_format',
'                                                 );',
'            end case;',
'          elsif substr(l_timer_def.timer_definition,1,1) = ''T'' then',
'            -- check for just an ISO Time, and then get next time that time of day occurs (today/tomorrow)',
'            l_time_string := substr(l_timer_def.timer_definition,2,8);',
'            case ',
'              when  (sysdate - to_date(to_char(sysdate,''YYYY-MM-DD '')||l_time_string,''YYYY-MM-DD HH24:MI:SS'')) < 0 then',
'                -- today',
'                l_parsed_tstz := to_timestamp_tz( to_char (sysdate,''YYYY-MM-DD '')||l_time_string, ''YYYY-MM-DD HH24:MI:SS'');',
'              else',
'                -- tomorrow',
'                l_parsed_tstz := to_timestamp_tz(to_char ( sysdate+1,''YYYY-MM-DD '')||l_time_string,''YYYY-MM-DD HH24:MI:SS'');',
'            end case;',
'',
'          else',
'            -- assume we have an ISO date-time',
'            l_parsed_tstz := to_timestamp_tz( replace ( l_timer_def.timer_definition, ''T'', '' '' ), ''YYYY-MM-DD HH24:MI:SS TZR'' );',
'          end if;',
'        when flow_constants_pkg.gc_timer_type_duration then',
'          -- ISO 8601 Duration - check for substitution of process variable',
'          if upper(substr(l_timer_def.timer_definition,1,5)) = flow_constants_pkg.gc_substitution_prefix || flow_constants_pkg.gc_substitution_flow_identifier then',
'            l_timer_def.timer_definition :=',
'              flow_proc_vars_int.get_var_vc2',
'              ( ',
'                pi_prcs_id  => pi_prcs_id',
'              , pi_var_name => substr(l_timer_def.timer_definition,6,length(l_timer_def.timer_definition)-6)',
'              , pi_scope    => l_scope',
'              )',
'            ;',
'          end if;     ',
'          get_iso_duration',
'          (',
'            in_string       => l_timer_def.timer_definition',
'          , in_start_tstz   => systimestamp',
'          , out_start_tstz  => l_parsed_tstz',
'          , out_interv_ym   => l_parsed_duration_ym',
'          , out_interv_ds   => l_parsed_duration_ds',
'          );',
'        when flow_constants_pkg.gc_timer_type_cycle then',
'          -- ISO 8601 Cycle - check for substitution of process variable',
'          flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                             , pi_sbfl_id => pi_sbfl_id',
'                                             , pi_scope   => l_scope',
'                                             , pio_string => l_timer_def.timer_definition',
'                                             );',
'          l_repeat_def := regexp_substr (l_timer_def.timer_definition, ''^''||''R([0-9]*|-1)\/''); -- using concatenation to prevent substitution on installation via script',
'          if l_repeat_def is null then',
'            raise e_invalid_repeat;',
'          end if;',
'          l_repeat_times := substr ( l_timer_def.timer_definition, 2',
'                                   , instr( l_timer_def.timer_definition, ''/'', 1, 1 ) - 2 ',
'                                   );',
'          if l_repeat_times = -1 or l_repeat_times is null then ',
'            -- ISO8601 repeat -1 means unlimited so set repeat_times to max cycles',
'            l_repeat_times := flow_engine_util.get_config_value ',
'            ( p_config_key    => flow_constants_pkg.gc_config_timer_max_cycles',
'            , p_default_value => flow_constants_pkg.gc_config_default_timer_max_cycles',
'            );',
'          elsif l_repeat_times = 0 then',
'            -- according to ISO 8601 it should run 1 time but not repeat',
'            l_repeat_times := 1;',
'          end if;',
'',
'          l_timer_def.timer_definition := substr  ( l_timer_def.timer_definition',
'                                                  , instr( l_timer_def.timer_definition, ''/'', 1, 1 ) + 1  ',
'                                                  );',
'          get_iso_duration',
'          (',
'            in_string       => l_timer_def.timer_definition',
'          , in_start_tstz   => systimestamp',
'          , out_start_tstz  => l_parsed_tstz',
'          , out_interv_ym   => l_parsed_duration_ym',
'          , out_interv_ds   => l_parsed_duration_ds',
'          );',
'        when flow_constants_pkg.gc_timer_type_oracle_date then',
'',
'          if upper(substr(l_timer_def.oracle_date,1,5)) = flow_constants_pkg.gc_substitution_prefix || flow_constants_pkg.gc_substitution_flow_identifier then',
'            case flow_proc_vars_int.get_var_type ( pi_prcs_id  => pi_prcs_id',
'                                                 , pi_var_name => substr(l_timer_def.oracle_date,6,length(l_timer_def.oracle_date)-6)',
'                                                 , pi_scope    => l_scope',
'                                                 )',
'            when flow_constants_pkg.gc_prov_var_type_date then',
'                -- substitution parameter is a date process var = already an Oracle date',
'                l_parsed_tstz :=',
'                  flow_proc_vars_int.get_var_date',
'                  ( ',
'                    pi_prcs_id  => pi_prcs_id',
'                  , pi_var_name => substr(l_timer_def.oracle_date,6,length(l_timer_def.oracle_date)-6)',
'                  , pi_scope    => l_scope',
'                  )',
'                ;',
'            when flow_constants_pkg.gc_prov_var_type_varchar2 then',
'                -- substitution parameter is a vc2 - use the specified format mask',
'                l_parsed_tstz := to_timestamp_tz ( flow_proc_vars_int.get_var_vc2',
'                                                  ( pi_prcs_id  => pi_prcs_id',
'                                     '))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'             , pi_var_name => substr  ( l_timer_def.oracle_date,6',
'                                                                                    , length(l_timer_def.oracle_date)-6',
'                                                                                    )',
'                                                  , pi_scope    => l_scope',
'                                                  )',
'                                                , l_timer_def.oracle_format_mask',
'                                                );',
'            end case;',
'          else',
'            -- just use the specified date and format mask',
'            l_parsed_tstz := to_timestamp ( l_timer_def.oracle_date, l_timer_def.oracle_format_mask);',
'          end if;',
'        when flow_constants_pkg.gc_timer_type_oracle_duration then ',
'          -- handle possible vc2-typed subsitutions for both parameters',
'          flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                             , pi_sbfl_id => pi_sbfl_id',
'                                             , pio_string => l_timer_def.oracle_duration_ds',
'                                             , pi_scope   => l_scope',
'                                             );',
'          flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                             , pi_sbfl_id => pi_sbfl_id',
'                                             , pio_string => l_timer_def.oracle_duration_ym',
'                                             , pi_scope   => l_scope',
'                                             );',
'          l_parsed_duration_ds := to_dsinterval ( nvl ( l_timer_def.oracle_duration_ds , ''000 00:00:00'') );',
'          l_parsed_duration_ym := to_yminterval ( nvl ( l_timer_def.oracle_duration_ym, ''0-0'') );',
'          l_parsed_tstz := systimestamp + l_parsed_duration_ym + l_parsed_duration_ds;',
'',
'        when flow_constants_pkg.gc_timer_type_oracle_cycle then',
'          -- oracle cycle timer - all 3 parameters can be substituted with vc2-type proc var',
'          flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                             , pi_sbfl_id => pi_sbfl_id',
'                                             , pi_scope   => l_scope',
'                                             , pio_string => l_timer_def.start_interval_ds',
'                                             );',
'          flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                             , pi_sbfl_id => pi_sbfl_id',
'                                             , pi_scope   => l_scope',
'                                             , pio_string => l_timer_def.repeat_interval_ds',
'                                             ); ',
'          if l_timer_def.max_runs is not null then            ',
'            flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id',
'                                               , pi_sbfl_id => pi_sbfl_id',
'                                               , pi_scope   => l_scope',
'                                               , pio_string => l_timer_def.max_runs',
'                                               );                                                       ',
'            l_repeat_times  := to_number ( l_timer_def.max_runs );',
'          else',
'            l_repeat_times := flow_engine_util.get_config_value ',
'                              ( p_config_key    => flow_constants_pkg.gc_config_timer_max_cycles',
'                              , p_default_value => flow_constants_pkg.gc_config_default_timer_max_cycles',
'                              );',
'          end if;',
'          l_parsed_tstz         := systimestamp + to_dsinterval ( l_timer_def.start_interval_ds );',
'          l_parsed_duration_ym  := to_yminterval (''0-0'');  -- UI currently does not allow YM input so set to 0',
'          l_parsed_duration_ds  := to_dsinterval ( l_timer_def.repeat_interval_ds );',
'        else',
'          flow_errors.handle_instance_error',
'          ( pi_prcs_id        => pi_prcs_id',
'          , pi_sbfl_id        => pi_sbfl_id',
'          , pi_message_key    => ''timer-incomplete-definition''',
'          , p0 => pi_sbfl_id         ',
'	        , p1 => l_timer_def.timer_type',
'          , p2 => l_timer_def.timer_definition',
'          );',
'          -- $F4AMESSAGE ''timer-incomplete-definition'' || ''Incomplete timer definitions for object %0. Type: %1; Value: %2''',
'      end case;',
'    exception',
'      when e_invalid_repeat or e_invalid_duration then',
'        flow_errors.handle_instance_error',
'        (',
'          pi_prcs_id     => pi_prcs_id',
'        , pi_sbfl_id     => pi_sbfl_id',
'        , pi_message_key => ''timer_definition_error''',
'        , p0             => pi_prcs_id',
'        , p1             => pi_sbfl_id',
'        , p2             => l_timer_def.timer_type',
'        , p3             => l_timer_def.timer_definition',
'        );',
'        -- $F4AMESSAGE ''timer-definition-error'' || ''Error parsing timer definition in process %0, subflow %1. Timer Type: %2, Definition: %3]''',
'      when others then',
'        flow_errors.handle_instance_error',
'        (',
'          pi_prcs_id     => pi_prcs_id',
'        , pi_sbfl_id     => pi_sbfl_id',
'        , pi_message_key => ''timer_definition_error''',
'        , p0             => pi_prcs_id',
'        , p1             => pi_sbfl_id',
'        , p2             => l_timer_def.timer_type',
'        , p3             => l_timer_def.timer_definition',
'        );',
'        -- $F4AMESSAGE ''timer-definition-error'' || ''Error parsing timer definition in process %0, subflow %1. Timer Type: %2, Definition: %3]''',
'    end;',
'',
'    insert into flow_timers',
'      (',
'        timr_prcs_id',
'      , timr_sbfl_id',
'      , timr_step_key',
'      , timr_run',
'      , timr_type',
'      , timr_created_on',
'      , timr_status',
'      , timr_start_on',
'      , timr_interval_ym',
'      , timr_interval_ds',
'      , timr_repeat_times',
'      , timr_callback',
'      , timr_callback_par',
'      )',
'      values',
'      (',
'        pi_prcs_id',
'      , pi_sbfl_id',
'      , pi_step_key',
'      , 1',
'      , l_timer_def.timer_type',
'      , systimestamp',
'      , c_created',
'      , l_parsed_tstz',
'      , l_parsed_duration_ym',
'      , l_parsed_duration_ds',
'      , l_repeat_times',
'      , pi_callback ',
'      , pi_callback_par ',
'      )',
'    ;',
'',
'  end start_new_timer;',
'',
'  procedure start_repeat_timer',
'  (',
'    pi_prcs_id      in flow_processes.prcs_id%type',
'  , pi_sbfl_id      in flow_subflows.sbfl_id%type ',
'  , pi_step_key     in flow_subflows.sbfl_step_key%type default null',
'  , pi_callback     in flow_timers.timr_callback%type',
'  , pi_callback_par in flow_timers.timr_callback_par%type  ',
'  , pi_run          in flow_timers.timr_run%type default 1 -- 1 original, 2-> repeats',
'  , pi_timr_id      in flow_timers.timr_id%type default null -- only set on repeats',
'  )',
'  as',
'    l_parsed_tstz         flow_timers.timr_start_on%type;',
'    l_parsed_duration_ym  flow_timers.timr_interval_ym%type;',
'    l_parsed_duration_ds  flow_timers.timr_interval_ds%type;',
'    l_repeat_times        flow_timers.timr_repeat_times%type;',
'    l_timer_def           t_timer_def;',
'  begin',
'    apex_debug.enter ',
'    ( ''start_repeat_timer''',
'    , ''prcs_id'', pi_prcs_id',
'    , ''sbfl_id'', pi_sbfl_id',
'    , ''step_key'', pi_step_key',
'    , ''timr_id (repeats)'', pi_timr_id',
'    , ''run'', pi_run',
'    );',
'',
'    insert into flow_timers',
'    ( timr_id',
'    , timr_run',
'    , timr_prcs_id',
'    , timr_sbfl_id',
'    , timr_step_key',
'    , timr_type',
'    , timr_created_on',
'    , timr_status',
'    , timr_start_on',
'    , timr_interval_ym',
'    , timr_interval_ds',
'    , timr_repeat_times',
'    , timr_callback',
'    , timr_callback_par',
'    ) ',
'    select',
'      pi_timr_id',
'    , pi_run',
'    , pi_prcs_id',
'    , pi_sbfl_id',
'    , pi_step_key',
'    , old_timr.timr_type',
'    , systimestamp',
'    , c_created',
'    , systimestamp + nvl(old_timr.timr_interval_ym,''0-0'') + nvl(old_timr.timr_interval_ds,''0 00:00:00'')',
'    , old_timr.timr_interval_ym',
'    , old_timr.timr_interval_ds',
'    , old_timr.timr_repeat_times',
'    , pi_callback ',
'    , pi_callback_par ',
'    from flow_timers old_timr',
'    where old_timr.timr_id = pi_timr_id',
'      and old_timr.timr_run = pi_run - 1',
'      and old_timr.timr_prcs_id = pi_prcs_id',
'    ;',
'',
'  end start_repeat_timer;',
'',
'  procedure start_timer',
'  (',
'    pi_prcs_id      in flow_processes.prcs_id%type',
'  , pi_sbfl_id      in flow_subflows.sbfl_id%type ',
'  , pi_step_key     in flow_subflows.sbfl_step_key%type default null',
'  , pi_callback     in flow_timers.timr_callback%type',
'  , pi_callback_par in flow_timers.timr_callback_par%type default null',
'  , pi_run          in flow_timers.timr_run%type default 1 -- 1 original, 2-> repeats',
'  , pi_timr_id      in flow_timers.timr_id%type default null -- only set on repeats',
'  )',
'  as',
'    l_parsed_tstz         flow_timers.timr_start_on%type;',
'    l_parsed_duration_ym  flow_timers.timr_interval_ym%type;',
'    l_parsed_duration_ds  flow_timers.timr_interval_ds%type;',
'    l_repeat_times        flow_timers.timr_repeat_times%type;',
'    l_timer_def           t_timer_def;',
'  begin',
'    apex_debug.enter ',
'    ( ''start_timer''',
'    , ''prcs_id'', pi_prcs_id',
'    , ''sbfl_id'', pi_sbfl_id',
'    , ''step_key'', pi_step_key',
'    , ''callback'', pi_callback',
'    , ''timr_id (repeats)'', pi_timr_id',
'    , ''timer run'', pi_run',
'    );',
'    if pi_run = 1 and pi_timr_id is null then',
'      -- starting the first run of a new timer',
'      start_new_timer',
'      ( pi_prcs_id      => pi_prcs_id   ',
'      , pi_sbfl_id      => pi_sbfl_id  ',
'      , pi_step_key     => pi_step_key ',
'      , pi_callback     => pi_callback',
'      , pi_callback_par => pi_callback_par',
'      );',
'    elsif pi_run > 1 and pi_timr_id is not null then',
'        -- starting a repeat cycle of a existing timer (on a new sbfl)',
'      start_repeat_timer',
'      ( pi_prcs_id      => pi_prcs_id   ',
'      , pi_sbfl_id      => pi_sbfl_id  ',
'      , pi_step_key     => pi_step_key ',
'      , pi_callback     => pi_callback',
'      , pi_callback_par => pi_callback_par',
'      , pi_run          => pi_run',
'      , pi_timr_id      => pi_timr_id',
'      );  ',
'    else',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => pi_prcs_id',
'        , pi_sbfl_id        => pi_sbfl_id',
'        , pi_message_key    => ''timer-internal-error''',
'        , p0 => pi_sbfl_id         ',
'	      , p1 => pi_run',
'        , p2 => pi_timr_id',
'        );',
'        -- $F4AMESSAGE ''timer-internal-error'' || ''Timer internal error  for object %0. Type: %1; Value: %2''',
'    end if;',
'  end start_timer;',
'',
'/******************************************************************************',
'  RESCHEDULE_TIMER',
'*******************************************************************************/',
'',
'procedure reschedule_timer',
'(',
'    p_process_id        in flow_processes.prcs_id%type',
'  , p_subflow_id        in flow_subflows.sbfl_id%type',
'  , p_step_key          in flow_subflows.sbfl_step_key%type default null',
'  , p_is_immediate      in boolean default false',
'  , p_restart_immediate in boolean default false',
'  , p_new_timestamp     in flow_timers.timr_start_on%type default null',
'  , p_comment           in flow_instance_event_log.lgpr_comment%type default null',
')',
'is',
'  l_timer_rec       flow_timers%rowtype;',
'  e_bad_new_timer   exception;',
'  l_current_object  flow_subflows.sbfl_current%type;',
'begin',
'  apex_debug.enter ',
'  ( ''reschedule_timer''',
'  , ''Process ID'',  p_process_id',
'  , ''Subflow ID'', p_subflow_id',
'  , ''Step Key'', p_step_key',
'  , ''Immediate'', case when p_is_immediate then ''true'' else ''false'' end',
'  , ''New Timestamp'', p_new_timestamp',
'  );',
'  -- lock the timer',
'  -- first try to lock a current active (i.e., ''created'') timer on the subflow',
'  begin',
'    select *',
'      into l_timer_rec',
'      from flow_timers timr ',
'     where timr.timr_prcs_id = p_process_id',
'       and timr.timr_sbfl_id = p_subflow_id',
'       and timr.timr_status = flow_timers_pkg.c_created',
'       for update wait 5',
'    ;',
'  exception',
'    when no_data_found then',
'      if p_restart_immediate then',
'        -- handle timer event restarts where timer has already fired but step needs to be re-started',
'        -- requires the old ''nded'' timer to be restarted with an imediate schedule. (See test case 3h2 Issue #710)',
'        select *',
'          into l_timer_rec',
'          from flow_timers timr ',
'         where timr.timr_last_run = ( select max (timr_last_run )',
'                                      from   flow_timers ',
'                                      where  timr_prcs_id = p_process_id',
'                                      and    timr_sbfl_id = p_subflow_id',
'                                      and    timr.timr_status = flow_timers_pkg.c_ended',
'                                    )',
'           and timr_prcs_id = p_process_id',
'           and timr_sbfl_id = p_subflow_id',
'           and timr.timr_status = flow_timers_pkg.c_ended',
'           for update wait 5',
'        ;',
'      else',
'        raise;',
'      end if;',
'  end;',
'  if flow_engine_util.step_key_valid( pi_prcs_id  => p_process_id',
'                                    , pi_sbfl_id  => p_subflow_id',
'                                    , pi_step_key_supplied  => p_step_key',
'                                    , pi_step_key_required  => l_timer_rec.timr_step_key) then ',
'    if p_is_immediate then',
'      l_timer_rec.timr_start_on := systimestamp;',
'    elsif p_new_timestamp >= systimestamp then',
'      l_timer_rec.timr_start_on := p_new_timestamp;',
'    elsif not p_is_immediate  and p_new_timestamp is null then',
'      raise e_bad_new_timer;',
'    end if;',
'',
'    update flow_timers',
'       set timr_start_on = l_timer_rec.timr_start_on',
'         , timr_status = c_created',
'     where timr_id = l_timer_rec.timr_id',
'       and timr_run = l_timer_rec.timr_run',
'    ;',
'',
'    select sbfl.sbfl_current',
'      into l_current_object',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_id = p_subflow_id',
'       and sbfl.sbfl_prcs_id = p_process_id',
'    ;',
'',
'    flow_logging.log_step_event',
'    ( p_process_id  => p_process_id',
'    , p_subflow_id  => p_subflow_id',
'    , p_event       => flow_constants_pkg.gc_prcs_event_rescheduled',
'    , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'    , p_comment     => p_comment',
'    );',
'',
'  end if;',
'exception',
'  when no_data_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => p_subflow_id',
'      , pi_message_key => ''engine-util-sbfl-not-found''',
'      , p0 => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''engine-util-sbfl-not-found'' || ''Subflow ID supplied ( %0 ) not found. Check for process events that changed process flow (timeouts, errors, escalations).''  ',
'  when lock_timeout then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => p_subflow_id',
'      , pi_message_key => ''timeout_locking_subflow''',
'      , p0 => p_subflow_id',
'      );',
'      -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Retry your transaction later.''  ',
'  when e_bad_new_timer then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => p_process_id',
'        , pi_sbfl_id        => p_subflow_id',
'        , pi_message_key    => ''timer-incomplete-definition''',
'        , p0 => p_subflow_id       ',
'	      , p1 => case when p_is_immediate then ''true'' else ''false'' end',
'        , p2 => p_new_timestamp',
'        );',
'        -- $F4AMESSAGE ''timer-incomplete-definition'' || ''Incomplete timer definitions for object %0. Type: %1; Value: %2''',
'',
'end reschedule_timer;',
'',
'/******************************************************************************',
'  suspend_process_timers',
'    suspend all timers for a process instance',
'******************************************************************************/',
'',
'  procedure suspend_process_timers',
'  (',
'    pi_prcs_id  in  flow_processes.prcs_id%type',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_suspended',
'     where timr_prcs_id = pi_prcs_id',
'       and timr_status = c_created',
'    ;',
'  end suspend_process_timers;',
'',
'/******************************************************************************',
'  resume_process_timers',
'    resume all timers for a process instance    ',
'******************************************************************************/',
'',
'  procedure resume_process_timers',
'  (',
'    pi_prcs_id  in  flow_processes.prcs_id%type',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_created',
'     where timr_prcs_id = pi_prcs_id',
'       and timr_status = c_suspended',
'    ;',
'  end resume_process_timers;',
'',
'/******************************************************************************',
'  EXPIRE_TIMER',
'******************************************************************************/',
'',
'  procedure expire_timer',
'  (',
'    pi_prcs_id in flow_processes.prcs_id%type',
'  , pi_sbfl_id in flow_subflows.sbfl_id%type ',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_expired',
'     where timr_prcs_id = pi_prcs_id',
'       and timr_sbfl_id = pi_sbfl_id',
'       and timr_status not in (c_ended, c_expired, c_terminated)',
'    ;',
'  end expire_timer;',
'',
'/******************************************************************************',
'  TERMINATE_TIMER',
'******************************************************************************/',
'',
'  procedure terminate_timer',
'  (',
'    pi_prcs_id      in flow_processes.prcs_id%type',
'  , pi_sbfl_id      in flow_subflows.sbfl_id%type',
'  , po_return_code out number',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_terminated',
'     where timr_prcs_id = pi_prcs_id',
'       and timr_sbfl_id = pi_sbfl_id',
'       and timr_status not in (c_ended, c_expired, c_terminated)',
'    ;',
'  end terminate_timer;',
'',
'/******************************************************************************',
'  TERMINATE_PROCESS_TIMERS',
'******************************************************************************/',
'',
'  procedure terminate_process_timers',
'  (',
'    pi_prcs_id      in flow_processes.prcs_id%type',
'  , po_return_code out number',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_terminated',
'     where timr_prcs_id = pi_prcs_id',
'       and timr_status not in (c_ended, c_expired, c_terminated)',
'    ;',
'  end terminate_process_timers;',
'',
'/******************************************************************************',
'  TERMINATE_ALL_TIMERS',
'******************************************************************************/',
'',
'  procedure terminate_all_timers',
'  (',
'    po_return_code  out  number',
'  )',
'  is',
'  begin',
'    update flow_timers',
'       set timr_status = c_terminated',
'     where timr_status not in (c_ended, c_expired, c_terminated)',
'    ;',
'  end terminate_all_timers;',
'',
'/******************************************************************************',
'  delete_process_timers',
'    delete all the timers of a process.',
'******************************************************************************/',
'',
'  procedure delete_process_timers',
'  (',
'    pi_prcs_id      in flow_processes.prcs_id%type',
'  , po_return_code out number',
'  )',
'  is ',
'  begin',
'    delete',
'      from flow_timers',
'     where timr_prcs_id = pi_prcs_id',
'    ;',
'  end delete_process_timers;',
'',
'  function get_timer_repeat_interval',
'  return sys.all_scheduler_jobs.repeat_interval%type',
'  as',
'    l_repeat_interval  sys.all_scheduler_jobs.repeat_interval%type;',
'  begin',
'    begin',
'      select repeat_interval',
'        into l_repeat_interval',
'        from sys.user_scheduler_jobs',
'       where job_name = ''APEX_FLOW_STEP_TIMERS_J'';',
'    exception',
'      when no_data_found then',
'        l_repeat_interval := null;',
'    end;',
'    return l_repeat_interval;',
'  end get_timer_repeat_interval;',
'',
'  procedure set_timer_repeat_interval ',
'  ( p_repeat_interval  in  varchar2',
'  )',
'  is',
'    l_existing_value                sys.all_scheduler_jobs.repeat_interval%type;',
'    l_host_url                      varchar2(4000);',
'    e_scheduler_repeat_too_small  exception;',
'  begin',
'    apex_debug.enter',
'    ( ''set_timer_repeat_interval''',
'    , ''p_repeat_interval'', p_repeat_interval ',
'    );',
'    -- check if this is actually an update, if not, ignore it.',
'    l_existing_value := get_timer_repeat_interval;',
'',
'    if l_existing_value = p_repeat_interval then',
'      -- no chages required',
'      null;',
'    else',
'      -- changes required',
'      l_host_url := apex_util.host_url;',
'      ',
'      if ( l_host_url like ''%apex.oracle.com%''',
'         or l_host_url like ''%oracleapex.com%''',
'         or l_host_url like ''%apex.oraclecorp.com%'' ',
'         )',
'      then ',
'        if p_repeat_interval like ''%SECONDLY%'' then',
'          raise e_scheduler_repeat_too_small;',
'        end if;',
'      end if;      ',
'      -- go ahead with the update',
'      sys.dbms_scheduler.set_attribute',
'      ( name => ''APEX_FLOW_STEP_TIMERS_J''',
'      , attribute => ''repeat_interval''',
'      , value => p_repeat_interval',
'      );',
'      apex_debug.message',
'      ( p_message => ''--- Timer scheduler repeat interval set.  Host: %0 Requested Interval %1''',
'      , p0 => l_host_url',
'      , p1 => p_repeat_interval',
'      );',
'    end if;',
'  exception',
'    when e_scheduler_repeat_too_small then',
'      apex_debug.message',
'      ( p_message => ''Attempt to set timer repeat interval too frequent.  Host: %0 Requested Interval %1''',
'      , p0 => l_host_url',
'      , p1 => p_repeat_interval',
'      );',
'      flow_errors.handle_general_error',
'      (pi_message_key  => ''scheduler-repeat-shared-env''',
'      , p0  => l_host_url',
'      , p1  => p_repeat_interval',
'      );',
'      -- $F4AMESSAGE ''scheduler-repeat-shared-env'' || ''Timer repeat interval too frequent for host (%0) Requested Interval %1.  Must be greater than 1 Minute.''',
'  end set_timer_repeat_interval;',
'',
'  function get_timer_status',
'  return varchar2',
'  as',
'    l_status  sys.user_scheduler_jobs.enabled%type;',
'  begin',
'    begin',
'      select enabled',
'        into l_status',
'        from sys.user_scheduler_jobs',
'       where job_name = ''APEX_FLOW_STEP_TIMERS_J'';',
'    exception ',
'      when no_data_found then',
'      l_status := ''FALSE'';',
'    end;',
'    return l_status;',
'  end get_timer_status;',
'    ',
'  procedure disable_scheduled_job',
'  as',
'  begin',
'    execute immediate',
'    q''[begin',
'    sys.dbms_scheduler.disable( name => ''apex_flow_step_timers_j'' );',
'    end;]'';',
'  end disable_scheduled_job;',
'',
'  procedure enable_scheduled_job',
'  as',
'  begin',
'    execute immediate',
'    q''[begin',
'    sys.dbms_scheduler.enable( name => ''apex_flow_step_timers_j'' );',
'    end;]'';',
'  end enable_scheduled_job;',
'',
'  function timer_job_exists',
'    return boolean',
'  as',
'    l_dummy number;',
'  begin',
'    select 1',
'      into l_dummy',
'      from sys.user_scheduler_jobs',
'     where job_name = ''APEX_FLOW_STEP_TIMERS_J''',
'    ;',
'    return true;',
'  exception',
'    when no_data_found then',
'      return false;',
'',
'  end timer_job_exists;',
'',
'end flow_timers_pkg;',
'/',
'',
'create or replace package body flow_usertask_pkg',
'as',
'/* ',
'-- Flows for APEX - flow_usertask_pkg.pkb',
'-- ',
'-- (c) Copyright Oracle Corporation and / or its affiliates, 2022.',
'-- (c) Copyright MT AG, 2020-2022.',
'-- (c) Copyright Flowquest Limited and/or its affiliates, 2025',
'--',
'-- Created 12-Nov-2020 Moritz Klein (MT AG) ',
'-- Edited  13-Apr-2022 Richard Allen (Oracle)',
'-- Edited  23-May-2022 Moritz Klein (MT AG)',
'-- Edted   23-Apr-2025 Richard Allen (Flowquest)',
'--',
'*/',
'  e_lock_timeout exception;',
'  pragma exception_init (e_lock_timeout, -3006);',
'  ',
'  function get_url',
'  (',
'    pi_prcs_id  in flow_processes.prcs_id%type',
'  , pi_sbfl_id  in flow_subflows.sbfl_id%type',
'  , pi_objt_id  in flow_objects.objt_id%type',
'  , pi_step_key in flow_subflows.sbfl_step_key%type default null',
'  , pi_scope    in flow_subflows.sbfl_scope%type default 0',
'  ) return varchar2',
'  as',
'    l_application        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_page               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_request            flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_clear_cache        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_items              flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_values             flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_form_template_item flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_form_template_id   flow_types_pkg.t_bpmn_attribute_vc2;',
'  begin',
'    select max(ut_application)',
'         , max(ut_page_id)',
'         , max(ut_request)',
'         , max(ut_clear_cache)',
'         , listagg( ut_item_name, '','' ) within group ( order by order_key ) as item_names',
'         , listagg( ut_item_value, '','' ) within group ( order by order_key ) as item_values',
'         , max(ut_form_template_item)',
'         , max(ut_form_template_id)',
'      into l_application',
'         , l_page',
'         , l_request',
'         , l_clear_cache',
'         , l_items',
'         , l_values',
'         , l_form_template_item',
'         , l_form_template_id',
'      from flow_objects objt',
'      join json_table( objt.objt_attributes',
'           , ''$.apex''',
'             columns',
'               ut_application        varchar2(4000) path ''$.applicationId''',
'             , ut_page_id            varchar2(4000) path ''$.pageId''',
'             , ut_request            varchar2(4000) path ''$.request''',
'             , ut_clear_cache        varchar2(4000) path ''$.cache''',
'             , nested path ''$.pageItems[*]''',
'                 columns ( order_key for ordinality',
'                         , ut_item_name varchar2(4000) path ''$.name''',
'                         , ut_item_value varchar2(4000) path ''$.value''',
'                         )',
'             , ut_form_template_item varchar2(4000) path ''$.formTemplateItem''',
'             , ut_form_template_id   varchar2(4000) path ''$.formTemplateId''',
'           ) jt',
'        on objt.objt_id = pi_objt_id',
'    ;',
'',
'    -- substitution for all attributes (was values only pre-23.1)',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_application );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_page );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_request );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_clear_cache );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_items );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_values );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_form_template_item );',
'    flow_proc_vars_int.do_substitution ( pi_prcs_id => pi_prcs_id, pi_sbfl_id => pi_sbfl_id, pi_step_key => pi_step_key, pi_scope => pi_scope, pio_string  => l_form_template_id );',
'',
'    -- apex_simple_form',
'    if l_form_template_id is not null',
'       and',
'       l_form_template_item is not null',
'    then',
'      -- append item name',
'      if l_items is null then',
'        l_items := l_form_template_item;',
'      else',
'        l_items := l_items || '','' || l_form_template_item;',
'      end if;',
'      -- append item value',
'      if l_values is null then',
'        l_values := l_form_template_id;',
'      else',
'        l_values := l_values || '','' || l_form_template_id;',
'      end if;',
'    end if;',
'',
'    return',
'      apex_page.get_url',
'      (',
'        p_application => l_application',
'      , p_page        => l_page',
'      , p_request     => l_request',
'      , p_clear_cache => l_clear_cache',
'      , p_items       => l_items',
'      , p_values      => l_values',
'      )',
'    ;',
'  end get_url;',
'',
'  procedure process_apex_page_task',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_priority_json           flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority                flow_subflows.sbfl_priority%type;',
'    l_due_on_json             flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_due_on                  flow_subflows.sbfl_due_on%type;',
'    l_potential_users_json    flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_potential_users         flow_subflows.sbfl_potential_users%type;',
'    l_potential_users_t       apex_t_varchar2;',
'    l_potential_groups_json   flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_potential_groups        flow_subflows.sbfl_potential_groups%type;',
'    l_excluded_users_json     flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_excluded_users          flow_subflows.sbfl_excluded_users%type;',
'    l_reservation             flow_subflows.sbfl_reservation%type;',
'    l_is_unallocated          varchar2(10) := flow_constants_pkg.gc_vcbool_true;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_APEX_page_task''',
'    , ''p_step_info.target_objt_tag''   , p_step_info.target_objt_tag ',
'    , ''p_step_info.target_objt_subtag'', p_step_info.target_objt_subtag ',
'    );',
'      -- get the userTask subtype  ',
'    select objt.objt_attributes."apex"."priority"',
'         , objt.objt_attributes."apex"."dueOn"',
'         , objt.objt_attributes."apex"."potentialUsers"',
'         , objt.objt_attributes."apex"."potentialGroups"',
'         , objt.objt_attributes."apex"."excludedUsers"',
'      into l_priority_json',
'         , l_due_on_json',
'         , l_potential_users_json',
'         , l_potential_groups_json ',
'         , l_excluded_users_json',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_step_info.target_objt_ref',
'       and objt.objt_dgrm_id = p_sbfl_in'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'fo.sbfl_dgrm_id',
'       ;',
'',
'      if l_priority_json is not null then',
'        l_priority := flow_settings.get_priority ',
'                      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                      , pi_expr    => l_priority_json',
'                      , pi_scope   => p_sbfl_info.sbfl_scope',
'                      );',
'      end if;',
'      if l_due_on_json is not null then ',
'        l_due_on   := flow_settings.get_due_on ',
'                      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                      , pi_expr    => l_due_on_json',
'                      , pi_scope   => p_sbfl_info.sbfl_scope',
'                      );',
'      end if;',
'',
'      if l_potential_groups_json is not null then ',
'        l_potential_groups := flow_settings.get_vc2_expression',
'                      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                      , pi_expr    => l_potential_groups_json',
'                      , pi_scope   => p_sbfl_info.sbfl_scope',
'                      );',
'        l_is_unallocated := flow_constants_pkg.gc_vcbool_false;',
'      end if;',
'      if l_excluded_users_json is not null then ',
'        l_excluded_users := flow_settings.get_vc2_expression',
'                      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                      , pi_expr    => l_excluded_users_json',
'                      , pi_scope   => p_sbfl_info.sbfl_scope',
'                      );',
'        l_is_unallocated := flow_constants_pkg.gc_vcbool_false;',
'      end if;',
'      if l_potential_users_json is not null then ',
'        l_potential_users := flow_settings.get_vc2_expression ',
'                      ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                      , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                      , pi_expr    => l_potential_users_json',
'                      , pi_scope   => p_sbfl_info.sbfl_scope',
'                      );',
'        l_is_unallocated := flow_constants_pkg.gc_vcbool_false;',
'        -- check if only 1 potential user & if so, auto-reserve',
'        if l_potential_groups is null then',
'          l_potential_users_t := apex_string.split ( p_str => l_potential_users, p_sep => '':'');',
'          if l_potential_users_t is not null then',
'            if l_potential_users_t.count = 1 then',
'              if not apex_string_util.phrase_exists (p_phrase => l_potential_users_t(1), p_string => l_excluded_users) then',
'                -- only 1 potential user who is not excluded so auto-reserve',
'                l_reservation := l_potential_users_t(1);',
'              end if;',
'            end if;',
'          end if;',
'        end if;       ',
'      end if;',
'',
'      -- if no specific task allocation was found, (i.e., l_is_unallocated is true ) use the lane role already set on the subflow ',
'      -- as the potential_group if it has a lane role',
'',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_last_update        = systimestamp',
'           , sbfl.sbfl_priority           = l_priority',
'           , sbfl.sbfl_due_on             = l_due_on',
'           , sbfl.sbfl_reservation        = l_reservation',
'           , sbfl.sbfl_potential_users    = l_potential_users',
'           , sbfl.sbfl_potential_groups   = coalesce ( l_potential_groups',
'                                                     , case ',
'                                                       when l_is_unallocated = flow_constants_pkg.gc_vcbool_true ',
'                                                        and sbfl_lane_isRole = flow_constants_pkg.gc_vcbool_true',
'                                                       then ',
'                                                         sbfl_lane_role',
'                                                       else null end',
'                                                      , null )                                                         ',
'           , sbfl.sbfl_excluded_users     = l_excluded_users',
'           , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'       where sbfl.sbfl_id       = p_sbfl_info.sbfl_id',
'         and sbfl.sbfl_prcs_id  = p_sbfl_info.sbfl_prcs_id',
'      ;',
'  end process_apex_page_task;',
'',
'  function apex_task_pk_is_required',
'  ( p_app_id          flow_types_pkg.t_bpmn_attribute_vc2',
'  , p_task_static_id  flow_types_pkg.t_bpmn_attribute_vc2',
'  ) return boolean',
'  is',
'    l_task_pk_required  boolean;',
'    l_static_id            apex_appl_taskdefs.static_id%type;',
'    l_actions_table_name   apex_appl_taskdefs.actions_table_name%type;',
'    l_actions_sql_query    apex_appl_taskdefs.actions_sql_query%type;',
'  begin',
'    --',
'    --  See if  the APEX Task needs a PK to be supplied. (for Actions Source Table or Actions Source Query)',
'    --',
'',
'    select td.static_id',
'         , td.actions_table_name',
'         , td.actions_sql_query',
'      into l_static_id',
'         , l_actions_table_name',
'         , l_actions_sql_query ',
'      from apex_appl_taskdefs td',
'     where td.application_id = p_app_id',
'       and td.static_id      = p_task_static_id;',
'  ',
'    return (l_actions_sql_query is not null) or (l_actions_table_name is not null);',
'',
'  end apex_task_pk_is_required;',
'',
'  procedure process_apex_approval_task',
'  ( p_sbfl_info     in flow_subflows%rowtype',
'  , p_step_info     in flow_types_pkg.flow_step_info',
'  )',
'  is ',
'    l_prcs_id                 flow_processes.prcs_id%type      := p_sbfl_info.sbfl_prcs_id;',
'    l_sbfl_id                 flow_subflows.sbfl_id%type       := p_sbfl_info.sbfl_id;',
'    l_scope                   flow_subflows.sbfl_scope%type    := p_sbfl_info.sbfl_scope;',
'    l_step_key                flow_subflows.sbfl_step_key%type := p_sbfl_info.sbfl_step_key;',
'    l_app_id                  flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_static_id               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_subject                 flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_parameters              flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_business_ref            flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_initiator               flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_initiator_can_complete  flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority_setting        flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_priority                flow_subflows.sbfl_priority%type;',
'    l_due_on_setting          flow_types_pkg.t_bpmn_attribute_vc2; ',
'    l_due_on                  flow_subflows.sbfl_due_on%type;',
'    l_potential_users_setting flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_potential_users         flow_subflows.sbfl_potential_users%type;',
'    l_business_admin_setting  flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_business_admin          flow_subflows.sbfl_apex_business_admin%type;',
'    l_result_var              flow_types_pkg.t_bpmn_attribute_vc2;',
'    l_apex_task_id            number;',
'',
'    e_priority_invalid   exception;',
'    e_business_ref_null  exception;',
'',
'    l_task_parameters  apex_human_task.t_task_parameters := apex_human_task.t_task_parameters();',
'    l_task_parameter   apex_human_task.t_task_parameter;',
'  begin',
'    apex_debug.enter ',
'    ( ''process_apex_approval_task''',
'    , ''step_bpmn_id: '', p_step_info.target_objt_ref',
'    );',
'',
'    -- get the parameters for the Approval Task creation',
'    select objt.objt_attributes."apex"."applicationId"',
'         , objt.objt_attributes."apex"."taskStaticId"',
'         , objt.objt_attributes."apex"."subject"',
'         , objt.objt_attributes."apex"."parameters"',
'         , objt.objt_attributes."apex"."businessRef"',
'         , objt.objt_attributes."apex"."resultVariable"',
'         , objt.objt_attributes."apex"."initiator"  ',
'         , objt.objt_attributes."apex"."initiatorCanComplete"  ',
'         , objt.objt_attributes."apex"."priority"',
'         , objt.objt_attributes."apex"."dueOn"',
'         , objt.objt_attributes."apex"."potentialUsers"',
'         , objt.objt_attributes."apex"."businessAdmin" ',
'      into l_app_id',
'         , l_static_id',
'         , l_subject',
'         , l_parameters',
'         , l_business_ref',
'         , l_result_var',
'         , l_initiator',
'         , l_initiator_can_complete',
'         , l_priority_setting',
'         , l_due_on_setting',
'         , l_potential_users_setting',
'         , l_business_admin_setting',
'      from flow_objects objt',
'     where objt.objt_bpmn_id = p_step_info.target_objt_ref',
'       and objt.objt_dgrm_id = p_sbfl_info.sbfl_dgrm_id',
'    ;',
'    apex_debug.info ',
'      ( p_message => ''APEX Approval Task parameter  %0 ''',
'      , p0 => l_parameters',
'      );',
'    -- do substitutions',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_app_id);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_static_id);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_subject);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_parameters);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_business_ref);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_result_var);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_initiator);',
'    flow_proc_vars_int.do_substitution( pi_prcs_id => l_prcs_id, pi_sbfl_id => l_sbfl_id, pi_scope => l_scope, pi_step_key => l_step_key, pio_string => l_business_admin);',
'',
'    if l_priority_setting is not null then',
'      l_priority := flow_settings.get_priority ( pi_prcs_id  => l_prcs_id',
'                                               , pi_sbfl_id  => l_sbfl_id',
'                                               , pi_expr     => l_priority_setting',
'                                               , pi_scope    => l_scope',
'                                               );',
'    end if;',
'',
'    if l_due_on_setting is not null then                                          ',
'      l_due_on :=   flow_settings.get_due_on   ( pi_prcs_id  => l_prcs_id',
'                                               , pi_sbfl_id  => l_sbfl_id',
'                                               , pi_expr     => l_due_on_setting',
'                                               , pi_scope    => l_scope',
'                                               );',
'    end if; ',
'',
'    if l_potential_users_setting is not null then ',
'      l_potential_users := flow_settings.get_vc2_expression ',
'                           ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                           , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                           , pi_expr    => l_potential_users_setting',
'                           , pi_scope   => p_sbfl_info.sbfl_scope',
'                           );',
'    end if;',
'',
'    if l_business_admin_setting is not null then',
'       l_business_admin := flow_settings.get_vc2_expression ',
'                           ( pi_prcs_id => p_sbfl_info.sbfl_prcs_id',
'                           , pi_sbfl_id => p_sbfl_info.sbfl_id',
'                           , pi_expr    => l_business_admin_setting',
'                           , pi_scope   => p_sbfl_info.sbfl_scope',
'                           );',
'    end if;',
'',
'    -- update subflow with potential users and business admin info so that APEX Human Task can call back...',
'    if l_potential_users is not null ',
'    or l_business_admin is not null then',
'',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_last_update          = systimestamp',
'           , sbfl.sbfl_potential_users      = l_potential_users',
'           , sbfl.sbfl_apex_business_admin  = l_business_admin',
'           , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'       where sbfl.sbfl_id       = l_sbfl_id',
'         and sbfl.sbfl_prcs_id  = l_prcs_id',
'      ;',
'',
'    end if;',
'',
'    -- create parameters table',
'    for parameters in (',
'      select static_id',
'           , data_type',
'           , value',
'      from json_table (l_parameters, ''$[*]''',
'                       columns(',
'                                static_id path ''$.parStaticId'',',
'                                data_type path ''$.parDataType'',',
'                                value     path ''$.parValue''',
'                              )',
'                      )',
'    )',
'    loop',
'      l_task_parameter.static_id    := parameters.static_id;',
'      l_task_parameter.string_value := parameters.value;',
'      l_task_parameters(l_task_parameters.count+1) := l_task_parameter;',
'      apex_debug.info ',
'      ( p_message => ''APEX Approval Task parameter created - parameter %0 value %1''',
'      , p0 => parameters.static_id',
'      , p1 => parameters.value',
'      );',
'    end loop;',
'    -- check that priority is a valid priority 1-5 before passing',
'    begin',
'      if l_priority is not null then',
'        if l_priority not between 1 and 5 then',
'          raise e_priority_invalid;',
'        end if;',
'      end if;',
'    exception',
'      when value_error then',
'        apex_debug.error',
'        ( p_message => ''APEX Approval Task priority (%0) must be between 1 and 5''',
'        , p0 => l_priority',
'        );',
'        raise e_priority_invalid;',
'    end;',
'    -- check that business_ref is not null before passing (prevents "lost" tasks in APEX)',
'    l_business_ref := coalesce(l_business_ref, flow_globals.business_ref);',
'    if l_business_ref is null then',
'      if apex_task_pk_is_required (p_app_id => l_app_id, p_task_static_id => l_static_id) then ',
'        apex_debug.error',
'        ( p_message => ''APEX Approval Task business ref is null''',
'        , p0 => coalesce(l_business_ref, flow_globals.business_ref)',
'        );',
'        raise e_business_ref_null;',
'      end if;',
'    end if;',
'',
'    begin',
'      l_apex_task_id := apex_human_task.create_task',
'                     ( p_application_id           => l_app_id',
'                     , p_task_def_static_id       => l_static_id',
'                     , p_subject                  => l_subject',
'                     , p_detail_pk                => coalesce(l_business_ref, flow_globals.business_ref) ',
'                     , p_parameters               => l_task_parameters',
'                     , p_initiator                => coalesce ( l_initiator',
'                                                        , sys_context(''apex$session'',''app_user'') ',
'                                                        , sys_context(''userenv'',''os_user'')',
'                                                        , sys_context(''userenv'',''session_user'')',
'                                                        ) ',
'                     , p_initiator_can_complete   => case l_initiator_can_complete ',
'                                                        when flow_constants_pkg.gc_vcbool_true then true',
'                                                        else null end',
'                     , p_priority                 => l_priority',
'                     , p_due_date                 => l_due_on',
'                     );',
'      apex_debug.info ',
'      ( p_message => ''APEX Human Task created - APEX Task Reference %0 created''',
'      , p0 => l_apex_task_id',
'      );  ',
'',
'      -- set the status to ''waiting for approval''',
'      update flow_subflows sbfl',
'         set sbfl.sbfl_last_update    = systimestamp',
'           , sbfl.sbfl_apex_task_id   = l_apex_task_id',
'           , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_waiting_approval',
'           , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                  , sys_context(''userenv'',''os_user'')',
'                                                  , sys_context(''userenv'',''session_user'')',
'                                                  )  ',
'       where sbfl.sbfl_id       = l_sbfl_id',
'         and sbfl.sbfl_prcs_id  = l_prcs_id',
'      ;',
'    exception',
'      when e_priority_invalid then',
'        apex_debug.info ',
'        ( p_message => '' --- Error creating Approval Task.  Priority should evaluate to number between 1 and 5.  Priority: %0''',
'        , p0 => l_priority',
'        );  ',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => l_prcs_id',
'        , pi_message_key    => ''apex-task-priority-error''',
'        , p0 => l_priority',
'        );  ',
'        -- $F4AMESSAGE ''apex-task-priority-error'' || ''Error creating APEX Human task - invalid priority %0.''    ',
'      when e_business_ref_null then',
'        apex_debug.info',
'        ( p_message => '' --- Error creating Approval Task - Business Ref / System of Record Primary Key must be not null.''',
'        );',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => l_prcs_id',
'        , pi_message_key    => ''apex-task-business-ref-null''',
'        );  ',
'        -- $F4AMESSAGE ''apex-task-business-ref-null'' || ''Error creating Approval Task - Business Ref / System of Record Primary Key must be not null.''             ',
'      when others then',
'        apex_debug.info ',
'        ( p_message => '' --- Error creating APEX Approval Task.  AppID %0 TaskStaticID %1 Subject %2 DetailPK %3 Initiator %4 Priority %5.''',
'        , p0 => l_app_id',
'        , p1 => l_static_id',
'        , p2 => l_subject',
'        , p3 => coalesce(l_business_ref, flow_globals.business_ref, null) ',
'        , p4 => l_initiator',
'        , p5 => l_priority',
'        );  ',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id        => l_prcs_id',
'        , pi_sbfl_id        => l_sbfl_id',
'        , pi_message_key    => ''apex-task-creation-error''',
'        , p0 => l_static_id',
'        , p1 => l_app_id',
'        );  ',
'        -- $F4AMESSAGE ''apex-task-creation-error'' || ''Error creating APEX Human Task %0 in application %1.  see debug for details.'' ',
'    end; ',
'      ',
'  end process_apex_approval_task;',
'',
'  function get_task_potential_owners',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_subflow_id    in flow_subflows.sbfl_id%type',
'  , p_step_key      in flow_subflows.sbfl_step_key%type',
'  , p_separator     in varchar2 default '',''',
'  ) return flow_process_variables.prov_var_vc2%type',
'  is',
'    l_potential_owners flow_process_variables.prov_var_vc2%type;',
'  begin',
'    select UPPER(sbfl.sbfl_potential_users)',
'      into l_potential_owners',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id     = p_subflow_id',
'       and sbfl.sbfl_step_key = p_step_key',
'    ;',
'    -- Flows for APEX uses default separator '':'' for potential owners',
'    -- but APEX uses '','' as separator for potential owners',
'',
'    -- so we need to replace '':'' with '','' in the potential owners string',
'    if l_potential_owners is not null and p_separator != '':'' then',
'      l_potential_owners := replace ( l_potential_owners,'':'', p_separator);',
'    end if;',
'',
'    return l_potential_owners;',
'  end get_task_potential_owners;',
'',
'  function get_task_business_admins',
'  ( p_process_id         in flow_processes.prcs_id%type',
'  , p_subflow_id         in flow_subflows.sbfl_id%type',
'  , p_step_key           in flow_subflows.sbfl_step_key%type',
'  , p_separator          in varchar2 default '',''',
'  , p_add_diagram_admin  in boolean default false',
'  , p_add_instance_admin in boolean default false',
'  ) return flow_process_variables.prov_var_vc2%type',
'    is',
'    l_business_admin flow_process_variables.prov_var_vc2%type;',
'    l_fallback_admin flow_process_variables.prov_var_vc2%type;',
'  begin',
'    select UPPER(sbfl.sbfl_apex_business_admin)',
'      into l_business_admin',
'      from flow_subflows sbfl',
'     where sbfl.sbfl_prcs_id = p_process_id',
'       and sbfl.sbfl_id     = p_subflow_id',
'       and sbfl.sbfl_step_key = p_step_key',
'    ;',
'    -- Flows for APEX uses default separator '':'' for business admins',
'    -- but APEX uses '','' as separator for business admins',
'',
'    -- so we need to replace '':'' with '','' in the business admins string',
'    if l_business_admin is not null and p_separator != '':'' then',
'      l_business_admin := replace ( l_business_admin,'':'', p_separator);',
'    end if;',
'',
'    if p_add_diagram_admin then',
'      -- add business admin defined in the current diagram to the list of business admins',
'        select objt.objt_attributes."apex"."businessAdmin"',
'          into l_fallback_admin',
'          from flow_objects objt',
'          join flow_diagrams dgrm',
'            on objt.objt_dgrm_id = dgrm.dgrm_id',
'          join flow_subflows sbfl',
'            on sbfl.sbfl_dgrm_id = dgrm.dgrm_id',
'         where sbfl.sbfl_prcs_id = p_process_id',
'           and objt.objt_tag_name = flow_constants_pkg.gc_bpmn_process',
'         fetch first row only',
'        ;',
'      if l_fallback_admin is not null then',
'        if l_business_admin is null then',
'          l_business_admin := l_fallback_admin;',
'        else',
'          l_business_admin := l_business_admin || p_separator || l_fallback_admin;',
'        end if;',
'      end if;',
'    end if;',
'',
'    if p_add_instance_admin then',
'      -- add business admin defined in the current instance to the list of business admins',
'      l_fallback_admin := flow_engine_util.get_config_value',
'                          ( p_config_key => flow_constants_pkg.gc_config_default_apex_business_admin',
'                          , p_default_value => null );',
'      if l_fallback_admin is not null then',
'        if l_business_admin is null then',
'          l_business_admin := l_fallback_admin;',
'        else',
'          l_business_admin := l_business_admin || p_separator || l_fallback_admin;',
'        end if;',
'      end if;',
'    end if;',
'',
'    return l_business_admin;',
'  end get_task_business_admins;',
'',
'  procedure schedule_background_task_cancelation',
'  ( p_process_id          in flow_processes.prcs_id%type',
'  , p_apex_task_id        in number ',
'  , p_apex_user           in flow_subflows.sbfl_apex_business_admin%type default null',
'  , p_app_id              in number',
'  , p_page_id             in number',
'  , p_objt_bpmn_id        in flow_objects.objt_bpmn_id%type',
'  ) ',
'  is',
'    l_job_name              varchar2(100);',
'  begin',
'    -- Generate a unique job name (optional but helpful)',
'    l_job_name := ''APEX_FLOW_CANCEL_APEX_TASK_J_'' || p_apex_task_id || ''_'' || p_apex_user || ''_'' || to_char(sysdate, ''YYYYMMDD_HH24MISS'');',
'  ',
'    -- Create the job (do NOT enable yet)',
'    sys.dbms_scheduler.create_job (',
'      job_name      => l_job_name,',
'      program_name  => ''APEX_FLOW_CANCEL_APEX_TASK_P'',',
'      start_date    => NULL,            -- don''t use scheduled start',
'      enabled       => FALSE,',
'      auto_drop     => TRUE             -- clean up after execution',
'    );',
'  ',
'    -- Set the argument values',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 1',
'                                          , argument_value => to_char(p_process_id)); -- p_process_id',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 2',
'                                          , argument_value => to_char(p_apex_task_id)); -- p_apex_task_id',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 3',
'                                          , argument_value => p_apex_user);-- p_apex_user',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 4',
'                                          , argument_value => to_char(p_app_id)); -- p_app_id',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 5',
'                                          , argument_value => to_char(p_page_id)); -- p_page_id',
'    sys.dbms_scheduler.set_job_argument_value ( job_name => l_job_name',
'                                          , argument_position => 6',
'                                          , argument_value => p_objt_bpmn_id);  -- p_objt_bpmn_id',
'  ',
'    -- Run the job immediately',
'    sys.dbms_scheduler.run_job(l_job_name, use_current_session => FALSE);  -- TRUE = sync; FALSE = async',
'                ',
'  end schedule_background_task_cancelation;',
'',
'  procedure cancel_apex_task',
'    ( p_process_id          in flow_processes.prcs_id%type',
'    , p_subflow_id          in flow_subflows.sbfl_id%type',
'    , p_objt_bpmn_id        in flow_objects.objt_bpmn_id%type',
'    , p_apex_task_id        in number    ',
'    , p_apex_business_admin in flow_subflows.sbfl_apex_business_admin%type default null',
'    )',
'  is',
'    l_is_allowed            boolean;',
'    l_task_initiator        apex_tasks.initiator%type;',
'    l_business_admins       apex_t_varchar2;',
'    l_business_admin        varchar2(255);',
'    l_job_name              varchar2(100);',
'  begin',
'    apex_debug.enter ',
'    ( ''cancel_apex_task''',
'    , ''subflow_id: '', p_subflow_id',
'    , ''apex task_id: '', p_apex_task_id ',
'    , ''apex business admin: '', p_apex_business_admin ',
'    );',
'    -- update subflow status to show its being canceled',
'    update flow_subflows sbfl',
'       set sbfl.sbfl_last_update    = systimestamp',
'         , sbfl.sbfl_status         = flow_constants_pkg.gc_sbfl_status_canceling_task',
'         , sbfl.sbfl_last_update_by = coalesce  ( sys_context(''apex$session'',''app_user'') ',
'                                                , sys_context(''userenv'',''os_user'')',
'                                                , sys_context(''userenv'',''session_user'')',
'                                                )  ',
'     where sbfl.sbfl_id       = p_subflow_id',
'       and sbfl.sbfl_prcs_id  = p_process_id',
'       and sbfl.sbfl_status    = flow_constants_pkg.gc_sbfl_status_waiting_approval',
'    ;',
'    -- check if current user is allowed  to cancel the task',
'    l_is_allowed := apex_human_task.is_allowed',
'      ( p_task_id         => p_apex_task_id',
'      , p_operation       => apex_human_task.c_task_op_cancel',
'      );',
'    if l_is_allowed then',
'      apex_debug.info ',
'      ( p_message => ''...Current  user can delete APEX Human Task : %0  - cancelling now ...''',
'      , p0 => p_apex_task_id',
'      );',
'      apex_human_task.cancel_task (p_task_id => p_apex_task_id);',
'    elsif p_apex_business_admin is not null then',
'      apex_debug.info ',
'      ( p_message => ''...Current  user cannot delete APEX Human Task : %0  - user dbms_scheduler job to cancel ...''',
'      , p0 => p_apex_task_id',
'      );',
'      -- start with business admins recorded on the subflow',
'      l_business_admins := apex_string.split ( p_str => p_apex_business_admin',
'                                             , p_sep => '':''',
'                                             );',
'      for i in 1 .. l_business_admins.count loop',
'        l_business_admin := l_business_admins(i);',
'        if l_business_admin is not null then',
'          -- check if the business admin is allowed to cancel the task',
'          l_is_allowed := apex_human_task.is_allowed',
'            ( p_task_id         => p_apex_task_id',
'            , p_operation       => apex_human_task.c_task_op_cancel',
'            , p_user            => l_business_admin',
'            );',
'          if l_is_allowed then ',
'            apex_debug.info ',
'            ( p_message => ''...Business Admin %0 can delete APEX Human Task : %1  - schedule cancelation...''',
'            , p0 => l_business_admin',
'            , p1 => p_apex_task_id',
'            );',
'            schedule_background_task_cancelation',
'              ( p_process_id          => p_process_id',
'              , p_apex_task_id        => p_apex_task_id',
'              , p_apex_user           => l_business_admin',
'              , p_app_id              => coalesce ( sys_context(''apex$session'',''app_id'')',
'                                                  , flow_engine_util.get_config_value ',
'                                                         ( p_config_key => flow_constants_pkg.gc_config_default_application',
'                                                         , p_default_value => null)',
'                                                  )',
'              , p_page_id             => coalesce ( sys_context(''apex$session'',''app_page_id'')',
'                                                  , flow_engine_util.get_config_value ',
'                                                         ( p_config_key => flow_constants_pkg.gc_config_default_pageid ',
'                                                         , p_default_value => null)',
'                                                  )',
'              , p_objt_bpmn_id        => p_objt_bpmn_id',
'              );',
'            continue;',
'          end if; -- business admin allowed to cancel task',
'        end if; -- bus admin not null  ',
'      end loop;',
'    else -- last chance to cancel the task - do it as the task originator',
'      -- get the task initiator.  ',
'      select task.initiator',
'        into l_task_initiator',
'        from apex_tasks task',
'       where task.task_id = p_a'))
);
wwv_flow_imp_shared.append_to_install_script(
 p_id=>wwv_flow_imp.id(30434682229468687)
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'pex_task_id;  ',
'',
'      apex_debug.info ',
'      ( p_message => ''...Task Originator %0 deleting APEX Human Task : %1  - scheduling cancel job now ...''',
'      , p0 => l_task_initiator',
'      , p1 => p_apex_task_id',
'      );',
'      schedule_background_task_cancelation',
'        ( p_process_id          => p_process_id',
'        , p_apex_task_id        => p_apex_task_id',
'        , p_apex_user           => l_task_initiator',
'        , p_app_id              => coalesce ( sys_context(''apex$session'',''app_id'')',
'                                            , flow_engine_util.get_config_value ',
'                                                   ( p_config_key => flow_constants_pkg.gc_config_default_application',
'                                                   , p_default_value => null)',
'                                            )',
'        , p_page_id             => coalesce ( sys_context(''apex$session'',''app_page_id'')',
'                                            , flow_engine_util.get_config_value ',
'                                                   ( p_config_key => flow_constants_pkg.gc_config_default_pageid ',
'                                                   , p_default_value => null)',
'                                            )',
'        , p_objt_bpmn_id        => p_objt_bpmn_id',
'        );',
'    end if;',
'  end cancel_apex_task;',
'',
'  procedure cancel_all_apex_tasks',
'  ( p_process_id          in flow_processes.prcs_id%type',
'  )',
'  is',
'  begin',
'    apex_debug.enter ',
'    ( ''cancel_all_apex_tasks''',
'    , ''process_id: '', p_process_id ',
'    );',
'    for current_apex_tasks in ',
'            (',
'            select sbfl.sbfl_apex_task_id',
'                 , sbfl.sbfl_id',
'                 , sbfl.sbfl_current',
'                 , sbfl.sbfl_apex_business_admin',
'              from flow_subflows sbfl',
'             where sbfl.sbfl_prcs_id = p_process_id',
'               and sbfl.sbfl_apex_task_id is not null',
'               and sbfl.sbfl_status = flow_constants_pkg.gc_sbfl_status_waiting_approval',
'            )',
'    loop',
'      cancel_apex_task ',
'        ( p_process_id          => p_process_id',
'        , p_subflow_id          => current_apex_tasks.sbfl_id',
'        , p_objt_bpmn_id        => current_apex_tasks.sbfl_current',
'        , p_apex_task_id        => current_apex_tasks.sbfl_apex_task_id',
'        , p_apex_business_admin => current_apex_tasks.sbfl_apex_business_admin',
'        );',
'      apex_debug.info ',
'      ( p_message => ''APEX Human Task : %0  canceled or scheduled for background cancelation on object : %1  by bus admin : %2''',
'      , p0 => current_apex_tasks.sbfl_apex_task_id  ',
'      , p1 => current_apex_tasks.sbfl_current',
'      , p2 => current_apex_tasks.sbfl_apex_business_admin',
'      );',
'    end loop;',
'    apex_debug.info ',
'    ( p_message => ''APEX Human Task : All tasks cancelled or scheduled for background cancelation for process : %0''',
'    , p0 => p_process_id',
'    );  ',
'',
'  end cancel_all_apex_tasks;',
'',
'',
'  procedure cancel_apex_task_from_scheduler',
'  ( p_process_id          in varchar2',
'  , p_apex_task_id        in varchar2 ',
'  , p_apex_user           in varchar2',
'  , p_app_id              in varchar2',
'  , p_page_id             in varchar2',
'  , p_objt_bpmn_id        in varchar2 default null',
'  )',
'  is',
'    l_objt_bpmn_id        flow_objects.objt_bpmn_id%type;',
'    l_session_id          number;',
'    l_process_id          flow_processes.prcs_id%type := to_number(p_process_id);',
'    l_apex_task_id        number := to_number(p_apex_task_id);  ',
'    l_app_id              number := to_number(p_app_id);',
'    l_page_id             number := to_number(p_page_id);',
'  begin',
'    -- create apex session ',
'    apex_session.create_session',
'      ( p_app_id        => l_app_id',
'      , p_page_id       => l_page_id',
'      , p_username      => p_apex_user',
'      );',
'    apex_debug.enter ',
'        ( ''cancel_apex_task_from_scheduler''',
'        , ''apex task_id: '', l_apex_task_id',
'        , ''apex user: '', p_apex_user',
'        );',
'    -- cancel the  task',
'    begin',
'      apex_human_task.cancel_task (p_task_id => l_apex_task_id);',
'      apex_debug.info ',
'      ( p_message => ''APEX Human Task : %0  canceled on object : %1''',
'      , p0 => l_apex_task_id',
'      , p1 => p_objt_bpmn_id',
'      );',
'    exception',
'      when others then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => l_process_id',
'        , pi_message_key => ''apex-task-cancelation-error''',
'        , p0 => p_objt_bpmn_id',
'        , p1 => l_apex_task_id',
'        , p2 => sqlerrm',
'        , p3 => sys_context(''apex$session'',''app_session'')',
'        );',
'        -- $F4AMESSAGE ''apex-task-cancelation-error'' || ''Error attempting to cancel APEX workflow task (task_id: %1 ) for process step : %0.)''',
'    end; ',
'  end cancel_apex_task_from_scheduler;',
'',
'  procedure return_approval_result',
'  ( p_process_id    in flow_processes.prcs_id%type',
'  , p_apex_task_id  in number',
'  , p_result        in flow_process_variables.prov_var_vc2%type default null',
'  )',
'  is',
'    l_sbfl_id             flow_subflows.sbfl_id%type;',
'    l_dgrm_id             flow_subflows.sbfl_dgrm_id%type;',
'    l_current_bpmn_id     flow_objects.objt_bpmn_id%type;',
'    l_scope               flow_subflows.sbfl_scope%type;',
'    l_step_key            flow_subflows.sbfl_step_key%type;',
'    l_var_name            flow_process_variables.prov_var_name%type;',
'    l_potential_current   flow_objects.objt_bpmn_id%type;',
'    l_result_var          flow_process_variables.prov_var_name%type;',
'    e_task_id_proc_var_not_found  exception;',
'    e_task_id_duplicate_found     exception;',
'    e_task_not_current_step       exception;',
'    e_task_no_return_var          exception;',
'  begin',
'    apex_debug.enter',
'    (p_routine_name => ''return_approval_result''',
'    );',
'    begin',
'      -- find and lock the subflow',
'      select sbfl.sbfl_id',
'           , sbfl.sbfl_step_key',
'           , sbfl.sbfl_dgrm_id',
'           , sbfl.sbfl_scope',
'           , sbfl.sbfl_current',
'        into l_sbfl_id',
'           , l_step_key',
'           , l_dgrm_id',
'           , l_scope',
'           , l_current_bpmn_id ',
'        from flow_subflows sbfl',
'       where sbfl.sbfl_prcs_id = p_process_id',
'         and sbfl.sbfl_apex_task_id = p_apex_task_id',
'      for update of sbfl.sbfl_step_key wait 5;',
'    exception',
'      when no_data_found then',
'        raise e_task_not_current_step;',
'      when too_many_rows then',
'        raise e_task_id_duplicate_found;',
'      when e_lock_timeout then',
'        raise e_lock_timeout;',
'    end;',
'    apex_debug.info ',
'    ( p_message => ''--- Returning Approval Outcome - Found Subflow %0 step Key %1 Diagram %2''',
'    , p0 => l_sbfl_id',
'    , p1 => l_step_key',
'    , p2 => l_dgrm_id',
'    );',
'    -- get name of return variable',
'    begin',
'      select objt.objt_attributes."apex"."resultVariable"',
'        into l_result_var',
'        from flow_objects objt',
'       where objt.objt_bpmn_id = l_current_bpmn_id ',
'         and objt.objt_dgrm_id = l_dgrm_id;',
'      apex_debug.info ',
'      ( p_message => ''--- Returning Approval Outcome - Found result variable id %0''',
'      , p0 => l_result_var',
'      );',
'    exception',
'      when no_data_found then',
'        raise e_task_no_return_var;',
'    end;',
'    -- create result variable',
'    flow_proc_vars_int.set_var',
'     ( pi_prcs_id       => p_process_id',
'     , pi_var_name      => l_result_var',
'     , pi_scope         => l_scope',
'     , pi_vc2_value     => p_result',
'     , pi_sbfl_id       => l_sbfl_id',
'     , pi_objt_bpmn_id  => l_potential_current',
'     );',
'    -- do next step',
'    flow_engine.flow_complete_step',
'      ( p_process_id    => p_process_id',
'      , p_subflow_id    => l_sbfl_id',
'      , p_step_key      => l_step_key',
'      );',
'  exception',
'    when e_lock_timeout then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => l_sbfl_id',
'      , pi_message_key => ''timeout_locking_subflow''',
'      , p0 => l_sbfl_id',
'      );',
'      -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''',
'    when e_task_id_proc_var_not_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => l_sbfl_id',
'      , pi_message_key => ''apex-task-not-found''',
'      , p0 => p_apex_task_id ',
'      );',
'      -- $F4AMESSAGE ''apex-task-not-found'' || ''APEX Human Task %0 not found in Flows for APEX Process''',
'    when e_task_id_duplicate_found then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => l_sbfl_id',
'      , pi_message_key => ''apex-task-on-multiple-steps''',
'      , p0 => p_apex_task_id',
'      );',
'      -- $F4AMESSAGE ''apex-task-on-multiple-steps'' || ''APEX Human Task %0 found associated with more than one Flows for APEX process step.''',
'    when e_task_not_current_step then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => l_sbfl_id',
'      , pi_message_key => ''apex-task-not-current-step''',
'      , p0 => p_apex_task_id',
'      );',
'      -- $F4AMESSAGE ''apex-task-not-current-step'' || ''APEX Human Task %0 is not the current step in Flows for APEX Process.''',
'    when e_task_no_return_var then',
'      flow_errors.handle_instance_error',
'      ( pi_prcs_id     => p_process_id',
'      , pi_sbfl_id     => l_sbfl_id',
'      , pi_message_key => ''apex-task-invalid-return-var''',
'      , p0 => p_apex_task_id',
'      );      ',
'      -- $F4AMESSAGE ''apex-task-invalid-return-var'' || ''APEX Human Task result process variable is not defined or invalid.''',
'  end return_approval_result;',
'',
'  procedure return_task_state_outcome',
'    ( p_process_id    in flow_processes.prcs_id%type',
'    , p_subflow_id    in flow_subflows.sbfl_id%type',
'    , p_step_key      in flow_subflows.sbfl_step_key%type',
'    , p_apex_task_id  in number',
'    , p_state_code    in apex_tasks.state_code%type ',
'    , p_outcome       in flow_process_variables.prov_var_vc2%type default null',
'    )',
'    is',
'      l_sbfl_rec                     flow_subflows%rowtype;',
'      l_var_name                     flow_process_variables.prov_var_name%type;',
'      l_result_var                   flow_process_variables.prov_var_name%type;',
'      l_cancelled_task_not_current   boolean := false;',
'      l_do_next_step                 boolean := false;',
'',
'      e_task_id_not_found           exception;',
'      e_task_id_duplicate_found     exception;',
'      e_task_not_current_step       exception;',
'      e_task_no_return_var          exception;',
'    begin',
'      apex_debug.enter',
'      ( ''return_task_state_outcome''',
'      , ''APEX task id: '', p_apex_task_id',
'      , ''outcome: '', p_outcome',
'      , ''state_code: '', p_state_code',
'      );',
'',
'      flow_globals.set_is_recursive_step (true);',
'      ',
'      -- uncomment to debug expirations - log into F4A instance log if this is an expiration',
'      --  flow_logging.log_step_event',
'      --  ( p_process_id => p_process_id',
'      --  , p_subflow_id => p_subflow_id',
'      --  , p_event => flow_constants_pkg.gc_step_event_expired',
'      --  , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'      --  , p_comment => ''APEX Human Task : '' || p_apex_task_id || '' state: ''||p_state_code||'' - entering return_task_state_outcome''',
'      --  );',
'',
'      begin',
'        -- find and lock the subflow',
'        select sbfl.*',
'          into l_sbfl_rec',
'          from flow_subflows sbfl',
'         where sbfl.sbfl_prcs_id      = p_process_id',
'           and sbfl.sbfl_id           = p_subflow_id',
'           and sbfl.sbfl_step_key     = p_step_key',
'           and sbfl.sbfl_apex_task_id = p_apex_task_id',
'        for update of sbfl.sbfl_step_key wait 5;',
'      exception',
'        when no_data_found then',
'          if p_state_code = apex_human_task.c_task_state_cancelled then',
'            -- task already cancelled in Flows - do nothing',
'            l_cancelled_task_not_current := true;',
'          else',
'            raise e_task_id_not_found;',
'          end if;',
'        when too_many_rows then',
'          raise e_task_id_duplicate_found;',
'        when e_lock_timeout then',
'          raise e_lock_timeout;',
'      end;',
'      apex_debug.info ',
'      ( p_message => ''--- Returning Approval Outcome - Found  Diagram %0''',
'      , p0 => l_sbfl_rec.sbfl_dgrm_id',
'      );',
'      -- un-comment to debug task expiration',
'      -- flow_logging.log_step_event',
'      --   ( p_process_id => p_process_id',
'      --   , p_subflow_id => p_subflow_id',
'      --   , p_event => flow_constants_pkg.gc_step_event_expired',
'      --   , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'      --   , p_comment => ''Found Diagram and subflow ''',
'      --   );',
'      if p_outcome is not null then',
'        -- get name of return variable',
'        begin',
'          select objt.objt_attributes."apex"."resultVariable"',
'            into l_result_var',
'            from flow_objects objt',
'           where objt.objt_bpmn_id = l_sbfl_rec.sbfl_current',
'             and objt.objt_dgrm_id = l_sbfl_rec.sbfl_dgrm_id;',
'          apex_debug.info ',
'          ( p_message => ''--- Returning Approval Outcome - Found result variable id %0''',
'          , p0 => l_result_var',
'          );',
'        exception',
'          when no_data_found then',
'            raise e_task_no_return_var;',
'        end;',
'  ',
'        -- create result variable',
'        flow_proc_vars_int.set_var',
'         ( pi_prcs_id       => p_process_id',
'         , pi_var_name      => l_result_var',
'         , pi_scope         => l_sbfl_rec.sbfl_scope',
'         , pi_vc2_value     => p_outcome',
'         , pi_sbfl_id       => p_subflow_id',
'         , pi_objt_bpmn_id  => l_sbfl_rec.sbfl_current',
'         );',
'      end if;',
'      case p_state_code',
'        when apex_human_task.c_task_state_cancelled then',
'          -- cancel task',
'          if l_cancelled_task_not_current then',
'            apex_debug.info ',
'            ( p_message => ''APEX Human Task : %0  already cancelled - not current task or subflow already deleted''',
'            , p0 => p_apex_task_id',
'            );',
'          elsif l_sbfl_rec.sbfl_status = flow_constants_pkg.gc_sbfl_status_canceling_task then',
'            apex_debug.info ',
'            ( p_message => ''APEX Human Task : %0  previously set to be canceled by Flows - task now cancelled''',
'            , p0 => p_apex_task_id',
'            );',
'          else',
'            -- task cancelled by initiator or business admin from APEX',
'            apex_debug.info ',
'            ( p_message => ''APEX Human Task : %0  cancelled on object : %1 from APEX - doing next step'' ',
'            , p0 => p_apex_task_id',
'            , p1 => l_sbfl_rec.sbfl_current',
'            );',
'            flow_logging.log_step_event',
'            ( p_sbfl_rec => l_sbfl_rec',
'            , p_event => flow_constants_pkg.gc_step_event_cancelled',
'            , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'            );  ',
'            l_do_next_step := true;',
'          end if;',
'        when apex_human_task.c_task_state_completed then',
'          -- complete task',
'          l_do_next_step := true;',
'        when apex_human_task.c_task_state_errored then',
'          -- error task action not yet implemented as of APEX 24.2. Code here for future...        ',
'          -- error task',
'          flow_logging.log_step_event',
'          ( p_sbfl_rec => l_sbfl_rec',
'          , p_event => flow_constants_pkg.gc_step_event_error',
'          , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'          );  ',
'          l_do_next_step := true; --TODO Change this to allow step restart',
'        when apex_human_task.c_task_state_expired then',
'          -- APEX bug in APEX <= 24.2.7 means that state_code for an expired task is not set to ''EXPIRED'' but to its previous state.',
'          -- use of the plugin in APEX versions with this bug will result in expirations not getting returned wit status of ''EXPIRED''',
'          -- users should use ''execute pl/sql'' in place of the plugin.  p_state_code must be manually set to ''EXPIRED'' in that case.',
'          -- expire task',
'          flow_logging.log_step_event',
'          ( p_sbfl_rec => l_sbfl_rec',
'          , p_event => flow_constants_pkg.gc_step_event_expired',
'          , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'          );   ',
'          -- uncomment to debug ',
'          -- flow_logging.log_step_event',
'          -- ( p_process_id => p_process_id',
'          -- , p_subflow_id => p_subflow_id',
'          -- , p_event => flow_constants_pkg.gc_step_event_expired',
'          -- , p_event_level => flow_constants_pkg.gc_logging_level_abnormal_events',
'          -- , p_comment => ''setting do next step''',
'          -- );',
'          l_do_next_step := true; ',
'        else   ',
'          null;',
'      end case;',
'',
'      if l_do_next_step then      ',
'        -- do next step',
'        flow_engine.flow_complete_step',
'          ( p_process_id    => p_process_id',
'          , p_subflow_id    => p_subflow_id',
'          , p_step_key      => p_step_key',
'          );',
'      end if;',
'    exception',
'      when e_lock_timeout then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''timeout_locking_subflow''',
'        , p0 => p_subflow_id',
'        );',
'        -- $F4AMESSAGE ''timeout_locking_subflow'' || ''Unable to lock subflow %0 as currently locked by another user.  Try again later.''',
'      when e_task_id_not_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''apex-task-not-found''',
'        , p0 => p_apex_task_id ',
'        );',
'        -- $F4AMESSAGE ''apex-task-not-found'' || ''APEX Human Task %0 not found in Flows for APEX Process''',
'      when e_task_id_duplicate_found then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''apex-task-on-multiple-steps''',
'        , p0 => p_apex_task_id',
'        );',
'        -- $F4AMESSAGE ''apex-task-on-multiple-steps'' || ''APEX Human Task %0 found associated with more than one Flows for APEX process step.''',
'      when e_task_not_current_step then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''apex-task-not-current-step''',
'        , p0 => p_apex_task_id',
'        );',
'        -- $F4AMESSAGE ''apex-task-not-current-step'' || ''APEX Human Task %0 is not the current step of the Process.  Step may have completed all ready.''',
'      when e_task_no_return_var then',
'        flow_errors.handle_instance_error',
'        ( pi_prcs_id     => p_process_id',
'        , pi_sbfl_id     => p_subflow_id',
'        , pi_message_key => ''apex-task-invalid-return-var''',
'        , p0 => p_apex_task_id',
'        );      ',
'        -- $F4AMESSAGE ''apex-task-invalid-return-var'' || ''APEX Human Task %0 is missing a return variable.''',
'    end return_task_state_outcome;',
'',
'end flow_usertask_pkg;',
'/',
'',
'create or replace package body flow_engine_app_api',
'as',
'',
'  function apex_error_handling (',
'    p_error in apex_error.t_error ',
'  )',
'  return apex_error.t_error_result',
'  is',
'    l_result          apex_error.t_error_result;',
'    l_reference_id    number;',
'    l_constraint_name varchar2(255);',
'  begin',
'    l_result := apex_error.init_error_result (',
'                    p_error => p_error );',
'                    ',
'    -- If it''s an internal error raised by APEX, like an invalid statement or',
'    -- code which can''t be executed, the error text might contain security sensitive',
'    -- information. To avoid this security problem we can rewrite the error to',
'    -- a generic error message and log the original error message for further',
'    -- investigation by the help desk.',
'    if p_error.is_internal_error then',
'      -- mask all errors that are not common runtime errors (Access Denied',
'      -- errors raised by application / page authorization and all errors',
'      -- regarding session and session state)',
'      if not p_error.is_common_runtime_error then',
'        -- log error for example with an autonomous transaction and return',
'        -- l_reference_id as reference#',
'        -- l_reference_id := log_error (',
'        --                       p_error => p_error );',
'        --',
'',
'        -- Change the message to the generic error message which doesn''t expose',
'        -- any sensitive information.',
'        l_result.message         := ''An unexpected internal application error has occurred. ''||',
'                                    ''Please fill a bug at  https://github.com/flowsforapex/apex-flowsforapex/issues''||',
'                                    '' for further investigation.'';',
'        l_result.additional_info := null;',
'      end if;',
'    else',
'      -- Note: If you want to have friendlier ORA error messages, you can also define',
'      --       a text message with the name pattern APEX.ERROR.ORA-number',
'      --       There is no need to implement custom code for that.',
'',
'      -- If it''s a constraint violation like',
'      --',
'      --   -) ORA-00001: unique constraint violated',
'      --   -) ORA-02091: transaction rolled back (-> can hide a deferred constraint)',
'      --   -) ORA-02290: check constraint violated',
'      --   -) ORA-02291: integrity constraint violated - parent key not found',
'      --   -) ORA-02292: integrity constraint violated - child record found',
'      --',
'      -- we try to get a friendly error message from APEX Text Messages.',
'      -- If we don''t find the constraint in APEX text message then create it',
'      if p_error.ora_sqlcode in (-1, -2091, -2290, -2291, -2292) then',
'        l_constraint_name := apex_error.extract_constraint_name (',
'                                   p_error => p_error );',
'',
'        l_result.message := apex_lang.message( l_constraint_name );',
'',
'      end if;',
'',
'      -- If no associated page item/tabular form column has been set, we can use',
'      -- apex_error.auto_set_associated_item to automatically guess the affected',
'      -- error field by examine the ORA error for constraint names or column names.',
'      if l_result.page_item_name is null and l_result.column_alias is null then',
'          apex_error.auto_set_associated_item (',
'              p_error        => p_error,',
'              p_error_result => l_result );',
'      end if;',
'    end if;',
'',
'    return l_result;',
'  end apex_error_handling;',
'',
'  procedure handle_ajax',
'  as ',
'    l_error_occured boolean := false;',
'    l_url           varchar2(4000);',
'    l_clob          clob;',
'    l_before_prcs_status flow_instances_vw.prcs_status%type;',
'    l_after_prcs_status flow_instances_vw.prcs_status%type;',
'    l_reload boolean := false;',
'',
'  begin',
'    apex_debug.message( p_message => ''Action: %s'', p0 => apex_application.g_x01 );',
'    if instr(apex_application.g_x01, ''bulk-'') > 0 then',
'      apex_debug.message( p_message => ''This is a bulk action'');',
'      if ( upper(apex_application.g_x01) = ''BULK-COMPLETE-STEP'' or upper(apex_application.g_x01) = ''BULK-RESTART-STEP'' ) then',
'        select prcs_status',
'        into l_before_prcs_status',
'        from flow_instances_vw',
'        where prcs_id = apex_application.g_f01(1);',
'      end if;',
'      for i in apex_application.g_f01.first..apex_application.g_f01.last',
'      loop',
'        apex_debug.message( p_message => ''Action: %s, PRCS: %s'', p0 => apex_application.g_x01, p1 => apex_application.g_f01(i) );',
'        case upper(apex_application.g_x01)',
'          when ''BULK-RESET-FLOW-INSTANCE'' then',
'            flow_api_pkg.flow_reset( p_process_id => apex_application.g_f01(i), p_comment => apex_application.g_x02 );',
'          when ''BULK-START-FLOW-INSTANCE'' then',
'            flow_api_pkg.flow_start( p_process_id => apex_application.g_f01(i) );',
'          when ''BULK-DELETE-FLOW-INSTANCE'' then',
'            flow_api_pkg.flow_delete( p_process_id => apex_application.g_f01(i), p_comment => apex_application.g_x02 );',
'          when ''BULK-TERMINATE-FLOW-INSTANCE'' then ',
'            flow_api_pkg.flow_terminate ( p_process_id => apex_application.g_f01(i), p_comment => apex_application.g_x02 );',
'          when ''BULK-RESERVE-STEP'' then',
'            flow_api_pkg.flow_reserve_step',
'            (',
'              p_process_id => apex_application.g_f01(i)',
'            , p_subflow_id => apex_application.g_f02(i)',
'            , p_step_key   => apex_application.g_f03(i)',
'            , p_reservation => coalesce(apex_application.g_x02, V(''APP_USER''))',
'            );',
'          when ''BULK-RELEASE-STEP'' then',
'            flow_api_pkg.flow_release_step',
'            (',
'              p_process_id => apex_application.g_f01(i)',
'            , p_subflow_id => apex_application.g_f02(i)',
'            , p_step_key   => apex_application.g_f03(i)',
'            );        ',
'          when ''BULK-COMPLETE-STEP'' then',
'            flow_api_pkg.flow_complete_step',
'            (',
'              p_process_id => apex_application.g_f01(i)',
'            , p_subflow_id => apex_application.g_f02(i)',
'            , p_step_key   => apex_application.g_f03(i)',
'            );',
'          when ''BULK-RESTART-STEP'' then ',
'            flow_api_pkg.flow_restart_step ',
'            (',
'              p_process_id => apex_application.g_f01(i)',
'            , p_subflow_id => apex_application.g_f02(i)',
'            , p_step_key   => apex_application.g_f03(i)',
'            , p_comment       => apex_application.g_x02           ',
'            );',
'          when ''BULK-DELETE-PROCESS-VARIABLE'' then ',
'            flow_process_vars.delete_var(',
'              pi_prcs_id  => apex_application.g_f01(i)',
'            , pi_var_name => apex_application.g_f02(i)',
'            , pi_scope    => apex_application.g_f03(i)',
'          );',
'          when ''BULK-RESCHEDULE-TIMER'' then',
'          flow_api_pkg.flow_reschedule_timer(',
