'      select dgrm_name|| '' - '' || pi_new_name',
'        into l_dgrm_name',
'        from flow_diagrams ',
'       where dgrm_id = l_flows(i);',
'',
'      if check_flow_exists(l_dgrm_name, ''0'') then',
