'  /* page 3 */',
'  function check_version_mismatch(',
'    p_app_id number default apex_application.g_flow_id',
'  ) return varchar2',
'  is',
'    l_app_version       apex_applications.version%type;',
'    l_datamodel_version flow_configuration.cfig_value%type;',
'    l_code_version      varchar2(10) := flow_constants_pkg.gc_version;',
'    l_message           varchar2(4000);',
'  begin',
'    select version',
'    into l_app_version',
'    from apex_applications',
'    where application_id = p_app_id;',
'   ',
'    select cfig_value',
'    into l_datamodel_version',
'    from flow_configuration',
'    where cfig_key = ''version_now_installed'';',
'   ',
'    if (( l_app_version = l_datamodel_version )  and ( l_datamodel_version = l_code_version )) = false then',
'        l_message := apex_lang.message(',
'            p_name => ''APP_VERSION_MISMATCH'',',
'            p0     => l_app_version,',
'            p1     => l_datamodel_version,',
'            p2     => l_code_version',
'        );',
'    end if;',
'',
'    return l_message;',
'',
'  end check_version_mismatch;',
'',
'  function check_apex_upgrade(',
'    p_app_id number default apex_application.g_flow_id',
'  ) return varchar2',
'  is',
'    l_actual_version pls_integer;',
'    l_actual_release pls_integer;',
'    l_stored_version pls_integer := flow_apex_env.version;',
'    l_stored_release pls_integer := flow_apex_env.release;',
'    l_message        varchar2(4000);',
'  begin',
'    select  ',
'         to_number(substr(version_no, 1, instr(version_no, ''.'', 1, 1) - 1))',
'       , to_number(substr(version_no, instr(version_no, ''.'', 1, 1) + 1, instr(version_no, ''.'', 1, 1) - 2))',
'    into l_actual_version, l_actual_release',
'    from apex_release;',
'',
'    if (( l_actual_version = l_stored_version ) and ( l_actual_release = l_stored_release )) = false then',
'        l_message := apex_lang.message(',
'            p_name => ''APP_APEX_UPGRADE_DETECTED'',',
'            p0     => l_actual_version,',
'            p1     => l_actual_release,',
'            p2     => l_stored_version,',
'            p3     => l_stored_release',
'        );',
'    end if;',
'',
'    return l_message;',
'',
'  end check_apex_upgrade;',
'',
'  function flow_apex_automation_disabled(',
'    p_app_id number default apex_application.g_flow_id',
'  ) return boolean',
'  is',
'    l_cnt number;',
'  begin',
'    select count(*)',
'      into l_cnt',
'      from apex_appl_automations  ',
'     where application_id = p_app_id',
'       and static_id like ''flows-for-apex-%''',
'       and trigger_type_code = ''POLLING''',
'       and polling_status_code = ''DISABLED'';',
'',
'    return (l_cnt > 0);',
'  end flow_apex_automation_disabled;',
'',
'',
'  function flow_apex_automation_failure(',
'    p_app_id number default apex_application.g_flow_id',
'  ) return boolean',
'  is',
'    l_cnt number;',
'  begin',
'    with automation_log as (',
'      select a.static_id',
'           , l.status_code',
'           , start_timestamp',
'           , row_number() over(partition by a.static_id order by start_timestamp desc) as rn',
'        from apex_appl_automations	a',
'        join apex_automation_log l  ',
'          on l.automation_id  = a.automation_id ',
'         and l.application_id = a.application_id',
'       where a.application_id = p_app_id',
'         and a.static_id like ''flows-for-apex-%''',
'         and a.trigger_type_code = ''POLLING''',
'    )',
'    select count(*)',
'      into l_cnt',
'      from automation_log',
'      where rn = 1',
'        and status_code = ''FAILURE''',
'    ;',
'',
'    return (l_cnt > 0);',
'  ',
'  end flow_apex_automation_failure;',
'',
