'    l_buffer := l_buffer||''    pi_dgrm_content => l_dgrm_content''||utl_tcp.crlf||'');''||utl_tcp.crlf;',
'    l_buffer := l_buffer||''end;''||utl_tcp.crlf||''/''||utl_tcp.crlf;',
'    dbms_lob.writeappend(l_sql, length(l_buffer), l_buffer);',
