'                     case l_prov_var_type',
'                        when ''DATE'' ',
'                           then coalesce( l_items ( l_item_name ).format_mask, v(''APP_NLS_DATE_FORMAT'') )',
'                     else',
'                        l_items ( l_item_name ).format_mask',
'                     end;',
'            end;',
'            ',
'            case l_prov_var_type ',
'               when ''VARCHAR2'' then',
'                  apex_debug.info(',
'                     p_message => ''......Name: %s - Type: %s - Value %s''',
'                     , p0 => l_prov_var_name',
'                     , p1 => l_prov_var_type',
'                     , p2 => case l_attribute4',
