'      ,q''[    <bpmn:exclusiveGateway id="Gateway_19h24z4">]''',
'      ,q''[      <bpmn:incoming>Flow_1j0axlj</bpmn:incoming>]''',
'      ,q''[      <bpmn:incoming>Flow_1txhooo</bpmn:incoming>]''',
