prompt --application/deployment/install/install_engine_messages_english
begin
wwv_flow_imp_shared.create_install_script(
 p_id=>wwv_flow_imp.id(30435440050476106)
,p_install_id=>wwv_flow_imp.id(30210531648852655)
,p_name=>'Engine Messages - English'
,p_sequence=>80
,p_script_type=>'INSTALL'
,p_script_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/*',
'-- Flows for APEX - engine_messages_en.sql',
'--',
'-- Engine Messages for language code "en"',
'--',
'-- Generated by language-load-generator',
'-- Generated on Mon, 26 Jun 2023 15:38:36 GMT',
'*/',
'',
'set define ''^''',
'whenever sqlerror exit rollback;',
'',
'-- Keep message reload deterministic on Autonomous DB.',
'begin',
'  execute immediate ''alter session disable parallel dml'';',
'exception',
'  when others then',
'    -- ignore where unsupported, e.g. XE / older versions',
'    null;',
'end;',
'/',
'',
'PROMPT >> Loading Engine Messages for Language "en"',
'declare',
'  c_load_lang constant varchar2(10) := ''en'';',
'begin',
'  delete',
'    from flow_messages',
'   where fmsg_lang = c_load_lang;',
'',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''ITE-unsupported-type'', c_load_lang, q''[Currently unsupported type of Intermediate Throw Event encountered at %0 .]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''apex-session-params-not-set'', c_load_lang, q''[Asynchronous connection details for object %0 need to be set in process variables, diagram async connection details, or system config details.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''async-invalid_params'', c_load_lang, q''[Unable to create asyncronous connection for object %0.  Username not valid in specified Application]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''async-no-username'', c_load_lang, q''[Unable to create asyncronous connection for object %0.  Username needs to be specified in process variable, the process diagram, or system configuration.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''async-no-appid'', c_load_lang, q''[Unable to create asyncronous connection for object %0.  Application ID needs to be specified in process variable, the process diagram, or system configuration.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''async-no-pageid'', c_load_lang, q''[Unable to create asyncronous connection for object %0.  Page ID needs to be specified in process variable, the process diagram, or system configuration.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''boundary-event-child-lock-to'', c_load_lang, q''[Child Boundary Subflows or Timers of %0 currently locked by another user.  Retry your transaction later.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''boundary-event-no-catch-found'', c_load_lang, q''[No boundaryEvent of type %0 found to catch event.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''boundary-event-too-many'', c_load_lang, q''[More than one %0 boundaryEvent found on sub process.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''eng_handle_event_int'', c_load_lang, q''[Flow Engine Internal Error: Process %0 Subflow %1 Module %2 Current %4 Current Tag %3]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''engine-unsupported-object'', c_load_lang, q''[Model Error: Process BPMN model next step uses unsupported object %0]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''engine-util-prcs-not-found'', c_load_lang, q''[Application Error: Process ID %0 not found.]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''engine-util-sbfl-not-in-prcs'', c_load_lang, q''[Application Error: Subflow ID supplied ( %0 ) exists but is not child of Process ID Supplied ( %1 ).]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''engine-util-sbfl-not-found'', c_load_lang, q''[Subflow ID supplied ( %0 ) not found. Check for process events that changed process flow (timeouts, errors, escalations).]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
'    values ( ''gateway-invalid-route'', c_load_lang, q''[Error at gateway %0. Supplied variable %1 contains invalid route: %2]'' );',
'  insert into flow_messages( fmsg_message_key, fmsg_lang, fmsg_message_content )',
