prompt --application/deployment/checks
begin
wwv_flow_imp_shared.create_install_check(
 p_id=>wwv_flow_imp.id(30433478510451383)
,p_install_id=>wwv_flow_imp.id(30210531648852655)
,p_name=>'Privilege Check'
,p_sequence=>10
,p_check_type=>'FUNCTION_BODY'
,p_check_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_actual_privs  apex_t_varchar2;',
'  l_needed_privs  apex_t_varchar2;',
'  l_missing_privs apex_t_varchar2;',
'begin',
'  -- set up needed privileges',
'  l_needed_privs :=',
'    apex_t_varchar2',
'    (',
'      ''CREATE TABLE''',
'    , ''CREATE PROCEDURE''',
'    , ''CREATE SEQUENCE''',
'    , ''CREATE VIEW''',
'    , ''CREATE TYPE''',
'    , ''CREATE JOB''',
'    )',
'  ;',
'',
'  -- Collect actual privileges',
'  select privilege',
'    bulk collect into l_actual_privs',
'    from user_sys_privs',
'  ;',
'',
'  -- deduct actual from needed privileges',
'  l_missing_privs := l_needed_privs multiset except l_actual_privs;',
'',
'  return (l_missing_privs.count = 0);',
'end;'))
,p_check_condition2=>'PLSQL'
,p_failure_message=>'Missing Privileges cannot continue installation.'
);
end;
/
